/**
*基于IndexDB的前端数据库缓存技术
*@author xiangjia
*@date 2020-02-17
**/
//class laya.cache.IndexDBMgr
var IndexDBMgr=(function(){
	function IndexDBMgr(){
		this.indexedDB=null;
		this.IDBTransaction=null;
		this.IDBKeyRange=null;
		this.cacheDB=null;
		this.libIDB=null;
		this.startT=0;
		this._keysDic={};
		this._isKeyDicChanged=false;
		this.instanceName="";
		if(IndexDBMgr.useLib){
			this.libIDB=IDB;
			if(!this.libIDB)IndexDBMgr.useLib=false;
		}
	}

	__class(IndexDBMgr,'laya.cache.IndexDBMgr');
	var __proto=IndexDBMgr.prototype;
	__proto.setName=function(value){
		this.instanceName=value;
		return this;
	}

	__proto.init=function(callBack){
		if(IndexDBMgr.useLib){
			try {
				this.libIDB.init(callBack);
				IndexDBMgr.IS_READY=true;
				}catch (e){
				console.error("Your browser doesn't support a stable version of IndexedDB. Such and such feature will not be available.");
				callBack(false);
			}
			}else{
			this.init1(callBack);
		}
	}

	__proto.init1=function(callBack){
		var _$this=this;
		Watcher.ins.reset("IndexDB inited");
		if(IndexDBMgr.IS_READY){
			return;
		};
		var _this=this;
		this.startT=Browser.now();
		var window=Browser.window;
		try{
			this.indexedDB=window.indexedDB || window.mozIndexedDB || window.webkitIndexedDB || window.msIndexedDB;
			this.IDBTransaction=window.IDBTransaction || window.webkitIDBTransaction || window.msIDBTransaction;
			this.IDBKeyRange=window.IDBKeyRange || window.webkitIDBKeyRange || window.msIDBKeyRange;
			if(!this.indexedDB){
				console.error("Your browser doesn't support a stable version of IndexedDB. Such and such feature will not be available.");
				callBack(false);
				return;
			};
			var request=this.indexedDB.open(IndexDBMgr.DB_NAME,IndexDBMgr.DB_VERSION);
			request.onerror=function (event){
				console.error("Database error: "+event.currentTarget.error.message);
				callBack(false);
				debugger
			};
			request.onsuccess=function (event){
				IndexDBMgr.IS_READY=true;
				var db=event.target.result;
				db.onerror=function (event){
					console.error("Database error2: "+event.target.errorCode);
				};
				db.onclose=function (event){
					console.error("Database closed");
					IndexDBMgr.IS_READY=false;
					_this.init(function(resut){
						console.error("Database reback");
					});
				}
				console.info("Database opened");
				_$this.cacheDB=db;
				_$this.onDBOpened(callBack);
			};
			request.onupgradeneeded=function (event){
				var db=event.target.result;
				if(!db.objectStoreNames.contains("USER_DATA")){
					var objectStore=db.createObjectStore("USER_DATA",{keyPath:"key" });
				}
			};
		}
		catch(error){
			console.error("Your browser doesn't support a stable version of IndexedDB.Maybe crossdomain");
			callBack(false);
		}
	}

	/**
	*数据库连接成功
	**/
	__proto.onDBOpened=function(initCallBack){
		this.readCache("DB_KEYS_DICTIONARY.OBJ",Handler.create(this,this.onIDBKeyDictionaryReady,[initCallBack]));
	}

	__proto.onIDBKeyDictionaryReady=function(initCallBack,url,succes,result){
		if(result){
			this._keysDic=result.data;
		}
		Watcher.ins.stop("IndexDB inited");
		Laya.timer.loop(2*60*1000,this,this.flushKeyDic2Disk);
		if(initCallBack){
			initCallBack(true);
		}
	}

	__proto.flushKeyDic2Disk=function(){
		if(this._isKeyDicChanged){
			this._isKeyDicChanged=false;
			this.writeCache("DB_KEYS_DICTIONARY.OBJ","json",this._keysDic);
		}
	}

	/**
	*更新KEY的最新访问时间。
	**/
	__proto.updateKeyDic=function(key){
		this._keysDic[key]=Browser.now();
		this._isKeyDicChanged=true;
	}

	__proto.writeCache=function(key,type,data){
		if(IndexDBMgr.useLib){
			var saveObj={key:key,data:data,type:type};
			this.libIDB.write(key,type,data);
			return saveObj;
			}else{
			return this.writeCache1(key,type,data);
		}
	}

	__proto.writeCache1=function(key,type,data){
		if(key!="DB_KEYS_DICTIONARY.OBJ"){
			this.updateKeyDic(key);
		};
		var saveObj={key:key,data:data,type:type};
		if(this.cacheDB!=null){
			try{
				var request=this.cacheDB.transaction("USER_DATA","readwrite").objectStore("USER_DATA").put(saveObj);
				request.onerror=function (e){
					console.info("write IDB Failed:"+saveObj.key);
					debugger;
				}
				request.onsuccess=function (e){}
			}
			catch(e){
				console.error(e.message);
			}
		}
		return saveObj;
	}

	__proto.readCache=function(url,resulCallBack){
		if(IndexDBMgr.useLib){
			this.libIDB.read(url,function(url,suc,data){
				resulCallBack.runWith([url,suc,data]);
			});
			}else{
			this.readCache1(url,resulCallBack);
		}
	}

	__proto.readCache1=function(url,resulCallBack){
		var _$this=this;
		if (null !=this.cacheDB && (this._keysDic[url] || url=="DB_KEYS_DICTIONARY.OBJ")){
			try {
				var request=this.cacheDB.transaction("USER_DATA").objectStore("USER_DATA").get(url);
				request.onerror=function (t){
					resulCallBack.runWith([url,false,null]);
				},
				request.onsuccess=function (t){
					if(url!="DB_KEYS_DICTIONARY.OBJ"){
						_$this.updateKeyDic(url);
					}
					request.result ? resulCallBack.runWith([url,true,request.result]):resulCallBack.runWith([url,false,null]);
				}
				}catch (t){
				resulCallBack.runWith([url,false,null]);
			}
		}
		else{
			resulCallBack.runWith([url,false,null]);
		}
	}

	__proto.clearIndexDB=function(call){
		if(IndexDBMgr.useLib){
			this.libIDB.clear(function(suc){
				call.runWith(suc);
			});
			}else {
			this.clearIndexDB1(call);
		}
	}

	__proto.clearIndexDB1=function(call){
		var _$this=this;
		if(this.indexedDB){
			try{
				if(this.cacheDB){
					this.cacheDB.close();
				};
				var delReq=this.indexedDB.deleteDatabase(IndexDBMgr.DB_NAME);
				delReq.onsuccess=function (){
					console.log("修复成功");
					IndexDBMgr.IS_READY=false;
					_$this.init(null);
					call.runWith(true);
				};
				delReq.onerror=function (){
					console.log("修复失败");
					call.runWith(false);
				};
			}
			catch(error){
				console.log("修复失败");
				call.runWith(false);
			}
		}
		else{
			console.log("清理成功");
			call.runWith(true);
		}
	}

	/*if(cacheDB){
	var transaction:*=cacheDB.transaction([DB_OBJECT_STORE_NAME],"readwrite");
	transaction.oncomplete=function(event){
		trace("Transaction completed.")
	}

	transaction.onerror=function(event){
		trace('Transaction not opened due to error: '+transaction.error);
	}

	var objectStore:*=transaction.objectStore(DB_OBJECT_STORE_NAME);
	var clearRequest:*=objectStore.clear();
	clearRequest.onsuccess=function(event){
		_keysDic={}
		trace('Indexdb仓库'+DB_OBJECT_STORE_NAME+'清空成功');
	};

}*/


__proto.printStats=function(){
	if (null !=this.cacheDB){
		var totalSize=0;
		var count=0;
		var objectStore=this.cacheDB.transaction("USER_DATA").objectStore("USER_DATA");
		objectStore.openCursor().onsuccess=function (event){
			var cursor=event.target.result;
			if (cursor){
				count++;
				totalSize+=cursor.value.data.size;
				var key=cursor.value.key;
				if(window.atob){
					key=window.atob(key);
				}
				console.log(key+"    size:"+cursor.value.data.size);
				cursor.continue();
			}
			else {
				var sum="IDB 统计，文件数："+count+"文件大小："+(totalSize/1024/1024).toFixed(2)+"MB";
				console.log(sum)
				alert(sum);
			}
		};
	}

}


IndexDBMgr.instance=function(){
	return IndexDBMgr._ins=IndexDBMgr._ins|| new IndexDBMgr().setName("indexDB1");
}


IndexDBMgr.DB_NAME="BASE_GAME";
IndexDBMgr.DB_VERSION=3;
IndexDBMgr.DB_OBJECT_STORE_NAME="USER_DATA";
IndexDBMgr.DB_KEYS_DICTIONARY="DB_KEYS_DICTIONARY.OBJ";
IndexDBMgr.IS_READY=false;
IndexDBMgr.useLib=true;
IndexDBMgr._ins=null;
return IndexDBMgr;
})()


