/**
*数据容器
*1、可以挂载自定义数据
*2、可以灵活分组查询
*@author xiangjia
*@date 2020-02-29
*/
//class laya.xq.cfg.DataContainer
var DataContainer=(function(){
	function DataContainer(){
		this._array=null;
		this._eleDic=null;
		this._groupDic=null;
		this.data=null;
		/**组Group*/
		this._keyGroup=null;
		this._array=[];
		this._eleDic={};
		this._groupDic={};
		this._keyGroup={};
	}

	__class(DataContainer,'laya.xq.cfg.DataContainer');
	var __proto=DataContainer.prototype;
	/**
	*@param id:主键
	*@param ele:数据对象
	**/
	__proto.addElement=function(id,ele){
		this._eleDic[id]=ele;
		this._array.push(ele);
	}

	/**
	*根据主键获得对象
	**/
	__proto.getElement=function(id){
		return this._eleDic[id];
	}

	/**
	*@param id:主键
	*@param properKey:子属性键
	*@param value :子属性值
	**/
	__proto.setValue=function(id,properKey,value){
		var ele=this._eleDic[id];
		if(ele){
			ele.setValue(properKey,value);
		}
		else{
			console.error("DataElement id 不存在："+id);
		}
	}

	/**
	*@param id:主键
	*@param properKey:子属性键
	**/
	__proto.getValue=function(id,properKey){
		var ele=this._eleDic[id];
		return ele.getValue(properKey);
	}

	/**
	*根据字段名称和值，查询数据，查询结果以新的DataContainter视图形式返回
	*@param fieldName:查询条件字段名称
	*@param value:查询条件对应字段的值
	*@param primaryKey:指定新DataContainer的主键名称(必须是配置表中的字段)
	**/
	__proto.where=function(fieldName,value,primaryKey){
		if(value==undefined || value=="undefined")
			debugger;
		var queryGroupCache=fieldName+"_"+primaryKey+"_"+value;
		var dc=this._groupDic[queryGroupCache];
		var gKey=fieldName+"_"+primaryKey;
		if(dc==null){
			if(!this._groupDic[gKey]){
				this._groupDic[gKey]=true;
				var len=this._array.length;
				for (var i=0;i < len;i++){
					var ele=this._array[i];
					var cfg=ele.getCfgData();
					var v=cfg[fieldName];
					var group=fieldName+"_"+primaryKey+"_"+v;
					var subDC=this._groupDic[group];
					if(subDC==null){
						subDC=new DataContainer();
						this._groupDic[group]=subDC;
					}
					subDC.addElement(cfg[primaryKey],ele);
				}
			}
			dc=this._groupDic[queryGroupCache];
			if(dc==null){
				dc=new DataContainer();
				this._groupDic[queryGroupCache]=dc;
			}
		}
		return dc;
	}

	/**添加自定义Data*/
	__proto.setCustomData=function(key,value){
		if(!this.data){
			this.data={};
		}
		this.data[key]=value;
	}

	/**获取Data里的数据*/
	__proto.getCustomValue=function(key){
		return this.data[key]
	}

	/**清除容器中 数据ele中键为Key的数据*/
	__proto.clearEleValue=function(key){
		var len=this._array.length;
		for(var i=0;i<len;i++){
			var ele=this._array[i];
			if(ele.getValue(key)){
				ele.setValue(key,null);
			}
		}
	}

	__getset(0,__proto,'array',function(){
		return this._array;
	});

	return DataContainer;
})()


