//class laya.xq.core.particle.Particle extends laya.display.Sprite
var Particle=(function(_super){
	function Particle(){
		this.tex=null;
		this.idx=0;
		this.len=0;
		this.texArr=null;
		this.timeArr=null;
		this.changeTime=NaN;
		this.lifeTime=NaN;
		this._speed=NaN;
		this.color=0;
		this.maxScale=NaN;
		this.xDir=NaN;
		this.yDir=NaN;
		this.sp=null;
		this.isRotate=false;
		this.xPer=NaN;
		this.yPer=NaN;
		this.aPer=NaN;
		this.rPer=NaN;
		this.sPer=NaN;
		this.ms=NaN;
		this.isDead=false;
		Particle.__super.call(this);
		this.sp=new Sprite();
		this.addChild(this.sp);
	}

	__class(Particle,'laya.xq.core.particle.Particle',_super);
	var __proto=Particle.prototype;
	__proto.init=function(text){
		this.texArr=text;
		this.len=this.texArr.length;
		this.idx=0;
		this.tex=this.texArr[this.idx];
		this.changeTime=0;
		this.xPer=this.xDir;
		this.yPer=this.yDir;
		this.sp.graphics.clear();
		this.sp.graphics.drawTexture(this.tex,0,0,this.tex.width,this.tex.height);
		this.sp.x=-this.tex.width>>1;
		this.sp.y=-this.tex.height>>1;
	}

	__proto.renders=function(time){
		if(this.lifeTime<=0)
			this.isDead=true;
		if(this.isDead)
			return;
		this.x+=this.ms*time*this.xPer;
		this.y+=this.ms*time*this.yPer;
		this.alpha+=this.aPer*time;
		if(this.isRotate)
			this.rotation+=this.rPer;
		if(this.scaleX < this.maxScale && this.scaleX >0){
			this.scaleX+=this.sPer;
			this.scaleY=this.scaleX;
		}
		this.changeTime+=time;
		if(this.timeArr && this.changeTime >=this.timeArr[this.idx]){
			this.idx++;
			this.idx %=this.len;
			this.changeTime-=this.timeArr[this.idx];
			this.tex=this.texArr[this.idx];
			this.sp.graphics.clear();
			this.sp.graphics.drawTexture(this.tex,0,0,this.tex.width,this.tex.height);
		}
		this.lifeTime-=time;
	}

	__getset(0,__proto,'speed',null,function(value){
		this._speed=value;
		this.ms=value*0.001;
	});

	return Particle;
})(Sprite)


