var WXSDK=(function(){
	function WXSDK(){}
	__class(WXSDK,'com.xq.configs.configs.WXSDK');
	WXSDK.init=function(){
		if(WXSDK.isInWX){
			window.wx.onHide(function(){
				EventCenter.instance.event("WX_ON_HIDE");
			});
			window.wx.onShow(function(res){
				EventCenter.instance.event("WX_ON_SHOW",res);
			});
			window.wx.onMemoryWarning(function(res){
				ResourceManager.systemResourceManager.autoRelease=true;
				ResourceManager.systemResourceManager.autoReleaseMaxSize=1024*1024*400;
				AmtLoaderMgr.instance.maxAtmMemorySize=1024*1024*250;
				AmtLoaderMgr.instance.maxMemorySize=1024*1024*350;
				AmtLoaderMgr.isLowMemery=true;
				window.wx.showToast({
					title:'内存过低',
					duration:2000
				})
				window.wx.triggerGC();
			});
		}
	}

	WXSDK.onEnterGame=function(){
		if(WXSDK.isInWX){
			EventCenter.instance.on("WX_ON_SHOW",WXSDK,WXSDK.onWxShow);
		}
	}

	WXSDK.onWxShow=function(){}
	WXSDK.requestAndGetUserInfo=function(o){
		var obj={};
		obj.success=function (res){
			if (!res.authSetting["scope.userInfo"]){
				var o1={};
				console.log("请求用户信息权限")
				o1.scope="scope.userInfo";
				o1.success=function (){
					console.log("请求用户信息")
					wx.getUserInfo(o);
				}
				wx.authorize(o1);
				}else{
				console.log("请求用户信息")
				wx.getUserInfo(o);
			}
		}
		wx.getSetting(obj);
	}

	WXSDK.login=function(complete){
		com.xq.configs.configs.WXSDK.complete=complete;
		var obj={};
		obj.success=function (res){
			console.log("微信登录Success：code："+res.code);
			WXSDK.code2accessToken(res.code);
		}
		obj.fail=function (res){
			console.log("微信登录Fail：code："+res.code);
		}
		obj.complete=function (res){
			console.log("微信登录complete：code："+res.code);
		}
		wx.showLoading({title:'正在登录游戏',mask:true});
		wx.login(obj);
		if(Configs.isStartPublishLogin)
			sdk_login()
	}

	WXSDK.code2accessToken=function(code){
		WXSDK.lgUrl="https://center.zhijiangames.com/center/wechat/code2Session"+"?wxcode="+code+"&pid="+Configs.platformId;
		console.log("发送登录请求："+WXSDK.lgUrl);
		Laya.loader.load(WXSDK.lgUrl,Handler.create(WXSDK,WXSDK.onAccessToken),null,"json",1,false);
	}

	WXSDK.onAccessToken=function(data){
		wx.hideLoading({});
		if(data.openid){
			wx.showToast({title:'登录成功！'});
			WXSDK.checkUserFrom(data.openid);
			WXSDK.openid=data.openid;
			WXSDK.session_key=data.session_key;
			var obj={
				withCredentials:true,
				lang:"zh_CN"
			}
			WXSDK.requestAndGetUserInfo({});
			WXSDK.sendUserInfo()
		}
		else{
			if(WXSDK.lgCount <=0){
				console.log("拉取服务器列表数据失败");
			}
		}
		if(com.xq.configs.configs.WXSDK.complete){
			if(data.openid || WXSDK.lgCount <=0){
				com.xq.configs.configs.WXSDK.complete.runWith(data);
				com.xq.configs.configs.WXSDK.complete=null;
			}
			else{
				WXSDK.lgCount--;
				WXSDK.code2accessToken(WXSDK.lgUrl)
			}
		}
	}

	WXSDK.checkUserFrom=function(openid){
		var lauchInfo=wx.getLaunchOptionsSync();
		if(lauchInfo){
			var query=lauchInfo.query;
			if(query){
				if(query.channelCode){
					WXSDK.channelCode=query.channelCode;
				}
				else if(query.scene){
					var scene=query.scene.replace(/%3D/g,"=");
					var name="channelCode";
					var reg=new RegExp("(^|&)"+name+"=([^&]*)(&|$)");
					var r=scene.substr(0).match(reg);
					if (r !=null){
						WXSDK.channelCode=unescape(r[2]);
					}
				}
				if(WXSDK.channelCode){
					var xml=new HttpRequest();
					var data={};
					data.channelCode=WXSDK.channelCode;
					data.gameOpenId=openid;
					data.appid=GameGlobal.appid;
				}
			}
		}
	}

	WXSDK.requestMidasPay=function(msg){
		if(Browser.now()-WXSDK.lastRequest >=3000){
			WXSDK.lastRequest=Browser.now();
			var orderId=msg.orderId;
			console.error("拉起米大师支付：=====",orderId);
			var sign=md5(orderId+wxPK);
			var object={};
			object.mode="game";
			object.env=msg.sanbox;
			object.offerId=GameGlobal.offerId;
			object.currencyType="CNY";
			object.platform="android";
			object.buyQuantity=msg.rmbFen/10;
			object.zoneId="1";
			object.success=function (res){
				console.log("Midas支付成功！！",res);
				wx.showToast({title:'充值成功！'});
				Mgr.vip.logWXPaySuccess(orderId,sign);
				debugger;
			}
			object.fail=function (res){
				console.log("Midas支付失败！！",res);
				debugger;
			};
			object.complete=function (res){
				console.log("Midas支付完成！！",res);
				debugger;
			};
			wx.requestMidasPayment(object);
		}
	}

	WXSDK.onGameLoaded=function(){
		if(typeof(wxMiniGameEnterd)!='undefined'){
			wxMiniGameEnterd=true;
		}
	}

	WXSDK.share=function(){
		var url="https://www.baidu.com/logo.jpg";
		var obj={
			title:"护法归来",
			imageUrl:url
		}
		wx.shareAppMessage(obj);
		Mgr.platPro.sendShareOK();
	}

	WXSDK.postMessage=function(info){
		if(!WXSDK.opendataContext)
			WXSDK.opendataContext=wx.getOpenDataContext();
		if(WXSDK.opendataContext)
			WXSDK.opendataContext.postMessage(info);
	}

	WXSDK.setWXRank=function(){
		var val={
			wxgame:{score:NetMgr.ins().roleVO.fightValue,update_time:Browser.now()/1000}
		};
		var obj={
			KVDataList:[{
				key:'rkScore',
				value:JSON.stringify(val)
			}],
			success:function (res){
				console.log("wx排行数据写入成功");
			},
			fail:function (res){
				console.log("wx排行数据写入失败"+res);
			},
			complete:function (res){}
		}
		wx.setUserCloudStorage(obj)
	}

	WXSDK.setPhonSys=function(){
		var obj={
			success:function (obj){
				if(obj.system.indexOf("iOS")!=-1)
					Browser.onIOS=true;
				else
				Browser.onAndroid=true;
			},
			fail:function (){},
			complete:function (){}
		}
		wx.getSystemInfo(obj);
	}

	WXSDK.sendUserInfo=function(){
		var callObj={
			success:function (obj){
				var data={};
				data.appid=GameGlobal.appid,
				data.channelCode=WXSDK.channelCode? WXSDK.channelCode :"",
				data.openId=WXSDK.openid;
				data.brand=obj.brand;
				data.model=obj.model;
				data.pixelRatio=obj.pixelRatio;
				data.screenWidth=obj.screenWidth;
				data.screenHeight=obj.screenHeight;
				data.windowWidth=obj.windowWidth;
				data.windowHeight=obj.windowHeight;
				data.statusBarHeight=20;
				data.language=obj.language;
				data.version=obj.version;
				data.system=obj.system;
				data.platform=obj.platform;
				data.fontSizeSetting=obj.fontSizeSetting;
				data.sdkVersion=obj.sdkVersion;
			}
		}
		wx.getSystemInfo(callObj);
	}

	WXSDK.sendOrderForm=function(msg){
		var itemid=msg.itemId;
		var data={}
		data.appid=GameGlobal.appid,
		data.openId=WXSDK.openid,
		data.channelCode=WXSDK.channelCode? WXSDK.channelCode :"",
		data.orderNum=msg.orderId,
		data.wxOrderNum="",
		data.goods=JSON.stringify({itemid:1})
		data.amount=msg.rmbFen/100
	}

	WXSDK.isInWX=false;
	WXSDK.complete=null;
	WXSDK.CODE2ACCESS_TOKEN="https://center.zhijiangames.com/center/wechat/code2Session";
	WXSDK.wxchannel=null;
	WXSDK.openid="";
	WXSDK.session_key="";
	WXSDK.lgUrl=null;
	WXSDK.lgCount=3;
	WXSDK.lastRequest=0;
	WXSDK.opendataContext=null;
	WXSDK.channelCode=null;
	return WXSDK;
})()


