//class com.xq.core.font.FontManager
var FontManager=(function(){
	function FontManager(){
		this.dic={};
	}

	__class(FontManager,'com.xq.core.font.FontManager');
	var __proto=FontManager.prototype;
	__proto.addFont1=function(url,fontName,comp){
		if(this.dic[url]){
			if(comp){
				comp.runWith(fontName);
			}
			return;
		}
		this.dic[url]=true;
		Laya.loader.load(url,Handler.create(this,this.onLoadFont,[url,fontName,comp]),null,"arraybuffer");
	}

	__proto.onLoadFont=function(url,fontName,comp,data){
		console.log("加载完毕");
		var blob=new Blob([data]);
		var blobPath=Browser.window.URL.createObjectURL(blob);
		var str="@font-face{font-family: "+fontName+";src: url('"+blobPath+"'); }";
		this.loadCssCode(str);
		if(comp){
			comp.runWith(fontName);
		}
	}

	__proto.loadCssCode=function(code){
		try{
			var document=Browser.window.document;
			var style=document.createElement('style');
			style.type='text/css';
			style.rel='stylesheet';
			style.appendChild(document.createTextNode(code));
			var head=document.getElementsByTagName('head')[0];
			head.appendChild(style);
			}catch(e){
			console.log("字体加载失败",code);
		}
	}

	FontManager.addFont=function(url,fontName,comp){
		comp.run();
	}

	__static(FontManager,
	['ins',function(){return this.ins=new FontManager();}
	]);
	return FontManager;
})()


/**
*单图片管理
*@author zhanglimin
*@date 2020-5-19
**/
//class com.xq.core.manager.image.SingleImageMgr
var SingleImageMgr=(function(){
	function SingleImageMgr(){
		/**最大内存*/
		this.memSize=50 *1024 *1024*4;
		/**图片监狱*/
		this.imgCache=null;
		this.imgCache=new SurvivalCache(this.memSize,SingleImageMgr.disposeTime,new Handler(this,this.clearItem,null,false));
	}

	__class(SingleImageMgr,'com.xq.core.manager.image.SingleImageMgr');
	var __proto=SingleImageMgr.prototype;
	/**添加*/
	__proto.add=function(img){
		var _memSize=img.width *img.height *4;
		if(_memSize > 0){
			this.imgCache.add(img.skin,img.skin,_memSize);
		}
	}

	/**检测缓存*/
	__proto.checkCache=function(_skin){
		this.imgCache.getCache(_skin);
	}

	/**清理所有缓存*/
	__proto.clearAll=function(){
		this.imgCache.clear();
	}

	/**过期清理*/
	__proto.clearItem=function(_skin){
		Laya.loader.clearRes(_skin);
	}

	SingleImageMgr.ins=function(){
		return SingleImageMgr._instace=SingleImageMgr._instace||new SingleImageMgr();
	}

	SingleImageMgr.disposeTime=10 *60 *1000;
	SingleImageMgr._instace=null;
	return SingleImageMgr;
})()


/**
*
*2019-10-13
*@auther gfr
*/
//class com.xq.core.net.BaseMsgAction
var BaseMsgAction=(function(){
	function BaseMsgAction(){
		this._net=null;
		this._msgList=null;
		this.tempArr=null;
		this._methodDic=null;
		this._net=NetMgr.ins();
		this._methodDic={};
		this.tempArr=[];
		this.registerMsg();
		var handler=new Handler(this,this.onMesgage,null,false)
		var j;
		for(var $each_j in this._msgList){
			j=this._msgList[$each_j];
			this._net.registerHandler(j,handler);
		}
		for(var key in this._methodDic){
			this._net.registerHandler(key,handler);
		}
	}

	__class(BaseMsgAction,'com.xq.core.net.BaseMsgAction');
	var __proto=BaseMsgAction.prototype;
	/**
	*子类重写定义一个协议数组
	*
	**/
	__proto.registerMsg=function(){
		this._msgList=[];
	}

	/**
	*子类重写
	*data.msgId
	*data.data
	**/
	__proto.onMesgage=function(data){
		var func=this._methodDic[data.msgId];
		if(func){
			this.tempArr.length=1;
			this.tempArr[0]=data.data;
			func.apply(this,this.tempArr);
		}
	}

	return BaseMsgAction;
})()


/**
*@author:huanghong
*@date:2021-11-19
*@desc:MsgFilter 协议筛选 （移除短时间内重复的net请求）
*/
//class com.xq.core.net.MsgFilter
var MsgFilter=(function(){
	function MsgFilter(){
		/**协议记录字典*/
		this._msgDic=null;
		/**冷却时间*/
		this._cd=1000;
		/**父类中的字段 用于判断是否是子类自己定义的字段*/
		this._fatherKeyName=null;
		/**跳过检测msgId(例如心跳包一直在调用的)*/
		this._leapfrogMsg=null;
		this.msgIds={};
		this._msgDic={};
		this._fatherKeyName=["outerBuf_","inBuf_","startPos"];
	}

	__class(MsgFilter,'com.xq.core.net.MsgFilter');
	var __proto=MsgFilter.prototype;
	/**协议cd检测 _cd时间内发送的相同的协议将被过滤掉 以减少不必要的前后端交互*/
	__proto.checkMsg=function(msgId,data){
		var key=this.transformKey(msgId,data);
		var lastSendTime=this._msgDic[key];
		var nowTime=Browser.now()
		if(!lastSendTime||lastSendTime+this._cd<=nowTime){
			this._msgDic[key]=nowTime;
			return true;
		}
		return false;
	}

	/**msg数值转换为key值（msgId _数据_数据...）*/
	__proto.transformKey=function(msgId,data){
		if(!data)return msgId+"";
		var key="";
		for(var i in data){
			var prop=data[i];
			if(!prop|| (typeof prop=='function')||this._fatherKeyName.indexOf(i)!=-1)continue ;
			key+="_"+prop;
		}
		return msgId+key;
	}

	__getset(1,MsgFilter,'ins',function(){
		return MsgFilter._ins=MsgFilter._ins||new MsgFilter();
	});

	MsgFilter._ins=null;
	return MsgFilter;
})()


