//class com.xq.core.tween.ShakeTween2
var ShakeTween2=(function(){
	function ShakeTween2(){
		this._target=null;
		this._delay=NaN;
		/**角度变化值*/
		this._rV=NaN;
		/**变化角度*/
		this._changeValue=NaN;
		this._startRotation=NaN;
		this._target1=NaN;
		this._target2=NaN;
	}

	__class(ShakeTween2,'com.xq.core.tween.ShakeTween2');
	var __proto=ShakeTween2.prototype;
	/**启动*/
	__proto.start=function(){
		if(!this._target)return;
		Laya.timer.loop(this._delay,this,this.shake,null);
	}

	__proto.shake=function(){
		if((this._rV<0&&this._target.rotation<=this._target1)||(this._rV>0&&this._target.rotation>=this._target2)){
			this._rV=-this._rV;
		}
		this._target.rotation+=this._rV;
	}

	__proto.stop=function(){
		Laya.timer.clear(this,this.shake);
		com.xq.core.tween.ShakeTween2.recover(this);
	}

	ShakeTween2.getItem=function(){
		return Pool.getItemByClass("ShakeTween2",ShakeTween2);
	}

	ShakeTween2.recover=function(item){
		Pool.recover("ShakeTween2",item);
	}

	ShakeTween2.start=function(target,delay,rV,changeValue){
		var st=com.xq.core.tween.ShakeTween2.getItem();
		st._target=target;
		st._startRotation=target.rotation;
		st._delay=delay;
		st._rV=rV;
		st._changeValue=changeValue;
		st._target1=st._startRotation-changeValue;
		st._target2=st._startRotation+changeValue;
		st.start();
		ShakeTween2.tweenDic.set(target,st);
		return st;
	}

	ShakeTween2.dispose=function(target){
		var tw=ShakeTween2.tweenDic.get(target);
		if(tw){
			target.rotation=tw._startRotation;
			ShakeTween2.tweenDic.remove(tw);
			tw.stop();
		}
	}

	__static(ShakeTween2,
	['tweenDic',function(){return this.tweenDic=new Dictionary();}
	]);
	return ShakeTween2;
})()


