	__proto.debugMem=function(){
		Mgr.sinImgMgr.clearAll();
		SImageManager.ins.checkToGC();
		var urlObj=CacheLoader.instance().urlObj;
		if(Browser.onMiniGame){
			if(Browser.onWeiXin){
				var f=MiniFileMgr$4.filesListObj;
				var path=MiniFileMgr$4.fileNativeDir;
				urlObj={};
				for (var key in f){
					var o=f[key];
					urlObj[path+"/"+o.md5]=o.readyUrl;
				}
			}
		};
		var resmgr=ResourceManager.systemResourceManager;
		var len=resmgr.getResourcesLength();
		var release="";
		var unRelease="";
		var releaseMem=0;
		var unReleaseMem=0;
		var releaseCount=0;
		var unRelaseCount=0;
		var res;
		var tempArr=[];
		for (var j=0;j < len;j++){
			res=resmgr.getResourceByIndex(j);
			if(res.memorySize > 0){
				tempArr.push(res);
			}
		}
		tempArr.sort(this.compare);
		for (var i=0;i < tempArr.length;i++){
			res=tempArr[i];
			if(res.released){
				releaseCount++;
				releaseMem+=res.memorySize;
				if(urlObj[res.url]){
					var tempUrl=urlObj[res.url];
				}
				else{
					tempUrl=res.url;
				}
				release+=tempUrl+"  "+(res.memorySize/1024)+"kb $R$";
			}
			else{
				if(res.memorySize > 0){
					unRelaseCount++;
					unReleaseMem+=res.memorySize;
					if(urlObj[res.url]){
						tempUrl=urlObj[res.url];
					}
					else{
						tempUrl=res.url;
					}
					unRelease+=tempUrl+"  "+(res.memorySize/1024)+"kb $R$";
				}
			}
		};
		var result="";
		result+="未释放图片资源大小："+(unReleaseMem/1024/1024).toFixed(2)+"MB"+" 数量 x"+unRelaseCount+" $R$";
		result+="准备释放图片资源大小："+(releaseMem/1024/1024).toFixed(2)+"MB"+" 数量 x"+releaseCount+" $R$";
		result+="===未释放=============> $R$";
		result+=unRelease;
		result+="===准备释放=============>$R$";
		result+=release;
		console.log(result);
		BaseSDK.ins.copyClip(result);
		if(Browser.onMiniGame){
			try {laya.xq.cfg.reportOneBug("资源统计",new Error(result));}catch (e){}
		}
	}

	__proto.compare=function(a,b){
		return b.memorySize-a.memorySize;
	}

