	/**
	*
	*@param e
	*
	*/
	__proto.onStageMouseDown=function(e){
		var x=Laya.stage.mouseX;
		var y=Laya.stage.mouseY;
		this.helperPoint.setTo(x,y);
		this.helperPointStage.setTo(x,y);
		this.hitPoint=this.helperPoint;
		if(!((e.target instanceof laya.display.Stage ))){
			this.mouseUp();
			if((e.target instanceof laya.ui.Button )){
				var ani=new UIAni();
				ani.loopTimes=1;
				ani.setRes(PathDefine.EFFECT_UI+"click"+".amt");
				ani.x=this.helperPoint.x;
				ani.y=this.helperPoint.y;
				ani.zOrder=99999;
				Laya.stage.addChild(ani);
			}
			return;
		};
		var scene=Game.getInstance().sceneContainer;
		scene.upMapLayer.globalToLocal(this.helperPoint,false);
		if(isNaN(this.helperPoint.x)||isNaN(this.helperPoint.y))
			return;
		var player=Game.getInstance().player;
		if(!player)
			return;
		this.targetPoint.setTo(player.x,player.y);
		var hitObj=scene.hitTestObj(this.helperPoint.x,this.helperPoint.y);
		if(hitObj){
			if((hitObj instanceof com.xq.rpg.unit.MainPlayer )){
			}
			else if((hitObj instanceof com.xq.rpg.unit.Unit )){
				if((hitObj).onMouseClick())
					return;
			}
		}
		else{
			if(this.isOpenControl){
				Game.getInstance().controlBox.doMove(e);
			}
			return
		}
		if(player.isNotClick){
			return;
		}
	}

