	__proto.printWholeStage=function(){
		function traceObj (node,retult){
			if(!node)
				return;
			var _clild=node._childs;
			retult.children=[];
			retult.name=ClassTool.getClassName(node);
			retult.values="x:"+node.x+",y:"+node.y+",width:"+node.width+",numChildren:"+node.numChildren;
			if(node.hasOwnProperty("curResUrl")){
				retult.values+=",curResUrl"+node["curResUrl"];
			}
			for (var i=0;i < _clild.length;i++){
				var childReult=new Object();
				retult.children.push(childReult);
				traceObj(_clild[i] ,childReult);
			}
		};
		var result=new Object();
		traceObj(this.stage ,result);
		var str=JSON.stringify(result);
		BaseSDK.ins.copyClip(str);
	}

