//class com.xq.map.MapAssetsLoader
var MapAssetsLoader=(function(){
	function MapAssetsLoader(onResLoaded){
		this.onResLoaded=null;
		/**平滑帧处理：因为当显示对象调用drawTexture的时候，会触发textImage2D这个接口，比较耗时，所以加个平滑帧处理，避免同事上传纹理，造成卡顿*/
		this.excuteLoadedCount=0;
		this.isStartFrame=false;
		this.itemList=new Dictionary();
		this.onResLoaded=onResLoaded;
	}

	__class(MapAssetsLoader,'com.xq.map.MapAssetsLoader');
	var __proto=MapAssetsLoader.prototype;
	/**
	*添加地图索引
	**/
	__proto.add=function(chunkItem){
		if(chunkItem.url==""){
			return;
		}
		if(!this.itemList.get(chunkItem.ID)){
			this.itemList.set(chunkItem.ID,chunkItem);
			Laya.loader.load(chunkItem.url,Handler.create(this,this.onChunkLoaded,[chunkItem.ID]),null,"image",2);
		}
	}

	__proto.onChunkLoaded=function(chunkID,tex){
		var chunkItem=this.itemList.get(chunkID);
		if(chunkItem){
			if(!((tex instanceof laya.resource.Texture ))){
				return;
			}
			if(!tex.bitmap){
				return;
			}
			(tex.bitmap).lock=true;
			(tex.bitmap).enableMerageInAtlas=false;
			chunkItem.sprite.texture=tex;
			chunkItem.size=tex.width *tex.height *4;
			if(this.onResLoaded)
				this.onResLoaded.runWith(chunkItem);
		}
	}

	__proto.cancelLoad=function(mapCKItem,forceDispose){
		(forceDispose===void 0)&& (forceDispose=false);
		if(mapCKItem.url==""){
			return;
		}
		Laya.loader.cancelLoadByUrl(mapCKItem.url);
		this.remove(mapCKItem,forceDispose);
	}

	/**移除正在加载队列中的区块*/
	__proto.remove=function(mapChunkItem,forceDispose){
		(forceDispose===void 0)&& (forceDispose=false);
		if(mapChunkItem.url==""){
			return;
		}
		this.itemList.remove(mapChunkItem.ID);
		Laya.loader.clearRes(mapChunkItem.url,forceDispose);
		mapChunkItem.sprite.texture=null;
	}

	/**移除已经加载完成的区块*/
	__proto.remove2=function(mapChunkItem){
		this.itemList.remove(mapChunkItem.ID);
	}

	__proto.removeAll=function(){
		var values=this.itemList.values.concat();
		var mapchunkItem;
		for(var $each_mapchunkItem in values){
			mapchunkItem=values[$each_mapchunkItem];
			this.cancelLoad(mapchunkItem ,true);
		}
		this.itemList.clear();
	}

	__proto.dispose=function(){
		this.removeAll();
		if(this.onResLoaded){
			this.onResLoaded.clear();
			this.onResLoaded=null;
		}
	}

	return MapAssetsLoader;
})()


