	__proto.createHancockArr=function(msg){
		var rankRoleInfo={};
		var len=msg.rankRoleInfoList.length;
		this.todayMaxValue=0;
		for (var i2=0;i2 < len;i2++){
			var rankInfo=msg.rankRoleInfoList[i2];
			if(rankInfo){
				rankRoleInfo[msg.rankRoleInfoList[i2].rank]=msg.rankRoleInfoList[i2];
				if(this.todayMaxValue<rankInfo.score){
					this.todayMaxValue=rankInfo.score;
				}
			}
		}
		if(msg.rankRoleInfoList.length > 0){
			this.firstSer=msg.rankRoleInfoList[0];
		};
		var cfgArr=this.feiShengBangCfgTab.getItemsByField("ranktype",msg.rankType+"");
		var len1=cfgArr.length;
		var lastCfg=cfgArr[cfgArr.length-1];
		var lastRank=parseInt(lastCfg.rank.split("|")[1]);
		var limitObj=cfgArr[cfgArr.length-1];
		this.minRank=parseInt(limitObj.limit);
		this.rankNum=lastRank;
		this.skipId=parseInt(cfgArr[0].mediator);
		this.nextExplain=cfgArr[0].explain;
		this.res=cfgArr[0].res;
		this.feiShengBangBtnSkin=cfgArr[0].icon;
		this.resScale=parseFloat(cfgArr[0].size);
		this.resY=cfgArr[0].height;
		this.curItemName=Mgr.item.getItemCfgMsgById(cfgArr[0].consume).name;
		this.oneScore=parseInt(cfgArr[0].num);
		this.feiShengBangArr=[];
		for (var i=0;i < lastRank;i++){
			var feiShengBangVo=new FeiShengBangVo();
			var feiShengBangItem=rankRoleInfo[i+1];
			if(feiShengBangItem){
				feiShengBangVo.rank=feiShengBangItem.rank;
				feiShengBangVo.roleName=feiShengBangItem.roleName;
				feiShengBangVo.score=feiShengBangItem.score;
			}
			else{
				feiShengBangVo.roleName=null;
				feiShengBangVo.rank=i+1;
			};
			var rewardArr;
			for (var k=0;k < len1;k++){
				var hancockCfg=cfgArr[k];
				var min=parseInt(hancockCfg.rank.split("|")[0]);
				var max=parseInt(hancockCfg.rank.split("|")[1]);
				if(feiShengBangVo.rank >=min && feiShengBangVo.rank <=max){
					rewardArr=hancockCfg.reward.split(";");
					rewardArr.pop();
					if(!feiShengBangVo.score){
						feiShengBangVo.score=hancockCfg.limit;
					}
					feiShengBangVo.tipShow=hancockCfg.tipshow;
					feiShengBangVo.mainHint=hancockCfg.mainHint;
					feiShengBangVo.rewardArr=rewardArr;
					break ;
				}
			}
			this.feiShengBangArr.push(feiShengBangVo);
		};
		var rewardCfgArr=this.feiShengBangCfgTab.getItemsByField("ranktype",msg.rankType+"");
		var _rewardArr=rewardCfgArr.concat([]);
		this.firstCfgInfo=_rewardArr[0];
		this.rewardShowArr=_rewardArr;
		EventCenter.instance.event("feishengbang",[this.feiShengBangArr]);
		this.openHancockGuide();
	}

