	/**根据排名获取 名字 或者 上榜多少人*/
	__proto.getRankTip=function(r1,r2){
		if(!this.feiShengBangArr)return "";
		var arr=this.feiShengBangArr;
		var len=arr.length;
		var feiShengBangVo;
		if(r1==r2){
			for(var i=0;i<len;i++){
				feiShengBangVo=arr[i];
				if(feiShengBangVo.rank==r1){
					return feiShengBangVo.roleName?feiShengBangVo.roleName:"虚位以待";
				}
			}
			return "虚位以待";
		}
		else{
			var count=0;
			for(i=0;i<len;i++){
				feiShengBangVo=arr[i];
				if(feiShengBangVo.rank >=r1&&feiShengBangVo.rank<=r2){
					if(feiShengBangVo.roleName){
						count++;
					}
				}
			}
			return"已有"+count+"位玩家上榜";
		}
	}

