/**
*护法令逻辑
*@author zhanglimin
*@date 2019-12-11
*/
//class com.xq.modules.active.tianshen.tianShenLing.TianShenLingMgr
var TianShenLingMgr=(function(){
	function TianShenLingMgr(){
		/**护法等级*/
		this.levelCfg=null;
		/**护法任务*/
		this.taskCfg=null;
		/**护法排行*/
		this.rankCfg=null;
		/**活动id*/
		this.actId=0;
		/**护法令购买价格*/
		this.cost=0;
		/**购买1级所需货币数量*/
		this.buycost=0;
		/**所有等急数据*/
		this.allLcCfg=null;
		/**最大等级*/
		this.maxBuyLv=0;
		/**大奖数据*/
		this.bigAry=null;
		/**预览特效*/
		this.ylEffUrl=null;
		/**特效偏移*/
		this.offPo=null;
		/**特效缩放*/
		this.scaNum=NaN;
		/**描写*/
		this.ylDec=null;
		/**购买金令提示*/
		this.buyTip=null;
		/**激活面板提示*/
		this.activationTip=null;
		/**名称*/
		this.ylName=null;
		/**上榜等级*/
		this.sbLevel=0;
		/**当前阶段天数*/
		this.stageDay=0;
		//任务
		this.red=null;
		//护法令奖励数据容器
		this.rewardData=null;
		//护法令任务数据容器
		this.taskData=null;
		//数据模型
		this.model=null;
		//普通大奖列表
		this.baseBigPrize=null;
		//金令大奖列表
		this.specBigPrize=null;
		//活动版本(赛季)
		this.flag=1;
		this.stageExpCache={};
		this.actEndTime=-1;
		this.model=new TianShenLingModel();
		this.offPo=new Point(0,0);
		this.levelCfg=CfgManager.getTableCfg("godcardlevel");
		this.allLcCfg=this.levelCfg.objectDataArray;
		this.taskCfg=CfgManager.getTableCfg("godcardtask");
		this.rankCfg=CfgManager.getTableCfg("godcardrank");
		this.red=Mgr.red;
		this.red.regist("TianShenHall","tianShenLing",true,"TianShenHallRed");
		this.red.regist("TianShenHall","tianShenTask",true,"TianShenHallRed");
		EventCenter.instance.on("UpdateTSLInfoTsEvent",this,this.checkRed);
		EventCenter.instance.on("GetTaskRewardTsEvent",this,this.checkTask);
		ActManager.ins.regist("TianShenHall","tianShenLing",41,"TSL_OPEN_STAUTS");
		NewActiveManager.ins.regActOpenHandler(41,Handler.create(this,this.openAct,null,false));
		NewActiveManager.ins.regActEndHandler(41,Handler.create(this,this.closeAct,null,false));
	}

	__class(TianShenLingMgr,'com.xq.modules.active.tianshen.tianShenLing.TianShenLingMgr');
	var __proto=TianShenLingMgr.prototype;
	__proto.openAct=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["TianShenHall",false]);
		Mgr.tslAct.reqInfo();
	}

	__proto.closeAct=function(){}
	__proto.updateCofig=function(curFlag){
		this.flag=curFlag;
		var tab=CfgManager.getTableCfg("godcardconfig");
		var obj=tab.getItemByField("flag",curFlag);
		this.maxBuyLv=obj.maxbuy;
		this.actId=41
		this.cost=obj.cost;
		this.buycost=obj.buycost;
		this.ylEffUrl=obj.ylUrl;
		var tempAry=obj.effOff.split(";")
		this.offPo=new Point(parseInt(tempAry[0]),parseInt(tempAry[0]));
		this.scaNum=parseFloat(obj.effSca);
		this.stageDay=parseInt(obj.stageDay);
		this.ylDec=obj.ylDec;
		this.buyTip=obj.buyTip;
		this.activationTip=obj.activationTip;
		this.ylName=obj.ylName;
		this.sbLevel=obj.rankLimit;
	}

	__proto.getTaskDataContainer=function(){
		if(!this.taskData){
			this.taskData=new DataContainer();
			var cfgArr=this.taskCfg.objectDataArray;
			var len=cfgArr.length;
			for (var i=0;i < len;i++){
				var cfg=cfgArr[i];
				var ele=new DataElement(cfg);
				this.taskData.addElement(cfg.taskId,ele);
			}
		}
		return this.taskData;
	}

	__proto.getCurRewardData=function(){
		return this.getRewardDataContainer().where("flag",this.flag,"level");
	}

	/**展示排名数据*/
	__proto.getShowRankVoArr=function(){
		return this.model.getShowRankVoArr(this.flag);
	}

	__proto.getRewardDataContainer=function(){
		if(!this.rewardData){
			this.baseBigPrize=[];
			this.specBigPrize=[];
			this.rewardData=new DataContainer();
			var cfgList=this.levelCfg.objectDataArray;
			var len=cfgList.length;
			var bigPriceEle;
			for (var i=0;i < len;i++){
				var ele=new DataElement(cfgList[i]);
				var cfg=ele.getCfgData();
				if(cfg.bigMark=="1"){
					bigPriceEle=ele;
					if(bigPriceEle){
						if(bigPriceEle.getCfgData().flag==cfg.flag){
							bigPriceEle.setValue("nextBigPrize",ele);
						}
					}
					this.baseBigPrize.push(cfg.baseReward);
					this.specBigPrize.push(cfg.specialReward);
				}
				this.rewardData.addElement(i,ele);
				var ary;
				var itemVo;
				if(cfg.baseReward){
					ary=String(cfg.baseReward).split(":");
					itemVo=Mgr.item.getItemVO(ary[0]);
					itemVo.count=parseInt(ary[1]);
					itemVo.whichPanel=10;
					ele.setValue("baseItemVo",itemVo);
				}
				if(cfg.specialReward){
					ary=String(cfg.specialReward).split(":");
					itemVo=Mgr.item.getItemVO(ary[0]);
					itemVo.count=ary[1];
					itemVo.whichPanel=10;
					ele.setValue("specialItemVo",itemVo);
				}
				ele.setValue("hasGetBaseReward",false);
				ele.setValue("hasGetSpecReward",false);
			}
		}
		return this.rewardData;
	}

	/**根据名次获取排行配置*/
	__proto.getRankCfg=function(rank){
		var arr=this.rankCfg.getItemsByField("flag",this.flag);
		var len=arr.length;
		for (var i=0;i < len;i++){
			var obj=arr[i];
			if(rank <=parseInt(obj.rank)){
				return obj;
			}
		}
		return null
	}

	/**
	*根据阶段/赛季获取任务数据
	**/
	__proto.getTaskData=function(type,stage){
		return this.getTaskDataContainer().where("flag",this.flag,"taskId")
		.where("type",type,"taskId")
		.where("stage",stage,"taskId");
	}

	/**根据ID获取任务配置*/
	__proto.getTaskById=function(taskId){
		return this.taskCfg.getItemByField("taskId",taskId);
	}

	/**根据阶段获取总经验*/
	__proto.getStageExp=function(stage){
		var key=this.flag+"_"+stage;
		if(!this.stageExpCache[key]){
			var ary=this.getTaskData(1,stage).array;
			var len=ary.length;
			var tempExp=0;
			for (var i=0;i < len;i++){
				var e=ary[i];
				var obj=e.getCfgData();
				tempExp+=parseInt(obj.rewardExp);
			}
			tempExp *=this.stageDay;
			this.stageExpCache[key]=tempExp;
		}
		return this.stageExpCache[key];
	}

	/**根据等级获取配置*/
	__proto.getCfgByLevel=function(level){
		var dc=this.getRewardDataContainer().where("flag",this.flag,"level").getElement(level);
		if(dc){
			return dc.getCfgData();
		}
		return null;
	}

	/**根据等级范围获取奖励
	*@param isJ:是否金令*/
	__proto.getRewardByLv=function(fromLv,toLv,isJ){
		(isJ===void 0)&& (isJ=false);
		var ary=[];
		var curLv=this.model.level
		for (var lv=fromLv;lv <=toLv;lv++){
			var obj=this.getCfgByLevel(lv);
			if(obj){
				if(!isJ){
					if(obj.baseReward){
						ary.push(obj.baseReward+";");
					}
				}
				else{
					if(obj.specialReward){
						ary.push(obj.specialReward+";");
					}
				}
			}
		}
		if(ary.length > 0){
			var str=ary[ary.length-1];
			ary[ary.length-1]=str.split(";")[0];
		}
		return ary;
	}

	/**检测等级普通奖励是否已领取*/
	__proto.checkIsGetPt=function(lv){
		return this.rewardData.where("flag",this.flag,"level").getValue(lv,"hasGetBaseReward");
	}

	/**检测等级额外奖励是否已领取*/
	__proto.checkIsGetJL=function(lv){
		return this.rewardData.where("flag",this.flag,"level").getValue(lv,"hasGetSpecReward");
	}

	/**根据任务ID获取任务信息*/
	__proto.taskInfoById=function(id){
		if(this.model.taskObj){
			return this.model.taskObj[id];
		}
		return null;
	}

	__proto.checkRed=function(){
		Laya.timer.callLater(this,this.checkTSl);
		Laya.timer.callLater(this,this.checkTask);
	}

	/**护法令红点*/
	__proto.checkTSl=function(){
		var ptKey="TSLPtRewPtRed";
		var jlKey="TSLJLRewPtRed";
		var lv=this.model.level;
		var isRed=false;
		var ary=this.getCurRewardData().array;
		var len=this.model.level;
		for (var i=0;i < len;i++){
			var e=ary[i];
			var obj=e.getCfgData();
			if(lv >=obj.level){
				if(obj.baseReward && !this.checkIsGetPt(obj.level)){
					isRed=true;
					break ;
				}
				if(this.model.hasGodToken && obj.specialReward && !this.checkIsGetJL(obj.level)){
					isRed=true;
					break ;
				}
			}
		}
		if(isRed){
			this.red.showRedPoint("tianShenLing","TSLingRed","TSLingRed");
		}
		else{
			this.red.hideRedPoint("tianShenLing","TSLingRed","TSLingRed");
		}
	}

	/**任务红点*/
	__proto.checkTask=function(){
		var isRed=false;
		var ary=this.getTaskData(1,this.model.curStage).array;
		var len=ary.length;
		for (var i=0;i < len;i++){
			var ele=ary[i];
			var obj=ele.getCfgData();
			var key="TSStageTaskRed"+obj.taskId;
			this.red.hideRedPoint("tianShenTask",key);
			var msg=Mgr.tslMgr.taskInfoById(obj.taskId);
			if(msg && msg.taskProcess >=obj.taskNum){
				if(!msg.isGet){
					isRed=true;
					break ;
				}
			}
		}
		if(isRed){
			this.red.showRedPoint("tianShenTask","TSStageTaskRed");
		}
		else{
			this.red.hideRedPoint("tianShenTask","TSStageTaskRed");
		};
		var sjRed=false;
		isRed=false;
		ary=this.getTaskData(2,1).array;
		len=ary.length;
		for (i=0;i < len;i++){
			var e=ary[i];
			obj=e.getCfgData();
			key="TSSaiJiTaskRed"+obj.taskId;
			this.red.hideRedPoint("tianShenTask",key);
			msg=Mgr.tslMgr.taskInfoById(obj.taskId);
			if(msg && msg.taskProcess >=obj.taskNum){
				if(!msg.isGet){
					isRed=true;
					sjRed=true;
					break ;
					this.red.showRedPoint("tianShenTask",key);
				}
			}
		}
		if(sjRed){
			this.red.showRedPoint("tianShenTask","TSSaiJiTaskRed");
		}
		else{
			this.red.hideRedPoint("tianShenTask","TSSaiJiTaskRed");
		}
		if(isRed){
			this.red.showRedPoint("tianShenTask","TSTaskRed","TSTaskRed");
		}
		else{
			this.red.hideRedPoint("tianShenTask","TSTaskRed","TSTaskRed");
		}
	}

	__proto.onBaseInfo=function(msg){
		this.model.level=msg.level;
		this.model.exp=msg.exp;
		this.model.hasGodToken=msg.hasGodToken;
		this.model.curStage=msg.stage;
		this.model.stageEndTime=msg.stageEndTime;
		this.updateCofig(msg.flag);
		this.setHasGetRewardLevels(msg.getLevel,false);
		this.setHasGetRewardLevels(msg.getGodLevel,true);
		this.checkRed();
		EventCenter.instance.event("UpdateTSLInfoTsEvent");
	}

	__proto.setHasGetRewardLevels=function(lvs,isGoldToken){
		this.getRewardDataContainer();
		var key=isGoldToken ? "hasGetSpecReward" :"hasGetBaseReward";
		for (var i=0;i < lvs.length;i++){
			var lv=lvs[i];
			this.rewardData.where("flag",this.flag,"level").setValue(lv,key,true);
		}
	}

	__proto.onBuyLevel=function(msg){
		this.model.level=msg.level;
		Mgr.prompt.optionPrompt("护法令等级提升至"+msg.level+"级");
		EventCenter.instance.event("UpdateTSLInfoTsEvent");
		EventCenter.instance.event("ONBuyTSLvSuccess");
	}

	__proto.onGetReward=function(msg){
		if(msg.type==1){
			this.setHasGetRewardLevels([msg.level] ,false);
		}
		else if(msg.type==2){
			this.setHasGetRewardLevels([msg.level] ,true);
		}
		this.checkRed();
		EventCenter.instance.event("GetTSlRewardTsEvent");
	}

	__proto.onGetTaskInfo=function(msg){
		if(msg.taskType==1){
			this.model.stageExp=msg.process;
		}
		else{
			this.model.saiJiNum=msg.process;
		};
		var ary=msg.taskInfos;
		var len=ary.length;
		for (var i=0;i < len;i++){
			var tsg=ary [i];
			this.model.taskObj[tsg.taskId]=tsg;
		}
		this.checkTask();
		EventCenter.instance.event("UpdateTSLTaskTsEvent");
	}

	__proto.onTaskRefreshInfo=function(msg){
		var tsg=this.model.taskObj[msg.taskId];
		if(tsg){
			tsg.taskProcess=msg.taskProcess;
			this.model.taskObj[msg.taskId]=tsg;
		}
		this.checkTask();
		EventCenter.instance.event("UpdateTSLTaskTsEvent");
	}

	__proto.onGetTaskReward=function(msg){
		var updateLv=false;
		this.model.exp=msg.exp;
		if(this.model.level!=msg.level){
			updateLv=true;
		}
		this.model.level=msg.level;
		var obj=this.getTaskById(msg.taskId);
		if(obj.type=="1"){
			this.model.stageExp=msg.process;
		}
		else{
			this.model.saiJiNum=msg.process;
		};
		var tsg=this.model.taskObj[msg.taskId];
		if(tsg){
			tsg.isGet=true;
			tsg.rewardTime=msg.rewardTimes
		}
		EventCenter.instance.event("GetTaskRewardTsEvent");
		EventCenter.instance.event("UpdateTSLInfoTsEvent");
	}

	__proto.onGetRankInfo=function(msg){
		this.model.rankAry=msg.ranks;
		this.model.myRnak=msg.rank;
		EventCenter.instance.event("GetTSlRankTsEvent");
	}

	__proto.onGetOneKeyReward=function(msg){
		this.setHasGetRewardLevels(msg.getLevel ,false);
		this.setHasGetRewardLevels(msg.getGodLevel,true);
		EventCenter.instance.event("GetTSlRewardTsEvent");
		this.checkTSl();
	}

	__getset(0,__proto,'actTime',function(){
		if(this.actEndTime==-1){
			var vo=NewActiveManager.ins.getActiveVerDic(this.actId);
			if(vo){
				this.actEndTime=vo.endTime;
			}
			else{
				console.log("！！！震惊了护法令活动居然没开！！！活动ID="+this.actId);
			}
		}
		return this.actEndTime;
	});

	/**获取赛季*/
	__getset(0,__proto,'season',function(){
		var vo=NewActiveManager.ins.getActiveVerDic(this.actId);
		if(vo){
			return vo.flag;
		}
		return 0;
	});

	return TianShenLingMgr;
})()


/**
*护法令数据封装
*@author xiangjia
*@date 2020-2-29
*/
//class com.xq.modules.active.tianshen.tianShenLing.TianShenLingModel
var TianShenLingModel=(function(){
	function TianShenLingModel(){
		/**排名奖励配置*/
		this._rankCfg=null;
		/**排名奖励配置数据容器*/
		this._rankDc=null;
		/**当前等级*/
		this.level=0;
		/**当前经验*/
		this.exp=0;
		/**是否买了护法令*/
		this.hasGodToken=false;
		/**第几阶段*/
		this.curStage=0;
		/**该阶段的活动结束时间*/
		this.stageEndTime=NaN;
		/**阶段任务信息*/
		this.taskObj={};
		this.stageExp=0;
		/**赛季完成任务个数*/
		this.saiJiNum=0;
		//排行
		this.rankAry=null;
		/**我的排名*/
		this.myRnak=0;
		this.initData();
	}

	__class(TianShenLingModel,'com.xq.modules.active.tianshen.tianShenLing.TianShenLingModel');
	var __proto=TianShenLingModel.prototype;
	__proto.initData=function(){
		this._rankCfg=CfgManager.getTableCfg("godcardrank");
	}

	/**获取排名配置数据容器*/
	__proto.getRankDc=function(){
		if(!this._rankDc){
			this._rankDc=new DataContainer();
			CommonUtil.initDataContainer(this._rankDc,this._rankCfg);
		}
		return this._rankDc;
	}

	__proto.getRankArrByFlag=function(flag){
		var dc=this.getRankDc().where("flag",flag,"id");
		return dc.array;
	}

	__proto.getRewardByRankFlag=function(flag,rank){
		var arr=this.getRankArrByFlag(flag);
		var len=arr.length;
		var ele;
		var cof;
		for(var i=0;i<len;i++){
			ele=arr[i];
			if(ele){
				cof=ele.getCfgData();
				if(rank>=cof.minRank&&rank<=cof.rank){
					return cof.rankReward;
				}
			}
		}
		return "";
	}

	/**获取展示排名数据*/
	__proto.getShowRankVoArr=function(flag){
		var rankVos=[];
		var arr=this.rankAry;
		var len=arr.length;
		var info;
		var vo;
		var lastRank=1;
		for(var i=0;i<len;i++){
			info=arr[i];
			vo=new TianShenLingRankVo();
			vo.rank=info.rank+"-"+info.rank;
			vo.playerInfo=info;
			vo.reward=this.getRewardByRankFlag(flag,info.rank);
			lastRank=info.rank+1;
			rankVos.push(vo);
		}
		arr=this.getRankArrByFlag(flag);
		len=arr.length;
		var ele;
		var cof;
		for(i=0;i<len;i++){
			ele=arr[i];
			if(ele){
				cof=ele.getCfgData();
				if(lastRank>=cof.minRank&&lastRank<=cof.rank){
					vo=new TianShenLingRankVo();
					vo.rank=lastRank+"-"+cof.rank;
					vo.reward=cof.rankReward;
					vo.playerInfo=null;
					rankVos.push(vo);
					lastRank=cof.rank+1
				}
			}
		}
		return rankVos;
	}

	return TianShenLingModel;
})()


