//class com.xq.modules.active.vipMiaoSha.SvipMiaoShaMgr
var SvipMiaoShaMgr=(function(){
	function SvipMiaoShaMgr(){
		this.svipMiaoShaSer=null;
		this.vipMiaoShaTab=null;
		this.vipQiangGouInfo=null;
		this.red=null;
		this.svipMiaoShaData=null;
		/**打包购买 所需svip等级*/
		this.daBaoSvip=0;
		this.miaoShaArr=null;
		this.svipMiaoShaClose=false;
		this.vipQiangGouInfo=new Object();
		this.vipMiaoShaTab=CfgManager.getTableCfg("svipmiaosha");
		this.red=Mgr.red;
		this.red.regist("SvipMiaoSha",null,true);
		this.getVipMiaoShaData();
		EventCenter.instance.on("new_function_open",this,this.newOpenFun);
	}

	__class(SvipMiaoShaMgr,'com.xq.modules.active.vipMiaoSha.SvipMiaoShaMgr');
	var __proto=SvipMiaoShaMgr.prototype;
	__proto.newOpenFun=function(funId){
		if(funId=="SvipMiaoSha"){
			Mgr.red.specialRedIcon("SvipMiaoSha",true);
		}
	}

	// }
	__proto.getVipMiaoShaData=function(){
		if(!this.svipMiaoShaData){
			this.svipMiaoShaData=new DataContainer();
			var cfgArr=this.vipMiaoShaTab.objectDataArray;
			var len=cfgArr.length;
			for (var i=0;i < len;i++){
				var cfg=cfgArr[i];
				if(cfg){
					var ele=new DataElement(cfg);
					this.svipMiaoShaData.addElement(cfg.id,ele);
				}
			}
		}
		return this.svipMiaoShaData;
	}

	__proto.regActive=function(){
		var kaiFuLiBaoAct=Mgr.kflbAction;
		NewActiveManager.ins.regActOpenHandler(72,Handler.create(kaiFuLiBaoAct,kaiFuLiBaoAct.sendGetLiBaoInfo,[6],false));
		NewActiveManager.ins.regActEndHandler(72,Handler.create(this,this.closeSvipMiaoSha,null,false));
	}

	__proto.closeSvipMiaoSha=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["SvipMiaoSha"]);
		EventCenter.instance.event("UpdateTab");
	}

	__proto.getYiYuanMiaoShaById=function(id){
		return this.getVipMiaoShaData().getElement(id+"").getCfgData();
	}

	__proto.lingSvipMiaoSha=function(vo){
		var serArr=this.miaoShaArr;
		var len=serArr.length;
		for (var i=0;i < len;i++){
			if(serArr[i].data.id==vo.msg.id){
				serArr[i].data=vo.msg;
			}
			if(this.svipMiaoShaSer.list[i].id==vo.msg.id){
				this.svipMiaoShaSer.list[i]=vo.msg;
			}
		}
		this.checkVipMiaoShaRed(this.svipMiaoShaSer);
		EventCenter.instance.event("yiyuanmiaosha_reward_fly");
	}

	/**svip秒杀加红点*/
	__proto.checkVipMiaoShaRed=function(msg){
		var arr=msg.list;
		this.svipMiaoShaSer=msg;
		var len=arr.length;
		this.svipMiaoShaClose=true;
		this.miaoShaArr=[];
		for (var i=0;i < len;i++){
			var liBaoMsg=msg.list[i];
			if(liBaoMsg.state==1){
				this.red.showRedPoint("SvipMiaoSha",msg.type+"_"+liBaoMsg.id,"MiaoShaHallRed");
				}else{
				this.red.hideRedPoint("SvipMiaoSha",msg.type+"_"+liBaoMsg.id,"MiaoShaHallRed");
			}
			if(liBaoMsg.state !=2){
				this.svipMiaoShaClose=false;
			};
			var ele=this.getVipMiaoShaData().getElement(liBaoMsg.id+"");
			ele.data=liBaoMsg;
			if(i==(len-1)){
				this.daBaoSvip=parseInt(ele.getCfgData().svipLimit);
			}
			this.miaoShaArr.push(ele);
		}
		if(this.svipMiaoShaClose || !Mgr.kaiFuHDMgr.progress){
			EventCenter.instance.event("ACTIVE_TOGGLE",["SvipMiaoSha"]);
			EventCenter.instance.event("UpdateTab");
		}
		EventCenter.instance.event("update_svipmiaosha");
	}

	SvipMiaoShaMgr.UPDATE_SVIPMIAOSHA="update_svipmiaosha";
	return SvipMiaoShaMgr;
})()


