//class com.xq.modules.active.xianShiQiYu.XianShiQiYuMgr
var XianShiQiYuMgr=(function(){
	function XianShiQiYuMgr(){
		this._model=null;
		this._red=null;
		this._model=new XianShiQiYuModel();
		this.registRed();
	}

	__class(XianShiQiYuMgr,'com.xq.modules.active.xianShiQiYu.XianShiQiYuMgr');
	var __proto=XianShiQiYuMgr.prototype;
	__proto.regActive=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["ZhaoCaiMiao"]);
		ActManager.ins.regist("XianShiQiYuHall","ZhaoCaiMiao",192,"XianShiQiYu");
		NewActiveManager.ins.regActOpenHandler(192,Handler.create(this,this.onActOpen,null,false));
		NewActiveManager.ins.regActEndHandler(192,Handler.create(this,this.onActClose,null,false));
	}

	__proto.onActOpen=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["ZhaoCaiMiao",false]);
		Mgr.xianShiQiYuA.sendGetInfo();
	}

	__proto.onActClose=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["ZhaoCaiMiao"]);
	}

	/**更新招财猫信息*/
	__proto.updateInfo=function(msg){
		this._model.updateInfo(msg);
		EventCenter.instance.event("UpdateInfo");
		this.updateRed();
	}

	/**更新日志信息*/
	__proto.updateLog=function(msg){
		this._model.updateLog(msg);
		EventCenter.instance.event("updateLog");
	}

	/**刷新抽奖*/
	__proto.updateDraw=function(msg){
		this._model.updateDraw(msg);
		EventCenter.instance.event("UpdateDraw");
	}

	/**刷新抽奖次数*/
	__proto.updateDrawCountAdd=function(msg){
		this._model.updateDrawCountAdd(msg);
		EventCenter.instance.event("UpdateDrawCountAdd");
		this.updateRed();
	}

	//=============红点=============
	__proto.registRed=function(){
		this._red=Mgr.red;
		this._red.regist("ZhaoCaiMiao",null,true);
	}

	__proto.updateRed=function(){
		var info=this.getInfo();
		if(!info||info.hasTimes<=0){
			this._red.hideRedPoint("ZhaoCaiMiao","drawTime","XianShiQiYuHallRed");
			return;
		}
		this._red.showRedPoint("ZhaoCaiMiao","drawTime","XianShiQiYuHallRed");
	}

	/**获取奇遇招财猫后端数据*/
	__proto.getInfo=function(){
		return this._model.getInfo();
	}

	/**获取我的个人日志数据*/
	__proto.getMyLogs=function(){
		return this._model.getMyLogs();
	}

	/**获取全服日志数据*/
	__proto.getAllLogs=function(){
		return this._model.getAllLogs();
	}

	__proto.getResultPer=function(){
		return CommonUtil.floatNumUtil(this._model.getResultPer(),1);
	}

	__proto.getResultYbNum=function(){
		return this._model.getResultYbNum();
	}

	/**根据倍率获取对应的格子栏位*/
	__proto.getGridByPer=function(per){
		var dc=this._model.getGridDc().where("rate",per,"rate");
		var ele=dc.getElement(per);
		if(!ele)return-1;
		return parseInt(ele.getCfgData().grid);
	}

	/**根据格子栏位 获取一个角度*/
	__proto.getTargetRotationByGrid=function(grid){
		var ele=this._model.getGridDc().getElement(grid);
		if(!ele)return 0;
		var roll=3;
		var rota=parseInt(ele.getCfgData().rota);
		var romRota=Math.floor(45/2-Math.random()*40);
		return rota+romRota+360*roll;
	}

	__proto.getTargetRotation=function(){
		var per=this.getResultPer();
		var grid=this.getGridByPer(per);
		var rota=this.getTargetRotationByGrid(grid);
		return rota;
	}

	/**通过指针角度获取当前指在那个格子*/
	__proto.getGridByRotation=function(rota){
		rota=rota%360;
		var arr=this._model.getGridDc().array;
		var len=arr.length;
		var ele;
		for(var i=0;i<len;i++){
			ele=arr[i];
			var cof=ele.getCfgData();
			var cfgRota=parseInt(cof.rota);
			if(rota>0&&rota<=22.5&&cfgRota==360){
				cfgRota=0;
			}
			if(cfgRota-22.5<rota&&cfgRota+22.5>=rota){
				return cof.grid;
			}
		}
		return-1;
	}

	__proto.getCfgRotaByGrid=function(grid){
		var ele=this._model.getGridDc().getElement(grid);
		if(!ele)return 0;
		return parseInt(ele.getCfgData().rota);
	}

	__proto.getCurFlag=function(){
		var opAct=NewActiveManager.ins.getActiveVerDic(192);
		if(!opAct)return-1;
		return opAct.flag;
	}

	/**获取活动结束时间戳*/
	__proto.getCurActTime=function(){
		var opAct=NewActiveManager.ins.getActiveVerDic(192);
		if(!opAct)return 0;
		return opAct.endTime;
	}

	/**根据flag获取版本配置*/
	__proto.getCofEleByFlag=function(flag){
		var ele=this._model.getZcmDc().getElement(flag);
		return ele;
	}

	/**获取当前版本配置*/
	__proto.getCurFlagCofEle=function(){
		var flag=this.getCurFlag();
		if(flag==-1)return null;
		return this.getCofEleByFlag(flag);
	}

	/**获取当前版本日志模板配置*/
	__proto.getCurFlagLogDesc=function(){
		var cfgEle=Mgr.xianShiQiYuM.getCurFlagCofEle();
		if(!cfgEle)return "";
		var cof=cfgEle.getCfgData();
		return cof.recordText;
	}

	__proto.getGridArr=function(){
		return this._model.getGridDc().array;
	}

	return XianShiQiYuMgr;
})()


