//class com.xq.modules.active.zhuanjintong.ZhuanJinTongMgr
var ZhuanJinTongMgr=(function(){
	function ZhuanJinTongMgr(){
		this._model=null;
		this._red=null;
		this._action
		this._model=new ZhuanJinTongModel();
		this._red=Mgr.red;
		this._action=Mgr.zhuanJinTongA;
		this.registRed();
	}

	__class(ZhuanJinTongMgr,'com.xq.modules.active.zhuanjintong.ZhuanJinTongMgr');
	var __proto=ZhuanJinTongMgr.prototype;
	//===============红点====================
	__proto.registRed=function(){
		this._red.regist("fulidating","zhuanjintong",true,"fulidating");
	}

	__proto.getcostArray=function(){
		return this._model.getcost_Dc().array;
	}

	__proto.getZJTInfo=function(msg){
		this._model.getZJTInfo(msg);
		EventCenter.instance.event("UpdateInfo");
		this.updateRed();
	}

	__proto.updateRed=function(){
		var info=this.getInfo();
		var index=this.getmaxtimer(NetMgr.ins().roleVO.vipLevel)
		if(info.times>0||index==0){
			this._red.showRedPoint("zhuanjintong","ZJT_RedPoint","fulidating");
			}else{
			this._red.hideRedPoint("zhuanjintong","ZJT_RedPoint","fulidating");
		}
	}

	__proto.getZJTExpInfo=function(vo){
		if(vo.errCode==1){
			this._action.sendGetInfo();
			Mgr.prompt.optionPrompt("本次获得 "+CommonUtil.numFormat(vo.exp*vo.rate)+"经验");
			var string="dj1004:"+vo.exp;
			RewardUtil.show([string],1);
		}
		else{
			if(vo.errCode==1002){
				UIMgrR.openIView(com.xq.view.modules.vip.IYuanBaoBuZuView,2);
			}
			else{
				Mgr.prompt.optionPrompt(CodeMgr.ins.getStringByCode(vo.errCode));
			}
		}
	}

	/**获取转经筒后端数据*/
	__proto.getInfo=function(){
		return this._model.getInfo();
	}

	/**通过vip等级获取当前最大转钱次数*/
	__proto.getmaxtimer=function(viplevel){
		var ele=Model.vip.svipDc.getElement(viplevel);
		if(!ele)return 0;
		var maxtimer=parseInt(ele.getCfgData().zhuanjingcount);
		return maxtimer;
	}

	/**返回本次消耗的玉币数量*/
	__proto.getCost=function(CurIndex){
		var arr=this.getcostArray();
		var length=arr.length;
		var ele;
		var id=0;
		var cost=0;
		for(var i=0;i<length;i++){
			ele=arr[i];
			id=parseInt(ele.getCfgData().id);
			if(id==CurIndex+1){
				cost=parseInt(ele.getCfgData().cost);
				break ;
			}
		}
		return cost;
	}

	return ZhuanJinTongMgr;
})()


