//class com.xq.modules.activity.chongbangxiaofei.ChongBangXiaoFeiMgr
var ChongBangXiaoFeiMgr=(function(){
	function ChongBangXiaoFeiMgr(){
		/**冲榜消费Cfg*/
		this.cbxfCfg=null;
		this._curType=0;
		this.red=null;
		this.cbxfCfg=CfgManager.getTableCfg("leijixiaofei3");
		EventCenter.instance.on("GetTargetRewardOpraEvent",this,this.checkRed);
		EventCenter.instance.on("UpDataTargetInfoOpraEvent",this,this.checkRed);
		this.red=Mgr.red;
		this.red.regist("feishengbang","ChongBangXiaoFei",true,"FeiShengBangTabRed");
	}

	__class(ChongBangXiaoFeiMgr,'com.xq.modules.activity.chongbangxiaofei.ChongBangXiaoFeiMgr');
	var __proto=ChongBangXiaoFeiMgr.prototype;
	__proto.regActive=function(){
		ActManager.ins.regist("quanminchongbang","ChongBangXiaoFei",48,"ChongBanActEvent");
		var opAct=Mgr.opeAct;
		var hand=Handler.create(opAct,opAct.sendGetTargetActivity,[48],false)
		NewActiveManager.ins.regActOpenHandler(48,hand);
		NewActiveManager.ins.regActEndHandler(48,Handler.create(this,this.closeAct,null,false));
	}

	__proto.closeAct=function(){}
	//EventCenter.instance.on(GameEvent.ACTIVE_TOGGLE,this,onActiveToggle);
	__proto.getCfgByType=function(){
		var opinfo=NewActiveManager.ins.getActiveVerDic(48);
		var ary=[];
		if(opinfo){
			ary=this.cbxfCfg.getItemsByField("group",opinfo.flag);
			var wlq=100;
			var wdc=200;
			var ylq=300;
			var len=ary.length;
			var oprVo=Mgr.opeAct.getOprationVo(48);
			for (var i=0;i < len;i++){
				var obj=ary[i];
				if(oprVo){
					var vo=oprVo.getTargetInfo(obj.id);
					if(vo){
						if(vo.state==1){
							obj["sortFlag"]=ylq++;
						}
						else if(vo.process >=obj.num){
							obj["sortFlag"]=wlq++;
						}
						else{
							obj["sortFlag"]=wdc++;
						}
						obj["tarInfo"]=vo;
					}
					else{
						obj["sortFlag"]=wdc++;
					}
				}
				else{
					obj["sortFlag"]=wdc++;
				}
			};
			var fun=function (a,b){
				return a["sortFlag"]-b["sortFlag"];
			}
			ary.sort(fun);
		}
		return ary;
	}

	__proto.checkRed=function(id){
		if(id==48){
			var arr=this.getCfgByType();
			var len=arr.length;
			for (var i=0;i < len;i++){
				var tarInfo=arr[i]["tarInfo"];
				if(tarInfo && tarInfo.state !=1 && tarInfo.process >=arr[i].num){
					this.red.showRedPoint("ChongBangXiaoFei","cbxf","FeiShengBangTabRed");
					return;
					}else{
					this.red.hideRedPoint("ChongBangXiaoFei","cbxf","FeiShengBangTabRed");
				}
			}
		}
	}

	return ChongBangXiaoFeiMgr;
})()


