//class com.xq.modules.activity.HuoDongHallMgr
var HuoDongHallMgr=(function(){
	function HuoDongHallMgr(){
		/**魂玉返利表名*/
		this._HUNYUFANLICOF="hunyufanli";
		/**圣印返利表名*/
		this._SHENGYINFANLICOF="shengyinfanli";
		/**魂玉返利表数据*/
		this._hunYuFanLiCof=null;
		/**圣印返利表数据*/
		this._shengYinFanLiCof=null;
		/**红点管理类引用*/
		this._red=null;
		this._hunYuFanLiCof=CfgManager.getTableCfg(this._HUNYUFANLICOF);
		this._shengYinFanLiCof=CfgManager.getTableCfg(this._SHENGYINFANLICOF);
		this._red=Mgr.red;
		this._red.regist("huoDongMain","hunYuFanLi",true,"huoDongMain");
		this._red.regist("huoDongMain","shengYinFanLi",true,"huoDongMain");
	}

	__class(HuoDongHallMgr,'com.xq.modules.activity.HuoDongHallMgr');
	var __proto=HuoDongHallMgr.prototype;
	// EventCenter.instance.on(GameEvent.NEW_FUN_OPEN,this,newOpenFun);
	__proto.regActive=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["shengYinFanLiNew"]);
		ActManager.ins.regist("huoDongMain","hunYuFanLi",68,"HuoDongIconEvent");
		ActManager.ins.regist("huoDongMain","shengYinFanLi",69,"HuoDongIconEvent");
		var fsbAct=Mgr.feiShengBangAction;
		var hunYuFanLi=Handler.create(this,this.openHunYu,null,false);
		NewActiveManager.ins.regActOpenHandler(68,hunYuFanLi);
		var shengYinFanLi=Handler.create(this,this.openShenYin,null,false);
		NewActiveManager.ins.regActOpenHandler(69,shengYinFanLi);
		NewActiveManager.ins.regActEndHandler(68,Handler.create(this,this.closeAct,[68],false));
		NewActiveManager.ins.regActEndHandler(69,Handler.create(this,this.closeAct,[69],false));
	}

	__proto.closeAct=function(actId){
		if(actId==68){
			this._red.hideAll("hunYuFanLi","huoDongMain");
		}
		else if(actId==69){
			this._red.hideAll("shengYinFanLi","huoDongMain");
			EventCenter.instance.event("ACTIVE_TOGGLE",["shengYinFanLiNew"]);
		}
	}

	__proto.openHunYu=function(){
		Mgr.feiShengBangAction.sendGetDanBiChongZhi(68);
	}

	//
	__proto.openShenYin=function(){
		Mgr.feiShengBangAction.sendGetDanBiChongZhi(69);
		EventCenter.instance.event("ACTIVE_TOGGLE",["shengYinFanLiNew",false]);
	}

	/**飞升榜单笔充值红点*/
	__proto.checkFanLiRed=function(msg){
		var list_arr=[];
		var _msg;
		var _data;
		var _cof;
		var arr=msg.msgList;
		var len=arr.length;
		for (var i=0;i < len;i++){
			_msg=arr[i];
			_data={};
			_cof=msg.opactivityType==68?this.getHunYuCofById(_msg.id):this.getShengYinCofById(_msg.id);
			if(!_cof){
				continue ;
			}
			_data.cfg=_cof;
			_data.ser=_msg;
			_data.type=msg.opactivityType;
			if(parseInt(_cof.num)> _msg.getCount && _msg.getCount < _msg.finishCount){
				if(msg.opactivityType==68){
					this._red.showRedPoint("hunYuFanLi",_msg.id+"hunYuFanLiRed","huoDongMain");
				}
				else if(msg.opactivityType==69){
					this._red.showRedPoint("shengYinFanLi",_msg.id+"shengYinFanLiRed","huoDongMain");
				}
				_data.index=2;
			}
			else{
				if(msg.opactivityType==68){
					this._red.hideRedPoint("hunYuFanLi",_msg.id+"hunYuFanLiRed","huoDongMain");
				}
				else if(msg.opactivityType==69){
					this._red.hideRedPoint("shengYinFanLi",_msg.id+"shengYinFanLiRed","huoDongMain");
				}
				if(parseInt(_cof.num)> _msg.getCount){
					_data.index=1;
				}
				else{
					_data.index=0;
				}
			}
			list_arr.push(_data);
		}
		EventCenter.instance.event("updata_hunyufanli",[list_arr]);
	}

	__proto.getHunYuCofById=function(id){
		return this._hunYuFanLiCof.getItemByField("id",id+"");
	}

	//========================圣印返利==========================
	__proto.getShengYinCofById=function(id){
		return this._shengYinFanLiCof.getItemByField("id",id+"");
	}

	HuoDongHallMgr.UPDATA_HUNYUFANLI="updata_hunyufanli";
	return HuoDongHallMgr;
})()


