	__proto.bagDeleteItems=function(guids){
		if (this.bagGuidDic==null){
			return;
		}
		for (var i=0;i < guids.length;i++){
			var bagGoodVO=this.bagGuidDic[guids[i]];
			if (bagGoodVO && bagGoodVO.slotNum && this.bagGoodsArr[bagGoodVO.slotNum-1]){
				this.bagGoodsArr[bagGoodVO.slotNum-1]=null;
			}
			this.bagGuidDic[guids[i]]=null;
		}
		Mgr.itemPro.sendGetBagGoodsMsg();
		this.itemChanged();
	}

