	/**
	*更新背包道具数据,只能更改背包总数组，和guid字典数据，不能更改单个物品数据
	*/
	__proto.updateItem=function(itemMsgs){
		if (this.bagGuidDic==null)return;
		var len=itemMsgs.length;
		for (var i=0;i < len;i++){
			var itemMsg=itemMsgs[i];
			if(!itemMsg)continue ;
			var templateId=itemMsg.templateId;
			var bagItemVO=this.bagGuidDic[itemMsg.guid];
			if (!bagItemVO){
				continue ;
			}
			bagItemVO.count=itemMsg.count;
			bagItemVO.itemMsg=itemMsg;
			if(templateId && templateId.indexOf("d")==0){
				var itemVO=this.createItemVo(itemMsg);
				if(!itemVO)return;
				itemVO.whichPanel=0;
				this.bagGoodsArr[itemMsg.slotNum-1]=itemVO;
				this.bagGuidDic[itemMsg.guid]=itemVO;
				this.itemSingleAry[itemVO.templateId]=itemVO.count;
			}
			else if(templateId.indexOf("z")==0 || templateId.indexOf("y")==0){
				var bagEquipVO=this.createEquipVO(itemMsg);
				if(!bagEquipVO)return;
				bagEquipVO.whichPanel=0;
				this.bagGoodsArr[itemMsg.slotNum-1]=bagEquipVO;
				this.bagGuidDic[itemMsg.guid]=bagEquipVO;
				this.itemSingleAry[bagEquipVO.templateId]=bagEquipVO.count;
			}
		}
		EventCenter.instance.event("ITEM_UPDATE");
		this.itemChanged();
	}

