/**
*2.0获取到背包服务器数组
*/
__proto.getBagItemMsgs=function(itemMsgs){
	this.red.hideRedPoint("bag","clear",RedTypeEnum.Bag);
	this.bagGemArr=[];
	this.bagEquipArr=[];
	this.bagItemArr=[];
	this.bagFaBaoArr=[];
	this.bagTuJianArr=[];
	var gemArr=[];
	var faBaoArr=[];
	var tuJianArr=[];
	var itemArr=[];
	var equipArr=[];
	this.bagGoodsArr.length=0;
	this.bagGoodsArr.length=this.bagCapacity;
	this.equipPartDic={};
	this.bagGuidDic={};
	this.bagGoodLen=itemMsgs.length;
	for (var i=0;i < this.bagGoodLen;i++){
		var itemMsg=itemMsgs[i];
		var templateId=itemMsg.templateId;
		var firstStr=templateId.substr(0,1);
		switch(firstStr){
			case "d":{
					var d=this.createItemVo(itemMsg);
					if(!d)break ;
					d.whichPanel=0;
					if(d.cfgItem.category==2){
						gemArr.push(d);
					}
					else if(d.cfgItem.category==33){
						faBaoArr.push(d);
					}
					else if(d.cfgItem.category==35){
						tuJianArr.push(d);
					}
					else{
						itemArr.push(d);
					}
					this.bagGoodsArr[itemMsg.slotNum-1]=d;
					this.bagGuidDic[itemMsg.guid]=d;
					if(d.cfgItem.skill=="10"||d.cfgItem.category==200){
						this.red.showRedPoint("bag","clear",RedTypeEnum.Bag);
					}
					break ;
				}
			default :{
					var z=this.createEquipVO(itemMsg);
					if (z==null){
						return;
					}
					z.whichPanel=0;
					this.pushEquipPartDic(z);
					this.bagGoodsArr[itemMsg.slotNum-1]=z;
					this.bagGuidDic[itemMsg.guid]=z;
					equipArr.push(z);
					break ;
				}
			}
	}

	this.itemChanged();
	this.updateBagByType(itemArr,1);
	this.updateBagByType(gemArr,2);
	this.updateBagByType(faBaoArr,3);
	this.updateBagByType(tuJianArr,5);
	this.updateBagByType(equipArr,4);
	this.bagEquipArr=this.bagEquipArr.sort(this.compare);
	this.checkBestScoreEquip();
	EventCenter.instance.event("ITEM_LIST_UPDATED");
	this.equipLen=equipArr.length;
	this.itemLen=itemArr.length;
	this.gemLen=gemArr.length;
	this.fabaoLen=faBaoArr.length;
	this.tuJianLen=tuJianArr.length;
	if((this.equipLen+6)>=this.getMaxCountByBagType(4)){
		this.bagIsFull=true;
		EventCenter.instance.event("bag_all_fill",[true]);
		if(Mgr.chaoZhiTeDianMgr.isBuyZz || Mgr.gqMgr.openAutoCha){
			Laya.timer.callLater(this,this.autoSmeltEquip);
		}
	}

	else{
		this.bagIsFull=false;
		EventCenter.instance.event("bag_all_fill",[false]);
	}

}


/**根据类型更新背包数据*/
__proto.updateBagByType=function(arr,type){
	var targetArr=this.getBagDataByType(type);
	var len=this.getMaxCountByBagType(type);
	targetArr.length=len;
	for (var i=0;i < len;i++){
		if(arr[i]){
			targetArr[i]=arr[i];
		}
	}

}


__proto.checkBestScoreEquip=function(){
	var screenEquipDic=new Dictionary();
	var betterEquipArr=[];
	var len=this.bagEquipArr.length;
	for (var i=0;i < len;i++){
		var equipVO=this.bagEquipArr[i];
		if(!equipVO)break ;
		var isBest=Mgr.equip.checkEquipBestScore(equipVO);
		if(isBest){
			var curPartEquip=screenEquipDic.get(equipVO.partPos);
			if(curPartEquip){
				if(curPartEquip.attrScore < equipVO.attrScore){
					screenEquipDic.set(equipVO.partPos,equipVO)
				}
				}else{
				screenEquipDic.set(equipVO.partPos,equipVO)
			}
		}
	}

	this.bestScoreArr=screenEquipDic;
	EventCenter.instance.event("get_new_equip");
}


__proto.compare=function(vo1,vo2){
	if(vo1.cfgItem.itemlevel > vo2.cfgItem.itemlevel){
		return-1
	}

	else if(vo1.cfgItem.itemlevel==vo2.cfgItem.itemlevel){
		if(vo1.rareLv > vo2.rareLv){
			return-1;
		}
		else if(vo1.rareLv==vo2.rareLv){
			if(vo1.cfgItem.star > vo2.cfgItem.star){
				return-1;
				}else if(vo1.cfgItem.star < vo2.cfgItem.star){
				return 1;
			}
			return 0;
		}
		else{
			return 1;
		}
	}

	else{
		return 1;
	}

	return 0;
}


/**背包满自动熔炼装备 特权卡特权*/
__proto.autoSmeltEquip=function(){
	var smeltArr=[];
	var canSmeltArr=this.getCanSmeltEquips();
	var minEquipDic=Mgr.equip.getAllMinEquipInfo();
	var len=canSmeltArr.length;
	if(Mgr.equip.smeltRareLv > 4){
		Mgr.equip.smeltRareLv=4;
	}

	for (var i=0;i < len;i++){
		var e=canSmeltArr[i];
		if (e.partPos < 1 || e.partPos > 10){
			continue ;
		}
		if (e.cfgItem.star >=this.minSmeltStar){
			continue ;
		}
		if(e.partPos==7 || e.partPos==8){
			continue ;
		};
		var minFight=minEquipDic[e.partPos] || 0;
		if(e.totalScore > minFight){
			continue ;
		}
		smeltArr.push(e.guid);
	}

	if(smeltArr.length > 0){
		Mgr.equipPro.sendSmelt(smeltArr);
	}

	else{
		Mgr.prompt.optionPrompt("暂无可熔炼装备");
	}

}


