	__proto.getCfgData=function(flag,type){
		var obj=this.bcxdCfg.getCfgMsgArrByTwoKey("flag",flag,"type",type)[0];
		if(obj){
			this.steChouJiangItem(obj.costitem);
		}
		return obj;
	}

