/**
*战役Boss Mgr
*@author huanghong
*2020-10-12
*/
//class com.xq.modules.boss.BattleBoss.BattleBossMgr
var BattleBossMgr=(function(){
	function BattleBossMgr(){
		this.curBossType=0;
		/**当前选中BossEle*/
		this.curBossEle=null;
		/**buffVo*/
		this.buffVo=null;
		/**查询支援BossId*/
		this.supBossId=0;
		/**支援列表*/
		this.supBossList=null;
		/**本次登录是否禁止 支援弹窗弹出*/
		this.ifClosePrompt=false;
		/**跳转BossId*/
		this.jumpBossId=0;
		/**buff加成倍率*/
		this.rate=NaN;
		this._curChallengeBossInfo=null;
		this._model=null;
		this._red=null;
		this._roleVo=null;
		this.copyView=null;
		this._model=Model.battleBoss;
		this._red=Mgr.red;
		this._roleVo=NetMgr.ins().roleVO;
		CopyTipMgr.ins.regisCopyTip(2023,Handler.create(this,this.closeTips,null,false));
		this.initRed();
	}

	__class(BattleBossMgr,'com.xq.modules.boss.BattleBoss.BattleBossMgr');
	var __proto=BattleBossMgr.prototype;
	/**获取默认选中页签（根据是否有召唤）*/
	__proto.getDefualtSelectIndex=function(type){
		return this._model.getDefualtSelectIndex(type);
	}

	__proto.updateBattleBossInfo=function(data){
		var bossList=data.list;
		var len=bossList.length;
		for(var i=0;i<len;i++){
			var msg=bossList[i];
			var id=msg.cfgId;
			var ele=this._model.dc.getElement(id);
			if(ele){
				ele.setValue("bossInfo",msg);
			}
		}
		this._model.countDic.set(data.type,data.helpTimes);
		EventCenter.instance.event("updateBattleBossInfo");
		this.updateRed(data.type);
	}

	/**更新支援列表数据*/
	__proto.updateSupBossList=function(msg){
		this.supBossId=msg.cfgId;
		this.supBossList=msg.list;
		var ele=this._model.dc.getElement(this.supBossId);
		if(ele){
			var data=ele.getValue("bossInfo");
			if(data){
				data.list=this.supBossList;
			}
		}
		EventCenter.instance.event("updateSupBossList");
	}

	/**收到支援请求*/
	__proto.showSupTip=function(msg){
		if(this.ifClosePrompt)return;
		var v=UIMgrR.openIView(com.xq.view.modules.bossHall.battleBoss.IBattleBossSupTips,2);
		v.dataSource=msg;
	}

	__proto.clearJumpId=function(){
		this.jumpBossId==0;
	}

	/**玩家是否已经召唤了这个boss*/
	__proto.ifMeCalled=function(id){
		var ele=this._model.dc.getElement(id);
		if(ele){
			var msg=ele.getValue("bossInfo");
			if(msg){
				var type=ele.getCfgData().teamType;
				var arr=msg.list;
				var len=arr.length;
				var curtime=Mgr.curTime.serverTimer;
				for(var i=0;i<len;i++){
					var data=arr[i];
					var team=this.checkTeam(type,data,curtime);
					if(team){
						var dataO={};
						dataO.data=data;
						dataO.type=type;
						dataO.team=team
						return dataO;
					}
				}
			}
			return null;
		}
		return null;
	}

	/**0:没有召唤 1，自己召唤了 2伴侣召唤了 3 战队召唤了 4帮派召唤了*/
	__proto.checkTeam=function(type,data,curtime){
		var id=data.roleId;
		var endTime=data.endTime;
		switch(type){
			case 1:{
					if(id==this._roleVo.guid&&endTime>curtime){
						return 1;
					}
					return 0;
				}
			case 2:{
					if(data.endTime>curtime){
						if(id==this._roleVo.guid){
							return 1;
						}
						else if(Model.marriage.checkIsPartarner(id)){
							return 2;
						}
						return 0;
					}
					return 0;
				}
			case 3:{
					return 0;
				}
			case 4:{
					if(data.endTime>curtime){
						if(id==this._roleVo.guid){
							return 1;
						}
						else if(this._roleVo.guildId!=0&&data.otherId==this._roleVo.guildId){
							return 4;
						}
						return 0;
					}
					return 0;
				}
			}
		return 0;
	}

	__proto.getTeamNameByType=function(type){
		var str;
		switch(type){
			case 1:{
					str="个人";
					break ;
				}
			case 2:{
					str="夫妻";
					break ;
				}
			case 3:{
					str="战队";
					break ;
				}
			case 4:{
					str="帮派";
					break ;
				}
			}
		return str
	}

	__proto.getBuffByType=function(type){
		var buffO=new BattleBossBuffVo();
		var t=0;
		switch(type){
			case 1:{
					t=13;
					break ;
				}
			case 2:{
					t=11;
					break ;
				}
			case 3:{
					t=14;
					break ;
				}
			case 4:{
					t=15;
					break ;
				}
			};
		var count=Mgr.szMgr.getShiZhuangNum(t);
		buffO.count=count;
		buffO.fightValue=this._roleVo.fightValue;
		buffO.name=this._roleVo.name;
		buffO.zzType=this.getCurTypeName();
		if(this.curBossEle){
			var per=this.curBossEle.getCfgData().per;
			buffO.per=count *per;
		}
		return buffO;
	}

	__proto.updateBuff=function(msg){
		if(!this.buffVo){
			this.buffVo=new BattleBossBuffVo();
		}
		this.buffVo.per=msg.per;
		this.buffVo.name=msg.name;
		this.buffVo.count=msg.num;
		this.buffVo.fightValue=msg.fight;
		this.buffVo.zzType=this.getCurTypeName();
		EventCenter.instance.event("udpateCopyBuff");
	}

	__proto.getCurTypeName=function(){
		if(this.curBossType==1){
			return "侠客幻化";
		}
		else if(this.curBossType==2){
			return "宠物幻化";
		}
		else if(this.curBossType==3){
			return "红颜幻化";
		}
		else if(this.curBossType==4){
			return "魔神幻化";
		}
		return "";
	}

	/**召唤成功后提示*/
	__proto.showCalledTips=function(msg){
		var id=msg.cfgId;
		var ele=this._model.dc.getElement(id);
		if(!ele)return;
		this.enterBoss=msg.info;
		Mgr.battleBossMgr.supBossId=id;
		this.okHandler(id);
	}

	__proto.okHandler=function(id){
		Mgr.battleBossAction.c_snatch(this.enterBoss.roleId,id);
	}

	__proto.onEnterCopy=function(){
		UIMgrR.closeIView(com.xq.view.modules.bossHall.battleBoss.IBattleBossSupListView);
		EventCenter.instance.on("BOSS_OWER_CHANGE",this,this.setOwner);
	}

	__proto.setOwner=function(monsterId){
		var v=UIMgrR.getIView(com.xq.view.mainUI.subPanel.IMiniUnitBloodBoxView);
		var ownvo=Mgr.bossOwnerM.getOwner(monsterId);
		if(v&&ownvo){
			if(this.curBossEle){
				var cof=this.curBossEle.getCfgData()
				var type=cof.isQiangDuo;
				if(type){
					var team=cof.teamType;
					if(this.checkAttack(ownvo.ownerId,team)){
						v.setOwer(ownvo,2);
					}
					else{
						v.setOwer(ownvo,1);
					}
				}
				else{
					v.setOwer(ownvo,2);
				}
			}
		}
	}

	__proto.checkAttack=function(roleId,type){
		switch(type){
			case 1:{
					if(roleId==this._roleVo.guid){
						return true;
					}
					break ;
				}
			case 2:{
					if(Model.marriage.checkIsPartarner(roleId)){
						return true;
					}
					break ;
				}
			case 3:{
					break ;
				}
			case 4:{
					if(this._roleVo.guildId!=0&&Mgr.guild.checkGuild(roleId)){
						return true;
					}
					break ;
				}
			}
		return false;
	}

	/**结算*/
	__proto.onResult=function(msg){
		var ifWin=msg.isSuccess;
		if(ifWin){
			var v=UIMgrR.openIView(com.xq.view.modules.bossHall.battleBoss.IBattleBossVictoryView,2);
			v.dataSource=msg;
		}
		else{
			UIMgrR.openIView(com.xq.view.modules.bossHall.battleBoss.IBattleBossFailView,2);
		}
	}

	__proto.getMapFuHuoNum=function(){
		var obj=this._model.mapCof.getItemByField("mapid",NetMgr.ins().roleVO.mapId);
		if(obj){
			return obj.borntimes;
		}
		return 0;
	}

	__proto.initFightVo=function(fightVo){
		fightVo.hideAry=[1,2,3,4];
		fightVo.closeFun=Handler.create(this,this.exit,null,false);
		var ele=this._model.getBossEleById(this.supBossId);
		if(ele){
			var rewards=ele.getCfgData().showRewards
			fightVo.reward=rewards;
		}
		this.showTips();
	}

	/**退出副本**/
	__proto.exit=function(){
		Mgr.battleBossAction.c_exit();
	}

	__proto.showTips=function(){
		this.copyView=UIMgrR.openIView(com.xq.view.modules.bossHall.battleBoss.IBattleBossCopyView,2);
	}

	__proto.closeTips=function(){
		if(this.copyView&&this.copyView.isPopup){
			this.copyView.close();
			this.copyView=null;
		}
		this.enterBoss=null;
		EventCenter.instance.off("BOSS_OWER_CHANGE",this,this.setOwner);
	}

	//================红点相关===================
	__proto.initRed=function(){
		this._red.regist("bosshall","zhanyiboss",true,RedTypeEnum.BossHallRed);
		this._red.regist("zhanyiboss","mingjiangboss",false,"BattleBossRed");
		this._red.regist("zhanyiboss","mengchongboss",false,"BattleBossRed");
		this._red.regist("zhanyiboss","nvshenboss",false,"BattleBossRed");
		this._red.regist("zhanyiboss","moshenboss",false,"BattleBossRed");
		EventCenter.instance.onQue("ITEM_CHANGE",this,this.updateAll);
	}

	__proto.updateRed=function(type){
		if(!Mgr.guide.isOpen("zhanyiboss")){
			return;
		};
		var func;
		if(type==1){
			func="mingjiangboss";
		}
		else if(type==2){
			func="mengchongboss";
		}
		else if(type==3){
			func="nvshenboss";
		}
		else if(type==4){
			func="moshenboss";
		};
		var arr=this._model.getBossListByType(type);
		if(!arr)return;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var ele=arr[i];
			var cof=ele.getCfgData()
			var needId=cof.needItem;
			var needCount=cof.needCount;
			if(Mgr.bag.checkSingleItemEnough(needId,needCount)){
				this._red.showRedPoint(func,func+"red","BattleBossRed");
				return;
			}
		}
		this._red.hideRedPoint(func,func+"red","BattleBossRed");
	}

	__proto.updateAll=function(){
		this.updateRed(1);
		this.updateRed(2);
		this.updateRed(3);
		this.updateRed(4);
	}

	__proto.initSvrData=function(){
		if(!Mgr.guide.isOpen("zhanyiboss"))return;
		Mgr.battleBossAction.c_getInfo(1);
		Mgr.battleBossAction.c_getInfo(2);
		Mgr.battleBossAction.c_getInfo(3);
		Mgr.battleBossAction.c_getInfo(4);
	}

	//================副本相关===================
	__getset(0,__proto,'enterBoss',function(){
		return this._curChallengeBossInfo;
		},function(msg){
		this._curChallengeBossInfo=msg;
	});

	return BattleBossMgr;
})()


/**
*@author:huanghong
*@date:2021-5-12
*@desc:boss伤害排行Mgr
*/
//class com.xq.modules.bossDamageRank.BossDamageRankMgr
var BossDamageRankMgr=(function(){
	function BossDamageRankMgr(){
		this._model
		this._model=new BossDamageRankModel();
	}

	__class(BossDamageRankMgr,'com.xq.modules.bossDamageRank.BossDamageRankMgr');
	var __proto=BossDamageRankMgr.prototype;
	/**刷新boss伤害排行*/
	__proto.updateDamage=function(msg){
		this._model.updateDamageArr(msg);
		EventCenter.instance.event("UPDATE_BOSSODAMAGE");
	}

	/**获取攻击列表*/
	__proto.getAttacks=function(){
		var arr=this._model.getDamageRankArr();
		var len=arr.length;
		if(len==0){
			return [];
		};
		var attacks=[0];
		var isPushOwner=false;
		var dataVo;
		var rid=NaN;
		for (var i=0;i < len;i++){
			dataVo=arr[i];
			if(this.checkIsOwner(dataVo)){
				attacks[0]=dataVo;
				isPushOwner=true;
			}
			else if (!this.checkIsMe(dataVo)){
				if(attacks.length<5){
					attacks.push(dataVo);
				}
			}
			if(isPushOwner&&attacks.length>=5){
				break ;
			}
		}
		return attacks;
	}

	/**获取伤害排行*/
	__proto.getDamages=function(){
		return this._model.getDamageRankArr();
	}

	/**检测是否为归属者*/
	__proto.checkIsOwner=function(vo){
		if(!vo)return false;
		var monsterId=vo.monsterId;
		var owner=Mgr.bossOwnerM.getOwner(monsterId);
		if(owner&&owner.ownerId==vo.roleId){
			return true;
		}
		return false;
	}

	/**检测是否是我*/
	__proto.checkIsMe=function(vo){
		if(!vo)return false;
		return NetMgr.ins().roleVO.guid==vo.roleId;
	}

	__proto.checkIsEnemy=function(vo){
		var arr=Game.getInstance().player.fanjiArr;
		if(arr){
			var roleId=vo.roleId;
			var len=arr.length;
			for(var i=0;i<len;i++){
				if(roleId==arr[i].guid){
					return true;
				}
			}
			return false
		}
		else{
			return false;
		}
	}

	__proto.getMyRank=function(){
		var arr=this._model.getDamageRankArr();
		var len=arr.length;
		var vo;
		for(var i=0;i<len;i++){
			vo=arr[i];
			if(this.checkIsMe(vo)){
				return vo.rank;
			}
		}
		return 0;
	}

	return BossDamageRankMgr;
})()


