//class com.xq.modules.bossHall.gerenBoss.GerenBossMgr
var GerenBossMgr=(function(){
	function GerenBossMgr(){
		/**cfgdata*/
		this.cfgArr=null;
		/**个人boss数据*/
		this.geren=null;
		/**个人月卡boss数据*/
		this.yueka=null;
		/**个人至尊卡boss数据*/
		this.zhizun=null;
		/**周卡boss数据*/
		this.zhouka=null;
		/**闯关特权boss数据*/
		this.chuangguantequan=null;
		/**个人特权boss数据 包含了各种特权boss*/
		this.tequanBoss=null;
		/**个人boss_普通 dic*/
		this.gerenDic=null;
		/**当前选中boss的number*/
		this.curBossNum=0;
		/**是否跳转到月卡界面*/
		this.skipToYueka=false;
		this.jdMgr=null;
		/**打开面板类型 0按钮 1是其他*/
		this.openType=1;
		this.red=null;
		/**挑战的是否时普通个人boss*/
		this.isNormal=false;
		this.tzDic=null;
		this.unLockArr=null;
		this.gerenDic={};
		this.jdMgr=Mgr.jindi;
		this.geren=this.jdMgr.getAllCfgByType(5);
		this.yueka=this.jdMgr.getAllCfgByType(6);
		this.zhizun=this.jdMgr.getAllCfgByType(7);
		this.zhouka=this.jdMgr.getAllCfgByType(14);
		this.chuangguantequan=this.jdMgr.getAllCfgByType(15);
		this.tequanBoss=this.yueka.concat(this.zhizun).concat(this.zhouka).concat(this.chuangguantequan);
		this.setDic(this.gerenDic,this.geren);
		this.setDic(this.gerenDic,this.yueka);
		this.setDic(this.gerenDic,this.zhizun);
		this.setDic(this.gerenDic,this.zhouka);
		this.setDic(this.gerenDic,this.chuangguantequan);
		this.cfgArr=[];
		this.mergeData(this.geren);
		this.red=Mgr.red;
		this.red.regist("benfuboss","gerenboss",false,RedTypeEnum.BossHallRed);
		this.red.regist("benfuboss","tequanboss",false,RedTypeEnum.BossHallRed);
	}

	__class(GerenBossMgr,'com.xq.modules.bossHall.gerenBoss.GerenBossMgr');
	var __proto=GerenBossMgr.prototype;
	/**合并月卡和至尊卡boss数据*/
	__proto.mergeData=function(arr){
		var len=arr.length;
		for(var i=0;i<len;i++){
			var o=arr[i];
			this.cfgArr.push(o);
		}
	}

	/**设置boss字典*/
	__proto.setDic=function(dic,arr){
		var len=arr.length;
		for(var i=0;i<len;i++){
			var o=arr[i];
			dic[o.number]=o;
		}
	}

	/**获取最新解锁的三个boss,必须要挑战的boss 不管是否已通关*/
	__proto.setTZBoss=function(){
		if(!this.tzDic){
			this.tzDic={};
		}
		if(!this.unLockArr){
			this.unLockArr=[];
		}
		this.unLockArr.length=0;
		var curLv=NetMgr.ins().roleVO.level;
		var len=this.geren.length;
		var count=0;
		this.unLockArr.length=0;
		for(var i=len-1;i>=0;i--){
			var o=this.geren[i];
			if(o.level<=curLv){
				if(count <3){
					this.tzDic[o.number]=o;
				}
				this.unLockArr.push(o);
				count++;
			}
		}
		return this.tzDic;
	}

	__proto.getBossList=function(){
		var ary=[];
		var lenOfInfo=this.cfgArr.length;
		for (var j=0;j < lenOfInfo;j++){
			var configData=this.cfgArr[j];
			if(configData.isguide==1){
				if(configData.taskid !=Mgr.task.curTask.id2){
					continue ;
				}
			}
			ary.push(configData);
		}
		return ary;
	}

	/**检测个人boss红点*/
	__proto.checkRed=function(){
		if(!Mgr.guide.isOpen("gerenboss")){
			return;
		};
		var ary=this.getBossList();
		var len=ary.length;
		var zsLv=NetMgr.ins().roleVO.zhuanshengLevel;
		var bo=false;
		for (var i=0;i < len;i++){
			var obj=ary[i]
			if(obj.type==5){
				if(zsLv >=obj.level){
					if(!obj.isKilled){
						bo=true;
						break ;
					}
				}
			}
		}
		if(bo){
			this.red.showRedPoint("gerenboss",RedTypeEnum.GeRenBossRed,RedTypeEnum.BossHallRed);
		}
		else{
			this.red.hideRedPoint("gerenboss",RedTypeEnum.GeRenBossRed,RedTypeEnum.BossHallRed);
		}
	}

	__proto.checkTeQuanRed=function(){
		if(!Mgr.guide.isOpen("tequanboss")){
			return;
		};
		var ary=this.tequanBoss;
		var len=ary.length;
		var bo=false;
		for (var i=0;i < len;i++){
			var obj=ary[i]
			if(obj.type==6){
				if(Mgr.chaoZhiTeDianMgr.isBuyYk){
					if(!obj.isKilled){
						bo=true;
						break ;
					}
				}
			}
			else if(obj.type==7){
				if(Mgr.chaoZhiTeDianMgr.isBuyZz){
					if(!obj.isKilled){
						bo=true;
						break ;
					}
				}
			}
		}
		if(bo){
			this.red.showRedPoint("tequanboss",RedTypeEnum.TeQuanBossRed,RedTypeEnum.BossHallRed);
		}
		else{
			this.red.hideRedPoint("tequanboss",RedTypeEnum.TeQuanBossRed,RedTypeEnum.BossHallRed);
		}
	}

	return GerenBossMgr;
})()


