	/**
	*根据BOSS类型获得BOSS数组(移除体验本)
	**/
	__proto.getBossListWithoutTiYan=function(bossType){
		var bossArr=[];
		var dc=this.getJindiBossDC().where("type",bossType,"number");
		var arr=dc.array;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var ele=arr[i];
			var cof=ele.getCfgData();
			if(!cof.isguide){
				bossArr.push(ele);
			}
		}
		return bossArr;
	}

	/**三界boss排序方式*/
	__proto.compareSanjie=function(ele1,ele2){
		return ele1.sortIndex-ele2.sortIndex;
	}

	__proto.sortSanJie=function(){
		var arr=Mgr.jindi.getBossList(11);
		var len=arr.length;
		var myZsLv=NetMgr.ins().roleVO.zhuanshengLevel;
		var ele;
		var cof;
		for(var i=0;i<len;i++){
			ele=arr[i];
			if(ele){
				cof=ele.getCfgData();
				if(myZsLv>cof.level){
					ele.sortIndex=200+parseInt(cof.level);
				}
				else if(myZsLv<cof.level){
					ele.sortIndex=100+parseInt(cof.level);
				}
				else{
					ele.sortIndex=parseInt(cof.level);
				}
			}
		}
		arr=arr.sort(this.compareSanjie);
		return arr;
	}

	/**获取禁地boss配置表数组*/
	__proto.getJinDiCfg=function(){
		return this.jindiCfg;
	}

	/**
	*处理后端发送过来的数据
	**/
	__proto.onReceiveBossListSC=function(msg){
		this.getJindiBossDC();
		this._serverMsgDic[msg.type]=msg;
		var infos=msg.infos;
		var len=infos.length;
		var ele;
		for (var i=0;i < len;i++){
			var bossMsg=infos[i];
			ele=this._jdBossDC.getElement(bossMsg.id);
			if(ele){
				ele.setValue("M",bossMsg);
			}
			else{
				this.updateTaskData(bossMsg);
			}
		};
		var tixinIds=msg.bossIdList;
		len=tixinIds.length;
		for (var j=0;j < tixinIds;j++){
			var numId=tixinIds[j];
			ele=this._jdBossDC.getElement(numId);
			if(ele){
				ele.setValue("N",true);
			}
		}
	}

