	__proto.updateTaskData=function(msg){
		var ele;
		var id=msg.id;
		for(var i in this._taskBossDic){
			ele=this._taskBossDic[i];
			if(ele.getCfgData().number==id){
				ele.setValue("M",msg);
			}
		}
	}

