	/**检测世界Boss红点*/
	__proto.checkWorldRed=function(){
		if(!Mgr.guide.isOpen("worldboss")){
			return;
		}
		if(this.getChanllengeTimes(2)<=0){
			this.red.hideRedPoint("worldboss",RedTypeEnum.WorldBossRed,RedTypeEnum.BossHallRed);
			return;
		};
		var ary=this.getBossList(2);
		var len=ary.length;
		var bo=false;
		var zsLv=NetMgr.ins().roleVO.zhuanshengLevel
		for (var i=0;i < len;i++){
			var obj=ary[i];
			var cfg=obj.getCfgData();
			if(zsLv >=parseInt(cfg.level)){
				var serInfo=obj.getValue("M");
				if(serInfo && serInfo.isKillded==false){
					bo=true;
					break ;
				}
			}
		}
		if(bo){
			this.red.showRedPoint("worldboss",RedTypeEnum.WorldBossRed,RedTypeEnum.BossHallRed);
		}
		else{
			this.red.hideRedPoint("worldboss",RedTypeEnum.WorldBossRed,RedTypeEnum.BossHallRed);
		}
	}

	/**检测秘境boss*/
	__proto.checkMjRed=function(){
		if(!Mgr.guide.isOpen("hongzhuangboss")){
			return;
		}
		this.mjType=MiJingBossMgr.BOSSTYPEARR;
		var bo=false;
		var zsLv=NetMgr.ins().roleVO.zhuanshengLevel;
		for (var i=0;i < 4;i++){
			var curType=this.mjType[i];
			var count=0;
			count=this.hasSYCount;
			var key=RedTypeEnum.MiJingBossRed+"_"+curType;
			this.red.hideRedPoint("hongzhuangboss",key,RedTypeEnum.MiJingBossRed);
			if(count > 0){
				var cfgAry=Mgr.mijing.getBossDataByType(curType);
				var len=cfgAry.length;
				for (var j=0;j < len;j++){
					var obj=cfgAry[j]
					if(zsLv >=obj.level){
						if(Mgr.bossRefreshMgr.checkBossAlive(obj.monsterid)){
							bo=true;
							this.red.showRedPoint("hongzhuangboss",key,RedTypeEnum.MiJingBossRed);
							break ;
						}
					}
				}
			}
		}
		if(bo){
			this.red.showRedPoint("hongzhuangboss",RedTypeEnum.MiJingBossRed,RedTypeEnum.BossHallRed);
		}
		else{
			this.red.hideRedPoint("hongzhuangboss",RedTypeEnum.MiJingBossRed,RedTypeEnum.BossHallRed);
		}
	}

