	__proto.updateHuiFuTili=function(msg){
		var time=msg.nextRecoverTime;
		var bossType=msg.type;
		var curTime=Mgr.curTime.serverTimer;
		if(time>curTime){
			switch(bossType){
				case 2:{
						Laya.timer.once((time-curTime),this,this.onWorldHuiFu);
						break ;
					}
				case 1:
				case 3:
				case 10:
				case 4:
				case 16:
				case 17:
				case 18:
				case 19:
				case 20:
				case 21:
				case 22:{
						Laya.timer.once((time-curTime),this,this.onWorldHuiFu);
						break ;
					}
				}
		}
	}

