//class com.xq.modules.bossHall.mijingBoss.MiJingBossMgr
var MiJingBossMgr=(function(){
	function MiJingBossMgr(){}
	__class(MiJingBossMgr,'com.xq.modules.bossHall.mijingBoss.MiJingBossMgr');
	var __proto=MiJingBossMgr.prototype;
	/**根据类型获取配置数据*/
	__proto.getBossDataByType=function(type){
		var arr=Mgr.jindi.getAllCfgByType(type);
		var len=arr.length;
		var newArr=[];
		for (var i=0;i < len;i++){
			var jdCfg=arr[i];
			if(jdCfg.isguide==1){
				if(jdCfg.taskid !=Mgr.task.curTask.id2){
					continue ;
				}
			}
			newArr.push(jdCfg);
		}
		return newArr;
	}

	__proto.getAttackPlayerArr=function(msg){
		var rankArr=msg.rankMsg.concat();
		var len=rankArr.length;
		var arr=[];
		var myRid=NetMgr.ins().roleVO.guid;
		var myRidIdx=-1;
		var guishuId=Mgr.jindi.bossOwnVo?Mgr.jindi.bossOwnVo.ownerId:0;
		var data;
		var rid=NaN;
		for (var j=0;j < len;j++){
			data=rankArr[j];
			rid=data.roleId;
			if(rid==guishuId){
				data["isGuiShu"]=true;
				arr.push(data);
			}
			data["isE"]=this.ifE(rid);
			if(rid==myRid){
				myRidIdx=j;
			}
		}
		if(myRidIdx!=-1)
			rankArr.splice(myRidIdx,1);
		for(var i=0;i < 5;i++){
			data=rankArr[i];
			if(data && !data["isGuiShu"]){
				arr.push(rankArr[i]);
			}
		}
		return arr;
	}

	__proto.ifE=function(roleId){
		var arr=Game.getInstance().player.fanjiArr;
		if(arr){
			var len=arr.length;
			for(var i=0;i<len;i++){
				if(roleId==arr[i].guid){
					return true;
				}
			}
			return false;
		}
		else{
			return false;
		}
	}

	/**根据秘境boss类型 获取对应页签下标*/
	__proto.getSeleceIndex=function(bossType){
		return MiJingBossMgr.BOSSTYPEARR.indexOf(bossType);
	}

	/**根据下标 获取对应boss类型*/
	__proto.getBossType=function(index){
		return MiJingBossMgr.BOSSTYPEARR[index];
	}

	/**根据自身转生排序*/
	__proto.compareByZS=function(a,b){
		var cof1=a.getCfgData();
		var cof2=b.getCfgData();
		var zsLv=NetMgr.ins().roleVO.zhuanshengLevel;
		var flag1=cof1.level>zsLv;
		var flag2=cof2.level>zsLv;
		if(flag1&&!flag2){
			return 1;
		}
		else if(!flag1&&flag2){
			return-1;
		}
		else if(!flag1&&!flag2){
			if(cof1.level>cof2.level){
				return-1;
			}
			if(cof1.level<cof2.level){
				return 1;
			}
			return cof1.number-cof2.number;
			}else{
			return cof1.level-cof2.level;
		}
	}

	__static(MiJingBossMgr,
	['BOSSTYPEARR',function(){return this.BOSSTYPEARR=[1,
		3,
		10,
		4,
		16,
		17,
		18,
		19,
		20,
		21,
		22,];}
	]);
	return MiJingBossMgr;
})()


