	__proto.hideVIPRed=function(){
		this.closeIcon();
		var len=this.buyRecordList.length;
		for (var i=0;i < len;i++){
			if(this.buyRecordList[i].buyCount > 0){
				this.red.showRedPoint("VipLiBao","redviplb","ChaoZhiLiBao");
				return;
				}else{
				this.red.hideRedPoint("VipLiBao","redviplb","ChaoZhiLiBao");
			}
		}
	}

	/**关闭主界面图标*/
	__proto.closeIcon=function(){
		var vipLb=false;
		if(this.buyRecordList){
			var len=this.buyRecordList.length;
			for (var i=0;i < len;i++){
				if(this.buyRecordList[i].buyCount <=0){
					vipLb=true;
				}
			}
			}else{
			vipLb=true;
		}
		if(this.xslbBuyNum <=0 && vipLb){
			EventCenter.instance.event("ACTIVE_TOGGLE",["ChaoZhiLiBao"]);
		}
	}

	ChaoZhiLiBaoMgr.XSLB_INFO="XSLB_INFO";
