//class com.xq.modules.comp.CompMgr
var CompMgr=(function(){
	function CompMgr(){
		this._model=null;
		/**成 初始选择页签*/
		this.openSelect=-1;
		this.red=null;
		this.compRed=null;
		this.ZHANWENCOUNT=3;
		this.nextRedTabArr=null;
		this._model=new CompModel();
		this.initAccordData();
		this.compRed={};
		this.registRed();
		EventCenter.instance.on("ITEM_CHANGE",this,this.checkTab);
		EventCenter.instance.on("MAIN_PLAYER_ATTRIBUTE_CHANGE",this,this.initAccordData);
	}

	__class(CompMgr,'com.xq.modules.comp.CompMgr');
	var __proto=CompMgr.prototype;
	__proto.registRed=function(){
		this.red=Mgr.red;
		this.red.regist("beibao","compAndBreak",true,RedTypeEnum.Bag);
		this.red.regist("compAndBreak","hecheng",false,RedTypeEnum.Bag);
	}

	__proto.initAccordData=function(){
		this._model.initAccordData();
	}

	__proto.getArr=function(supertype,tabInx){
		return this._model.getArrBySuperTypeAndTab(supertype,tabInx);
	}

	/**获取合成数据字典*/
	__proto.getTypeDic=function(){
		return this._model.getTypeDic();
	}

	/**获取合成数据数组*/
	__proto.getTypeArr=function(){
		return this._model.getTypeArr();
	}

	/**根据tab获取对应index*/
	__proto.getIndexByTab=function(tab){
		return this._model.getIndexByTab(tab);
	}

	/**
	*检测单个render
	*/
	__proto.checkRender=function(o){
		return Mgr.bag.checkItemIsEnough(o.compound);
	}

	/**
	*检测文件夹
	*/
	__proto.checkFolder=function(node){
		var init=false;
		var inx=-1;
		var o=node.data;
		var arr=this.getArr(o.supertype,o.tab);
		for (var i=0;i < arr.length;i++){
			var obj=arr[i];
			if(!obj)
				continue ;
			if (this.checkRender(arr[i])){
				if(!this.compRed[ obj.tab+""]){
					this.compRed[ obj.tab+""]=obj.xiaolei;
					}else{
					if(obj.xiaolei < this.compRed[ obj.tab+""]){
						this.compRed[ obj.tab+""]=obj.xiaolei;
					}
				}
				this.red.showRedPoint("hecheng",obj.supertype+"-"+obj.tab+"-"+obj.xiaolei,RedTypeEnum.Comp);
				if (!init){
					inx=i;
					init=true;
				}
			}
			else{
				this.red.hideRedPoint("hecheng",obj.supertype+"-"+obj.tab+"-"+obj.xiaolei,RedTypeEnum.Comp);
			}
		}
		if (!init){
			inx=-1;
			init=true;
		}
		return inx;
	}

	/**
	*检测surpertype标签
	*/
	__proto.checkTab1=function(node){
		var tempArr={};
		var obj=node.data;
		var arr=node.tabArr;
		for (var i=0;i < arr.length;i++){
			var node1=arr[i];
			var idx=this.checkFolder(node1);
			if (idx !=-1){
				this.red.showRedPoint("hecheng",node1.data.supertype+"-"+node1.data.tab,RedTypeEnum.Comp);
				var tab1Arr=[];
				tab1Arr[0]=i;
				tab1Arr[1]=idx;
				tempArr[node1.data.tab+""]=tab1Arr;
			}
			else{
				this.red.hideRedPoint("hecheng",node1.data.supertype+"-"+node1.data.tab,RedTypeEnum.Comp);
			}
		}
		return tempArr;
	}

	/**
	*typeArr
	*检测合成页签
	*/
	__proto.checkTab=function(){
		if(!Mgr.guide.isOpen("hecheng"))return;
		this.nextRedTabArr={};
		var typeArr=this.getTypeArr();
		for (var i=0;i < typeArr.length;i++){
			var node=typeArr[i];
			var redTypeArr=this.checkTab1(node);
			if(JSON.stringify(this.nextRedTabArr)==='{}'){
				this.nextRedTabArr=redTypeArr;
			}
		}
	}

	/**设置合成 初始选择页签*/
	__getset(0,__proto,'setCompSelect',null,function(value){
		this.openSelect=value;
	});

	__getset(0,__proto,'curCompSelect',function(){
		return this.openSelect;
	});

	return CompMgr;
})()


