/**
*战斗力日志
*@author zhanglimin
*@date 2020-4-30
**/
//class com.xq.modules.console.PowerLogMgr
var PowerLogMgr=(function(){
	function PowerLogMgr(){
		this._recordId=0;
		this.powerKey="powerKey";
		/**比较战力2百万*/
		this.gapPower=2000000
	}

	__class(PowerLogMgr,'com.xq.modules.console.PowerLogMgr');
	var __proto=PowerLogMgr.prototype;
	/**战斗力发生改变*/
	__proto.changePower=function(_power){
		if(_power > 0 && this._recordId > 0){
			this.comparePower(_power);
			LocalStorage.setItem(this.powerKey,_power.toString());
		}
	}

	/**比较战力。战力减少向后端发送战力日志*/
	__proto.comparePower=function(_pow){
		var oldPower=parseFloat(LocalStorage.getItem(this.powerKey));
		if(!oldPower || oldPower <=0)
			return;
		if(oldPower-_pow >=this.gapPower){
			var obj=Mgr.power.getPowerObj(this._recordId);
			if(obj){
				var str="对比前的战力="+oldPower+"</br>";
				for (var type in obj){
					str+="枚举ID= "+type+" 战斗力= "+obj[type]+"</br>";
				}
			}
		}
		if(str){
			laya.xq.cfg.reportOneBug("战斗力日志",new Error("战斗力日志:"+str));
		}
	}

	__getset(1,PowerLogMgr,'ins',function(){
		return PowerLogMgr._ins=PowerLogMgr._ins|| new PowerLogMgr();
	});

	PowerLogMgr._ins=null;
	return PowerLogMgr;
})()


