	/**获取有次数的VIP等级*/
	__proto.getVPLv=function(){
		var lp=NetMgr.ins().roleVO.vipLevel;
		var lv=-1;
		var oldC=Mgr.vipcfgMgr.getCLCount(lp);
		while(lv <=0 && lp < 15){
			if(Mgr.vipcfgMgr.getCLCount(lp+1)> oldC){
				lv=lp+1;
			}
			else
			lp=lp+1;
		}
		if(lp >=15)
			return-1
		return lv;
	}

	/**
	*根据次数获取花费
	*/
	__proto.getCCcost=function(id,type){
		var msg=Mgr.copy.getSyCt(id);
		if(msg){
			var c=msg.maxCount+1;
		}
		if(!c)
			return 0;
		var tu=c+":"+type;
		while(!this.ccCah[tu]){
			this.ccCah[tu]=this.cccfig.getCfgMsgByTwoKey("count",c,"type",type);
			c--;
			if(c <=-1){
				break ;
			}
		};
		var ob=this.ccCah[tu]
		if(ob)
			return parseInt(ob.cost);
		return 0;
	}

	__proto.checkRedMt=function(vo){
		var alreadyChallenge={};
		this.saoDangState=0;
		var yuanBaoNum=NetMgr.ins().roleVO.yuanbao;
		var challengeArr=vo.coungMsgs;
		var len1=challengeArr.length;
		for (var j=0;j < len1;j++){
			var msgc=challengeArr[j];
			alreadyChallenge[msgc.id]=msgc.count;
		};
		var saoDangInfo={};
		var saoDangArr=vo.saoDangmsgs;
		var len2=saoDangArr.length;
		for (var k=0;k < len2;k++){
			var msg=saoDangArr[k];
			saoDangInfo[saoDangArr[k].mainId]=msg.ynCount+msg.vipCount+msg.svipCount;
		};
		var len=this.materialArr.length;
		for (var i=0;i < len;i++){
			var materialTab=this.materialArr[i];
			var ary=this.checkOpen(materialTab.limit,materialTab.value)
			var isOpen=ary[0];
			if(isOpen && materialTab.value1){
				ary=this.checkOpen(materialTab.limit1,materialTab.value1);
				isOpen=ary[0];
			}
			if(isOpen){
				if(alreadyChallenge[materialTab.mainid]>0){
					this.materialDic[materialTab.mainid]=1;
				}
				else if(saoDangInfo[materialTab.mainid] >0){
					var tb=Mgr.copy.getmCpyInfo(materialTab.mainid)
					var m=Mgr.copy.getCCcost(materialTab.mainid,tb.type);
					if(m > yuanBaoNum){
						this.materialDic[materialTab.mainid]=3;
						}else{
						yuanBaoNum-=m;
						this.materialDic[materialTab.mainid]=2;
					}
				}
				else{
					this.materialDic[materialTab.mainid]=0;
				}
			}
			else{
				this.materialDic[materialTab.mainid]=0;
			}
		}
		this.refreshMaterialRed();
	}

	/**检测材料副本开启*/
	__proto.checkOpen=function(limt,limtVal){
		var lv=0;
		var hint="";
		if(limt==0){
			var ary=limtVal.split(";");
			var len=ary.length;
			for (var i=0;i < len;i++){
				var tp=ary[i].split(":");
				var bo=this.getOpenState(tp[0],tp[1]);
				if(bo){
					return [true,""];
				}
				else{
					hint+=this.getTipStr(parseInt(tp[0]),tp[1])+"或";
				}
			}
		}
		else{
			bo=this.getOpenState(limt,limtVal);
			if(bo)
				return [true,""];
			else{
				hint+=this.getTipStr(parseInt(limt),limtVal)+"或";
			}
		}
		hint=hint.substring(0,hint.length-1);
		hint+="开启"
		return [false,hint];
	}

	__proto.getOpenState=function(type,value){
		var vis=false
		if(type==1){
			var lv=NetMgr.ins().roleVO.level;
			if(lv >=value)
				vis=true
		}
		else if(type==2){
			var bo=Mgr.task.curTask.state==2
			if((Mgr.task.curTask.id2==value && bo)){
				vis=true;
				}else if(Mgr.guide.taskModel.compareTaskId(Mgr.task.curTask.id2,value)){
				vis=true;
			}
		}
		else if(type==4){
			lv=CommonUtil.openServerDay;
			if(lv >=value)
				vis=true
		}
		else if(type==5){
			if(Mgr.gqMgr.gqInfo){
				lv=Mgr.gqMgr.gqInfo.nextLevel-1;
			}
			else{
				lv=100;
			}
			if(lv >=value)
				vis=true
		}
		else if(type==6){
			lv=NetMgr.ins().roleVO.vipLevel;
			if(lv >=value)
				vis=true
		}
		return vis
	}

	__proto.getTipStr=function(limit,value){
		if(limit==2){
			var tempVo=Mgr.task.getTaskVoById(value);
			if(tempVo){
				return "完成任务【"+tempVo.name2+"】后";
			}
		}
		else if(limit==4){
			return "开服"+value+"天后"
		}
		else if(limit==5){
			return "关卡达到"+value+"关后";
		}
		else if(limit==6){
			return "Svip达到"+value+"级后"
		}
		return ""
	}

