/**
*红颜考验逻辑类
*@author zhanglimin
*@date 2019-12-9
*/
//class com.xq.modules.copy.meirenguan.MeiRenGuanMgr
var MeiRenGuanMgr=(function(){
	function MeiRenGuanMgr(){
		this.queGoodCfg=null;
		/**每天免费次数*/
		this.freeTimes=0;
		/**每天购买次数*/
		this.buyTimes=0;
		/**购买次数消耗元宝*/
		this.buyMonAry=null;
		/**最多能在副本呆的时间*/
		this.maxTime=0;
		/**奖励展示*/
		this.rewardShow=null;
		/**特殊奖励层数*/
		this.specialGoodsLayerArr=[];
		this.queGoodCfg=CfgManager.getTableCfg("queengood");
		var arr=this.queGoodCfg.objectDataArray;
		var len=arr.length;
		for(var i=0;i< len;i++){
			var o=arr[i];
			if(o.specialReward){
				this.specialGoodsLayerArr.push(o.layer);
			}
		};
		var tempCfg=CfgManager.getTableCfg("queenconfig");
		var obj=tempCfg.objectDataArray[0]
		this.freeTimes=parseInt(obj.freeTimes);
		this.buyTimes=parseInt(obj.buyTimes);
		this.buyMonAry=obj.buyCost.split(";");
		this.maxTime=parseInt(obj.time);
		this.rewardShow=obj.rewardShow.split(";");
	}

	__class(MeiRenGuanMgr,'com.xq.modules.copy.meirenguan.MeiRenGuanMgr');
	var __proto=MeiRenGuanMgr.prototype;
	__proto.getNextSpecialLayerByAlreadyGetArr=function(speRewardAry){
		var len=speRewardAry.length;
		var maxGet=0;
		for(var i=0;i < len;i++){
			maxGet=Math.max(maxGet,speRewardAry[i]);
		}
		len=this.specialGoodsLayerArr.length;
		for(i=0;i < len;i++){
			if(maxGet < this.specialGoodsLayerArr[i]){
				return this.specialGoodsLayerArr[i]
			}
		}
		return 0;
	}

	__proto.getCfgByLayer=function(lay){
		return this.queGoodCfg.getItemByField("layer",lay);
	}

	/**获取跳关时间断*/
	__proto.getTimes=function(obj){
		var ary=[];
		if(obj.jumpTime1 > 0){
			ary.push(obj.jumpTime1,obj.jumpLayer1);
		}
		if(obj.jumpTime2 > 0){
			ary.push(obj.jumpTime2,obj.jumpLayer2);
		}
		if(obj.jumpTime3 > 0){
			ary.push(obj.jumpTime3,obj.jumpLayer3);
		}
		return ary;
	}

	/**世界邀请*/
	__proto.sendRespInvition=function(id){
		if(!Mgr.guide.isOpen("meiRenGuan")){
			Mgr.prompt.optionPrompt("尚未开启红颜考验副本");
			return;
		}
		Mgr.teamAct.reqAcceptInvite(TeamEnum.NvShen,id,Handler.create(this,this.onRespInVition));
		console.log("发送接收红颜考验邀请~");
	}

	// Mgr.inoutMap.check(Handler.create(this,this.checkRespInvition,[id]));
	__proto.checkRespInvition=function(id){
		Mgr.teamAct.reqAcceptInvite(TeamEnum.NvShen,id,Handler.create(this,this.onRespInVition));
	}

	__proto.onRespInVition=function(teamType){
		if(teamType==TeamEnum.NvShen){
			UIMgrR.openSecIView(com.xq.view.modules.singleCopy.ICopyFrameView,1,1,1);
		}
	}

	/**红颜副本信息数据*/
	__proto.initFightVo=function(fightVo){
		fightVo.hideAry=[2,3,4];
		fightVo.aniType=2;
		fightVo.closeFun=Handler.create(Mgr.mrgAct,Mgr.mrgAct.reqExit,null,false);
		fightVo.remainTime=(this.maxTime *1000)
		fightVo.curFloor=1;
	}

	return MeiRenGuanMgr;
})()


