//class com.xq.modules.danyao.FuHunVo
var FuHunVo=(function(){
	function FuHunVo(fuhunType){
		this._fuhunType=0;
		/**附魂类型字典*/
		this.typeCfgDic={};
		/**附魂子类型限制配置字典*/
		this.idCfgLimitDic={};
		/**附魂的服务器数据字典*/
		this.serverInfoDic={};
		/**附魂类型数组*/
		this._typeArr=[];
		this._fuhunType=fuhunType;
	}

	__class(FuHunVo,'com.xq.modules.danyao.FuHunVo');
	var __proto=FuHunVo.prototype;
	/**设置来自服务器的数据*/
	__proto.setServerMsg=function(msg){
		this.serverInfoDic[ msg.danYaoType+"_"+msg.type]=msg;
	}

	/**设置附魂类型数据*/
	__proto.setTypeCfg=function(type,data){
		if(!this.typeCfgDic[type]){
			this._typeArr.push(type);
		}
		this.typeCfgDic[type]=data;
	}

	/**设置附魂子类型限制配置数据*/
	__proto.setIdLimitCfg=function(id,lv,data){
		var lvDic=this.idCfgLimitDic[id];
		if(!lvDic){
			lvDic={};
			this.idCfgLimitDic[id]=lvDic;
		}
		lvDic[lv]=data;
		var lastLv=lvDic["maxLevel"];
		var ylv=parseInt(lv);
		var llv=parseInt(lastLv);
		if(ylv){
			if(!llv || ylv > llv){
				lvDic["maxLevel"]=lv;
			}
			}else{
			if(!lastLv || lv>lastLv){
				lvDic["maxLevel"]=lv;
			}
		}
	}

	/**获取附魂子类型最大等级*/
	__proto.getLimitMaxLevel=function(danyaoType,id){
		var lvDic=this.idCfgLimitDic[id];
		if(lvDic){
			var o=lvDic[lvDic["maxLevel"]];
			var arr=o.qiannengdan;
			return arr[danyaoType-1];
		}
		return 0;
	}

	/**获取附魂子类型当前限制等级*/
	__proto.getLimitLevel=function(danyaoType,id,lv){
		var lvDic=this.idCfgLimitDic[id];
		if(lvDic){
			var o=lvDic[lv];
			if(o){
				var arr=o.qiannengdan;
				return arr[danyaoType-1];
			}
		}
		return 0;
	}

	__proto.getShowMaxUseNum=function(jieJi){
		return Mgr.fuhun.getFuHunJieJiData().getElement(jieJi+"").getCfgData().number;
	}

	/**获取附魂类型数据*/
	__proto.getTypeCfg=function(type){
		return this.typeCfgDic[type];
	}

	/**获取服务器数据*/
	__proto.getServerMsg=function(dyType,funcType){
		return this.serverInfoDic[dyType+"_"+funcType];
	}

	/**获取指定id的丹药总战力*/
	__proto.getTotalFightByTypeId=function(fuhunType){
		var totalFight=0;
		var len=this.typeArr.length;
		for(var i=0;i< len;i++){
			var dyType=this.typeArr[i];
			var msg=this.getServerMsg(dyType,fuhunType);
			if(msg){
				totalFight+=msg.fightValue;
			}
		}
		return totalFight;
	}

	__proto.getAllServerMsg=function(){
		return this.serverInfoDic;
	}

	/**附魂类型字典*/
	__getset(0,__proto,'typeArr',function(){
		return this._typeArr;
	});

	__getset(0,__proto,'fuhunType',function(){
		return this._fuhunType;
	});

	return FuHunVo;
})()


