//class com.xq.modules.drop.DropGoodsMgr
var DropGoodsMgr=(function(){
	function DropGoodsMgr(){
		this.cfgData=null;
		this.scene=null;
		this.pickTime=2000;
		this.mainPlayer=null;
		this.ownGoods=[];
		this.allDrops=[];
		this.allDropsDic={};
		this.tempDrops=[];
		this.cfgData=CfgManager.getTableCfg("DaoJuBiao");
		EventCenter.instance.on("SCENE_DROP_GOODS",this,this.drop);
	}

	__class(DropGoodsMgr,'com.xq.modules.drop.DropGoodsMgr');
	var __proto=DropGoodsMgr.prototype;
	__proto.drop=function(vo){
		if(!this.mainPlayer)
			this.mainPlayer=Game.getInstance().player;
		if(this.ownGoods.length > 60)
			this.pickALL(null);
		var goodsArr=vo.elements;
		var len=goodsArr.length;
		var dropGoodsArr=[];
		this.allDrops.concat(goodsArr);
		for(var i=0;i<len;i++){
			var item=goodsArr [i];
			FrameSmooth.add(Handler.create(this,this.createDropGoods,[item]));
		}
		FrameSmooth.add(Handler.create(this ,this.beginPickTimer));
	}

	__proto.beginPickTimer=function(){
		Laya.timer.once(this.pickTime,this,this.pickDrops,[this.tempDrops.concat()],false);
		this.tempDrops.length=0;
	}

	/**拾取所有物品*/
	__proto.pickDrops=function(dropArr){
		var len=dropArr.length;
		for(var i=0;i<len;i++){
			var drop=dropArr[i];
			if(drop.vo.ownerId==this.mainPlayer.guid){
				drop.showFlyAni();
			}
			else{
				drop.dispose(false);
			}
		}
	}

	//Laya.timer.once(time,this,pickUp,[drop],false);
	__proto.createDropGoods=function(item){
		if(!this.mainPlayer)
			this.mainPlayer=Game.getInstance().player;
		if(this.mainPlayer){
			var fromUnit=UnitManager.ins.unitList.get(item.monsterId);
			var drop=new DropGoods(item,this.mainPlayer,fromUnit);
			if(!this.scene)
				this.scene=SceneContainer.getInstance();
			this.scene.bottomLayer.addChild(drop);
			this.tempDrops.push(drop);
			if(item.ownerId==this.mainPlayer.guid)
				this.ownGoods.push(drop);
		}
		return drop;
	}

	__proto.pickALL=function(callback){
		var len=this.ownGoods.length;
		for(var i=0;i<len;i++){
			FrameSmooth.add(Handler.create(this,this.disposeDrop,[this.ownGoods[i],true]));
		}
		this.ownGoods.length=0;
		if(callback){
			FrameSmooth.add(callback);
		}
	}

	__proto.disposeDrop=function(item,flag){
		item.dispose(flag);
	}

	return DropGoodsMgr;
})()


