		var slotFV=0;
		var partFV=0;
		for (var i=0;i < len;i++){
			gemId=gemIdArr[i];
			if (gemId==""){
				continue ;
			};
			var cfgLineMsg=this._model.getGemCofById(gemId);
			if (cfgLineMsg.hitpoints !="0"){
				slotFV=parseInt(Mgr.item.fightValueByFactor("hitpoints",parseInt(cfgLineMsg.hitpoints)));
				partFV+=slotFV;
			}
			else if (cfgLineMsg.physicdamage !="0"){
				slotFV=parseInt(Mgr.item.fightValueByFactor("physicdamage",parseInt(cfgLineMsg.physicdamage)));
				partFV+=slotFV;
			}
			else if (cfgLineMsg.physicdefence !="0"){
				slotFV=parseInt(Mgr.item.fightValueByFactor("physicdefence",parseInt(cfgLineMsg.physicdefence)));
				partFV+=slotFV;
			}
		}
		return partFV.toString();
