//class com.xq.modules.equip.StrenAndStarMgr
var StrenAndStarMgr=(function(){
	function StrenAndStarMgr(){
		/**
		*全局配置表
		*/
		this.quanjuCfg=null;
		/**
		*升星附魂表
		*/
		this.fuHunCfg=null;
		/**
		*装备表
		*/
		this.equipCfg=null;
		/**
		*升星表
		*/
		this.starCfg=null;
		/**
		*升星概率表
		*/
		this.starRateCfg=null;
		/**
		*升星最大等级
		*/
		this.starMaxLv=0;
		/**
		*是否可以强化
		**/
		this.canStrengh=false;
		/**
		*是否可以升星
		*/
		this.canUpStar=false;
		/**
		*升星附魂配数据容器
		*/
		this.fuHunData=null;
		this.red=null;
		this.maxStar=0;
		/**
		*组装升星和强化数据
		*/
		this.enhanceDic=null;
		this.starDic=null;
		/**
		*升星的失败次数
		*/
		this.failCount=0;
		this.red=Mgr.red;
		this.quanjuCfg=CfgManager.getTableCfg("Config");
		this.equipCfg=CfgManager.getTableCfg("ZhuangBeiBiao");
		this.starCfg=CfgManager.getTableCfg("ZhuangBeiShengXingShuXingBiao");
		this.starRateCfg=CfgManager.getTableCfg("ZhuangBeiShengXingRate");
		this.fuHunCfg=CfgManager.getTableCfg("shengxingfuhun");
		this.maxStar=parseInt(this.quanjuCfg.getItemByField("type",178).value);
		this.starMaxLv=this.starRateCfg.objectDataArray.length;
		this.red.regist("duanZao","dzqianhua",true,RedTypeEnum.ForgeRed);
		this.red.regist("duanZao","dzshengxing",true,RedTypeEnum.ForgeRed);
		EventCenter.instance.onQue("ITEM_CHANGE" ,this,this.onBagChangeRefreshEnhanceRed);
		EventCenter.instance.onQue("LEVEL_UP",this,this.onBagChangeRefreshEnhanceRed);
		this.getFuHunData();
	}

	__class(StrenAndStarMgr,'com.xq.modules.equip.StrenAndStarMgr');
	var __proto=StrenAndStarMgr.prototype;
	__proto.getFuHunData=function(){
		if(!this.fuHunData){
			this.fuHunData=new DataContainer();
			var cfgArr=this.fuHunCfg.objectDataArray;
			var len=cfgArr.length;
			for (var i=0;i < len;i++){
				var cfg=cfgArr[i];
				if(cfg){
					var ele=new DataElement(cfg);
					this.fuHunData.addElement(cfg.danyaotype,ele);
				}
			}
		}
		return this.fuHunData;
	}

	__proto.isUnlock=function(star,unlockArr){
		var starDic=Mgr.equip.curModel.starDic;
		var len=unlockArr.length;
		for (var i=1;i < len;i++){
			if(!starDic[unlockArr[i]] || starDic[unlockArr[i]].starLv < star){
				return false;
			}
		}
		return true;
	}

	/**背包物品改变刷新强化和升星红点*/
	__proto.onBagChangeRefreshEnhanceRed=function(){
		var heroAry=Mgr.subPlayer.getHeroHeadList();
		var len=heroAry.length;
		for (var i=0;i < len;i++){
			var tempVo=heroAry[i];
			if(!tempVo)
				continue ;
			this.checkStrenUp(Mgr.equip.getModelbyRoleId(tempVo.roleId));
			this.checkStarUp(Mgr.equip.getModelbyRoleId(tempVo.roleId));
		}
	}

	__proto.assembly=function(list,roleId){
		var equipModel=Mgr.equip.getModelbyRoleId(roleId);
		equipModel.enhanceDic={};
		equipModel.starDic={};
		var len=list.length;
		for (var i=0;i < len;i++){
			var listVO=list[i];
			var e=equipModel.wearEquipDic[listVO.pos];
			if (!e)continue ;
			var pos=listVO.pos;
			var level=listVO.level;
			var starLv=listVO.starLevel;
			e.strengthLv=level;
			e.starLevel=starLv;
			var strenVO=this.createStrenVO(pos,level,e,listVO.show);
			equipModel.enhanceDic[listVO.pos]=strenVO;
			var starVO=this.createStarVO(pos,starLv,e,listVO.failCount);
			equipModel.starDic[listVO.pos]=starVO;
		}
		equipModel.enhanceLv=this.getAllStrenLv();
		equipModel.starFv=this.getAllStarFV();
		this.checkR(equipModel);
	}

	__proto.checkR=function(equipModel){
		this.checkStarUp(equipModel);
		this.checkStrenUp(equipModel);
		EventCenter.instance.event("EQUIP_PART_STREN_LIST");
		EventCenter.instance.event("EQUIP_PART_STAR_LIST");
	}

	__proto.allStren=function(arr){
		for (var i=0;i < arr.length;i++){
			var vo=arr[i];
			var e=Mgr.equip.curModel.wearEquipDic[vo.pos];
			if (!e)continue ;
			var pos=vo.pos;
			var level=vo.level;
			var starLv=vo.starLevel;
			e.strengthLv=level;
			var strenVO=this.createStrenVO(pos,level,e,vo.show);
			if(strenVO){
				Mgr.equip.curModel.enhanceDic[pos]=strenVO;
			}
		}
		this.checkStrenUp(Mgr.equip.curModel);
		EventCenter.instance.event("ALL_STREN");
	}

	/**
	*获取全身强化等级
	*/
	__proto.getAllStrenLv=function(){
		var lv=0;
		var model;
		for(var $each_model in Mgr.equip.getModelDic()){
			model=Mgr.equip.getModelDic()[$each_model];
			var vo;
			for(var $each_vo in model){
				vo=model[$each_vo];
				if (vo){
					lv+=vo.strenLv;
				}
			}
		}
		return lv;
	}

	__proto.getReachNum=function(condition,isTen){
		var reachNum=0;
		var equipDic=Mgr.equip.curModel.wearEquipDic;
		for (var i=1;i <=10;i++){
			var equipVo=equipDic[i];
			if(!equipVo){
				continue ;
			}
			if(!isTen && (equipVo.partPos==7 || equipVo.partPos==8)){
				continue ;
			}
			if(equipVo.strengthLv >=condition){
				reachNum++;
			}
		}
		return reachNum;
	}

	/**
	*获取全身升星等级
	*/
	__proto.getAllStarLv=function(){
		var lv=0;
		var vo;
		for(var $each_vo in Mgr.equip.curModel.starDic){
			vo=Mgr.equip.curModel.starDic[$each_vo];
			if (vo){
				lv+=vo.starLv;
			}
		}
		return lv;
	}

	/**
	*获取全身升星当前战斗力
	*/
	__proto.getAllStarFV=function(){
		var fv=0;
		for (var i=1;i <=10;i++){
			fv+=this.getPartStarFV(i);
		}
		return fv;
	}

	/**
	*获取升星附魂当前战斗力
	*/
	__proto.getUpStarFuHunFV=function(){
		var fv=0;
		var fhVo=Mgr.fuhun.getFuHunVo(9);
		for (var i=0;i < 6;i++){
			var fuHunMsg=fhVo.getServerMsg(i+1,9);
			if(fuHunMsg){
				fv+=fuHunMsg.fightValue;
			}
		}
		return fv;
	}

	/**
	*获取全身强化当前战斗力
	*/
	__proto.getAllStrenFV=function(){
		var fv=0;
		for (var i=1;i <=10;i++){
			fv+=this.getPartStrenFV(i);
		}
		return fv;
	}

	/**
	*获取单个部位强化战斗力
	*/
	__proto.getPartStrenFV=function(partPos){
		var vo=Mgr.equip.curModel.enhanceDic[partPos];
		if (!vo || !vo.nowAddFV)return 0;
		return vo.nowAddFV;
	}

	/**
	*获取单个部位升星战斗力
	*/
	__proto.getPartStarFV=function(partPos){
		var vo=Mgr.equip.curModel.starDic[partPos];
		if(!vo || !vo.nowAttrArr)return 0;
		var addFv=AttributeTypeEnum.getZdlByAttrArr(vo.nowAttrArr);
		return addFv;
	}

	/**获取下一个稀有等级的升星战斗力*/
	__proto.getNextQuaStarFV=function(partPos){
		var vo=Mgr.equip.curModel.starDic[partPos];
		var rareLv=vo.rareLv+1;
		var starLv=vo.starLv;
		var obj=this.starCfg.getCfgMsgByTwoKey("level",starLv.toString(),"position",partPos);
		if (!obj)return 0;
		var attrArr=AttributeTypeEnum.getAttrArrByCfgMsg(obj);
		var attrVO=attrArr[0];
		var fv=parseInt(attrVO.attrFV);
		return fv;
	}

	__proto.createStarVO=function(pos,starLv,e,failCount){
		var starVO=new StarVO;
		if (e){
			starVO.equipVO=e;
			var nextE=this.getStarNextE(e);
		}
		starVO.failCount=failCount;
		starVO.starLv=starLv;
		starVO.pos=pos;
		starVO.nextEquipVO=nextE;
		if (starVO.starLv !=0){
			var cfgMsg=this.starCfg.getCfgMsgByTwoKey("level",starLv.toString(),"position",pos.toString());
			if (cfgMsg==null){
				return starVO;
			}
			starVO.nowAttrArr=AttributeTypeEnum.getAttrArrByCfgMsg(cfgMsg);
			var attrVO=starVO.nowAttrArr[0];
			starVO.nowAddFV=attrVO.attrFV;
			starVO.curData=cfgMsg;
		}
		else{
			cfgMsg=this.starCfg.getCfgMsgByTwoKey("level","1","position","1");
			starVO.curData=cfgMsg;
		}
		if (starVO.starLv < this.starMaxLv){
			var nextCfgMsg=this.starCfg.getCfgMsgByTwoKey("level",(starLv+1).toString(),"position",pos.toString());
			if (nextCfgMsg==null){
				AlertUtil.show("从表中读到的最大升星等级："+this.starMaxLv+"级，我的升星等级："+starLv+"在升星表中找不到星级："+(starLv+1)+"级，稀有级别"+e.rareLv+"的数据");
				return starVO;
			};
			var needMatStr=nextCfgMsg.cost;
			starVO.nextData=nextCfgMsg;
			starVO.needMatStr=needMatStr;
			var needMatStrArr=needMatStr.split(":");
			starVO.needTemplateId=needMatStrArr[0];
			starVO.needMatCount=parseInt(needMatStrArr[1]);
			starVO.nextAttrArr=AttributeTypeEnum.getAttrArrByCfgMsg(nextCfgMsg);
			var rateMsg=this.getStarRateMsg((starVO.starLv+1).toString());
			starVO.rate=parseFloat(rateMsg.rate);
			starVO.addrate=parseFloat(rateMsg.addrate);
		}
		return starVO;
	}

	__proto.createStrenVO=function(pos,level,e,show){
		if(!show)
			return null;
		var strenVO=new StrenVO;
		if (e){
			strenVO.equipVO=e;
		}
		strenVO.pos=pos;
		strenVO.strenLv=level;
		strenVO.nextAttrArr=AttributeTypeEnum.newGetAttrArrByArr(show.nextAttr,"#4dff55","#4dff55");
		if(show.attr.length==0)
			strenVO.nowAttrArr=AttributeTypeEnum.newGetAttrArrByArr(show.nextAttr,null,null,false);
		else
		strenVO.nowAttrArr=AttributeTypeEnum.newGetAttrArrByArr(show.attr);
		strenVO.nowAddV=show.value;
		strenVO.nowAddFV=show.power;
		strenVO.needTemplateId=TemplateIdEnum.STREN_STONE;
		strenVO.needMatCount=show.itemNum;
		strenVO.costSilver=show.money;
		strenVO.nextAddV=show.nextValue;
		strenVO.nextAddFV=show.nextPower;
		return strenVO;
	}

	/**
	*强化红点检测
	*/
	__proto.checkStrenUp=function(equipModel){
		var isOpen=Mgr.guide.isOpen("dzqianhua");
		if (!isOpen){
			return;
		}
		this.red.hideRedPoint("dzqianhua",equipModel.curRoleId+"_"+"dzqianhua",RedTypeEnum.ForgeEnhance);
		if(!equipModel.enhanceDic)return;
		var vo;
		for(var $each_vo in equipModel.enhanceDic){
			vo=equipModel.enhanceDic[$each_vo];
			if(vo){
				if(Mgr.item.checkMatIsEnou(vo.needTemplateId,vo.needMatCount)&& NetMgr.ins().roleVO.level > vo.strenLv && NetMgr.ins().roleVO.coin >=vo.costSilver){
					this.red.showRedPoint("dzqianhua",equipModel.curRoleId+"_"+"dzqianhua",RedTypeEnum.ForgeEnhance);
					this.red.showRedPoint("dzqianhua",equipModel.curRoleId+"_"+vo.pos+"dzqianhua",RedTypeEnum.ForgeEnhance);
				}
				else
				this.red.hideRedPoint("dzqianhua",equipModel.curRoleId+"_"+vo.pos+"dzqianhua",RedTypeEnum.ForgeEnhance);
			}
		}
		this.checkEnhanceOrUpStarHeadRed(RedTypeEnum.ForgeEnhance,"dzqianhua");
	}

	__proto.checkGongMingRed=function(msg){
		var isQiangHua=msg.type !=24;
		var resonanceType=isQiangHua?"dzqianhua":"dzshengxing";
		var eventType=isQiangHua?RedTypeEnum.ForgeEnhance:RedTypeEnum.ForgeUpStar;
		if(msg.nextLevel==msg.level){
			this.red.hideRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
			return;
		}
		else{
			if(msg.type==24){
				var gongMingInfo=Mgr.equip.getGongMingByTwo(msg.type,msg.level);
				var nextGongMingInfo=Mgr.equip.getGongMingByTwo(msg.type,msg.nextLevel);
				if(nextGongMingInfo){
					if(!msg.isActive && msg.totalLevel >=parseInt(gongMingInfo.level)){
						this.red.showRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
					}
					else if(msg.totalLevel >=parseInt(nextGongMingInfo.level)){
						this.red.showRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
					}
					else{
						this.red.hideRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
					}
				}
				}else{
				gongMingInfo=Mgr.equip.getGongMingByTwoJieShu(msg.type,msg.level);
				nextGongMingInfo=Mgr.equip.getGongMingByTwoJieShu(msg.type,msg.nextLevel);
				if(nextGongMingInfo){
					if(msg.type==20){
						if(!msg.isActive && (this.getReachNum(parseInt(gongMingInfo.level),false)>=8)){
							this.red.showRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
						}
						else if(this.getReachNum(parseInt(nextGongMingInfo.level),false)>=8){
							this.red.showRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
						}
						else{
							this.red.hideRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
						}
						}else{
						if(!msg.isActive && (this.getReachNum(parseInt(gongMingInfo.level),true)>=10)){
							this.red.showRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
						}
						else if(this.getReachNum(parseInt(nextGongMingInfo.level),true)>=10){
							this.red.showRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
						}
						else{
							this.red.hideRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
						}
					}
				}
			}
		}
	}

	/**
	*检测升星提升
	*/
	__proto.checkStarUp=function(equipModel){
		var isOpen=Mgr.guide.isOpen("dzshengxing");
		if (!isOpen){
			return;
		}
		this.red.hideRedPoint("dzshengxing",equipModel.curRoleId+"_"+"dzshengxing",RedTypeEnum.ForgeUpStar);
		var vo;
		for(var $each_vo in equipModel.starDic){
			vo=equipModel.starDic[$each_vo];
			if(Mgr.item.checkMatIsEnou(vo.needTemplateId,vo.needMatCount)&& vo.starLv < this.starMaxLv){
				this.red.showRedPoint("dzshengxing",equipModel.curRoleId+"_"+"dzshengxing",RedTypeEnum.ForgeUpStar);
				this.red.showRedPoint("dzshengxing",equipModel.curRoleId+"_"+vo.pos+"dzshengxing",RedTypeEnum.ForgeUpStar);
			}
			else
			this.red.hideRedPoint("dzshengxing",equipModel.curRoleId+"_"+vo.pos+"dzshengxing",RedTypeEnum.ForgeUpStar);
		}
		this.checkEnhanceOrUpStarHeadRed(RedTypeEnum.ForgeUpStar,"dzshengxing");
	}

	/**根据部位，部位强化等级，获取到部位强化vo*/
	__proto.getStrenNextE=function(e){
		var nextE=ObjectTools.copyObjFast(e);
		nextE.strengthLv=e.strengthLv+1;
		return nextE;
	}

	/**
	*根据部位,强化等级,获取到下一级部位升星的vo
	*/
	__proto.getStarNextE=function(e){
		var nextE=ObjectTools.copyObjFast(e);
		nextE.starLevel=e.starLevel+1;
		return nextE;
	}

	/**
	*改变强化信息
	*/
	__proto.strenChange=function(pos,level,show){
		var e=Mgr.equip.curModel.wearEquipDic[pos];
		e.strengthLv=level;
		var vo=Mgr.equip.curModel.enhanceDic[pos];
		vo.equipVO=e;
		vo.strenLv=level;
		vo.needMatCount=show.itemNum;
		vo.costSilver=show.money;
		vo.nowAddV=show.value;
		vo.nowAddFV=show.power;
		vo.nextAddV=show.nextValue;
		vo.nextAddFV=show.nextPower;
		vo.nowAttrArr=AttributeTypeEnum.newGetAttrArrByArr(show.attr);
		vo.nextAttrArr=AttributeTypeEnum.newGetAttrArrByArr(show.nextAttr);
		this.checkStrenUp(Mgr.equip.curModel);
		EventCenter.instance.event("EQUIP_PART_STREN_CHANGE",vo);
	}

	/**
	*改变升星信息
	*/
	__proto.starChange=function(guid,starLv,isFail,failCount,roleId){
		var equipModel=Mgr.equip.getModelbyRoleId(roleId);
		this.failCount=failCount;
		if (!Mgr.equip.guidDic){
			alert("从未收到装备列表更新协议");
			return;
		};
		var e=Mgr.equip.guidDic[guid];
		if (!e){
			alert("找不到guid为"+guid+"的装备");
			return;
		}
		e.starLevel=starLv;
		var starVO=equipModel.starDic[e.partPos];
		starVO.starLv=starLv;
		starVO.equipVO=e;
		var nowCfgMsg=this.starCfg.getCfgMsgByTwoKey("level",starLv.toString(),"position",e.partPos.toString());
		starVO.nowAttrArr=AttributeTypeEnum.getAttrArrByCfgMsg(nowCfgMsg);
		starVO.curData=nowCfgMsg;
		starVO.nextData=nowCfgMsg;
		var nextCfgMsg=this.starCfg.getCfgMsgByTwoKey("level",(starLv+1).toString(),"position",e.partPos.toString());
		if (nextCfgMsg){
			starVO.needMatStr=nextCfgMsg.cost;
			var needMatStrArr=starVO.needMatStr.split(":");
			starVO.needTemplateId=needMatStrArr[0];
			starVO.needMatCount=parseInt(needMatStrArr[1]);
			starVO.nextAttrArr=AttributeTypeEnum.getAttrArrByCfgMsg(nextCfgMsg);
			var rateObj=this.getStarRateMsg((starVO.starLv+1).toString());
			starVO.rate=parseFloat(rateObj.rate);
			starVO.addrate=parseFloat(rateObj.addrate);
			starVO.nextData=nextCfgMsg;
		}
		this.checkStarUp(equipModel);
		EventCenter.instance.event("EQUIP_PART_STAR_CHANGE",starVO);
	}

	/**
	*根据升星等级获取到一行的升星失败概率
	*/
	__proto.getStarRateMsg=function(level){
		var addRateObj=this.starRateCfg.getItemByField("level",level);
		return addRateObj;
	}

	/**强化和升星 头像红点 */
	__proto.checkEnhanceOrUpStarHeadRed=function(headName,moduleName){
		var heroAry=Mgr.subPlayer.getHeroHeadList();
		var len=heroAry.length;
		var roleRed=this.red.getValue(moduleName);
		for (var i=0;i < len;i++){
			var tempVo=heroAry[i];
			if(!tempVo)
				continue ;
			var redBo=roleRed.getCornerState(tempVo.roleId+"_"+moduleName);
			if(redBo){
				EventCenter.instance.event(RedTypeEnum.RoleHeadRed,[headName,i,redBo]);
				continue ;
			}
			EventCenter.instance.event(RedTypeEnum.RoleHeadRed,[headName,i,false]);
		}
	}

	__proto.initSendResonance=function(){
		Mgr.equipPro.sendGongMing(20,0,2);
		Mgr.equipPro.sendGongMing(126,0,2);
		Mgr.equipPro.sendGongMing(24,0,2);
	}

	return StrenAndStarMgr;
})()


/**
*@author wyz
*date：2019-11-24 下午4:51:11
*
*/
//class com.xq.modules.equip.suit.SuitMgr
var SuitMgr=(function(){
	function SuitMgr(){
		/**
		*收集装备表
		*/
		this.collectEquipCfg=null;
		/**
		*装备表
		*/
		this.equipCfg=null;
		/**
		*兑换装备表
		*/
		this.collectEquipData=null;
		this.red=null;
		/**当前套装唯一编号 */
		this.curSuitId=0;
		/**当前可预览最大大类id*/
		this.maxShowSuitTab=0;
		/**当前套装已激活件数 3 6 8*/
		this.curActiveNum=0;
		this.activeArr=[3,6,8];
		/**套装 大类数组*/
		this.suitTabArr=null;
		/**套装 装备阶级数组*/
		this.suitItemArr=null;
		/**套装中装备最大阶级*/
		this.suitMaxLevel=0;
		/**套装后端信息字典*/
		this.suitSerDic=null;
		/**每个套装激活数量*/
		this.suitNumDic=null;
		/**套装大类数量*/
		this.suitDaLeiNum=0;
		this._selectCurSuitId=0;
		this.orangeArr=null;
		this.redArr=null;
		/**
		*服务器整理收集装备数据
		*/
		this.suitRewardDic=null;
		this.suitRewardArr=null;
		/**当前套装数量*/
		this.wearNum=0;
		this.suitSerDic=new Dictionary();
		this.suitNumDic=new Dictionary();
		this.equipCfg=CfgManager.getTableCfg("ZhuangBeiBiao");
		this.collectEquipCfg=CfgManager.getTableCfg("newshoujizhuangbei");
		this.red=Mgr.red;
		EventCenter.instance.onQue("ROLE_EQUIP_EXCHANGE_UPDATED",this,this.checkIconRedPoint);
		EventCenter.instance.on("new_function_open",this,this.newOpenFun);
		this.suitTabArr=[];
		this.suitItemArr=[];
		this.neatenSuitInfo();
	}

	__class(SuitMgr,'com.xq.modules.equip.suit.SuitMgr');
	var __proto=SuitMgr.prototype;
	__proto.setSuitSerValue=function(shouJiSuitMsg){
		this.suitSerDic.set(shouJiSuitMsg.id,shouJiSuitMsg);
	}

	__proto.getSuitSerValue=function(id){
		return this.suitSerDic.get(id);
	}

	__proto.getCollectEquipData=function(){
		if(!this.collectEquipData){
			this.collectEquipData=new DataContainer();
			var cfgArr=this.collectEquipCfg.objectDataArray;
			var len=cfgArr.length;
			for (var i=0;i < len;i++){
				var cfg=cfgArr[i];
				if(cfg){
					var ele=new DataElement(cfg);
					this.collectEquipData.addElement(cfg.ID,ele);
				}
				if(i==(len-1)){
					this.suitDaLeiNum=parseInt(cfg.dalei);
				}
			}
		}
		return this.collectEquipData;
	}

	__proto.neatenSuitInfo=function(){
		var suitArr=this.collectEquipCfg.objectDataArray;
		var len=suitArr.length;
		this.suitMaxLevel=parseInt(suitArr[len-1].level);
		for (var i=0;i <=this.suitMaxLevel;i++){
			var suitLevelArr=this.getSuitArrByOne(i);
			if(suitLevelArr){
				this.suitTabArr.push(suitLevelArr[0]);
				this.suitItemArr.push(suitLevelArr);
			}
		}
	}

	/**通过装备阶级获取一个数组 然后组装成suitVo数组*/
	__proto.getSuitArrByOne=function(level){
		var suitVoArr=[];
		var suitArr=this.collectEquipCfg.getItemsByField("level",level+"");
		if(suitArr.length==0){
			return null;
		};
		var len=suitArr.length;
		for (var i=0;i < len;i++){
			var suitInfo=suitArr[i];
			var cfgArr=this.equipCfg.getCfgMsgArrByThreeKey("itemlevel",parseInt(suitInfo.level),"rarelevel",parseInt(suitInfo.rarelevel),"star",suitInfo.star);
			var equipArr=[];
			for (var j=0;j < cfgArr.length;j++){
				var templateId=cfgArr[j].id;
				var e=Mgr.item.getItemVO(templateId);
				equipArr.push(e);
			}
			suitVoArr.push(this.createSuitVo(suitInfo,equipArr));
		}
		return suitVoArr;
	}

	__proto.newOpenFun=function(id,initBo){
		(id===void 0)&& (id="");
		(initBo===void 0)&& (initBo=false);
		if(!initBo){
			if(id=="roleSuit"){}
				}
		else{
			if(Mgr.guide.isOpen("roleSuit")){}
				}
	}

	/**通过套装稀有级别和第套装获取到一行数据*/
	__proto.getSuitMsg=function(rareLv,suitNum){
		return this.collectEquipCfg.getCfgMsgByTwoKey("rarelevel",rareLv.toString(),"suit",suitNum);
	}

	/**通过套装稀有级别和第套装获取到一行数据*/
	__proto.getSuitMsgById=function(id){
		return this.getCollectEquipData().getElement(id+"").getCfgData();
	}

	__proto.getSuitArrByRareLv=function(rareLv){
		var roleVO=NetMgr.ins().roleVO;
		var roleJob=roleVO.job;
		var lv=roleVO.level;
		var allSuitArr=[];
		var collectCfgArr=this.collectEquipCfg.objectDataArray;
		var len=collectCfgArr.length;
		for (var suitIndex=1;suitIndex <=len;suitIndex++){
			var obj=collectCfgArr[suitIndex-1];
			if (!obj){
				debugger
				continue ;
			};
			var cfgArr=this.equipCfg.getCfgMsgArrByThreeKey("suit",suitIndex,"rarelevel",obj.rarelevel,"star",0);
			var equipArr=[];
			for (var j=0;j < cfgArr.length;j++){
				var templateId=cfgArr[j].id;
				var job=cfgArr[j].job;
				var e=Mgr.item.getItemVO(templateId);
				e.whichPanel=10;
				if (job=="0" || job==roleJob){
					equipArr.push(e);
				}
			};
			var suitVO=this.createSuitVo(obj,equipArr);
			allSuitArr.push(suitVO);
		};
		var showArr=[];
		if (rareLv==SuitMgr.ORANGE_RARE){
			for (var i2=0;i2 < allSuitArr.length;i2++){
				var temp=allSuitArr[i2];
				if(Mgr.equip.curModel.curSuitId >=parseInt(temp.suitId))
					temp.isActivation=true;
				else
				temp.isActivation=false;
				showArr.push(temp);
			}
			this.orangeArr=showArr;
			return this.orangeArr;
		}
		else{
			this.redArr=allSuitArr;
			return this.redArr;
		}
	}

	__proto.createSuitVo=function(obj,equipArr){
		var suitVO=new SuitVO;
		suitVO.cfg=obj;
		suitVO.suitNum=obj.suit;
		suitVO.equipArr=equipArr;
		suitVO.suitLv=parseInt(obj.showLevel);
		suitVO.suitRareLv=obj.rarelevel;
		suitVO.suitId=obj.ID;
		suitVO.huanHuaId=obj.huanhuaid;
		suitVO.addFV=obj.zhanlibiaosheng;
		var attr1Str=obj.attr1;
		var attr1Arr=this.getAttrArr(attr1Str);
		suitVO.attr1=attr1Arr;
		suitVO.attr1FV=this.getAttrFV(attr1Str);
		var attr2Str=obj.attr2;
		var attr2Arr=this.getAttrArr(attr2Str);
		suitVO.attr2=attr2Arr;
		suitVO.attr2FV=this.getAttrFV(attr2Str);
		var attr3Str=obj.attr3;
		var attr3Arr=this.getAttrArr(attr3Str);
		suitVO.attr3=attr3Arr;
		suitVO.attr3FV=this.getAttrFV(attr3Str);
		var attr4Str=obj.attr4;
		var attr4Arr=this.getAttrArr(attr4Str);
		suitVO.attr4=attr4Arr;
		suitVO.attr4FV=this.getAttrFV(attr4Str);
		var attr5Str=obj.attr5;
		var attr5Arr=this.getAttrArr(attr5Str);
		suitVO.attr5=attr5Arr;
		suitVO.attr5FV=this.getAttrFV(attr5Str);
		var attr6Str=obj.attr6;
		var attr6Arr=this.getAttrArr(attr6Str);
		suitVO.attr6=attr6Arr;
		suitVO.attr6FV=this.getAttrFV(attr6Str);
		var attr7Str=obj.attr7;
		var attr7Arr=this.getAttrArr(attr7Str);
		suitVO.attr7=attr7Arr;
		suitVO.attr7FV=this.getAttrFV(attr7Str);
		var attr10Str=obj.attr10;
		var attr10Arr=this.getAttrArr(attr10Str);
		suitVO.attr10=attr10Arr;
		suitVO.attr10FV=this.getAttrFV(attr10Str);
		return suitVO;
	}

	/**
	*传进去套装属性字符串，返回属性字符串数组
	*/
	__proto.getAttrArr=function(attrStr){
		var resultStrArr=[];
		var attrTypeStrArr=attrStr.split(";");
		for (var i=0;i < attrTypeStrArr.length;i++){
			var attrTypeStr=attrTypeStrArr[i];
			var attrStrArr=attrTypeStr.split(":");
			var attr=new AttributeMsg();
			var attrOneStr=attrStrArr[0];
			var attrObj=AttributeTypeEnum.getMsgByZhanLiCfg(attrOneStr);
			attr.attrId=parseInt(attrObj.id);
			attr.attrValue=parseInt(attrStrArr[1]);
			resultStrArr.push(attr);
		}
		return resultStrArr;
	}

	/**
	*传进去套装属性字符串，返回战斗力
	*/
	__proto.getAttrFV=function(attrStr){
		var fv=0;
		var attrTypeStrArr=attrStr.split(";");
		for (var i=0;i < attrTypeStrArr.length;i++){
			var str=attrTypeStrArr[i];
			var arr=str.split(":");
			var factor=AttributeTypeEnum.getAttrFactor(arr[0]);
			fv+=Math.floor(parseFloat(arr[1])*factor);
		}
		return fv;
	}

	/**
	*检测页签红点s
	*/
	__proto.checkSuitTabRedPoint=function(selectSuitId){
		(selectSuitId===void 0)&& (selectSuitId=0);
		if(!Mgr.guide.isOpen("roleSuit"))
			return;
		this.red.hideRedPoint("roleSuit","roleSuit");
		this.red.hideRedPoint("roleSuitNewRed","roleSuit","roleSuit");
		this.hideAllDaLeiRed();
		this.curSuitId=0;
		var serArr=this.suitSerDic.values;
		var len=serArr.length;
		for (var i=0;i < len;i++){
			var suitMsg=serArr[i];
			var allActiveArr=suitMsg.suitEquipState;
			var curSuitWearNum=0;
			this.red.hideRedPoint("roleSuit","roleSuit"+"_"+suitMsg.id ,RedTypeEnum.RefreshSuitRed);
			var len1=allActiveArr.length;
			for (var j=0;j < len1;j++){
				var cfg=this.getSuitMsgById(suitMsg.id);
				var equipState=allActiveArr[j];
				if(equipState.activeState){
					curSuitWearNum++;
				}
				if(this.curPartIsActive(cfg,equipState)){
					this.setCurSuitId(suitMsg.id);
					this.red.showRedPoint("roleSuitNewRed","roleSuit","roleSuit");
					this.red.showRedPoint("roleSuit",suitMsg.id+"_"+equipState.equipPart ,RedTypeEnum.RefreshSuitRed);
					this.red.showRedPoint("roleSuit","roleSuit"+"_"+suitMsg.id ,RedTypeEnum.RefreshSuitRed);
					this.red.showRedPoint("roleSuit","roleSuit"+"_tab"+cfg.dalei,RedTypeEnum.RefreshSuitRed);
					}else{
					this.red.hideRedPoint("roleSuit",suitMsg.id+"_"+equipState.equipPart ,RedTypeEnum.RefreshSuitRed);
				}
			}
			this.suitNumDic.set(suitMsg.id,curSuitWearNum);
		}
		this.setCurSuitId(this._selectCurSuitId);
		EventCenter.instance.event("GUIDE_SUIT_UPDAE");
	}

	__proto.setCurSuitId=function(suitId){
		if(!this.curSuitId){
			this.curSuitId=suitId;
		}
	}

	/**去掉套装下方页签红点*/
	__proto.hideAllDaLeiRed=function(){
		for (var i=1;i <=this.suitDaLeiNum;i++){
			this.red.hideRedPoint("roleSuit","roleSuit"+"_tab"+i ,RedTypeEnum.RefreshSuitRed);
		}
	}

	__proto.curPartIsActive=function(cfg,suitMsg){
		if(suitMsg.activeState || suitMsg.equipPart==7 || suitMsg.equipPart==8){
			return false;
			}else{
			var equipVo=Mgr.equip.curModel.wearEquipDic[suitMsg.equipPart];
			if(equipVo && equipVo.cfgItem.itemlevel >=cfg.level && equipVo.cfgItem.rarelevel >=cfg.rarelevel && equipVo.cfgItem.star >=cfg.star){
				return true;
			}
		}
		return false;
	}

	/**
	*检测收集装备红点
	*/
	__proto.checkIconRedPoint=function(){
		Laya.timer.callLater(this,this.checkR);
	}

	__proto.checkR=function(){
		FrameSmooth.add(Handler.create(this,this.delayCheck));
	}

	__proto.delayCheck=function(){
		this.checkSuitTabRedPoint();
	}

	/**
	*获取身上的套装数组vo
	*/
	__proto.getSuitWearArr=function(){
		var arr;
		var dic=Mgr.equip.partDic;
		for (var i=0;i < 10;i++){
			var e=dic[i+1];
			if (e && e.cfgItem.suit > 0){
				arr[i]=e;
			}
			else{
				arr[i]=null;
			}
		}
		return arr;
	}

	__proto.setMaxShowSuitTab=function(suitId){
		var nowSuitTab=suitId;
		if(this.maxShowSuitTab !=nowSuitTab){
			Mgr.equipPro.sendCollectEquip();
		}
		this.maxShowSuitTab=nowSuitTab;
	}

	__proto.getMaxShowSuitTab=function(){
		return this.maxShowSuitTab;
	}

	__getset(0,__proto,'selectCurSuitId',null,function(select){
		this._selectCurSuitId=select;
	});

	SuitMgr.ORANGE_RARE=4;
	SuitMgr.RED_RARE=5;
	SuitMgr.GOLD_RARE=6;
	SuitMgr.ORANGE_SUIT_NUM=10;
	SuitMgr.PART_NUM=10;
	return SuitMgr;
})()


