		if(Mgr.copy.getForceExit){
			Mgr.copy.setForceExit=false;
			Mgr.fengshenluPro.sendExit();
			return;
		}
		if(this.alertTip && this.alertTip.isPopup){
			this.alertTip.close();
			this.alertTip=null;
			return
		};
		var str="退出副本后本次副本次数将扣除，确定要退出吗？";
		this.alertTip=AlertUtil.ShowAlert(str,Handler.create(this,this.onTeamExit),null);
