	/**获取自己宗门相关信息*/
	__proto.getSelfPosition=function(){
		var members=this.model.myGuildInfoMsg.members;
		var len=members.length;
		for(var i=0;i<len;i++){
			var memberInfo=members[i];
			if(memberInfo.id==NetMgr.ins().roleVO.guid){
				NetMgr.ins().roleVO.guildTitle=memberInfo.position;
				NetMgr.ins().roleVO.contribute=memberInfo.contribution;
				NetMgr.ins().roleVO.totalContribute=memberInfo.totalContribution;
				break ;
			}
		}
	}

	__proto.setGuild=function(){
		NetMgr.ins().roleVO.guildId=this.model.myGuildInfoMsg.id;
		NetMgr.ins().roleVO.guildName=this.model.myGuildInfoMsg.name;
		if(Game.getInstance().player){
			Game.getInstance().player.guildName=this.model.myGuildInfoMsg.name;
		}
		if(!this.first&&this.model.myGuildInfoMsg.id!=0){
			Mgr.taskPro.sendGetDailyTaskInfo(3);
			this.first=true;
		}
	}

	//
	__proto.onGetGuildList=function(msg){
		this.guildList=msg;
		this.guildListArr=[];
		var arr=this.guildList.guildInfos;
		var lent=arr.length
		for (var i=0;i < lent;i++){
			var obj={};
			var info=arr[i];
			var members=info.members;
			var onLineCount=0;
			var len=members.length
			for (var j=0;j < len;j++){
				var memInfo=members[j];
				if(memInfo.isOnline){
					onLineCount++;
				}
			}
			obj.maxMem=this.getMaxMemByLevel(info.level);
			obj.onLineCount=onLineCount;
			obj.msgItem=info;
			obj.level=info.level;
			obj.memberCount=members.length;
			obj.fightValue=info.fightValue;
			obj.notice=info.notice;
			obj.name=info.name;
			this.guildListArr.push(obj);
		}
		EventCenter.instance.event("GUILD_LIST_UPDATE");
	}

