	__proto.onMsgBtnClick=function(){
		if(NetMgr.ins().roleVO.guildId!=0){
			var avo=this.model.applyDic.values.pop();
			if(avo){
				var key=this.model.applyDic.indexOf(avo);
				this.model.deleteApply(avo.applyRoleId);
				var str="<font color='#57f274'>"+avo.roleName+"</font><font color='#cbdff2'>申请加入您所在帮派</font>";
				this.newAlert=AlertUtil.ShowAlert(str,Handler.create(this,this.closeAler,[avo]));
				this.newAlert.getBtnCancle().label="忽略";
				this.newAlert.getBtnSure().label="通过";
			}
			}else{
			var ivo=this.model.inviteDic.values.pop();
			if(ivo){
				var key=this.model.inviteDic.indexOf(ivo);
				this.model.deleteInvite(ivo.inviterId);
				var str=ivo.inviterName+"邀请您加入帮派";
				this.newAlert=AlertUtil.ShowAlert(str,Handler.create(this,this.closeAler,[ivo]));
			}
		}
	}

	__proto.closeAler=function(vo,type){
		(type===void 0)&& (type="");
		if(type=="OK"){
			if((vo instanceof com.xq.modules.guild.vo.ApplyVO )){
				Mgr.guildPro.sendHandleApplyJoinGuild(true,vo.applyRoleId);
			}
			else{
				Mgr.guildPro.sendHandleInviteJoin(true,(vo).guildId,(vo).inviterId);
			}
		}
		else{
			if((vo instanceof com.xq.modules.guild.vo.ApplyVO )){
				Mgr.guildPro.sendHandleApplyJoinGuild(false,vo.applyRoleId);
			}
			else{
				Mgr.guildPro.sendHandleInviteJoin(false,(vo).guildId,(vo).inviterId);
			}
		};
		var arr;
		if((vo instanceof com.xq.modules.guild.vo.ApplyVO )){
			if(this.model.applyDic.values.length>0){
				this.onMsgBtnClick();
			}
		}
		else{
			if(this.model.inviteDic.values.length>0){
				this.onMsgBtnClick();
			}
		}
	}

	__proto.onGuildInfoChange=function(sc){
		var players=UnitManager.ins.roleList.values;
		var len=players.length;
		var player;
		var roleVO;
		for(var i=0;i<len;i++){
			player=players[i];
			roleVO=player.vo;
			if(String(sc.roleId)==String(roleVO.guid)){
				roleVO.guildId=sc.guildId;
				roleVO.guildName=sc.guildName;
				player.guildName=sc.guildName;
				var vo=NetMgr.ins().roleVO;
				if(roleVO.guildId==vo.guildId && vo.guildId !=0){
					player.unitGuild.color="#4dff55";
					}else{
					player.unitGuild.color="#ffd951";
				}
				break ;
			}
		}
	}

