	/**检查宗门捐献的权限*/
	__proto.checkContriRed=function(){
		if(!this.contributeInfo){
			this.red.hideRedPoint("zongmenjuanxian","hasNum","UPDATE_ZONGMEN_RED_POINT");
			return false;
		};
		var roleVO=NetMgr.ins().roleVO;
		var obj=this.model.contriDic.get(2)[0];
		if(roleVO.coin>parseInt(obj.limit)&& this.contributeInfo.contributeTimes < this.model.totalContriTimes){
			this.red.showRedPoint("zongmenjuanxian","hasYL","UPDATE_ZONGMEN_RED_POINT");
			return true;
		}
		else
		this.red.hideRedPoint("zongmenjuanxian","hasYL","UPDATE_ZONGMEN_RED_POINT");
		var datas=this.model.contriDic.get(3)
		var obje;
		for(var $each_obje in datas){
			obje=datas[$each_obje];
			if(Mgr.bag.getBagMatCount(obje.item)>=parseInt(obje.limit)){
				this.red.showRedPoint("zongmenjuanxian","hasLP","UPDATE_ZONGMEN_RED_POINT");
				return true;
			}
			else
			this.red.hideRedPoint("zongmenjuanxian","hasLP","UPDATE_ZONGMEN_RED_POINT");
		}
		return false;
	}

	__proto.checkContributeRankRed=function(){
		var stat=this.getContributeRankRewardStat();
		if(stat==1){
			this.red.showRedPoint("zongmenjuanxian","rankReward","UPDATE_ZONGMEN_RED_POINT");
		}
		else{
			this.red.hideRedPoint("zongmenjuanxian","rankReward","UPDATE_ZONGMEN_RED_POINT");
		}
	}

