	__proto.refreshGuildStoreList=function(storeList){
		var len=storeList.length;
		this.storeItemList=[];
		for (var i=0;i < len;i++){
			var itemMsg=storeList[i];
			var templateId=itemMsg.templateId;
			var firstStr=templateId.substr(0,1);
			switch(firstStr){
				case "d":{
						var d=Mgr.bag.createItemVo(itemMsg);
						d.whichPanel=16;
						d.count=this.exchangeRemainingItem;
						this.storeItemList.push(d);
						break
					}
				default :{
						var z=Mgr.bag.createEquipVO(itemMsg);
						if(z){
							z.whichPanel=16;
							var ele=Mgr.guild.getEquipScore(z.cfgItem.itemlevel,z.cfgItem.rarelevel,z.cfgItem.star);
							z.donateScore=parseInt(ele.getCfgData().donate);
							z.exchangeScore=parseInt(ele.getCfgData().needscore);
							this.storeItemList.push(z);
						}
					}
				}
		}
		EventCenter.instance.event("updata_guild_store_info");
	}

