	__proto.startChallenge=function(msg){
		var warVo=new WarPlayerVo();
		var obj={};
		obj.ID=msg.tId;
		obj.name=msg.tName;
		obj.job=msg.tSex;
		obj.level=msg.tLevel;
		if(msg.wingHuanHua > 0)
			obj.shenyi=[1,msg.wingHuanHua];
		else
		obj.shenyi=[0,msg.wingId];
		if(msg.weaponHuanHua > 0)
			obj.shenbing=[1,msg.weaponHuanHua];
		else
		obj.shenbing=[0,msg.weaponId];
		obj.shizhuang=msg.roleHuanHua;
		obj.fightValue=msg.tFightValue;
		warVo.roleObj=obj;
		warVo.poVo=Mgr.jintai.model.btzPo;
		warVo.subRoles=msg.subrole;
		Wargame.Ins.init(warVo,Mgr.jintai.model.tzPo,true,Handler.create(this,this.stopChallenge));
	}

