//class com.xq.modules.guild.GuildModel
var GuildModel=(function(){
	function GuildModel(){
		this.powerTable=null;
		this.guildLevelTable=null;
		this.shopTable=null;
		this.contriTable=null;
		this.powerDic=null;
		this.shopDic=null;
		this.guildLevelDic=null;
		this.attrDic=null;
		this.contriDic=null;
		this.applyDic=null;
		this.inviteDic=null;
		/**宗门捐献银两 已捐献次数*/
		this.totalContriTimes=0;
		/**宗门捐献元宝 已捐献次数*/
		this.goldContriTimes=0;
		/**我的宗门信息*/
		this.myGuildInfoMsg=null;
		/**宗门所有成员总战力*/
		this.allPower=NaN;
		//===捐献日志 捐献排行榜====
		this._contributeRankCof=null;
		this._contributeRankDc=null;
		/**捐献日志数组*/
		this._contributeLogs=[];
		/**我的捐献排行*/
		this._myContributeRank=0;
		/**已领取id数组*/
		this._gotIds=null;
		/**今日最高排行奖励是否已领取*/
		this._ifGetTopReward=false;
		this.powerDic=new Dictionary();
		this.guildLevelDic=new Dictionary();
		this.shopDic=new Dictionary();
		this.applyDic=new Dictionary();
		this.inviteDic=new Dictionary();
		this.attrDic=new Dictionary();
		this.contriDic=new Dictionary();
		this.powerTable=CfgManager.getTableCfg("GuildPosition");
		this.shopTable=CfgManager.getTableCfg("Guildjianzhu");
		this.guildLevelTable=CfgManager.getTableCfg("Guildhome");
		this.contriTable=CfgManager.getTableCfg("Guilddonate");
		this._contributeRankCof=CfgManager.getTableCfg("GuildjuanxianRank");
		this.parsePower();
		this.parseShop();
		this.parseGuildLevel();
		this.parseContri();
	}

	__class(GuildModel,'com.xq.modules.guild.GuildModel');
	var __proto=GuildModel.prototype;
	/**解析权限*/
	__proto.parsePower=function(){
		var arr=this.powerTable.objectDataArray;
		var obj;
		for(var $each_obj in arr){
			obj=arr[$each_obj];
			this.powerDic.set(obj.postLevel,obj);
		}
	}

	__proto.parseGuildLevel=function(){
		var arr=this.guildLevelTable.objectDataArray;
		var len=arr.length;
		var obj;
		var level=0;
		for(var i=0;i<len;i++){
			level=parseInt(arr[i].level);
			this.guildLevelDic.set(level,arr[i]);
			var attr=arr[i].attr;
			var attrs=attr.split(";");
			obj=new Object();
			var per;
			for(var $each_per in attrs){
				per=attrs[$each_per];
				var pers=per.split(":");
				obj[pers[0]]=parseInt(pers[1]);
			}
			this.attrDic.set(level,obj);
		}
	}

	__proto.parseShop=function(){
		var arr=this.shopTable.objectDataArray;
		var len=arr.length;
		for(var i=0;i<len;i++){
			this.shopDic.set(parseInt(arr[i].level),arr[i]);
		}
	}

	__proto.parseContri=function(){
		var arr=this.contriTable.objectDataArray;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var type=parseInt(arr[i].type);
			var datas=this.contriDic.get(type);
			if(!datas){
				datas=[];
				this.contriDic.set(type,datas);
			}
			datas.push(arr[i]);
			if(type==1){
				this.goldContriTimes=arr[i].times;
			}
			else if(type==2){
				this.totalContriTimes=arr[i].times;
			}
		}
	}

	/**检查是否有权限*/
	__proto.checkPower=function(position,power){
		var obj=this.powerDic.get(position);
		if(!obj || obj.permissions==null){
			return false;
		}
		if(obj.permissions==null){
			return false;
		};
		var pows=obj.permissions.split(";");
		var inx=pows.indexOf(String(power));
		return inx >-1 ? true:false;
	}

	__proto.getPosAry=function(po){
		var obj=this.powerDic.get(po);
		if(!obj)
			return [];
		return obj.permissions.split(";");
	}

	__proto.getPostName=function(position){
		var obj=this.powerDic.get(position);
		if(!obj){
			return "";
		}
		return obj.postName;
	}

	/***/
	__proto.getGuildProperty=function(level,name){
		var obj=this.guildLevelDic.get(level);
		var attr=obj.attr;
		var attrs=attr.split(";");
		var per;
		for(var $each_per in attrs){
			per=attrs[$each_per];
			per.split(":");
		}
	}

	__proto.addApply=function(vo){
		this.applyDic.set(vo.applyRoleId,vo);
		EventCenter.instance.event("guild_message_change");
	}

	__proto.deleteApply=function(roleId){
		this.applyDic.remove(roleId);
		EventCenter.instance.event("guild_message_change");
	}

	__proto.clearApply=function(){
		this.applyDic.clear();
		EventCenter.instance.event("guild_message_change");
	}

	__proto.addInvite=function(vo){
		this.inviteDic.set(vo.inviterId,vo);
		EventCenter.instance.event("guild_message_change");
	}

	__proto.deleteInvite=function(inviteId){
		this.inviteDic.remove(inviteId);
		EventCenter.instance.event("guild_message_change");
	}

	__proto.clearInvite=function(){
		this.inviteDic.clear();
		EventCenter.instance.event("guild_message_change");
	}

	__proto.getGuidLevel=function(){
		if(this.myGuildInfoMsg && this.myGuildInfoMsg.id !=0){
			return this.myGuildInfoMsg.level;
		}
		return 0;
	}

	/**捐献排行配置DataContainer*/
	__proto.getContributeRankDc=function(){
		if(!this._contributeRankDc){
			this._contributeRankDc=new DataContainer();
			CommonUtil.initDataContainer(this._contributeRankDc,this._contributeRankCof,"rank");
		}
		return this._contributeRankDc;
	}

	/**刷新捐献日志数据*/
	__proto.updateContributeLog=function(msg){
		this._contributeLogs=msg.infos;
	}

	/**刷新捐献排行数据*/
	__proto.updateContributeRank=function(msg){
		var dc=this.getContributeRankDc();
		dc.clearEleValue("s_data");
		var arr=msg.rankInfo;
		var rankInfo;
		var len=arr.length;
		for(var i=0;i<len;i++){
			rankInfo=arr[i];
			var rank=rankInfo.rank;
			var ele=dc.getElement(rank);
			ele&&ele.setValue("s_data",rankInfo);
		}
		this._myContributeRank=msg.myRank;
		this._gotIds=msg.getIds;
		this._ifGetTopReward=msg.getReward;
	}

	/**刷新领取捐献奖励*/
	__proto.updateContributeRankReward=function(msg){
		this._gotIds=msg.getIds;
		this._ifGetTopReward=msg.getReward;
	}

	//
	__proto.getContributeLogs=function(){
		return this._contributeLogs;
	}

	__proto.getMyRank=function(){
		return this._myContributeRank;
	}

	/**该Id的排名奖励是否被领取过（不重置）*/
	__proto.ifReceivedId=function(id){
		return this._gotIds&&this._gotIds.indexOf(id)!=-1
	}

	/**今日最高排名奖励是否领取（每天重置）*/
	__proto.ifReceivedToday=function(){
		return this._ifGetTopReward;
	}

	/**通过Rank获取对应配置id 如没找到返回0*/
	__proto.getIdByRank=function(rank){
		var ele=this.getContributeRankDc().getElement(rank);
		if(!ele)return 0;
		return parseInt(ele.getCfgData().id);
	}

	GuildModel.ins=function(){
		return GuildModel._ins=GuildModel._ins|| new GuildModel();
	}

	GuildModel._ins=null;
	return GuildModel;
})()


