var GuoGuanCfgVo=(function(){
	function GuoGuanCfgVo(){
		/**当前版本*/
		this.flag=0;
		/**参与最小等级*/
		this.minPlayer=0;
		/**通关排名奖励 格式[0-排名，1-奖励]*/
		this.tgReward=null;
		/**伤害排名奖励*/
		this.harmReward=null;
		/**首刀奖励*/
		this.firstReward=null;
		/**活动奖励*/
		this.actReward=null;
		/**击杀吕布奖励*/
		this.killReward=null;
		/**通关层数奖励 格式[0-排名，1-奖励]*/
		this.floorReward=null;
	}

	__class(GuoGuanCfgVo,'com.xq.modules.guoguanzhanjiang.GuoGuanCfgVo');
	var __proto=GuoGuanCfgVo.prototype;
	/**
	*设置通关/伤害奖励
	*@param _reward奖励内容 type:0-通关排名;1-伤害排名
	**/
	__proto.setTgRew=function(_reward,type){
		var typeAry;
		var ary=_reward.split(";");
		var len=ary.length;
		for (var i=0;i < len;i++){
			var tempAry=ary[i].split("|");
			var rankAry=[]
			ary[i]=rankAry;
			rankAry[0]=tempAry[0];
			rankAry[1]=tempAry[1].split("-");
		}
		if(type==0){
			this.tgReward=ary;
		}
		else if(type==1){
			this.harmReward=ary;
		}
		else if(type==2){
			this.floorReward=ary;
		}
	}

	/**设置击杀奖励*/
	__getset(0,__proto,'killRew',null,function(_reward){
		this.killReward=_reward.split(";");
	});

	/**设置首刀奖励*/
	__getset(0,__proto,'firstRew',null,function(_reward){
		this.firstReward=_reward.split(";");
	});

	/**设置活动奖励*/
	__getset(0,__proto,'actRew',null,function(_reward){
		this.actReward=_reward.split(";");
	});

	return GuoGuanCfgVo;
})()


