var QunXiongZhengBaMgr=(function(){
	function QunXiongZhengBaMgr(){
		this.ifMeInitiate=false;
		this._selectType=0;
		this._selectCity=0;
		this._model=null;
		this._kuafuDic=null;
		this._attackGuildId=NaN;
		this._red=null;
		this._myCity=null;
		this._battleCityId=0;
		this.copyView=null;
		//=====================红点相关====================
		this.ifBfRed=false;
		this.ifKfRed=false;
		this._model=Model.qunxiongzhengba;
		this._kuafuDic=new Dictionary();
		CopyTipMgr.ins.regisCopyTip(2030,Handler.create(this,this.closeTips,null,false));
		CopyTipMgr.ins.regisCopyTip(2034,Handler.create(this,this.closeTips,null,false));
		this._red=Mgr.red;
	}

	__class(QunXiongZhengBaMgr,'com.xq.modules.gvg.qunxiongzhengba.QunXiongZhengBaMgr');
	var __proto=QunXiongZhengBaMgr.prototype;
	/**刷新城池数据*/
	__proto.updateInfo=function(msg){
		this._myCity=[];
		this._model.cityDc.clearEleValue("s");
		var arr=msg.infos;
		var len=arr.length;
		this._kuafuDic.clear();
		for(var i=0;i<len;i++){
			var info=arr[i];
			var id=info.manorId;
			var ele=this._model.cityDc.getElement(id);
			if(ele){
				ele.setValue("s",info);
				if(info.guild){
					var cof=ele.getCfgData();
					var type=cof.gjId;
					if(type){
						var vo=this._kuafuDic.get(info.guild);
						if(!vo){
							vo=new QXZBKuaFuRankVo();
							this._kuafuDic.set(info.guild,vo);
							vo.setData(info);
						}
						vo.cityNum++;
					}
				}
				if(Mgr.guild.checkMyGuild(info.guild)){
					this._myCity.push(ele);
				}
			}
		}
		this.UpdateBenfuRankList();
		this.updateKuaFuRankList();
		EventCenter.instance.event("updateQXZBInfo");
		this.updateRed();
	}

	/**刷新城池奖励状态*/
	__proto.updateReward=function(msg){
		var id=msg.manorId;
		var ele=this._model.cityDc.getElement(id);
		if(ele){
			var info=ele.getValue("s");
			if(info){
				info.rewardTime=msg.rewardTime;
				info.rewardTimes=msg.rewardTimes;
			}
		}
		EventCenter.instance.event("updateQXZBReward");
		this.updateRed();
	}

	/**更新副本信息*/
	__proto.updateCopyInfo=function(msg){
		var copy=this._model.copyVo;
		if(!copy){
			copy=new QunXiongZhengBaCopyVo();
			this._model.copyVo=copy;
		}
		copy.setData(msg);
		this._attackGuildId=copy.attackerGuild;
		var fightVo=Mgr.fightMgr.curData;
		if(fightVo){
			fightVo.remainTime=copy.endTime-Mgr.curTime.serverTimer;
			EventCenter.instance.event("Refresh_time");
		}
		EventCenter.instance.event("updateQXZBCopyInfo");
	}

	/**传送*/
	__proto.translate=function(msg){
		var player=Game.getInstance().player;
		var pointArr=SceneContainer.GridToGlobal(msg.x,msg.y);
		player.pos(pointArr[0],pointArr[1]);
		EventCenter.instance.event("SEND_SYNC_POS",[player.x,player.y,true]);
		var subArr=Model.subPlayer.subPlayers.values;
		var len=subArr.length;
		for(var i=0;i<len;i++){
			var sub=subArr[i];
			sub.stand();
			sub.pos(pointArr[0],pointArr[1]);
			Mgr.sceneSyn.sendPlayerMove(sub,pointArr,false,true);
		}
		EventCenter.instance.event("updateQXZBTranslate");
	}

	/**结算*/
	__proto.updateResult=function(msg){
		var v=UIMgrR.openIView(com.xq.view.modules.gvg.qunxiongzhengba.IQunXiongZhengBaVic,2);
		v.dataSource=msg;
	}

	__proto.getResultStat=function(msg){
		var attackGuildId=this._attackGuildId;
		var flag=Mgr.guild.checkMyGuild(attackGuildId);
		if(msg.suc){
			if(flag){
				return 2;
			}
			else{
				return 1;
			}
		}
		else{
			if(flag){
				return 4;
			}
			else{
				return 3;
			}
		}
	}

	/**更新怪物复活时间戳*/
	__proto.updateMonster=function(msg){
		var dic=this._model.monsterDic;
		var arr=msg.infos;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var info=arr[i];
			dic.set(info.monsterId,info.reviveTime);
		}
		EventCenter.instance.event("updateQXZBMonsterInfo");
	}

	/**根据怪物Id获取*/
	__proto.getReviveTimeById=function(id){
		var time=this._model.monsterDic.get(id);
		if(!time){
			return 0;
		}
		return time;
	}

	/**推送给帮派玩家攻守消息*/
	__proto.updateAttackInfo=function(msg){
		this.battleCityId=msg.manorId;
		this.createNoticeBall();
		if(this.ifMeInitiate){
			this.ifMeInitiate=false;
			return;
		};
		var v=UIMgrR.openIView(com.xq.view.modules.gvg.qunxiongzhengba.IQunXiongZhengBaAttackTip,2);
		v.dataSource=msg;
	}

	/**更新日志*/
	__proto.updateLog=function(msg){
		var arr=msg.infos;
		arr=arr.sort(this.compareLog);
		this._model.logArr=arr;
		EventCenter.instance.event("updateQXZBLogInfo");
	}

	__proto.compareLog=function(a,b){
		var timeA=a.logTime;
		var timeB=b.logTime;
		return timeB-timeA;
	}

	/**获取本服排行*/
	__proto.UpdateBenfuRankList=function(){
		var dc=this._model.getCity(0);
		var arr=dc.array.concat();
		arr=arr.sort(this.compareCity);
		var len=arr.length;
		var rankList=[];
		for(var i=0;i<len;i++){
			var vo=new QXZBBenFuRankVo();
			vo.setData(arr[i]);
			vo.rank=i+1;
			rankList.push(vo);
		}
		this._model.benfuRankList=rankList;
	}

	/**按 城池等级 > id 来排序*/
	__proto.compareCity=function(a,b){
		var cofA=a.getCfgData();
		var cofB=b.getCfgData();
		var lvA=cofA.level;
		var lvB=cofB.level;
		if(lvA==lvB){
			return cofA.id-cofB.id;
		}
		return lvB-lvA;
	}

	__proto.updateKuaFuRankList=function(){
		var arr=this._kuafuDic.values.concat();
		arr=arr.sort(this.compareKuaFu);
		var len=arr.length;
		for(var i=0;i<len;i++){
			arr[i].rank=(i+1);
		}
		this._model.kuafuRankList=arr;
	}

	__proto.compareKuaFu=function(a,b){
		return b.cityNum-a.cityNum;
	}

	/**获取日志状态
	*1：我 攻击成功
	*2：我 防守成功
	*3：我 进攻失败
	*4：我 防守失败
	*5：其他
	**/
	__proto.getLogStat=function(msg){
		var guildId=NetMgr.ins().roleVO.guildId;
		if(guildId==msg.attackerId){
			if(msg.isAttackSuc){
				return 1;
			}
			else{
				return 3;
			}
			}else if(guildId==msg.defenceId){
			if(msg.isAttackSuc){
				return 4;
			}
			else{
				return 2;
			}
		}
		else{
			return 5;
		}
	}

	/**设置选中城池Id*/
	__proto.setSelect=function(id){
		if(this.selectCity==id)return;
		this.selectCity=id;
		if(id==-1)return;
		EventCenter.instance.event("updateQXZBSelectCity");
	}

	/**获取城池状态
	*1：本帮占领
	*2：无人占领
	*3：别帮占领
	*4：未开启
	**/
	__proto.getCityStat=function(ele){
		var info=ele.getValue("s");
		var cof=ele.getCfgData();
		if(cof.openday>CommonUtil.openServerDay){
			return 4;
		}
		if(!info||!info.guild){
			return 2;
		};
		var myGuildId=NetMgr.ins().roleVO.guildId;
		if(info.guild !=myGuildId){
			return 3;
		}
		return 1;
	}

	/**获取奖励状态
	*1:可领取
	*2:冷却中
	*3:领奖次数满
	*4:无权领取
	**/
	__proto.getRewardStat=function(ele){
		var ifMeCity=this.getCityStat(ele)==1;
		if(ifMeCity){
			var cof=ele.getCfgData();
			var info=ele.getValue("s");
			var curTime=Mgr.curTime.serverTimer;
			var limit=cof.rewardTimes;
			if(info.rewardTimes>=limit){
				return 3;
			}
			if(curTime<info.rewardTime){
				return 2;
			}
			return 1;
		}
		return 4;
	}

	/**获取默认选中城池
	*0：本服
	*1：跨服
	**/
	__proto.getDefualtSelect=function(type){
		var arr=this._model.getCity(type).array.concat();
		if(!arr||arr.length==0)return-1;
		arr=arr.sort(this.compareDefualt);
		var ele=arr[0];
		var id=ele.getCfgData().id;
		return id;
	}

	__proto.compareDefualt=function(a,b){
		var statA=Mgr.qunxiongzhengbaM.getCityStat(a);
		var statB=Mgr.qunxiongzhengbaM.getCityStat(b);
		if(statA==statB){
			var cofA=a.getCfgData();
			var cofB=b.getCfgData();
			var lvA=cofA.level;
			var lvB=cofB.level;
			if(lvA==lvB){
				return cofA.id-cofB.id;
			}
			return lvB-lvA;
		}
		return statA-statB;
	}

	/**检测城池是否处于战争中
	*0:没有处于战争中
	*1:我是进攻者
	*2:我是防守者
	*3:与我无关的战争
	**/
	__proto.getBattleStat=function(ele){
		var info=ele.getValue("s");
		if(!info)return 0;
		var myGuildId=NetMgr.ins().roleVO.guildId;
		var attackId=info.attackerId;
		var defenceId=info.guild;
		if(attackId!=0){
			if(attackId==myGuildId){
				return 1;
			}
			else if(defenceId==myGuildId){
				return 2;
			}
			else{
				return 3;
			}
		}
		return 0;
	}

	/**是否处于休赛期
	*0:未在休赛期
	*1:打完架休赛
	*2:活动没开
	**/
	__proto.getOffseasonStat=function(ele){
		var info=ele.getValue("s");
		if(!info)return 0;
		if(NewActiveManager.ins.checkIsOpen(189)){
			if(info.attackTime>Mgr.curTime.serverTimer){
				return 1;
			}
			else{
				return 0;
			}
		}
		return 2;
	}

	/**根据帮派等级获取最大可占领城池数量*/
	__proto.getCityMaxByLv=function(lv){
		return this._model.getCityMaxByLv(lv);
	}

	/**我的城池数量*/
	__proto.getMyCityNum=function(){
		return this._myCity?this._myCity.length:0;
	}

	__proto.checkCityFull=function(){
		var myGuildLv=Mgr.guild.guildLevel;
		var num=this.getCityMaxByLv(myGuildLv);
		return num?this.getMyCityNum()>=num:true;
	}

	/**检测我帮是否是攻方*/
	__proto.checkAttackGuild=function(){
		var copyVo=this._model.copyVo;
		if(!copyVo)return false;
		var attackId=copyVo.attackerGuild;
		return Mgr.guild.checkMyGuild(attackId);
	}

	/**群雄争霸信息数据*/
	__proto.initFightVo=function(fightVo){
		this.showTips();
		fightVo.hideAry=[1,2];
		fightVo.closeFun=Handler.create(Mgr.qunxiongzhengbaA,Mgr.qunxiongzhengbaA.c_exit,null,false);
		if(this._model.copyVo){
			fightVo.remainTime=this._model.copyVo.endTime-Mgr.curTime.serverTimer;
		}
	}

	__proto.showTips=function(){
		this.copyView=UIMgrR.openIView(com.xq.view.modules.gvg.qunxiongzhengba.IQunXiongZhengBaCopyView,2);
	}

	__proto.closeTips=function(){
		if(this.copyView&&this.copyView.isPopup){
			this.copyView.close();
			this.copyView=null;
		}
	}

	//注册逻辑放在guildMgr统一管理
	__proto.updateRed=function(){
		if(!Mgr.guide.isOpen("qunxiongzhengbacopy")){
			this._red.hideAll("qunxiongzhengbacopy");
			return;
		}
		this.ifKfRed=false;
		this.ifBfRed=false;
		var arr=this._model.cityDc.array;
		var len=arr.length;
		var minTime=0;
		for(var i=0;i<len;i++){
			var ele=arr[i];
			var cof=ele.getCfgData();
			var stat=this.getCityStat(ele);
			if(stat==1){
				var rewardStat=this.getRewardStat(ele);
				if(rewardStat==1){
					this._red.showRedPoint("qunxiongzhengbacopy","city"+cof.id,"GVGQunXiongZhengBaRed");
					if(cof.gjId){
						this.ifKfRed=true;
					}
					else{
						this.ifBfRed=true;
					}
				}
				else{
					this._red.hideRedPoint("qunxiongzhengbacopy","city"+cof.id,"GVGQunXiongZhengBaRed");
					if(rewardStat==2){
						var info=ele.getValue("s");
						var time=info.rewardTime-Mgr.curTime.serverTimer;
						if(minTime==0){
							minTime=time;
						}
						else if(minTime>time){
							minTime=time;
						}
					}
				}
			}
			else{
				this._red.hideRedPoint("qunxiongzhengbacopy","city"+cof.id,"GVGQunXiongZhengBaRed");
			}
		}
		if(minTime){
			Laya.timer.once(minTime,this,this.updateRed);
		}
	}

	//主界面气泡弹窗
	__proto.createNoticeBall=function(){
		var vo=new CommonNoticeVo();
		var type=CommonNoticeType.QXZBCopy;
		var handler=Handler.create(this,this.onClickBall,null,false);
		vo.setDat(type,"",handler);
		NoticeManager.ins.addNotice(vo);
	}

	__proto.onClickBall=function(){
		var cityId=Mgr.qunxiongzhengbaM.battleCityId;
		var ele=Model.qunxiongzhengba.getCityById(cityId);
		if(!ele)return;
		var cof=ele.getCfgData();
		var type=cof.gjId;
		this.selectType=type;
		UIMgrR.openViewByFunID("qunxiongzhengbacopy");
	}

	__proto.removeNoticeBall=function(){
		NoticeManager.ins.removeNotice(CommonNoticeType.QXZBCopy);
	}

	/**
	*@private
	*/
	/**选中跨服类型*/
	__getset(0,__proto,'selectType',function(){
		return this._selectType;
		},function(value){
		this._selectType=value;
	});

	//刷新后端数据
	__getset(0,__proto,'battleCityId',function(){
		return this._battleCityId;
		},function(value){
		this._battleCityId=value;
	});

	__getset(0,__proto,'selectCity',function(){
		return this._selectCity;
		},function(value){
		this._selectCity=value;
	});

	return QunXiongZhengBaMgr;
})()


/**
*问鼎天下Mgr
*@author huanghong
*2020-12-16
*/
//class com.xq.modules.gvg.wendingtianxia.WenDingTianXiaMgr
var WenDingTianXiaMgr=(function(){
	function WenDingTianXiaMgr(){
		this.ifFirstArea=false;
		this._model=null;
		this._red=null;
		this._ifOpen=false;
		this.copyView=null;
		//主界面气泡弹窗
		this.ball=null;
		this._red=Mgr.red;
		this._model=Model.wendingtianxia;
		CopyTipMgr.ins.regisCopyTip(2029,Handler.create(this,this.closeTips,null,false));
	}

	__class(WenDingTianXiaMgr,'com.xq.modules.gvg.wendingtianxia.WenDingTianXiaMgr');
	var __proto=WenDingTianXiaMgr.prototype;
	/**刷新数据*/
	__proto.updateInfo=function(msg){
		this._model.updateInfo(msg);
		EventCenter.instance.event("updateInfo");
		if(this._ifOpen){
			if(this.checkGuild()){
				this.createNoticeBall();
			}
		}
	}

	/**更新副本信息*/
	__proto.updateCopyInfo=function(msg){
		this._model.updateCopyInfo(msg);
		var fightVo=Mgr.fightMgr.curData;
		if(fightVo){
			fightVo.remainTime=msg.endTime-Mgr.curTime.serverTimer;
			EventCenter.instance.event("Refresh_time");
		}
		EventCenter.instance.event("updateCopyInfo");
	}

	/**推送旗帜消息*/
	__proto.updateCollectInfo=function(msg){
		this._model.flagOpInfo=msg;
		var type=msg.type;
		switch(type){
			case 1:{
					break ;
				}
			case 2:{
					break ;
				}
			case 3:{
					var copyInfo=this._model.copyInfoVo;
					if(copyInfo){
						copyInfo.baqizheId=msg.roleId;
						copyInfo.baqizhename=msg.roleName;
						copyInfo.baqizheGuildId=copyInfo.attackerGuild;
					}
					break ;
				}
			case 4:{
					copyInfo=this._model.copyInfoVo;
					if(copyInfo){
						copyInfo.baqizheId=0;
						copyInfo.baqizhename="";
						copyInfo.baqizheGuildId=0;
					}
					break ;
				}
			}
		EventCenter.instance.event("updateCollectFlag",type);
		console.log("WDTX刷新旗帜采集状态:"+type);
	}

	/**更新胜利时间戳*/
	__proto.updateWinTime=function(msg){
		var copyInfo=this._model.copyInfoVo;
		if(copyInfo){
			copyInfo.winTime=msg.winTime;
			EventCenter.instance.event("updateWinTime");
			console.log("WDTX刷新胜利时间戳:"+copyInfo.winTime);
		}
	}

	/**传送*/
	__proto.translate=function(msg){
		var player=Game.getInstance().player;
		var pointArr=SceneContainer.GridToGlobal(msg.x,msg.y);
		player.pos(pointArr[0],pointArr[1]);
		EventCenter.instance.event("SEND_SYNC_POS",[player.x,player.y,true]);
		var subArr=Model.subPlayer.subPlayers.values;
		var len=subArr.length;
		for(var i=0;i<len;i++){
			var sub=subArr[i];
			sub.stand();
			sub.pos(pointArr[0],pointArr[1]);
			Mgr.sceneSyn.sendPlayerMove(sub,pointArr,false,true);
		}
		this.ifFirstArea=this.checkFirstArea(msg.x+":"+msg.y);
		EventCenter.instance.event("updateTranslate");
		console.log("WDTX传送成功:"+pointArr);
	}

	/**更新积分*/
	__proto.updateJF=function(msg){
		var copyInfo=this._model.copyInfoVo;
		if(copyInfo){
			copyInfo.curJf=msg.score;
			EventCenter.instance.event("updateJiFen");
			console.log("WDTX刷新当前副本积分:"+copyInfo.curJf);
		}
	}

	/**结算*/
	__proto.updateResult=function(msg){
		var v=UIMgrR.openIView(com.xq.view.modules.gvg.wendingtianxia.IWenDingTianXiaResult,2);
		v.dataSource=msg;
		v.zOrder=1001;
	}

	/**展示建国提示*/
	__proto.showJgTips=function(msg){
		var v=UIMgrR.openIView(com.xq.view.modules.gvg.wendingtianxia.IWenDingTianXiaJianGuo,2);
		v.dataSource=msg;
	}

	/**展示建国奖励提示*/
	__proto.showJgReward=function(msg){
		var v=UIMgrR.openIView(com.xq.view.modules.gvg.wendingtianxia.IWenDingTianXiaJGReward,2);
		v.dataSource=msg;
	}

	__proto.updateJfRewardInfo=function(msg){
		this._model.curJf=msg.score;
		var arr=msg.rewardIds;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var id=arr[i];
			var ele=this._model.rewardDc.getElement(id);
			if(ele){
				ele.setValue("got",true);
			}
		}
		EventCenter.instance.event("updateJiFenReward");
		this.updateRed();
	}

	__proto.updateRewardStat=function(msg){
		var id=msg.rewardId;
		var ele=this._model.rewardDc.getElement(id);
		if(ele){
			ele.setValue("got",true);
		}
		EventCenter.instance.event("updateJiFenReward");
		console.log("WDTX领取奖励成功:"+id);
		this.updateRed();
	}

	__proto.getJfRewardArr=function(){
		var arr=this._model.rewardDc.array.concat();
		arr=arr.sort(this.compare);
		return arr;
	}

	/**积分奖励状态
	*1：可领取
	*2：未达成
	*3：已领取
	**/
	__proto.getJfRewardStat=function(ele){
		var ifGot=ele.getValue("got");
		if(ifGot){
			return 3;
		};
		var curJf=this._model.curJf;
		var cof=ele.getCfgData();
		var score=cof.score;
		if(curJf>=score){
			return 1;
		}
		return 2;
	}

	__proto.compare=function(a,b){
		var statA=Mgr.wendingtianxiaM.getJfRewardStat(a);
		var statB=Mgr.wendingtianxiaM.getJfRewardStat(b);
		if(statA==statB){
			return a.getCfgData().id-b.getCfgData().id
		}
		return statA-statB;
	}

	/**检测是否传送到了第一区域*/
	__proto.checkFirstArea=function(pos){
		var ele=this._model.transDc.getElement(pos);
		if(ele){
			var cof=ele.getCfgData();
			if(cof.area==1){
				return true;
			}
			else{
				return false;
			}
		}
		return false;
	}

	/**检测攻防帮派
	*0：不关我什么事
	*1：我是攻击者
	*2：我是防守者
	**/
	__proto.checkGuild=function(){
		var guild=NetMgr.ins().roleVO.guildId;
		if(guild==0)return 0;
		if(guild==this._model.infoVo.attacker.guildId){
			return 1;
		}
		else if(guild==this._model.infoVo.defencer.guildId){
			return 2;
		}
		else{
			return 0;
		}
	}

	/**获取结果状态
	*1：赢了 老大
	*2：赢了 普通群众
	*3：输了
	**/
	__proto.getResultStat=function(msg){
		var winGuildid=msg.winGuild;
		if(!Mgr.guild.checkMyGuild(winGuildid)){
			return 3;
		}
		else{
			if(Mgr.guild.checkGuidLeader()){
				return 1;
			}
			else{
				return 2;
			}
		}
	}

	/**
	*获取旗帜状态
	*1：无人占领
	*2：友军占领
	*3：敌军占领
	**/
	__proto.getFlagStat=function(){
		var copyInfo=this._model.copyInfoVo;
		if(copyInfo){
			if(copyInfo.baqizheId){
				var guild=NetMgr.ins().roleVO.guildId;
				if(guild==copyInfo.attackerGuild){
					return 2;
				}
				else{
					return 3;
				}
			}
			else{
				return 1;
			}
		}
		return 1;
	}

	/**根据类型获取奖励展示配置*/
	__proto.getRewardByType=function(type){
		var dc=this._model.showRewDc.where("type",type,"id");
		return dc.array;
	}

	//副本相关
	__proto.initFightVo=function(fightVo){
		this.showTips();
		fightVo.hideAry=[1,2];
		fightVo.closeFun=Handler.create(Mgr.qunxiongzhengbaA,Mgr.qunxiongzhengbaA.c_exit,null,false);
		if(this._model.copyInfoVo){
			fightVo.remainTime=this._model.copyInfoVo.endTime-Mgr.curTime.serverTimer;
		}
	}

	__proto.showTips=function(){
		this.copyView=UIMgrR.openIView(com.xq.view.modules.gvg.wendingtianxia.IWenDingTianXiaCopyView,2);
	}

	__proto.closeTips=function(){
		if(this.copyView&&this.copyView.isPopup){
			this.copyView.close();
			this.copyView=null;
		}
	}

	//===============红点相关=======================
	__proto.updateRed=function(){
		var arr=this._model.rewardDc.array;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var ele=arr[i];
			var stat=this.getJfRewardStat(ele);
			if(stat==1){
				this._red.showRedPoint("wendingtianxiacopy","jifen","GVGWDTXRed");
				return;
			}
		}
		this._red.hideRedPoint("wendingtianxiacopy","jifen","GVGWDTXRed");
	}

	//===============活动开关相关===================
	__proto.openWDTX=function(){
		this._ifOpen=true;
		Mgr.wendingtianxiaA.c_getInfo(false);
	}

	__proto.closeWDTX=function(){
		this._ifOpen=false;
		this.removeNoticeBall();
	}

	__proto.registAtc=function(){
		NewActiveManager.ins.regActOpenHandler(190,Handler.create(this,this.openWDTX,null,false));
		NewActiveManager.ins.regActEndHandler(190,Handler.create(this,this.closeWDTX,null,false));
	}

	__proto.createNoticeBall=function(){
		EventCenter.instance.on("ENTER_SCENE",this,this.hideBall);
		this.hideBall();
		var vo=new CommonNoticeVo();
		var type=CommonNoticeType.WDTXCopy;
		var handler=Handler.create(this,this.onClickBall,null,false);
		vo.setDat(type,"",handler);
		NoticeManager.ins.addNotice(vo);
	}

	__proto.onClickBall=function(){
		UIMgrR.openViewByFunID("wendingtianxiacopy");
	}

	__proto.removeNoticeBall=function(){
		EventCenter.instance.off("ENTER_SCENE",this,this.hideBall);
		NoticeManager.ins.removeNotice(CommonNoticeType.WDTXCopy);
	}

	__proto.hideBall=function(){
		var rolevo=NetMgr.ins().roleVO;
		if(MapType.isCopy(rolevo.mapType)){
			NoticeManager.ins.hideNotice(true);
		}
		else{
			NoticeManager.ins.hideNotice(false);
		}
	}

	return WenDingTianXiaMgr;
})()


