	// debugger
	__proto.createHancockArr=function(msg){
		var rankRoleInfo={};
		var len=msg.rankRoleInfoList.length;
		this.maxValue=0;
		for (var i2=0;i2 < len;i2++){
			var rankInfo=msg.rankRoleInfoList[i2];
			if(rankInfo){
				rankRoleInfo[msg.rankRoleInfoList[i2].rank]=msg.rankRoleInfoList[i2];
				if(this.maxValue<rankInfo.levelOrZhanli){
					this.maxValue=rankInfo.levelOrZhanli;
				}
			}
		};
		var cfgArr=this.hancockCfgTab.getItemsByField("ranktype",msg.rankType+"");
		var len1=cfgArr.length;
		var lastCfg=cfgArr[cfgArr.length-1];
		if(!lastCfg){
			debugger;
		};
		var lastRank=parseInt(lastCfg.rank.split("|")[1]);
		var limitObj=cfgArr[cfgArr.length-1];
		this._isJinJieXian=limitObj.stepranktype=="1";
		this.minRank=parseInt(limitObj.limit);
		this.rankNum=lastRank;
		this.hancockInfo=cfgArr[0];
		this.flag=this.hancockInfo.flag;
		this.needItemArr=this.hancockInfo.djId.split(";");
		this.skipId=parseInt(this.hancockInfo.mediator);
		this.explainCode=parseInt(this.hancockInfo.explain);
		this.nextRank=this.hancockInfo.explain1;
		this.res=this.hancockInfo.res;
		this.hancockBtnSkin=this.hancockInfo.icon;
		this.resHeight=this.hancockInfo.mainY;
		this.pathArr=this.hancockInfo.djshow.split(";");
		this.resScale=parseFloat(this.hancockInfo.mainSize);
		this.modelPos=this.hancockInfo.xy.split(":");
		this.modelScale=parseFloat(this.hancockInfo.size);
		this.hancockArr=[];
		for (var i=0;i < lastRank;i++){
			var hancockItem=new ChongBangInfoMsg();
			if(rankRoleInfo[i+1]){
				hancockItem=rankRoleInfo[i+1];
				for (var k=0;k < len1;k++){
					var hancockCfg=cfgArr[k];
					var params=hancockCfg.rank.split("|");
					var min=parseInt(params[0]);
					var max=parseInt(params[1]);
					if(hancockItem.rank >=min && hancockItem.rank <=max){
						hancockItem["limit"]=hancockCfg.limit;
						hancockItem["mainHint"]=hancockCfg.mainHint;
						hancockItem["tipshow"]=hancockCfg.tipshow;
						break ;
					}
				}
				this.lastIndex=i;
			}
			else{
				if(!this.lastIndex)
					this.lastIndex=i-1;
				hancockItem.rewardIdList=[];
				hancockItem.rank=i+1;
				var rewardArr;
				for (var k=0;k < len1;k++){
					var hancockCfg=cfgArr[k];
					var min=parseInt(hancockCfg.rank.split("|")[0]);
					var max=parseInt(hancockCfg.rank.split("|")[1]);
					if(hancockItem.rank >=min && hancockItem.rank <=max){
						rewardArr=hancockCfg.reward.split(";");
						rewardArr.pop();
						hancockItem["limit"]=hancockCfg.limit;
						hancockItem["mainHint"]=hancockCfg.mainHint;
						hancockItem["tipshow"]=hancockCfg.tipshow;
						break ;
					}
				}
			}
			this.hancockArr.push(hancockItem);
		};
		var rewardCfgArr=this.hancockCfgTab.getItemsByField("ranktype",msg.rankType+"");
		var _rewardArr=rewardCfgArr.concat([]);
		this.firstCfgInfo=_rewardArr[0];
		this.rewardShowArr=_rewardArr;
		this.rankList(this.hancockArr);
		this.openHancockGuide();
	}

