	/**根据排名获取 名字 或者 上榜多少人*/
	__proto.getRankTip=function(r1,r2){
		if(!this.hancockArr)return "";
		var arr=this.hancockArr;
		var len=arr.length;
		var ChongBangVo;
		if(r1==r2){
			for(var i=0;i<len;i++){
				ChongBangVo=arr[i];
				if(ChongBangVo.rank==r1){
					return ChongBangVo.roleName?ChongBangVo.roleName:"虚位以待";
				}
			}
			return "虚位以待";
		}
		else{
			var count=0;
			for(i=0;i<len;i++){
				ChongBangVo=arr[i];
				if(ChongBangVo.rank >=r1&&ChongBangVo.rank<=r2){
					if(ChongBangVo.roleName){
						count++;
					}
				}
			}
			return"已有"+count+"位玩家上榜";
		}
	}

