//class com.xq.modules.jiesuan.FailMgr
var FailMgr=(function(){
	function FailMgr(){
		this.failSkipPanelTab=null;
		this.failSkipPanelTab=CfgManager.getTableCfg("failSkipPanel");
	}

	__class(FailMgr,'com.xq.modules.jiesuan.FailMgr');
	var __proto=FailMgr.prototype;
	__proto.getSkipObj=function(){
		var arr=this.failSkipPanelTab.objectDataArray;
		var len=arr.length;
		for (var i=0;i < len;i++){
			if(this.isSkipById(parseInt(arr[i].id))){
				return arr[i];
			}
		}
		return null;
	}

	__proto.isSkipById=function(id){
		switch(id){
			case 1:{
					return Mgr.kaiFuHDMgr.progress==0;
					break ;
				}
			case 2:{
					return !Mgr.hfMgr.isBuy;
					break ;
				}
			case 3:{
					return !Mgr.qlbMgr.isBuy;
					break ;
				}
			case 4:{
					return !Mgr.chaoZhiTeDianMgr.isBuyZz;
					break ;
				}
			case 5:{
					return true;
					break ;
				}
			}
		return false;
	}

	return FailMgr;
})()


/**
*经脉管理类
*@author zhanglimin
*@date 2019-11-7
*/
//class com.xq.modules.jingmai.JingMaiMgr
var JingMaiMgr=(function(){
	function JingMaiMgr(){
		this.zlCfg=null;
		this.gmCfg=null;
		/**经脉类型数据*/
		this.jmAry=null;
		/**储存经脉的相同阶数的个数*/
		this.jieObj={};
		/**类型存储阶*/
		this.typeJie={};
		this.red=null;
		/**最大共鸣等级*/
		this.maxGmLv=0;
		this.jmCfgCha={};
		this.gmCfgCha={};
		this.totFig=0;
		this.gongMingFig=0;
		this.zlCfg=CfgManager.getTableCfg("zhanlin");
		this.gmCfg=CfgManager.getTableCfg("zhanlingongming");
		this.maxGmLv=this.gmCfg.objectDataArray.length;
		this.jmList();
		EventCenter.instance.on("GET_PAYLINE_INFO_UPDATE",this,this.onInfo);
		this.red=Mgr.red;
		this.red.regist("role","zhanlingframe",false,RedTypeEnum.RoleOneMenuRed);
		this.red.regist("zhanlingframe","jingjiezhanling",false,RedTypeEnum.RoleOneMenuRed);
		EventCenter.instance.on("CURRENCY_CHANGE" ,this ,this.checkRed);
		EventCenter.instance.on("ActGMEvent" ,this ,this.checkRed);
		this.checkRed();
	}

	__class(JingMaiMgr,'com.xq.modules.jingmai.JingMaiMgr');
	var __proto=JingMaiMgr.prototype;
	__proto.checkRed=function(){
		var bo=false;
		if(Mgr.guide.isOpen("jingjiezhanling")){
			var len=this.jmAry.length;
			for (var i=0;i < len;i++){
				var curMsg=Mgr.payLine.getPayLineInfo(this.jmAry[i]);
				if(curMsg){
					if(curMsg.stars==9){
						var obj=this.getJmCfg(curMsg.type,curMsg.jieshu+1,0);
					}
					else{
						obj=this.getJmCfg(curMsg.type,curMsg.jieshu,curMsg.stars+1);
					}
					if(!obj)
						continue ;
					if(Mgr.jmMgr.checkIsOpen(obj.type)){
						var key=RedTypeEnum.ZhanLingMatRed+"_"+curMsg.type;
						this.red.hideRedPoint("jingjiezhanling",key,RedTypeEnum.RoleOneMenuRed);
						if(obj){
							if(parseInt(obj.money)!=0 && NetMgr.ins().roleVO.coin >=parseInt(obj.money)){
								this.red.showRedPoint("jingjiezhanling",key,RedTypeEnum.RoleOneMenuRed);
								bo=true;
							}
						}
					}
				}
			};
			var gmId=Mgr.jmAct.gmId;
			if(gmId < 1){
				var curObj=this.getGmCfgById(1);
			}
			else{
				curObj=this.getGmCfgById(gmId+1);
			}
			if(curObj){
				var aim=this.getGmNum(curObj.jie);
				if(aim >=curObj.num){
					this.red.showRedPoint("jingjiezhanling",RedTypeEnum.ZhanLingGmRed,RedTypeEnum.RoleOneMenuRed);
					bo=true;
				}
				else{
					this.red.hideRedPoint("jingjiezhanling",RedTypeEnum.ZhanLingGmRed,RedTypeEnum.RoleOneMenuRed);
				}
			}
			else{
				this.red.hideRedPoint("jingjiezhanling",RedTypeEnum.ZhanLingGmRed,RedTypeEnum.RoleOneMenuRed);
			}
		}
		if(bo){
			this.red.showRedPoint("jingjiezhanling",RedTypeEnum.ZhanlingRed,RedTypeEnum.RoleOneMenuRed);
		}
		else{
			this.red.hideRedPoint("jingjiezhanling",RedTypeEnum.ZhanlingRed,RedTypeEnum.RoleOneMenuRed);
		}
	}

	/**更新通信信息*/
	__proto.onInfo=function(type){
		if(PayLineType.jmAry.indexOf(type)!=-1){
			var msg=Mgr.payLine.getPayLineInfo(type);
			if(!msg.activeState){
				Mgr.payLinePro.reqActiveSystem(type);
			}
			else{
				this.typeJie[msg.type]=msg.jieshu;
			}
			this.setNum();
			this.checkRed();
		}
	}

	__proto.checkIsOpen=function(type){
		var lv=this.getOpenLv(type);
		if(Mgr.fhProMgr.baijiangLevel < lv){
			return false;
		}
		return true;
	}

	__proto.setNum=function(){
		this.jieObj={};
		for (var type in this.typeJie){
			var jie=this.typeJie[type];
			var num=this.jieObj[jie];
			if(!num){
				num=1;
			}
			else{
				num+=1;
			}
			this.jieObj[jie]=num;
			for (var i=1;i < jie;i++){
				if(!this.jieObj[i]){
					this.jieObj[i]=1
				}
				else
				this.jieObj[i]+=1;
			}
		}
	}

	/**根据阶数获取达到条件经脉数*/
	__proto.getGmNum=function(jie){
		var num=this.jieObj[jie];
		if(!num)
			num=0;
		return num;
	}

	/**获取经脉类型列表*/
	__proto.jmList=function(){
		if(!this.jmAry){
			this.jmAry=[];
			var ary=this.zlCfg.objectDataArray;
			var len=ary.length;
			for (var i=0;i < len;i++){
				var obj=ary[i];
				if(this.jmAry.indexOf(obj.type)==-1){
					this.jmAry.push(obj.type);
				}
			}
		}
		return this.jmAry;
	}

	/**根据类型、阶数、星级获取配置*/
	__proto.getJmCfg=function(type,rank,lv){
		var key=type+"_"+rank+"_"+lv;
		if(!this.jmCfgCha[key]){
			this.jmCfgCha[key]=this.zlCfg.getCfgMsgByThreeKey("type",type,"rank",rank,"level",lv);
		}
		return this.jmCfgCha[key];
	}

	/**根据类型获取开启转生等级*/
	__proto.getOpenLv=function(type){
		var obj=this.zlCfg.getItemByField("type",type);
		return parseInt(obj.openLevel);
	}

	/**根据个数和阶数获取共鸣配置*/
	__proto.getGmCfg=function(num,jie){
		var key=num+"_"+jie;
		if(!this.gmCfgCha[key]){
			this.gmCfgCha[key]=this.gmCfg.getCfgMsgByTwoKey("num",num,"jie",jie);
		}
		return this.gmCfgCha[key];
	}

	/**根据ID获取共鸣配置*/
	__proto.getGmCfgById=function(id){
		return this.gmCfg.getItemByField("id",id);
	}

	/**根据类型获取名称*/
	__proto.getNameByType=function(type){
		var obj=this.zlCfg.getItemByField("type",type);
		return obj.name;
	}

	/**获取总属性*/
	__proto.getTotAttr=function(){
		var len=this.jmAry.length;
		var tempObj={};
		for (var i=0;i < len;i++){
			var curMsg=Mgr.payLine.getPayLineInfo(this.jmAry[i]);
			if(curMsg){
				var obj=this.getJmCfg(curMsg.type,curMsg.jieshu,curMsg.stars);
				if(obj){
					tempObj=CommonUtil.getCfgAdded(tempObj,obj);
				}
			}
		};
		var baseFv=AttributeTypeEnum.getAttrArrTotalFVByCfgMsg(tempObj);
		if(this.totFig==baseFv){
			this.gongMingFig=0;
		}
		else if(this.totFig==0){
			this.totFig=baseFv;
			this.gongMingFig=0;
		}
		else{
			this.gongMingFig=this.totFig-baseFv;
		};
		var ary=CommonUtil.getListAryByCfg(tempObj);
		return ary;
	}

	return JingMaiMgr;
})()


