	__proto.closeAct=function(actId){
		if(actId==17){
			this.red.hideAll("QuanMingJinJieView");
		}
		else if(actId==57){
			this.red.hideAll("kaifuleichonghaoli");
		}
		else if(actId==56){
			this.red.hideAll("quanminchongbangleichong");
		}
		else if(actId==11){
			this.red.hideAll("meirileichong");
		}
		else if(actId==19){
			this.red.hideAll("ShouChongTuanGouView");
		}
		else if(actId==39){
			this.red.hideAll("LianChongHaoLiView");
			EventCenter.instance.event("ACTIVE_TOGGLE",["LianChongHaoLiNew"]);
		}
		else if(actId==62){
			this.red.hideAll("kaiFuLiBao");
			}else if(actId==64){
			EventCenter.instance.event("ACTIVE_TOGGLE",["xiaoFeiPaiHang"]);
			}else if(actId==66){
			EventCenter.instance.event("ACTIVE_TOGGLE",["xiaoFeiPaiHang"]);
		}
	}

