	__proto.showActiveTime=function(endTime){
		if(Mgr.guide.isOpen("shouchonghaoli")){
			var rend=Game.getInstance().newMainView.getCenterRender().getIonRender("shouchonghaoli");
			if(rend && endTime > 0 && endTime-Mgr.curTime.serverTimer > 0){
				if(!this.scTime){
					this.scTime=UIMgrR.newInstanceByIClass(com.xq.view.modules.shouchonghaoli.IShouChongTime);
				}
				this.scTime.dataSource=[endTime];
				this.scTime.pos(-20,-65);
				rend.addChild(this.scTime);
			}
		}
	}

