	/**获取本次活动数据*/
	__proto.getArrData=function(){
		var mrlcCfg=[];
		if(57==this.mrlcType){
			mrlcCfg=this.kfqdMrlcCfg;
			}else if(11==this.mrlcType){
			mrlcCfg=this.fsbMrlcCfg;
			}else{
			mrlcCfg=this.qmcbMrlcCfg;
		}
		if(!mrlcCfg)return [];
		var data=[];
		var len=mrlcCfg.length;
		var lenRewa=this.mrlc_rewards.length;
		for (var j=0;j <lenRewa;j++){
			for (var i=0;i < len;i++){
				var obj=mrlcCfg[i];
				if(obj.id==this.mrlc_rewards[j].id){
					data.push(obj);
				}
			}
		}
		return data;
	}

	__proto.getMrlcReward=function(id){
		var len=this.mrlc_rewards.length;
		for (var i=0;i < len;i++){
			if(id==this.mrlc_rewards[i].id){
				return this.mrlc_rewards[i].awarded;
			}
		}
		return 0;
	}

	__proto.redMrlc=function(){
		var mrlcData=this.getArrData();
		var len=mrlcData.length;
		var string="";
		var stringRed="";
		if(57==this.mrlcType){
			string="MeiRiLeiChongViewA";
			stringRed="kaifuhuodong";
			}else if(11==this.mrlcType){
			string="MeiRiLeiChongView";
			stringRed="FeiShengBangTabRed";
			}else{
			string="MeiRiLeiChongViewB";
			stringRed=RedTypeEnum.QuanMinChongBangRed;
		}
		for (var i=0;i < len;i++){
			if(this.mrlcYuan >=mrlcData[i].targetValue && this.getMrlcReward(mrlcData[i].id)!=2){
				this.red.showRedPoint(string,"mrlc",stringRed);
				if(57==this.mrlcType){
					this.red.showRedPoint("LianChongHaoLiNewRed","mrlcNew","kaifuhuodong");
				}
				return;
				}else{
				this.red.hideRedPoint(string,"mrlc",stringRed);
				if(57==this.mrlcType){
					this.red.hideRedPoint("LianChongHaoLiNewRed","mrlcNew","kaifuhuodong");
				}
			}
		}
	}

