	__proto.redSctg=function(){
		var actID=this.getSctgData(this.actTimeId);
		for (var i=0;i < 5;i++){
			var a_name=this.getTypeData((i+1),actID);
			for (var j=0;j < a_name.length;j++){
				if(Mgr.kaiFuHDMgr.getSctgReward(a_name[j].id)!=1&& this.rechargePlayerNum >=a_name[j].peopleCnt && this.playerRechargeYuanBao >=a_name[j].rmb){
					this.red.showRedPoint("ShouChongTuanGouView","sctg","kaifuhuodong");
					this.red.showRedPoint("LianChongHaoLiNewRed","sctgNew","kaifuhuodong");
					return;
					}else{
					this.red.hideRedPoint("ShouChongTuanGouView","sctg","kaifuhuodong");
					this.red.hideRedPoint("LianChongHaoLiNewRed","sctgNew","kaifuhuodong");
				}
			}
		}
	}

