		EventCenter.instance.event("ACTIVE_TOGGLE",["KaiXueKuangHuan"]);
		EventCenter.instance.event("ACTIVE_TOGGLE",["BianCeKuangHuan"]);
		EventCenter.instance.event("ACTIVE_TOGGLE",["LiDongKuangHuan"]);
		EventCenter.instance.on("UpDataTargetInfoOpraEvent",this,this.kaixuekuanghuanInfo);
		EventCenter.instance.on("GetTargetRewardOpraEvent",this,this.kaixuekuanghuanInfo);
		this.red=Mgr.red;
		this.red.regist("KaiXueKuangHuan",null,true);
		this.red.regist("GuoQingKuangHuan",null,true);
		this.red.regist("BianCeKuangHuan",null,true);
