//class com.xq.modules.kaixueqingdian.XueBaBangMgr
var XueBaBangMgr=(function(){
	function XueBaBangMgr(){
		this.rankInfoSc=null;
		this.rankData=null;
		this.rankEndTime=NaN;
		/**砸蛋榜**/
		this.biancebangCfg=null;
		/**当前版本号 flag*/
		this.flag=0;
		this._isOpen=false;
		//=============================================国旗榜界线分割===========================================
		this.gqMdel=null;
		/**榜单类型Ary*/
		this.bangTypeAry=null;
		//=============================================雪人榜界线分割===========================================
		this.xueRenModel=null;
		this.biancebangCfg=CfgManager.getTableCfg("xuebabang");
		this.bangTypeAry=[107,120,159];
		this.gqMdel=new GuoQiModel();
		this.xueRenModel=new XueRenModel();
	}

	__class(XueBaBangMgr,'com.xq.modules.kaixueqingdian.XueBaBangMgr');
	var __proto=XueBaBangMgr.prototype;
	__proto.regActive=function(){
		ActManager.ins.regist("KaiXueQingDianFrame","XueBaBang",107,"KaiXueQingDianEvent");
		ActManager.ins.regist("GuoQing","ShengQiBang",120,"GuoQingEvent");
		ActManager.ins.regist("bingtianxuediframe","xuerenbang",159,"BingTianXueDiEvent");
		var l=this.bangTypeAry.length;
		var tempThis=Mgr.rankingPro;
		for (var i=0;i < l;i++){
			var type=this.bangTypeAry[i];
			var bcRankHand=Handler.create(tempThis,tempThis.c_getRank,[type],false);
			NewActiveManager.ins.regActOpenHandler(type,bcRankHand);
		}
	}

	/**砸蛋榜Cfg**/
	__proto.getBianCeBangData=function(flag){
		return this.biancebangCfg.getAllItemByFiled("flag",flag);
	}

	__proto.getRankCfg=function(){
		var opAct=NewActiveManager.ins.getActiveVerDic(107);
		if(opAct){
			this.flag=opAct.flag;
		};
		var ary=this.getBianCeBangData(this.flag);
		var rankArr=[];
		var len=ary.length;
		for (var i=0;i < len;i++){
			var aryObj=ary[i];
			var a=aryObj.rank.split("|");
			var min=parseInt(a[0]);
			var max=parseInt(a[1]);
			var leng=1;
			var qujian=max-min;
			if(qujian > leng){
				leng=qujian+1;
			}
			for (var j=0;j < leng;j++){
				var obj={};
				obj["reward"]=aryObj.reward;
				obj["limit"]=aryObj.limit;
				obj["rank"]=min+j;
				obj["name"]=min+j;
				rankArr.push(obj);
			}
		}
		return rankArr;
	}

	//-----------------------学霸榜----------------------
	__proto.getRankDataSc=function(vo){
		this.rankEndTime=vo.endTime;
		this.rankInfoSc=vo;
		this.rankData={};
		var len=vo.list.length;
		for (var i=0;i < len;i++){
			var rankMsg=vo.list[i];
			this.rankData[rankMsg.rank]=rankMsg;
		};
		var opAct=NewActiveManager.ins.getActiveVerDic(vo.type);
		if(opAct){
			if(vo.type==120){
				this.gqMdel.updateServer(vo,opAct.flag);
				this.gqMdel.msgInfo=vo;
				}else if(vo.type==159){
				this.xueRenModel.updateServer(vo,opAct.flag);
				this.xueRenModel.msgInfo=vo;
			}
		}
		EventCenter.instance.event("xuebabang_info");
	}

	__proto.getRankData=function(rank){
		return this.rankData[rank]
	}

	__getset(0,__proto,'isOpen',function(){
		return this._isOpen;
		},function(open){
		this._isOpen=open;
	});

	return XueBaBangMgr;
})()


