//class com.xq.modules.kuaquBoss.KuaQuBossMgr
var KuaQuBossMgr=(function(){
	function KuaQuBossMgr(){
		this.jindibossCfg=null;
		this.guwuCfg=null;
		//----------------------------------------
		this._isActivity=false;
		this.reaminTime=NaN;
		//-----------------------
		this.curId=0;
		this.remainTime=NaN;
		//副本剩余时间
		this.bossBlood=NaN;
		this.buff=0;
		this.ybState=false;
		this.yxbState=false;
		//---------------------------
		this.monsterKill=null;
		this.killerInfo=null;
		this.setup();
	}

	__class(KuaQuBossMgr,'com.xq.modules.kuaquBoss.KuaQuBossMgr');
	var __proto=KuaQuBossMgr.prototype;
	__proto.setup=function(){
		this.jindibossCfg=CfgManager.getTableCfg("bossjindi");
		this.guwuCfg=CfgManager.getTableCfg("bossjindiguwuconfig");
		Mgr.red.regist("bosshall","kuaquboss",true,RedTypeEnum.BossHallRed);
		Mgr.red.regist("kuaquboss","jindiboss",true,"kuaqubosskey");
		CopyTipMgr.ins.regisCopyTip(2028,Handler.create(this,this.closeTips,null,false));
		EventCenter.instance.on("LEVEL_UP",this,this.checkRed);
	}

	__proto.regActive=function(){
		NewActiveManager.ins.regActOpenHandler(168,Handler.create(this,this.openAct,null,false));
		NewActiveManager.ins.regActEndHandler(168,Handler.create(this,this.closeAct,null,false));
	}

	__proto.checkRed=function(){
		if(!Mgr.guide.isOpen("jindiboss"))return false;
		var curCfg=com.xq.modules.kuaquBoss.KuaQuBossMgr.ins.getBossCfg();
		if(curCfg && parseInt(curCfg.level)<=NetMgr.ins().roleVO.level && com.xq.modules.kuaquBoss.KuaQuBossMgr.ins.isActivity){
			Mgr.red.showRedPoint("jindiboss","kuaqubosskey","kuaqubossevent");
			return true;
		}
		Mgr.red.hideRedPoint("jindiboss","kuaqubosskey","kuaqubossevent");
		return false;
	}

	__proto.getBossCfg=function(){
		return this.jindibossCfg.objectDataArray[0];
	}

	__proto.getBossCfgById=function(monsterid){
		var len=this.jindibossCfg.objectDataArray.length;
		var obj;
		for(var i=0;i < len;i++){
			obj=this.jindibossCfg.objectDataArray[i];
			if(obj.monsterid==monsterid){
				return obj;
			}
		}
		return this.jindibossCfg.objectDataArray[0];
	}

	__proto.getGuWuCfg=function(){
		return this.guwuCfg.objectDataArray[0];
	}

	/**天降豪礼活动开启*/
	__proto.openAct=function(){
		this._isActivity=true;
		Mgr.opeAct.sendGetTargetActivity(168);
		var actVo=NewActiveManager.ins.getActiveVerDic(168);
		if(actVo){
			this.reaminTime=actVo.endTime;
		}
		CopyTipMgr.ins.regisCopyTip(2028,Handler.create(this,this.closeTips,null,false));
		this.checkRed();
	}

	/**活动关闭*/
	__proto.closeAct=function(){
		this._isActivity=false;
		this.checkRed();
		this.closeTips();
	}

	__proto.initFightVo=function(fightVo){
		fightVo.hideAry=[2,3,4];
		fightVo.remainTime=this.reaminTime;
		fightVo.closeFun=Handler.create(this,this.closeTips,null,false);
		this.showTip();
	}

	/***/
	__proto.showTip=function(){
		UIMgrR.openIView(com.xq.view.modules.kuaquBoss.dungeon.IBossJinDiCopyView,2);
	}

	__proto.closeTips=function(){
		UIMgrR.closeIView(com.xq.view.modules.kuaquBoss.dungeon.IBossJinDiCopyView);
		Mgr.kuaQuBossAct.reqBossJinDiQuit();
	}

	//----------------------------------------------------------------
	__proto.reqChallenge=function(cfg){
		if(parseInt(cfg.level)> NetMgr.ins().roleVO.level){
			Mgr.prompt.optionPrompt("很抱歉，进入需要等级达到"+cfg.level+"级!");
			return;
		}
		if(!com.xq.modules.kuaquBoss.KuaQuBossMgr.ins.isActivity){
			Mgr.prompt.optionPrompt("很抱歉，活动暂未开启!");
			return;
		}
		Mgr.kuaQuBossAct.reqChallenge(cfg.number);
	}

	//挑战boss禁地 CMD_80205950="80205950";
	__proto.onBossJinDiChallengeSC=function(vo){
		if(vo.errCode !=1){
			Mgr.prompt.optionPrompt("很抱歉，BOSS已经被击败!");
			return;
		}
		this.curId=vo.id;
	}

	// 进入boss禁地副本推送剩余时间 CMD_80205952="80205952";
	__proto.onBossJinDiFubenInfoSC=function(vo){
		this.curId=vo.id;
		this.remainTime=vo.remainTime;
		this.bossBlood=vo.bossBlood;
	}

	//拉取boss禁地鼓舞信息 80205954
	__proto.onBossJinDiGuWuInfoSC=function(vo){
		this.buff=vo.buff;
		this.ybState=vo.ybState;
		this.yxbState=vo.yxbState;
		EventCenter.instance.event("KuaQuBossGuWu");
	}

	__proto.reqBossJinDiGuWuCS=function(moneyType,fubenId,curBuyPrice){
		if(moneyType==1 && this.yxbState){
			Mgr.prompt.optionPrompt("银两鼓舞已达到上限!");
			return;
		}
		if(moneyType==2 && this.ybState){
			Mgr.prompt.optionPrompt("元宝鼓舞已达到上限!");
			return;
		};
		var myMoney=Mgr.moneyMgr.getMoneyByType(moneyType);
		if(myMoney < curBuyPrice){
			Mgr.prompt.optionPrompt(Mgr.moneyMgr.moneyName[ moneyType]+"不足");
			return;
		}
		Mgr.kuaQuBossAct.reqBossJinDiGuWuCS(moneyType,fubenId);
	}

	// 鼓舞操作 80205953
	__proto.onBossJinDiGuWuSC=function(vo){
		if(vo.error !=1){
			Mgr.prompt.optionPrompt("鼓舞失败!");
			return;
		}
		this.buff=vo.buff;
		this.ybState=vo.ybState;
		this.yxbState=vo.yxbState;
		EventCenter.instance.event("KuaQuBossGuWu");
	}

	//boss击杀数据 CMD_80205956="80205956";
	__proto.onBossJinDiMonsterKillSC=function(vo){
		this.monsterKill=vo;
		if(vo.auctionLists && vo.auctionLists.length > 0){
			UIMgrR.openIView(com.xq.view.modules.kuaquBoss.dungeon.IJinDiBossPaiMaiTishiView,2);
			return;
		}
		UIMgrR.openIView(com.xq.view.modules.kuaquBoss.dungeon.IJinDiBossVictory,2);
	}

	/**同步boss击杀信息*/
	__proto.updateKillerInfo=function(msg){
		this.killerInfo=msg;
		EventCenter.instance.event("KuaQuBossKillerInfo");
	}

	//-------------------------------------
	__getset(0,__proto,'isActivity',function(){
		return this._isActivity;
	});

	__getset(1,KuaQuBossMgr,'ins',function(){
		return KuaQuBossMgr._ins=KuaQuBossMgr._ins||new KuaQuBossMgr();
	});

	KuaQuBossMgr._ins=null;
	return KuaQuBossMgr;
})()


