//class com.xq.modules.loginGift.model.LoginGiftMgr
var LoginGiftMgr=(function(){
	function LoginGiftMgr(){
		/**当前_id*/
		this._flag=0;
		/**是否领取了普通奖励*/
		this._normalStat=false;
		/**是否领取了svip奖励*/
		this._svipStat=false;
		/**登录豪礼 dataContainer*/
		this._loginGiftDC=null;
		this._cof=null;
		this._red=null;
		this._cof=CfgManager.getTableCfg("dengluhaoli");
		this.regRed();
	}

	__class(LoginGiftMgr,'com.xq.modules.loginGift.model.LoginGiftMgr');
	var __proto=LoginGiftMgr.prototype;
	__proto.getDataByFlag=function(flag){
		var dc=this.loginGiftDC.where("flag",flag,"id");
		return dc.array.sort(this.compare);
	}

	__proto.compare=function(a,b){
		return a.getValue("Z")-b.getValue("Z");
	}

	__proto.updateData=function(msg){
		this._flag=msg.flag;
		var arr=msg.msg;
		var len=arr.length;
		var ele;
		var stat;
		for(var i=0;i<len;i++){
			stat=arr[i];
			ele=this.loginGiftDC.getElement(stat.id);
			ele.setValue("S",stat.state);
			if(stat.state){
				ele.setValue("Z",(stat.id+10));
			}
		}
		EventCenter.instance.event("updateView");
	}

	/**注册活动 开启 关闭handler*/
	__proto.regActive=function(){
		ActManager.ins.regist("huoDongMain","loginGift",77,"HuoDongIconEvent");
		NewActiveManager.ins.regActOpenHandler(77,Handler.create(this,this.openAct,null,false));
		NewActiveManager.ins.regActEndHandler(77,Handler.create(this,this.endAct,null,false));
		this.endAct();
	}

	//默认关闭
	__proto.openAct=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["loginGift",false]);
		Mgr.loginGiftA.c_getInfo(77);
	}

	__proto.endAct=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["loginGift"]);
	}

	//========================红点=============
	__proto.regRed=function(){
		this._red=Mgr.red;
		this._red.regist("huoDongMain","loginGift",true,"huoDongMain");
		EventCenter.instance.on("VIPLEVEL_CHANGE",this,this.updateRed);
	}

	/**刷新红点*/
	__proto.updateRed=function(){
		var svipLv=NetMgr.ins().roleVO.vipLevel;
		var flag=false;
		var arr=this.getDataByFlag(this.curFlag);
		var len=arr.length;
		for(var i=0;i<len;i++){
			var ele=arr[i];
			var cof=ele.getCfgData();
			if(cof.type==1){
				var stat=ele.getValue("S");
				if(!stat &&svipLv>=cof.sviplevel){
					flag=true;
					break ;
				}
			}
		}
		if(flag){
			this._red.showRedPoint("loginGift","LoginGift_Red","LoginGiftRed");
		}
		else{
			this._red.hideRedPoint("loginGift","LoginGift_Red","LoginGiftRed");
		}
	}

	/**活动剩余时间*/
	__getset(0,__proto,'timeLeft',function(){
		var vo=NewActiveManager.ins.getActiveVerDic(77);
		if(vo){
			return vo.endTime-Browser.now();
		}
		return 0;
	});

	/**LoginGift DataContainer*/
	__getset(0,__proto,'loginGiftDC',function(){
		if(!this._loginGiftDC){
			this._loginGiftDC=new DataContainer();
			var arr=this._cof.objectDataArray;
			var cof;
			var ele;
			var len=arr.length;
			for(var i=0;i<len;i++){
				cof=arr[i];
				ele=new DataElement(cof);
				ele.setValue("Z",cof.id);
				this._loginGiftDC.addElement(cof.id,ele);
			}
		}
		return this._loginGiftDC;
	});

	/**当前Id*/
	__getset(0,__proto,'curFlag',function(){
		return this._flag;
	});

	return LoginGiftMgr;
})()


