var LunHuiJingMgr=(function(){
	function LunHuiJingMgr(){
		/**当前关卡*/
		this.curLv=0;
		/**今日可扫荡次数*/
		this.saoDangTimes=0;
		this.rankArr=null;
		this.myRank=0;
		this.First=null;
		this.model=null;
		this._red=null;
		this.model=Model.lunhuijing;
		this._red=Mgr.red;
	}

	__class(LunHuiJingMgr,'com.xq.modules.lunhuijing.LunHuiJingMgr');
	var __proto=LunHuiJingMgr.prototype;
	__proto.updateInfo=function(msg){
		this.curLv=msg.id;
		this.saoDangTimes=msg.times;
		this.updateRed();
		EventCenter.instance.event("updateLunHuiJing");
	}

	__proto.updateRank=function(msg){
		this.rankArr=msg.ranks;
		this.myRank=msg.rank;
		this.First=this.rankArr[0];
		EventCenter.instance.event("updateLunHuiJingRank");
	}

	__proto.updateSaoDang=function(msg){
		this.saoDangTimes--;
		this.updateRed();
	}

	__proto.updateJieSuan=function(msg){
		if(msg.isWin){
			var id=msg.id;
			var v=UIMgrR.openIView(com.xq.view.modules.lunhuijing.ILunHuiJingVictory,2);
			v.dataSource=id;
			this.curLv=id;
			this.updateRed();
			EventCenter.instance.event("curLvChanged");
		}
		else{
			UIMgrR.openIView(com.xq.view.modules.lunhuijing.ILunHuiJingFail,2);
		}
	}

	/**检测是否通关最大关卡*/
	__proto.checkMaxLv=function(lv){
		var max=this.model.maxLv;
		return lv>=max;
	}

	__proto.initFightVo=function(fightVo){
		fightVo.hideAry=[3];
		fightVo.curFloor=this.curLv+1;
		fightVo.closeFun=Handler.create(Mgr.lunhuijingA,Mgr.lunhuijingA.c_quit,null,false);
		fightVo.aniType=1;
		var ele=this.model.copyDc.getElement(this.curLv+1);
		if(!ele)return;
		var cof=ele.getCfgData();
		fightVo.remainTime=cof.time*1000;
		fightVo.speReward=cof.reward;
	}

	//红点相关
	__proto.updateRed=function(){
		if(!Mgr.guide.isOpen("LunHuiJing"))return;
		var nextId=this.curLv+1;
		var nextEle=this.model.copyDc.getElement(nextId);
		if(nextEle){
			var nextCof=nextEle.getCfgData();
			var needF=nextCof.zhanli;
			if(needF <=NetMgr.ins().roleVO.fightValue){
				this._red.showRedPoint("LunHuiJing","red","LunHuiJingRed");
				return;
			}
		}
		if(this.curLv>0&&this.saoDangTimes>0){
			this._red.showRedPoint("LunHuiJing","red","LunHuiJingRed");
			return;
		}
		this._red.hideRedPoint("LunHuiJing","red","LunHuiJingRed");
	}

	return LunHuiJingMgr;
})()


