//class com.xq.modules.map.alone.AloneMapSpecial
var AloneMapSpecial=(function(){
	function AloneMapSpecial(){
		/**热点数据*/
		this.redPosAry=null;
		/**波数*/
		this.count=0;
		/**单位管理器*/
		this.unitMgr=null;
		/**主角Vo*/
		this.roleVo=null;
		/**场景容器*/
		this.container=null;
		/**主角*/
		this.mainPl=null;
		/**怪物是否已经开始反击*/
		this.monIsWake=false;
		/**怪物Po*/
		this.mtPo=null;
		/**当前Vo*/
		this.aloneVo=null;
		/**下一个刷怪点*/
		this.nextPo=null;
		/**战斗系数*/
		this.fightData=null;
		this._curKillNum=0;
		/**robot数据*/
		this.robotAry=null;
		/**从第二波怪 开始创建机器人*/
		this.robotMark=1;
		/**开始创建机器人关卡*/
		this.starPass=0;
		/**结束创建机器人的关卡*/
		this.endPass=0;
		this._space=100;
		this.gqInfo=null;
		/**3次获取地图信息，没有就抛出错误*/
		this.initCount=0;
		this.monsterDic=new Dictionary();
		this.ins
		var ary=Mgr.cfgMgr.getValueByType(208).split(":");
		this.starPass=parseInt(ary[0]);
		this.endPass=parseInt(ary[1]);
	}

	__class(AloneMapSpecial,'com.xq.modules.map.alone.AloneMapSpecial');
	var __proto=AloneMapSpecial.prototype;
	Laya.imps(__proto,{"com.xq.modules.map.IMapSpecial":true})
	/**进入前准备*/
	__proto.preEnter=function(){}
	/**进入副本*/
	__proto.onEnter=function(tx,ty){
		EventCenter.instance.on("OfflineAndReconnection",this,this.reConnect);
		if(Mgr.gqMgr.gqInfo){
			this.curKillNum=Mgr.gqMgr.gqInfo.killed;
		}
		else{
			this.curKillNum=0;
		}
		this.dispose();
		EventCenter.instance.on("main_skill_targets",this,this.onSkillBack);
		this.unitMgr=UnitManager.ins;
		this.container=Game.getInstance().sceneContainer;
		this.roleVo=NetMgr.ins().roleVO;
		this.mainPl=Game.getInstance().player;
		this.mainPl.curHp=this.roleVo.curHp;
		this.mainPl.maxHp=this.roleVo.maxHp;
		this.mainPl.curSpeed=this.roleVo.velocity || 360;
		this.mainPl.isInSinCopy=true;
		this.initData();
		Laya.timer.loop(10000,this,this.checkHasMon);
	}

	/**断线重连*/
	__proto.reConnect=function(){
		console.log("做了一次断线重连----")
		this.count=0;
	}

	/**数据OK之后在进行场景初始化*/
	__proto.dataOk=function(){
		EventCenter.instance.on("UPDATE_ALONECOPY_POS",this,this.initPlayerPo);
		Laya.timer.once(1000,this,this.checkCanMon);
	}

	__proto.initPlayerPo=function(){
		if(Mgr.gqMgr.isChangeGuaJiDian){
			this.count=0;
		}
		Laya.timer.clear(this,this.checkCanMon);
		if(!Mgr.gqMgr.gqInfo){
			this.checkCanMon();
			return;
		}
		this.gqInfo=Mgr.gqMgr.gqInfo;
		this.fightData=Mgr.cfgMgr.getAloneData(this.gqInfo.nextLevel-1);
		this.createMonsters();
		var po=this.getMonBornPo();
		if(po){
			if(NetMgr.ins().roleVO.level > 1){
				if(Mgr.gqMgr.isChangeGuaJiDian || !MapIdEnum.checkIsGuanQia(NetMgr.ins().roleVO.lastMapId)){
					this.mainPl.pos(po.x,po.y);
					this.mainPl.updatePos();
				}
			};
			var sjAry=SubPlayerModel.ins().getShenJiangNums();
			var len=sjAry.length;
			var rd=NaN;
			var temp=NaN;
			for (var i=0;i < len;i++){
				var sjPl=sjAry[i];
				if(sjPl){
					rd=Math.random()*3+1;
					temp=rd *64;
					sjPl.x=po.x+temp;
					sjPl.y=po.y+temp;
					sjPl.updatePos();
				}
			}
			AIController.ins().startAutoCombat();
		}
	}

	/**创建怪物之前,确认一下关卡信息是否初始化,然后在开始创建怪物*/
	__proto.checkCanMon=function(){
		if(!Mgr.gqMgr.gqInfo){
			this.curKillNum=0;
			Laya.timer.once(500,this,this.checkCanMon);
			}else{
			EventCenter.instance.off("UPDATE_ALONECOPY_POS",this,this.initPlayerPo);
			this.initPlayerPo();
		}
	}

	/**怪物进入*/
	__proto.onMonsterEnter=function(monster){}
	/**做一次同场景切换*/
	__proto.onEnterAgain=function(tx,ty){
		debugger
	}

	/**推出*/
	__proto.onExit=function(){
		if(this.mainPl)
			this.mainPl.isInSinCopy=false;
	}

	/**释放怪物资源*/
	__proto.dispose=function(){
		SingleRobotMgr.ins().gc();
		var uitMgr=UnitManager.ins;
		Laya.timer.clear(this,this.checkHasMon);
		Laya.timer.clear(this,this.initData);
		Laya.timer.clearAll(this);
		EventCenter.instance.off("main_skill_targets",this,this.onSkillBack);
		EventCenter.instance.off("UPDATE_ALONECOPY_POS",this,this.initPlayerPo);
		EventCenter.instance.off("OfflineAndReconnection",this,this.reConnect);
		if(this.monsterDic){
			var arys=this.monsterDic.values;
			var len=arys.length;
			if(arys && arys.length > 0){
				for (var i=len-1;i >=0;i--){
					uitMgr.destMonstRobot(arys[i]);
					arys[i]=null;
				}
				this.count++;
			}
			this.monsterDic.clear();
		}
		if(this.robotAry){
			for (i=0;i < 3;i++){
				var pl=this.robotAry[i];
				if(pl){
					uitMgr.destoryRole(pl);
				}
			}
			this.robotAry=null;
		}
		this.robotMark=1;
	}

	/**
	*检查是否还有怪物，没有重现调一次enter
	**/
	__proto.checkHasMon=function(){
		if(this.count <=0){
			if(!this.ins)
				this.ins=UnitManager.ins;
			if(this.ins.getMonstList().length <=0){
				this.onEnter(0,0);
			}
		}
	}

	/**
	*主角技能释放返回
	*@param tar 击中目标
	*@param slot 英雄序列/槽位
	*@param rabio 技能伤害系数
	*@param harmType 伤害类型
	*@param skillType 技能类型
	**/
	__proto.onSkillBack=function(tar,slot,rabio,harmType,skillType,timeAry,harmVal){
		(harmVal===void 0)&& (harmVal=-1);
		if(harmVal !=-1){
			var figNum=harmVal;
		}
		else{
			if(!this.fightData){
				var harmRabio=0;
			}
			else{
				if(harmType==16){
					harmRabio=parseFloat(this.fightData[3]);
				}
				else if(harmType==18){
					harmRabio=parseFloat(this.fightData[4]);
				}
				else if(harmType==17){
					harmRabio=parseFloat(this.fightData[5]);
				}
				else{
					harmRabio=parseFloat(this.fightData[0]);
				}
			}
			figNum=Math.round(this.getFight(slot)*rabio *harmRabio);
		}
		if(timeAry && timeAry.length > 0){
			var n=timeAry.length;
			var delay=10;
			var v=Math.floor(figNum/n);
			for(var j=0;j < n;j++){
				delay+=parseInt(timeAry[j]);
				Laya.timer.once(delay,this,this.onSkillBack,[tar,slot,rabio,harmType,skillType,null,v],false);
			}
			return;
		}
		if(tar){
			var len=tar.length;
			for (var i=0;i < len;i++){
				var tempRobt=this.monsterDic.get(tar[i]);
				if(tempRobt){
					if(harmType==0){
						harmType=HarmManager.ins.calculateHarmType(this.mainPl);
						if(harmType==2){
							figNum=parseInt(Math.round(HarmManager.ins.calculateBaoJiHarm(this.mainPl,figNum)).toFixed());
						}
					}
					tempRobt.curHp-=figNum;
					tempRobt.updateBlood(tempRobt.curHp/tempRobt.maxHp);
					var dir=CommonUtil.changeDir(this.mainPl.x,this.mainPl.y,tempRobt.x,tempRobt.y);
					HarmManager.ins.hurt(harmType,figNum,tempRobt,dir);
					if(tempRobt.curHp <=0){
						this.curKillNum+=1;
						tempRobt.curHp=0;
						tempRobt.updateBlood(0);
						tempRobt.dead();
						UnitManager.ins.destMonstRobot(tempRobt);
						this.monsterDic.remove(tar[i]);
						this.checkOver();
						Mgr.taskPro.reqKillMonster(tempRobt.monsterId);
					}
				}
			}
		}
	}

	__proto.getFight=function(slot){
		var fightNum=Mgr.power.getPowerByRoleId(this.roleVo.guid);
		return fightNum;
	}

	/**检查一波是否结束，结束后创建下一波乖*/
	__proto.checkOver=function(){
		if(this.monsterDic.values.length <=0){
			if(this.robotMark < 2 && this.gqInfo){
				if(this.gqInfo.nextLevel > this.starPass && this.gqInfo.nextLevel < this.endPass){
					this.robotMark++;
				}
			}
			this.count++;
			this.createMonsters();
			Mgr.gqProMgr.reqKillServ();
			if(this.robotMark==2){
				this.robotMark=3;
				SingleRobotMgr.ins().createRobt(this.nextPo.x,this.nextPo.y);
			}
		}
	}

	/**创建怪物*/
	__proto.createMonsters=function(){
		this.monIsWake=false;
		var po=this.getMonBornPo();
		if(po && this.aloneVo){
			var sceIns=SceneContainer.getInstance();
			var num=this.aloneVo.mNum;
			var posArr=CommonUtil.getBornPosArr(num,this._space);
			for (var i=0;i < num;i++){
				var mvo=this.getMonstVo(i,this.aloneVo.monstId);
				var monster=this.unitMgr.createMonRobot(mvo);
				this.monsterDic.set(mvo.guid,monster);
				var pos=posArr[i];
				var tx=po.x+pos[0];
				var ty=po.y+pos[1];
				if(!sceIns.isCanWalkable(tx,ty)){
					var endArr=sceIns.upMapLayer.globalToGrid(tx,ty);
					var endNode=sceIns.getNodeByXY(endArr[0],endArr[1]);
					tx=po.x;
					ty=po.y;
					if(endNode){
						var ary=sceIns.getNearOKPath(endNode,1);
						if(ary.length > 0){
							ary=sceIns.upMapLayer.gridToGlobal(ary[0],ary[1])
							tx=ary[0];
							ty=ary[1];
						}
					}
				}
				monster.pos(tx,ty);
				monster.curSpeed=230
				monster.updatePos();
				monster.blood.visible=false;
				monster.unitNameText.visible=false;
				monster.monsterId=this.aloneVo.monstId;
				this.container.unitLayer.addChild(monster);
			}
		}
	}

	/**获取怪物Vo*/
	__proto.getMonstVo=function(num,monsterId){
		var obj=this.unitMgr.getMonsterCfg(monsterId);
		var tempVo=new MonsterVO();
		tempVo.monsterId=obj.id;
		tempVo.guid=600 *this.count+num+ClientUnitGuid.ins.aloneSceneGuid;
		var hp=this.getFight(-1)*(parseFloat(this.fightData[1])+parseFloat(this.fightData[2])*Mgr.subPlayer.getFightSJnum);
		tempVo.maxHp=hp;
		tempVo.curHp=hp;
		return tempVo;
	}

	/**获取怪物刷新点*/
	__proto.getMonBornPo=function(){
		var temp=this.count % this.redPosAry.length;
		this.aloneVo=this.redPosAry[temp];
		if(!this.aloneVo){
			var str="单机本获取怪物热点出错，热点下标temp="+temp+"波数->count="+this.count+"热点数组redPosAry="+this.redPosAry.length;
			if(Mgr.gqMgr.gqInfo){
				str+="当前关卡ID======"+(Mgr.gqMgr.gqInfo.nextLevel-1);
			}
			else{
				str+="关卡信息为空";
			};
			var len=this.redPosAry.length;
			for (var i=0;i < len;i++){
				str+="热点数据"+this.redPosAry[i].mx+"========"+this.redPosAry[i].my+"\n";
			}
			laya.xq.cfg.reportOneBug(str,new Error("单机本获取怪物刷新点"+str));
			console.log(str)
			return null;
		}
		if(!this.mtPo){
			this.mtPo=new Point();
		}
		if(this.aloneVo){
			this.mtPo.setTo(this.aloneVo.mx,this.aloneVo.my);
			if(!this.nextPo && this.robotMark > 1){
				this.nextPo=new Point(this.aloneVo.mx,this.aloneVo.my);
			}
		}
		else{
			var player=Game.getInstance().player;
			this.mtPo.setTo(player.x,player.y);
			laya.xq.cfg.reportOneBug("获取怪物刷新点异常",new Error("获取怪物刷新点异常:"+this.redPosAry.length+":"+temp));
		}
		temp=(this.count+1)% this.redPosAry.length;
		var nextVo=this.redPosAry[temp];
		if(nextVo){
			Mgr.gqMgr.nextMonPo.setTo(nextVo.mx,nextVo.my);
		}
		return this.mtPo;
	}

	__proto.onPlayerEnter=function(player){
		if((player instanceof com.xq.rpg.unit.SubPlayer )){
			var subPlayer=player;
			var mainPlayer=Game.getInstance().player;
			if(mainPlayer && subPlayer.getParentGuid()==mainPlayer.guid){
				var rd=Math.random()*3+1;
				var temp=rd *64;
				subPlayer.x=mainPlayer.x+temp;
				subPlayer.y=mainPlayer.y+temp;
			}
		}
	}

	/**初始化数据*/
	__proto.initData=function(){
		console.log("重新获取单机本数据")
		this.redPosAry=[];
		var mapObj=Mgr.gqMgr.getMapDataByID();
		if(!mapObj){
			if(this.initCount > 5){
				if(Mgr.gqMgr.gqInfo){
					var errStr="挂机点表没有"+Mgr.gqMgr.gqInfo.nextLevel+"挂机点ID,请策划前往检查"
					console.error(errStr);
					console.log(errStr)
					laya.xq.cfg.reportOneBug("AloneMap->initData异常",new Error(errStr));
				}
				debugger;
			}
			else{
				if(!this.mainPl.isJuQing){
					this.initCount++;
					Laya.timer.once(200,this,this.initData);
				}
			}
			return;
		};
		var tempAry=mapObj.rule.split(";");
		var len=tempAry.length;
		if(len <=0){
			if(Mgr.gqMgr.gqInfo){
				errStr="获取单机本，怪物热点失败rule="+mapObj.rule+"关卡id="+(Mgr.gqMgr.gqInfo.nextLevel-1);
			}
			else{
				errStr="获取单机本，怪物热点失败rule="+mapObj.rule+"关卡id=关卡信息不存在";
			}
			console.log(errStr)
			debugger;
			return;
		}
		for (var i=0;i < len;i++){
			var vo=new AloneVo();
			var temp=tempAry[i].split(":");
			this.checkEro(temp);
			vo.monstId=temp[0];
			vo.mNum=parseInt(temp[2]);
			var poAry=temp[1].split("|");
			poAry=SceneContainer.GridToGlobal(parseInt(poAry[0]),parseInt(poAry[1]));
			vo.mx=poAry[0];
			vo.my=poAry[1];
			this.redPosAry[i]=vo;
		}
		this.dataOk();
	}

	/**检查表格是否有异常*/
	__proto.checkEro=function(temp){
		if(!temp[0]){
			console.error("挂机点表异常==>没有配置挂物ID");
		}
	}

	/**
	*@private
	*/
	/**当前杀怪数量*/
	__getset(0,__proto,'curKillNum',function(){
		return this._curKillNum;
		},function(value){
		this._curKillNum=value;
		Mgr.gqMgr.upadteKillNum(value);
	});

	return AloneMapSpecial;
})()


