//class com.xq.modules.map.douyinGame.DouYinGameMapSpecial
var DouYinGameMapSpecial=(function(){
	function DouYinGameMapSpecial(){
		this.mainPlayer=null;
		this.curBoss=null;
		this.preffix=null;
		this.monsterScale=2.5;
		this.playerScale=1.6;
	}

	__class(DouYinGameMapSpecial,'com.xq.modules.map.douyinGame.DouYinGameMapSpecial');
	var __proto=DouYinGameMapSpecial.prototype;
	Laya.imps(__proto,{"com.xq.modules.map.IMapSpecial":true})
	__proto.preEnter=function(){
		this.mainPlayer=Game.getInstance().player;
	}

	__proto.onEnter=function(tx,ty){
		this.hideAll(true);
		SkillEffectAni.TmpScale=2.2;
		Tween.to(this.mainPlayer,{x:-200},100,null,null,5000);
		console.log("进入抖音单击本");
		Mgr.sound.playBgMusic("1");
	}

	//来点背景音助兴
	__proto.onResize=function(){
		SceneContainer.getInstance().mapCamera.updateViewPortSize(99999,99999);
		if(this.curBoss && !this.curBoss.isDispose){
			Mgr.douyinGameM.showBossBlood(this.curBoss);
		}
	}

	__proto.onMonsterEnter=function(monster){
		if(monster && (monster.vo).monsterId==Mgr.douyinGameM.curBossId){
			Mgr.douyinGameM.showBossBlood(monster);
			this.curBoss=monster;
			Mgr.douyinGameM.showBossAni(this.curBoss);
			Mgr.douyinGameM.bossMaxHp=this.curBoss.maxHp;
			monster.scale(this.monsterScale,this.monsterScale);
		}
	}

	__proto.onPlayerEnter=function(player){
		if(player==this.mainPlayer){
			var name=player.unitName;
			var idx=name.indexOf(".");
			this.preffix=name.substr(0,idx);
			name=name.substr(idx+1);
			player.setUnitName(name);
			}else{
			var x=player.x;
			var y=player.y;
			player.y=0;
			player.x=Math.random()>0.5?-100:SceneContainer.getInstance().upMapLayer.mapWidth+100;
			player.titleDecorate.offHeight=50;
			player.unitGuild.style.fontSize=50;
			player.unitGuild.style.letterSpacing=5;
			player.unitGuild.innerHTML=" Lv."+(player.vo).level;
			player.unitNameText.fontSize=55;
			player.blood.scaleY=this.playerScale;
			player.isShield=false;
			player.unitNameTitle.visible=false;
			player.doAction(0,1,true);
			player.scale(this.playerScale,this.playerScale);
			Mgr.douyinGameM.randomShiZhuang(player);
			Mgr.douyinGameM.initPlayer(player);
			player.tiao(x,y,1200);
			console.log("玩家"+player.unitName+"当前位置:",player.x,player.y);
			var vo=new SkillVO();
			vo.rang=768 << 1;
			vo.width=768 << 1;
			(player).extraVo=vo;
		}
	}

	__proto.onEnterAgain=function(tx,ty){}
	__proto.onExit=function(){
		this.hideAll(false);
		Laya.timer.once(2000,Mgr.douyinGameA,Mgr.douyinGameA.enter);
		console.log("退出抖音单击本");
	}

	__proto.hideAll=function(isHide){
		if(isHide){
			AIEnum.attackDistance=768;
			SceneContainer.getInstance().mapCamera.updateViewPortSize(99999,99999);
			UIMgrR.hideAll();
			UIMgrR.closeIView(com.xq.view.modules.notice.INoticeDialog);
			Laya.stage.on("resize",this,this.onResize);
			AmtLoaderMgr.instance.maxMemorySize=1024*1024*99999;
			AmtLoaderMgr.instance.maxAtmMemorySize=1024*1024*99999;
			AmtMgr.isForbitGC=true;
			Unit.isForbitHalo=true;
			Unit.isForbitBeBitFilter=true;
			}else{
			SceneContainer.getInstance().mapCamera.updateViewPortSize(Laya.stage.width,Laya.stage.height);
			AIEnum.attackDistance=192;
			UIMgrR.showAll();
			AmtLoaderMgr.instance.maxMemorySize=1024*1024*450;
			AmtLoaderMgr.instance.maxAtmMemorySize=1024*1024*450;
			AmtMgr.isForbitGC=false;
			Unit.isForbitHalo=false;
			Unit.isForbitBeBitFilter=false;
			Laya.stage.off("resize",this,this.onResize);
		};
		var bossRfreshPanel=UIMgrR.getIView(com.xq.view.modules.bosstips.IBossRefreshTips);
		bossRfreshPanel.visible=!isHide;
		this.mainPlayer.unitNameBox.visible=!isHide;
		this.mainPlayer.blood.visible=!isHide;
		this.mainPlayer.doAction(ActionType.NOACT,0,true);
		this.mainPlayer.scale(0,0);
		AIController.ins().changeForbitAutoCombat();
	}

	__proto.dispose=function(){}
	return DouYinGameMapSpecial;
})()


//class com.xq.modules.map.FuWenTaMapSpecial
var FuWenTaMapSpecial=(function(){
	function FuWenTaMapSpecial(){
		/**主角 */
		this.mainPlayer=null;
		this.aiController=null;
		this.scene=null;
		this.showAni=null;
		this.centerX=0;
		this.centerY=0;
		this.ifAniEnd=false;
		this.curMonster=null;
		this.time=1200;
		this.isAgain=false;
		this.playerIdx=0;
		this.curTaiZi=new Image();
		this.nextTaiZi=new Image();
	}

	__class(FuWenTaMapSpecial,'com.xq.modules.map.FuWenTaMapSpecial');
	var __proto=FuWenTaMapSpecial.prototype;
	Laya.imps(__proto,{"com.xq.modules.map.IMapSpecial":true})
	__proto.preEnter=function(){
		this.aiController=AIController.ins();
		this.mainPlayer=Game.getInstance().player;
		this.scene=SceneContainer.getInstance();
		this.curTaiZi.skin=PathDefine.getMapSpecialPath("taizi");
		this.nextTaiZi.skin=PathDefine.getMapSpecialPath("taizi");
		if(!this.showAni){
			this.showAni=new UIAni();
		}
		this.showAni.setRes(PathDefine.getUIEffectUrl("guangshu"));
		this.showAni.loopTimes=1;
	}

	__proto.onEnter=function(tx,ty){
		Mgr.subPlayer.stopSubPlayerAI(true);
		this.aiController.changeForbitAutoCombat();
		this.enterAni(tx,ty,0);
		this.mainPlayer.tiaoAction.stop();
		this.playerTiao();
		Laya.timer.once(1500,this.aiController,this.aiController.changeForbitAutoCombat,[false]);
	}

	__proto.onMonsterEnter=function(monster){
		if(this.ifAniEnd){
			this.onAniEnd();
			this.ifAniEnd=false;
		}
		else{
			this.curMonster=monster;
			this.curMonster.x=-1000;
			this.curMonster.y=-1000;
			this.curMonster.alpha=0;
		}
	}

	__proto.onPlayerEnter=function(player){
		if((player instanceof com.xq.rpg.unit.SubPlayer )){
			if(this.isAgain){
				var subPlayer=player;
				if(this.playerIdx %2==1){
					subPlayer.pos(this.mainPlayer.x-40 *(this.playerIdx+1),this.mainPlayer.y-20 *(this.playerIdx+1));
					}else{
					subPlayer.pos(this.mainPlayer.x-40 *(this.playerIdx+1),this.mainPlayer.y+20 *(this.playerIdx+1));
				};
				var posY=subPlayer.y;
				subPlayer.doAction(1,3,true);
				subPlayer.curActIsOk=false;
				Laya.timer.frameLoop(1,subPlayer,subPlayer.updatePos,null);
				Tween.to(subPlayer,{x:subPlayer.x,y:posY-300},this.time>>1,Ease.quadOut,null,0);
				Tween.to(subPlayer,{x:subPlayer.x,y:posY},this.time>>1,Ease.quadIn,null,this.time>>1);
				this.playerIdx++;
			}
		}
	}

	__proto.playerTiao=function(){
		var disX=this.centerX-this.mainPlayer.x;
		var offX=0;
		this.mainPlayer.tiaoAction.tiao(this.centerX-offX,this.centerY,this.time);
		this.mainPlayer.curActIsOk=false;
		Laya.timer.frameLoop(1,this.mainPlayer,this.mainPlayer.updatePos,null);
		Tween.to(this.mainPlayer,{x:this.mainPlayer.x+disX,y:this.centerY-300},this.time>>1,Ease.quadOut,null,0);
		Tween.to(this.mainPlayer,{x:this.centerX-offX,y:this.centerY},this.time>>1,Ease.quadIn,null,this.time>>1);
		Laya.timer.once(this.time,this,this.enterAgain);
	}

	__proto.onEnterAgain=function(tx,ty){
		this.isAgain=true;
		this.playerIdx=0;
		this.enterAni(tx,ty,0);
		this.playerTiao();
	}

	__proto.enterAgain=function(){
		this.mainPlayer.curActIsOk=true;
		this.mainPlayer.stand();
	}

	__proto.onExit=function(){
		this.nextTaiZi.alpha=0;
		if(this.curMonster){
			Tween.to(this.curMonster,{y:this.curMonster.y+1000},1500);
		}
		Tween.to(this.curTaiZi,{y:this.curTaiZi.y+1000,alpha:0.3},1500);
	}

	__proto.dispose=function(){
		this.isAgain=false;
		Laya.loader.clearRes(this.curTaiZi.skin);
		this.curTaiZi.skin=null;
		this.nextTaiZi.skin=null;
		if(this.showAni){
			this.showAni.dispose();
			this.showAni=null;
		}
	}

	/**入场动画*/
	__proto.enterAni=function(tx,ty,delayTime){
		this.centerX=tx;
		this.centerY=ty;
		this.curTaiZi.alpha=1;
		this.curTaiZi.width=228*3;
		this.curTaiZi.height=142*3;
		this.curTaiZi.x=tx-(this.curTaiZi.width >> 1);
		this.curTaiZi.y=ty-(this.curTaiZi.height >>2);
		this.scene.bottomLayer.addChild(this.curTaiZi);
		this.nextTaiZi.alpha=this.curTaiZi.alpha;
		this.nextTaiZi.width=this.curTaiZi.width;
		this.nextTaiZi.height=this.curTaiZi.height;
		this.nextTaiZi.x=this.curTaiZi.x;
		this.nextTaiZi.y=this.curTaiZi.y;
		this.scene.bottomLayer.addChild(this.nextTaiZi);
		this.ifAniEnd=false;
		Tween.to(this.curTaiZi,{x:this.curTaiZi.x-1000,y:this.curTaiZi.y+1000},1200,null,null,delayTime);
		Tween.from(this.nextTaiZi,{x:this.nextTaiZi.x+1000,y:this.nextTaiZi.y-1000},1200,null,Handler.create(this,this.onAniEnd),delayTime);
	}

	__proto.onAniEnd=function(){
		this.ifAniEnd=true;
		if(this.curMonster){
			this.curTaiZi.pos(this.nextTaiZi.x,this.nextTaiZi.y);
			this.curMonster.pos(this.nextTaiZi.x+500 ,this.nextTaiZi.y+100);
			this.curMonster.alpha=1;
			if(!this.showAni){
				this.showAni=new UIAni();
			}
			this.showAni.setRes(PathDefine.getUIEffectUrl("guangshu"));
			this.showAni.loopTimes=1;
			this.curMonster.addChild(this.showAni);
		}
		Mgr.subPlayer.startSubPlayerAI(true);
		this.aiController.changeForbitAutoCombat(false);
	}

	return FuWenTaMapSpecial;
})()


//class com.xq.modules.map.guanqia.GuanQiaMapSpecial
var GuanQiaMapSpecial=(function(){
	function GuanQiaMapSpecial(){
		/**怪物坐标*/
		this.monstPo=null;
		/**主角 */
		this.mainPlayer=null;
		/**场景对象*/
		this.sceneContainer=null;
		/**boss对象*/
		this.monster=null;
		/**距离boss的出现距离*/
		this.distance=200;
		this.sceneAni=null;
		this.gqInfo=null;
		this.isAni=false;
	}

	__class(GuanQiaMapSpecial,'com.xq.modules.map.guanqia.GuanQiaMapSpecial');
	var __proto=GuanQiaMapSpecial.prototype;
	Laya.imps(__proto,{"com.xq.modules.map.IMapSpecial":true})
	__proto.preEnter=function(){
		if(!this.monstPo){
			this.monstPo=new Point();
		}
		this.monstPo=Mgr.gqMgr.nextMonPo;
		this.mainPlayer=Game.getInstance().player;
		this.sceneContainer=SceneContainer.getInstance();
		this.gqInfo=Mgr.gqMgr.gqInfo;
		this.isAni=this.gqInfo.nextLevel <=Mgr.cfgMgr.getAniGuanQiaNum();
	}

	__proto.onCameraTo=function(){
		BossComingUtil.startShoAni();
		this.playSceneAni();
		Laya.timer.once(1000,this,this.monsterAni);
	}

	__proto.playSceneAni=function(){
		this.sceneAni=new SceneAni();
		this.sceneAni.loopTimes=1;
		this.sceneAni.setRes(PathDefine.EFFECT+"bs_chuchang"+".amt");
	}

	__proto.onEnter=function(tx,ty){
		if(this.isAni){
			this.mainPlayer.curActIsOk=true;
			this.mainPlayer.stand();
			this.sceneContainer.mapCamera.lookAtPosTween(this.monstPo.x,this.monstPo.y,500,Handler.create(this,this.onCameraTo));
			AIController.ins().changeForbitAutoCombat(true,3000);
		}
	}

	__proto.onMonsterEnter=function(monster){
		this.monster=monster;
		monster.pos(this.monstPo.x,this.monstPo.y);
		if(this.isAni){
			monster.isShield=true;
			monster.visible=false;
			}else{
			AIController.ins().startAutoCombat();
			AIController.ins().autoCombatAI.curBattleObj=monster;
			AIController.ins().autoCombatAI.exec();
		}
	}

	__proto.monsterAni=function(){
		this.playSceneAni();
		if(!this.monster){
			return;
		}
		this.monster.isShield=false;
		this.monster.visible=true;
		this.monster.alpha=0;
		this.sceneAni.pos(this.monstPo.x,this.monstPo.y);
		this.sceneContainer.bottomLayer.addChild(this.sceneAni);
		Tween.to(this.monster,{alpha:1},500,null,Handler.create(this,this.onAniPlayComp),500,true);
		this.playerTiao();
	}

	__proto.playerTiao=function(){
		var px=this.mainPlayer.x;
		var py=this.mainPlayer.y;
		var mx=this.monster.x;
		var my=this.monster.y;
		var flagX=px<mx?-1:1;
		var flagY=py<my?-1:1;
		var toX=mx+flagX *this.distance;
		var toY=my+flagY *this.distance;
		this.mainPlayer.curActIsOk=true;
		this.mainPlayer.tiao(toX,toY,1500);
		var arr=SubPlayerModel.ins().getShenJiangNums();
		var len=arr.length;
		for(var i=0;i< len;i++){
			var subPlayer=arr[i];
			if(subPlayer){
				subPlayer.curActIsOk=true;
				subPlayer.tiao(toX-128+Math.random()*256,toY-128+Math.random()*256,1500);
			}
		}
	}

	__proto.onAniPlayComp=function(){
		this.sceneContainer.mapCamera.lookAt(this.mainPlayer);
		AIController.ins().startAutoCombat();
		AIController.ins().autoCombatAI.curBattleObj=this.monster;
		AIController.ins().autoCombatAI.exec();
	}

	__proto.onPlayerEnter=function(player){}
	__proto.onEnterAgain=function(tx,ty){
		this.onEnter(tx,ty);
	}

	__proto.onExit=function(){}
	__proto.dispose=function(){
		if(this.sceneAni){
			this.sceneAni.dispose();
			this.sceneAni=null;
		}
		Laya.timer.clear(this,this.monsterAni);
	}

	return GuanQiaMapSpecial;
})()


