//class com.xq.modules.map.MapSpecialFactory
var MapSpecialFactory=(function(){
	function MapSpecialFactory(){}
	__class(MapSpecialFactory,'com.xq.modules.map.MapSpecialFactory');
	MapSpecialFactory.getMapEffect=function(mapId){
		if(MapIdEnum.checkIsAlone(mapId)){
			return MapSpecialFactory.aloneCopy=MapSpecialFactory.aloneCopy|| new AloneMapSpecial();
		}
		else if(MapIdEnum.checkIsGuanQia(mapId)){
			return MapSpecialFactory.guanQiaCopy=MapSpecialFactory.guanQiaCopy|| new GuanQiaMapSpecial();
		}
		switch(mapId){
			case 104:
				return MapSpecialFactory.zhuxianzhen=MapSpecialFactory.zhuxianzhen|| new FuWenTaMapSpecial();
			case 301:
				return MapSpecialFactory.wanxianzhen=MapSpecialFactory.wanxianzhen|| new XiaKeDaoMapSpecial();
			case 105:
				return MapSpecialFactory.wanxianzhen=MapSpecialFactory.wanxianzhen|| new XiaKeDaoMapSpecial();
			case 2025:
				return MapSpecialFactory.wanxianzhen=MapSpecialFactory.wanxianzhen|| new XiaKeDaoMapSpecial();
			case 2024:
				return MapSpecialFactory.zhuxianzhen=MapSpecialFactory.zhuxianzhen|| new FuWenTaMapSpecial();
			case 2039:
				return MapSpecialFactory.douyinGame=MapSpecialFactory.douyinGame|| new DouYinGameMapSpecial();
			default :
				return MapSpecialFactory.base;
			}
		return null;
	}

	MapSpecialFactory.zhuxianzhen=null;
	MapSpecialFactory.wanxianzhen=null;
	MapSpecialFactory.douyinGame=null;
	MapSpecialFactory.guanQiaCopy=null;
	MapSpecialFactory.aloneCopy=null;
	__static(MapSpecialFactory,
	['base',function(){return this.base=new MapEnterBase();}
	]);
	return MapSpecialFactory;
})()


//class com.xq.modules.map.XiaKeDaoMapSpecial
var XiaKeDaoMapSpecial=(function(){
	function XiaKeDaoMapSpecial(){
		this.mainPlayer=null;
		this.aiController=null;
		this.scene=null;
		this.centerX=0;
		this.centerY=0;
		this.w=1243;
		this.h=1179;
		this.offX=707;
		this.offY=697;
		this.isAgain=false;
		this.posArr=[[-0.5,0.86],[-0.86,0.5],[-1,0],[-0.86,-0.5],[-0.5,-0.86],[0,-1],[0.5,-0.86],[0.86,-0.5],[1,0],[0.86,0.5],[0.5,0.86],[0,1]];
		this.monsterIdx=0;
		this.playerIdx=0;
		this.distance=150;
		this.container=new Sprite();
		this.curLou=new Image();
		this.nextLou=new Image();
		this.diLou=new Image();
	}

	__class(XiaKeDaoMapSpecial,'com.xq.modules.map.XiaKeDaoMapSpecial');
	var __proto=XiaKeDaoMapSpecial.prototype;
	Laya.imps(__proto,{"com.xq.modules.map.IMapSpecial":true})
	__proto.preEnter=function(){
		this.curLou.skin=PathDefine.getMapSpecialPath("palou");
		this.nextLou.skin=PathDefine.getMapSpecialPath("palou");
		this.diLou.skin=PathDefine.getMapSpecialPath("palou");
		this.aiController=AIController.ins();
		this.mainPlayer=Game.getInstance().player;
		this.scene=SceneContainer.getInstance();
	}

	__proto.onEnter=function(tx,ty){
		this.monsterIdx=0;
		this.container.x=0;
		this.container.y=-100;
		this.centerX=tx;
		this.centerY=ty;
		this.curLou.width=this.w;
		this.curLou.height=this.h;
		this.curLou.x=0;
		this.curLou.y=0;
		this.nextLou.width=this.curLou.width;
		this.nextLou.height=this.curLou.height;
		this.nextLou.x=this.curLou.x+this.offX;
		this.nextLou.y=this.curLou.y-this.offY;
		this.diLou.width=this.curLou.width;
		this.diLou.height=this.curLou.height;
		this.diLou.x=this.nextLou.x+this.offX;
		this.diLou.y=this.nextLou.y-this.offY;
		this.scene.bottomLayer.addChild(this.container);
		this.container.addChild(this.curLou);
		this.container.addChild(this.nextLou);
		this.container.addChild(this.diLou);
	}

	__proto.onMonsterEnter=function(monster){
		if(this.monsterIdx >=this.posArr.length){
			this.monsterIdx %=this.posArr.length;
		};
		var pos=this.posArr[this.monsterIdx++];
		var dis=100+this.distance *Math.random();
		monster.stand();
		monster.x=-1000;
		monster.y=-1000;
		Laya.timer.once(this.monsterIdx *20,this,this.monsterShow,[monster,dis,pos],false);
	}

	__proto.monsterShow=function(monster,dis,pos){
		monster.tiao(this.centerX+dis *pos[0],this.centerY+dis *pos[1],1000);
	}

	__proto.onPlayerEnter=function(player){
		if((player instanceof com.xq.rpg.unit.SubPlayer )){
			if(this.isAgain){
				var subPlayer=player;
				if(this.playerIdx %2==1){
					subPlayer.pos(this.mainPlayer.x-20 *(this.playerIdx+1),this.mainPlayer.y+50 *(this.playerIdx+1));
					}else{
					subPlayer.pos(this.mainPlayer.x-80 *(this.playerIdx+1),this.mainPlayer.y+20 *(this.playerIdx+1));
				}
				this.playerIdx++;
				subPlayer.doAction(1,3,true);
				subPlayer.curActIsOk=false;
			}
		}
	}

	__proto.onEnterAgain=function(tx,ty){
		this.isAgain=true;
		this.playerIdx=0;
		Mgr.subPlayer.stopSubPlayerAI(true);
		this.aiController.changeForbitAutoCombat();
		this.aiController.stopAutoCombat();
		this.mainPlayer.pos(tx,ty);
		this.onEnter(tx,ty);
		this.enterAni(1200);
	}

	__proto.enterAni=function(time){
		if(this.mainPlayer.isMount){
			this.mainPlayer.doAction(11,3,true);
			}else{
			this.mainPlayer.doAction(1,3,true);
		}
		this.mainPlayer.curActIsOk=false;
		Tween.to(this.container,{x:this.container.x-this.offX,y:this.container.y+this.offY},time,null,Handler.create(this,this.aniEnd));
	}

	__proto.aniEnd=function(){
		this.mainPlayer.curActIsOk=true;
		this.mainPlayer.stand();
		Mgr.subPlayer.startSubPlayerAI(true);
		this.aiController.changeForbitAutoCombat(false);
		this.aiController.startAutoCombat();
	}

	__proto.onExit=function(){}
	__proto.dispose=function(){
		this.isAgain=false;
		Laya.loader.clearRes(this.curLou.skin);
		this.curLou.skin=null;
		this.nextLou.skin=null;
		this.diLou.skin=null;
	}

	return XiaKeDaoMapSpecial;
})()


