//class com.xq.modules.marriage.MarriageCopyMgr
var MarriageCopyMgr=(function(){
	function MarriageCopyMgr(){
		/**姻缘副本怪物刷新表 用于获取跳关时间*/
		this.marriageMonsterCfg=null;
		this.marriageMonsterData=null;
		/**姻缘副本后端信息*/
		this._copyInfo=null;
		/**姻缘副本后端信息*/
		this._marriageCopyLayerInfo=null;
		this.model=null;
		this.victoryRewardArr=null;
		this._specialRewardArr=null;
		this._curGetLoyer=0;
		this.model=Model.marriage;
		this.marriageMonsterCfg=CfgManager.getTableCfg("marryCopyConfig");
		this._specialRewardArr=[];
	}

	__class(MarriageCopyMgr,'com.xq.modules.marriage.MarriageCopyMgr');
	var __proto=MarriageCopyMgr.prototype;
	__proto.getMarriageMonsterData=function(){
		if(!this.marriageMonsterData){
			this.marriageMonsterData=new DataContainer();
			var arr=this.marriageMonsterCfg.objectDataArray;
			var len=arr.length;
			var cof;
			var ele;
			for(var i=0;i<len;i++){
				cof=arr[i];
				ele=new DataElement(cof);
				this.marriageMonsterData.addElement(cof.layer,ele);
				if(cof.copyItems){
					this._specialRewardArr.push(cof);
				}
			}
		}
		return this.marriageMonsterData;
	}

	/**每日可挑战的基础次数*/
	__proto.getEveryChallengeNum=function(){
		return this.model.configVo.fubenTimes;
	}

	/**每日可挑战的基础次数 加上额外购买的挑战次数*/
	__proto.getAllChallengeNum=function(){
		if(!this.copyInfo){
			return 0;
		}
		return this.model.configVo.fubenTimes+this.copyInfo.buyTimes;
	}

	/**每日可额外购买的挑战次数*/
	__proto.getAllBuyNum=function(){
		return Mgr.tequanMgr.getTequanVal(34)
	}

	/**当前剩余可挑战次数*/
	__proto.getNowChallengeNum=function(){
		if(!this.copyInfo){
			return 0;
		}
		return this.getAllChallengeNum()-this.copyInfo.count;
	}

	/**婚姻副本购买次数所需金额*/
	__proto.getBuyNumMoney=function(count){
		var len=this.model.configVo.buyCostArr.length;
		if(count >=len){
			return this.model.configVo.buyCostArr[len-1];
			}else{
			return this.model.configVo.buyCostArr[count];
		}
	}

	/**获取跳关时间断*/
	__proto.getTimes=function(obj){
		var ary=[];
		if(obj.time1 > 0){
			ary.push(obj.time1,obj.guanqia1);
		}
		if(obj.time2 > 0){
			ary.push(obj.time2,obj.guanqia2);
		}
		if(obj.time3 > 0){
			ary.push(obj.time3,obj.guanqia3);
		}
		return ary;
	}

	__proto.refreshMarriageCopyRed=function(){
		curLayer=0;
		var len=this._specialRewardArr.length;
		for (var i=0;i < len;i++){
			var curLayer=parseInt(this._specialRewardArr[i].layer);
			if(curLayer < this.copyInfo.copyLv && curLayer > this.copyInfo.maxCopyLvReward){
				this._curGetLoyer=curLayer;
				break ;
			}
		}
	}

	/**接受姻缘副本邀请*/
	__proto.sendRespInvition=function(id){
		if(!Mgr.guide.isOpen("marriagecopy")){
			Mgr.prompt.optionPrompt("尚未开启姻缘副本");
			return;
		}
		if(Mgr.teamMgr.ifInTeam){
			Mgr.prompt.optionPrompt("当前已在其他副本组队中，请退出后再进入");
			return;
		}
		Mgr.teamAct.reqAcceptInvite(TeamEnum.YinYuanFuBen,id,Handler.create(this,this.onRespInVition));
		console.log("发送接收姻缘副本邀请~");
	}

	__proto.onRespInVition=function(teamType){
		if(teamType==TeamEnum.YinYuanFuBen){
			UIMgrR.openViewByFunID("marriagecopy",null,2);
		}
	}

	/**进入姻缘副本*/
	__proto.reqEnter=function(){
		Mgr.inoutMap.check(Handler.create(Mgr.teamAct,Mgr.teamAct.reqEnterCopy,[TeamEnum.YinYuanFuBen]),false,60,TeamEnum.YinYuanFuBen);
	}

	/**姻缘副本信息数据*/
	__proto.initFightVo=function(fightVo){
		fightVo.hideAry=[2,3,4];
		fightVo.aniType=2;
		fightVo.closeFun=Handler.create(Mgr.marriageAct,Mgr.marriageAct.reqExit,null,false);
		fightVo.remainTime=(this.model.configVo.fubenTime *1000)
		fightVo.curFloor=1;
	}

	__getset(0,__proto,'copyInfo',function(){
		return this._copyInfo;
		},function(msg){
		this._copyInfo=msg;
	});

	/**姻缘副本怪物层数信息*/
	__getset(0,__proto,'marriageCopyLayerInfo',function(){
		return this._marriageCopyLayerInfo;
		},function(msg){
		this._marriageCopyLayerInfo=msg;
	});

	return MarriageCopyMgr;
})()


