var MarriageTaskMgr=(function(){
	function MarriageTaskMgr(){
		this.taskModel=null;
		/**1 每日任务 2 终身任务*/
		this.taskType=0;
		this.red=null;
		this.taskModel=Model.marrTaskModel;
		this.red=Mgr.red;
		this.red.regist("marriage","marriagetask",false,"MarriageRed");
	}

	__class(MarriageTaskMgr,'com.xq.modules.marriage.MarriageTaskMgr');
	var __proto=MarriageTaskMgr.prototype;
	__proto.updateTask=function(msg){
		this.taskModel.updateTask(msg);
		this.updateRed();
		EventCenter.instance.event("marrytask_info");
	}

	__proto.updateReward=function(msg){
		this.taskModel.updateReward(msg);
		this.updateRed();
		EventCenter.instance.event("marrytask_info");
	}

	/**离婚后消失红点**/
	__proto.xiaoShiRed=function(){
		this.red.hideRedPoint("marriagetask","marriageTask","MarriageTaskRed");
	}

	__proto.ifReward=function(type){
		var arr;
		if(type==1){
			arr=this.taskModel.dailyTaskList;
		}
		else{
			arr=this.taskModel.lifelongTaskList;
		};
		var len=arr.length;
		for(var i=0;i<len;i++){
			var stat=this.taskModel.getStat(arr[i]);
			if(stat==1){
				return true;
			}
		}
		return false;
	}

	__proto.updateRed=function(){
		if(!Mgr.guide.isOpen("marriage"))return;
		if(!Mgr.marriageMgr.checkIsMarriage())return;
		var arr=this.taskModel.taskDc.array;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var ele=arr[i];
			var stat=this.taskModel.getStat(ele);
			if(stat==1){
				this.red.showRedPoint("marriagetask","marriageTask","MarriageTaskRed");
				return;
			}
		}
		this.red.hideRedPoint("marriagetask","marriageTask","MarriageTaskRed");
	}

	__getset(0,__proto,'dailyTaskList',function(){
		return this.taskModel.dailyTaskList;
	});

	__getset(0,__proto,'lifelongTaskList',function(){
		return this.taskModel.lifelongTaskList;
	});

	MarriageTaskMgr.MARRYTASK_ONE=1;
	MarriageTaskMgr.MARRYTASK_TWO=2;
	return MarriageTaskMgr;
})()


