//class com.xq.modules.mergeSvrCelebration.MergeSvrGfitMgr
var MergeSvrGfitMgr=(function(){
	function MergeSvrGfitMgr(){
		this.model=null;
		this._red=null;
		this.model=Model.mergeSvrGift;
		this._red=Mgr.red;
	}

	__class(MergeSvrGfitMgr,'com.xq.modules.mergeSvrCelebration.MergeSvrGfitMgr');
	var __proto=MergeSvrGfitMgr.prototype;
	__proto.getList=function(){
		var arr=this.model.getCurList().concat();
		return arr.sort(this.compare);
	}

	__proto.compare=function(a,b){
		return a.getValue("Z")-b.getValue("Z");
	}

	__proto.updateData=function(msg){
		this.model.updateData(msg);
		this.updateRed();
		EventCenter.instance.event("updateView");
	}

	/**刷新红点*/
	__proto.updateRed=function(){
		var svipLv=NetMgr.ins().roleVO.vipLevel;
		var flag=false;
		var arr=this.model.getCurList();
		var len=arr.length;
		for(var i=0;i<len;i++){
			var ele=arr[i];
			var cof=ele.getCfgData();
			if(cof.type==1){
				var stat=ele.getValue("S");
				if(!stat &&svipLv>=cof.sviplevel){
					flag=true;
					break ;
				}
			}
		}
		if(flag){
			this._red.showRedPoint("MergeSvrGift","MergeSvrGiftRed","MergeSvrGiftRed");
		}
		else{
			this._red.hideRedPoint("MergeSvrGift","MergeSvrGiftRed","MergeSvrGiftRed");
		}
	}

	/**活动剩余时间*/
	__getset(0,__proto,'timeLeft',function(){
		var vo=NewActiveManager.ins.getActiveVerDic(132);
		if(vo){
			return vo.endTime-Mgr.curTime.serverTimer;
		}
		return 0;
	});

	return MergeSvrGfitMgr;
})()


//class com.xq.modules.mergeSvrCelebration.MergeSvrLiBaoMgr
var MergeSvrLiBaoMgr=(function(){
	function MergeSvrLiBaoMgr(){
		this.model=null;
		this._red=null;
		this.model=Model.mergeSvrLiBao;
		this._red=Mgr.red;
	}

	__class(MergeSvrLiBaoMgr,'com.xq.modules.mergeSvrCelebration.MergeSvrLiBaoMgr');
	var __proto=MergeSvrLiBaoMgr.prototype;
	__proto.getTime=function(){
		var vo=NewActiveManager.ins.getActiveVerDic(133);
		if(vo){
			return vo.endTime-Mgr.curTime.serverTimer;
		}
		return 0;
	}

	__proto.getList=function(){
		var arr=this.model.dc.array.concat();
		return arr.sort(this.compare);
	}

	__proto.updateInfo=function(msg){
		this.model.updateData(msg);
		this.updateRed();
		EventCenter.instance.event("buy_RewardOk");
	}

	__proto.updateBuy=function(msg){
		this.model.updateBuy(msg);
		EventCenter.instance.event("buy_RewardOk");
		this.updateRed();
		this.showTips(msg.msg.id);
	}

	__proto.showTips=function(id){
		var rewardCfg={};
		var way="";
		var ele=this.model.dc.getElement(id);
		var cfg=ele.getCfgData();
		way=PathDefine.HUANHUA_ZHEKOU+cfg.ani+".amt";
		var xyArrCfg=cfg.xytype.split(";");
		var xyArr=xyArrCfg[1].split(":");
		rewardCfg["resPath"]=way;
		var scale=parseFloat(cfg.size);
		rewardCfg["scale"]=scale;
		rewardCfg["name"]=PathDefine.KaiFuLiBao+cfg.id+".png";
		var rewardShow=UIMgrR.openIView(com.xq.view.modules.fourteenluxurygifts.IRewardShow,2);
		rewardShow.dataSource=rewardCfg;
	}

	__proto.compare=function(a,b){
		if(a.sortIndex==b.sortIndex){
			return a.getCfgData().sortIndex-b.getCfgData().sortIndex;
		}
		return a.sortIndex-b.sortIndex
	}

	__proto.updateRed=function(){
		var arr=this.model.dc.array;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var ele=arr[i];
			var stat=ele.getValue("stat");
			if(stat!=2){
				this._red.showRedPoint("MergeSvrLiBao","MergeSvrLiBaoRed","MergeSvrLiBaoRed");
				return;
			}
		}
		this._red.hideRedPoint("MergeSvrLiBao","MergeSvrLiBaoRed","MergeSvrLiBaoRed");
	}

	return MergeSvrLiBaoMgr;
})()


