//class com.xq.modules.paimai.PaiMaiMgr
var PaiMaiMgr=(function(){
	function PaiMaiMgr(){
		this.flag=0;
		this._model=null;
		this._isActive=false;
		this.auctionInfoDic=new Dictionary();
		this.auctionLogInfoDic=new Dictionary();
		this.auctionLogDetailDic=new Dictionary();
		this._redDic=new Dictionary();
		this.setup();
		this._model=new PaiMaiModel();
	}

	__class(PaiMaiMgr,'com.xq.modules.paimai.PaiMaiMgr');
	var __proto=PaiMaiMgr.prototype;
	__proto.setup=function(){
		Mgr.red.regist("shangcheng_main" ,"paimaitab3",true,"StoreFreeExhchange");
		NewActiveManager.ins.regActOpenHandler(167,Handler.create(this,this.openAct,null,false));
		NewActiveManager.ins.regActEndHandler(167,Handler.create(this,this.closeAct,null,false));
	}

	__proto.setRed=function(type){
		this._redDic.set(type,true);
		this.checkRed();
	}

	__proto.checkRed=function(){
		if(this._isActive){
			if(this._redDic.indexOf(3)==-1 && this.hasAuctionInfo(3))
				Mgr.red.showRedPoint("paimaitab3","paimaikey","paimaievent");
			else
			Mgr.red.hideRedPoint("paimaitab3","paimaikey","paimaievent");
			return;
		}
		Mgr.red.hideRedPoint("paimaitab3","paimaikey","paimaievent");
		return;
	}

	//---------------------------------------------------
	__proto.getPaiMaiCfg=function(flag,itemId){
		var ele=this._model.getEleByFlagAndItemId(flag,itemId);
		if(!ele)return null;
		return ele.getCfgData();
	}

	__proto.getEleByRankId=function(rankid){
		var ele=this._model.getEleByRankId(rankid);
		if(!ele)return null;
		return ele.getCfgData();
	}

	__proto.isPaiMaiGood=function(itemId){
		return this.getPaiMaiCfg(this.flag,itemId);
	}

	/**天降豪礼活动开启*/
	__proto.openAct=function(){
		this._isActive=true;
		this._redDic.clear();
		this.sendPaiMaiMsg();
		Mgr.opeAct.sendGetTargetActivity(167);
		var actVo=NewActiveManager.ins.getActiveVerDic(167);
		this.flag=actVo.flag;
		this.checkRed();
	}

	/**活动关闭*/
	__proto.closeAct=function(){
		this._isActive=false;
		this._redDic.clear();
		this.checkRed();
	}

	__proto.sendPaiMaiMsg=function(){
		Mgr.paiMaiMAct.reqGetAuctionInfoCS(3);
	}

	//--------------------------------
	__proto.getAuctionInfo=function(type){
		if(type==3){
			return this._model.getCrossPmItems();
		}
		return [];
	}

	__proto.hasAuctionInfo=function(type){
		var arr=this.getAuctionInfo(type);
		return arr.length>0;
	}

	__proto.getDetailInfo=function(){
		return this._model.getDetailInfo();
	}

	__proto.getAuctionLogInfo=function(type){
		return this.auctionLogInfoDic.get(type);
	}

	__proto.getAuctionLogDetail=function(auctionId){
		return this.auctionLogDetailDic.get(auctionId);
	}

	/**同步跨服拍卖品数据*/
	__proto.updateAllInfo=function(msg){
		if(msg.type==3){
			this._model.updateAllCrossInfo(msg);
		}
		EventCenter.instance.event("PaiMaiData");
	}

	/**参与竞价操作后刷新*/
	__proto.updateOneInfo=function(msg){
		this._model.updateOneCrossInfo(msg);
		EventCenter.instance.event("PaiMaiData");
	}

	/**拍卖物品的信息变化后推送操作*/
	__proto.updateAuctionChange=function(msg){
		this._model.updateAuctionChange(msg);
		EventCenter.instance.event("PaiMaiData");
	}

	/**一口价*/
	__proto.updateOnePrice=function(msg){
		this._model.updateOnePrice(msg);
		EventCenter.instance.event("PaiMaiData");
	}

	/**通知上一个竞价的玩家 有人竞价了*/
	__proto.updatePriceNotice=function(msg){
		if(!msg)return;
		var name=msg.roleName;
		var price=msg.price;
		var id=msg.auctionId;
		var vo=this._model.getInfoByAuctionId(id);
		if(!vo)return;
		var itemId=vo.itemId;
		var item=Mgr.item.getItemVO(itemId);
		if(!item)
			return;
		var moneyType=vo.moneyType;
		var moneyName=Mgr.moneyMgr.getMoneyName(moneyType);
		var itemName=item.goodName;
		var desc="您参与竞拍的【"+itemName+"】已被【"+name+"】"+"以"+price+moneyName+"的价格抢拍了，是否前往竞价？";
		AlertUtil.ShowAlert(desc,Handler.create(this,this.jumpToPaiMai),null);
	}

	__proto.jumpToPaiMai=function(){
		UIMgrR.navigateToViewByID(20005);
	}

	// 查询的数据类型，1帮派，2本服，3跨服
	__proto.onGetAuctionInfoSC=function(vo){
		this.auctionInfoDic.set(vo.type,vo);
		this.checkRed();
		EventCenter.instance.event("PaiMaiData");
	}

	// String AuctionLogInfo="80205964";// 查看拍卖的日志数据
	__proto.onAuctionLogInfoSC=function(vo){
		vo.logDatas.sort(this.sortByTime);
		this.auctionLogInfoDic.set(vo.type,vo);
		EventCenter.instance.event("PaiMaiLogData");
	}

	// String AuctionLogDetail="80205965";// 查看拍卖的日志详情
	__proto.onAuctionLogDetailSC=function(vo){
		this._model.updateDetail(vo);
		EventCenter.instance.event("PaiMaiLogDetailData");
	}

	__proto.sortByTime=function(msg1,msg2){
		return msg1.logTime > msg2.logTime ?-1 :1;
	}

	__getset(1,PaiMaiMgr,'ins',function(){
		return PaiMaiMgr._ins=PaiMaiMgr._ins||new PaiMaiMgr();
	});

	PaiMaiMgr._ins=null;
	return PaiMaiMgr;
})()


