	/**材料红点*/
	__proto.checkMaterialRed=function(type){
		var oId=this.model.funTypeAry[type];
		if(!Mgr.guide.isOpen(oId)){
			return;
		}
		if(this.specialPaylineIsOpen(type)){
			return;
		};
		var key=type+"_"+RedTypeEnum.UpgradeTypeMat;
		var funID=this.pyFunObj[type];
		var redBo=this.getUpgradeMateri(type);
		if(redBo)
			this.red.showRedPoint(funID,key,RedTypeEnum.UpgradeRed);
		else
		this.red.hideRedPoint(funID,key,RedTypeEnum.UpgradeRed);
		EventCenter.instance.event("UPGRADE_PAYLINE_MATERIAL");
	}

	__proto.specialPaylineIsOpen=function(type){
		switch(type){
			case 25:{
					if(!Mgr.tianShenActiveMgr.getIfOver()){
						this.red.hideRedPoint(this.pyFunObj[type],type+"_"+RedTypeEnum.UpgradeTypeMat,RedTypeEnum.UpgradeRed);
						return true;
					}
					break ;
				}
			}
		return false;
	}

	/**技能审计*/
