	__proto.getSkillTip=function(ary){
		var len=ary.length;
		var pyLv=this.model.curModel.getPeiYangLevel(this.curPayLinType);
		var minLv=9999;
		var minID="";
		var nextlv=0;
		var jhString;
		for (var i=0;i < len;i++){
			var obj=ary[i];
			if(obj){
				var skillType=obj.skillType;
				if(pyLv < obj.jieshu){
					if(minLv > parseInt(obj.jieshu)){
						minLv=parseInt(obj.jieshu);
						minID=skillType;
						nextlv=1;
						jhString="激活";
					}
				}
				else{
					var skillInfO=this.getSkillInfo(this.curPayLinType,skillType);
					if(skillInfO){
						var tempLv=skillInfO.skillLevel;
						var nextSki=SkillManager.ins.getData(skillType,false,++tempLv);
						if(nextSki && nextSki.levelneed-pyLv <=0){
							for (var j=0;j < 100;j++){
								nextSki=SkillManager.ins.getData(skillType,false,++tempLv);
								if(nextSki){
									if(nextSki.levelneed-pyLv > 0){
										if(minLv > nextSki.levelneed){
											minLv=nextSki.levelneed;
											minID=skillType;
											nextlv=tempLv;
											jhString="升级";
											break ;
										}
									}
								}
								else{
									break
								}
							}
						}
						else{
							if(nextSki && minLv > nextSki.levelneed){
								minLv=nextSki.levelneed;
								minID=skillType;
								nextlv=tempLv;
								jhString="升级";
							}
						}
					}
				}
			}
		}
		if(minID){
			var strAry=[];
			strAry[0]=(minLv-pyLv)+"级";
			var vo=SkillManager.ins.getData(minID,false,1);
			strAry[1]=jhString;
			strAry[2]="【"+vo.name+"】"+nextlv+"级";
			return strAry;
		}
		return null
	}

