//class com.xq.modules.pinnacle.PinnacleMgr
var PinnacleMgr=(function(){
	function PinnacleMgr(){
		this.selectRounds=0;
		this.ifOpen=false;
		/**常量配置*/
		this.model=null;
		/**当前轮次*/
		this._curRounds=0;
		/**轮次信息数组*/
		this._roundsDic=null;
		/**排行榜*/
		this._rankArr=null;
		/**排行榜数据容器*/
		this._rankDc=null;
		/**轮次配置*/
		this._roundsCof=null;
		/**轮次配置DC*/
		this._roundsDc=null;
		/**奖励配置*/
		this._rewardCof=null;
		/**奖励配置Dc*/
		this._rewardDc=null;
		this._roundsDic={};
		this._rankArr=[];
		this.model=new PinnacleConstant();
		this._roundsCof=CfgManager.getTableCfg("dianfengCount");
		this._rewardCof=CfgManager.getTableCfg("dianfengReward");
	}

	__class(PinnacleMgr,'com.xq.modules.pinnacle.PinnacleMgr');
	var __proto=PinnacleMgr.prototype;
	//活动开关
	__proto.registAct=function(){
		var open=Handler.create(this,this.activeStat,[true],false);
		NewActiveManager.ins.regActOpenHandler(105,open);
		NewActiveManager.ins.regActEndHandler(105,Handler.create(this,this.activeStat,[false],false));
	}

	__proto.activeStat=function($ifOpen){
		this.ifOpen=$ifOpen;
		EventCenter.instance.event("updateActivityStat");
	}

	__proto.updateRoundsInfo=function(msg){
		var lun=msg.lun;
		var ele=this.roundsDc.getElement(lun);
		if(ele){
			ele.setValue("server",msg);
			EventCenter.instance.event("updateRoundsInfo");
		}
	}

	__proto.updateRank=function(msg){
		this.clearRank();
		var arr=msg.list;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var rankMsg=arr[i];
			var rank=rankMsg.rank;
			var ele=this.rankDc.getElement(rank);
			if(ele){
				ele.setValue("server",rankMsg);
			}
		}
		EventCenter.instance.event("updateRank");
	}

	__proto.clearRank=function(){
		var arr=this.rankDc.array;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var ele=arr[i];
			ele.setValue("server",null);
		}
	}

	/**支持后刷新*/
	__proto.updateSup=function(msg){
		var matchId=msg.id;
		var roleId=msg.roleId;
		var ele=this.roundsDc.getElement(this.curRounds);
		if(ele){
			var data=ele.getValue("server");
			if(data){
				var arr=data.list;
				var len=arr.length;
				for(var i=0;i<len;i++){
					var vo=arr[i];
					if(vo.id==matchId){
						var playerArr=vo.list;
						var len2=playerArr.length;
						for(var j=0;j<len2;j++){
							var player=playerArr[j];
							if(player.roleId==roleId){
								player.yuanbao=msg.yuanbao;
								player.num=msg.totalCount;
								break ;
							}
						}
						break ;
					}
				}
				data.count=msg.myCount;
				EventCenter.instance.event("updateRoundsInfo");
			}
		}
	}

	/**展示轮次开始tip*/
	__proto.showRoundStart=function(msg){
		var round=msg.round;
		var ele=this.roundsDc.getElement(round);
		if(ele){
			var cof=ele.getCfgData();
			var name=cof.name;
			var sai="赛";
			if(name.indexOf(sai)==-1)name=name+sai;
			var desc="华山论剑"+name+"已经开启，赶紧前围观支持下吧！";
			AlertUtil.ShowAlert(desc,Handler.create(this,this.jumpToView),null);
		}
	}

	__proto.jumpToView=function(){
		UIMgrR.openViewByFunID("Pinnacle",null,2);
	}

	/**轮次状态*/
	__proto.getStat=function(rounds){
		if(!this._curRounds)return 3;
		if(rounds<this._curRounds){
			return 1;
		}
		else if(rounds==this._curRounds){
			return 2;
		}
		else{
			return 3;
		}
	}

	/**检测该轮次剩余支持数是否足够*/
	__proto.checkSupNum=function(rounds){
		var ele=this.roundsDc.getElement(rounds);
		if(ele){
			var msg=ele.getValue("server");
			if(msg){
				var supCount=msg.count;
				var cof=ele.getCfgData();
				var allCount=cof.count;
				return supCount<allCount;
			}
			else{
				return false;
			}
		}
		return false;
	}

	__proto.initFightVo=function(fightVo){
		fightVo.hideAry=[2,3,4];
		fightVo.closeFun=Handler.create(this,this.exit,null,false);
		BattleReportMgr.ins.start();
		BattleReportMgr.ins.closeHandler=Handler.create(this,this.exit,null,false);
	}

	__proto.exit=function(){
		Mgr.pinnacleA.c_quitBattle();
		BattleReportMgr.ins.end();
	}

	__proto.showPromotionTip=function(msg){
		var rounds=msg.curRounds;
		var v=UIMgrR.openIView(com.xq.view.modules.pinnacle.IPinnacleWinTip,3);
		v.dataSource=rounds;
	}

	//配置
	__getset(0,__proto,'rankDc',function(){
		if(!this._rankDc){
			this._rankDc=new DataContainer();
			var len=this.model.maxRank;
			for(var i=0;i<len;i++){
				var ele=new DataElement(null);
				var rank=i+1;
				this._rankDc.addElement(rank,ele);
				ele.setValue("rank",rank);
			}
		}
		return this._rankDc;
	});

	/**轮次配置DC**/
	__getset(0,__proto,'roundsDc',function(){
		if(!this._roundsDc){
			this._roundsDc=new DataContainer();
			var arr=this._roundsCof.objectDataArray;
			var len=arr.length;
			var ele;
			var cof;
			for(var i=0;i<len;i++){
				cof=arr[i];
				ele=new DataElement(cof);
				this._roundsDc.addElement(cof.id,ele);
			}
		}
		return this._roundsDc;
	});

	/**奖励*/
	__getset(0,__proto,'rewardDc',function(){
		if(!this._rewardDc){
			this._rewardDc=new DataContainer();
			var arr=this._rewardCof.objectDataArray;
			var len=arr.length;
			var ele;
			var cof;
			for(var i=0;i<len;i++){
				cof=arr[i];
				ele=new DataElement(cof);
				this._rewardDc.addElement(cof.rank,ele);
			}
		}
		return this._rewardDc;
	});

	//后台数据
	__getset(0,__proto,'curRounds',function(){
		return this._curRounds;
		},function(rounds){
		this._curRounds=rounds;
	});

	return PinnacleMgr;
})()


