//class com.xq.modules.prompt.AttributePrompt
var AttributePrompt=(function(){
	function AttributePrompt(){
		this.attrContainerDic=null;
		this.isPlay=false;
		this.num=0;
		this.index=0;
		this.maxNum=7;
		this.continuePlay=false;
		this.posX=60;
		//0.65
		this.proDic={};
		this._itemArr=[];
		this.posY=Laya.stage.height *0.5;
		this.attrContainerDic={};
		for(var i=0;i< this.maxNum;i++){
			var attrContainer=new Sprite();
			attrContainer.mouseEnabled=false;
			attrContainer.mouseThrough=true;
			attrContainer.x=this.posX;
			attrContainer.y=this.posY+(i-this.maxNum)*30;
			attrContainer.zOrder=1001;
			Laya.stage.addChild(attrContainer);
			attrContainer.zOrder=9999;
			this.attrContainerDic[i]=attrContainer;
		}
		this.isPlay=false;
	}

	__class(AttributePrompt,'com.xq.modules.prompt.AttributePrompt');
	var __proto=AttributePrompt.prototype;
	__proto.getNewAttrContainer=function(){
		if(this.num < this.maxNum && this.continuePlay){
			var c=this.attrContainerDic[this.index++];
			if(c){
				this.num++;
			}
			return c;
		}
		this.continuePlay=false;
		return null;
	}

	__proto.recoverAttrContainer=function(attrContainer){
		this.num--;
		if(this.num==0){
			this.continuePlay=true;
			this.index=0;
		}
	}

	__proto.play=function(attrType,val,isPer){
		var arr=this.proDic[attrType];
		if(!arr){
			arr=[];
			this.proDic[attrType]=arr;
		}
		arr.push([val,isPer]);
		if(!this.isPlay && !this.continuePlay){
			this.isPlay=true;
			this.continuePlay=true;
			this.next();
		}
	}

	__proto.next=function(){
		var attrType=0;
		for(var key in this.proDic){
			attrType=parseInt(key);
			var arr=this.proDic[key];
			if(arr.length > 0){
				break ;
			}
		}
		if(arr.length>0 || !this.continuePlay){
			if(this.continuePlay){
				var attrContainer=this.getNewAttrContainer();
				if(attrContainer){
					var targetArr;
					if(arr){
						var tempVal=0;
						var tempPer=false;
						while(arr.length > 0){
							var tempArr=arr.pop();
							if(tempArr){
								tempVal+=tempArr[0];
								tempPer=tempArr[1];
							}
						}
						if(tempVal > 0){
							targetArr=[tempVal,tempPer];
						}
					};
					var cof=Model.prop.getAttrCofById(attrType);
					var name=cof?cof.mingzi:"";
					var ifPer=targetArr[1];
					var valueStr=ifPer?targetArr[0].toFixed(2)+"%":targetArr[0];
					this.showTxtPrompt(name,valueStr,attrContainer);
					Laya.timer.once(1500,this,this.recoverAttrContainer,[attrContainer],false);
				}
			}
			Laya.timer.once(100,this,this.next);
		}
		else if(arr.length==0 && this.num==0){
			this.isPlay=false;
			this.continuePlay=false;
			}else{
			Laya.timer.once(100,this,this.next);
		}
	}

	/**展示程序字属性变化提示*/
	__proto.showTxtPrompt=function(name,value,target){
		if(this._itemArr.length>0){
			var item=this._itemArr.pop();
		}
		else{
			item=UIMgrR.newInstanceByIClass(com.xq.view.modules.common.IAttrTextPromptItem);
		}
		target.addChild(item);
		item.update(name,value);
		item.startMove(Handler.create(this,this.recoverItem,[item],false));
	}

	__proto.recoverItem=function(item){
		item.dispose();
		this._itemArr.push(item);
	}

	return AttributePrompt;
})()


