//class com.xq.modules.prompt.ExpPrompt
var ExpPrompt=(function(){
	function ExpPrompt(){
		this.expContainer=null;
		this.expArr=null;
		this.isPlay=false;
		this._type=0;
		this._expAddPer=0;
		this._zqAddPer=0;
		this.expContainer=new Box();
		this.expContainer.zOrder=1001;
		this.expContainer.x=400;
		this.expContainer.y=Laya.stage.height-400;
		this.expArr=[];
		this.isPlay=false;
	}

	__class(ExpPrompt,'com.xq.modules.prompt.ExpPrompt');
	var __proto=ExpPrompt.prototype;
	__proto.play=function(exp,activeVal,type){
		(activeVal===void 0)&& (activeVal=0);
		(type===void 0)&& (type=0);
		this.expArr.push([exp,activeVal]);
		this._type=type;
		if(!this.isPlay){
			this.isPlay=true;
			var mainV=Game.getInstance().newMainView;
			if(mainV){
				mainV.addChild(this.expContainer);
				mainV.setChildIndex(this.expContainer,4);
				this._expAddPer=Mgr.tequanMgr.getTequanVal(2)+Mgr.gqMgr.gqInfo.expAdd+100;
				this._zqAddPer=100;
			}
			this.next();
		}
	}

	__proto.next=function(){
		var len=this.expArr.length;
		if(len>0){
			Laya.timer.clear(this,this.removeHand);
			var expNumber=0;
			for(var i=0;i < len;i++){
				var arr=this.expArr.pop();
				expNumber+=arr[0];
			}
			if(expNumber){
				if(this._type==0){
					var suffix="exp";
					var add=this._expAddPer;
				}
				else if(this._type==1){
					suffix="zhenqi";
					add=this._zqAddPer;
				}
				if(arr[1]){
					var all=expNumber+arr[1];
					var addPre=Math.floor((all/expNumber)*100);
					var txt="t+"+(all)+"("+addPre+"%"+")";
				}
				else{
					txt="t+"+expNumber+"("+add+"%"+")";
				};
				var scene=FontUtil.showSceneEffectText(txt,this.expContainer,100,4,2000,150,22,suffix);
			}
			Laya.timer.once(300,this,this.next);
		}
		else{
			Laya.timer.once(2000,this,this.removeHand);
			this.isPlay=false;
		}
	}

	__proto.removeHand=function(){
		this.expContainer.removeSelf();
	}

	return ExpPrompt;
})()


//class com.xq.modules.prompt.FlowerGiftPrompt
var FlowerGiftPrompt=(function(){
	function FlowerGiftPrompt(bgstr){
		/**跑马灯消息数组*/
		this.queueArr=null;
		/**背景图片 */
		this.img=null;
		this.panel=null;
		/**消息部分*/
		this.msgH=null;
		/**滚动距离*/
		this.scrolloffset=0;
		/**是否已经在广播喇叭了*/
		this.isPlay=false;
		this.bgStr=null;
		this.roleVo=null;
		this.bgStr=bgstr;
		this.isPlay=false;
		this.queueArr=[];
		this.msgH=new HTMLDivElement();
		this.msgH.cacheAs="bitmap";
		this.msgH.style.wordWrap=false;
		this.msgH.style.color="#FFFFFF";
		this.msgH.style.fontFamily="SimHei";
		this.msgH.style.fontSize=22;
		this.msgH.y=5;
		this.img=new Image();
		this.img.zOrder=1001;
		this.img.on("loaded",this,this.onLoad);
		this.panel=new Panel();
		this.panel.height=50;
		this.img.mouseThrough=true;
		this.img.mouseEnabled=false;
		this.msgH.mouseThrough=true;
		this.msgH.mouseEnabled=false;
		this.roleVo=NetMgr.ins().roleVO;
	}

	__class(FlowerGiftPrompt,'com.xq.modules.prompt.FlowerGiftPrompt');
	var __proto=FlowerGiftPrompt.prototype;
	__proto.onLoad=function(){
		this.img.sizeGrid="0,80,0,80";
		this.img.width=Laya.stage.width-200;
		this.panel.width=this.img.width-100;
		this.img.centerX=0;
		this.img.top=200;
		this.panel.x=50;
		this.panel.y=10;
		this.panel.addChild(this.msgH);
		this.img.addChild(this.panel);
		Laya.stage.addChild(this.img);
	}

	__proto.play=function(msg){
		this.playMarquee(msg);
		this.playFlowerEffect(msg);
	}

	__proto.playFlowerEffect=function(msg){
		var need1=Mgr.flowerRankM.getNeed1();
		var need2=Mgr.flowerRankM.getNeed2();
		if(msg.meiliVal<need1){
			Mgr.flowerRankM.addEffect();
		}
		else if(msg.meiliVal<need2){
			Mgr.flowerRankM.addParticle(1);
		}
		else{
			Mgr.flowerRankM.addParticle(2);
		}
	}

	/**跑马灯*/
	__proto.playMarquee=function(msg){
		this.queueArr.push(msg);
		this.queueArr.sort(this.compare);
		if(!this.isPlay){
			this.img.skin=null;
			this.img.skin=this.bgStr;
			this.next();
		}
	}

	/**播放下一个跑马灯*/
	__proto.next=function(){
		if(this.queueArr.length>0){
			this.isPlay=true;
			var msg=this.queueArr.shift();
			var str=CodeMgr.ins.getStringByCode([169].concat([msg.sendName,msg.getName,msg.meiliVal]),false)
			this.msgH.innerHTML=str;
			this.scrolloffset=this.panel.width+this.msgH.contextWidth;
			var time=this.scrolloffset*5;
			this.msgH.x=this.panel.width;
			Tween.to(this.msgH,{x:-this.msgH.contextWidth},time,null,HandlerN.create(this,this.next,null,true,"pool_game_notice"));
			this.showSystemMessage(str);
		}
		else{
			this.isPlay=false;
			this.img.removeSelf();
			Laya.loader.clearRes(this.img.skin);
		}
	}

	__proto.showSystemMessage=function(desc){
		var cvo=new ChatAnyCSC();
		cvo.chatType=11;
		cvo.name="";
		cvo.message=desc;
		Mgr.chat.onMessage(cvo,true);
	}

	__proto.compare=function(a,b){
		if(!this.roleVo){
			return 0;
		};
		var name=this.roleVo.name;
		a["showOrder"]=a.id;
		b["showOrder"]=b.id;
		if(name==a.getName||name==a.sendName){
			a["showOrder"]=4;
		}
		if(name==b.getName||name==b.sendName){
			b["showOrder"]=4;
		}
		return b["showOrder"]-a["showOrder"];
	}

	return FlowerGiftPrompt;
})()


