//class com.xq.modules.prompt.QueenPrompt
var QueenPrompt=(function(){
	function QueenPrompt(bgstr){
		/**跑马灯消息数组*/
		this.queenArr=null;
		/**背景图片 */
		this.img=null;
		this.panel=null;
		/**消息部分*/
		this.msgH=null;
		/**滚动距离*/
		this.scrolloffset=0;
		/**是否已经在广播喇叭了*/
		this.isPlay=false;
		this.bgStr=null;
		this.bgStr=bgstr;
		this.isPlay=false;
		this.queenArr=[];
		this.msgH=new HTMLDivElement();
		this.msgH.cacheAsBitmap=true;
		this.msgH.style.wordWrap=false;
		this.msgH.style.color="#FFFFFF";
		this.msgH.style.fontFamily="SimHei";
		this.msgH.style.fontSize=22;
		this.img=new Image();
		this.img.zOrder=1001;
		this.img.on("loaded",this,this.onLoad);
		this.panel=new Panel();
		this.panel.height=35;
		this.img.mouseThrough=true;
		this.img.mouseEnabled=false;
		this.msgH.mouseThrough=true;
		this.msgH.mouseEnabled=false;
	}

	__class(QueenPrompt,'com.xq.modules.prompt.QueenPrompt');
	var __proto=QueenPrompt.prototype;
	__proto.onLoad=function(){
		this.img.width=Laya.stage.width-200;
		this.panel.width=this.img.width;
		this.img.centerX=0;
		this.img.top=145+Configs.OFFSET_TOP;
		this.panel.addChild(this.msgH);
		this.img.addChild(this.panel);
		Laya.stage.addChild(this.img);
	}

	__proto.play=function(msg){
		this.queenArr.push(msg);
		if(!this.isPlay){
			this.img.skin=null;
			this.img.skin=this.bgStr;
			this.next();
		}
	}

	/**播放下一个跑马灯*/
	__proto.next=function(){
		if(this.queenArr.length>0){
			this.isPlay=true;
			this.msgH.innerHTML=this.queenArr.shift();
			this.scrolloffset=this.img.width+this.msgH.contextWidth;
			var time=Math.max(this.scrolloffset*10,3000);
			this.msgH.x=this.img.width;
			Tween.to(this.msgH,{x:-this.scrolloffset},time,null,HandlerN.create(this,this.next,null,true,"pool_game_notice"));
		}
		else{
			this.isPlay=false;
			this.img.removeSelf();
			Laya.loader.clearRes(this.img.skin);
		}
	}

	return QueenPrompt;
})()


