/**
*@author:huanghong
*@date:2021-4-19
*@desc:
*/
//class com.xq.modules.PropMgr
var PropMgr=(function(){
	function PropMgr(){
		this._model
		this._model=Model.prop;
	}

	__class(PropMgr,'com.xq.modules.PropMgr');
	var __proto=PropMgr.prototype;
	/**属性公式1 总属性=基础战力*等级系数+基础战力 *(每级增长系数*(等级*(等级-1))/2)
	*color:为了适配以前 同一个render不用颜色的需求
	**/
	__proto.attrFormula1=function(propId,per,perAdd,lv,color){
		(color===void 0)&& (color="#FFFFFF");
		var propArr=Model.prop.getPropById(propId);
		var len=propArr.length;
		for(var i=0;i<len;i++){
			var vo=propArr[i];
			var val=lv? Math.floor(vo.attrVal*(per*lv+(perAdd*(lv*(lv-1))/2))):0;
			vo.attrVal=val;
			if(color){
				vo.color=color;
			}
		}
		return propArr;
	}

	/**属性公式2 总属性=基础属性+(总等级-1)*此系数*基础属性*/
	__proto.attrFormula2=function(propId,per,lv){
		var propArr=Model.prop.getPropById(propId);
		var len=propArr.length;
		for(var i=0;i<len;i++){
			var vo=propArr[i];
			var val=lv? Math.floor(vo.attrVal+(lv-1)*per*vo.attrVal):0;
			vo.attrVal=val;
		}
		return propArr;
	}

	/**属性公式3 总属性=此系数*基础属性*/
	__proto.attrFormula3=function(propId,per){
		var propArr=Model.prop.getPropById(propId);
		var len=propArr.length;
		for(var i=0;i<len;i++){
			var vo=propArr[i];
			var val=vo.attrVal*per;
			vo.attrVal=val;
		}
		return propArr;
	}

	/**属性公式4 总属性=基础属性+(总等级-1)*每级增长系数*基础属性） 如果等级为0 则为0*/
	__proto.attrFormula4=function(propId,per,lvPer,lv){
		var propArr=Model.prop.getPropById(propId);
		var len=propArr.length;
		for(var i=0;i<len;i++){
			var vo=propArr[i];
			var val=lv? Math.floor(vo.attrVal+(lv-1)*per*lvPer*vo.attrVal):0;
			vo.attrVal=val;
		}
		return propArr;
	}

	/**属性公式5 总属性=基础属性+(每级增长系数*基础属性） 如果等级为0 则为0*/
	__proto.attrFormula5=function(propId,per,lvPer,lv){
		var propArr=Model.prop.getPropById(propId);
		var len=propArr.length;
		for(var i=0;i<len;i++){
			var vo=propArr[i];
			var val=lv?Math.floor(vo.attrVal+per*lvPer*vo.attrVal):0;
			vo.attrVal=val;
		}
		return propArr;
	}

	/**属性工具1 计算一组属性的某倍率*/
	__proto.attrUtil1=function(arr,per){
		if(!arr)return[];
		var newArr=arr.concat();
		var len=newArr.length;
		for(var i=0;i<len;i++){
			var vo=newArr[i];
			var val=Math.floor(vo.attrVal*per);
			vo.attrVal=val;
		}
		return newArr;
	}

	/**属性战力计算工具 计算一组属性的总战力*/
	__proto.attrFVUtil=function(arr){
		if(!arr)return 0;
		var len=arr.length;
		var fv=0;
		for(var i=0;i<len;i++){
			var vo=arr[i];
			fv+=vo.attrFV;
		}
		return fv;
	}

	/**获取属性条描述 name+值;name+值*/
	__proto.attrDescStr=function(arr){
		if(!arr)return "";
		var len=arr.length;
		var attrTxt="";
		for(var i=0;i<len;i++){
			var vo=arr[i];
			attrTxt+=vo.ifPer?vo.cnName+"+"+Math.round((vo.attrVal*10000))/100+"%":vo.cnName+"+"+vo.attrVal;
			if(i!=len-1){
				attrTxt+=";"
			}
		}
		return attrTxt;
	}

	/**
	*支持一下两种数据结构转换成PropAttrVo；
	*physicdamageJin:20000;physicdefenceJin:20000
	*["physicdamageJin:20000","physicdefenceJin:20000"]
	**/
	__proto.cofAttrUnit=function(attr){
		if(!attr)return [];
		var arr;
		if((attr instanceof Array)){
			arr=attr;
		}
		else{
			arr=attr.split(";")
		};
		var changeArr=[];
		var len=arr.length;
		for(var i=0;i<len;i++){
			var attrStr=arr[i];
			var tmpArr=attrStr.split(":");
			var vo=new PropAttrVo();
			vo.setData(tmpArr);
			changeArr.push(vo);
		}
		return changeArr;
	}

	/**
	*attrType:0：不展示属性1:展示基础属性 2：展示特殊属性
	**/
	__proto.getAttrsByTeShu=function(attrType){
		return this._model.getAttrsByTeShu(attrType);
	}

	/**计算增加属性值*/
	__proto.setNextAddAttr=function(curAttrs,nextAttrs){
		if(!curAttrs)return [];
		if(!nextAttrs||nextAttrs.length==0)return curAttrs;
		var len=curAttrs.length;
		var propVo;
		var nextVo;
		for(var i=0;i<len;i++){
			nextVo=nextAttrs[i];
			if(!nextVo)continue ;
			propVo=curAttrs[i];
			if(propVo.ifShow){
				propVo.nextLvAddVal=nextVo.showVal-propVo.showVal;
			}
			else{
				propVo.nextLvAddVal=nextVo.attrVal-propVo.attrVal;
			}
		}
		return curAttrs;
	}

	return PropMgr;
})()


