	__proto.updatePanel=function(vo,type){
		this.object=vo;
		switch(type){
			case 3:{
					this.lianXuChongZhi();
					break ;
				}
			case 4:{
					this.shouChongTuanGou();
					break ;
				}
			case 5:{
					break ;
				}
			case 6:{
					break ;
				}
			case 8:{
					this.chongZhiHaoLi();
					break ;
				}
			}
	}

	/**直购连反*/
	__proto.lianXuChongZhi=function(){
		var arr=this.table_lianxu.getAllItemByFiled("id",this.object.curContinueDay);
		var current=this.object.curDayConsume;
		var goal=parseInt(arr[0].mubiao);
		var len=this.object.rewardList.length;
		for (var i=0;i < len;i++){
			if(current>=goal&&this.object.rewardList[i].rewardStatus==2){
				this.zhiRed=true;
				break ;
				}else{
				this.zhiRed=false;
			}
		}
	}

	/**首充团购*/
	__proto.shouChongTuanGou=function(){
		var rechargePlayerNum=this.object.rechargePlayerNum;
		var YuanBao=this.object.playerRechargeYuanBao;
		var arra=this.table_shouchong.getAllItemByFiled("actTimeId",this.object.actTimeId);
		var len=arra.length;
		this.red.hideRedPoint("shouchongtuangou","sctg","UPDATE_FANLIDATING_RED_POINT");
		for (var i=0;i < len;i++){
			var peopleCnt=parseInt(arra[i].peopleCnt);
			var rmb=parseInt(arra[i].rmb);
			if(rechargePlayerNum>=peopleCnt&&YuanBao>=rmb&&parseInt(this.object.getRewardRecord[i].value)==0){
				this.red.showRedPoint("shouchongtuangou","sctg","UPDATE_FANLIDATING_RED_POINT");
				break ;
			}
		}
	}

	/**原充值好礼，现改名为每日累充*/
	__proto.chongZhiHaoLi=function(){
		this.red.hideRedPoint("chongzhihaoli","mrlc","UPDATE_FANLIDATING_RED_POINT");
		this.arrCReceive=this.object.rewards;
		var len=this.arrCReceive.length;
		for (var i=0;i < 6;i++){
			if(this.arrCReceive[i].awarded==0 && this.object.progress >=this.chongZhiHaoLiDic[this.arrCReceive[i].id].targetValue){
				this.red.showRedPoint("chongzhihaoli","mrlc","UPDATE_FANLIDATING_RED_POINT");
				break ;
			}
		}
	}

