	/**天天返利*/
	__proto.ttFanli=function(info){
		this.red.hideRedPoint("tiantianfanli","ttfl","UPDATE_FANLIDATING_RED_POINT");
		var ttArr=[];
		var arr=info.rewardList;
		var len=arr.length;
		for (var i=0;i < len;i++){
			var msg=arr[i];
			var ttVO=this.createTTVO(msg,info.curDayConsume);
			if(!ttVO)continue ;
			if (msg.rewardStatus==1){
				this.red.showRedPoint("tiantianfanli","ttfl","UPDATE_FANLIDATING_RED_POINT");
			}
			ttArr.push(ttVO);
		}
		ttArr.sort(this.compare);
		EventCenter.instance.event("tiantianfanli",[info,ttArr]);
	}

	// checkIconRed();
	__proto.compare=function(o1,o2){
		if (parseInt(o1.id)> parseInt(o2.id)){
			return 1;
		}
		else if (parseInt(o1.id)< parseInt(o2.id)){
			return-1;
		}
		else{
			return 0;
		}
	}

	__proto.getJinJieRiInfo=function(actId){
		var arra=this.table_jinjie.getAllItemByFiled("actId",actId);
		return arra;
	}

	/**创建天天返利vo*/
	__proto.createTTVO=function(msg,progress){
		if(!msg || !msg.day)return null;
		var obj=this.getRechargeObj(msg.day);
		if(!obj)return null;
		var o=new OperationActivityVO();
		o.activityType="tiantianfanli";
		o.rewards=obj.items;
		o.awarded=msg.rewardStatus;
		o.targetValue=obj.num;
		o.value=progress;
		o.id=obj.id;
		return o;
	}

	/**购买或领取零元购奖励重组零元购数据*/
	__proto.regroupLingYuanGou=function(msg){
		var len=this.lingYuanGouSerArr.length;
		for (var i=0;i < len;i++){
			if(this.lingYuanGouSerArr[i].configId==msg.configId){
				this.lingYuanGouSerArr[i]=msg;
				break ;
			}
		}
		this.lingYuanGou();
	}

	/**惊喜零元购数据和红点处理*/
	__proto.lingYuanGou=function(){
		this.lingYuanGouInfoArr=[];
		var rewardArr=this.lingYuanGouSerArr;
		var len=rewardArr.length;
		var isOpen=false;
		var isTime=false;
		var isCanGouMai=false;
		for (var i=0;i < 3;i++){
			var lingYuanGouInfo1=new Object();
			var msg=rewardArr[i];
			if(!msg)return;
			var cfgObj=this.getLingYuanGouById(msg.configId);
			lingYuanGouInfo1.cfg=cfgObj;
			lingYuanGouInfo1.ser=msg;
			if(msg.getMoneyTime > Mgr.curTime.serverTimer && !isTime){
				isTime=true;
				Laya.timer.once(msg.getMoneyTime-Mgr.curTime.serverTimer,this,this.getLingYuanGouInfo);
			}
			if(msg.getRewardState !=2 || msg.getMoneyState !=2){
				isOpen=true;
			}
			if(msg.getMoneyState==0){
				var taiYuNum=NetMgr.ins().roleVO.taiYu;
				if(taiYuNum >=parseInt(cfgObj.price.split(":")[1])){
					isCanGouMai=true;
				}
			}
			if(msg.getRewardState==1){
				this.red.showRedPoint("jingxilingyuangou",cfgObj.id+"_1" ,RedTypeEnum.JingXiLingYuanGouRed);
			}
			else{
				this.red.hideRedPoint("jingxilingyuangou",cfgObj.id+"_1",RedTypeEnum.JingXiLingYuanGouRed);
			}
			if(msg.getMoneyState==1){
				this.red.showRedPoint("jingxilingyuangou",cfgObj.id+"_2" ,RedTypeEnum.JingXiLingYuanGouRed);
			}
			else{
				this.red.hideRedPoint("jingxilingyuangou",cfgObj.id+"_2",RedTypeEnum.JingXiLingYuanGouRed);
			}
			this.lingYuanGouInfoArr.push(lingYuanGouInfo1);
		}
		if(this.isFirst && isCanGouMai){
			this.isFirst=false;
			Laya.timer.once(1000,this,this.delayOpenQiPao);
		}
		if(isOpen){
			EventCenter.instance.event("ACTIVE_TOGGLE",["jingxilingyuangou",false]);
			}else{
			EventCenter.instance.event("ACTIVE_TOGGLE",["jingxilingyuangou"]);
		}
		EventCenter.instance.event("JING_XI_LING_YUAN_GOU");
	}

	__proto.delayOpenQiPao=function(){
		if(Configs.isForbitIOSPay||Configs.isForbitAndroidPay){
			return;
		};
		var lingYuanGouRender=Game.getInstance().getNewMainView().getCenterRender().getIonRender("jingxilingyuangou");
		var tarPos=new Point(lingYuanGouRender.x,lingYuanGouRender.y);
		if(lingYuanGouRender.parent){
			tarPos=(lingYuanGouRender.parent).localToGlobal(tarPos);
			}else{
			return;
		}
		if(!this.lingYuanGouQiPao){
			this.lingYuanGouQiPao=UIMgrR.newInstanceByIClass(com.xq.view.mainUI.subPanel.IQiPaoTip)
		};
		var obj={};
		obj["viewId"]=64601;
		obj["code"]=260833;
		this.lingYuanGouQiPao.dataSource=obj;
		this.lingYuanGouQiPao.open();
		Game.getInstance().getNewMainView().addViewToHide(this.lingYuanGouQiPao,1);
		Game.getInstance().mainQiPaoView.addChild(this.lingYuanGouQiPao);
		this.lingYuanGouQiPao.zOrder=999;
		var offsetX=20;
		this.lingYuanGouQiPao.x=tarPos.x+offsetX;
		this.lingYuanGouQiPao.y=tarPos.y+lingYuanGouRender.height;
	}

