//class com.xq.modules.relationship.RelationshipTianShenMgr
var RelationshipTianShenMgr=(function(){
	function RelationshipTianShenMgr(){
		//----------------------------------------------------
		this.fetterSkillCfg=null;
		//-----------------------------------------------
		this.oldSkillList=[];
		this.firstLevelCfgs=null;
		this.fetterDatas=new Dictionary();
		this.setup();
	}

	__class(RelationshipTianShenMgr,'com.xq.modules.relationship.RelationshipTianShenMgr');
	var __proto=RelationshipTianShenMgr.prototype;
	__proto.setup=function(){
		this.fetterSkillCfg=CfgManager.getTableCfg("ShenJiangJiBan");
		Mgr.red.regist("zhuzhan","jiBan",true,RedTypeEnum.HeroSystemRed);
		Mgr.red.regist("jiBan","jiBanTab",false,RedTypeEnum.HeroTabRed);
		Mgr.red.registSilRed("jiBanInfo","JiBanInfoEvent");
		EventCenter.instance.onQue("ITEM_CHANGE" ,this ,this.onBagChange);
		EventCenter.instance.on("update_card_head",this,this.updateSkill);
	}

	__proto.onBagChange=function(){
		this.checkRed();
	}

	__proto.checkRed=function(){
		if(!Mgr.guide.isOpen("jiBan")){
			return;
		};
		var list=this.firstLevelFettersCfgs;
		var len=list.length;
		var firstCfg;
		var curCfg;
		var boo=false;
		var majorDic=new Dictionary();
		for (var i=0;i < len;i++){
			firstCfg=list[i];
			curCfg=com.xq.modules.relationship.RelationshipTianShenMgr.ins.getFetterCfg(firstCfg.id,com.xq.modules.relationship.RelationshipTianShenMgr.ins.getFetterLevel(firstCfg.id));
			if(!curCfg)
				continue ;
			var boo2=this.checkSelf(curCfg);
			var boo1=this.checkSkill(curCfg);
			if((boo1 || boo2)){
				majorDic.set(curCfg.majorID,true);
				if(!boo){
					boo=true;
				}
			}
			else{
				if(majorDic.indexOf(curCfg.majorID)==-1)
					majorDic.set(curCfg.majorID,false);
			}
		};
		var keys=majorDic.keys;
		len=keys.length;
		var key=0;
		for(var j=0;j < len;j++){
			key=keys[j];
			if(majorDic.get(key)){
				Mgr.red.showRedPoint("jiBanInfo","JiBanTab2Key"+key,"JiBanInfoEvent");
			}
			else{
				Mgr.red.hideRedPoint("jiBanInfo","JiBanTab2Key"+key,"JiBanInfoEvent");
			}
		}
		if(boo){
			Mgr.red.showRedPoint("jiBan","JiBanKey",RedTypeEnum.HeroSystemRed);
			Mgr.red.showRedPoint("jiBanTab","JiBanTabKey",RedTypeEnum.HeroTabRed);
		}
		else{
			Mgr.red.hideRedPoint("jiBan","JiBanKey",RedTypeEnum.HeroSystemRed);
			Mgr.red.hideRedPoint("jiBanTab","JiBanTabKey",RedTypeEnum.HeroTabRed);
		}
	}

	__proto.checkSkill=function(curCfg){
		if(this.getFetterLevel(curCfg.id)<=0){
			Mgr.red.hideRedPoint("jiBanInfo","JiBanSkillKey"+curCfg.id,"JiBanInfoEvent");
			return false;
		};
		var skillLevel=this.getFetterSkillLevel(curCfg.id);
		var curSkillVo=SkillManager.ins.getData(curCfg.skillId,false,skillLevel);
		if(curSkillVo &&
			SkillManager.ins.getData(curCfg.skillId,false,skillLevel+1)&&
		this.isCanUpgrade(curSkillVo.itemneed)){
			Mgr.red.showRedPoint("jiBanInfo","JiBanSkillKey"+curCfg.id,"JiBanInfoEvent");
			return true;
		}
		Mgr.red.hideRedPoint("jiBanInfo","JiBanSkillKey"+curCfg.id,"JiBanInfoEvent");
		return false;
	}

	__proto.checkSelf=function(curCfg){
		if(curCfg.level <=0){
			if(this.isCanActive(curCfg)){
				Mgr.red.showRedPoint("jiBanInfo","JiBanSelfKey"+curCfg.id,"JiBanInfoEvent");
				return true;
			}
			Mgr.red.hideRedPoint("jiBanInfo","JiBanSelfKey"+curCfg.id,"JiBanInfoEvent");
			return false;
		}
		if(this.isMaxLevel(curCfg.id,curCfg.level)){
			Mgr.red.hideRedPoint("jiBanInfo","JiBanSelfKey"+curCfg.id,"JiBanInfoEvent");
			return false;
		}
		if(this.isCanUpgrade(curCfg.item)){
			Mgr.red.showRedPoint("jiBanInfo","JiBanSelfKey"+curCfg.id,"JiBanInfoEvent");
			return true;
		}
		Mgr.red.hideRedPoint("jiBanInfo","JiBanSelfKey"+curCfg.id,"JiBanInfoEvent");
		return false;
	}

	__proto.updateSkill=function(){
		var shenjiangInfo=Mgr.subPlayer.getSubplayerVo(0);
		if(!shenjiangInfo)
			return;
		var mdl=Mgr.skillGroup.getSkillModel(shenjiangInfo.roleId);
		if(!mdl)
			return;
		var headArr=Mgr.subPlayer.getHeroHeadList();
		if(!headArr)return;
		var mingap=Mgr.heroSysMgr.heroModel.minGap;
		var len=headArr.length;
		var type=0;
		var obj;
		var szId=0;
		for (var i=0;i < len;i++){
			var subplayerVo=headArr[i];
			if(!subplayerVo)
				continue ;
			var sjId=subplayerVo.shenJiangType;
			if(sjId <=0)
				continue ;
			type=0;
			if(sjId > mingap){
				obj=Mgr.szMgr.getCfgById(sjId+"");
				if(obj && obj.type==13){
					szId=obj.huanhuaid;
					break ;
				}
			}
		};
		var newSkillList=[];
		var newSkillVo;
		if(szId > 0){
			var objs=this.getFettersCfgByTianShenId(szId);
			if(objs){
				len=objs.length;
				for(i=0;i < len;i++){
					obj=objs[i];
					var fetterSkillMsg=this.getFetterData(obj.id);
					if(fetterSkillMsg){
						newSkillVo=SkillManager.ins.getData(obj.skillId,false,fetterSkillMsg.skillLv);
						if(newSkillVo.type==1)
							newSkillList.push(newSkillVo);
					}
				}
			}
		}
		len=this.oldSkillList.length;
		for(i=0;i < len;i++){
			newSkillVo=this.oldSkillList[i];
			mdl.removeSkillByType(newSkillVo.skillType);
		}
		len=newSkillList.length;
		for(i=0;i < len;i++){
			newSkillVo=newSkillList[i];
			mdl.addModelSkill(newSkillVo.skillType,newSkillVo,"JI_BAN");
		}
		this.oldSkillList=newSkillList;
	}

	/**
	*得到配置数据
	*@param id
	*@return
	*
	*/
	__proto.getFetterCfg=function(id,level){
		return this.fetterSkillCfg.getCfgMsgByTwoKey("id",id,"level",level);
	}

	__proto.getFettersCfgByMajorID=function(majorID){
		var alls=this.fetterSkillCfg.getItemsByField("majorID",majorID);
		var len=alls.length;
		if(len <=0)
			return null;
		var list=[];
		var cfgObj;
		for(var i=0;i < len;i++){
			cfgObj=alls[i];
			if(cfgObj.level==0){
				list.push(cfgObj);
			}
		}
		if(list.length <=0)
			return null;
		return list;
	}

	__proto.getFetterTab=function(){
		var alls=this.fetterSkillCfg.objectDataArray;
		var len=alls.length;
		if(len <=0)
			return null;
		var list=[];
		var list2=[];
		var cfgObj;
		for(var i=0;i < len;i++){
			cfgObj=alls[i];
			if(list2.indexOf(cfgObj.majorID)==-1){
				list2.push(cfgObj.majorID);
				list.push(cfgObj);
			}
		}
		if(list.length <=0)
			return null;
		return list;
	}

	__proto.getFettersCfgByTianShenId=function(id){
		var alls=this.fetterSkillCfg.objectDataArray;
		var len=alls.length;
		if(len <=0)
			return null;
		var list=[];
		var cfgObj;
		for(var i=0;i < len;i++){
			cfgObj=alls[i];
			if(!cfgObj.shenJiangIds)
				continue ;
			var suits=cfgObj.shenJiangIds.split(";");
			if(-1 !=suits.indexOf(id+"")){
				list.push(cfgObj);
			}
		}
		if(list.length <=0)
			return null;
		return list;
	}

	/**
	*得到羁绊数据
	*@param id
	*@return
	*
	*/
	__proto.getFetterData=function(id){
		return this.fetterDatas.get(id);
	}

	__proto.getAllFetterData=function(){
		return this.fetterDatas.values;
	}

	__proto.isActive=function(id){
		var msg=this.getFetterData(id);
		if(msg)
			return msg.currLv > 0;
		return false;
	}

	__proto.getFetterLevel=function(id){
		var msg=this.getFetterData(id);
		if(msg)
			return msg.currLv;
		return 0;
	}

	__proto.getFetterSkillLevel=function(id){
		var msg=this.getFetterData(id);
		if(msg)
			return msg.skillLv;
		return 0;
	}

	/**
	*羁绊是否满级
	*@param id
	*@param level
	*@return
	*
	*/
	__proto.isMaxLevel=function(id,level){
		return !(this.getFetterCfg(id,parseInt(level)+1));
	}

	//-------------------------------------------------------------
	__proto.isCanActive=function(cfgObj,isHint){
		(isHint===void 0)&& (isHint=false);
		var suits=cfgObj.shenJiangIds.split(";");
		var len=suits.length;
		var id=0;
		for(var i=0;i < len;i++){
			id=parseInt(suits[i]);
			if(!Mgr.szMgr.szModel.huanhuaDic[id]){
				if(isHint)
					Mgr.prompt.optionPrompt("羁绊有未激活的侠客，无法激活羁绊");
				return false;
			}
		}
		return true;
	}

	__proto.isCanUpgrade=function(cost,isHint){
		(isHint===void 0)&& (isHint=false);
		if(!cost)
			return true;
		var ary=cost.split(":");
		if(ary.length < 2)
			return true;
		var num=Mgr.bag.getBagMatCount(ary[0]);
		var isE=num >=ary[1];
		if(!isE){
			if(isHint)
				Mgr.prompt.optionPrompt("消耗物品不足！无法升级");
			return false;
		}
		return true;
	}

	/**获取羁绊技能相关的数据操作 */
	__proto.onGetFetterSkillInfoSC=function(vo){
		this.fetterDatas.clear();
		if(vo && vo.fetterDatas){
			var len=vo.fetterDatas.length;
			var msgVo;
			for(var i=0;i < len;i++){
				msgVo=vo.fetterDatas[i];
				this.fetterDatas.set(msgVo.id,msgVo);
			}
		}
		this.checkRed();
		this.updateSkill();
	}

	/**激活羁绊技能的操作*/
	__proto.reqActiveFetterSkillCS=function(cfgObj){
		if(!this.isCanActive(cfgObj,true))
			return;
		RelationshipTianShenAction.ins.reqActiveFetterSkillCS(cfgObj.id);
	}

	/**激活羁绊技能的操作 返回 */
	__proto.onActiveFetterSkillSC=function(vo){
		this.fetterDatas.set(vo.fetterData.id,vo.fetterData);
		var activeView=UIMgrR.openIView(com.xq.view.modules.relationship.IRelationshipTianShenActiveView,2);
		activeView.dataSource=vo.fetterId;
		this.checkRed();
		this.updateSkill();
		EventCenter.instance.event("ACTIVE_RELATIONSHIP_TIAN_SHEN");
	}

	/**激活羁绊技能的操作*/
	__proto.reqFetterSkillUpgradeCS=function(type,cfgObj){
		if(!this.isCanUpgrade(cfgObj.item,true))
			return;
		RelationshipTianShenAction.ins.reqFetterSkillUpgradeCS(type,cfgObj.id);
	}

	__proto.reqFetterSkillUpgradeCS2=function(type,cfgObj,curSkillVo){
		if(!this.isActive(cfgObj.id)){
			Mgr.prompt.optionPrompt("尚未激活羁绊，无法升级技能");
			return;
		}
		if(!this.isCanUpgrade(curSkillVo.itemneed,true))
			return;
		RelationshipTianShenAction.ins.reqFetterSkillUpgradeCS(type,cfgObj.id);
	}

	/**羁绊或是羁绊技能升级操作 返回 */
	__proto.onFetterSkillUpgradeSC=function(vo){
		this.fetterDatas.set(vo.fetterData.id,vo.fetterData);
		this.checkRed();
		switch(vo.type){
			case 0:
				EventCenter.instance.event("UPGRADE_RELATIONSHIP_TIAN_SHEN");
				break ;
			case 1:
				EventCenter.instance.event("UPGRADE_LEVEL_RELATIONSHIP_TIAN_SHEN");
				break ;
			}
	}

	/**羁绊技能可以激活的状态变化推送 */
	__proto.onFetterSkillUpdateSC=function(vo){
		this.checkRed();
		EventCenter.instance.event("CAN_ACTIVE_RELATIONSHIP_TIAN_SHEN");
	}

	__getset(0,__proto,'firstLevelFettersCfgs',function(){
		if(this.firstLevelCfgs)
			return this.firstLevelCfgs;
		this.firstLevelCfgs=[];
		var alls=this.fetterSkillCfg.objectDataArray;
		var len=alls.length;
		if(len <=0)
			return null;
		var cfgObj;
		for(var i=0;i < len;i++){
			cfgObj=alls[i];
			if(cfgObj.level==0){
				this.firstLevelCfgs.push(cfgObj);
			}
		}
		return this.firstLevelCfgs;
	});

	__getset(0,__proto,'hasActive',function(){
		return this.fetterDatas.values.length > 0;
	});

	__getset(1,RelationshipTianShenMgr,'ins',function(){
		return RelationshipTianShenMgr._ins=RelationshipTianShenMgr._ins||new RelationshipTianShenMgr();
	});

	RelationshipTianShenMgr._ins=null;
	return RelationshipTianShenMgr;
})()


