//class com.xq.modules.singleCopy.growUpCopy.GrowUpModel
var GrowUpModel=(function(){
	function GrowUpModel(){
		this.copyTable=null;
		this.copyDic=null;
		this.copys=null;
		this.copyDic=new Dictionary();
		this.copyTable=CfgManager.getTableCfg("Cailiaofubenbiao");
		this.parseCopyData();
	}

	__class(GrowUpModel,'com.xq.modules.singleCopy.growUpCopy.GrowUpModel');
	var __proto=GrowUpModel.prototype;
	__proto.parseCopyData=function(){
		this.copyDic=new Dictionary();
		var datas=this.copyTable.getItemsByField("ty","2");
		if(!datas)return;
		var len=datas.length;
		var type=0;
		for(var i=0;i<len;i++){
			type=parseInt(datas[i].type);
			if(!this.copyDic.get(type)){
				this.copyDic.set(type,this.copyTable.getItemsByField("type",String(type)));
			}
		};
		var copys=this.copyDic.values.concat();
		copys.sort(this.sortCopy);
		len=copys.length;
		for(var j=0;j<len;j++){
			if(!Mgr.guide.isOpen(copys[j][0].func)){
				this.copyDic.remove(parseInt(copys[j][0].type));
			}
		}
	}

	/**排序*/
	__proto.sortCopy=function(arr1,arr2){
		var turn1=parseInt(arr1[0].turn);
		var turn2=parseInt(arr2[0].turn);
		if(turn1 > turn2){
			return 1;
		}
		else if(turn1 < turn2){
			return-1;
		}
		return 0;
	}

	return GrowUpModel;
})()


