/**
*商城管理
*@author xiangjia
*@date 2019-11-13
*/
//class com.xq.modules.store.StoreMgr
var StoreMgr=(function(){
	function StoreMgr(){
		this._model=null;
		this.quanjuCfg=null;
		/**出售列表缓存*/
		this.storeItemDic=null;
		/**已显示物品字典*/
		this.showItemDic=null;
		/**代币与moneyType之间的映射关系*/
		this.moneyTypeDaiBi={};
		/**某种物品购买数量*/
		this.goodBuyCount={};
		/**宗门帮贡*/
		this.bangong=0;
		this.nextRefreshTime=NaN;
		/**打开面板类型 0按钮 1是其他*/
		this.openType=1;
		this.showEffTemplateId=null;
		this.curStoreId=0;
		this.buyCountDic=null;
		/**
		*神秘商店数组
		*/
		this.randomArr=[];
		this.randomItems=[];
		this.randomShopRefreshTimes=-1;
		this._model=new StoreModel();
		this.buyCountDic=new Dictionary();
		this.quanjuCfg=CfgManager.getTableCfg("Config");
		this.storeItemDic={};
		this.showItemDic={};
	}

	__class(StoreMgr,'com.xq.modules.store.StoreMgr');
	var __proto=StoreMgr.prototype;
	/**
	*初始化
	**/
	__proto.init=function(){
		this.registRed();
		if(Configs.isForbitIOSPay||Configs.isForbitAndroidPay){
			UIMgrR.uiMgr.forbitUIPage("20001");
			UIMgrR.uiMgr.forbitUIPage("70007");
		}
	}

	/**判断 传入的道具 再限购商城 是否有购买次数*/
	__proto.getIsBuyById=function(itemId){
		this.getItemListByType(3001);
		return this.buyCountDic.get(itemId);
	}

	__proto.onVIPSVIPUp=function(){
		Mgr.vip.sendVipShopInfo();
	}

	/**
	*每日重置数据
	**/
	__proto.resetData=function(){
		if(!Mgr.guide.isOpen("shangcheng")){
			EventCenter.instance.on("new_function_open",this,this.storeOpen);
		}
		else{
			this.send();
		}
	}

	__proto.getStoreCfg=function(){
		return this._model.getStoreCfg();
	}

	/**通过道具Id获取对应得配置ele*/
	__proto.getStoreEle=function(id){
		return this._model.getStoreEle(id);
	}

	/**检测道具是否在商城中有售卖(默认日常普通商店)*/
	__proto.checkIsGood=function(id,storeType){
		(storeType===void 0)&& (storeType=2001);
		var ele=this._model.getStoreEleByPage(storeType,id);
		if(!ele)return false;
		return true;
	}

	__proto.send=function(){
		Mgr.storePro.sendGetVertureItem();
		Mgr.storePro.sendGetBuyHistory();
		Mgr.vip.sendVipShopInfo();
	}

	__proto.storeOpen=function(funcId){
		if(funcId=="shangcheng"){
			EventCenter.instance.off("new_function_open",this,this.onStoreFuncOpen);
			this.send();
		}
	}

	/**
	*@param pageType:参考枚举 SotrePageType
	**/
	__proto.getItemListByType=function(pageType){
		var array=this.storeItemDic[pageType];
		if(array==null)
			array=[];
		var cfgArray=[];
		var len=cfgArray.length;
		var sellIds;
		var sellId;
		var sex=NetMgr.ins().roleVO.sex;
		for (var i=0;i < len;i++){
			var cfgItem=cfgArray[i];
			if(this.showItemDic[cfgItem.id]){
				var leng=array.length;
				var index=-1;
				for(var j=0;j<leng;j++){
					if(array[j].cfgItem.id==cfgItem.id){
						index=j;
						break ;
					}
				}
				if(index!=-1&&!this.checkIsShow(array[index])){
					this.showItemDic[cfgItem.id]=false;
					array.splice(index,1);
				}
				continue ;
			};
			var vo=new StoreItemVo();
			vo.setData(cfgItem);
			if(this.checkIsShow(vo)){
				this.showItemDic[cfgItem.id]=true;
				array.push(vo);
			}
		}
		this.storeItemDic[pageType]=array;
		this.updateBoughtCount(pageType ,array);
		return array;
	}

	__proto.updateBoughtCount=function(pageType,dataSource){
		var showRedPoint=false;
		var len=dataSource.length;
		for (var i=0;i < len;i++){
			var vo=dataSource[i];
			if(vo.countLimitType!=0){
				vo.boughtCount=this.getAlreadyBuy(vo.cfgItem.id);
				this.buyCountDic.set(vo.cfgItem.id,vo.boughtCount < vo.maxCount);
				if(vo.money==0){
					if(vo.boughtCount<vo.maxCount){
						showRedPoint=true;
					}
				}
			}
		}
		if(pageType==3001){
			if(showRedPoint){
				Mgr.red.showRedPoint("shangcheng_sc_limit_daily","default","shangcheng_sc_limit_daily");
			}
			else{
				Mgr.red.hideRedPoint("shangcheng_sc_limit_daily","default","shangcheng_sc_limit_daily");
			}
		}
	}

	/**检查商品是否达到显示资格*/
	__proto.checkIsShow=function(vo){
		var roleVo=NetMgr.ins().roleVO;
		var sex=roleVo.sex;
		var cfgItem=vo.cfgItem;
		if(cfgItem.sex!=2&&cfgItem.sex !=sex){
			return false;
		}
		if(vo.djCfgItem && vo.djCfgItem.cfgItem){
			var djcfg=vo.djCfgItem.cfgItem;
			if(djcfg.job !="0" && djcfg.job !=NetMgr.ins().roleVO.job){
				return false;
			}
		}
		if(vo.roleLevel > roleVo.level){
			return false;
		}
		if(vo.guildLevel > Mgr.guild.guildLevel){
			return false;
		}
		if(vo.zsLevel){
			var needZsLv=vo.zsLevel.split(";");
			var myZsLv=roleVo.zhuanshengLevel;
			if(myZsLv< parseInt(needZsLv[0])|| myZsLv>parseInt(needZsLv[1])){
				return false;
			}
		}
		return true;
	}

	__proto.getDaiBiID=function(moneyType){
		return this.moneyTypeDaiBi[moneyType];
	}

	__proto.onUpdateVertureItem=function(dummyItemInfo){
		var roleVo=NetMgr.ins().roleVO;
		this.bangong=dummyItemInfo.bangGong;
		var moneyList=dummyItemInfo.moneyList;
		var len=moneyList.length;
		for (var i=0;i < len;i++){
			var itemMsg=moneyList[i];
			this.updateMoneyByteDummyId(itemMsg.itemId,itemMsg.count);
		}
		Mgr.moneyMgr.isInit=false;
		EventCenter.instance.event("DUMMY_ITEM_INFO_UDDATE");
	}

	__proto.onUpCopyGuaJiRewardItem=function(copyguajiInfo){
		if(copyguajiInfo.moneyItemId){
			if(copyguajiInfo.moneyItemId=="dj1341"){
				Mgr.prompt.expPrompt(copyguajiInfo.guaJiVal,copyguajiInfo.activeVal,1);
			}
			else if(copyguajiInfo.moneyItemId=="dj1004"){
				Mgr.prompt.expPrompt(copyguajiInfo.guaJiVal,copyguajiInfo.activeVal);
			}
		}
	}

	__proto.updateMoneyByteDummyId=function(itemId,money){
		switch(itemId){
			case "dj1007":{
					Mgr.moneyMgr.updateMoney(5 ,money);
					break ;
				}
			case "dj1348":{
					Mgr.moneyMgr.updateMoney(9 ,money);
					break ;
				}
			case "dj1920":
				Mgr.moneyMgr.updateMoney(6 ,money);
				break ;
			case "dj1921":
				Mgr.moneyMgr.updateMoney(7 ,money);
				break ;
			case "dj1922":
				Mgr.moneyMgr.updateMoney(8 ,money);
				break ;
			case "dj1923":
				Mgr.moneyMgr.updateMoney(13 ,money);
				break ;
			case "dj1341":
				Mgr.moneyMgr.updateMoney(14 ,money);
				break ;
			case "dj1926":
				Mgr.moneyMgr.updateMoney(15 ,money);
				break ;
			case "dj1927":
				Mgr.moneyMgr.updateMoney(16 ,money);
				break ;
			case "dj1008":
				Mgr.moneyMgr.updateMoney(19 ,money);
				break ;
			case "dj1006":
				Mgr.moneyMgr.updateMoney(20 ,money);
				break ;
			default :{
					break ;
				}
			}
	}

	__proto.onMallBuy=function(buyFromMall){
		if(buyFromMall.errCode==1){
			this.goodBuyCount[buyFromMall.chushouId]=buyFromMall.buyedCount;
			EventCenter.instance.event("MALL_BUY_SUCCESS",buyFromMall);
			Mgr.prompt.optionPrompt("购买成功");
			UIMgrR.closeIView(com.xq.view.modules.store.IBuyGoodPanelView);
		}
		else{
			if(buyFromMall.errCode==1003)
				Mgr.prompt.optionPrompt(buyFromMall.errCode);
			else if(buyFromMall.errCode==1002)
			UIMgrR.openIView(com.xq.view.modules.vip.IYuanBaoBuZuView,2);
		}
	}

	/**
	*购买物品
	**/
	__proto.buy=function(storeItemVO,count){
		Mgr.storePro.sendBuy(storeItemVO ,count);
	}

	/**
	*检查每日可以领取(红点)
	**/
	__proto.checkDailyFree=function(){
		if(Mgr.guide.isOpen("shangcheng")){
			this.getItemListByType(3001);
		}
		else{
			EventCenter.instance.on("new_function_open",this,this.onStoreFuncOpen);
		}
	}

	__proto.onStoreFuncOpen=function(funcId){
		if(funcId=="shangcheng"){
			EventCenter.instance.off("new_function_open",this,this.onStoreFuncOpen);
			this.checkDailyFree();
		}
	}

	__proto.getAlreadyBuy=function(itemId){
		var count=parseInt(this.goodBuyCount[itemId]);
		if(count>=0){
			return count;
			}else{
			return 0;
		}
	}

	__proto.onGetRandom=function(arr,times,needPushTip){
		this.randomShopRefreshTimes=times;
		this.randomArr.length=0;
		this.randomItems.length=0;
		var pushItemVo;
		var len=arr.length;
		for (var i=0;i < len;i++){
			var msg=arr[i];
			var vo=StoreMgr.shopItemMsgToVo(msg);
			vo.isRandomShop=true;
			this.randomItems.push(vo);
			this.randomArr[vo.slot]=vo;
			if(needPushTip&& vo.boughtCount==0){
				if(pushItemVo==null){
					pushItemVo=vo;
				}
				else{
					if(pushItemVo.discount>vo.discount){
						pushItemVo=vo;
					}
					else{
						if(pushItemVo.discount==vo.discount){
							if(pushItemVo.money<vo.money){
								pushItemVo=vo;
							}
						}
					}
				}
			}
		}
		if(pushItemVo){
			if(Mgr.guide.isOpen("dhshangcheng")){
				var pushCopyItem=ObjectTools.copyObj(pushItemVo);
				pushCopyItem.djCfgItem.rareLv=pushItemVo.djCfgItem.rareLv;
				RandomShopRefreshTipUtil.show(pushCopyItem);
			}
		}
		EventCenter.instance.event("RANDOM_STORE");
	}

	__proto.buyRandom=function(slot){
		var vo=this.randomArr[slot];
		vo.buyed=true;
		vo.boughtCount=1;
		EventCenter.instance.event("RANDOM_STORE");
	}

	/**
	*获取到全局表神秘商店刷新价格
	*/
	__proto.getPrice=function(){
		var obj=this.quanjuCfg.getItemByField("type","85");
		var str=obj.value;
		var arr=str.split(";");
		if (arr[this.randomShopRefreshTimes]){
			return arr[this.randomShopRefreshTimes];
		}
		else{
			return "0";
		}
	}

	/**
	*获得全局表神秘商店的刷新剩余时间
	*/
	__proto.getRemainTime=function(){
		return this.nextRefreshTime-Mgr.curTime.serverTimer;
	}

	__proto.buyAllRandomGoods=function(){
		var arr=this.randomItems;
		if(arr){
			var canBuy=false;
			for (var i=0;i < arr.length;i++){
				var vo=arr[i];
				if(!vo.buyed){
					canBuy=true;
					break ;
				}
			}
			if(canBuy){
				Mgr.storePro.sBuyRandom(-1);
			}
			else{
				Mgr.prompt.optionPrompt("已经全部购买，请刷新后再来");
			}
		}
	}

	__proto.getLockValue=function(lockType){
		switch (lockType){
			case 1:
				return Mgr.fbgkMgr.maxId;
				break ;
			case 2:
				return Mgr.copy.tiaozhanId;
				break ;
			}
		return 0;
	}

	/**
	*根据类型获取商品详情
	*/
	__proto.getPageStore=function(pageId,sellId){
		var arr=this.getItemListByType(pageId);
		var len=arr.length;
		for (var i=0;i < len;i++){
			var vo=arr[i];
			if(vo.cfgItem.sellId==sellId){
				var butCt=this.getAlreadyBuy(vo.cfgItem.id);
				if(butCt >=vo.maxCount){
					return null;
				}
				else{
					return vo
				}
			}
		}
		return null;
	}

	__proto.onBtnBuy=function(ifEnough,storeItemVO,curBuyCount){
		(curBuyCount===void 0)&& (curBuyCount=1);
		if(ifEnough){
			if(storeItemVO.isRandomShop){
				Mgr.storePro.sBuyRandom(storeItemVO.slot);
			}
			else if(storeItemVO.isTaiYuRandomShop){
				Mgr.storePro.sendBuyTaiyu(storeItemVO.slot);
			}
			else if(storeItemVO.isVipShop){
				Mgr.vip.sendBuyVipShop(storeItemVO.slot,curBuyCount);
			}
			else{
				Mgr.store.buy(storeItemVO,curBuyCount);
			}
		}
		else{
			var name=Mgr.moneyMgr.getMoneyName(storeItemVO.moneyType);
			Mgr.prompt.optionPrompt(name+"不足");
		}
	}

	__proto.updateNextRefeshTime=function(nextRefeshTime){
		this.nextRefreshTime=nextRefeshTime;
	}

	/**根据商城页签类型获取对应展示道具ele数组*/
	__proto.getShowArr=function(pageType){
		var showItems=[];
		var arr=this._model.getStoreElesByType(pageType);
		var len=arr.length;
		var ele;
		for(var i=0;i<len;i++){
			ele=arr[i];
			if(!this.checkShow(ele))continue ;
			showItems.push(ele);
		}
		return showItems;
	}

	/**检测道具是否展示*/
	__proto.checkShow=function(ele){
		if(!ele)return false;
		var cfg=ele.getCfgData();
		var roleVo=NetMgr.ins().roleVO;
		var sex=roleVo.sex;
		if(cfg.sex!=2&&cfg.sex !=sex){
			return false;
		}
		if(cfg.roleLevel > roleVo.level){
			return false;
		}
		if(cfg.guildLevel > Mgr.guild.guildLevel){
			return false;
		}
		if(cfg.zsLevel){
			var needZsLv=cfg.zsLevel.split(";");
			var myZsLv=roleVo.zhuanshengLevel;
			if(myZsLv< parseInt(needZsLv[0])|| myZsLv>parseInt(needZsLv[1])){
				return false;
			}
		}
		return true;
	}

	/**展示特效*/
	__proto.checkShowEff=function(ele){
		if(!ele)return false;
		var showId=Mgr.store.showEffTemplateId;
		if(!showId)return false;
		var cfg=ele.getCfgData();
		var sellId=cfg.sellId;
		var liHeCfg=Mgr.item.getLiheMsg(sellId);
		if(!liHeCfg&&sellId==showId)return true;
		if(liHeCfg&&(liHeCfg.things.lastIndexOf(showId)!=-1))return true;
		return false;
	}

	/**限购商城 是否显示推荐角标*/
	__proto.checkRecommend=function(ele){
		if(!ele)return false;
		var cfg=ele.getCfgData();
		var pageType=cfg.page;
		if(pageType!=3001)return false;
		var recommendArr=Mgr.hancock.needItemArr;
		if(!recommendArr||recommendArr.length==0)return false;
		var sellId=cfg.sellId;
		var len=recommendArr.length;
		var liHeCfg=Mgr.item.getLiheMsg(sellId);
		for(var i=0;i<len;i++){
			var recomId=recommendArr[i];
			if(cfg.sellId==recomId){
				return true;
			}
			else if(liHeCfg && liHeCfg.things.lastIndexOf(recomId)!=-1){
				return true;
			}
		}
		return false;
	}

	/**请求购买记录后刷新购买次数数据*/
	__proto.updateStoreInfo=function(msg){
		this._model.updateStoreInfo(msg);
		this.updateFreeRed();
		EventCenter.instance.event("UpdateStoreInfo");
	}

	/**商城购买后刷新*/
	__proto.updateAfterBuy=function(msg){
		if(msg.errCode==1){
			Mgr.prompt.optionPrompt("购买成功");
			UIMgrR.closeIView(com.xq.view.modules.store.IBuyGoodPanelView);
		}
		else if(msg.errCode==1003){
			Mgr.prompt.optionPrompt(msg.errCode);
		}
		else if(msg.errCode==1002){
			UIMgrR.openIView(com.xq.view.modules.vip.IYuanBaoBuZuView,2);
		}
	}

	/**同步vip商城数据*/
	__proto.updateVipStoreInfo=function(msg){
		this._model.updateVipStoreInfo(msg);
		EventCenter.instance.event("UpdateStoreInfo");
	}

	/**Vip商城购买后刷新数据*/
	__proto.updateVipBuy=function(msg){
		if(msg.errorCode!=1){
			Mgr.prompt.optionPrompt(CodeMgr.ins.getStringByCode(msg.errorCode));
			return;
		}
		this._model.updateVipBuy(msg);
		EventCenter.instance.event("updateStoreBuyInfo");
	}

	//==================红点=================
	__proto.registRed=function(){
		Mgr.red.regist("shangcheng_main" ,"shangcheng",true,"StoreFreeExhchange");
		Mgr.red.regist("shangcheng" ,"StoreView",false,"StoreFreeExhchange");
		Mgr.red.regist("StoreView" ,"shangcheng_sc_limit",false,"StoreFreeExhchange");
		Mgr.red.regist("shangcheng_sc_limit" ,"shangcheng_sc_limit_daily",false,"StoreFreeExhchange");
		Mgr.red.regist("shangcheng","vipStore",false,"StoreFreeExhchange");
		EventCenter.instance.on("VIPLEVEL_CHANGE",this,this.onVIPSVIPUp);
		EventCenter.instance.on("NORMAL_VIP_CHANGE",this,this.onVIPSVIPUp);
		Mgr.red.regist("shangcheng_main","dhshangcheng",false,"StoreFreeExhchange");
	}

	/**限购商城免费 红点*/
	__proto.updateFreeRed=function(){
		var arr=this.getShowArr(3001);
		var len=arr.length;
		var ele;
		var cfg;
		var info;
		for (var i=0;i < len;i++){
			ele=arr[i];
			if(!ele)continue ;
			cfg=ele.getCfgData();
			var limitType=cfg.countLimitType?parseInt(cfg.countLimitType):0;
			var max=cfg.maxCount?parseInt(cfg.maxCount):0;
			if(limitType!=0&&parseInt(cfg.money)==0){
				info=ele.getValue("s_data");
				var buyCount=info?info.count:0;
				if(buyCount<max){
					Mgr.red.showRedPoint("shangcheng_sc_limit_daily","default","shangcheng_sc_limit_daily");
					return;
				}
			}
		}
		Mgr.red.hideRedPoint("shangcheng_sc_limit_daily","default","shangcheng_sc_limit_daily");
	}

	StoreMgr.shopItemMsgToVo=function(msg){
		var index=msg.slot;
		var buyed=msg.buyed;
		var itemInfoArr=msg.itemInfo.split(":");
		var templateId=itemInfoArr[0];
		var count=parseInt(itemInfoArr[1]);
		var bind=parseInt(itemInfoArr[2]);
		var moneyType=parseInt(itemInfoArr[3]);
		var prePrice=parseInt(itemInfoArr[4]);
		var disCount=parseInt(itemInfoArr[5]);
		var price=parseInt(itemInfoArr[6]);
		var vo=new StoreItemVo;
		vo.djCfgItem=Mgr.item.getItemVO(templateId,bind,count);
		if (!vo.djCfgItem){
			return null;
		}
		vo.cfgItem=vo.djCfgItem.cfgItem;
		vo.buyed=msg.buyed;
		if(msg.buyed){
			vo.boughtCount=1;
		}
		else{
			vo.boughtCount=0;
		}
		vo.maxCount=1;
		vo.countLimitType=1;
		vo.money=price;
		vo.preMoney=prePrice;
		vo.discount=disCount;
		vo.moneyType=moneyType;
		vo.slot=index;
		return vo;
	}

	return StoreMgr;
})()


/**
*玉币商店（玉阁）
**/
//class com.xq.modules.store.taiyu.TaiyuStoreMgr
var TaiyuStoreMgr=(function(){
	function TaiyuStoreMgr(){
		/**显示列表数据*/
		this.taiyuStoreArr=[];
		this.nextTaiyuRefreshTime=0;
		this.refreshCostMoneyType=2;
		this.refreshCostMoneyArr=null;
		/**是否弹出气泡刷新提示*/
		this.isQIiPao=false;
		this.configTab=null;
		this.refreshedCount=0;
		this.YuGeQiPao=null;
		this.configTab=CfgManager.getTableCfg("TaiYuStoreConfig");
		var cfgItem=this.configTab.objectDataArray[0];
		var str=cfgItem.tyRefreshMoney;
		this.refreshCostMoneyArr=str.split(";");
		this.refreshCostMoneyType=cfgItem.tyRefreshMoneyType;
	}

	__class(TaiyuStoreMgr,'com.xq.modules.store.taiyu.TaiyuStoreMgr');
	var __proto=TaiyuStoreMgr.prototype;
	__proto.getCostMoney=function(){
		var refreshCount=this.refreshedCount;
		var len=this.refreshCostMoneyArr.length;
		if(len>0){
			if(refreshCount<len){
				return this.refreshCostMoneyArr[refreshCount];
			}
			else if(refreshCount>=len){
				return this.refreshCostMoneyArr[len-1];
			}
		}
		return 200;
	}

	__proto.onUpdateRandomTaiList=function(arr,needPushTip,refreshCount){
		this.refreshedCount=refreshCount;
		this.taiyuStoreArr.length=0;
		var pushItemVo;
		var size=arr.length;
		for (var i=0;i <size;i++){
			var msg=arr[i];
			var vo=StoreMgr.shopItemMsgToVo(msg);
			this.taiyuStoreArr.push(vo);
			vo.isTaiYuRandomShop=true;
			if(needPushTip&& vo.boughtCount==0){
				if(pushItemVo==null){
					pushItemVo=vo;
				}
				else{
					if(pushItemVo.discount>vo.discount){
						pushItemVo=vo;
					}
					else{
						if(pushItemVo.discount==vo.discount){
							if(pushItemVo.money<vo.money){
								pushItemVo=vo;
							}
						}
					}
				}
			}
		}
		if(pushItemVo){}
			EventCenter.instance.event("RANDOM_STORE_TAI_YU");
	}

	__proto.onGetRandomTaiyu=function(r){
		this.nextTaiyuRefreshTime=r.nextRefeshTime;
		var arr=r.items;
		this.onUpdateRandomTaiList(arr,r.isOnTime,r.refreshedTimes);
		Laya.timer.loop(1000,this,this.coutDown);
	}

	__proto.onBuyRandomTaiyu=function(slot){
		var vo=this.taiyuStoreArr[slot];
		vo.buyed=true;
		vo.boughtCount=1;
		EventCenter.instance.event("RANDOM_STORE_TAI_YU");
	}

	__proto.coutDown=function(){
		var leftTime=this.nextTaiyuRefreshTime-Mgr.curTime.serverTimer;
		if(leftTime <=0){
			var len=this.taiyuStoreArr.length;
			for (var i=0;i < len;i++){
				var msg=this.taiyuStoreArr[i];
				if(msg.discount==1 || msg.discount==2 ||msg.discount==3){
					this.delayOpenQiPao();
					break ;
				}
			}
		}
	}

	__proto.delayOpenQiPao=function(){
		if(Configs.isForbitIOSPay||Configs.isForbitAndroidPay){
			return;
		};
		var taiyuView=ActiveMgr.ins.getActivityRender("taiYuMain");
		var tarPos=new Point(taiyuView.x,taiyuView.y);
		if(taiyuView.parent){
			tarPos=(taiyuView.parent).localToGlobal(tarPos);
			}else{
			return;
		}
		if(!this.YuGeQiPao){
			this.YuGeQiPao=UIMgrR.newInstanceByIClass(com.xq.view.mainUI.subPanel.IQiPaoTip);
		};
		var obj={};
		obj["viewId"]=70263;
		obj["code"]=260832;
		this.YuGeQiPao.dataSource=obj;
		this.YuGeQiPao.open();
		Game.getInstance().getNewMainView().addViewToHide(this.YuGeQiPao,1);
		Game.getInstance().mainQiPaoView.addChild(this.YuGeQiPao);
		this.YuGeQiPao.x=tarPos.x;
		this.YuGeQiPao.y=tarPos.y+taiyuView.height;
		this.isQIiPao=true;
	}

	return TaiyuStoreMgr;
})()


