//class com.xq.modules.syn.InOutMapMgr
var InOutMapMgr=(function(){
	function InOutMapMgr(){
		this.viewDic={};
		this.cfg=null;
		// private var level:int;
		this.viewObj=null;
		this._lastFunID=null;
		this.husongTishi=true;
		this.checkCd=0;
		/**退出一关卡本，需要等待换场景后在调用进入请求*/
		this.waitEnterSceneHandler=null;
		this._isCanEnterCopy=true;
		/**逻辑函数*/
		this.logicHandler=null;
		this.initData();
	}

	__class(InOutMapMgr,'com.xq.modules.syn.InOutMapMgr');
	var __proto=InOutMapMgr.prototype;
	__proto.initData=function(){
		this.viewObj={};
		var cfg=CfgManager.getTableCfg("LastPanelControl");
		var arr=cfg?cfg.objectDataArray:[];
		var len=arr.length;
		var data;
		for(var i=0;i<len;i++){
			data=arr[i];
			data&&this.registLastView(data.func);
		}
	}

	/**
	*注册面板
	*@param funID 功能ID对应uiCoder表的
	**/
	__proto.registLastView=function(funID){
		if(!this.viewObj[funID]){
			var obj=UIMgrR.getUiCfgByFunId(funID);
			if(obj){
				this.viewObj[funID]=obj.ID;
			}
		}
	}

	/**打开记忆面板*/
	__proto.openReMory=function(){
		if(Mgr.task.curTask && Mgr.task.curTask.stayMain==1){
			this.lastFunID=null;
			return
		}
		if(this.lastFunID){
			var tempID=this.viewObj[this.lastFunID];
			if(tempID){
				UIMgrR.navigateToViewByID(tempID);
				this.lastFunID=null;
			}
		}
	}

	__proto.check=function(c,isBarrier,mapType,teamType){
		(isBarrier===void 0)&& (isBarrier=false);
		(mapType===void 0)&& (mapType=0);
		if(ZhuChengMgr.ins.isZhuCheng){
			Mgr.prompt.optionPrompt(CodeMgr.ins.getStringByCode(260878));
			return;
		}
		if(!this.isCanEnterCopy){
			this.waitEnterSceneHandler=c;
			return;
		}
		if(!teamType){
		};
		var anotherTeamType;
		if(NetMgr.ins().roleVO.mapType==52){
			Mgr.gqProMgr.reqLeavelChallenge(false);
			if(c.caller==Mgr.gqMgr){
				debugger;
			}
			this.waitEnterSceneHandler=c;
			return;
		}
		this.logicHandler=c;
		if(mapType !=16 && Mgr.fengshenlu.teamArr && Mgr.fengshenlu.teamArr.length > 0){
			AlertUtil.ShowAlert("当前正在组队中，要进入当前场景需退出队伍，是否退出队伍？",Handler.create(this,this.skipTeam),Handler.create(this,this.exitTeam,[c]),null,"留在队伍","退出前往");
			return;
		}
		else if((anotherTeamType=Mgr.teamMgr.checkHasAnotherTeam(teamType))!=null){
			AlertUtil.ShowAlert("当前正在组队中，要进入当前场景需退出队伍，是否退出队伍？",Handler.create(this,this.skipTeam),Handler.create(this,this.exitTeam,[c]),null,"留在队伍","退出前往");
			return;
		}
		else if(Mgr.bag.bagIsFull){
			if(Mgr.gqMgr.openAutoCha && isBarrier){
				Mgr.bag.autoSmeltEquip();
				this.runLogic();
				}else{
				AlertUtil.ShowAlert("当前背包空间不足，是否一键熔炼",Handler.create(this,this.smeltOk),null);
			}
		}
		else{
			if(this.checkCd <=Browser.now()){
				this.runLogic();
				this.checkCd=Browser.now()+800;
				console.log("发送了进入副本协议-----------checkCd",this.checkCd);
			}
			else{
				console.log("进入副本请求公共CD中"+this.checkCd);
			}
		}
	}

	__proto.runLogic=function(){
		if(this.logicHandler){
			this.logicHandler.run();
			this.logicHandler=null;
		}
	}

	__proto.ok=function(c){
		this.runLogic()
	}

	__proto.ck=function(flag){
		this.husongTishi=!flag;
	}

	__proto.smeltOk=function(){
		Mgr.bag.autoSmeltEquip();
		this.runLogic();
	}

	/**是否有切换场景后的函数要执行*/
	__proto.checkEnteredReq=function(){
		if(this.waitEnterSceneHandler){
			var curType=NetMgr.ins().roleVO.mapType
			if(curType==52){
				Mgr.gqProMgr.reqLeavelChallenge(false);
				return;
			}
			if(!MapType.isCopy(curType)){
				this.waitEnterSceneHandler.run();
				this.waitEnterSceneHandler=null;
			}
		}
	}

	__proto.exitTeam=function(c){
		Mgr.teamAct.reqExitTeam(Mgr.teamMgr.teamType);
		this.runLogic();
	}

	__proto.skipTeam=function(){
		Mgr.teamMgr.openCurTeam();
	}

	/**
	*@private
	*/
	/**是否可以进入副本*/
	__getset(0,__proto,'isCanEnterCopy',function(){
		return this._isCanEnterCopy;
		},function(value){
		this._isCanEnterCopy=value;
		if(value){
			this.checkEnteredReq();
		}
		if(value){
			console.log("进入地图场景结束==============");
		}
		else{
			console.log("进入地图场景开始============")
		}
	});

	__getset(0,__proto,'lastFunID',function(){
		return this._lastFunID;
		},function(value){
		this._lastFunID=value;
	});

	return InOutMapMgr;
})()


