/**
*玩家战斗力、自角色战斗力管理
*@author xiangjia
*@date 2019-7-17
*/
//class com.xq.modules.syn.PowerMgr
var PowerMgr=(function(){
	function PowerMgr(){
		this.powerDic=null;
		this.totalPower=NaN;
		this.mergePowerList=null;
		this.fightCatalogue=null;
		/**记录改变前的战斗力*/
		this.lastTotalPower=0;
		/**已powerType为key储存模块名*/
		this.powerNameDic=null;
		this.powerDic={};
		this.fightCatalogue={};
		this.powerNameDic={};
		this.setPowerName();
	}

	__class(PowerMgr,'com.xq.modules.syn.PowerMgr');
	var __proto=PowerMgr.prototype;
	/**
	*根据战力类型获取对应模块（多角色合并后的）的战斗力
	**/
	__proto.getPowerByType=function(type){
		if(this.fightCatalogue.hasOwnProperty(type)){
			return this.fightCatalogue[type];
		}
		return 0;
	}

	/**
	*获取单角色，单项战斗力
	**/
	__proto.getRolePower=function(roleId,type){
		if(this.powerDic.hasOwnProperty(roleId)){
			var msg=this.powerDic[roleId];
			if(msg.hasOwnProperty(type)){
				return msg[type];
			}
		}
		return 0;
	}

	/**
	*获取单角色总战斗
	**/
	__proto.getPowerByRoleId=function(roleId){
		return this.getRolePower(roleId ,PowerType.TOTAL_POWER);
	}

	/**
	*获取单角色技能战斗力
	**/
	__proto.getPowerJiNemg=function(roleId){
		return this.getRolePower(roleId ,10);
	}

	__proto.onPowerUpdate=function(roleId,powerMsg){
		var powerObj=this.powerDic[roleId];
		if(powerObj==null){
			powerObj=new Object();
			this.powerDic[roleId]=powerObj;
		};
		var arr=powerMsg.fightValues;
		var isShowUp=true;
		var len=arr.length;
		var fightMsg=arr[0];
		if(fightMsg.type==0 && fightMsg.fightValue > powerObj[0] && powerObj[0] !=0){
			isShowUp=false;
		}
		for (var i=0;i < len;i++){
			fightMsg=arr[i];
			powerObj[fightMsg.type]=fightMsg.fightValue;
		}
		this.calcPower(isShowUp);
		EventCenter.instance.event("module_change_fight");
	}

	//Laya.timer.once(50,this,calcPower);
	__proto.calcPower=function(isShowUpFight){
		this.totalPower=0;
		this.fightCatalogue={};
		for(var roleId in this.powerDic){
			var powerObj=this.powerDic[roleId];
			for(var powerType in powerObj){
				if(!this.fightCatalogue.hasOwnProperty(powerType)){
					this.fightCatalogue[powerType]=powerObj[powerType];
				}
				else{
					this.fightCatalogue[powerType]+=powerObj[powerType];
				}
			}
		}
		this.totalPower=this.fightCatalogue[PowerType.TOTAL_POWER];
		var rvo=NetMgr.ins().roleVO;
		var add=this.totalPower-rvo.fightValue;
		if(rvo.fightValue !=0 && add>0){
			Laya.timer.once(500,this,this.delayPlayZdl,[isShowUpFight]);
			if(WXSDK.isInWX)
				WXSDK.setWXRank();
		}
		else{
			rvo.fightValue=this.totalPower;
			EventCenter.instance.event("FIGHT_CHANGE",[this.totalPower]);
		}
	}

	__proto.delayPlayZdl=function(isShowFight){
		var rvo=NetMgr.ins().roleVO;
		if(isShowFight){
			Mgr.prompt.zdlPrompt(rvo.fightValue,this.totalPower);
		}
		rvo.fightValue=this.totalPower;
		EventCenter.instance.event("FIGHT_CHANGE",[this.totalPower]);
	}

	__proto.setPowerName=function(){
		this.powerNameDic[116]="宠物";
		this.powerNameDic[115]="宠物";
		this.powerNameDic[109]="侠客";
		this.powerNameDic[112]="侠客";
		this.powerNameDic[111]="护法";
		this.powerNameDic[114]="护法";
		this.powerNameDic[110]="红颜";
		this.powerNameDic[113]="红颜";
		this.powerNameDic[16]="坐骑";
		this.powerNameDic[17]="翅膀";
		this.powerNameDic[27]="神武";
		this.powerNameDic[89]="易容";
		this.powerNameDic[128]="姻缘";
	}

	__proto.getPowerNameByType=function(powerType){
		return this.powerNameDic[powerType];
	}

	__proto.getPowerObj=function(roleId){
		return this.powerDic[roleId];
	}

	return PowerMgr;
})()


