//class com.xq.modules.taiYu.TaiYuMgr
var TaiYuMgr=(function(){
	function TaiYuMgr(){
		this.taiYuCfg=null;
		this.yuShuCfg=null;
		this.yuShuKu=null;
		this.perCfg=null;
		/**玉币充值*/
		this.tYval=0;
		this.tYendTime=NaN;
		this.tYflag=0;
		/**是否是永久活动，是则不需要显示活动倒计时*/
		this.isActivity=false;
		/**消耗货币id*/
		this.huobiType=null;
		/**玉树活动版本号*/
		this.flag=0;
		/**玉树珍惜奖励*/
		this.yuShuDaJiang=null;
		/**玉树普通奖励*/
		this.yuShuPuTong=null;
		/**福气值大奖*/
		this.extrareward=null;
		/**福气值*/
		this.fuqizhi=null;
		this.yuShuCfgVo=null;
		/**界面奖励展示数据*/
		this.rewardData=null;
		/**第几轮奖励*/
		this.version=0;
		/**后端给的 玉树寻宝类型*/
		this.xunbaoType=0;
		/**抽奖奖励*/
		this.rollRewards=null;
		/**个人 全服 抽奖记录*/
		this.chouJiangJiLu=null;
		/**个人 全服 抽奖记录类型*/
		this.chouJiangJiLuType=0;
		this.rewardHistory=null;
		this.fuqizhiSc=0;
		this.red=null;
		this.fqz=0;
		this.yuShuDaJiang=[];
		this.yuShuPuTong=[];
		this.rewardData=[];
		this.fuqizhi=[];
		this.extrareward=[];
		this.taiYuCfg=CfgManager.getTableCfg("svipshangxian");
		this.yuShuCfg=CfgManager.getTableCfg("yushuconfig");
		this.yuShuKu=CfgManager.getTableCfg("yushuku");
		this.perCfg=CfgManager.getTableCfg("taiyuchongzhiper");
		this.red=Mgr.red;
		this.red.regist("taiYuMain","yushu",true,"taiYuMain");
	}

	__class(TaiYuMgr,'com.xq.modules.taiYu.TaiYuMgr');
	var __proto=TaiYuMgr.prototype;
	__proto.regActive=function(){
		ActManager.ins.regist("taiYuMain","taiyu",40,"TaiYuHallEvent");
		ActManager.ins.regist("taiYuMain","yushu",36,"TaiYuHallEvent");
		var tyAction=Mgr.taiYuAction;
		var hand=Handler.create(tyAction,tyAction.sendTaiYuInfo,null,false)
		var yushuAction=Mgr.mgxbProMgr;
		var yushu=Handler.create(yushuAction,yushuAction.sendBackCs,[103],false)
		NewActiveManager.ins.regActOpenHandler(40,hand);
		NewActiveManager.ins.regActOpenHandler(36,yushu);
		NewActiveManager.ins.regActEndHandler(40,Handler.create(this,this.closeAct,[40],false));
		NewActiveManager.ins.regActEndHandler(36,Handler.create(this,this.closeAct,[36],false));
	}

	__proto.closeAct=function(actId){
		if(actId==40){
			this.red.hideAll("taiyu");
		}
		else if(actId==36){
			this.red.hideAll("yushu");
		}
	}

	// red.hideRedPoint(FunctionDefine.YUSHU,FunctionDefine.TAIYUMAIN,FunctionDefine.KAIFUHUODONG);
	__proto.getTaiYuCfgData=function(svip,flag){
		var obj=this.taiYuCfg.getCfgMsgByTwoKey("svip",svip,"flag",flag);
		if(obj){
			return obj;
		}
		return-1;
	}

	__proto.taiYuInfo=function(obj){
		this.tYval=obj.val;
		this.activitTime();
		EventCenter.instance.event("taiyu_info");
	}

	__proto.activitTime=function(){
		var opAct=NewActiveManager.ins.getActiveVerDic(40);
		if(opAct){
			this.tYflag=opAct.flag;
			this.tYendTime=opAct.endTime;
			this.isActivity=opAct.isForeverActivity;
		}
	}

	__proto.getExtrareward=function(id){
		var arr=this.yuShuCfg.getItemsByField("id",id);
		this.yuShuCfgVo=arr[0];
		if(this.yuShuCfgVo){
			this.huobiType=this.yuShuCfgVo.costitem.split(":")[0];
			var djItemArr=this.yuShuCfgVo.extrareward.split("@");
			if(djItemArr[this.version-1]){
				this.fuqizhi.length=0;
				this.extrareward.length=0;
				var reward=djItemArr[this.version-1].split("|");
				var len=reward.length;
				for (var i=0;i < len;i++){
					var a=reward[i].split("_");
					this.fuqizhi.push(parseInt(a[0]));
					this.extrareward.push(a[1]);
				}
			}
		}
	}

	__proto.getYsShuKuData=function(configid){
		var arr=this.yuShuKu.getItemsByField("configid",configid);
		if(arr){
			var len=arr.length;
			this.yuShuDaJiang.length=0;
			this.yuShuPuTong.length=0;
			this.rewardData.length=0;
			for (var i=0;i < len;i++){
				if(arr[i].maxgod==1){
					this.yuShuDaJiang.push(arr[i].depot);
					}else{
					this.yuShuPuTong.push(arr[i].depot);
				}
				if(arr[i].location){
					this.rewardData.push(arr[i].depot);
				}
			}
		}
	}

	/**玉树获得初始数据*/
	__proto.setInfo=function(obj){
		this.version=obj.version;
		this.getYsShuKuData(obj.configId);
		this.getExtrareward(obj.configId);
		this.rewardHistory=[];
		if(obj.rewardHistory){
			var a=obj.rewardHistory.split(";");
			for (var i=0;i < a.length;i++){
				this.rewardHistory.push(parseInt(a[i]));
			}
		}
		this.xunbaoType=obj.type;
		this.fuqizhiSc=obj.yiChouCiShu;
		this.yushuRed();
		EventCenter.instance.event("yushu_update_info");
	}

	/**玉树抽奖获得数据*/
	__proto.setJiangLi=function(obj){
		this.rollRewards=obj.RollRewards;
		this.fuqizhiSc=obj.yiChouCiShu;
		this.red.showRedPoint("yushucahngku","ysxb","taiYuMain");
		if(this.rollRewards.length > 1){
			var ysrv=UIMgrR.openIView(com.xq.view.modules.taiYu.IYuShuRewardView,2);
			var object={};
			object["rollRewards"]=this.rollRewards;
			object["type"]=this.xunbaoType;
			object["cfgVo"]=this.yuShuCfgVo;
			ysrv.dataSource=object;
			}else{
			EventCenter.instance.event("yushu_one_reward");
		};
		var arr=Mgr.mgxbMgr.zhuFuZhiList;
		if(arr && arr.length >=1){
			var xbdj=UIMgrR.openIView(com.xq.view.modules.xunbao.IXunbaoDaJiagnView,2);
			xbdj.dataSource={"rewardArr":[Mgr.mgxbMgr.zhuFuZhiList[0]]};
		}
		this.yushuRed();
		EventCenter.instance.event("yushu_update_info");
	}

	/**玉树抽奖记录*/
	__proto.setJiLu=function(obj){
		this.chouJiangJiLu=obj.records;
		this.chouJiangJiLuType=obj.type;
		EventCenter.instance.event("yushu_choujiangjiu");
	}

	/**元宝是否足够 cost1消耗 货币数量货币类型*/
	__proto.isEnough=function(cost1,type){
		var arrCost=cost1.split(":");
		var need=0;
		if(arrCost.length>1){
			need=parseInt(arrCost[1]);
			}else{
			need=parseInt(arrCost[0]);
		};
		var roleVO=NetMgr.ins().roleVO;
		var huobi=0;
		if(type==1){
			huobi=roleVO.coin;
			}else if(type==2){
			huobi=roleVO.yuanbao;
			}else if(type==4){
			huobi=Mgr.bag.getBagMatCount(arrCost[0]);
			}else{
			huobi=roleVO.taiYu;
		}
		if(need > huobi){
			if(type==2){
				var ybbz=UIMgrR.openIView(com.xq.view.modules.vip.IYuanBaoBuZuView,2);
				}else if(type==4){
				var tip1=UIMgrR.openIView(com.xq.view.modules.common.IDaoJuPath,2);
				tip1.setData(arrCost[0]);
				}else{
				var tip=UIMgrR.openIView(com.xq.view.modules.common.IDaoJuPath,2);
				tip.setData(this.huobiType);
			}
			}else{
			return true;
		}
		return false;
	}

	__proto.yushuRed=function(){
		var len=this.fuqizhi.length;
		for (var i=0;i < len;i++){
			if(this.rewardHistory.indexOf(this.fuqizhi[i])==-1 && this.fuqizhiSc >=this.getZhuFuZhiRed(i)){
				this.red.showRedPoint("yushu","ysxb","taiYuMain");
				return;
				}else{
				this.red.hideRedPoint("yushu","ysxb","taiYuMain");
			}
		}
	}

	__proto.getZhuFuZhiRed=function(index){
		var len=this.fuqizhi.length;
		var zhuFuZhi=0;
		for (var i=0;i <=index;i++){
			if(this.rewardHistory.indexOf(this.fuqizhi[i])==-1){
				zhuFuZhi+=this.fuqizhi[i];
			}
		}
		return zhuFuZhi;
	}

	/**获取一次增加的福气值*/
	__proto.getOneFuQiValue=function(){
		if(!this.fqz){
			var arr=this.yuShuCfg.objectDataArray;
			var cof=arr[0];
			this.fqz=cof.num;
		}
		return this.fqz;
	}

	/**根据活动版本获取倍数*/
	__proto.getPerByFlag=function(flag){
		var cfg=this.perCfg.getItemByField("flag",flag);
		if(!cfg)return "1";
		return cfg.per;
	}

	return TaiYuMgr;
})()


