//class com.xq.modules.task.TaofaMgr
var TaofaMgr=(function(){
	function TaofaMgr(){
		/**最大可接讨伐任务次数*/
		this.maxTimes=0;
		/**剩余接任务次数*/
		this.leftTimes=0;
		/**任务进度*/
		this.progress=0;
		/**当前使用的道具id*/
		this.itemId=null;
		/**当前奖励表id*/
		this.rewardId=0;
		/**当前任务id*/
		this.taskId=0;
		/**当前讨伐任务*/
		this.curTask=null;
		/**讨伐奖励字典*/
		this.tfRewardDic=null;
		/**讨伐任务字典*/
		this.tfTaskDic=null;
		/**任务卷轴对象数组*/
		this.jzArr=null;
		/**秒杀所用元宝*/
		this.msYb=0;
		var tab=CfgManager.getTableCfg("Config");
		var obj=tab.getItemByField("type",101);
		this.maxTimes=parseInt(obj.value);
		obj=tab.getItemByField("type",102);
		this.msYb=parseInt(obj.value);
		tab=CfgManager.getTableCfg("taofajiangli");
		var arr=tab.objectDataArray;
		var len=arr.length;
		this.tfRewardDic={};
		for(var i=0;i < len;i++){
			obj=arr[i];
			var o1={};
			o1[obj.needitem1]=obj.award1;
			o1[obj.needitem2]=obj.award2;
			o1[obj.needitem3]=obj.award3;
			this.tfRewardDic[obj.id]=o1;
			if(!this.jzArr){
				this.jzArr=[];
				this.jzArr.push(obj.needitem1);
				this.jzArr.push(obj.needitem2);
				this.jzArr.push(obj.needitem3);
			}
		}
		this.tfTaskDic={};
		tab=CfgManager.getTableCfg("taofaguaiwu");
		arr=tab.objectDataArray;
		len=arr.length;
		for(i=0;i< len;i++){
			obj=arr[i];
			this.tfTaskDic[obj.id]=obj;
		}
	}

	__class(TaofaMgr,'com.xq.modules.task.TaofaMgr');
	return TaofaMgr;
})()


