//class com.xq.modules.task.TaskMgr
var TaskMgr=(function(){
	function TaskMgr(){
		this.model=null;
		this.taskModule=null;
		this.curTask=null;
		this.lastTask=null;
		this.uiMgr=null;
		this.isOnece=false;
		this.isLimit=false;
		/**最后一个主线任务Num号*/
		this.maxCfgNum=0;
		this._isBranck=false;
		this.oldTask="";
		this.isFirst=true;
		/**检查是否卡级，是则进行相关处理*/
		this.limitLevel=0;
		this.isOnece=true;
		this.model=TaskModel.ins();
		this.uiMgr=Mgr.taskUI;
		EventCenter.instance.on("achieve_gain",this,this.onGainAchieve);
		EventCenter.instance.on(GameEvent.DO_TASK,this,this.doCurTask);
		var taskVO=this.model.tasks[this.model.tasks.length-3];
		if(taskVO){
			this.maxCfgNum=taskVO.num;
		}
	}

	__class(TaskMgr,'com.xq.modules.task.TaskMgr');
	var __proto=TaskMgr.prototype;
	/**更新转职任务*/
	__proto.updateZhuanZhiTask=function(taskId,state){
		var taskVO=this.model.taskobj[taskId];
		this.model.zhuanzhiTaskVo=taskVO;
		taskVO.state=state;
	}

	/**更新主线任务*/
	__proto.updateTask=function(taskId,state,progress){
		(progress===void 0)&& (progress=-1);
		var taskVO=this.model.taskobj[taskId];
		PreLoadManager.changeId(taskId);
		this.curTask=taskVO;
		taskVO.state=state;
		this.model.curTaskVO=taskVO;
		if(this.isOnece){
			Mgr.guide.checkMul(true);
		}
		if(!taskVO.autoTask){
			EventCenter.instance.event("MianTaskIsOverEvent");
		}
		else{
			EventCenter.instance.event("update_task_taskinfo_event",[taskVO]);
		}
		if(progress!=-1){
			EventCenter.instance.event("update_task_numinfo_event",[taskId,progress,false]);
		}
		Mgr.actionSkillM.updateTaskSkill();
		Mgr.guanZMgr.taskPopInstallShortcut();
		if(this.curTask.storyid && !this.curTask["storyShowed"]){
			this.curTask["storyShowed"]=true;
			Mgr.juqing.start(this.curTask.storyid);
			this.lastTask=null;
			return;
		}
		this.lastTask=this.curTask;
		if(this.oldTask=="")
			this.oldTask=taskId;
		if(state==2){
			EventCenter.instance.event("MAIN_TASK_COMPLETE",taskId);
			Mgr.guide.onTaskUp(this.oldTask);
		}
		if(this.oldTask !=taskId)
			this.oldTask=taskId
		FrameSmooth.add(Handler.create(this,this.doTask,[taskVO]));
		if(this.isOnece==true){
			this.isOnece=false;
			Mgr.guideActivity.checkLimit();
			if(Mgr.guide.isOpen("xianji")){
				EventCenter.instance.event("OPEN_SKILL",Mgr.hjModel.hejiJN);
			}
			EventCenter.instance.event("check_new_func");
		};
		var guidemode=NewGuideAction.Ins;
		if(!guidemode.guideIsOver && !NetMgr.ins().roleVO.isInCopy){
			if(state !=2 && taskVO.yindaoID > 0){
				var guideVo=guidemode.checkHasGuide(taskId,taskVO.yindaoID);
				if(!guidemode.isGuideing && guideVo){
					if(this.isFirst){
						if(state !=1)
							Laya.timer.once(1000,this,this.delayGuide,[guideVo,taskId]);
					}
					else
					guidemode.startGuide(guideVo,taskId);
				}
			}
		}
	}

	//Laya.timer.once(300,this,delayGuide,[guideVo]);
	__proto.delayGuide=function(vo,taskId){
		NewGuideAction.Ins.startGuide(vo,taskId);
	}

	/**继续任务*/
	__proto.doTask=function(taskVO,isClick){
		(isClick===void 0)&& (isClick=false);
		if(MapType.isCopy(NetMgr.ins().roleVO.mapType))
			return;
		var player=Game.getInstance().player;
		if(!player || player.isJuQing)
			return;
		if(taskVO.state==1){
			if(taskVO.completeNpc){
				Mgr.logicAction.doAction(FindNpcAction.getObject(taskVO.completeNpc));
			}
			else if(taskVO.cjType){
				if(isClick){
					Mgr.taskPro.sendPayMainTask(taskVO.id2);
				}
			}
			else{
				Mgr.taskPro.sendPayMainTask(taskVO.id2);
			}
		}
		else if(taskVO.state==3){
			Mgr.taskPro.sendAcceptMainTask(taskVO.id2);
		}
		else if(taskVO.state==2){
			Mgr.taskPro.sendGetTaskInfo(true);
		}
		else if(taskVO.state==0){
			this.excuteTask(taskVO,isClick);
		}
	}

	/**交任务*/
	__proto.payTask=function(){}
	/**接任务*/
	__proto.acceptTask=function(){}
	/**继续任务*/
	__proto.excuteTask=function(taskVO,isClick){
		(isClick===void 0)&& (isClick=false);
		if(taskVO.taskPanel){
			if(isClick){
				var obj=UIMgrR.uiControlTable.getItemByField("ID",taskVO.taskPanel);
				if(obj){
					if(taskVO.taskPanel){
						UIMgrR.navigateToViewByID(parseInt(taskVO.taskPanel));
						Game.getInstance().player.isTask=true;
						return;
					}
				}
			}
		}
		else {
			if(taskVO.completeMonster){
				var monster=taskVO.completeMonster;
				var ge=taskVO.completeMonster.indexOf(":");
				var monsterId=monster.substring(1,ge);
				Mgr.logicAction.doAction(FindMonsterAction.getObject(monsterId,taskVO.MonsterMapID));
			}
			else if(taskVO.completeResource){
				Mgr.logicAction.doAction(FindCollectAction.getObject(taskVO.completeResource.split(":")[0]));
			}
			else
			AIController.ins().startAutoCombat();
		}
	}

	__proto.doCurTask=function(isClick){
		(isClick===void 0)&& (isClick=false);
		var mt=NetMgr.ins().roleVO.mapType;
		if(Model.scene.isChangeScene || MapType.isCopy(mt))
			return;
		if(this.curTask){
			this.doTask(this.curTask,isClick);
		}
	}

	__proto.updateTaskNumber=function(data){
		var taskId=data.taskId;
		var monsterId=data.monsterId;
		var count=data.count;
	}

	/**==============================日常任务相关===================================*/
	__proto.checkNpcTask=function(npcId){
		if(this.curTask && this.curTask.id2){
			var taskVO=this.model.taskobj[this.curTask.id2];
			return (taskVO && taskVO.completeNpc==npcId && NetMgr.ins().roleVO.level >=taskVO.limit)
		}
		return false;
	}

	__proto.deleteNpcANi=function(taskVO){
		if(taskVO.completeNpc){
			var dic=UnitManager.ins.npcList;
			var npc=dic.get(taskVO.completeNpc);
			if(npc){
				npc.deleteTaskAni();
			}
		}
	}

	__proto.addNpcAni=function(){
		var taskVO=this.model.taskobj[this.curTask.id2];
		if(taskVO.completeNpc){
			var dic=UnitManager.ins.npcList;
			var npc=dic.get(taskVO.completeNpc);
		}
	}

	/**跨场景跳跃后的行为*/
	__proto.flyCompleteDoTask=function(taskType){
		var model=Mgr.task.model;
		var map=0;
		if(taskType==3){
		}
		else if(taskType==2){
		}
		else if(taskType==1){
			Mgr.task.doCurTask();
		}
		else if(taskType==5){
			if(Mgr.taofa.curTask)
				AIController.ins().startAutoCombat(Mgr.taofa.curTask.monsterId);
		}
		Mgr.transPro.taskType=0;
	}

	/**试炼副本*/
	__proto.checkDailyTaskRed=function(){
		var vo=Mgr.task.model.dailyTaskVO;
		if(!vo)
			return false;
		else{
			if(vo.loop_index>=vo.maxLoop && vo.killNum>=vo.max){
				return false;
			}
			return true;
		}
	}

	/**宗门副本*/
	__proto.checkGuildTaskRed=function(){
		var vo=Mgr.task.model.guildTaskVO;
		if(!vo)return false;
		if((vo.loop_index < vo.maxLoop)&& (vo.killNum < vo.max)&& (NetMgr.ins().roleVO.guildId>0)){
			return true;
		}
		return false;
	}

	__proto.onGainAchieve=function(id){
		Game.getInstance().player.isTask=false;
	}

	/**根据子任务获取TaskVo*/
	__proto.getTaskVoById=function(taskId){
		return this.model.taskobj[taskId];
	}

	__proto.getTaskId=function(num){
		return this.model.getTaskId(num);
	}

	__proto.getFinalTask=function(){
		var taskVO=this.model.tasks[this.model.tasks.length-3];
		if(taskVO){
			return taskVO.id2;
		}
		return null;
	}

	/**更新引导ID*/
	__proto.updateYinDaoID=function(old){
		if(old==28){
			Mgr.setting.isAutoUseNuqi=true;
			Mgr.setting.sendSetSettingParams();
			EventCenter.instance.event("ChangeAutoHeJiSkill",[true]);
		}
	}

	__proto.checkLimitTask=function(id){
		var roleVO=NetMgr.ins().roleVO;
		var curTask=this.curTask;
		var taskVO;
		if(curTask.state==3){
			if(curTask.limit>0 && roleVO.level < curTask.limit){
				taskVO=curTask;
			}
		}
		else if(curTask.state==2 && curTask.autoTask){
			var nextVO=this.model.taskobj[curTask.autoTask];
			if(nextVO && nextVO.limit>0 && roleVO.level<nextVO.limit){
				taskVO=nextVO;
			}
		}
		if(taskVO){
			this.limitLevel=taskVO.limit;
			EventCenter.instance.event("update_task_taskinfo_event",[taskVO]);
			EventCenter.instance.on("LEVEL_UP",this,this.onLevelChange);
			this.isLimit=true;
		}
		else{
			this.isLimit=false;
		}
		return taskVO;
	}

	__proto.onLevelChange=function(e){
		var level=NetMgr.ins().roleVO.level;
		if(this.limitLevel>0 && level>=this.limitLevel){
			Mgr.taskPro.sendGetTaskInfo(true);
			EventCenter.instance.off("LEVEL_UP",this,this.onLevelChange);
			this.limitLevel=0;
		}
	}

	/**获取分支任务*/
	__proto.getBranchTask=function(){
		var xsObj=Mgr.xsMgr.getCurTask();
		if(xsObj){
			return xsObj;
		}
		else{
			var dkObj=Mgr.mrdkMgr.getCurTask();
			if(dkObj){
				return dkObj;
			}
			else{
				var rcObj=Mgr.xianShi.getCurTask();
				if(rcObj){
					return rcObj;
				}
			}
		}
		return null;
	}

	/**
	*@private
	*/
	/**是否支线任务*/
	__getset(0,__proto,'isBranck',function(){
		return this._isBranck;
		},function(value){
		this._isBranck=value;
	});

	return TaskMgr;
})()


