//class com.xq.modules.task.TaskUtil
var TaskUtil=(function(){
	function TaskUtil(){}
	__class(TaskUtil,'com.xq.modules.task.TaskUtil');
	TaskUtil.getMonsterTaskTrack=function(taskVO,link){
		(link===void 0)&& (link=false);
		TaskUtil.isLink=link;
		var str=taskVO.tasktrack;
		var inx1=str.indexOf("{");
		var pre=str.substring(0,inx1);
		var s1=taskVO.completeMonster;
		var ge=s1.indexOf(":");
		var df=s1.substring(1,ge);
		var name=Model.monster.getMonsterNameById(df);
		var count=parseInt(s1.substring(ge+1,s1.length));
		if(taskVO.MonsterMapID || taskVO.taskPanel){
			var re=TaskUtil.addMonsterPosLink(taskVO);
			name=re=="" ? name:re;
		};
		var sstr=TaskUtil.addColor(name,"#c1342d")+TaskUtil.addColor("("+"@/"+String(count)+")","#24971e");
		sstr=TaskUtil.addColor(pre,"#495966")+sstr;
		return [sstr,name,count];
	}

	TaskUtil.getCollectTaskTrack=function(taskVO,link){
		(link===void 0)&& (link=false);
		TaskUtil.isLink=link;
		var table=CfgManager.getTableCfg("ZiYuanDian");
		var arr=taskVO.completeResource.split(":");
		var id=arr[0];
		var count=parseInt(arr[1]);
		var name=table.getItemByField("id",id).name;
		var sstr=TaskUtil.addColor(name,"#c1342d")+TaskUtil.addColor("("+"@/"+String(count)+")","#24971e");
		return [sstr,name,count];
	}

	TaskUtil.getPrizeStr=function(exp,money){
		var strs=[];
		var str="";
		if(exp>0){
			str="dj1004:"+exp+":1";
			strs.push(str);
		}
		if(money>0){
			str="dj1000:"+money+":1";
			strs.push(str);
		}
		return strs;
	}

	TaskUtil.addColor=function(text,color){
		if(TaskUtil.isLink==false){
			return text;
		}
		return "<font color='"+color+"'>"+text+"</font>";
	}

	TaskUtil.addMonsterPosLink=function(taskVO){
		if(!TaskUtil.isLink){
			return "";
		};
		var mapLineCfgData=CfgManager.getTableCfg("MapLine");
		var mapName="";
		if(taskVO.MonsterMapID){
			mapName=mapLineCfgData.getItemByField("mapid",String(taskVO.MonsterMapID)).mapname;
		};
		var arr=taskVO.completeMonster.split(":");
		var monsterId=arr[0].substring(1,arr[0].length);
		var name=Model.monster.getMonsterNameById(monsterId);
		var str="";
		if(mapName){
			str=com.xq.modules.task.TaskUtil.addColor(mapName+"的","#22991e")+"<span href='event:"+"'>"+name+"</span>";
		}
		else{
			str="<span href='event:"+"'>"+name+"</span>";
		}
		return str;
	}

	TaskUtil.addNpcPosLink=function(vo){
		var mapLineCfgData=CfgManager.getTableCfg("MapLine");
		var mapName=mapLineCfgData.getItemByField("mapid",String(vo.map)).mapname;
		var str=com.xq.modules.task.TaskUtil.addColor(mapName+"的","#22991e")+"<span href='event:"+vo.id+"'>"+vo.name+"</span>";
		return str;
	}

	TaskUtil.isLink=false;
	return TaskUtil;
})()


