/**
*组队逻辑管理
*@author zhanglimin
*@date 2019-12-9
*/
//class com.xq.modules.team.TeamMgr
var TeamMgr=(function(){
	function TeamMgr(){
		this._model=null;
		/**收到的邀请信息列表*/
		this.beInvitedList=[];
		/**定时清除组队邀请信息*/
		this.clearBeInvitedTime=2*60*1000;
		/**最大显示的组队邀请信息数量*/
		this.maxBeInvitedNum=5;
		this._teamType=null;
		/**组队匹配状态字典*/
		this.teamMatchDic=null;
		this.matchType=-1;
		this.acceptHandlerDic={};
		this.teanMain=null;
		this.teamInfo=new Object();
		this.teamMatchDic=new Dictionary();
		this._model=new TeamModel();
		this.startListener();
	}

	__class(TeamMgr,'com.xq.modules.team.TeamMgr');
	var __proto=TeamMgr.prototype;
	__proto.startListener=function(){
		EventCenter.instance.on("RefreshTeamInfoTeamEvent",this,this.updataTeamInfo);
		EventCenter.instance.on("ExitTeamTeamEvent",this,this.hideTeamMain,[false]);
		EventCenter.instance.on("ENTER_SCENE",this,this.checkMapTypeHandler);
	}

	/**场景切换后操作*/
	__proto.checkMapTypeHandler=function(){
		var rolevo=NetMgr.ins().roleVO;
		if(MapType.isCopy(rolevo.mapType)){
			this.hideTeamMain(false);
			return;
		}
		UIMgrR.closeIView(com.xq.view.modules.marriage.IMarriageInvite);
	}

	__proto.updataTeamInfo=function(){
		var teamInfo=Mgr.teamMgr.getTeamInfo();
		if(this.teamType==TeamEnum.YinYuanFuBen){
			return;
		}
		if(!teamInfo){
			this.hideTeamMain(false);
			return;
		}
		if(teamInfo.members.length >=teamInfo.maxNum){
			this.openCurTeam();
		}
		this.hideTeamMain(true);
	}

	__proto.updateMarriageTeam=function(msg){
		var marriageTeam=UIMgrR.openIView(com.xq.view.modules.marriage.IMarriageCopyMatch,2);
		marriageTeam.loverState=msg.param;
		if(msg.param==1){
			Mgr.teamAct.reqInviteTeam(Mgr.teamMgr.teamType,Mgr.marriageMgr.model.marryInfo.partarner.roleId,Mgr.marriageMgr.model.marryInfo.partarner.serverId);
		}
	}

	__proto.hideTeamMain=function(isShow){
		if(isShow){
			var vo=new CommonNoticeVo();
			var type=CommonNoticeType.Team;
			var team=Mgr.teamMgr.getTeamInfo();
			var desc=team.members.length+"/"+team.maxNum;
			var hand=Handler.create(this,this.openCurTeam,null,false);
			vo.setDat(type,desc,hand);
			NoticeManager.ins.addNotice(vo);
		}
		else{
			NoticeManager.ins.removeNotice(CommonNoticeType.Team);
		}
	}

	__proto.openCurTeam=function(){
		if(!this.teamType)return;
		UIMgrR.openViewByFunID(this.teamType.functionId,null,2);
	}

	__proto.getMatchState=function(teamType){
		return this.teamMatchDic.get(teamType);
	}

	__proto.setMatchState=function(teamType,state){
		this.teamMatchDic.set(teamType,state);
	}

	/**获取队伍信息*/
	__proto.getTeamInfo=function(type){
		return this._model.getTeamInfo(type);
	}

	/**根据队伍类型 获取 组队成员上限*/
	__proto.getMemberNumLimit=function(type){
		var teamVo=!type?this._model.getTeamInfo():this._model.getTeamInfo(type);
		if(teamVo){
			return teamVo.maxNum;
		}
		return 0;
	}

	/**队伍是否已经满了*/
	__proto.checkTeamFull=function(type){
		var teamVo=!type?this._model.getTeamInfo():this._model.getTeamInfo(type);
		if(teamVo){
			return teamVo.members.length >=teamVo.maxNum;
		}
		return false;
	}

	/**检测是否已经在这个队伍中*/
	__proto.checkInTeam=function(type,id){
		var teamInfo=this._model.getTeamInfo(type);
		if(teamInfo&&teamInfo.teamId==id){
			return true;
		}
		return false;
	}

	/**检测是否匹配机器人*/
	__proto.checkMatchRobot=function(type){
		return this._model.checkMatchRoBot(type);
	}

	/**检测是否没有一键喊话功能*/
	__proto.checkNotCall=function(type){
		return this._model.checkNotCall(type);
	}

	/**检测是否没有自动匹配功能*/
	__proto.checkNotPiPei=function(type){
		return this._model.checkNotPiPei(type);
	}

	/**检测是否没有邀请功能*/
	__proto.checkNotInvite=function(type){
		return this._model.checkNotInvite(type);
	}

	__proto.clearTeamInfo=function(){
		this._model.clearAllTeam();
		this.hideTeamMain(false);
	}

	/**检查是否有除某个队伍之外还有队伍
	*没有返回0
	*有就返回对应队伍类型
	**/
	__proto.checkHasAnotherTeam=function(tarType){
		return this._model.checkHasOtherTeam(tarType);
	}

	/**判断是否是队长*/
	__proto.checkIsCaptain=function(id,type){
		var vo=this.getTeamInfo(type);
		if(vo && vo.masterId==id){
			return true
		}
		return false;
	}

	/**获取一键喊话内容*/
	__proto.getChatStr=function(){
		var str=CodeMgr.ins.getStringByCode([260688,this.teamType.name]);
		return str;
	}

	/**一键喊话*/
	__proto.oneKeyCall=function(){
		var teamInfo=this.getTeamInfo();
		if(teamInfo){
			var o={};
			o.funid=this.teamType.functionId;
			o.data=[teamInfo.teamId];
			o.type=this.teamType;
			var str=Mgr.teamMgr.getChatStr();
			if(Mgr.teamMgr.teamType !=TeamEnum.SanYingHui){
				Mgr.chat.sendInfo(str,6,o);
			}
			else{
				Mgr.chat.sendInfo(str,4,o);
			}
		}
	}

	//主界面气泡弹窗
	__proto.createNoticeBall=function(){
		var vo=new CommonNoticeVo();
		var type=CommonNoticeType.Invite;
		var handler=Handler.create(this,this.onClickBall,null,false);
		vo.setDat(type,"",handler);
		NoticeManager.ins.addNotice(vo);
	}

	__proto.onClickBall=function(){
		UIMgrR.openIView(com.xq.view.modules.team.ITeamInvitedView,2);
	}

	__proto.removeNoticeBall=function(){
		NoticeManager.ins.removeNotice(CommonNoticeType.Invite);
	}

	/**收到邀请弹出*/
	__proto.onInviteData=function(msg){
		var isRepeat=false;
		var len=this.beInvitedList.length;
		for(var i=0;i < len;i++){
			var o=this.beInvitedList[i];
			if(o && o.teamId==msg.teamId){
				isRepeat=true;
				this.beInvitedList[i]=msg;
				break ;
			}
		}
		if(!isRepeat){
			this.beInvitedList.push(msg);
		}
		if(this.beInvitedList.length > this.maxBeInvitedNum){
			this.beInvitedList.shift();
		}
		this.createNoticeBall();
		Laya.timer.once(this.clearBeInvitedTime,this,this.clearInviteData);
	}

	/**收到姻缘副本邀请弹出*/
	__proto.onMarriageCopyInvite=function(msg){
		var rolevo=NetMgr.ins().roleVO;
		if(MapType.isCopy(rolevo.mapType)){
			return;
		};
		var marriageInvite=UIMgrR.openIView(com.xq.view.modules.marriage.IMarriageInvite,2);
		marriageInvite.dataSource=msg;
	}

	__proto.createMarriageTeam=function(){
		if(this.ifInTeam){
			Mgr.prompt.optionPrompt("正在组队中，无法进入姻缘副本");
			}else{
			Mgr.teamAct.c_creatTeam(TeamEnum.YinYuanFuBen);
		}
	}

	/**收到姻缘副本邀请*/
	__proto.onMarriageInvite=function(){}
	__proto.clearInviteData=function(){
		Laya.timer.clear(this,this.clearInviteData);
		this.beInvitedList.length=0;
		this.removeNoticeBall();
	}

	/**获取被邀请的组队信息列表*/
	__proto.getBeInvitedInfos=function(){
		return this.beInvitedList.reverse();
	}

	/**检测被邀请的组队信息列表 如果都同意了就清除掉提示*/
	__proto.checkAndClearBeInvitedInfos=function(){
		var len=this.beInvitedList.length;
		var remainArr=[];
		for(var i=0;i < len;i++){
			var o=this.beInvitedList[i];
			if(!o["a"]){
				remainArr.push(o);
			}
		}
		this.beInvitedList=remainArr;
		if(this.beInvitedList.length==0){
			this.clearInviteData();
		}
	}

	//==============同步后端数据==================
	__proto.updateCreatTeam=function(msg){
		var creatTeamType=this._model.getFlagTeamType();
		if(creatTeamType==TeamEnum.YinYuanFuBen && msg.param==2){
			Mgr.prompt.optionPrompt("对方正在副本中");
			return;
		}
		this._model.updateTeam(msg.teamVO);
		var curTeamType=this._model.getCurTeamType();
		if(curTeamType==TeamEnum.YinYuanFuBen){
			this.updateMarriageTeam(msg);
		}
		else{
			this.updataTeamInfo();
		}
		EventCenter.instance.event("SuccseCreateTeamEvent");
		console.log("创建队伍成功====队伍类型："+curTeamType.teamType+"=====功能ID:"+curTeamType.functionId);
	}

	__proto.updateApplyTeam=function(msg){
		this._model.updateTeam(msg.teamVO);
	}

	__proto.updateJoinTeamOneKey=function(msg){
		if(msg.state==3){
			console.log("一键加入成功=================")
		}
		else if(msg.state==4){
			Mgr.prompt.optionPrompt(260679);
		}
	}

	/**同步收到组队邀请*/
	__proto.updateOnBeInvited=function(msg){
		if(msg.teamType==TeamEnum.YinYuanFuBen.teamType){
			this.onMarriageCopyInvite(msg);
			}else{
			this.onInviteData(msg);
		}
	}

	/**接受邀请*/
	__proto.updateAccept=function(msg){
		var typeVo=this._model.getTeamEnumVo(msg.teamType,msg.ext);
		this.updateFlagTeamType(typeVo);
		var vo=new TeamPublicVO();
		vo.teamId=msg.teamId;
		this._model.updateTeam(vo);
		var handler=this.acceptHandlerDic[typeVo];
		if(handler){
			handler.runWith(typeVo);
			this.acceptHandlerDic[typeVo]=null;
			Mgr.prompt.optionPrompt("成功加入组队");
		}
		EventCenter.instance.event("SuccssReciveInvitedEvent",this.teamType);
	}

	/**推出队伍*/
	__proto.updateExitTeam=function(msg){
		Mgr.teamMgr.setMatchState(Mgr.teamMgr.teamType,0)
		this._model.clearTeam(msg.teamType);
		EventCenter.instance.event("ExitTeamTeamEvent");
	}

	/**被提出队伍*/
	__proto.udpateBeTicked=function(msg){
		if(msg.roleId==NetMgr.ins().roleVO.guid){
			this._model.clearTeam(msg.teamType);
			EventCenter.instance.event("ExitTeamTeamEvent");
		}
	}

	/**同步更新当前队伍信息*/
	__proto.updateRefreshTeam=function(msg){
		this._model.updateCurTeam(msg.teamVO);
		EventCenter.instance.event("RefreshTeamInfoTeamEvent");
	}

	/**获取当前队伍类型*/
	__proto.getCurTeamType=function(){
		return this._model.getCurTeamType();
	}

	/**记录当前创建或解散队伍 注意是要创建的队伍类型，不是已创建成功的队伍类型！*/
	__proto.updateFlagTeamType=function(type){
		this._model.updateFlagTeamType(type);
	}

	__proto.updateAccepHandler=function(type,handler){
		this.acceptHandlerDic[type]=handler
	}

	/**根据队伍类型 和额外类型 确定对应队伍枚举*/
	__proto.getTeamEnumVo=function(teamType,exrtType){
		return this._model.getTeamEnumVo(teamType,exrtType);
	}

	/**满人后自动进入副本倒计时时间*/
	__proto.getAutoEnterCopyTime=function(){
		return this._model.getAutoEnterCopyTime();
	}

	/**组队副本 自动加入机器人时间*/
	__proto.getAddBotTime=function(){
		return this._model.getAddBotTime();
	}

	/**注册组队 不添加机器人 无一键喊话 无自动匹配 无邀请 类型*/
	__proto.registTeamType=function(teamtype,ifBot,ifNoCall,ifNoPiPei,ifNoInvite){
		this._model.registTeamType(teamtype,ifBot,ifNoCall,ifNoPiPei,ifNoInvite);
	}

	/**
	*@private
	*/
	/**当前队伍类型*/
	__getset(0,__proto,'teamType',function(){
		return this._model.getCurTeamType();
		},function(value){
		this._teamType=value;
	});

	/**是否处于队伍中*/
	__getset(0,__proto,'ifInTeam',function(){
		return this._model.checkInTeam();
	});

	return TeamMgr;
})()


