/**
*@author YuHaiTao
*@data 2018-4-17
**/
//class com.xq.modules.tequanlibao.TequanMgr
var TequanMgr=(function(){
	function TequanMgr(){
		/**特权表*/
		this.teQuanTableConfig=null;
		/**是否勾选 本次登录不再提示购买月卡*/
		this.isHintBuy=false;
		this.teQuanTableConfig=CfgManager.getTableCfg("VipTeQuan");
	}

	__class(TequanMgr,'com.xq.modules.tequanlibao.TequanMgr');
	var __proto=TequanMgr.prototype;
	/**根据id获取一行特权表数据*/
	__proto.getTeQuanById=function(id){
		return this.teQuanTableConfig.getItemByField("id",id+"");
	}

	__proto.getTequanVal=function(tequanType,vipLevel){
		(vipLevel===void 0)&& (vipLevel=0);
		var teQuanNum=0;
		var teQuanCfg=this.getTeQuanById(tequanType);
		if(vipLevel){
			vipLv=vipLevel;
			}else{
			var vipLv=NetMgr.ins().roleVO.vipLevel;
		}
		if(Mgr.chaoZhiTeDianMgr.isBuyYk)
			teQuanNum+=parseInt(teQuanCfg.yueka);
		if(Mgr.chaoZhiTeDianMgr.isBuyZz)
			teQuanNum+=parseInt(teQuanCfg.zhizunka);
		if(Mgr.zhouka.ifActive){
			teQuanNum+=parseInt(teQuanCfg.zhouka);
		}
		if(vipLv > 0)
			teQuanNum+=parseInt(teQuanCfg["vip"+vipLv])?parseInt(teQuanCfg["vip"+vipLv]):0;
		if(Model.vip.vipData){
			var normalVipLv=Model.vip.vipData.normalVipLevel;
			if(normalVipLv > 0){
				teQuanNum+=parseInt(teQuanCfg["nvip"+normalVipLv])?parseInt(teQuanCfg["nvip"+normalVipLv]):0;
			}
		}
		return teQuanNum;
	}

	/**只取至尊月卡的值 不管买没买*/
	__proto.getZzTequanVal=function(tequanType){
		var teQuanNum=0;
		var teQuanCfg=this.getTeQuanById(tequanType);
		teQuanNum+=parseInt(teQuanCfg.zhizunka);
		return teQuanNum;
	}

	/**只取元宝月卡的值 不管买没买*/
	__proto.getYkTequanVal=function(tequanType){
		var teQuanNum=0;
		var teQuanCfg=this.getTeQuanById(tequanType);
		teQuanNum+=parseInt(teQuanCfg.yueka);
		return teQuanNum;
	}

	/**只取周卡的值 不管买没买*/
	__proto.getZkTequanVal=function(tequanType){
		var teQuanNum=0;
		var teQuanCfg=this.getTeQuanById(tequanType);
		teQuanNum+=parseInt(teQuanCfg.zhouka);
		return teQuanNum;
	}

	/**获取某个特权类型中最大的vip等级特权值*/
	__proto.getMaxValByVipMax=function(tequanType){
		var teQuanCfg=this.getTeQuanById(tequanType);
		var vipMax=Mgr.vipcfgMgr.maxSvipLv;
		var val=parseInt(teQuanCfg["vip"+vipMax])?parseInt(teQuanCfg["vip"+vipMax]):0;
		return val;
	}

	/**获取某个特权类型的最大特权值*/
	__proto.getMaxValByTequanType=function(tequanType){
		var val=this.getZzTequanVal(tequanType);
		val+=this.getYkTequanVal(tequanType);
		val+=this.getMaxValByVipMax(tequanType);
		return val;
	}

	/**获取某个特权类型中下一个不同的值的vip等级，没有则返回-1*/
	__proto.getVipLevelByNextDifferent=function(tequanType,flagVip){
		(flagVip===void 0)&& (flagVip=-1);
		var vipLv=flagVip;
		if(flagVip==-1){
			vipLv=NetMgr.ins().roleVO.vipLevel;
		};
		var teQuanCfg=this.getTeQuanById(tequanType);
		var vipMax=Mgr.vipcfgMgr.maxSvipLv;
		var curVal=parseInt(teQuanCfg["vip"+vipLv]);
		for(var i=vipLv;i <=vipMax;i++){
			var val=parseInt(teQuanCfg["vip"+i])?parseInt(teQuanCfg["vip"+i]):curVal;
			if(val !=curVal){
				return i;
			}
		}
		return-1;
	}

	/**这个应该是获取某个特权类型中最低需要的vip等级*/
	__proto.getVipLevelByTequanType=function(tequanType){
		var teQuanCfg=this.getTeQuanById(tequanType);
		var vipMax=Mgr.vipcfgMgr.maxSvipLv;
		for(var i=0;i <=vipMax;i++){
			var val=parseInt(teQuanCfg["vip"+i])?parseInt(teQuanCfg["vip"+i]):0;
			if(val >0){
				return i;
			}
		}
		return 0;
	}

	__proto.getKuaiSuGuaJiNum=function(){
		var curNum=this.getTequanVal(28);
		var vipLv=NetMgr.ins().roleVO.vipLevel;
		var vipMax=Mgr.vipcfgMgr.maxSvipLv;
		for (var i=vipLv;i <=vipMax;i++){
			var next=this.getTequanVal(28,i);
			if(next > curNum){
				break ;
			}
		}
		if(i > vipMax)return vipLv;
		return i;
	}

	__proto.getMaterialSaoDangNum=function(){
		var curNum=this.getTequanVal(23);
		var vipLv=NetMgr.ins().roleVO.vipLevel;
		var vipMax=Mgr.vipcfgMgr.maxSvipLv;
		for (var i=vipLv;i <=vipMax;i++){
			var next=this.getTequanVal(23,i);
			if(next > curNum){
				break ;
			}
		}
		if(i > vipMax)return [vipLv,curNum,next];
		return [i,curNum,next];
	}

	__proto.getTianShenSanDangNum=function(){
		var curNum=this.getTequanVal(35);
		var vipLv=NetMgr.ins().roleVO.vipLevel;
		var vipMax=Mgr.vipcfgMgr.maxSvipLv;
		for (var i=vipLv;i <=vipMax;i++){
			var next=this.getTequanVal(35,i);
			if(next > curNum){
				break ;
			}
		}
		if(i > vipMax)return vipLv;
		return i;
	}

	__proto.getExpJiNum=function(){
		var curNum=this.getTequanVal(29);
		var vipLv=NetMgr.ins().roleVO.vipLevel;
		var vipMax=Mgr.vipcfgMgr.maxSvipLv;
		for (var i=vipLv;i <=vipMax;i++){
			var next=this.getTequanVal(29,i);
			if(next > curNum){
				break ;
			}
		}
		if(i > vipMax)return vipLv;
		return i;
	}

	/**设置本次登录 是否不再提示购买月卡*/
	__getset(0,__proto,'setIsHintBuy',null,function(isBuy){
		this.isHintBuy=isBuy;
	});

	/**获取 是否勾选 本次登录不再提示购买月卡*/
	__getset(0,__proto,'getIsHintBuy',function(){
		return this.isHintBuy;
	});

	return TequanMgr;
})()


