/**
*天降豪礼逻辑类
*@author zhanglimin
*@date 2020-5-15
**/
//class com.xq.modules.tianjianghaoli.TianJiangHaoLiMgr
var TianJiangHaoLiMgr=(function(){
	function TianJiangHaoLiMgr(){
		/**当前活动配置*/
		this.curCfg=null;
		/**活动结束时间戳*/
		this.reaminTime=NaN;
		/**活动信息*/
		this.msgInfo=null;
		this.copyInfo=null;
	}

	__class(TianJiangHaoLiMgr,'com.xq.modules.tianjianghaoli.TianJiangHaoLiMgr');
	var __proto=TianJiangHaoLiMgr.prototype;
	__proto.regActive=function(){
		ActManager.ins.regist("quantianwangwanfa","tianjianghaoli",74,"RiChang");
		var hand=Handler.create(this,this.openAct,null,false);
		NewActiveManager.ins.regActOpenHandler(74,hand);
		NewActiveManager.ins.regActEndHandler(74,Handler.create(this,this.closeAct,null,false));
		Mgr.xianShi.regActivity("tianjianghaoli",Handler.create(Mgr.tjhlAct,Mgr.tjhlAct.reqEnter,null,false));
	}

	/**天降豪礼活动开启*/
	__proto.openAct=function(){
		Mgr.opeAct.sendGetTargetActivity(74);
		var actVo=NewActiveManager.ins.getActiveVerDic(74);
		if(actVo){
			this.reaminTime=actVo.endTime;
			this.initCfg(actVo.flag);
		}
		CopyTipMgr.ins.regisCopyTip(144,Handler.create(this,this.closeTips,null,false));
	}

	/**活动信息*/
	__proto.initInfo=function(msg){
		this.msgInfo=msg;
		EventCenter.instance.event("changeinfoTjhl");
	}

	/**更新采集次数*/
	__proto.updateTimes=function(num){
		if(this.msgInfo){
			this.msgInfo.hasTimes=num
		}
		EventCenter.instance.event("changetimes");
	}

	/**初始化活动配置*/
	__proto.initCfg=function(flag){
		var tempCfg=CfgManager.getTableCfg("tianjianghaoli");
		if(tempCfg){
			this.curCfg=tempCfg.getItemByField("flag",flag);
		}
		if(!this.curCfg){
			console.log("天降豪礼活动伦次flag="+flag+"没有拿到配置");
			debugger;
		}
	}

	/**活动剩余时间*/
	__proto.getActtime=function(){
		var gap=this.reaminTime-Browser.now();
		if(gap > 0){
			return gap;
		}
		return null;
	}

	/**活动关闭*/
	__proto.closeAct=function(){
		CollectMgr.ins().interruptCollect();
	}

	/**显示豪礼副本信息*/
	__proto.showCopyInfo=function(){
		this.copyInfo=UIMgrR.openIView(com.xq.view.modules.activity.tianjianghaoli.ITianJiangHaoLiCopy,2);
	}

	__proto.closeTips=function(){
		if(this.copyInfo && this.copyInfo.isPopup){
			this.copyInfo.close();
			this.copyInfo=null;
		}
	}

	/**天降豪礼信息数据*/
	__proto.initFightVo=function(fightVo){
		fightVo.hideAry=[2,3,4];
		fightVo.aniType=-1;
		fightVo.closeFun=Handler.create(Mgr.tjhlAct,Mgr.tjhlAct.reqExit,null,false);
		fightVo.remainTime=this.getActtime();
		this.showCopyInfo();
	}

	TianJiangHaoLiMgr.ChangeInFo="changeinfoTjhl";
	TianJiangHaoLiMgr.ChangeTimes="changetimes";
	return TianJiangHaoLiMgr;
})()


//class com.xq.modules.tianming.TianMingMgr
var TianMingMgr=(function(){
	function TianMingMgr(){
		this.model=null;
		this.slotsDic=null;
		this.selectQuaDic=null;
		this.selectTmGuids=null;
		this.selectSlotEle=null;
		/**已镶嵌类型*/
		this.xiangQianType=null;
		this.ifAutoBreak=true;
		/**当前选中的栏位是都已镶嵌*/
		this.ifSelectXq=false;
		this.curJjxType=0;
		this._selectmInfo=[];
		this._red=null;
		this.ifBreakIng=false;
		this.model=Model.tianming;
		this.slotsDic=new Dictionary();
		this.selectQuaDic=new Dictionary();
		this.selectTmGuids=[];
		this.xiangQianType=new Dictionary();
		this._red=Mgr.red;
		EventCenter.instance.on("curLvChanged",this,this.updateAllStat);
	}

	__class(TianMingMgr,'com.xq.modules.tianming.TianMingMgr');
	var __proto=TianMingMgr.prototype;
	// EventCenter.instance.onQue(GameEvent.ITEM_CHANGE,this,updateItemRed);
	__proto.initBag=function(){
		Mgr.tianmingAction.c_getBagInfo();
	}

	__proto.initTianMing=function(){
		Mgr.tianmingAction.c_getInfo(18);
		Mgr.tianmingAction.c_getInfo(2);
		Mgr.tianmingAction.c_getInfo(3);
		Mgr.tianmingAction.c_getInfo(6);
	}

	//=========================================================
	__proto.updateInfo=function(msg){
		var type=msg.type;
		var dc=this.model.getSlotDcByType(type);
		var arr=msg.infos;
		var len=arr.length;
		var dic=this.slotsDic.get(type)
		if(!dic){
			dic=new Dictionary();
			this.slotsDic.set(type,dic);
		};
		var typeArr=this.xiangQianType.get(type);
		if(!typeArr){
			typeArr=[];
			this.xiangQianType.set(type,typeArr);
		}
		for(var i=0;i<len;i++){
			var info=arr[i];
			var slot=info.pos;
			var ele=dc.getElement(slot);
			if(ele){
				ele.setValue("SlotSvrInfo",info);
				ele.setValue("TmLevel",info.level);
				var cof=ele.getCfgData();
				dic.set(cof.slot,info.guid);
			};
			var tmEle=this.model.getTmById(info.id);
			if(tmEle){
				var tmCof=tmEle.getCfgData();
				var tmType=tmCof.type;
				if(typeArr.indexOf(tmType)==-1){
					typeArr.push(tmType);
				}
			}
		}
		this.model.jinghuaNum=msg.jinghua;
		this.updateStat(type);
		this.updateAllRed();
	}

	__proto.updateStat=function(type){
		var dc=this.model.getSlotDcByType(type);
		var slotArr=dc.array;
		var len=slotArr.length;
		for(var i=0;i<len;i++){
			var ele=slotArr[i];
			ele.setValue("SlotStat",this.getStat(ele));
		}
		EventCenter.instance.event("UpdateTianMing");
	}

	// updateRed(type);
	__proto.updateAllStat=function(){
		this.updateStat(18);
		this.updateStat(2);
		this.updateStat(3);
		this.updateStat(6);
	}

	/**刷新天命背包数据*/
	__proto.updateBagInfo=function(msg){
		var arr=msg.infos;
		this.model.tmBagArr=arr.sort(this.compare);
		var dic=this.model.tmBagDic;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var info=arr[i];
			dic.set(info.guid,info);
		}
		this.updateAllStat();
		this.updateAllRed();
		EventCenter.instance.event("UpdateTianMingBag");
	}

	__proto.updateOption=function(msg){
		var type=msg.type;
		if(msg.opType==1){
			Mgr.prompt.optionPrompt("镶嵌命格成功");
		}
		else{
			Mgr.prompt.optionPrompt("卸下命格成功");
		}
		this.clearCache(type);
		Mgr.tianmingAction.c_getBagInfo();
		Mgr.tianmingAction.c_getInfo(type);
	}

	__proto.clearCache=function(type){
		var dc=this.model.getSlotDcByType(type);
		var arr=dc.array;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var ele=arr[i];
			if(ele){
				ele.setValue("SlotSvrInfo",null);
				ele.setValue("TmLevel",null);
				ele.setValue("SlotStat",0);
				var cof=ele.getCfgData();
				var dic=this.slotsDic.get(type);
				if(dic){
					dic.clear();
				}
			}
		}
		this.xiangQianType.remove(type);
	}

	__proto.updateUpgrade=function(msg){
		var type=msg.type;
		Mgr.tianmingAction.c_getBagInfo();
		Mgr.tianmingAction.c_getInfo(type);
		Mgr.prompt.optionPrompt("命格升级成功");
	}

	__proto.updateBreak=function(msg){
		this.model.jinghuaNum+=msg.jinghua;
		Mgr.prompt.optionPrompt("命格分解成功");
		EventCenter.instance.event("UpdateTianMingJingHua");
		Mgr.tianmingAction.c_getBagInfo();
	}

	__proto.updateBagAdd=function(msg){
		var info=msg.info;
		this.model.tmBagArr.push(info);
		this.model.tmBagArr=this.model.tmBagArr.sort(this.compare);
		this.model.tmBagDic.set(info.guid,info);
		this.updateAllStat();
		this.updateAllRed();
		EventCenter.instance.event("UpdateTianMingBag");
		if(this.model.AllTmNum>=300){
			if(this.ifAutoBreak&&!this.ifBreakIng){
				this.ifBreakIng=true;
				Laya.timer.once(500,this,this.autoBreak);
			}
		}
	}

	// autoBreak();
	__proto.getStat=function(ele){
		if(!this.ifUnLocked(ele))return 1;
		if(this.ifUnmounted(ele))return 5;
		if(this.ifChange(ele))return 4;
		if(this.ifUpgrade(ele))return 3;
		return 2;
	}

	/**获取对应类型天命总等级*/
	__proto.getAllLevelByType=function(type){
		var arr=this.model.getSlotDcByType(type).array;
		var len=arr.length;
		var ele;
		var allGrade=0;
		for(var i=0;i<len;i++){
			ele=arr[i];
			var level=ele.getValue("TmLevel");
			if(!level)continue ;
			allGrade+=level;
		}
		return allGrade;
	}

	/**检测栏位是否解锁*/
	__proto.ifUnLocked=function(ele){
		if(!ele)return false;
		var cof=ele.getCfgData();
		var jjxType=cof.ziyuanType;
		var limitType=cof.limitType;
		var limitVal=cof.limitVal;
		var myVal=0;
		if(limitType==1){
			myVal=this.getAllLevelByType(jjxType);
		}
		else if(limitType==2){
			myVal=Mgr.lunhuijingM.curLv;
		}
		return myVal>=limitVal;
	}

	/**是否是未镶嵌*/
	__proto.ifUnmounted=function(ele){
		var info=ele.getValue("SlotSvrInfo");
		if(!info||!info.id)return true;
		return false;
	}

	/**是否可替换*/
	__proto.ifChange=function(ele){
		if(!ele)return false;
		var slotCof=ele.getCfgData();
		var type=slotCof.ziyuanType;
		var info=ele.getValue("SlotSvrInfo");
		if(!info||!info.id)return false;
		var slot=info.pos;
		var id=info.id;
		var level=info.level;
		var tmEle=this.model.getTmById(id);
		if(!tmEle)return false;
		var tmCof=tmEle.getCfgData();
		var qua=tmCof.quality;
		var bagArr=this.model.tmBagArr;
		var len=bagArr.length;
		for(var i=0;i<len;i++){
			var bagInfo=bagArr[i];
			if(this.ifXiangQian(bagInfo.guid)){
				continue ;
			};
			var bagId=bagInfo.id;
			var baglv=bagInfo.level;
			var bagEle=this.model.getTmById(bagId);
			if(bagEle){
				if(this.checkSlot(type,slot,bagEle)){
					var bagCof=bagEle.getCfgData();
					var bagQua=bagCof.quality;
					if((id==bagId&&level<baglv)||(qua < bagQua)){
						return true;
					}
				}
			}
		}
		return false;
	}

	__proto.getXiangQianArr=function(slot){
		var xqArr=[];
		if(!slot)return xqArr;
		var slotCof=slot.getCfgData();
		var type=slotCof.ziyuanType;
		var bagArr=this.model.tmBagArr;
		var len=bagArr.length;
		for(var i=0;i<len;i++){
			var bagInfo=bagArr[i];
			if(this.ifXiangQian(bagInfo.guid)){
				continue ;
			};
			var bagId=bagInfo.id;
			var baglv=bagInfo.level;
			var bagEle=this.model.getTmById(bagId);
			if(bagEle){
				if(this.checkSlot(type,slotCof.slot,bagEle)){
					if(!this.ifXiangQianType(type,bagEle.getCfgData().type)){
						xqArr.push(bagEle);
					}
				}
			}
		}
		return xqArr;
	}

	/**检测某个天命是否可以安装到某个栏位中*/
	__proto.checkSlot=function(type,slot,tmEle){
		if(!tmEle)return false;
		var tmCof=tmEle.getCfgData();
		var jjxType=parseInt(tmCof.ziyuanType);
		if(jjxType!=0){
			if(jjxType !=type){
				return false;
			}
		};
		var slots=tmCof.slots.split(";");
		return slots.indexOf(slot.toString())!=-1;
	}

	__proto.ifUpgrade=function(ele){
		if(!ele)return false;
		var info=ele.getValue("SlotSvrInfo");
		if(!info)return false;
		var level=info.level;
		var id=info.id;
		var tmEle=this.model.getTmById(id);
		if(!tmEle)return false;
		var cof=tmEle.getCfgData();
		var maxLevel=parseInt(cof.levelmax);
		if(level>=maxLevel)return false;
		var costType=parseInt(cof.costType);
		var base=parseInt(cof.costBase);
		var cost=parseInt(cof.levelcost);
		var needVal=base+base*(level-1)*cost;
		if(costType==0){
			var myVal=this.model.jinghuaNum;
		}
		else if(costType==1){
			myVal=this.getBagNumById(cof.id);
		}
		return needVal <=myVal;
	}

	/**通过Id获取天命背包中的数量*/
	__proto.getBagNumById=function(id){
		var arr=this.model.tmBagArr;
		var len=arr.length;
		var num=0;
		for(var i=0;i<len;i++){
			var info=arr[i];
			if(this.ifXiangQian(info.guid)){
				continue ;
			}
			if(id==info.id){
				num++;
			}
		}
		return num;
	}

	__proto.compare=function(a,b){
		var idA=a.id;
		var idB=b.id;
		var eleA=Model.tianming.getTmById(idA);
		var eleB=Model.tianming.getTmById(idB);
		var quaA=eleA.getCfgData().quality;
		var quaB=eleB.getCfgData().quality
		return quaB-quaA;
		return b.level-a.level;
		return a.id-b.id;
	}

	/**获取默认选中下标*/
	__proto.getDefault=function(type){
		var arr=this.model.getSlotDcByType(type).array;
		var len=arr.length;
		var curStat=0;
		var index=0;
		for(var i=0;i<len;i++){
			var ele=arr[i];
			var stat=this.getStat(ele);
			if(curStat<stat){
				curStat=stat;
				index=i;
			}
		}
		return index;
	}

	__proto.ifXiangQian=function(guid){
		var arr=this.slotsDic.values;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var dic=arr[i];
			if(dic){
				var guidArr=dic.values;
				if(guidArr.indexOf(guid)!=-1){
					return true;
				}
			}
		}
		return false;
	}

	/**是否是材料类型*/
	__proto.ifCaiLiao=function(id){
		return this.getTypeById(id)==1;
	}

	/**清除当前选中*/
	__proto.removeSelect=function(){
		this.selectQuaDic.clear();
		this.selectTmGuids.length=0;
		this._selectmInfo.length=0;
	}

	__proto.getBreakList=function(){
		var breakList=[];
		var arr=this.model.tmBagArr;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var info=arr[i];
			if(!this.ifXiangQian(info.guid)){
				var ele=this.model.getTmById(info.id);
				if(ele){
					var cof=ele.getCfgData();
					if(!cof.ifSp){
						breakList.push(info);
					}
				}
			}
		}
		breakList=breakList.sort(this.compare)
		return breakList;
	}

	__proto.setSelectQua=function(qua,ifAdd){
		if(ifAdd){
			this.selectQuaDic.set(qua,qua);
		}
		else{
			this.selectQuaDic.remove(qua);
		}
		this.updateBreakSelectList();
		EventCenter.instance.event("UpdateTianMingBreakSelect");
	}

	__proto.updateBreakSelectList=function(){
		this.selectTmGuids.length=0;
		this._selectmInfo.length=0;
		var arr=this.getBreakList();
		var selectQuas=this.selectQuaDic.values;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var info=arr[i];
			var id=info.id;
			var ele=this.model.getTmById(id);
			if(ele){
				var qua=ele.getCfgData().quality;
				if(selectQuas.indexOf(qua)!=-1){
					this.selectTmGuids.push(info.guid);
					this._selectmInfo.push(info);
				}
			}
		}
	}

	__proto.updateSingleBreak=function(info,ifadd){
		if(ifadd){
			this.selectTmGuids.push(info.guid);
			this._selectmInfo.push(info);
		}
		else{
			var index=this.selectTmGuids.indexOf(info.guid);
			if(index!=-1){
				this.selectTmGuids.splice(index,1);
				this._selectmInfo.splice(index,1);
			}
		}
		EventCenter.instance.event("UpdateTianMingBreakSelect");
	}

	__proto.getCaiLiaoGuids=function(){
		var clArr=[];
		var arr=this.model.tmBagArr;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var info=arr[i];
			var ele=this.model.getTmById(info.id);
			if(ele){
				var cof=ele.getCfgData();
				if(cof.type==1){
					clArr.push(info);
				}
			}
		}
		return clArr;
	}

	__proto.selectCaiLiao=function(){
		var arr=this.getCaiLiaoGuids();
		var len=arr.length;
		for(var i=0;i<len;i++){
			this.updateSingleBreak(arr[i],true);
		}
	}

	__proto.getBreakReward=function(){
		var jh=0;
		var sp=0;
		var arr=this._selectmInfo;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var info=arr[i];
			var id=info.id;
			var ele=this.model.getTmById(id);
			if(ele){
				var cof=ele.getCfgData();
				if(cof.type==1){
					var jhAdd=parseInt(cof.soul);
				}
				else{
					jhAdd=parseInt(cof.costBase)+(info.level-1)*parseInt(cof.levelcost);
				}
				jh+=jhAdd;
				if(cof.breakChip&&cof.breakChip.lenght>0){
					var itemArr=cof.breakChip[0].split(":");
					var count=arr[2];
					sp+=count;
				}
			}
		}
		return [jh,sp];
	}

	/**是否被选中分解*/
	__proto.ifSelectBreak=function(guid){
		if(this.selectTmGuids.indexOf(guid)!=-1){
			return true;
		}
		else{
			return false;
		}
	}

	__proto.getAttrArr=function(cof,level){
		var attrArr=[];
		var baseArr=cof.attr;
		var chengzhangArr=cof.gudingxishu;
		var len=baseArr.length;
		for(var i=0;i<len;i++){
			var base=baseArr[i];
			var bArr=base.split("|");
			var name=bArr[0];
			var attrData=AttributeTypeEnum.getMsgByZhanLiCfg(name);
			if(attrData){
				if(attrData.isPer){
					var basePer=parseFloat(bArr[1]);
					var jc=chengzhangArr[i];
					var jcArr=jc.split("|");
					var jcPer=parseFloat(jcArr[1]);
					var curPer=basePer+jcPer*(level-1);
					attrArr.push(AttributeTypeEnum.getAttrCNameByEName(name)+"+"+(curPer*100).toFixed(1)+"%");
				}
				else{
					var baseV=parseInt(bArr[1]);
					jc=chengzhangArr[i];
					jcArr=jc.split("|");
					var jcV=parseInt(jcArr[1]);
					var curV=baseV+jcV*(level-1);
					attrArr.push(AttributeTypeEnum.getAttrCNameByEName(name)+"+"+curV);
				}
			}
		}
		return attrArr;
	}

	/**获取仓库中有多少该种天命*/
	__proto.getTmBagNum=function(id){
		var num=0;
		var arr=this.model.tmBagArr;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var bagInfo=arr[i];
			if(bagInfo.id==id&&!this.ifXiangQian(bagInfo.guid)){
				num++
			}
		}
		return num;
	}

	__proto.getXiangQianBgTM=function(slotEle){
		if(!slotEle)return null;
		var arr=[];
		var slot=slotEle.getCfgData().slot;
		var jjxType=parseInt(slotEle.getCfgData().ziyuanType);
		var info=slotEle.getValue("SlotSvrInfo");
		if(info&&info.id){
			arr.push(this.model.tmBagDic.get(info.guid));
			var type=this.getTypeById(info.id);
			this.ifSelectXq=true;
		}
		else{
			this.ifSelectXq=false;
			type=0;
		};
		var xqArr=this.getKeXiangQianTm(jjxType,type,slot);
		arr=arr.concat(xqArr);
		return arr;
	}

	__proto.getKeXiangQianTm=function(jjxType,type,slot){
		var tmArr=[];
		var arr=this.model.tmBagArr;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var bagInfo=arr[i];
			var id=bagInfo.id;
			var ele=this.model.getTmById(id);
			if(ele){
				if(this.checkSlot(jjxType,slot,ele)){
					if(!this.ifXiangQian(bagInfo.guid)&&!this.ifCaiLiao(bagInfo.id)){
						var tmType=this.getTypeById(bagInfo.id);
						if(tmType==type || !this.ifXiangQianType(jjxType,tmType)){
							tmArr.push(bagInfo);
						}
					}
				}
			}
		}
		return tmArr.sort(this.compare);
	}

	__proto.getTypeById=function(id){
		var ele=this.model.getTmById(id);
		if(ele){
			var type=ele.getCfgData().type;
			return type;
		}
		return 0;
	}

	__proto.ifXiangQianType=function(jjxType,tmType){
		var arr=this.xiangQianType.get(jjxType);
		if(arr){
			return arr.indexOf(tmType)!=-1;
		}
		return false;
	}

	__proto.getPowerType=function(type){
		switch(type){
			case 18:{
					return 152;
				}
			case 2:{
					return 149;
				}
			case 3:{
					return 150;
				}
			case 6:{
					return 151;
				}
			}
		return 0;
	}

	//==================红点相关========================
	__proto.updateRed=function(type){
		var func;
		var redtype;
		switch(type){
			case 18:{
					func="ZhanZhuangTianMing";
					redtype="ShiZhuangTMRed";
					break ;
				}
			case 2:{
					func="ZhanQiTianMing";
					redtype="ZhanQiTMRed";
					break ;
				}
			case 3:{
					func="ShenYiTianMing";
					redtype="ShenYiTMRed";
					break ;
				}
			case 6:{
					func="ShenBingTianMing";
					redtype="ShenWuTMRed";
					break ;
				}
			}
		if(!Mgr.guide.isOpen(func)){
			return;
		};
		var dc=this.model.getSlotDcByType(type);
		var arr=dc.array;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var ele=arr[i];
			var stat=this.getStat(ele);
			if(stat==4||stat==3){
				this._red.showRedPoint(func,func+"red",redtype);
				return;
			}
			else if((stat==5&&this.getXiangQianArr(ele).length>0)){
				this._red.showRedPoint(func,func+"red",redtype);
				return;
			}
		}
		this._red.hideRedPoint(func,func+"red",redtype);
	}

	// }
	__proto.updateAllRed=function(){
		this.updateRed(18);
		this.updateRed(2);
		this.updateRed(3);
		this.updateRed(6);
	}

	/**自动分解*/
	__proto.autoBreak=function(){
		var len=this.model.AllTmNum;
		if(len>=300){
			this.removeSelect();
			this.selectCaiLiao();
			if(this.selectTmGuids.length>0){
				this.ifBreakIng=false;
				Mgr.tianmingAction.c_break(this.selectTmGuids)
			}
		}
	}

	//===================天命组合预览===================
	__getset(0,__proto,'showArr',function(){
		return this.model.zuheDc.array;
	});

	return TianMingMgr;
})()


