//class com.xq.modules.tujian.TujianMgr
var TujianMgr=(function(){
	function TujianMgr(){
		/**当前选择图鉴id*/
		this.curSelect=0;
		/**当前菜单类型*/
		this.curTypeID=0;
		this.red=null;
		/**各种图鉴总等级字典*/
		this._model=null;
		this._model=new TuJianModel();
		this.registRed();
	}

	__class(TujianMgr,'com.xq.modules.tujian.TujianMgr');
	var __proto=TujianMgr.prototype;
	__proto.init=function(){
		if(!Mgr.guide.isOpen("tujian")){
			EventCenter.instance.on("new_function_open",this,this.newOpenFun);
		}
		else{
			this.reqData();
		}
	}

	__proto.reqData=function(){
		Mgr.tjProMgr.sendGetCS();
	}

	/**拉取所有图鉴后端数据*/
	__proto.updateInfo=function(msg){
		this._model.updateTuJianInfo(msg);
		this.checkRed();
		EventCenter.instance.event("GK_TIAOZHAN");
	}

	/**激活后同步数据*/
	__proto.updateJiHuo=function(msg){
		this._model.updateJiHuo(msg);
		EventCenter.instance.event("act_jhsc_tj");
		var tjpy=UIMgrR.openIView(com.xq.view.modules.tujian.ITuJianPeiYangView,2);
		tjpy.dataSource=this._model.getTuJianEleById(msg.cfgId);
	}

	/**升级后同步数据*/
	__proto.updateUpgrade=function(msg){
		this._model.updateUpgrade(msg);
		EventCenter.instance.event("info_sjsc_tj");
	}

	//=================红点==================
	__proto.registRed=function(){
		this.red=Mgr.red;
		this.red.regist("beibao","tujian",true,RedTypeEnum.Bag);
		EventCenter.instance.onQue("ITEM_CHANGE" ,this ,this.checkRed);
		EventCenter.instance.on("info_sjsc_tj",this,this.checkRed);
	}

	/**红点*/
	__proto.checkRed=function(){
		var arr=this._model.getTuJianDc().array;
		var len=arr.length;
		var tjEle;
		var cof;
		var id=0;
		var stat=0;
		var type=0;
		var typeRedDic={};
		for(var i=0;i<len;i++){
			tjEle=arr[i];
			cof=tjEle.getCfgData();
			type=cof.typeID;
			if(typeRedDic[type])continue ;
			id=tjEle.getCfgData().id;
			stat=this.getTuJianStat(id);
			if(stat>1){
				typeRedDic[type]=true;
			}
		}
		arr=this.getTypeArr();
		len=arr.length;
		for(i=0;i<len;i++){
			type=arr[i].getCfgData().typeID;
			if(typeRedDic[type]){
				this.red.showRedPoint("tujian",type+"","tujianred");
			}
			else{
				this.red.hideRedPoint("tujian",type+"","tujianred");
			}
		}
	}

	/**图鉴类型数据*/
	__proto.getTypeArr=function(){
		return this._model.getTypeDc().array;
	}

	/**根据图鉴类型 获取图鉴数据数组*/
	__proto.getTuJianArr=function(type){
		return this._model.getTuJianArrByType(type);
	}

	/**获取升级配置ele 后端等级数据存在这里*/
	__proto.getTiShenEle=function(tjId){
		return this._model.getTiShenEleById(tjId);
	}

	/**获取图鉴ele*/
	__proto.getTuJianEle=function(tjId){
		return this._model.getTuJianEleById(tjId);
	}

	/**根据图鉴Id获取状态 根据状态 大 到小排序
	*0：未激活 不可操作
	*1：已激活 不能操作
	*2：可升级
	*3：可激活
	**/
	__proto.getTuJianStat=function(id){
		var lvEle=this.getTiShenEle(id);
		if(!lvEle)return 0;
		var info=lvEle.getValue("s_data");
		var cof=lvEle.getCfgData();
		if(!info){
			var jhItem=cof.item1;
			if(Mgr.bag.checkItemIsEnough(jhItem)){
				return 3;
			}
			return 0;
		}
		else{
			var max=cof.level;
			var lv=info.level;
			if(lv>=max){
				return 1;
			}
			else{
				var needNum=lv+1;
				var id1=cof.item1.split(":")[0];
				var id2=cof.item2.split(":")[0];
				var have=Mgr.bag.getBagMatCount(id1)+Mgr.bag.getBagMatCount(id2);
				if(have>=needNum){
					return 2;
				}
				else{
					return 1;
				}
			}
		}
	}

	__proto.getAttrArr=function(tjId,ifNext){
		(ifNext===void 0)&& (ifNext=false);
		var lvEle=this.getTiShenEle(tjId);
		if(!lvEle)return [];
		var info=lvEle.getValue("s_data");
		var curLv=info?info.level:0;
		var cof=lvEle.getCfgData();
		var maxLv=cof.level;
		var color="";
		if(ifNext){
			if(curLv>=maxLv)return [];
			curLv=curLv+1;
			color="#4dff55";
		};
		var propId=cof.propId;
		var per=parseFloat(cof.basePer);
		var perAdd=parseFloat(cof.propPer);
		var propArr=Mgr.propM.attrFormula1(propId,per,perAdd,curLv,color);
		return propArr;
	}

	__proto.newOpenFun=function(funId){
		if(funId=="tujian"){
			this.reqData();
			EventCenter.instance.off("new_function_open",this,this.newOpenFun);
		}
	}

	return TujianMgr;
})()


