/**
*充值管理类
*author:huanghong
*2020-3-25
*/
//class com.xq.modules.vip.ChargeMgr
var ChargeMgr=(function(){
	function ChargeMgr(){
		this._chargeCof=null;
		/**充值dataContainer*/
		this._chargeData=null;
		/**返回表数据*/
		this.fanghuanData=null;
		this._red=null;
		this._chongzhiList=null;
		this._chongzhiDic=null;
		this._chargeCof=CfgManager.getTableCfg("chongzhi");
		this.init();
		this.registRed();
	}

	__class(ChargeMgr,'com.xq.modules.vip.ChargeMgr');
	var __proto=ChargeMgr.prototype;
	/**注册红点*/
	__proto.registRed=function(){
		this._red=Mgr.red;
		this._red.regist("RechargeHall","directBuyGift",true,"RechargeHall");
		this._red.regist("directBuyGiftIcon","weekBuyGift",true,"RechargeHall");
		this._red.regist("directBuyGiftIcon","monthBuyGift",true,"RechargeHall");
		this._red.regist("directBuyGiftIcon","directBuyGiftIconRed",true);
	}

	/**
	*充值面板获取列表数据源
	**/
	__proto.getChongZhiList=function(){
		if(this._chongzhiList==null){
			this._chongzhiDic={};
			this._chongzhiList=[];
			var arr=this._chargeCof.objectDataArray;
			for (var i=0;i < arr.length;i++){
				var cfg=arr[i];
				var vo=new ChongZhiVO(cfg);
				if(cfg.pos){
					this._chongzhiList.push(vo);
				}
				this._chongzhiDic[vo.id]=vo;
			}
			this._chongzhiList.sort(this.compare);
		}
		return this._chongzhiList;
	}

	__proto.getChongZhiVo=function(productId){
		if(this._chongzhiDic==null){
			this.getChongZhiList();
		};
		var vo=this._chongzhiDic[productId];
		return vo;
	}

	__proto.getRmbByID=function(productId){
		if(this._chongzhiDic==null){
			this.getChongZhiList();
		};
		var vo=this._chongzhiDic[productId];
		if(!vo)return 0;
		return vo.getRmb();
	}

	__proto.compare=function(voA,voB){
		if(voA.cfgItem.pos > voB.cfgItem.pos){
			return 1;
		}
		else{
			return-1;
		}
	}

	/**注册活动开关*/
	__proto.registAct=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["directBuyGiftIcon"]);
		var directBuy=Handler.create(this,this.openDirectBuy,null,false);
		NewActiveManager.ins.regActOpenHandler(88,directBuy);
		NewActiveManager.ins.regActEndHandler(88,Handler.create(this,this.closeAct,[88],false));
		ActManager.ins.regist("RechargeHall","directBuyGift",88,"Recharge");
	}

	__proto.openDirectBuy=function(){
		Mgr.directBuyGiftA.c_getInfo();
		Mgr.weekBuyGiftA.c_getInfo(1);
		Mgr.weekBuyGiftA.c_getInfo(2);
		EventCenter.instance.event("ACTIVE_TOGGLE",["directBuyGiftIcon",false]);
	}

	__proto.closeAct=function(actId){
		if(actId==88){
			this._red.hideAll("directBuyGift");
			this._red.hideAll("directBuyGiftIcon");
			EventCenter.instance.event("ACTIVE_TOGGLE",["directBuyGift"]);
			EventCenter.instance.event("ACTIVE_TOGGLE",["directBuyGiftIcon"]);
		}
	}

	__proto.init=function(){
		this.fanghuanData=new DataContainer();
		var cfg=CfgManager.getTableCfg("DanBiFanHuan");
		var ary=cfg.objectDataArray;
		var len=ary.length;
		for (var i=0;i < len;i++){
			var ele=new DataElement(ary[i]);
			this.fanghuanData.addElement(i,ele);
		}
	}

	__proto.getDanBiList=function(){
		return this.fanghuanData.array;
	}

	__proto.getDbData=function(flag,targetValue){
		var obj=this.fanghuanData.where("flag",flag,"targetValue").where("targetValue",targetValue,"targetValue").getElement(targetValue);
		if(obj){
			var cof=this._chargeCof.getItemByField("huodongId",obj.getCfgData().id);
		}
		return cof;
	}

	__proto.getRewardShow=function(flag,targetValue){
		var obj=this.fanghuanData.where("flag",flag,"targetValue").where("targetValue",targetValue,"targetValue").getElement(targetValue);
		return obj.getCfgData().rewardshow;
	}

	__proto.compareByHuodongId=function(ele1,ele2){
		return ele1.getCfgData().huodongId-ele2.getCfgData().huodongId;
	}

	/**直购礼包是否开启*/
	__getset(0,__proto,'ifOpenDirectBuyGift',function(){
		return NewActiveManager.ins.checkIsOpen(88);
	});

	return ChargeMgr;
})()


/**
*vip配置表管理
*2019-12-28
*@auther gfr
*/
//class com.xq.modules.vip.VipCfgMgr
var VipCfgMgr=(function(){
	function VipCfgMgr(){
		this.vipPass=0;
		/**最大svip等级*/
		this.maxSvipLv=0;
		/**最大vip等级*/
		this.maxVipLv=0;
		/**1元兑换元宝数量*/
		this.rmbRatio=0;
		/**打开面板类型 0按钮 1是其他*/
		this.openType=1;
		/**vipModel*/
		this._model=null;
		/**rolevo*/
		this.rInfo=null;
		this._red=null;
		this._model=Model.vip;
		this.rInfo=NetMgr.ins().roleVO;
		this.registRed();
		this.vipPass=parseInt(Mgr.cfgMgr.getValueByType(221));
		this.maxSvipLv=parseInt(Mgr.cfgMgr.getValueByType(157));
		this.maxVipLv=parseInt(Mgr.cfgMgr.getValueByType(184));
		this.rmbRatio=parseInt(Mgr.cfgMgr.getValueByType(32));
		EventCenter.instance.on("VIPLEVEL_CHANGE",this,this.updateSvipLvRed);
	}

	__class(VipCfgMgr,'com.xq.modules.vip.VipCfgMgr');
	var __proto=VipCfgMgr.prototype;
	/**更新vip和svip数据*/
	__proto.updateVipData=function(msg){
		this._model.vipData=msg;
		NetMgr.ins().roleVO.normalVipLevel=msg.normalVipLevel;
		EventCenter.instance.event("NORMAL_VIP_CHANGE");
		this.updateSvipDailyRed();
		this.updateSvipLvRed();
		this.updateVipLvRed();
		EventCenter.instance.event("VIPPULL_VIEW");
		Laya.timer.once(1000,this,this.updataVipTitle,[msg.normalVipLevel+1]);
		Mgr.guide.checkMul(true);
	}

	/**更新svip奖励状态*/
	__proto.updateSvipReward=function(msg){
		var lv=msg.needVipLevel;
		this._model.vipData.stateReward.push(lv);
		this.showReward(lv);
		this.updateSvipLvRed();
		EventCenter.instance.event("RECEIVE_OK");
	}

	/**更新vip奖励状态*/
	__proto.updateVipReward=function(msg){
		this._model.vipData.normalVipRewards.push(msg.needVipLevel);
		this.updateVipLvRed();
		EventCenter.instance.event("NORMAL_RECEIVE_OK",msg);
	}

	/**更新svip每日奖励*/
	__proto.updateSvipDailyReward=function(msg){
		this._model.vipData.dayRewardState=true;
		this.updateSvipDailyRed();
		EventCenter.instance.event("SVIP_DAILY_REWARD");
	}

	/**关卡vip改变*/
	__proto.updateNormalVipData=function(msg){
		if(!this._model.vipData)return;
		this._model.vipData.normalVipLevel=msg.normalVipLevel;
		this.updataVipTitle(msg.normalVipLevel);
		NetMgr.ins().roleVO.normalVipLevel=msg.normalVipLevel;
		this.updateVipLvRed();
		EventCenter.instance.event("NORMAL_VIP_CHANGE",[true]);
	}

	/**更新Vip称号（还有几关获得vip几）*/
	__proto.updataVipTitle=function(nextLv){
		var pl=Game.getInstance().player;
		if(!pl || !Mgr.gqMgr.gqInfo){
			return;
		}
		if(Mgr.kaiFuHDMgr.progress !=0){
			if(pl.vipTitle){
				pl.setVipTitle(0,0);
			}
			return;
		};
		var nextInfo=Mgr.vip.getNormalVipByLv(nextLv);
		if(nextInfo){
			if(nextInfo.lv==1)return;
			var difGuanQia=parseInt(nextInfo.condition)-(Mgr.gqMgr.gqInfo.nextLevel-1);
			if(difGuanQia < 0){
				return;
			}
			pl.setVipTitle(difGuanQia,parseInt(nextInfo.lv));
		}
		else{
			if(Mgr.gqMgr.gqInfo.nextLevel-1 > this.vipPass){
				if(pl.vipTitle){
					pl.setVipTitle(0,0);
				}
			}
			else{
				pl.setVipTitle(0,-1);
			}
		}
	}

	/**刷新Vip称号*/
	__proto.refreshVipTitle=function(){
		if(this._model.vipData){
			this.updataVipTitle(this._model.vipData.normalVipLevel+1);
		}
	}

	/**展示获取的svip奖励*/
	__proto.showReward=function(vipLevel){
		var ele=Mgr.vipcfgMgr.getDataBySvipLv(vipLevel);
		if(!ele)return;
		var cof=ele.getCfgData();
		var aniPath;
		var rewardCfg={};
		if(cof && cof.showres){
			var showres_amt=cof.showres.split(";");
			if(showres_amt.length > 1){
				var string="";
				var myJob=NetMgr.ins().roleVO.job;
				string=myJob=="A"?showres_amt[0]:showres_amt[1];
				aniPath=PathDefine.OUT_RES+string+".amt";
				rewardCfg["name"]=PathDefine.VIP+vipLevel+"_"+myJob+".png";
			}
			else{
				aniPath=PathDefine.OUT_RES+cof.showres+".amt"
				rewardCfg["name"]=PathDefine.VIP+vipLevel+".png";
			}
		}
		rewardCfg["resPath"]=aniPath;
		var scale=parseFloat(cof.zoom)*0.8;
		rewardCfg["scale"]=scale;
		var rewardShow=UIMgrR.openIView(com.xq.view.modules.fourteenluxurygifts.IRewardShow,2);
		rewardShow.dataSource=rewardCfg;
	}

	__proto.getDataBySvipLv=function(lv){
		return this._model.svipDc.getElement(lv);
	}

	/**获取材料本次数*/
	__proto.getCLCount=function(lv){
		(lv===void 0)&& (lv=-1);
		if(lv >=0){
			var ele=this._model.svipDc.getElement(lv);
			if(ele){
				return ele.getCfgData().cailiao;
			}
		};
		var mySvipLv=this.rInfo.vipLevel;
		ele=this._model.svipDc.getElement(lv);
		if(ele){
			return ele.getCfgData().cailiao;
		}
		return 0;
	}

	/**svip 等级礼包是否领取*/
	__proto.ifReceived=function(lv){
		var arr=this._model.vipData.stateReward;
		return arr.indexOf(lv)!=-1;
	}

	/**vip 等级礼包是否领取*/
	__proto.ifReceivedVip=function(lv){
		var arr=this._model.vipData.normalVipRewards;
		return arr.indexOf(lv)!=-1;
	}

	/**获取默认选中SvipLv*/
	__proto.getSvipDefualtLv=function(){
		var myLv=this._model.vipData.vipLevel;
		for(var lv=1;lv<=myLv;lv++){
			if(!this.ifReceived(lv)){
				return lv;
			}
		}
		if(myLv<this.maxSvipLv){
			return myLv+1;
		}
		else{
			return myLv;
		}
	}

	/**当前选中前后是否又可领取的奖励*/
	__proto.getSvipOtherRed=function(lv,ifLast){
		var myLv=this._model.vipData.vipLevel;
		if(ifLast){
			for(var i=1;i<lv;i++){
				if(!this.ifReceived(i)&&i<myLv){
					return true;
				}
			}
			return false;
		}
		else{
			for(i=lv+1;i<=myLv;i++){
				if(!this.ifReceived(i)){
					return true;
				}
			}
			return false;
		}
	}

	/**获取默认选中vipLv*/
	__proto.getVipDefualtLv=function(){
		var myLv=this._model.vipData.normalVipLevel;
		for(var lv=1;lv<=myLv;lv++){
			if(!this.ifReceivedVip(lv)){
				return lv;
			}
		}
		if(myLv<this.maxVipLv){
			return myLv+1;
		}
		else{
			return myLv;
		}
	}

	/**当前选中前后是否又可领取的奖励*/
	__proto.getVipOtherRed=function(lv,ifLast){
		var myLv=this._model.vipData.normalVipLevel;
		if(ifLast){
			for(var i=1;i<lv;i++){
				if(!this.ifReceivedVip(i)&&i<myLv){
					return true;
				}
			}
			return false;
		}
		else{
			for(i=lv+1;i<=myLv;i++){
				if(!this.ifReceivedVip(i)){
					return true;
				}
			}
			return false;
		}
	}

	//=================红点相关=================
	__proto.registRed=function(){
		this._red=Mgr.red;
		this._red.regist("vip_main","vip",true,RedTypeEnum.VipMainRed);
		this._red.regist("vip_main","normalVip",true,RedTypeEnum.VipMainRed);
	}

	/**刷新Svip等级礼包红点*/
	__proto.updateSvipLvRed=function(){
		var data=this._model.vipData;
		if(!data)return;
		var myLv=this.rInfo.vipLevel;
		for(var i=1;i<=myLv;i++){
			if(!this.ifReceived(i)){
				this._red.showRedPoint("vip","vip"+i,RedTypeEnum.VipRed);
			}
			else{
				this._red.hideRedPoint("vip","vip"+i,RedTypeEnum.VipRed);
			}
		}
	}

	/**刷新vip等级礼包红点*/
	__proto.updateVipLvRed=function(){
		var data=this._model.vipData;
		if(!data)return;
		var myLv=data.normalVipLevel;
		for(var i=1;i<=myLv;i++){
			if(!this.ifReceivedVip(i)){
				this._red.showRedPoint("normalVip","normal_vip"+i,RedTypeEnum.NormalVipRed);
			}
			else{
				this._red.hideRedPoint("normalVip","normal_vip"+i,RedTypeEnum.NormalVipRed);
			}
		}
	}

	/**刷新svip每日礼包红点*/
	__proto.updateSvipDailyRed=function(){
		var myLv=this._model.vipData.vipLevel;
		var ifget=this._model.vipData.dayRewardState;
		if(myLv>0&&!ifget){
			this._red.showRedPoint("vip","SvipMeiRi",RedTypeEnum.VipRed);
		}
		else{
			this._red.hideRedPoint("vip","SvipMeiRi",RedTypeEnum.VipRed);
		}
	}

	return VipCfgMgr;
})()


