/**
*
*@author yuhaitao
*@date 2020-10-22 下午2:47:02
*/
//class com.xq.modules.waixianActive.WaiXianActiveMgr
var WaiXianActiveMgr=(function(){
	function WaiXianActiveMgr(){
		/**当前活动 145 为兵符活动 146 为开服豪礼*/
		this._curType=0;
		/**兵符活动*/
		this.bingFuData=null;
		this.bingFuCfg=null;
		this.bingFuRewardCfg=null;
		this.bingFuRewardArr=null;
		/**开服豪礼*/
		this.kaiFuHaoLiData=null;
		this.kaiFuHaoLiCfg=null;
		this.kaiFuRewardCfg=null;
		this.kaiFuRewardArr=null;
		this.waiXianSerDic=null;
		this.openSelectIdDic=null;
		this.red=null;
		this.bingFuCfg=CfgManager.getTableCfg("bingfuTask");
		this.bingFuRewardCfg=CfgManager.getTableCfg("bingfuReward");
		this.bingFuRewardArr=this.bingFuRewardCfg.objectDataArray;
		this.kaiFuHaoLiCfg=CfgManager.getTableCfg("kaifuTask");
		this.kaiFuRewardCfg=CfgManager.getTableCfg("kaifuReward");
		this.kaiFuRewardArr=this.kaiFuRewardCfg.objectDataArray;
		this.waiXianSerDic=new Dictionary();
		this.openSelectIdDic=new Dictionary();
		this.red=Mgr.red;
		this.red.regist("BingFuActive",null,true);
		this.red.regist("KaiFuActive",null,true);
	}

	__class(WaiXianActiveMgr,'com.xq.modules.waixianActive.WaiXianActiveMgr');
	var __proto=WaiXianActiveMgr.prototype;
	__proto.regActive=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["BingFuActive"]);
		var hand=Handler.create(this,this.openAct,[154],false);
		NewActiveManager.ins.regActOpenHandler(154,hand);
		NewActiveManager.ins.regActEndHandler(154,Handler.create(this,this.closeAct,[154],false));
		EventCenter.instance.event("ACTIVE_TOGGLE",["KaiFuActive"]);
		hand=Handler.create(this,this.openAct,[155],false);
		NewActiveManager.ins.regActOpenHandler(155,hand);
		NewActiveManager.ins.regActEndHandler(155,Handler.create(this,this.closeAct,[155],false));
	}

	__proto.openAct=function(activityId){
		var openDay=CommonUtil.openServerDay;
		if(activityId==154){
			EventCenter.instance.event("ACTIVE_TOGGLE",["BingFuActive",false]);
			Mgr.waiXianActiveAction.sendWaiXianInfo(activityId,openDay);
			}else{
			EventCenter.instance.event("ACTIVE_TOGGLE",["KaiFuActive",false]);
			Mgr.waiXianActiveAction.sendWaiXianInfo(activityId,openDay);
		}
	}

	__proto.closeAct=function(activityId){
		if(activityId==154){
			EventCenter.instance.event("ACTIVE_TOGGLE",["BingFuActive"]);
			}else{
			EventCenter.instance.event("ACTIVE_TOGGLE",["KaiFuActive"]);
		}
	}

	__proto.setWaiXianSerDic=function(msg){
		if(!this.waiXianSerDic.get(msg.activityId)){
			var dic=new Dictionary();
			this.waiXianSerDic.set(msg.activityId,dic);
		};
		var len=msg.tasks.length;
		dic=this.waiXianSerDic.get(msg.activityId);
		for (var i=0;i < len;i++){
			var taskMsg=msg.tasks[i];
			dic.set(taskMsg.taskId,taskMsg);
		}
		if(this.refreshWaiXianRed(msg.activityId)){
			EventCenter.instance.event("ACTIVE_TOGGLE",[this.getFuncId(msg.activityId)]);
			}else{
			EventCenter.instance.event("refresh_waixian_info");
		}
	}

	__proto.getOneDayTaskArr=function(activityId,taskId){
		if(!this.waiXianSerDic.get(activityId))
			return null;
		return this.waiXianSerDic.get(activityId).get(taskId);
	}

	__proto.getSerTaskInfoById=function(taskId,id){
		var bingFuTaskMsg=this.getOneDayTaskArr(this.curType,taskId);
		if(!bingFuTaskMsg){
			return 0;
		};
		var taskArr=bingFuTaskMsg.tasks;
		var len=taskArr.length;
		for (var i=0;i < len;i++){
			var taskMsg=taskArr[i];
			if(taskMsg.id==id){
				return taskMsg.progress;
			}
		}
		return 0;
	}

	__proto.refreshWaiXianRed=function(activityId){
		var isGetAll=true;
		var tempDic=this.waiXianSerDic.get(activityId);
		if(!tempDic){
			return true;
		};
		var taskArr=tempDic.keys;
		var len=taskArr.length;
		var funcId=this.getFuncId(activityId);
		var defaultSelect=-1;
		var redSelect=-1;
		this.openSelectIdDic.set(activityId,0);
		for(var i=0;i < len;i++){
			var state=this.getCurDayRewardState(activityId,parseInt(taskArr[i]));
			if(state==1){
				this.red.showRedPoint(funcId,activityId+"_"+taskArr[i],"WaiXianActiveRed");
				if(redSelect < 0){
					redSelect=i;
					this.openSelectIdDic.set(activityId,i);
				}
				}else{
				this.red.hideRedPoint(funcId,activityId+"_"+taskArr[i],"WaiXianActiveRed");
			}
			if(state==0 && defaultSelect==-1){
				defaultSelect=i;
			}
			if(state !=2){
				isGetAll=false;
			}
		}
		if(redSelect < 0){
			this.openSelectIdDic.set(activityId,defaultSelect);
		}
		return isGetAll;
	}

	/**获取默认选中页签*/
	__proto.getSeleceId=function(activityId){
		return this.openSelectIdDic.get(activityId);
	}

	__proto.getWaiXianData=function(activityId){
		switch(activityId){
			case 154:{
					return this.getBingFuData;
				}
			case 155:{
					return this.getKaiFuHaoLiData;
				}
			}
		return null;
	}

	/**0 未领取 1可领取 2 已领取 */
	__proto.getCurDayRewardState=function(activityId,taskId){
		var taskArr=this.getCurTaskCondition(activityId,taskId);
		var len=taskArr.length;
		var serTask=this.getOneDayTaskArr(activityId,taskId);
		if(!serTask)return 0;
		if(serTask.isGetReward){
			return 2;
		};
		var isCanGet=true;
		for (var i=0;i < len;i++){
			var taskMsg=serTask.tasks[i];
			if(taskArr[i].getCfgData().type=="1"){
				if(taskMsg.progress >=parseInt(taskArr[i].getCfgData().target)){
					return 1;
				}
				}else{
				if(taskMsg.progress < parseInt(taskArr[i].getCfgData().target)){
					isCanGet=false;
				}
			}
		}
		if(isCanGet){
			return 1;
		}
		return 0;
	}

	__proto.getCurTaskCondition=function(activityId,taskId){
		var taskArr=this.getWaiXianData(activityId).where("taskId",taskId,"type").array;
		return taskArr;
	}

	__proto.getShowRewardArr=function(){
		switch(this.curType){
			case 154:{
					return this.bingFuRewardArr;
				}
			case 155:{
					return this.kaiFuRewardArr;
				}
			}
		return null;
	}

	__proto.getFuncId=function(activityId){
		switch(activityId){
			case 154:{
					return "BingFuActive";
				}
			case 155:{
					return "KaiFuActive";
				}
			}
		return null;
	}

	/**领取外显类奖励后 刷新数据及红点 */
	__proto.getReward=function(activityId,taskId){
		var taskMsg=this.getOneDayTaskArr(activityId,taskId);
		taskMsg.isGetReward=true;
		if(this.refreshWaiXianRed(activityId)){
			EventCenter.instance.event("ACTIVE_TOGGLE",[this.getFuncId(activityId)]);
		}
	}

	__getset(0,__proto,'getBingFuData',function(){
		if(!this.bingFuData){
			this.bingFuData=new DataContainer();
			var cfgArr=this.bingFuCfg.objectDataArray;
			var len=cfgArr.length;
			for (var i=0;i < len;i++){
				var cfg=cfgArr[i];
				var ele=new DataElement(cfg);
				this.bingFuData.addElement(cfg.id,ele);
			}
		}
		return this.bingFuData;
	});

	__getset(0,__proto,'getKaiFuHaoLiData',function(){
		if(!this.kaiFuHaoLiData){
			this.kaiFuHaoLiData=new DataContainer();
			var cfgArr=this.kaiFuHaoLiCfg.objectDataArray;
			var len=cfgArr.length;
			for (var i=0;i < len;i++){
				var cfg=cfgArr[i];
				var ele=new DataElement(cfg);
				this.kaiFuHaoLiData.addElement(cfg.id,ele);
			}
		}
		return this.kaiFuHaoLiData;
	});

	__getset(0,__proto,'curType',function(){
		return this._curType;
		},function(type){
		this._curType=type;
	});

	return WaiXianActiveMgr;
})()


