//class com.xq.modules.wulinfuben.WuLinFuBenMgr
var WuLinFuBenMgr=(function(){
	function WuLinFuBenMgr(){
		this.curFbType=0;
		this.vicReward=null;
		/**记录是否是自己推出的*/
		this.ifQuit=false;
		this._model=null;
		this._copyView=null;
		this._curTeamType=null;
		this.quitAlert=null;
		this._model=new WuLinFuBenModel();
		this.registTeam();
		CopyTipMgr.ins.regisCopyTip(2037,Handler.create(this,this.closeTips,null,false));
	}

	__class(WuLinFuBenMgr,'com.xq.modules.wulinfuben.WuLinFuBenMgr');
	var __proto=WuLinFuBenMgr.prototype;
	/**同步武林副本信息*/
	__proto.updateInfo=function(msg){
		this._model.updateInfo(msg);
		EventCenter.instance.event("updateInfo");
	}

	/**同步战队模式副本推荐人*/
	__proto.updateRecommend=function(msg){
		this._model.updateRecommend(msg);
		EventCenter.instance.event("updateRecommendInfo");
	}

	/**同步巅峰榜单*/
	__proto.updateDianFeng=function(msg){
		this._model.updateDianFengRank(msg);
		EventCenter.instance.event("updateDianFengRankInfo");
	}

	/**同步最佳战队榜单*/
	__proto.updateZhanDui=function(msg){
		this._model.updateZhanDuiRank(msg);
		EventCenter.instance.event("updateZhanDuiRank");
	}

	/**同步副本内信息*/
	__proto.updateCopyInfo=function(msg){
		this._model.updateLayer(msg);
		this._model.addReward(msg.htype,msg.layer);
		if(!this._copyView||!this._copyView.isPopup){
			this._copyView=UIMgrR.openIView(com.xq.view.modules.wulinfuben.IWuLinFuBenCopyView,2);
		}
		EventCenter.instance.event("updateCopyInfo");
		EventCenter.instance.event("UpdateLayerFigEvent",msg.layer);
	}

	/**结算奖励*/
	__proto.updateReward=function(msg){
		if(msg.layer>0){
			this.vicReward=msg.rewards;
			UIMgrR.openIView(com.xq.view.modules.wulinfuben.IWuLinFuBenVictory,2);
		}
		else{
			UIMgrR.openIView(com.xq.view.modules.wulinfuben.IWuLinFuBenFail,2);
		}
	}

	//=============组队相关==============
	__proto.registTeam=function(){
		Mgr.teamMgr.registTeamType(TeamEnum.YuanshenFuBenPerson,true,false,false,true);
		Mgr.teamMgr.registTeamType(TeamEnum.YuanshenFuBenZhanDui,true,true,true,false);
	}

	/**获取 副本后台数据*/
	__proto.getInfo=function(fbType){
		return this._model.getFuBenInfo(fbType);
	}

	/**获取 副本巅峰榜dataelement数组（后端排行榜信息存在ele中）*/
	__proto.getDianFengEles=function(fbType){
		return this._model.getDianFengRankEles(fbType);
	}

	/**获取 副本战队榜dataelement数组（后端排行榜信息存在ele中）*/
	__proto.getZhanDuiEles=function(fbType){
		return this._model.getZhanDuiRankEles(fbType);
	}

	/**展示大奖奖励*/
	__proto.getShowRewards=function(fbType){
		var ele=this._model.getConstEle(fbType);
		if(!ele)return [];
		var cof=ele.getCfgData();
		return cof.reward;
	}

	/**副本限定时长*/
	__proto.getLimitTime=function(fbType){
		var ele=this._model.getConstEle(fbType);
		if(!ele)return 0;
		var cof=ele.getCfgData();
		return cof.time;
	}

	/**当前层数*/
	__proto.getCurLayer=function(fbType){
		return this._model.getCurLayer(fbType);
	}

	/**个人需战队模式层数达到X层才可以领奖励*/
	__proto.getZDRewardLimit=function(fbType){
		var ele=this._model.getConstEle(fbType);
		if(!ele)return 0;
		var cof=ele.getCfgData();
		return cof.layer;
	}

	/**获取战队模式推荐*/
	__proto.getRecommend=function(fbType){
		var vo=this._model.getRecommend(fbType);
		if(!vo)return [];
		return vo.infos;
	}

	/**获取当前累计奖励*/
	__proto.getCurAllRewards=function(){
		return this._model.getCurAllReward();
	}

	/**清理累计奖励数组*/
	__proto.clearCurAllRewards=function(){
		this._model.clearCurAllReward();
	}

	//===============场景相关==============
	__proto.initFightVo=function(fightVo){
		fightVo.hideAry=[1,2,3,4];
		fightVo.aniType=1;
		fightVo.closeFun=Handler.create(this,this.exit,null,false);
		fightVo.curFloor=1;
		var time=this.getLimitTime(this.curFbType)
		fightVo.remainTime=time*60*1000;
	}

	/**退出副本**/
	__proto.exit=function(timeOver){
		if(!timeOver){
			this.quitAlert=AlertUtil.show("退出将视为挑战结束,是否退出？","提示",Handler.create(this,this.closeHandler),true);
		}
		else{
			Mgr.teamAct.reqExitCopy(Mgr.teamMgr.teamType,this.getCurLayer(this.curFbType)>1);
			this.closeTips();
		}
	}

	__proto.closeHandler=function(type){
		if(type=="OK"){
			Mgr.teamAct.reqExitCopy(Mgr.teamMgr.teamType,this.getCurLayer(this.curFbType)>1);
			this.ifQuit=true;
			this.closeTips();
		}
	}

	__proto.closeTips=function(){
		if(this._copyView&&this._copyView.isPopup){
			this._copyView.close();
			this._copyView=null;
		}
		if(this.quitAlert&&this.quitAlert.isPopup){
			this.quitAlert.close();
			this.quitAlert=null;
		}
	}

	/**元神副本接受世界邀请*/
	__proto.sendRespInvition=function(id){
		if(!Mgr.guide.isOpen("YuanShenFuBen")){
			Mgr.prompt.optionPrompt("尚未开启元神副本");
			return;
		}
		if(Mgr.teamMgr.checkInTeam(TeamEnum.YuanshenFuBenPerson,id)){
			Mgr.prompt.optionPrompt("你已在这个队伍中");
			return;
		}
		Mgr.teamAct.reqAcceptInvite(TeamEnum.YuanshenFuBenPerson,id,Handler.create(this,this.onRespInVition,null,false));
	}

	__proto.onRespInVition=function(teamType){
		if(teamType==TeamEnum.YuanshenFuBenPerson){
			UIMgrR.openSecIView(com.xq.view.modules.singleCopy.ICopyFrameView,1,1,3);
		}
	}

	return WuLinFuBenMgr;
})()


