//class com.xq.modules.xiianyuanjingji.XianYuanJingJiMgr
var XianYuanJingJiMgr=(function(){
	function XianYuanJingJiMgr(){
		this._red=null;
		this._model=null;
		this._robatDic=null;
		this.copyInfo=null;
		this._red=Mgr.red;
		this._model=Model.xianyuanjingji;
		this._robatDic=new Dictionary();
		this._red.regist("danrenjingji","xianyuanjingji",false,RedTypeEnum.JingJiRed);
		this.registCopyTip();
	}

	__class(XianYuanJingJiMgr,'com.xq.modules.xiianyuanjingji.XianYuanJingJiMgr');
	var __proto=XianYuanJingJiMgr.prototype;
	__proto.updateXuanYuanJingJiSer=function(msg){
		this._model.xianYuanJingJiSer=msg;
		this.refreshRankRewardRed(msg);
	}

	__proto.refreshRankRewardRed=function(msg){
		var getRewardArr=this.model.xianYuanJingJiData.array;
		var maxRank=msg.myDatas.highGrade;
		var len=getRewardArr.length;
		var ele;
		var ylq=500;
		var wlq=200;
		for (var i=0;i < len;i++){
			ele=getRewardArr[i];
			var id=parseInt(ele.getCfgData().id);
			if(!this.model.isGetById(id)){
				ele.sortIndex=id+wlq;
				}else{
				ele.sortIndex=id+ylq;
			}
			if(maxRank >=id && !this.model.isGetById(id)){
				this._red.showRedPoint("xianyuanjingji",id+"",RedTypeEnum.XianYuanJingJiRed);
				ele.sortIndex=id;
				}else{
				this._red.hideRedPoint("xianyuanjingji",id+"",RedTypeEnum.XianYuanJingJiRed);
			}
		}
		EventCenter.instance.event(XianYuanJingJiEvent.XianYuanJingJiGetReward);
	}

	__proto.getDuanWeiRewardArr=function(){
		return this.model.xianYuanJingJiData.array.sort(this.compare);
	}

	__proto.compare=function(a,b){
		return a.sortIndex-b.sortIndex
	}

	__proto.getDuanWeiCfgById=function(id){
		var ele=this._model.xianYuanJingJiData.getElement(id+"");
		if(ele){
			return ele.getCfgData();
		}
		return null;
	}

	__proto.onChallenge=function(target){
		if(this.model.xianYuanJingJiSer){
			if(!this.model.xianYuanJingJiSer.myDatas.selfDatas.parternerData.roleId){
				Mgr.prompt.optionPrompt("您没有伴侣，无法挑战");
				return;
			}
			Mgr.inoutMap.check(Handler.create(this,this.clickChallenge,[target]));
		}
	}

	__proto.clickChallenge=function(target){
		if(this.getChallengeNum()> 0){
			Mgr.xianYuanJingJiA.sendStartChallenge(target);
			}else{
			Mgr.prompt.optionPrompt("挑战次数不足");
		}
	}

	__proto.getChallengeNum=function(){
		return this._model.chanllengeNum;
	}

	/**刷新挑战对手*/
	__proto.refreshFighter=function(msg){
		this.model.refreshFight(msg);
		EventCenter.instance.event(XianYuanJingJiEvent.XianYuanJingJiRefresh);
	}

	__proto.getDuanWeiReward=function(rewardStr){
		this.model.xianYuanJingJiSer.myDatas.hadGradeReward=rewardStr;
		this.model.setAlreadyGetDic();
		this.refreshRankRewardRed(this.model.xianYuanJingJiSer);
	}

	__proto.addChallenge=function(msg){
		this.model.xianYuanJingJiSer.myDatas.buyCount=msg.buyCount;
		this.model.xianYuanJingJiSer.myDatas.challengeCount=msg.challengeCount;
		this.model.xianYuanJingJiSer.myDatas.cooldown=msg.cooldown;
		EventCenter.instance.event(XianYuanJingJiEvent.XianYuanJingJiChallengeCount);
	}

	/**仙缘竞技信息数据*/
	__proto.initFightVo=function(fightVo){
		fightVo.hideAry=[2,3,4];
		this.copyInfo=UIMgrR.openIView(com.xq.view.modules.pvpcopy.xianyuanjingji.IXianYuanCopyInfo,2);
	}

	__proto.closeTips=function(){
		if(this.copyInfo){
			this.copyInfo.close();
			this.copyInfo=null;
		}
		RobotPlayerMgr.ins.RobotIsEney=false;
	}

	__proto.registCopyTip=function(){
		CopyTipMgr.ins.regisCopyTip(2031,Handler.create(this,this.closePanel,null,false));
	}

	__proto.closePanel=function(){
		this._robatDic.clear();
		this.closeTips();
	}

	__proto.getRewardArr=function(arr){
		var rewardArr=[];
		var len=arr.length;
		var marryReward;
		for (var i=0;i < len;i++){
			marryReward=arr[i];
			rewardArr.push(marryReward.itemId+":"+marryReward.num+":"+marryReward.bind);
		}
		return rewardArr;
	}

	__proto.getMyData=function(){
		var info=this._model.xianYuanJingJiSer;
		if(!info)return null;
		return info.myDatas;
	}

	__getset(0,__proto,'model',function(){
		return this._model;
		},function(value){
		this._model=value;
	});

	__getset(0,__proto,'robatDic',function(){
		return this._robatDic;
		},function(value){
		this._robatDic=value;
	});

	return XianYuanJingJiMgr;
})()


