	__class(XinWuMgr,'com.xq.modules.xinWu.XinWuMgr');
	var __proto=XinWuMgr.prototype;
	/**是否开启信物主界面按钮*/
	__proto.isOpenBtn=function(type){
		if(type==0){
			if(Mgr.guide.isOpen("MarriageXwLingPai")){
				var info=this.mdl.getJianZhengInfo(type);
				if(info && info.isActive){
					var msg=Mgr.xinWu.getLiBao(type);
					if(msg&&msg.state==2){
						EventCenter.instance.event("ACTIVE_TOGGLE",["MarriageXwLingPai"]);
						return;
					}
				}
				if(Mgr.marriageMgr.checkIsMarriage()){
					EventCenter.instance.event("ACTIVE_TOGGLE",["MarriageXwLingPai",false]);
				}
			}
		}
		else{
			if(Mgr.qlbMgr.isBuy && Mgr.guide.isOpen("QiLingBiXwLingPai")){
				var tsg=Mgr.xinWu.getLiBao(1);
				if(tsg&&tsg.state==2){
					EventCenter.instance.event("ACTIVE_TOGGLE",["QiLingBiXwLingPai"]);
					return;
				}
				EventCenter.instance.event("ACTIVE_TOGGLE",["QiLingBiXwLingPai",false]);
			}
		}
	}

	/**令牌红点*/
	__proto.lingpaiRed=function(type){
		if(type==0){
			if(!Mgr.guide.isOpen("marriage"))return;
			if(!Mgr.marriageMgr.checkIsMarriage())return;
		};
		var msg=this.getLiBao(type);
		var fun=this.lbFucObj[type];
		if(msg.state==1){
			this.red.showRedPoint(fun,"LingPaiRed","LingPaiRed");
		}
		else{
			this.red.hideRedPoint(fun,"LingPaiRed","LingPaiRed");
		}
	}

	/**刷新见证红点*/
	__proto.checkJzRed=function(type){
		if(!this.checkOp(type)){
			return
		};
		var info=this.mdl.getJianZhengInfo(type);
		var hasRed=false;
		var fuc=this.jzFucObj[type]
		if(info && info.isActive){
			var num=info.suiPianVal;
			var ary=this.mdl.getJianZhengData(type);
			var l=ary.length;
			for (var i=0;i < l;i++){
				var item=ary[i];
				var cfg=item.getCfgData();
				var msg=item.getValue("msg");
				if(msg){
					if(msg.nextAtrrs.length > 0 && cfg.itemNum <=num){
						item.setValue("XinWuUpRed",true);
						hasRed=true;
					}
					else{
						item.setValue("XinWuUpRed",false);
					}
				}
				else{
					if(cfg.randomNum <=num){
						item.setValue("XinWuSjJhRed",true);
						hasRed=true;
					}
					else{
						item.setValue("XinWuSjJhRed",false);
					}
					if(cfg.activeNum <=num){
						item.setValue("XinWuZjJhRed",true);
						hasRed=true;
					}
					else{
						item.setValue("XinWuZjJhRed",false);
					}
				}
				if(hasRed){
					item.setValue("JianZhengRed",true);
				}
			}
		};
		var bo=this.checkTaskRed(type);
		if(hasRed || bo){
			this.red.showRedPoint(fuc,"XinWuRed","XinWuRed");
		}
		else{
			this.red.hideRedPoint(fuc,"XinWuRed","XinWuRed");
		}
	}

	__proto.checkOp=function(type){
		if(type==0){
			if(!Mgr.guide.isOpen("marriage"))return false;
			if(!Mgr.marriageMgr.checkIsMarriage())return false;
			if(Mgr.guide.isOpen("MarriageXwLingPai")){
				return true;
			}
		}
		else{
			if(Mgr.qlbMgr.isBuy && Mgr.guide.isOpen("QiLingBiXwLingPai")){
				return true
			}
		}
		return false;
	}

	__proto.checkTaskRed=function(type){
		var fuc=this.jzFucObj[type];
		var ary=this.mdl.getTaskData(type);
		var l=ary.length;
		var rwRed=false;
		for (var i=0;i < l;i++){
			var item=ary[i];
			var tsg=item.getValue("msg");
			if(tsg && tsg.taskState==1){
				rwRed=true;
				break ;
			}
		}
		if(rwRed){
			this.red.showRedPoint(fuc,"XinWuTaskRed");
		}
		else{
			this.red.hideRedPoint(fuc,"XinWuTaskRed");
		}
		return rwRed;
	}

	/**获取可以操作的见证*/
	__proto.getEuJianZheng=function(type){
		var info=this.mdl.getJianZhengInfo(type);
		if(!info){
			return 1;
		};
		var num=info.suiPianVal;
		var ary=this.mdl.getJianZhengData(type);
		var l=ary.length;
		var bigAry=[];
		var smallAry=[];
		var minlv=999;
		var minId=1;
		for (var i=0;i < l;i++){
			var item=ary[i];
			var cfg=item.getCfgData();
			var msg=item.getValue("msg");
			if(msg && msg.nextAtrrs.length > 0){
				if(minlv > msg.currLv){
					minId=msg.id;
					minlv=msg.currLv;
				}
				if(cfg.itemNum <=num){
					return cfg.Id;
				}
			}
			else{
				if(i > 10){
					bigAry.push(cfg.Id);
				}
				else{
					smallAry.push(cfg.Id);
				}
			}
		}
		if(bigAry.length > 0){
			var rand=Math.floor(Math.random()*bigAry.length);
			return bigAry[rand];
		}
		else if(smallAry.length > 0){
			rand=Math.floor(Math.random()*smallAry.length);
			return smallAry[rand];
		}
		else{
			return minId;
		}
	}

	/**礼包*/
	__proto.updateLibao=function(type,msg){
		this.libaoMsg[type]=msg;
		this.lingpaiRed(type);
		this.isOpenBtn(type);
		EventCenter.instance.event("LibaoUpdateXW");
	}

	__proto.getLiBao=function(type){
		return this.libaoMsg[type];
	}

	/**打开令牌界面*/
	__proto.openLingPai=function(){
		if(this.curType==0){
			UIMgrR.openIView(com.xq.view.modules.xinwu.jianZhengTab.IMarriageLingPai,2);
		}
		else{
			UIMgrR.openIView(com.xq.view.modules.xinwu.jianZhengTab.IQiLingBiLingPai,2);
		}
	}

	/**打开任务面包*/
	__proto.openTask=function(){
		if(this.curType==0){
			UIMgrR.openIView(com.xq.view.modules.xinwu.jianZhengTab.IMarriageJzTask,2);
		}
		else{
			UIMgrR.openIView(com.xq.view.modules.xinwu.jianZhengTab.IQiLingBiJzTask,2);
		}
	}

	/**打开激活见证提示界面*/
	__proto.openActiveJz=function(){
		if(this.randData){
			if(this.randData.isSuc){
				var vv=UIMgrR.openIView(com.xq.view.modules.xinwu.jianZhengTab.IJianZhengSucTip,2);
				vv.dataSource=[this.randData.type,this.randData.id];
			}
			else{
				if(!this.markAry[this.curType]){
					var viw=UIMgrR.openIView(com.xq.view.modules.xinwu.jianZhengTab.IJianZhengReturn,2);
					viw.dataSource=[this.randData.type,this.randData.num];
				}
			}
		}
	}

