var ChongBangXunBaoMgr=(function(){
	function ChongBangXunBaoMgr(){
		/**冲榜寻宝记录 是否换行*/
		this.isHtml=false;
		/**倒计时*/
		this.endTime=NaN;
		/**是否是永久活动，是则不需要显示活动倒计时*/
		this.isActivity=false;
		this.cBxbCfg=null;
		this.cBxbBaoKuCfg=null;
		this.cbXunbaoCfgVo=null;
		this.cBxbBaoKu=null;
		/**积分大奖*/
		this.extrareward=null;
		/**积分值*/
		this.jifenData=null;
		/**抽奖奖励*/
		this.rollRewards=null;
		/**后端给的 玉树寻宝类型*/
		this.xunbaoType=0;
		/**积分*/
		this.jifen=0;
		/**个人 全服 抽奖记录*/
		this.chouJiangJiLu=null;
		/**个人 全服 抽奖记录类型*/
		this.chouJiangJiLuType=0;
		/**领取后的奖励值*/
		this.zhouReward=null;
		/**当次抽奖奖励道具*/
		this.dangCiItem=null;
		/**当次抽奖奖励id 光效停止位置*/
		this.dangCiId=0;
		this.red=null;
		this.cBxbCfg=CfgManager.getTableCfg("chongbangduobaoconfig");
		this.cBxbBaoKuCfg=CfgManager.getTableCfg("chongbangduobaoku");
		this.red=Mgr.red;
		this.red.regist("quanminchongbang","ChongBangXunBao",true,RedTypeEnum.QuanMinChongBangRed);
	}

	__class(ChongBangXunBaoMgr,'com.xq.modules.xunbao.chongBangXunBao.ChongBangXunBaoMgr');
	var __proto=ChongBangXunBaoMgr.prototype;
	__proto.regActive=function(){
		ActManager.ins.regist("quanminchongbang","ChongBangXunBao",44,"ChongBanActEvent");
		var opAct=Mgr.mgxbProMgr;
		var hand=Handler.create(opAct,opAct.sendBackCs,[105],false)
		NewActiveManager.ins.regActOpenHandler(44,hand);
		NewActiveManager.ins.regActEndHandler(44,Handler.create(this,this.closeAct,null,false));
	}

	__proto.closeAct=function(){}
	//EventCenter.instance.on(GameEvent.ACTIVE_TOGGLE,this,onActiveToggle);
	__proto.getExtrareward=function(id){
		this.extrareward=[];
		this.jifenData=[];
		var arrCfg=this.cBxbCfg.getItemsByField("id",id);
		this.cbXunbaoCfgVo=arrCfg[0];
		if(this.cbXunbaoCfgVo.extrareward){
			var arr=this.cbXunbaoCfgVo.extrareward.split("|")
			var len=arr.length;
			for (var i=0;i < len;i++){
				if(arr[i]){
					var a=arr[i].split("_");
					this.jifenData.push(a[0]);
					this.extrareward.push(a[1]);
				}
			}
		}
	}

	__proto.getCbXunBaoKuReward=function(id){
		this.cBxbBaoKu=this.cBxbBaoKuCfg.getItemsByField("configid",id);
	}

	__proto.activitTime=function(){
		var opAct=NewActiveManager.ins.getActiveVerDic(44);
		if(opAct){
			this.endTime=opAct.endTime;
			this.isActivity=opAct.isForeverActivity;
		}
	}

	/**冲榜获得初始数据*/
	__proto.setChongBanXunBaoInfo=function(obj){
		this.zhouReward=[];
		this.activitTime();
		this.getExtrareward(obj.configId);
		this.getCbXunBaoKuReward(obj.configId);
		if(obj.rewardHistory){
			var arr=obj.rewardHistory.split(";");
			for (var i=0;i < arr.length;i++){
				if(arr[i])this.zhouReward.push(arr[i]);
			}
		}
		this.xunbaoType=obj.type;
		this.jifen=obj.yiChouCiShu;
		this.boxRed();
		EventCenter.instance.event("chongbaog_update_info");
	}

	/**冲榜寻宝获得数据*/
	__proto.setJiangLi=function(obj){
		this.rollRewards=obj.RollRewards;
		this.jifen=obj.yiChouCiShu;
		if(this.rollRewards.length > 1){
			var ysrv=UIMgrR.openIView(com.xq.view.modules.taiYu.IYuShuRewardView,2);
			var object={};
			object["rollRewards"]=this.rollRewards;
			object["type"]=this.xunbaoType;
			object["cfgVo"]=this.cbXunbaoCfgVo;
			ysrv.dataSource=object;
			}else{
			var leng=this.cBxbBaoKu.length;
			for (var j=0;j < leng;j++){
				if(obj.configId==this.cBxbBaoKu[j].ID){
					this.dangCiId=j+1;
				}
			};
			var len=this.rollRewards.length;
			this.dangCiItem=[];
			for (var i=0;i < len;i++){
				var itemVO=this.rollRewards[i];
				this.dangCiItem.push(itemVO.templateId+":"+itemVO.count);
			}
			EventCenter.instance.event("chongbaog_one_reward");
		};
		var arr=Mgr.mgxbMgr.zhuFuZhiList;
		if(arr && arr.length >=1){
			var xbdj=UIMgrR.openIView(com.xq.view.modules.xunbao.IXunbaoDaJiagnView,2);
			xbdj.dataSource={"rewardArr":[Mgr.mgxbMgr.zhuFuZhiList[0]]};
		}
		this.boxRed();
		EventCenter.instance.event("chongbaog_update_info");
	}

	__proto.boxRed=function(){
		if(Mgr.guide.isOpen("ChongBangXunBao")){
			var arr=this.jifenData;
			var len=arr.length;
			for (var i=0;i < len;i++){
				if(this.zhouReward.indexOf(arr[i])==-1 && this.jifen >=arr[i]){
					this.red.showRedPoint("ChongBangXunBao","cbxb",RedTypeEnum.QuanMinChongBangRed);
					return;
					}else{
					this.red.hideRedPoint("ChongBangXunBao","cbxb",RedTypeEnum.QuanMinChongBangRed);
				}
			}
		}
	}

	/**冲榜寻宝记录*/
	__proto.setJiLu=function(obj){
		this.chouJiangJiLu=obj.records;
		this.chouJiangJiLuType=obj.type;
		EventCenter.instance.event("chongbaog_choujiangjiu");
	}

	return ChongBangXunBaoMgr;
})()


