		this.fsXunbaoCfgVo=null;
		this.cBxbBaoKu=null;
		/**积分大奖*/
		this.extrareward=null;
		/**积分值*/
		this.jifenData=null;
		/**抽奖奖励*/
		this.rollRewards=null;
		/**总积分*/
		this.jifen=0;
		/**折扣*/
		this.zheKou=0;
		/**抽一次需要消耗的元宝数*/
