			var itemVoMsg=this.cBxbBaoKu[i].depot.split(":");
			if(itemVoMsg && djArrReward){
				if(itemVoMsg[0]==djArrReward.templateId && itemVoMsg[1]==djArrReward.count){
					this.dangCiId=i+1;
					return;
				}
			}
