//class com.xq.modules.youJiangDiaoYan.YouJiangDiaoYanMgr
var YouJiangDiaoYanMgr=(function(){
	function YouJiangDiaoYanMgr(){
		/**表youjiangdiaoyan*/
		this.yjdy=null;
		this.yjdyCfg=null;
		/**第几道题 为0代表没开始答题*/
		this.seq=0;
		/**是否已经领取奖励*/
		this.isGetReward=false;
		this.red=null;
		this.ifOpenAct=false;
		if(!Mgr.guide.isOpen("youJiangDiaoYan")){
			EventCenter.instance.on("new_function_open",this,this.onNewFuncOpen);
		}
		EventCenter.instance.event("ACTIVE_TOGGLE",["youJiangDiaoYan"]);
		this.yjdy=CfgManager.getTableCfg("youjiangdiaoyan");
		this.yjdyCfg=this.yjdy.objectDataArray;
		var yjdyHan=Handler.create(this,this.openAct,[34],false);
		NewActiveManager.ins.regActOpenHandler(34,yjdyHan);
		NewActiveManager.ins.regActEndHandler(34,Handler.create(this,this.closeAct,[34],false));
		this.red=Mgr.red;
		this.red.regist("youJiangDiaoYan","redYouJiangDiaoYan",true,"youJiangDiaoYan");
	}

	__class(YouJiangDiaoYanMgr,'com.xq.modules.youJiangDiaoYan.YouJiangDiaoYanMgr');
	var __proto=YouJiangDiaoYanMgr.prototype;
	// red.showRedPoint(FunctionDefine.REDYOUJIANGDIAOYAN,"yjdy",FunctionDefine.YOUJIANGDIAOYAN);
	__proto.openAct=function(actId){
		if(actId==34){
			Mgr.yjdyProMgr.sendYjdyInfo();
			this.ifOpenAct=true;
		}
	}

	__proto.showRed=function(){
		if(NewActiveManager.ins.checkIsOpen(34)&&Mgr.guide.isOpen("youJiangDiaoYan")&&!this.isGetReward){
			EventCenter.instance.event("MAIN_VIEW_CORNOR",["youJiangDiaoYan",true]);
		}
		else{
			EventCenter.instance.event("MAIN_VIEW_CORNOR",["youJiangDiaoYan",false]);
		}
	}

	/**
	*关闭页签
	*/
	__proto.closeAct=function(actId){
		if(actId==34){
			this.red.hideAll("QuanMingJinJieView");
			this.ifOpenAct=false;
		}
	}

	__proto.onNewFuncOpen=function(funId){
		if(funId=="youJiangDiaoYan"){
			if(this.ifOpenAct){
				EventCenter.instance.off("new_function_open",this,this.onNewFuncOpen);
				Mgr.yjdyProMgr.sendYjdyInfo();
			}
		}
	}

	/**根据id获取每一行数据*/
	__proto.getData=function(seq){
		var opActiv=NewActiveManager.ins.getActiveVerDic(34);
		if(opActiv){
			var obj=this.yjdy.getCfgMsgByTwoKey("flag",opActiv.flag,"seq",seq);
			if(obj)return obj;
		}
		return null;
	}

	/**
	*0 还未答题
	*1 选择题
	*2 问答题
	*3 结束面板
	**/
	__proto.getDatiState=function(){
		if(this.seq==0){
			return 0;
			}else if(this.getData(this.seq)==null){
			return 3;
			}else if(this.getData(this.seq).choose==""){
			return 2;
			}else{
			return 1;
		}
	}

	return YouJiangDiaoYanMgr;
})()


