	__proto.getYsNameByType=function(type){
		var ele=this.getYsEleByType(type);
		if(!ele)return "";
		return ele.getCfgData().name;
	}

	__proto.checkXiuLianLv=function(type,needJie,needCong){
		var info=this._model.getInfoByType(type);
		if(!info)return false;
		var myJie=info.xlJie;
		var myChong=info.xlChong;
		var flag=(myJie>needJie)||(myJie==needJie&&myChong>=needCong);
		return flag;
	}

	/**获取某类型修炼某重是否已激活*/
	__proto.ifActive=function(type,chong){
		var info=this._model.getInfoByType(type);
		if(!info)return false;
		var xlChong=info.xlChong;
		return xlChong>=chong;
	}

	//获取升级到下重需要的道具数量
	__proto.getNextNeed=function(type){
		var info=this._model.getInfoByType(type);
		var cof=this._model.getCofByType(type);
		if(!info||!cof)return 0;
		var maxJ=parseInt(cof.maxJie);
		var maxChong=parseInt(cof.maxChong);
		if((info.xlJie>=maxJ)&&(info.xlChong>=maxChong))
			return 0;
		var needExp=parseInt(cof.exp)*cof.expPer*info.xlJie-info.xlexp;
		var needCount=Math.ceil((needExp/parseInt(cof.addExp)));
		var needItems=CommonUtil.setMultipleReward(cof.baseCost,needCount);
		var needStr=needItems[0];
		if(needStr){
			var needItemCount=needStr.split(":")[1];
			return needItemCount;
		}
		return 0;
	}

	/**当前拥有的道具数量*/
	__proto.getCurHave=function(type){
		var cof=this._model.getCofByType(type);
		if(!cof)return 0;
		var item=cof.baseCost[0];
		var needId=item.split(":")[0];
		var moneyType=Mgr.moneyMgr.getMoneyTypeById(needId);
		if(moneyType){
			var have=Mgr.moneyMgr.getMoneyByType(moneyType);
		}
		else{
			have=Mgr.bag.getBagMatCount(needId);
		}
		return have;
	}

	__proto.getCurNeedItem=function(type){
		var cof=this._model.getCofByType(type);
		if(!cof)return null;
		var item=cof.baseCost[0];
		var needId=item.split(":")[0];
		var itemVo=Mgr.item.getItemVO(needId);
		return itemVo;
	}

	/**当前阶每重需要的exp*/
	__proto.getNeedExp=function(type){
		var info=this._model.getInfoByType(type);
		var cof=this._model.getCofByType(type);
		if(!info||!cof)return 0;
		var maxC=cof.maxChong;
		var allC=info.xlJie*maxC+info.xlChong;
		var expPer=parseFloat(cof.expPer);
		return ((allC*expPer)+1)*cof.exp;
	}

	/**根据元神类型 获取对应的修炼模块战力类型*/
	__proto.getXlPowerType=function(type){
		var index=type-1;
		var powerType=this._xlpowerType[index];
		if(powerType){
			return powerType;
		}
		return-1;
	}

	__proto.getXiuLianAttr=function(type,ifNext){
		(ifNext===void 0)&& (ifNext=false);
		var info=this._model.getInfoByType(type);
		var cof=this._model.getCofByType(type);
		if(!cof)return [];
		var maxC=cof.maxChong;
		if(ifNext){
			if(this.ifFull(type)){
				return [];
			};
			var allChong=info.xlJie*maxC+info.xlChong+1;
		}
		else{
			allChong=info.xlJie*maxC+info.xlChong;
		};
		var propId=cof.propId;
		var per=parseFloat(cof.propPer);
		var perAdd=parseFloat(cof.propAddPer);
		var propArr=Mgr.propM.attrFormula1(propId,per,perAdd,allChong);
		return propArr;
	}

	//获取修炼总战力
	__proto.getXiuLianFight=function(type){
		var xlarr=this.getXiuLianAttr(type);
		var xlPowr=Mgr.propM.attrFVUtil(xlarr);
		var gdPower=this.getGdFight(type);
		var clattr=this.getCuiLianAttr(type);
		var clPowr=Mgr.propM.attrFVUtil(clattr);
		return xlPowr+gdPower+clPowr;
	}

	/**修炼是否满级*/
	__proto.ifFull=function(type){
		var info=this._model.getInfoByType(type);
		var cof=this._model.getCofByType(type);
		if(!info||!cof)return false;
		return info.xlJie>=cof.maxJie&&info.xlChong>=cof.maxChong;
	}

	/**下一级能不能灌顶*/
	__proto.ifCanGd=function(type){
		var info=this._model.getInfoByType(type);
		if(!info)return false;
		var nextGdId=info.gdId+1;
		var cof=this._model.getGDCof(type,nextGdId);
		if(!cof)return false;
		if((info.xlJie>cof.jie)||(info.xlJie==cof.jie&&info.xlChong>=cof.chong)){
			return true;
		}
		return false;
	}

	__proto.getGdFight=function(type){
		var info=this._model.getInfoByType(type);
		if(!info)return 0;
		var gdId=info.gdId;
		if(!gdId)return 0;
		var cof=this._model.getGDCof(type,gdId);
		var per=cof.per;
		var xlAttr=this.getXiuLianAttr(type);
		var gdAttr=Mgr.propM.attrUtil1(xlAttr,per/100);
		return Mgr.propM.attrFVUtil(gdAttr);
	}

	__proto.getCuiLianAttr=function(type,ifNext){
		(ifNext===void 0)&& (ifNext=false);
		var info=this._model.getInfoByType(type);
		var cof=this._model.getCLCof(type);
		if(!cof)return [];
		var maxLv=cof.maxLv;
		if(ifNext){
			if(info.clLv>=maxLv){
				return [];
			};
			var lv=info.clLv+1;
		}
		else{
			lv=info.clLv;
		};
		var propId=cof.propId;
		var per=parseFloat(cof.per);
		var propArr=Mgr.propM.attrFormula2(propId,per,lv);
		return propArr;
	}

	/**淬炼是否满级*/
	__proto.ifCuiLianFull=function(type){
		var info=this._model.getInfoByType(type);
		var cof=this._model.getCLCof(type);
		if(!info||!cof)return false;
		var lv=info.clLv;
		var max=cof.maxLv;
		return lv>=max;
	}

	__proto.checkCuiLianLv=function(type,needLv){
		var info=this._model.getInfoByType(type);
		if(!info)return false;
		return info.clLv>=needLv;
	}

