	__proto.getDressGuids=function(type){
		var info=this._model.getInfoByType(type);
		var guids=[];
		var equipType=YuanShenType.getEquipType(type);
		var slots=com.xq.modules.yuanshen.YuanShenMgr.Slots;
		var len=slots.length;
		for(var i=0;i<len;i++){
			var slot=slots[i];
			var vo=Mgr.bag.getHighestStarEquipByType(equipType,slot);
			if(vo){
				var star=vo.cfgItem.star;
				var curStar=info.getEquipStarBySlot(slot);
				if(star>curStar){
					guids.push(vo.guid);
				}
			}
		}
		return guids;
	}

