	/**一键附魔*/
	__proto.oneKeyFuMo=function(ysType,Slot){
		var fmArr=this.getfmVoArr(ysType,Slot);
		var bgArr=Mgr.bag.getItemByCatogory(YuanShenType.getEquipType(ysType));
		bgArr.sort(this.compareBg);
		bgArr=this.unfoldBagArr(bgArr);
		var len=fmArr.length;
		for(var i=0;i<len;i++){
			var fmVo=fmArr[i];
			var bagVo=bgArr[i];
			if(!bagVo||fmVo.getLv()>=this.getFuMoLvByDjId(bagVo.templateId)){
				if(i==0){
					Mgr.prompt.optionPrompt("无可装配卷轴");
				}
				break ;
			};
			var count=bagVo.count;
			var equipInfo=this.getEquipInfo(ysType,Slot);
			if(!equipInfo)continue ;
			var guid=equipInfo.guid;
			var ele=this.getFumoEleByDjId(bagVo.templateId);
			if(!ele)continue ;
			var fmId=ele.getCfgData().id;
			Mgr.yuanShenA.c_fumo(ysType,guid,fmVo.fumoSlot,fmId);
		}
	}

	/**道具叠加了 这里把道具展开*/
	__proto.unfoldBagArr=function(arr){
		var unfoldarr=[];
		var len=arr.length;
		for(var i=0;i<len;i++){
			var bagVo=arr[i];
			var count=bagVo.count;
			for(var j=0;j<count;j++){
				unfoldarr.push(bagVo);
			}
		}
		return unfoldarr;
	}

	__proto.getfmVoArr=function(ysType,Slot){
		var fmArr=[];
		var arr=this._model.fmGridDc.array;
		var len=arr.length;
		var fmVo;
		for(var i=0;i<len;i++){
			var ele=arr[i];
			var fmId=ele.getValue(ysType+"_"+Slot);
			if(fmId==-1)continue ;
			fmVo=new YuanShenFuMoVo();
			fmVo.setData(ele.getCfgData().index,fmId);
			fmArr.push(fmVo);
		}
		fmArr.sort(this.compareLv);
		return fmArr;
	}

	__proto.getFuMoLvById=function(fmId){
		var ele=this._model.fmDc.getElement(fmId);
		if(!ele)return 0;
		return ele.getCfgData().lv;
	}

	/**按等级小到大*/
	__proto.compareLv=function(a,b){
		return a.getLv()-b.getLv();
	}

	/**按等级大到小*/
	__proto.compareBg=function(a,b){
		var lvA=Mgr.yuanShenM.getFuMoLvByDjId(a.templateId);
		var lvB=Mgr.yuanShenM.getFuMoLvByDjId(b.templateId);
		return lvB-lvA;
	}

	__proto.getFuMoLvByDjId=function(id){
		var ele=this.getFumoEleByDjId(id);
		if(!ele)return 0;
		return ele.getCfgData().lv;
	}

	/**通过武器Id获取武器装备评分 基础+极品属性*/
	__proto.getEquipBaseFight=function(id){
		var cof=Mgr.item.getEquip(id);
		if(!cof)return 0;
		var baseAttr=cof.jichuAttribute;
		var arr=Mgr.propM.cofAttrUnit(baseAttr);
		return Mgr.propM.attrFVUtil(arr);
	}

	/**获取武器装备极品属性评分
	*arr:特殊属性id数组
	*ifother:是否是获取别人的
	**/
	__proto.getEquipSpicalFight=function(id,ifOther){
		(ifOther===void 0)&& (ifOther=false);
		var arr=this.getSpAttrs(id,ifOther);
		if(!arr)return 0;
		var len=arr.length;
		var fight=0;
		for(var i=0;i<len;i++){
			var spCof=Mgr.equipCompMgr.getSpecialAttrById(arr[i]);
			if(!spCof)continue ;
			var cof=AttributeTypeEnum.getAttrObj(spCof.type);
			var val=spCof.value;
			if(!cof)continue ;
			fight+=cof.pingfen*val;
		}
		return fight;
	}

	__proto.getEquipFumoFight=function(id,ifOther){
		(ifOther===void 0)&& (ifOther=false);
		var cof=Mgr.item.getEquip(id);
		if(!cof)return 0;
		var ysType=this.getYsTypeByEquipType(cof.type);
		var slot=cof.eqpart;
		var arr=this.getFumoIds(ysType,slot,ifOther);
		if(!arr)return 0;
		var len=arr.length;
		var fight=0;
		for(var i=0;i<len;i++){
			if(!arr[i])continue ;
			var ele=Mgr.yuanShenM.getFumoEleByFumoId(arr[i]);
			if(!ele)continue ;
			var fmcof=ele.getCfgData();
			var propId=fmcof.propId;
			var propPer=fmcof.propPer;
			var lv=fmcof.lv;
			var attrArr=Mgr.propM.attrFormula3(propId,propPer);
			fight+=Mgr.propM.attrFVUtil(attrArr);
		}
		return fight;
	}

	/**通过武器ID获取*/
	__proto.getSpAttrs=function(id,ifOther){
		(ifOther===void 0)&& (ifOther=false);
		var cof=Mgr.item.getEquip(id);
		if(!cof)return [];
		var ysType=this.getYsTypeByEquipType(cof.type);
		var slot=cof.eqpart;
		var equipInfo=ifOther?Model.checkPlayerModel.getEquipMsg(ysType,slot):this.getEquipInfo(ysType,slot);
		if(!equipInfo)return [];
		var spArr=equipInfo.makeAttributes;
		return spArr;
	}

