	/**是否满足升级条件 包括以下
	*是否已满级
	*修炼等级 淬炼等级
	**/
	__proto.checkConditionStat=function(type,skillId){
		var lv=this.getSkillLv(type,skillId);
		var cof=this.getSkillUpgradeCof(skillId,lv+1);
		if(!cof)return false;
		var condition=cof.conditions;
		var len=condition.length;
		for(var i=0;i<len;i++){
			var conditionStr=condition[i];
			var conditions=conditionStr.split(":");
			var conditionType=parseInt(conditions[0]);
			var ysType=parseInt(conditions[1])
			if(conditionType==1){
				var needJie=parseInt(conditions[2]);
				var needChong=parseInt(conditions[3]);
				var flag=Mgr.yuanShenM.checkXiuLianLv(ysType,needJie,needChong);
				}else if(conditionType==2){
				var needLv=parseInt(conditions[2]);
				flag=Mgr.yuanShenM.checkCuiLianLv(ysType,needLv);
			}
			if(!flag){
				return false;
			}
		}
		return true;
	}

	__proto.checkSkillCost=function(type,skillId){
		var lv=this.getSkillLv(type,skillId);
		var cof=this.getSkillUpgradeCof(skillId,lv+1);
		if(!cof)return false;
		var cost=cof.cost;
		var needItem=cost[0];
		return Mgr.bag.checkItemIsEnough(needItem);
	}

