var GiveActivityVo=(function(){
	function GiveActivityVo(){
		/**赠送类活动配置表*/
		this.giveActivityCfg=null;
		/**赠送类活动排行榜配置表*/
		this.giveActivityRankCfg=null;
		/**赠送类活动配置表Data*/
		this.giveActivityData=null;
		/**赠送类活动排行榜配置表Data*/
		this.giveActivityRankData=null;
		/**活动类型*/
		this.activityType=0;
		/**排行榜奖励数组*/
		this.giveActivityRankArr=null;
		/**赠送道具Id*/
		this.giveItemId=null;
		/**大奖展示模型*/
		this.showRes=null;
		/**排行榜最大数量*/
		this.rankMaxNum=0;
		/**当前活动版本*/
		this.flag=0;
		/**uiControl表子功能id*/
		this.funcId=null;
		/**父级功能id*/
		this.parentFuncId=null;
		/**活动刷新事件*/
		this.activeEvent=null;
		/**红点更新刷新事件*/
		this.redEvent=null;
		/**号召赠送月饼cd*/
		this.chatCdDic=null;
		this.giveActivityRankCfgName="huahaoyueyuanbang";
		this.giveActivityCfgName="huahaoyueyuan";
	}

	__class(GiveActivityVo,'com.xq.modules.zhongQiuHuoDong.GiveActivityVo');
	var __proto=GiveActivityVo.prototype;
	__proto.getGiveActivityData=function(){
		if(!this.giveActivityCfg){
			return;
		}
		if(!this.giveActivityData){
			this.giveActivityData=new DataContainer();
			var cfgArr=this.giveActivityCfg.objectDataArray;
			var len=cfgArr.length;
			for (var i=0;i < len;i++){
				var obj=cfgArr[i];
				var ele=new DataElement(obj);
				this.giveActivityData.addElement(obj.item,ele);
			}
		}
	}

	__proto.getGiveActivityRankArr=function(){
		this.giveActivityRankArr=[];
		var giveRankCfgArr=this.giveActivityRankCfg.objectDataArray;
		if(!giveRankCfgArr){
			return;
		};
		var len=giveRankCfgArr.length;
		var giveRankVo;
		for (var i=0;i < this.rankMaxNum;i++){
			giveRankVo=new GiveActivityRankVo();
			giveRankVo.rank=i+1;
			var rewardArr;
			for (var k=0;k < len;k++){
				var rankCfg=giveRankCfgArr[k];
				var min=rankCfg.rank[0];
				var max=rankCfg.rank[1];
				if(giveRankVo.rank >=min && giveRankVo.rank <=max){
					giveRankVo.helpLimit=rankCfg.limit2;
					giveRankVo.helpRewardArr=rankCfg.assistReward;
					giveRankVo.limit=rankCfg.limit1;
					giveRankVo.rewardArr=rankCfg.reward;
					break ;
				}
			}
			this.giveActivityRankArr.push(giveRankVo);
		}
	}

	__proto.getGiveActivity=function(){
		var actVo=NewActiveManager.ins.getActiveVerDic(114);
		if(!actVo){
			return;
		}
		this.flag=actVo.flag;
		if(this.giveActivityCfg){
			var ele=this.giveActivityData.array[0];
			if(!ele){
				return;
			};
			var cfg=ele.getCfgData();
			this.giveItemId=cfg.item;
			this.showRes=cfg.show;
			this.rankMaxNum=50;
		}
	}

	__proto.setConfig=function(){}
	return GiveActivityVo;
})()


