//class com.xq.modules.zhouka.ZhouKaMgr
var ZhouKaMgr=(function(){
	function ZhouKaMgr(){
		this._model=null;
		this._red=null;
		this._model=Model.zhouKa;
		this._red=Mgr.red;
		this.registRed();
	}

	__class(ZhouKaMgr,'com.xq.modules.zhouka.ZhouKaMgr');
	var __proto=ZhouKaMgr.prototype;
	//==========后端数据同步=========
	__proto.updateInfo=function(msg){
		this._model.updateData(msg);
		EventCenter.instance.event("UpateInfo");
		this.updateRed();
		this.checkFuFeiYinDao();
	}

	__proto.updateRewardTimes=function(msg){
		this._model.updateRewardTimes(msg);
		this.updateRed();
		EventCenter.instance.event("upateRewardTimes");
		this._model.updateLastRewardCount();
	}

	/**更新击杀boss数量*/
	__proto.updateKillBossNum=function(msg){
		this._model.updateKillBossNum(msg);
		this.updateRed();
		EventCenter.instance.event("updateKillBossNum");
		this.checkFuFeiYinDao();
	}

	__proto.checkFuFeiYinDao=function(){
		if(this._model.ifShowFuFeiYinDao()){
			this._model.updateLastRewardCount();
			Mgr.chipPopMgr.openFuFeiYinDaoView(this._model.lvInfo.remainReward,64802,261130);
		}
	}

	//=============红点相关============
	__proto.registRed=function(){
		this._red.regist("zhoukamainicon","zhouka",true,RedTypeEnum.TeQuanKaRed);
	}

	/**红点刷新*/
	__proto.updateRed=function(){
		if(!this.ifActive){
			this._red.hideRedPoint("zhouka","reward",RedTypeEnum.ZhouKaRed);
			return;
		};
		var info=this._model.lvInfo;
		if(!info)return;
		if(info.totalRewardTimes!=0&&info.remainReward>0&&info.getRewardTimes<info.totalRewardTimes){
			this._red.showRedPoint("zhouka","reward",RedTypeEnum.ZhouKaRed);
		}
		else{
			this._red.hideRedPoint("zhouka","reward",RedTypeEnum.ZhouKaRed);
		}
	}

	/**获取当前状态
	*0：未激活
	*1：激活可领奖励
	*2：激活已领取奖励
	**/
	__proto.getStat=function(){
		var ele=Model.teQuanKa.getDataByType(3);
		if(!ele)return 0;
		var info=ele.getValue("s_data");
		if(!info)return 0;
		if(info.leftDay<=0)return 0;
		if(info.alreadyReard)return 2;
		return 1;
	}

	//======================================
	__getset(0,__proto,'ifActive',function(){
		return Model.teQuanKa.getActiveStat(3);
	});

	return ZhouKaMgr;
})()


