//class com.xq.modules.zhoumokuanghuan.DanBiChongZhiMgr
var DanBiChongZhiMgr=(function(){
	function DanBiChongZhiMgr(){
		this.danBiFanHuanData=null;
		this.danBiChongZhiCfg=null;
		this.red=null;
		this.red=Mgr.red;
		this.danBiChongZhiCfg=CfgManager.getTableCfg("zmdanbichongzhi");
		this.red.regist("zhoumokuanghuan","danbichongzhi_week",true,"ZhouMoKuangHuanRed");
	}

	__class(DanBiChongZhiMgr,'com.xq.modules.zhoumokuanghuan.DanBiChongZhiMgr');
	var __proto=DanBiChongZhiMgr.prototype;
	__proto.getDengLuHaoLiData=function(isUpdataCfg){
		(isUpdataCfg===void 0)&& (isUpdataCfg=false);
		if(!this.danBiChongZhiCfg)return null;
		if(!this.danBiFanHuanData || isUpdataCfg){
			this.danBiFanHuanData=new DataContainer();
			var arr=this.danBiChongZhiCfg.objectDataArray;
			var cof;
			var ele;
			var len=arr.length;
			for(var i=0;i<len;i++){
				cof=arr[i];
				ele=new DataElement(cof);
				this.danBiFanHuanData.addElement(cof.id,ele);
			}
		}
		return this.danBiFanHuanData;
	}

	/**注册活动 开启 关闭handler*/
	__proto.regActive=function(){
		ActManager.ins.regist("zhoumokuanghuan","danbichongzhi_week",80,"ZhouMoKuangHuanEvent");
		NewActiveManager.ins.regActOpenHandler(80,Handler.create(this,this.openAct,null,false));
		NewActiveManager.ins.regActEndHandler(80,Handler.create(this,this.endAct,null,false));
		this.endAct();
	}

	//默认关闭
	__proto.getDanBiChongZhiCfg=function(){
		CfgManager.clearTabCfg("zmdanbichongzhi");
		this.danBiChongZhiCfg=CfgManager.getTableCfg("zmdanbichongzhi");
		this.getDengLuHaoLiData(true);
	}

	__proto.openAct=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["QiXiHuoDong",false]);
		Mgr.feiShengBangAction.sendGetDanBiChongZhi(80);
	}

	__proto.endAct=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["QiXiHuoDong"]);
	}

	/**运营活动单笔充值红点*/
	__proto.checkDanBiChongZhiRed=function(msg){
		var danBiChongZhiArr=[];
		var len=msg.msgList.length;
		var isRed=false;
		for (var i=0;i < len;i++){
			var danChongMsg=msg.msgList[i];
			var ele=this.getDengLuHaoLiData().getElement(danChongMsg.id)
			ele.data=danChongMsg;
			if(danChongMsg.getCount < danChongMsg.finishCount && danChongMsg.getCount < parseInt(ele.getCfgData().num)){
				ele.sortIndex=2;
				isRed=true;
			}
			else{
				if(parseInt(ele.getCfgData().num)> danChongMsg.getCount){
					ele.sortIndex=1;
				}
				else{
					ele.sortIndex=0;
				}
			}
			danBiChongZhiArr.push(ele);
		}
		if(isRed){
			this.red.showRedPoint("danbichongzhi_week","DanBiChongZhiWeekRed","DanBiChongZhiWeekRed");
			}else{
			this.red.hideRedPoint("danbichongzhi_week","DanBiChongZhiWeekRed","DanBiChongZhiWeekRed");
		}
		EventCenter.instance.event(DanBiChongZhiMgr.UPDATA_DANBICHONGZHI_WEEK,[danBiChongZhiArr.sort(this.compare)]);
	}

	__proto.compare=function(vo1,vo2){
		if(vo1.sortIndex > vo2.sortIndex){
			return-1;
		}
		else if(vo1.sortIndex < vo2.sortIndex){
			return 1;
		}
		return 0;
	}

	DanBiChongZhiMgr.UPDATA_DANBICHONGZHI_WEEK="updata_danbichongzhi_week";
	return DanBiChongZhiMgr;
})()


