//class com.xq.modules.zhoumokuanghuan.DengLuHaoLiMgr
var DengLuHaoLiMgr=(function(){
	function DengLuHaoLiMgr(){
		/**当前_id*/
		this._flag=0;
		/**是否领取了普通奖励*/
		this._normalStat=false;
		/**是否领取了svip奖励*/
		this._svipStat=false;
		/**登录豪礼 dataContainer*/
		this._loginGiftDC=null;
		this._cof=null;
		this._red=null;
		this.regRed();
		this._cof=CfgManager.getTableCfg("zmdengluhaoli");
	}

	__class(DengLuHaoLiMgr,'com.xq.modules.zhoumokuanghuan.DengLuHaoLiMgr');
	var __proto=DengLuHaoLiMgr.prototype;
	__proto.getDengLuHaoLiData=function(isUpdataCfg){
		(isUpdataCfg===void 0)&& (isUpdataCfg=false);
		if(!this._cof)return null;
		if(!this._loginGiftDC || isUpdataCfg){
			this._loginGiftDC=new DataContainer();
			var arr=this._cof.objectDataArray;
			var cof;
			var ele;
			var len=arr.length;
			for(var i=0;i<len;i++){
				cof=arr[i];
				ele=new DataElement(cof);
				ele.setValue("Z",cof.id);
				this._loginGiftDC.addElement(cof.id,ele);
			}
		}
		return this._loginGiftDC;
	}

	__proto.getDataByFlag=function(flag){
		var dc=this.getDengLuHaoLiData().where("flag",flag,"id");
		return dc.array.sort(this.compare);
	}

	__proto.compare=function(a,b){
		return a.getValue("Z")-b.getValue("Z");
	}

	__proto.updateData=function(msg){
		this._flag=msg.flag;
		var arr=msg.msg;
		var len=arr.length;
		var ele;
		var stat;
		for(var i=0;i<len;i++){
			stat=arr[i];
			ele=this.getDengLuHaoLiData().getElement(stat.id);
			ele.setValue("S",stat.state);
			if(stat.state){
				ele.setValue("Z",(stat.id+10));
			}
		}
		EventCenter.instance.event("updateView");
	}

	/**注册活动 开启 关闭handler*/
	__proto.regActive=function(){
		ActManager.ins.regist("zhoumokuanghuan","dengluhaoli",79,"ZhouMoKuangHuanEvent");
		NewActiveManager.ins.regActOpenHandler(79,Handler.create(this,this.openAct,null,false));
		NewActiveManager.ins.regActEndHandler(79,Handler.create(this,this.endAct,null,false));
		this.endAct();
	}

	// }
	__proto.openAct=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["zhoumokuanghuan",false]);
		Mgr.loginGiftA.c_getInfo(79);
	}

	__proto.endAct=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["loginGift"]);
	}

	//========================红点=============
	__proto.regRed=function(){
		this._red=Mgr.red;
		this._red.regist("zhoumokuanghuan","dengluhaoli",true,"ZhouMoKuangHuanRed");
		EventCenter.instance.on("VIPLEVEL_CHANGE",this,this.updateRed);
	}

	/**刷新红点*/
	__proto.updateRed=function(){
		var svipLv=NetMgr.ins().roleVO.vipLevel;
		var flag=false;
		var arr=this.getDataByFlag(this.curFlag);
		var len=arr.length;
		for(var i=0;i < len;i++){
			var ele=arr[i];
			var cof=ele.getCfgData();
			if(cof.type==1){
				var stat=ele.getValue("S");
				if(!stat &&svipLv>=cof.sviplevel){
					flag=true;
					break ;
				}
			}
		}
		if(flag){
			this._red.showRedPoint("dengluhaoli","DengLuHaoLi_Red","DengLuHaoLiRed");
		}
		else{
			this._red.hideRedPoint("dengluhaoli","DengLuHaoLi_Red","DengLuHaoLiRed");
		}
	}

	/**活动剩余时间*/
	__getset(0,__proto,'timeLeft',function(){
		var vo=NewActiveManager.ins.getActiveVerDic(79);
		if(vo){
			return vo.endTime-Browser.now();
		}
		return 0;
	});

	/**当前Id*/
	__getset(0,__proto,'curFlag',function(){
		return this._flag;
	});

	return DengLuHaoLiMgr;
})()


