/**
*遥控控制Mgr
*@author zhanglimin
*@date 2020-7-17
**/
//class com.xq.modules.zhuCheng.ZhuChengMgr
var ZhuChengMgr=(function(){
	function ZhuChengMgr(){
		/**显示玩家数量*/
		this.maxPlayerNum=5;
		/**城主雕像*/
		this.masterStatue=null;
		/**主城配置*/
		this.zhuchengCfg=null;
		/**主城Vo*/
		this.zhuChengVo=null;
		/**膜拜按钮出现距离*/
		this.mobaiRect=350;
		/**是否膜拜了*/
		this.mobaied=false;
		this.unitMgr=null;
		this.mainPl=null;
		this.controlTip
		this.mainPo=new Point();
		this.zhuchengCfg=CfgManager.getTableCfg("zhucheng");
		this.init();
		this.unitMgr=UnitManager.ins;
	}

	__class(ZhuChengMgr,'com.xq.modules.zhuCheng.ZhuChengMgr');
	var __proto=ZhuChengMgr.prototype;
	__proto.init=function(){
		var obj=this.zhuchengCfg.objectDataArray[0];
		this.zhuChengVo=new ZhuChengVo();
		this.zhuChengVo.zhuchengPo=obj.chengZhuPo;
	}

	/**排行信息*/
	__proto.onRankSc=function(msg){
		if(msg.rankType==2){
			var rankVo=msg.rankInfoLists[0].rankVo;
			var roleVO=new RoleVO();
			roleVO.job=rankVo.job;
			if(rankVo.shenyiIsActive){
				roleVO.wingLevel=1;
				}else{
				roleVO.wingLevel=0;
			}
			roleVO.name=rankVo.roleName;
			roleVO.shenBingPeiDaiId=rankVo.shenBingHuanHua;
			roleVO.wingHuanHuaId=rankVo.shenYiHuanHua;
			roleVO.roleHuanHuaId=rankVo.roleHuanHua;
			roleVO.wuQiHuanHuaId=rankVo.shenBingHuanHua;
			roleVO.titleId=parseInt(rankVo.title);
			this.createStatue(roleVO);
		}
	}

	/**创角雕像*/
	__proto.createStatue=function(vo){
		this.masterStatue=new Statue();
		this.masterStatue.mobaiBack=Handler.create(this,this.setMoBai);
		this.masterStatue.initData(vo,1);
		Game.getInstance().sceneContainer.unitLayer.addChild(this.masterStatue);
		this.masterStatue.pos(this.zhuChengVo.chengZhuX,this.zhuChengVo.chengZhuY);
		this.masterStatue.updateMb(!this.mobaied);
	}

	/**设置模板状态*/
	__proto.setMoBai=function(){
		this.mobaied=true;
		if(this.masterStatue){
			this.masterStatue.updateMb(false);
		}
		Mgr.rankingPro.sendMoBai(2);
	}

	/**根据类型获取雕像类型资源*/
	__proto.getStatueTypeUrl=function(type){
		var temp="zlph";
		switch(type){
			case 1:
				temp="zlph";
				break ;
			}
		return PathDefine.getZhuChengRes(temp);
	}

	/**是否显示遥感*/
	__proto.updateControl=function(mapType){
		var bo=MapType.controlMapAry.indexOf(mapType)!=-1;
		EventCenter.instance.event("ChangeControlBoxState",bo);
	}

	/**副本信息*/
	__proto.copyInfo=function(){
		Mgr.ghMgr.openGouhuoCopy();
	}

	/**是否是主城*/
	__getset(0,__proto,'isInZhuCheng',null,function(mapType){
		this.mainPl=Game.getInstance().player;
		if(!this.mainPl)
			return;
		this.updateControl(mapType)
		this.mainPl.isInZhuCheng=false;
		if(mapType==2){
			if(mapType==2){
				this.mainPl.isInZhuCheng=true;
				Game.getInstance().newMainView.showHide(MainHideEnum.ZhuCheng,false);
			}
			Game.getInstance().newMainView.getTopActive().isShowActive(false);
			EventCenter.instance.event("ZHU_CHENG_OPEN_CONTROL",[true])
			var mb=Mgr.rankingPro.moBaiDic.get(2);
			if(mb){
				this.mobaied=mb.mobaiState;
			}
			else{
				this.mobaied=true;
			}
			EventCenter.instance.once("RANKINGLIST_ONE",this,this.onRankSc);
			Mgr.rankingPro.sendGetRankInfoCS(2);
			if(mapType !=62){
				this.copyInfo();
				if(NewGuideAction.Ins.checkHasGuide("38",38,true)){
					if(!this.controlTip){
						this.controlTip=new ControlPaoPao();
						this.controlTip.y=-100;
						this.controlTip.x=100;
						Game.getInstance().controlBox.addChild(this.controlTip);
					}
				}
			}
		}
		else{
			EventCenter.instance.event("ZHU_CHENG_OPEN_CONTROL",[false])
			if(this.masterStatue){
				this.masterStatue.gc();
				this.masterStatue=null
			}
		}
	});

	__getset(0,__proto,'isZhuCheng',function(){
		if(Model.game.mPlayer){
			return Model.game.mPlayer.isInZhuCheng;
		}
		return false;
	});

	__getset(1,ZhuChengMgr,'ins',function(){
		return ZhuChengMgr._ins=ZhuChengMgr._ins|| new ZhuChengMgr();
	});

	ZhuChengMgr._ins=null;
	return ZhuChengMgr;
})()


