//class com.xq.modules.zhujueguanghuan.ZhuJueGuangHuanMgr
var ZhuJueGuangHuanMgr=(function(){
	function ZhuJueGuangHuanMgr(){
		this._model=null;
		this._red=null;
		this._model=new ZhuJueGuangHuanModel();
		this._red=Mgr.red;
		this.registRed();
	}

	__class(ZhuJueGuangHuanMgr,'com.xq.modules.zhujueguanghuan.ZhuJueGuangHuanMgr');
	var __proto=ZhuJueGuangHuanMgr.prototype;
	//===========================
	__proto.registRed=function(){
		this._red.regist("ZhuJueGuangHuanMain","ZhuJueGuangHuan",true,RedTypeEnum.TeQuanKaRed);
	}

	__proto.updateRed=function(){
		var stat=this.getStat();
		if(stat==1){
			this._red.showRedPoint("ZhuJueGuangHuan","dailyReward",RedTypeEnum.ZhuJueGuangHuanRed);
		}
		else{
			this._red.hideRedPoint("ZhuJueGuangHuan","dailyReward",RedTypeEnum.ZhuJueGuangHuanRed);
		}
	}

	/**获取特权数据*/
	__proto.getTeQuanArr=function(){
		return this._model.getTequanArr();
	}

	/**获取充值立得的元宝和玉币的数量*/
	__proto.getChargeRewardNum=function(){
		var ele=Model.teQuanKa.getDataByType(4);
		if(!ele)return null;
		var cof=ele.getCfgData();
		var data={};
		var reward=cof.firstReward;
		var rewards=reward.split(";");
		var len=rewards.length;
		for(var i=0;i<len;i++){
			var item=rewards[i];
			var items=item.split(":");
			var id=items[0];
			var num=parseInt(items[1]);
			if(id=="dj1688"){
				data.yuanbaoNum=num;
			}
			else if(id=="dj1923"){
				data.yubiNum=num;
			}
			else{
				continue ;
			}
		}
		return data;
	}

	/**获取称号url*/
	__proto.getTitleUrl=function(){
		var ele=Model.teQuanKa.getDataByType(4);
		if(!ele)return null;
		var cof=ele.getCfgData();
		var url=PathDefine.OUT_RES+cof.titleId+".amt";
		return url;
	}

	/**获取当前状态
	*0：未激活
	*1：激活可领奖励
	*2：激活已领取奖励
	**/
	__proto.getStat=function(){
		var ele=Model.teQuanKa.getDataByType(4);
		if(!ele)return 0;
		var info=ele.getValue("s_data");
		if(!info)return 0;
		if(info.leftDay<=0)return 0;
		if(info.alreadyReard)return 2;
		return 1;
	}

	/**获取描述*/
	__proto.getDesc=function(id){
		var desc=this._model.getTequanDesc(id);
		var num=0;
		if(id==1||id==7){
			var day=CommonUtil.openServerDay;
			var data=Model.teQuanKa.getDayRewards(4,day);
			if(id==1){
				var reward=data.dayReward;
			}
			else if(id==7){
				reward=data.extraReward1;
			}
			num=reward.split(":")[1];
		}
		if(num){
			desc=desc.replace("{0}",num);
		}
		return desc;
	}

	return ZhuJueGuangHuanMgr;
})()


/**
*@author:huanghong
*@date:2021-8-24
*@desc:卓越BOSSMgr
*/
//class com.xq.modules.zhuoYueBoss.ZhuoYueBossMgr
var ZhuoYueBossMgr=(function(){
	function ZhuoYueBossMgr(){
		this.curType=0;
		this.curBoss=null;
		this._model=null;
		this._red=null;
		this._bossFuncDic=null;
		this._notOpenFuncNum=0;
		this._model=new ZhuoYueBossModel();
		this._bossFuncDic={};
		this.registBossType(1,"ZhuoYueBoss");
		CopyTipMgr.ins.regisCopyTip(2038,Handler.create(this,this.closeTips,null,false));
	}

	__class(ZhuoYueBossMgr,'com.xq.modules.zhuoYueBoss.ZhuoYueBossMgr');
	var __proto=ZhuoYueBossMgr.prototype;
	__proto.init=function(){
		this.registRed();
	}

	/**根据卓越类型和层数 获取boss ele arr*/
	__proto.getBossEles=function(zyType,layer){
		return this._model.getBossEles(zyType,layer);
	}

	/**根据卓越类型获取层数数组*/
	__proto.getLayerArr=function(zyType){
		return this._model.getLayerArr(zyType);
	}

	/**获取常量配置Ele*/
	__proto.getConstEle=function(zyType){
		return this._model.getConstEle(zyType);
	}

	/**剩余次数检测*/
	__proto.checkTimes=function(zyType){
		return this.getRemainTimes(zyType)>0;
	}

	/**剩余次数*/
	__proto.getRemainTimes=function(zyType){
		var constEle=this.getConstEle(zyType);
		if(!constEle)return 0;
		var constCfg=constEle.getCfgData();
		var remainTimes=constEle.getValue("remain");
		if(!remainTimes)remainTimes=0;
		return remainTimes;
	}

	__proto.getMaxTimes=function(zyType){
		var constEle=this.getConstEle(zyType);
		if(!constEle)return 0;
		var constCfg=constEle.getCfgData();
		var max=parseInt(constCfg.times);
		return max;
	}

	/**最大购买次数*/
	__proto.getMaxBuyTime=function(zyType,svipLv){
		(svipLv===void 0)&& (svipLv=0);
		var constEle=this.getConstEle(zyType);
		if(!constEle)return 0;
		var constCfg=constEle.getCfgData();
		var baseTimes=parseInt(constCfg.buytimes);
		var svipTimes=Mgr.tequanMgr.getTequanVal(42,svipLv);
		return baseTimes+svipTimes;
	}

	/**已购买次数*/
	__proto.getHasBuyTimes=function(zyType){
		var constEle=this.getConstEle(zyType);
		if(!constEle)return 0;
		var hasBuy=constEle.getValue("buy");
		if(!hasBuy)hasBuy=0;
		return hasBuy;
	}

	/**剩余购买次数检测*/
	__proto.checkBuyTimes=function(zyType){
		var constEle=this.getConstEle(zyType);
		if(!constEle)return false;
		var svipLv=NetMgr.ins().roleVO.vipLevel;
		var maxTimes=this.getMaxBuyTime(zyType,svipLv);
		var hasBuy=constEle.getValue("buy");
		if(!hasBuy)hasBuy=0;
		return hasBuy<maxTimes;
	}

	/**次数是否是满的*/
	__proto.checkIsFull=function(zyType){
		var remainTimes=this.getRemainTimes(zyType);
		var max=this.getMaxTimes(zyType);
		return remainTimes>=max;
	}

	/**增加次数消耗品检测*/
	__proto.checkCost=function(zyType){
		var constEle=this.getConstEle(zyType);
		if(!constEle)return false;
		var constCfg=constEle.getCfgData();
		var cost=constCfg.cost[0];
		var costSplitArr=cost.split(":");
		var id=costSplitArr[0];
		var need=parseInt(costSplitArr[1]);
		var moneyType=Mgr.moneyMgr.getMoneyTypeById(id);
		if(moneyType){
			var have=Mgr.moneyMgr.getMoneyByType(moneyType);
		}
		else{
			have=Mgr.bag.getBagMatCount(id);
		}
		return have>=need;
	}

	/**获取默认选中层数*/
	__proto.getDefuatIndex=function(zyType){
		var jie=Mgr.zhuoYueZhuangBeiM.getMaxJieByType(zyType);
		if(jie==0)jie=1;
		var arr=this._model.getBossArrByTypeAndJie(zyType,jie);
		var len=arr.length;
		var index=0;
		var ele;
		var cfg;
		for(var i=0;i<len;i++){
			ele=arr[i];
			cfg=ele.getCfgData();
			var attrArr=cfg.needAttr;
			if(!attrArr||attrArr.length)continue ;
			if(!Mgr.zhuoYueZhuangBeiM.checkZYZLAll(attrArr)){
				break ;
			}
			index=i;
		}
		ele=arr[index];
		if(!ele)return [0,0];
		cfg=ele.getCfgData();
		var layerIndex=parseInt(cfg.layer)-1;
		index=parseInt(cfg.index)-1;
		return [layerIndex,index]
	}

	//=============场景进入===========
	__proto.initFightVo=function(fightVo){
		fightVo.hideAry=[1,2,3,4];
		fightVo.closeFun=Handler.create(this,this.exit,null,false);
		if(this.curBoss){
			fightVo.reward=this.curBoss.getCfgData().showReward;
		}
		EventCenter.instance.on("UPDATE_BOSSOWNER",this,this.setOwner);
		this.openFuBenView();
	}

	/**推出场景方法*/
	__proto.exit=function(){
		Mgr.zhuoYueBossA.sendExit();
		this.curBoss=null;
	}

	/**打开副本界面*/
	__proto.openFuBenView=function(){
		UIMgrR.openIView(com.xq.view.modules.bossHall.zhuoYueBoss.IZhuoYueBossCopyView,2);
	}

	__proto.closeTips=function(){
		UIMgrR.closeIView(com.xq.view.modules.bossHall.zhuoYueBoss.IZhuoYueBossCopyView);
		EventCenter.instance.off("UPDATE_BOSSOWNER",this,this.setOwner);
	}

	/**设置归属者*/
	__proto.setOwner=function(){
		var v=UIMgrR.getIView(com.xq.view.mainUI.subPanel.IMiniUnitBloodBoxView);
		if(!v)return;
		var monster=v.mVo;
		if(!monster)return;
		var monsterId=monster.monsterId;
		var ownvo=Mgr.bossOwnerM.getOwner(monsterId);
		if(ownvo){
			v.setOwer(ownvo,1);
		}
	}

	//============后端数据同步============
	__proto.updateGetInfo=function(msg){
		this._model.updateGetInfo(msg);
		this.updateRed(msg.type);
		EventCenter.instance.event("UpdateInfo");
	}

	/**购买归属次数后同步数据*/
	__proto.updateBuyTimes=function(msg){
		this._model.updateBuyTimes(msg);
		this.updateRed(msg.type);
		EventCenter.instance.event("UpdateBuyimes");
	}

	/**奖励*/
	__proto.onReward=function(msg){
		var v=UIMgrR.openIView(com.xq.view.modules.bossHall.zhuoYueBoss.IZhuoYueBossRewardView,2);
		v.dataSource=msg;
	}

	//=============红点===================
	__proto.registBossType=function(type,funcId){
		this._bossFuncDic[type]=funcId;
	}

	__proto.registRed=function(){
		this._red=Mgr.red;
		this._red.regist("wulinhuanjing","ZhuoYueBoss",false,RedTypeEnum.BossHallRed);
		this._notOpenFuncNum=0;
		this.checkOpen("ZhuoYueBoss");
		if(this._notOpenFuncNum>0){
			EventCenter.instance.on("new_function_open",this,this.newOpenFun);
		}
	}

	__proto.checkOpen=function(funcId){
		if(!Mgr.guide.isOpen("ZhuoYueBoss")){
			this._notOpenFuncNum++;
		}
		else{
			Mgr.zhuoYueBossA.sendGetInfo(1);
		}
	}

	__proto.newOpenFun=function(funcId){
		if(funcId=="ZhuoYueBoss"){
			this._notOpenFuncNum--;
			Mgr.zhuoYueBossA.sendGetInfo(1);
		}
		if(this._notOpenFuncNum<=0){
			EventCenter.instance.off("new_function_open",this,this.newOpenFun);
		}
	}

	__proto.updateRed=function(bossType){
		var func=this._bossFuncDic[bossType];
		if(!func)return;
		var remainTime=this.getRemainTimes(bossType);
		if(remainTime>0){
			this._red.showRedPoint(func,"red","ZhuoYueBossRed");
		}
		else{
			this._red.hideRedPoint(func,"red","ZhuoYueBossRed");
		}
	}

	return ZhuoYueBossMgr;
})()


