/**
*@author xiangjia
*@date 2019-6-3
*/
//class com.xq.rpg.action.ai.base.BaseAIController
var BaseAIController=(function(){
	function BaseAIController(){
		this.curAIAction=null;
		this.lastAIAction=null;
		this.isStartLoop=false;
	}

	__class(BaseAIController,'com.xq.rpg.action.ai.base.BaseAIController');
	var __proto=BaseAIController.prototype;
	__proto.start=function(){}
	__proto.dispose=function(){
		if(this.isStartLoop){
			this.isStartLoop=false;
			Laya.timer.clear(this,this.loop);
		}
		if(this.curAIAction){
			this.curAIAction.sleep();
		}
		this.curAIAction=null;
	}

	__proto.switchAction=function(action){
		if(this.curAIAction==action){
			return;
		}
		if(this.curAIAction){
			this.curAIAction.sleep();
		}
		this.lastAIAction=this.curAIAction;
		this.curAIAction=action;
		if(this.curAIAction){
			this.curAIAction.active();
			if(!this.isStartLoop){
				this.isStartLoop=true;
				Laya.timer.loop(200,this,this.loop,null,true,true);
			}
		}
		else{
			if(this.isStartLoop){
				this.isStartLoop=false;
				Laya.timer.clear(this,this.loop);
			}
		}
	}

	__proto.loop=function(){
		if(this.curAIAction){
			this.curAIAction.exec();
		}
	}

	return BaseAIController;
})()


