//class com.xq.rpg.buffer.BufferManager
var BufferManager=(function(){
	function BufferManager(){
		/**buffer效果配置表数据*/
		this.cfgData=null;
		/**buff字典*/
		this.buffDic=null;
		/**屏蔽某类技能*/
		this.hideSkillObj=null;
		this.cfgData=CfgManager.getTableCfg("XiaoGuoBiao");
		this.buffDic=new Object();
		this.hideSkillObj={};
		this.hideSkillObj[230]=[];
	}

	__class(BufferManager,'com.xq.rpg.buffer.BufferManager');
	var __proto=BufferManager.prototype;
	__proto.createBuff=function(buffmsg){
		var buff=new BaseBuffer();
		buff.guid=buffmsg.buffGuid;
		var cfgObj=this.cfgData.getItemByField("effectid",buffmsg.buffId);
		buff.bindVo(cfgObj);
		this.buffDic[buffmsg.buffGuid]=buff;
		return buff;
	}

	__proto.getCofById=function(buffId){
		return this.cfgData.getItemByField("effectid",buffId);
	}

	/**添加buff\*/
	__proto.addBuff=function(target,buffmsg){
		if(buffmsg.buffId=="")
			return null;
		var buff=this.buffDic[buffmsg.buffGuid];
		if(!buff){
			buff=this.createBuff(buffmsg);
		}
		else{
		}
		if(buff.effectid.indexOf("bf")!=-1 && buff.head_uri){
			if(target.warRune){
				var ef=PathDefine.SKILL+buff.head_uri+"/"+buff.head_uri+".amt";
				target.warRune.fight(true,ef);
			}
			delete this.buffDic[buffmsg.buffGuid]
			return null;
		}
		buff.layers=buffmsg.layers;
		buff.target=target;
		buff.djsTime=buffmsg.leftTime;
		buff.start();
		target.updateBuff(buff,false);
		if((target instanceof com.xq.rpg.unit.MainPlayer )){
			var ary=this.hideSkillObj[buff.speType];
			if(ary){
				ary.push(buff.speValue);
				console.log("增加了一个屏蔽技能的buff");
			}
		}
		EventCenter.instance.event("BUFF_UPDATE",[buffmsg.buffId,]);
		return buff;
	}

	/**移除buff*/
	__proto.removeBuff=function(buffId){
		var buff=this.buffDic[buffId];
		if(buff){
			if((buff.target instanceof com.xq.rpg.unit.MainPlayer )){
				var ary=this.hideSkillObj[buff.speType];
				if(ary){
					var index=ary.indexOf(buff.speValue);
					if(index >-1){
						ary.splice(index,1);
						console.log("移除了一个屏蔽技能的buff");
					}
				}
			}
			buff.target.updateBuff(buff,true);
			buff.dispose();
			delete buffId[buffId];
		}
	}

	/**更新buff*/
	__proto.updateBuff=function(buffmsg){
		var buff=this.buffDic[buffmsg.buffGuid];
		console.log("收到了更新buff协议！",buffmsg.buffGuid);
		if(!buff)
			return;
		buff.layers=buffmsg.layers;
		buff.djsTime=buffmsg.leftTime;
		buff.start();
		buff.target.updateBuff(buff,false);
	}

	/**获取特殊buff的字符串*/
	__proto.hideSpeStr=function(type){
		var tp=com.xq.rpg.buffer.BufferManager.ins.hideSkillObj[type];
		var skillBf=tp? tp.join(""):"";
		return skillBf;
	}

	__getset(1,BufferManager,'ins',function(){
		return BufferManager._ins=BufferManager._ins|| new BufferManager();
	});

	BufferManager.HideSkill=230;
	BufferManager._ins=null;
	return BufferManager;
})()


