/**
*伤害管理类
*2019-10-23
*@auther gfr
*/
//class com.xq.rpg.HarmManager
var HarmManager=(function(){
	function HarmManager(){
		this._player=null;
		this._hejiCount=0;
		this._combCount=0;
		this._player=Model.game.mPlayer;
	}

	__class(HarmManager,'com.xq.rpg.HarmManager');
	var __proto=HarmManager.prototype;
	/**计算该次伤害的伤害类型 前端假计算*/
	__proto.calculateHarmType=function(attaker){
		var vo=attaker.vo;
		var per=Math.max(((vo.critical-(Math.random()*vo.critical))*0.0000012)+0.1,0);
		var random=Math.random();
		if(random < per){
			return 2;
		}
		return 0;
	}

	/**计算暴击伤害*/
	__proto.calculateBaoJiHarm=function(attaker,hurt){
		var vo=attaker.vo;
		return hurt *(1.5+vo.slay);
	}

	/**受到伤害*/
	__proto.hurt=function(type,value,target,dir,distance){
		(distance===void 0)&& (distance=50);
		if(target==Game.getInstance().player)return;
		var text;
		var anitype=0;
		var suffix;
		var offset=25;
		var offsetY=0;
		var offsetX=0;
		var time=700;
		var playerx=this._player.x;
		var space=0;
		switch(type){
			case 10000:
				anitype=105;
				text=CommonUtil.harmChange(value);
				suffix="normal";
				var flag=target.x<this._player.x;
				offsetX=flag?-30:30;
				offsetY=0;
				target.beBit();
				break ;
			case 0:
				anitype=this.getDeffDirAni(target);
				text=CommonUtil.harmChange(value);
				suffix="normal";
				offsetX=target.x<this._player.x?-30:30;
				offsetY=0;
				target.beBit();
				break ;
			case 2:
				if(value <=0)
					return;
				anitype=this.getDeffDirAni(target);
				suffix="bj";
				text="b"+CommonUtil.harmChange(value);
				offsetX=target.x<this._player.x?-50:50;
				target.beBit();
				break ;
			case 13:
				time=1000;
				var curHjid=Model.heji.getChuZhanIdByType(1);
				var hjSkill=Model.heji.getCurUseSkillId(curHjid);
				this._hejiCount=SkillManager.ins.getData(hjSkill).maxTimes;
				anitype=this.getSameDirAni(target);
				var count=0;
				flag=target.x<this._player.x;
				offsetX=flag?-180:180;
				count=flag?-20:20;
				var value1=Math.floor(value/3);
				suffix="heji";
				text="c"+CommonUtil.harmChange(value1);
				for(var i=0;i<this._hejiCount;i++){
					offsetY=-(i*80);
					offsetX+=count;
					FontUtil.showSceneEffectText(text,target,anitype,dir,time,distance,offset,suffix,space,type,offsetX,offsetY);
				}
				target.beBit();
				return;
			case 1:
				text="t";
				anitype=1;
				suffix="diushi";
				break ;
			case 30:
				text="t";
				anitype=1;
				suffix="wudi";
				break ;
			case 4:
				text="b+"+value;
				anitype=2;
				suffix="huihu";
				time=4000;
				break ;
			case 5:
				text="+"+CommonUtil.harmChange(value);
				anitype=2;
				suffix="huifubaoji";
				break ;
			case 12:
				anitype=2;
				suffix="bj";
				text="b"+CommonUtil.harmChange(value);
				target.beBit();
				break ;
			case 14:
				anitype=this.getDeffDirAni(target);
				offsetY=HarmOffsetYEnum.OFFSETY_MC;
				suffix="mc";
				text="a"+CommonUtil.harmChange(value);
				flag=target.x<this._player.x;
				offsetX=flag?-80:80;
				target.beBit();
				break ;
			case 15:
				debugger;
				break ;
			case 29:
				CodeLinkUtil.ins().optionPrompt(CodeMgr.ins.getStringByCode(6));
				break ;
			case 16:
				anitype=this.getDeffDirAni(target);
				offsetY=HarmOffsetYEnum.OFFSETY_ZJ;
				suffix="zj";
				text="a"+CommonUtil.harmChange(value);
				offset=0;
				flag=target.x<this._player.x;
				offsetX=flag?-80:80;
				target.beBit();
				break ;
			case 17:
				anitype=this.getDeffDirAni(target);
				offsetY=HarmOffsetYEnum.OFFSETY_MS;
				suffix="ms";
				text="a"+CommonUtil.harmChange(value);
				offset=0;
				flag=target.x<this._player.x;
				offsetX=flag?-80:80;
				target.beBit();
				break ;
			case 18:
				anitype=this.getDeffDirAni(target);
				offsetY=HarmOffsetYEnum.OFFSETY_NS;
				suffix="ns";
				text="a"+CommonUtil.harmChange(value);
				offset=0;
				flag=target.x<this._player.x;
				offsetX=flag?-80:80;
				target.beBit();
				break ;
			case 19:
				anitype=this.getDeffDirAni(target);
				suffix="zy";
				text="a"+CommonUtil.harmChange(value);
				flag=target.x<this._player.x;
				offsetX=flag?-50:50;
				target.beBit();
				break ;
			case 31:
				anitype=this.getDeffDirAni(target);
				suffix="ws";
				text="a"+CommonUtil.harmChange(value);
				flag=target.x<this._player.x;
				offsetX=flag?-100:100;
				target.beBit();
				break ;
			default :
				text=""+CommonUtil.harmChange(value);
				anitype=1;
				suffix="normal";
				offset=0;
				break ;
			}
		FontUtil.showSceneEffectText(text,target,anitype,dir,time,distance,offset,suffix,space,type,offsetX,offsetY);
	}

	/**根据相对位置来决定动画*/
	__proto.getDeffDirAni=function(target){
		if(target.x<Model.game.mPlayer.x){
			return 5;
		}
		else{
			return 4;
		}
	}

	/**根据相同位置来决定动画*/
	__proto.getSameDirAni=function(target){
		if(target.x<Model.game.mPlayer.x){
			return 4;
		}
		else{
			return 5;
		}
	}

	__getset(1,HarmManager,'ins',function(){
		return HarmManager._ins=HarmManager._ins|| new HarmManager;
	});

	HarmManager._ins=null;
	return HarmManager;
})()


