		this.serHistory=null;
		/**已购买次数*/
		this.buyCount=0;
		this.serGuWuCount=0;
		/**pvp奖励表*/
		this.rewardTab=null;
		/**是否打开金台拜将*/
		this.isOpening=false;
		/**已挑战次数..*/
		this.hasChallge=0;
		/**是否已经退出场景*/
		this.isExitScene=false;
		this.hasCount=0;
