		var _ifCanUp=false;
		if(!this.ringInfo){
			return;
		};
		var _curRingLv=this.ringInfo.ringLevel;
		for(var i=0;i<len;i++){
			var ele=arr[i];
			var cof=ele.getCfgData();
			var curSkillLv=ele.getValue("level");
			var skillId=cof.skill;
			_ifActive=curSkillLv!=0;
			var nextSkillCof=SkillManager.ins.getData(skillId,false,curSkillLv+1);
			if(nextSkillCof){
				if(_ifActive){
					var nextLvNeed=nextSkillCof.levelneed;
					_ifCanUp=nextLvNeed<=_curRingLv;
				}
				else{
					var activeNeed=parseInt(cof.level);
					_ifCanUp=activeNeed<=_curRingLv;
				}
			}
			else{
				_ifCanUp=false;
			}
			if(_ifCanUp){
				this._red.showRedPoint("hunjie","skillRed","MarriageRingRed");
				return;
			}
		}
		this._red.hideRedPoint("hunjie","skillRed","MarriageRingRed");
