		if(nextcfg){
			var arr=nextcfg.cost.split(":");
			var id=arr[0];
			var onceNeed=parseInt(arr[1]);
			var needJF=nextcfg.need-this.marryInfo.qinmiduPro;
			var needNum=Math.ceil((needJF/nextcfg.exp)*onceNeed);
			return id+":"+needNum;
		}
