//class com.xq.rpg.model.ModulesTypeModel
var ModulesTypeModel=(function(){
	function ModulesTypeModel(){
		this._cof=null;
		this._moduleDc=null;
		this._cof=CfgManager.getTableCfg("modulesType");
	}

	__class(ModulesTypeModel,'com.xq.rpg.model.ModulesTypeModel');
	var __proto=ModulesTypeModel.prototype;
	/**根据模块类型和功能枚举获取对应数据*/
	__proto.getDataByModuleAndEnum=function(moduleType,enumId){
		var id=moduleType+"-"+enumId;
		var ele=this.moduleDc.getElement(id);
		return ele;
	}

	__getset(0,__proto,'moduleDc',function(){
		if(!this._moduleDc){
			this._moduleDc=new DataContainer();
			var arr=this._cof.objectDataArray;
			var len=arr.length;
			var _ele;
			var _cofO;
			for(var i=0;i<len;i++){
				_cofO=arr[i];
				_ele=new DataElement(_cofO);
				var id=_cofO["moduleType"]+"-"+_cofO["enumId"];
				this._moduleDc.addElement(id,_ele);
			}
		}
		return this._moduleDc;
	});

	return ModulesTypeModel;
})()


