var PaylineRoleData=(function(){
	function PaylineRoleData(){
		/**roleID*/
		this.roleId=NaN;
		/**限时进阶丹进阶回退时间*/
		this.xianshiTime=0;
		/**存储当前所有进阶的阶数*/
		this.curJieData=[];
		/**存储当前所有进阶（新）等级数*/
		this.curLevelData={};
		/**进阶线信息*/
		this.myPayLineInfo={};
		/**每种进阶线总战力字典 （基础+丹药+装备+技能）*/
		this.paylineAllFightDic={};
		this.zhufuValueInfo=new Dictionary();
		this.skillInfo=new Dictionary();
		this.zhuhunDic=new Dictionary();
		this.gongmingDic=new Dictionary();
	}

	__class(PaylineRoleData,'com.xq.rpg.model.PaylineRoleData');
	var __proto=PaylineRoleData.prototype;
	/**更新祝福值*/
	__proto.updateZhuFu=function(type,value){
		var info=this.myPayLineInfo[type];
		if(info){
			info.luckyValue=value;
		}
	}

	/**更新星级*/
	__proto.updateStar=function(type,star){
		var info=this.myPayLineInfo[type];
		if(info){
			info.stars=star;
		}
		this.calcLevel(type);
	}

	/**获取技能信息*/
	__proto.getSkillInfo=function(type,skillId){
		var ary=this.skillInfo.get(type);
		if(!ary){
			ary=[];
			this.skillInfo.set(type,ary);
		};
		var len=ary.length;
		for (var i=0;i < len;i++){
			var temp=ary[i];
			if(temp.skillId==skillId){
				return temp;
			}
		};
		var msg=new SkillUpPaylineSC();
		msg.roleId=this.roleId;
		msg.type=type;
		msg.skillId=skillId;
		msg.skillLevel=0;
		ary.push(msg);
		return msg;
	}

	/**更新技能等级*/
	__proto.setSkillLv=function(type,skillId,lv){
		var msg=this.getSkillInfo(type,skillId);
		msg.skillLevel=lv;
	}

	/**获取技能等级*/
	__proto.getSkillLv=function(type,skillId){
		var msg=this.getSkillInfo(type,skillId);
		return msg.skillLevel;
	}

	/**获取铸魂信息*/
	__proto.getZhuHunInfo=function(type){
		return this.zhuhunDic.get(type);
	}

	/**获取共鸣信息*/
	__proto.getGongMing=function(type){
		return this.gongmingDic.get(type);
	}

	/**获取培养等级*/
	__proto.getPeiYangLevel=function(type){
		if(this.curLevelData[type]){
			return this.curLevelData[type];
		}
		return 0;
	}

	/**
	*更新注入服务器端数据
	**/
	__proto.updateInfo=function(msg){
		this.myPayLineInfo[msg.type]=msg;
		this.curJieData[msg.type]=msg.jieshu;
		this.xianshiTime=msg.tempTime;
		this.calcLevel(msg.type);
	}

	__proto.calcLevel=function(type){
		var msg=this.myPayLineInfo[type]
		this.curLevelData[msg.type]=(msg.jieshu-1)*10+msg.stars;
	}

	/**更新超级技能*/
	__proto.updateSupeSkill=function(type,huanhuaSkill){
		var msg=this.myPayLineInfo[type];
		if(msg){
			msg.huanhuaSkill=huanhuaSkill;
		}
	}

	return PaylineRoleData;
})()


