//class com.xq.rpg.model.PropModel
var PropModel=(function(){
	function PropModel(){
		/**prop属性模板*/
		this._propCof=null;
		this._propDc=null;
		/**战力系数表*/
		this._zlxsCof=null;
		this._zlxsDc=null;
		this.initCof();
	}

	__class(PropModel,'com.xq.rpg.model.PropModel');
	var __proto=PropModel.prototype;
	__proto.initCof=function(){
		this._propCof=CfgManager.getTableCfg("prop");
		this._zlxsCof=CfgManager.getTableCfg("ZhanLiXiShu");
	}

	//===========prop===========
	__proto.getPropById=function(id){
		var propEle=this.propDc.getElement(id);
		if(!propEle)return [];
		var propArr=[];
		var propCof=propEle.getCfgData();
		var arr=this.zlxsDc.array;
		var len=arr.length;
		var ele;
		var cof;
		var propAttrVo;
		for(var i=0;i<len;i++){
			ele=arr[i];
			cof=ele.getCfgData();
			var name=cof.name;
			var value=parseFloat(propCof[name]);
			if(value){
				propAttrVo=new PropAttrVo();
				propAttrVo.setData([name,value]);
				propArr.push(propAttrVo);
			}
		}
		return propArr;
	}

	/**根据属性名（英文）获取对应属性ID*/
	__proto.getAttrCofByName=function(name){
		var ele=this.zlxsDc.getElement(name);
		if(ele){
			var cof=ele.getCfgData();
			return cof;
		}
		return null;
	}

	/**根据属性名（英文）获取对应属性中文名称*/
	__proto.getCnNameByname=function(name){
		var ele=this.zlxsDc.getElement(name);
		if(ele){
			var cof=ele.getCfgData();
			return cof.mingzi;
		}
		return "";
	}

	/**根据属性名（英文）获取对应属性ID*/
	__proto.getAttrIdByName=function(name){
		var ele=this.zlxsDc.getElement(name);
		if(ele){
			var cof=ele.getCfgData();
			var id=parseInt(cof.id);
			return id;
		}
		return-1;
	}

	__proto.getAttrCofById=function(id){
		var dc=this.zlxsDc.where("id",id,"id");
		var ele=dc.getElement(id);
		if(!ele)return null;
		return ele.getCfgData();
	}

	/**
	*attrType:0：不展示属性1:展示基础属性 2：展示特殊属性
	**/
	__proto.getAttrsByTeShu=function(attrType){
		var dc=this.zlxsDc.where("teshu",attrType,"id");
		return dc.array;
	}

	/**prop数据容器*/
	__getset(0,__proto,'propDc',function(){
		if(!this._propDc){
			this._propDc=new DataContainer();
			CommonUtil.initDataContainer(this._propDc,this._propCof);
		}
		return this._propDc;
	});

	__getset(0,__proto,'zlxsDc',function(){
		if(!this._zlxsDc){
			this._zlxsDc=new DataContainer();
			CommonUtil.initDataContainer(this._zlxsDc,this._zlxsCof,"name");
		}
		return this._zlxsDc;
	});

	return PropModel;
})()


