//class com.xq.rpg.model.ShiZhuangModel
var ShiZhuangModel=(function(){
	function ShiZhuangModel(){
		/**幻化表*/
		this.huanhuaCfg=null;
		/**幻化表数组*/
		this.huanhuaCfgArr=null;
		/**幻化表字典*/
		this.huanhuaCfgDic={};
		/**幻化激活合击信息字典*/
		this.huanhuaHeJiDic={};
		/**已拥有幻化字典*/
		this.huanhuaDic={};
		this.needCfgCha={};
		this.zsSkillAry=null;
		this.huanhuaCfg=CfgManager.getTableCfg("huanhua");
		this.huanhuaCfgArr=this.huanhuaCfg.objectDataArray;
		var len=this.huanhuaCfgArr.length;
		for (var i=0;i < len;i++){
			var attr=new HuanHuaAttr();
			attr.id=this.huanhuaCfgArr[i].huanhuaid;
			attr.level=0;
			this.huanhuaCfgDic[this.huanhuaCfgArr[i].huanhuaid]=attr;
			var canActiveHeJiArr=HejiModel.ins().getCanActiveHeJi(attr.id+"");
			if(canActiveHeJiArr.length > 0){
				this.huanhuaHeJiDic[attr.id]=canActiveHeJiArr;
				}else{
				this.huanhuaHeJiDic[attr.id]=null;
			}
		}
	}

	__class(ShiZhuangModel,'com.xq.rpg.model.ShiZhuangModel');
	var __proto=ShiZhuangModel.prototype;
	/**
	*根据幻化id获取单个时装信息
	*/
	__proto.getCfgById=function(id){
		return this.huanhuaCfg.getItemByField("huanhuaid",id);
	}

	/**
	*根据type获取幻化数组
	*/
	__proto.getCfgByType=function(type){
		return this.huanhuaCfg.getAllItemByFiled("type",type);
	}

	/**根据材料获取幻化配置*/
	__proto.getHuanHuaCfg=function(needitem){
		if(this.needCfgCha[needitem])
			return this.needCfgCha[needitem];
		var ary=this.huanhuaCfg.objectDataArray;
		var len=ary.length;
		for (var i=0;i < len;i++){
			var obj=ary[i]
			if(obj.needitem.indexOf(needitem)!=-1){
				this.needCfgCha[needitem]=obj;
				break ;
			}
		}
		return this.needCfgCha[needitem];
	}

	/**
	*获取专属技能
	*@param id 幻化id
	**/
	__proto.getZsSkillAry=function(id){
		if(!this.zsSkillAry){
			this.zsSkillAry=[];
		};
		var ary=this.zsSkillAry[id]
		if(!ary){
			var obj=this.huanhuaCfg.getItemByField("huanhuaid",id);
			if(obj){
				ary=obj.skill.split(";");
				this.zsSkillAry[id]=ary;
			}
		}
		return ary;
	}

	__proto.getHuanHuaInfoByOne=function(id){
		return this.huanhuaCfg.getItemByField("huanhuaid",id);
	}

	__proto.getHhUrl=function(id,type){
		var url="";
		var cfg=this.getHuanHuaInfoByOne(id);
		if(cfg){
			switch(type){
				case 24:
					url=PathDefine.Cloak+cfg.uires;
					break ;
				case 20:
					url=PathDefine.QiLinBiEff+cfg.res;
					break ;
				case 22:
					url=PathDefine.FABAO+cfg.uires+"/"+cfg.uires+".amt";
					break ;
				}
		}
		return url;
	}

	/**幻化类型 转换成 助战类型*/
	__proto.typeConversion=function(type){
		switch(parseInt(type)){
			case 11:
				return 4;
			case 13:
				return 1;
			case 14:
				return 3;
			case 15:
				return 2;
			default :
				return-1;
			}
	}

	ShiZhuangModel.ins=function(){
		return ShiZhuangModel._ins=ShiZhuangModel._ins||new ShiZhuangModel();
	}

	ShiZhuangModel._ins=null;
	return ShiZhuangModel;
})()


