	TaskModel.getChapterReward=function(str){
		if(!str){
			return [];
		};
		var reward=[];
		var arr=str.split(";");
		var $each_str;
		for($each_str in arr){
			str=arr[$each_str];
			var temp=str.split(":");
			reward[temp[0]]=int(temp[1]);
		}
		return reward;
	}

