/**
*
*技能数据模型
*@author xiangjia
*/
//class com.xq.rpg.skill.model.SkillModel
var SkillModel=(function(){
	function SkillModel(){
		this.roleId=NaN;
		//角色ID
		this.job=null;
		//职业标记
		this.shenJiangType=0;
		/**模块技能对象，保证唯一性*/
		this.moduleObj={};
		this.cdTimeDic={};
		this.jumpkey=["name","queue","opType","rang","width"]
		this.allSkills=new Dictionary();
		this.zhuDongSkills=new Dictionary();
		this.zongMenSkills=new Dictionary();
		this.moduleSkills=new Dictionary();
		this.wuShenSkills=new Dictionary();
	}

	__class(SkillModel,'com.xq.rpg.skill.model.SkillModel');
	var __proto=SkillModel.prototype;
	/**添加主动技能*/
	__proto.addZhuDongSkill=function(skillType,skillVo){
		this.zhuDongSkills.set(skillType ,skillVo);
		this.allSkills.set(skillType ,skillVo);
		skillVo.nextSkillVO=SkillManager.ins.getData(skillVo.skillType,false,skillVo.level+1,false);
	}

	/**添加宗门（被动）技能*/
	__proto.addZongMenSkill=function(skillType,skillVo){
		this.zongMenSkills.set(skillType ,skillVo);
		skillVo.nextSkillVO=SkillManager.ins.getData(skillVo.skillType,false,skillVo.level+1,false);
		this.allSkills.set(skillType ,skillVo);
	}

	/**添加模块主动技能<br/> 为了和主角基础技能区分*/
	__proto.addModelSkill=function(skilltype,vo,mdlType){
		this.moduleSkills.set(skilltype ,vo);
		var temp=this.moduleObj[mdlType];
		if(temp){
			this.removeSkillByType(temp);
		}
		if(vo){
			this.allSkills.set(skilltype ,vo);
			this.moduleObj[mdlType]=skilltype;
		}
	}

	/**
	*移除模块技能
	*/
	__proto.removeSkillByType=function(ski){
		this.moduleSkills.remove(ski);
		this.allSkills.remove(ski);
	}

	/**判断是否主动技能*/
	__proto.isZhuDongSkill=function(skillType){
		return this.zhuDongSkills.get(skillType)!=null;
	}

	/**
	*设置CD时间
	**/
	__proto.resetCDTime=function(skillType,cdTime){
		if(!cdTime){
			cdTime=0;
		}
		if(cdTime==-1){
			this.cdTimeDic[skillType]=-1;
			}else{
			this.cdTimeDic[skillType]=Browser.now()+cdTime;
		}
	}

	/**获取CD时间*/
	__proto.getCdTime=function(skillType){
		if(this.cdTimeDic[skillType]){
			return this.cdTimeDic[skillType];
		}
		return 0;
	}

	__proto.getZhuDongSkill=function(){
		return this.zhuDongSkills.values;
	}

	__proto.getModelSkill=function(){
		return this.moduleSkills.values;
	}

	__proto.updateZhuSkillStatus=function(){
		if(this.shenJiangType!=-1){
			var skillVOArr=this.zhuDongSkills.values;
			var lne=skillVOArr.length;
			for (var i=0;i < lne;i++){
				var skillVO=skillVOArr[i];
				var skillMsg=HeroModel.ins().getSkillMsg(skillVO.skillType)
				if(skillMsg){
					skillVO.isOpened=skillMsg.opened;
					skillVO.level=skillMsg.level;
					skillVO.skillCD=skillMsg.cdTime;
					skillVO.nextSkillVO=SkillManager.ins.getData(skillVO.skillType,false,skillVO.level+1,false);
				}
			}
		}
	}

	__proto.getZongMenSkill=function(){
		return this.zongMenSkills.values;
	}

	/**
	*更新技能等级\CD
	**/
	__proto.updateSkillLevel=function(templateId,level,cd){
		(cd===void 0)&& (cd=-1);
		var skillVo=this.allSkills.get(templateId);
		if(skillVo!=null){
			var newSkillVo=SkillManager.ins.getData(skillVo.skillType,false,level,false);
			if(newSkillVo){
				SkillVO.copyValueFrom(skillVo,newSkillVo,this.jumpkey);
			}
			skillVo.level=level <=0? 1:level;
			skillVo.isOpened=true;
			if(cd !=-1)
				skillVo.skillCD=cd;
			skillVo.nextSkillVO=SkillManager.ins.getData(skillVo.skillType,false,level+1,false);
			this.allSkills.set(templateId,skillVo);
		}
		else if(cd > 0){
			skillVo=SkillManager.ins.getData(templateId);
			if(skillVo){
				skillVo.skillCD=cd;
			}
		}
	}

	/**获取技能信息*/
	__proto.getSkillVo=function(id){
		return this.allSkills.get(id);
	}

	/**添加武神变身主动技能*/
	__proto.addWuShenSkill=function(skillType,skillVo){
		this.wuShenSkills.set(skillType ,skillVo);
		skillVo.skillCD=500;
		this.allSkills.set(skillType ,skillVo);
		skillVo.nextSkillVO=SkillManager.ins.getData(skillVo.skillType,false,skillVo.level+1,false);
	}

	__proto.removeWuShenSkill=function(skillType){
		this.wuShenSkills.remove(skillType);
		this.allSkills.remove(skillType);
	}

	/**移除所有武神技能*/
	__proto.removeAllWuShenSkill=function(){
		var keys=this.wuShenSkills.keys;
		var len=keys.length;
		for(var i=0;i<len;i++){
			this.allSkills.remove(keys[i]);
		}
		this.wuShenSkills.clear();
	}

	/**获取武神变身技能*/
	__proto.getWuShenSkill=function(){
		return this.wuShenSkills.values;
	}

	return SkillModel;
})()


