		var unit=skillVO.curObj;
		var deyTime=skillVO.delayTime;
		var laya=1;
		var boci=0;
		var aryAry=[[200,-450,0.6,35,0],[-50,-500,0.6,-10,0],[100,-500,0.4,-10,0],[-230,-500,0.3,-10,0],[-220,-350,0.5,-10,0],[20,-350,0.5,10,0],[250,-300,0.45,-10,0],[120,-200,0.6,15,0],[-10,50,1,-10,1],[230,-50,0.8,-5,0]
		,[220,230,0.9,-20,1],[-50,200,0.5,10,1],[-270,210,0.9,0,1],[-200,-100,0.6,-10,0]];
