	CommonUtil.getBornPosArr=function(num,space){
		(space===void 0)&& (space=15);
		var arr=[];
		var n=0;
		var startNum=1;
		var row=0;
		while(n < num){
			n+=startNum;
			arr.push([0,row]);
			var len=startNum>>1;
			for(var i=1;i<=len;i++){
				var offx1=i;
				var offx2=-i;
				var offy=row;
				arr.push([offx1,offy]);
				arr.push([offx2,offy]);
			};
			var nextStartNum=startNum+2;
			if((num-n)< (startNum+1)/2 *(startNum-1)/2){
				startNum=startNum-2;
				}else{
				startNum=nextStartNum;
			}
			startNum=Math.max(startNum,1);
			row++;
		};
		var offRow=row>>1;
		len=arr.length;
		for(i=0;i < len;i++){
			var pos=arr[i];
			pos[0]=pos[0] *space;
			pos[1]=(pos[1]-offRow)*space;
		}
		return arr;
	}

	CommonUtil.changeDir=function(x1,y1,x2,y2){
		var r=Math.atan2(y2-y1,x2-x1)/ Math.PI *180;
		var d=r+180;
		if(d < 90){
			return 5;
		}
		else if(d < 180){
			return 3;
		}
		else if(d < 270){
			return 1;
		}
		else{
			return 7;
		}
	}

	CommonUtil.getRelativeDirArr=function(x1,y1,x2,y2){
		var dirType=CommonUtil.changeDir(x1,y1,x2,y2);
		switch(dirType){
			case 5:
				return [1,1];
			case 6:
				return [1,0];
			case 7:
				return [1,-1];
			case 0:
				return [0,-1];
			case 1:
				return [-1,-1];
			case 2:
				return [-1,0];
			case 3:
				return [-1,1];
			case 4:
				return [0,1];
			}
		return [];
	}

	CommonUtil.getRotation=function(x1,y1,x2,y2){
		var r=Math.atan2(y2-y1,x2-x1)/ Math.PI *180+180;
		return r;
	}

	CommonUtil.radianToAngle=function(radian){
		return radian*180/Math.PI;
	}

	CommonUtil.angleToRadian=function(angle){
		return angle/180*Math.PI;
	}

	CommonUtil.getDistance=function(x1,y1,x2,y2){
		var x=x1-x2;
		var y=y1-y2;
		var distance=Math.sqrt((x*x)+(y*y));
		return distance;
	}

	CommonUtil.isInRange=function(cx,cy,tx,ty,radius){
		if(Math.abs(cx-tx)> radius){
			return false;
		}
		if(Math.abs(cy-ty)>radius){
			return false;
		}
		return true;
	}

	CommonUtil.isTheNextDay=function(lastTime,curTime){
		var s=Math.floor(curTime/1000);
		var min=Math.floor(s/60);
		var h=Math.floor(min/60);
		h=h%24;
		min=min%60;
		s=s%60;
		var lingchen=curTime-(h*60*60*1000)-(min*60*1000)-(s*1000);
		return (lastTime<lingchen);
	}

	CommonUtil.getNumDig=function(num){
		var d=1;
		var m=Math.floor(num/10);
		while(m>0){
			d++;
			num /=10;
			m=Math.floor(num/10);
		}
		return d;
	}

	CommonUtil.formatDate=function(time,type,isTimestap){
		(type===void 0)&& (type=0);
		(isTimestap===void 0)&& (isTimestap=true);
		if(isTimestap){
			var date=new Date(time);
			var m=date.getMinutes();
			var d=date.getDate();
			var s=date.getSeconds();
			var h=date.getHours();
			var mouth=date.getMonth()+1;
			var n=date.getFullYear();
		}
		else{
			if(time<=0)
				time=0;
			s=Math.floor(time/1000);
			m=Math.floor(s/60);
			h=Math.floor(m/60);
			d=Math.floor(h/24);
		};
		var hs=(h % 24)+"";
		var hb=h+"";
		var ht=hb;
		var ms=(m % 60)+"";
		var mb=m+"";
		var ss=(s % 60)+"";
		var sb=s+"";
		if(parseInt(hs)<10){
			hs="0"+hs;
		}
		if(parseInt(hb)<10){
			hb="0"+hb;
		}
		if(parseInt(ht)<100){
			ht="0"+ht;
			if(parseInt(ht)<10){
				ht="0"+ht;
			}
		}
		if(parseInt(ms)<10){
			ms="0"+ms;
		}
		if(parseInt(mb)<10){
			mb="0"+mb;
		}
		if(parseInt(ss)<10){
			ss="0"+ss;
		}
		if(parseInt(sb)<10){
			sb="0"+sb;
		}
		switch(type){
			case 0:
				return d+"天"+hs+"小时"+ms+"分钟";
			case 1:
				return hs+":"+ms+":"+ss;
			case 2:
				return hs+":"+ms;
			case 3:
				return n+"-"+mouth+"-"+d+" "+hs+":"+ms;
			case 4:
				if(d!=0){
					return d+"天"+hs+"小时"+ms+"分钟"+ss+"秒";
					}else if(parseInt(hs)!=0){
					return hs+"小时"+ms+"分钟"+ss+"秒";
					}else {
					return ms+"分钟"+ss+"秒";
				}
			case 5:
				return ms+"分"+ss+"秒";
			case 6:
				return n+"年"+mouth+"月"+d+"日"+hs+":"+ms+":"+ss;
			case 7:
				return n+"年"+mouth+"月"+d+"日";
			case 8:
				return hs+":"+ms+":"+ss;
			case 9:
				return d+"天";
			case 10:
				return hs+"小时"+ms+"分钟"+ss+"秒";
			case 11:
				return hs+"小时"+ms+"分";
			case 12:
				return h+"小时";
			case 13:
				return ms+":"+ss;
			case 14:
				return ss;
			case 15:
				if(h!=0){
					return hs+":"+ms+":"+ss;
				}
				return ms+":"+ss;
			case 16:
				return ms+"mi"+ss+"s";
			case 17:
				return ss+"s";
			case 18:
				return mouth+"月"+d+"日-"+hs+":"+ms;
			case 19:
				return hb+":"+ms+":"+ss;
			case 20:
				return d.toString();
			case 21:
				return d+"天"+hs+":"+ms+":"+ss;
			case 22:
				return mouth+":"+d;
			case 23:
				return mb+":"+ss;
			case 24:
				return ht+":"+ms+":"+ss;
			case 25:
				return h+":"+ms+":"+ss;
			case 26:
				return d+":"+hs+":"+ms+":"+ss;
			case 27:
				return d+"天"+hs+"时"+ms+"分"+ss+"秒";
			case 28:
				if(d!=0){
					return d+"天"+hs+"时";
					}else if(parseInt(hs)!=0){
					return hs+"时"+ms+"分";
					}else {
					return ms+"分";
				}
			case 29:
				if(d!=0){
					if(d>7){
						return "超过7天";
					}
					else{
						return d+"天"+hs+"小时";
					}
					}else if(parseInt(hs)!=0){
					return (h % 24)+"小时";
					}else if (parseInt(ms)!=0){
					return (m % 60)+"分钟";
				}
				else{
					return "1分钟";
				}
			case 30:
				if(d!=0){
					return d+"天";
					}else if(parseInt(hs)!=0){
					return (h % 24)+"小时";
					}else if (parseInt(ms)!=0){
					return (m % 60)+"分钟";
				}
				else{
					return s+"秒";
				}
			}
		return "请设置格式化类型";
	}

	CommonUtil.compareTimes=function(data,start,end){
		var starts=start.split(":");
		var ends=end.split(":");
		var startMin=parseInt(starts[0])*60+parseInt(starts[1]);
		var endMin=parseInt(ends[0])*60+parseInt(ends[1]);
		var curMin=data.getHours()*60+data.getMinutes();
		if(curMin < startMin){
			return 1;
		}
		else if(curMin >=endMin){
			return 0;
		}
		else{
			return 2;
		}
	}

	CommonUtil.checkIsInSevenDay=function(){
		var battleStartRegularTime=NaN;
		if(NetMgr.ins().serverVO.combineTime > 0){
			battleStartRegularTime=CommonUtil.mergeTime();
			}else{
			if(!CommonUtil.openDate)
				CommonUtil.openDate=new Date(NetMgr.ins().serverVO.openTime);
			var offsetTime=(CommonUtil.openDate.getHours()*3600+CommonUtil.openDate.getMinutes()*60)*1000;
			battleStartRegularTime=NetMgr.ins().serverVO.openTime-offsetTime+7 *CommonUtil.oneDayMileSeconds;
		};
		var curServiceTime=ServerTimeAction.ins().serverTimer;
		if(curServiceTime < battleStartRegularTime){
			var date=new Date(battleStartRegularTime);
			var date1=ServerTimeAction.ins().serverDate;
			return ((date.getDay()+7-date1.getDay())%7)+1;
		}
		else{
			return 0;
		}
	}

	CommonUtil.mergeTime=function(){
		if(!CommonUtil.combineDate)
			CommonUtil.combineDate=new Date(NetMgr.ins().serverVO.combineTime);
		var offsetTime=(CommonUtil.combineDate.getHours()*3600+CommonUtil.combineDate.getMinutes()*60)*1000;
		return NetMgr.ins().serverVO.combineTime-offsetTime+7 *CommonUtil.oneDayMileSeconds;
	}

	CommonUtil.getNextOpenTime=function(server,times,kaifuDay,kaifutimes,hefuDay,hefutimes){
		(kaifuDay===void 0)&& (kaifuDay=0);
		(kaifutimes===void 0)&& (kaifutimes="");
		(hefuDay===void 0)&& (hefuDay=0);
		(hefutimes===void 0)&& (hefutimes="");
		var firsts=times.split("[");
		var day=server.getDay()==0 ? 7 :server.getDay();
		var thirTime=String(firsts[firsts.length-1]).split("]")[0];
		var timearea=thirTime.split("-");
		var startTimes=timearea[0];
		var endTimes=timearea[1];
		var sTimes=startTimes.split(":");
		var eTimes=endTimes.split(":");
		var sHorus=parseInt(sTimes[0]);
		var sMins=parseInt(sTimes[1]);
		var eHorus=parseInt(eTimes[0]);
		var eMins=parseInt(eTimes[1]);
		var kaifus=kaifutimes.split(";");
		var dddd;
		if(CommonUtil.checkIsInSevenDay()&& kaifus.length>0 && kaifus[0]!=""){
			for (var i=0;i < kaifus.length;i++){
				if(kaifus[i]==kaifuDay){
					var openType=CommonUtil.compareTimes(server,startTimes,endTimes);
					dddd=new Date(server.getTime()+(parseInt(kaifus[i])-kaifuDay)*24 *3600 *1000+CommonUtil.getTwoTimeSub(server.getHours(),server.getMinutes(),server.getSeconds(),sHorus,sMins));
					return [dddd,openType];
				}
			}
		}
		else{
			openType=CommonUtil.compareTimes(server,startTimes,endTimes);
			for (i=1;i < firsts.length-1;i++){
				var sec=firsts[i];
				var time=sec.split("]")[0];
				if(time=="*")
					continue ;
				var weks=time.split(",");
				for (var j=0;j < weks.length;j++){
					var wek=parseInt(weks[j].substr(1));
					if((day < wek || (day==wek && openType !=0))&& (wek-day+kaifuDay)> 7){
						dddd=new Date(server.getTime()+(wek-day)*24 *3600 *1000+CommonUtil.getTwoTimeSub(server.getHours(),server.getMinutes(),server.getSeconds(),sHorus,sMins));
						return [dddd,openType];
					}
				}
				for (j=0;j < weks.length;j++){
					wek=parseInt(weks[j].substr(1));
					if(day <=wek+7){
						dddd=new Date(server.getTime()+(wek+7-day)*24 *3600 *1000+CommonUtil.getTwoTimeSub(server.getHours(),server.getMinutes(),server.getSeconds(),sHorus,sMins));
						return [dddd,openType];
					}
				}
			}
		}
		return null;
	}

	CommonUtil.getTwoTimeSub=function(hour1,mins1,sec1,hour2,mins2,sec2){
		(hour1===void 0)&& (hour1=0);
		(mins1===void 0)&& (mins1=0);
		(sec1===void 0)&& (sec1=0);
		(hour2===void 0)&& (hour2=0);
		(mins2===void 0)&& (mins2=0);
		(sec2===void 0)&& (sec2=0);
		return (((hour2-hour1)*60+(mins2-mins1))*60+(sec2-sec1))*1000;
	}

	CommonUtil.checkActivitySteak=function(activity,server,isOpen){
		if(activity.getFullYear()==server.getFullYear()&& activity.getMonth()==server.getMonth()&& activity.getDay()==server.getDay()){
			return true;
		}
		return false;
	}

	CommonUtil.getAttributeInfo=function(obj){
		if(!obj){
			console.error("传入的obj为null,请注意检查，点击继续!");
			return [];
		};
		var tempAry=[];
		if(obj.hitpoints > 0)
			tempAry.push(["生命",obj.hitpoints,2]);
		if(obj.physicdamage > 0)
			tempAry.push(["攻击",obj.physicdamage,0]);
		if(obj.physicdefence > 0)
			tempAry.push(["防御",obj.physicdefence,1]);
		if(obj.critical > 0)
			tempAry.push(["暴击",obj.critical,5]);
		if(obj.hitrate > 0)
			tempAry.push(["命中",obj.hitrate,3]);
		if(obj.dodge > 0)
			tempAry.push(["闪避",obj.dodge,4]);
		if(obj.tenacity > 0)
			tempAry.push(["韧性",obj.tenacity,6]);
		if(obj.peiyangPercentage > 0)
			tempAry.push(["全属性",obj.peiyangPercentage,7]);
		if(obj.formuleb > 0){
			tempAry.push(["合击伤害",obj.formuleb,8]);
		}
		return tempAry.concat();
	}

	CommonUtil.getAttributeObj=function(obj){
		var tempObj=new Object();
		tempObj.hitpoints=obj.hitpoints?obj.hitpoints:0;
		tempObj.physicdamage=obj.physicdamage?obj.physicdamage:0;
		tempObj.physicdefence=obj.physicdefence?obj.physicdefence:0;
		tempObj.critical=obj.critical?obj.critical:0;
		tempObj.hitrate=obj.hitrate?obj.hitrate:0;
		tempObj.dodge=obj.dodge?obj.dodge:0;
		tempObj.tenacity=obj.tenacity?obj.tenacity:0;
		return tempObj;
	}

	CommonUtil.numFormat=function(num,type,isRank,fix){
		(type===void 0)&& (type=0);
		(isRank===void 0)&& (isRank=false);
		(fix===void 0)&& (fix=1);
		if(isRank){
			if(num < 10000*10000){
				return num+"";
			}
			else{
				return Math.floor((num/(10000*10000)))+"亿"+Math.floor(num%(10000*10000)/10000)+"万";
			}
		}
		else{
			if (num < 10000){
				return num+"";
			}
			else if(num < 10000*10000){
				if(type==0){
					return (num/10000).toFixed(fix)+"万";
				}
				else{
					return (num/10000).toFixed(fix)+"w";
				}
				}else{
				var yi=Math.floor(num/(10000*10000))+"";
				var wan=Math.floor(num%(10000*10000)/ 10000)+"";
				if(type==0){
					if(parseInt(wan)> 0){
						return yi+"亿"+wan+"万";
					}
					else{
						return yi+"亿";
					}
				}
				else{
					return yi+"亿"+wan+"w";
				}
			}
		}
	}

	CommonUtil.numFormat2=function(num){
		if(num>(10000*10000)){
			return (num/(10000*10000)).toFixed(2)+"亿";
		}
		else if(num>10000){
			return (num/10000).toFixed(2)+"万";
		}
		else{
			return num.toString();
		}
	}

	CommonUtil.numFormat3=function(num){
		if(num>=(10000*10000)){
			return (num/(10000*10000)).toFixed(2)+"亿";
		}
		else if(num>=1000000){
			return (num/10000).toFixed(2)+"万";
		}
		else{
			return num.toString();
		}
	}

	CommonUtil.numFormat4=function(num){
		if(isNaN(num))num=0;
		if(num>=(10000*10000)){
			return Math.floor((num/(10000*10000)))+"y"+Math.floor(num%(10000*10000)/10000)+"w";
		}
		else{
			return num.toString();
		}
	}

