	CommonUtil.getAttrTotal=function(atrAry1,atrAry2){
		var ary=[];
		var len=atrAry1.length > atrAry2.length? atrAry1.length :atrAry2.length;
		for (var i=0;i < len;i++){
			var tempAtr=new AttributeMsg();
			var atr1=atrAry1[i];
			var atr2=atrAry2[i];
			if(atr1){
				tempAtr.attrId=atr1.attrId;
				tempAtr.attrValue=atr1.attrValue;
			}
			if(atr2){
				if(tempAtr.attrId){
					tempAtr.attrValue+=atr2.attrValue;
				}
				else{
					tempAtr.attrId=atr2.attrId;
					tempAtr.attrValue=atr2.attrValue;
				}
			}
			ary.push(tempAtr);
		}
		return ary;
	}

