//class com.xq.util.DateTimeUtil
var DateTimeUtil=(function(){
	function DateTimeUtil(){}
	__class(DateTimeUtil,'com.xq.util.DateTimeUtil');
	DateTimeUtil.checkIsToDay=function(_time){
		var startN=DateTimeUtil.getTodayNumber(0,0,0);
		var endN=DateTimeUtil.getTodayNumber(23,59,59);
		if(_time >=startN && _time <=endN)
			return true;
		return false;
	}

	DateTimeUtil.getTodayNumber=function(h,m,s,_time){
		(h===void 0)&& (h=0);
		(m===void 0)&& (m=0);
		(s===void 0)&& (s=0);
		(_time===void 0)&& (_time=0);
		if(_time > 0)
			var today=new Date(_time);
		else
		today=new Date(Mgr.curTime.serverTimer);
		today.setHours(h,m,s);
		return today.getTime();
	}

	DateTimeUtil.daojishi=function(time){
		var count=time-Mgr.curTime.serverTimer;
		if(count > 0)
			return count;
		else{
			return 0;
		}
	}

	return DateTimeUtil;
})()


