//class com.xq.util.ExpBallManager
var ExpBallManager=(function(){
	function ExpBallManager(){
		/**计数器*/
		this._tiMer=0;
		this._mgr=null;
		/**经验球对象*/
		/**是否激活主角光环状态*/
		this._stAt=0;
		/**缓存数组*/
		this._cache=null;
		/**显示数组*/
		this._expBallarr=null;
		this._expInfoVo=null;
		/**可领取次数*/
		this.lqNum=0;
		/**生成时间间隔*/
		this._starTtimer=0;
		/**销毁时间间隔*/
		this._endtimer=0;
		this._generateBallNum=0;
		/**生成球的时间(依次增加)*/
		this._generateBalltimer=0;
		/**球id数组*/
		this._ballIdarr=null;
		/**球的坐标点数组*/
		this._expBallpoint=null;
		this._expBallVo=null;
		this._expBallVo=new ExpBallVo();
	}

	__class(ExpBallManager,'com.xq.util.ExpBallManager');
	var __proto=ExpBallManager.prototype;
	// }
	__proto.starttimer=function(_starttimer,endtimer){
		Laya.timer.clearAll(this);
		this._mgr=Mgr.jingyan;
		this._cache=[];
		this._expBallarr={};
		this._ballIdarr=[];
		this._starTtimer=_starttimer;
		this._endtimer=endtimer;
		this._generateBallNum=5;
		this._tiMer=0;
		this._generateBalltimer=_starttimer;
		this._stAt=Mgr.zhuJueGuangHuanM.getStat();
		Laya.timer.loop(1000,this,this.timeManage);
		if(this._stAt==0){
			EventCenter.instance.on("UpdateTeQuanKaInfo",this,this.autoLq);
		}
	}

	__proto.timeManage=function(){
		this._tiMer++;
		if(this._tiMer%this._starTtimer==0&&this._generateBallNum>0){
			Mgr.jingyanPro.sendGenerateExpBall();
			this._generateBallNum--;
			this._stAt=Mgr.zhuJueGuangHuanM.getStat();
			return;
		}
		if(this._stAt!=0){
			if(this._tiMer%(this._generateBalltimer+5)==0){
				this.ergOdic();
				this._generateBalltimer+=this._starTtimer;
			}
			}else{
			if(this._tiMer%(this._generateBalltimer+this._endtimer)==0){
				this.ergOdic();
				this._generateBalltimer+=this._starTtimer;
			}
		}
	}

	/**遍历数组*/
	__proto.ergOdic=function(){
		var expobj;
		var ballId=0;
		if(this._ballIdarr.length==0){
			Laya.timer.clear(this,this.timeManage);
			return;
		}
		for(var i=0;i<this._ballIdarr.length;i++){
			ballId=this._ballIdarr[i];
			expobj=this._expBallarr[ballId];
			if(expobj){
				if(this._stAt!=0){
					if(expobj.haloendtimer==this._generateBalltimer+5){
						this.delayedLq(expobj.ballId);
						break ;
					}
					}else{
					if(expobj.endtimer==this._generateBalltimer+this._endtimer){
						this.autoRemove(expobj.ballId);
						break ;
					}
				}
			}
		}
	}

	/**生成小球后获取数据*/
	__proto.getExpBallData=function(){
		this._expInfoVo=this._mgr.getExpInfoVo();
		var ballId=this._expInfoVo.ballId;
		var skin=PathDefine.getExpBallRes(this._expInfoVo.exp/10000+"W");
		var endtimer=this._tiMer+this._endtimer;
		var haloendtimer=this._tiMer+5;
		this.lqNum=this._expInfoVo.times;
		this._expBallVo.ballId=ballId;
		this._expBallVo.skin=skin;
		this._expBallVo.endtimer=endtimer;
		this._expBallVo.haloendtimer=haloendtimer;
		this.addExpBall(this._expBallVo);
	}

	/**添加小球*/
	__proto.addExpBall=function(_expBallVo){
		this._expBallobj=this.getElement();
		var Random=Math.random();
		var dirdev=0;
		if(Random<0.5){
			dirdev=1;
			}else{
			dirdev=-1;
		}
		if(!this._expBallobj){
			this._expBallobj=UIMgrR.newInstanceByIClass(com.xq.view.modules.common.IExpBallView);
		};
		var posx=Math.floor(Math.random()*200*dirdev+Laya.stage.width/2);
		var posy=Math.floor(Math.random()*200*dirdev+Laya.stage.height/2);
		this._expBallobj.setData(_expBallVo,posx,posy,this._expInfoVo);
		Game.getInstance().uiLayerBottom.addChild(this._expBallobj);
		this._expBallobj.setAlpha(1);
		this._expBallarr[_expBallVo.ballId]=this._expBallobj;
		this._ballIdarr.push(_expBallVo.ballId);
	}

	/**领取经验球后获取数据*/
	__proto.getLqExpBallData=function(){
		var LqexpInfoVo=this._mgr.getLqExpInfoVo();
		var ballId=LqexpInfoVo.ballId;
		var expobj=this._expBallarr[ballId];
		expobj.setOverTimer=true;
		this.lqNum=LqexpInfoVo.times;
		expobj.offImageClick();
		Tween.to(expobj.getSImage(),{alpha:0},500,null,Handler.create(this,this.removeExpBall,[ballId]));
	}

	/**删除经验球*/
	__proto.removeExpBall=function(ballId){
		var expobj=this._expBallarr[ballId];
		if(expobj){
			Tween.clearAll(expobj);
			expobj.removeSelf();
			delete this._expBallarr[ballId];
			expobj.setSkin=null;
			this._cache.push(expobj);
			for(var i=0;i<this._ballIdarr.length;i++){
				if(this._ballIdarr[i]==ballId){
					this._ballIdarr.splice(i,1);
					break ;
				}
			}
		}
	}

	/**激活主角光环后自动领取*/
	__proto.delayedLq=function(ballId){
		var expobj=this._expBallarr[ballId];
		if(!expobj.getisOver()){
			Mgr.jingyanPro.sendLqExpBall(ballId);
		}
	}

	/**自动删除*/
	__proto.autoRemove=function(ballId){
		var expobj=this._expBallarr[ballId];
		if(!expobj.getisOver()){
			expobj.setOverTimer=true;
			Tween.to(expobj.getSImage(),{alpha:0},500,null,Handler.create(this,this.removeExpBall,[ballId]))
		}
	}

	/**获取经验球对象*/
	__proto.getElement=function(){
		if(this._cache.length>0){
			return this._cache.pop();
			}else{
			return null;
		}
	}

	/**开通的一瞬间全部领取*/
	__proto.autoLq=function(){
		this._stAt=Mgr.zhuJueGuangHuanM.getStat();
		for(var i=0;i<this._ballIdarr.length;i++){
			var ballId=this._ballIdarr[i];
			var expobj=this._expBallarr[ballId];
			if(expobj&&this._stAt!=0){
				expobj.setOverTimer=true;
				Tween.to(expobj.getSImage(),{alpha:0},500,null,Handler.create(this,this.removeExpBall,[ballId]));
				Mgr.jingyanPro.sendLqExpBall(ballId);
			}
		}
	}

	__proto.dispose=function(){
		for(var i=0;i<this._ballIdarr.length;i++){
			var ballId=this._ballIdarr[i];
			this.removeExpBall(ballId);
		}
		this._expBallarr={};
		this._cache=[];
		this._ballIdarr=[];
		EventCenter.instance.off("UpdateTeQuanKaInfo",this,this.autoLq);
	}

	__getset(1,ExpBallManager,'ins',function(){
		return ExpBallManager._ins=ExpBallManager._ins|| new ExpBallManager();
	});

	ExpBallManager._ins=null;
	return ExpBallManager;
})()


