/**
*通知消息管理
*@author zhanglimin
*@date 2020-6-20
**/
//class com.xq.util.NoticeManager
var NoticeManager=(function(){
	function NoticeManager(){
		this.box=null;
		this.teamDic=null;
		/**是否启动了事件监听*/
		this._ifStartListener=false;
	}

	__class(NoticeManager,'com.xq.util.NoticeManager');
	var __proto=NoticeManager.prototype;
	__proto.startListener=function(){
		if(this._ifStartListener)return;
		this._ifStartListener=true;
		EventCenter.instance.on("ENTER_SCENE",this,this.hideBall);
		this.hideBall();
	}

	__proto.stopListener=function(){
		if(!this._ifStartListener)return;
		this._ifStartListener=false;
		EventCenter.instance.off("ENTER_SCENE",this,this.hideBall);
	}

	/**添加消息通知球*/
	__proto.addNotice=function(vo){
		this.startListener();
		if(!this.teamDic){
			this.teamDic=new Dictionary();
			this.box=Game.getInstance().getNewMainView().getNoticeBox();
		};
		var ball=this.teamDic.get(vo.type);
		if(ball){
			ball.setData(vo);
			return;
		}
		ball=UIMgrR.newInstanceByIClass(com.xq.view.modules.common.ICommonNoticeBall);
		ball.setData(vo);
		this.teamDic.set(vo.type,ball);
		this.updatePos();
	}

	__proto.removeNotice=function(type){
		if(!this.teamDic)return;
		var ball=this.teamDic.get(type);
		if(ball){
			this.teamDic.remove(type);
			ball.dispose();
			this.updatePos();
		}
		if(this.teamDic.values.length<=0){
			this.stopListener();
		}
	}

	__proto.hideNotice=function(ifHide){
		this.box=Game.getInstance().getNewMainView().getNoticeBox();
		this.box.visible=!ifHide;
	}

	__proto.hideBall=function(){
		var rolevo=NetMgr.ins().roleVO;
		if(MapType.isCopy(rolevo.mapType)){
			com.xq.util.NoticeManager.ins.hideNotice(true);
		}
		else{
			com.xq.util.NoticeManager.ins.hideNotice(false);
		}
	}

	__proto.updatePos=function(){
		var ary=this.teamDic.values;
		var len=ary.length;
		var tempX=0;
		var w=0;
		for (var i=0;i < len;i++){
			var sp=ary[i];
			if(sp){
				sp.x=tempX;
				sp.y=-sp.height/2;
				tempX+=sp.width+10;
				w=tempX-10;
				this.box.addChild(sp);
			}
		}
		this.box.width=w;
		this.box.x=(Laya.stage.width-w)/2;
	}

	__getset(1,NoticeManager,'ins',function(){
		return NoticeManager._ins=NoticeManager._ins|| new NoticeManager();
	});

	NoticeManager._ins=null;
	return NoticeManager;
})()


