//class com.xq.util.scene.LightingUtil
var LightingUtil=(function(){
	function LightingUtil(){}
	__class(LightingUtil,'com.xq.util.scene.LightingUtil');
	LightingUtil.light=function(nums,time){
		(nums===void 0)&& (nums=1);
		(time===void 0)&& (time=100);
		if(!LightingUtil.whiteImg){
			LightingUtil.whiteImg=new Image();
		};
		var player=Model.game.mPlayer;
		if(!player)
			return;
		LightingUtil.whiteImg.skin=PathDefine.RES2_ROOT+PathDefine.IMAGE+"juqing/white"+".jpg";
		LightingUtil.whiteImg.x=player.x-5000;
		LightingUtil.whiteImg.y=player.y-5000;
		LightingUtil.whiteImg.width=10000;
		LightingUtil.whiteImg.height=10000;
		LightingUtil.whiteImg.alpha=0;
		SceneContainer.getInstance().topLayer.addChild(LightingUtil.whiteImg);
		LightingUtil.lightnums=nums;
		LightingUtil.jiangeTime=time;
		LightingUtil.lighting();
	}

	LightingUtil.lighting=function(){
		Tween.to(LightingUtil.whiteImg,{alpha:0.4},80);
		Tween.to(LightingUtil.whiteImg,{alpha:0},80,null,null,80);
		if(LightingUtil.lightnums>0){
			Laya.timer.once(LightingUtil.jiangeTime,LightingUtil,com.xq.util.scene.LightingUtil.lighting);
		}
		else{
			LightingUtil.whiteImg.destroy();
			LightingUtil.whiteImg=null;
		}
		LightingUtil.lightnums--;
	}

	LightingUtil.jiangeTime=0;
	LightingUtil.whiteImg=null;
	LightingUtil.lightnums=0;
	return LightingUtil;
})()


