//class com.xq.util.scene.MainEffectViewUtil
var MainEffectViewUtil=(function(){
	function MainEffectViewUtil(){}
	__class(MainEffectViewUtil,'com.xq.util.scene.MainEffectViewUtil');
	MainEffectViewUtil.addToEffLayer=function(target,ani,offsetX,offsetY,isShow){
		(offsetX===void 0)&& (offsetX=0);
		(offsetY===void 0)&& (offsetY=0);
		(isShow===void 0)&& (isShow=true);
		if(Configs.isForbitIOSPay||Configs.isForbitAndroidPay){
			return;
		};
		var sp=target.parent;
		if(!sp || !ani)
			return;
		MainEffectViewUtil.point.setTo(target.x,target.y);
		MainEffectViewUtil.point=sp.localToGlobal(MainEffectViewUtil.point);
		MainEffectViewUtil.point=(MainEffectViewUtil.mainEffctView.parent).globalToLocal(MainEffectViewUtil.point);
		ani.x=MainEffectViewUtil.point.x+offsetX;
		ani.y=MainEffectViewUtil.point.y+offsetY;
		ani.visible=isShow;
		MainEffectViewUtil.mainEffctView.addChild(ani);
		if(Laya.__typeof(target,'com.xq.interfaces.IActiveIcon')){
			MainEffectViewUtil.aniDic.set(ani,[target,ani,offsetX,offsetY]);
			if(!target.visible)
				ani.visible=false;
			var parent=target.parent;
			if(parent && !parent.visible)
				ani.visible=false;
			MainEffectViewUtil.activeAniDic.set(ani,ani);
		}
		if((ani instanceof com.xq.util.coolingmask.CoolingMask )){
			MainEffectViewUtil.skillCoolDic.set(ani,ani);
		}
	}

	MainEffectViewUtil.showSkillAni=function(flag){
		var arr=MainEffectViewUtil.skillCoolDic.values;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var ani=arr[i];
			ani.visible=flag;
		}
	}

	MainEffectViewUtil.showActiveAni=function(flag){
		var arr=MainEffectViewUtil.activeAniDic.values;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var ani=arr[i];
			ani.visible=flag;
		}
	}

	MainEffectViewUtil.removeEff=function(ani){
		var arr=MainEffectViewUtil.aniDic.get(ani);
		if(arr){
			var dicAni=arr[1];
			if(dicAni){
				dicAni.removeSelf();
				MainEffectViewUtil.aniDic.remove(ani);
			}
		}
	}

	MainEffectViewUtil.resize=function(){
		var aniArr=MainEffectViewUtil.aniDic.values;
		var len=aniArr.length;
		for(var i=0;i< len;i++){
			var arr=aniArr[i];
			var target=arr[0];
			var ani=arr[1];
			MainEffectViewUtil.point.setTo(target.x,target.y);
			var sp=target.parent;
			if(sp){
				MainEffectViewUtil.point=sp.localToGlobal(MainEffectViewUtil.point);
				ani.x=MainEffectViewUtil.point.x+arr[2];
				ani.y=MainEffectViewUtil.point.y+arr[3];
			}
		}
	}

	MainEffectViewUtil.mainEffctView=null;
	__static(MainEffectViewUtil,
	['aniDic',function(){return this.aniDic=new Dictionary();},'activeAniDic',function(){return this.activeAniDic=new Dictionary();},'skillCoolDic',function(){return this.skillCoolDic=new Dictionary();},'point',function(){return this.point=new Point();}
	]);
	return MainEffectViewUtil;
})()


