//class com.xq.util.scene.ShakeUtil
var ShakeUtil=(function(){
	function ShakeUtil(){}
	__class(ShakeUtil,'com.xq.util.scene.ShakeUtil');
	ShakeUtil.shake1=function(times,r,target){
		(times===void 0)&& (times=1);
		(r===void 0)&& (r=10);
		if(!SettingAction.ins().isShowZhenPing)
			return;
		if(ShakeUtil.isShaking)
			return;
		if(!target){
			target=Model.game.mPlayer;
		}
		if(!target || !target.parent)
			return;
		if(!times || times<1)
			times=1;
		var time=times *200;
		if(!r || r<1)
			r=10;
		if(!ShakeUtil.kongSp){
			ShakeUtil.kongSp=new Sprite();
		}
		ShakeUtil.kongSp.x=target.x;
		ShakeUtil.kongSp.y=target.y;
		target.parent.addChild(ShakeUtil.kongSp);
		SceneContainer.getInstance().mapCamera.lookAt(ShakeUtil.kongSp);
		ShakeUtil.isShaking=true;
		Laya.timer.loop(20,ShakeUtil,ShakeUtil.shakeAni,[target,ShakeUtil.kongSp,time,r,1]);
	}

	ShakeUtil.shakeAni=function(target,kongSp,time,r,type){
		if(ShakeUtil.countTime>=time){
			ShakeUtil.resetAni(target);
			return;
		}
		ShakeUtil.countTime+=50;
		switch(type){
			case 1:
				kongSp.y=target.y+r*ShakeUtil.aniArr[ShakeUtil.aniTimes];
				kongSp.x=target.x;
				break ;
			}
		ShakeUtil.aniTimes=(ShakeUtil.aniTimes+1)%4;
	}

	ShakeUtil.resetAni=function(target){
		ShakeUtil.aniTimes=0;
		ShakeUtil.countTime=0;
		ShakeUtil.isShaking=false;
		if(ShakeUtil.kongSp)
			ShakeUtil.kongSp.removeSelf();
		Laya.timer.clear(ShakeUtil,ShakeUtil.shakeAni);
		SceneContainer.getInstance().mapCamera.lookAt(target);
	}

	ShakeUtil.UP_DOWN=1;
	ShakeUtil.aniLen=4;
	ShakeUtil.kongSp=null;
	ShakeUtil.countTime=0;
	ShakeUtil.isShaking=false;
	ShakeUtil.aniTimes=0;
	__static(ShakeUtil,
	['aniArr',function(){return this.aniArr=[1,-1,-1,1];}
	]);
	return ShakeUtil;
})()


/**
*时钟,用于事务提醒
*@author zenghuaqiang
*/
//class com.xq.util.ServerClock
var ServerClock=(function(){
	function ServerClock(){
		/**
		*计时器时间间隔
		*/
		this.CLOCK_INTERVAL=1;
		/**
		*计时器
		*/
		this._timer=null;
		/**
		*每日待办事务
		*/
		this._dailyAffairsTodo=[];
		/**
		*每日已完成事务
		*/
		this._dailyAffairsDone=[];
		/**
		*开服第几天待办事务(非周期性,所以不需要记录已完成事务)
		*/
		this._dayAfterServerStartAffairsTodo=[];
		/**
		*每周待办事务
		*/
		this._weekAffairsTodo=[];
		/**
		*每周已完成事务
		*/
		this._weekAffairsDone=[];
		/**
		*一天毫秒数
		*/
		this.oneDayMileSeconds=24*60*60*1000;
		this.overDayResetAry=[];
		this.helpTimeArr=[];
		this.isDailyRemain=false;
		this.helperDate1=new Date();
		this.helperDate2=new Date();
		this._timer=Laya.timer;
	}

	__class(ServerClock,'com.xq.util.ServerClock');
	var __proto=ServerClock.prototype;
	/**
	*开启时钟
	*/
	__proto.startClock=function(){
		this._timer.loop(1000,this,this.onTimer);
	}

	/**
	*注册每日事务提醒(周期性的)
	*@param callback 回调函数
	*@param params 回调函数参数
	*@param activityTime 活动时间(单位：毫秒)example:活动开启时间为15:30:00，则 activityTime=TextUtil.timeToMilSeconds(15,30,00);
	*@param timeOffset 时间偏移(单位：毫秒,如果在活动时间之前,则为负数)example:活动开启前10分钟，则 timeOffset=-TextUtil.timeToMilSeconds(0,10,00);
	*/
	__proto.registerDailyAlarmClock=function(callback,activityTime,timeOffset){
		if(callback.once){
			console.error("必须为false，否则可能导致不可预料的问题！");
			debugger;
		};
		var timeArr=this.getDailyTimeArrByTimeOffset(activityTime,timeOffset);
		if(this.isExist(callback,callback.args,timeArr)){
			console.log("请不要重复注册！ -- > registerDailyAlarmClock");
			return;
		};
		var obj={c:callback,p:callback.args,t:timeArr};
		if(this.isTimeOut(timeArr)){
			this._dailyAffairsDone.push(obj);
			}else{
			this._dailyAffairsTodo.push(obj);
		}
		this.overDayResetAry.push(obj);
	}

	/**
	*每周固定 开启活动注册（开服七天后，如果是在对的时间，就注册活动开启通知事件）
	*@param weekDayList [星期1,星期X]
	*@param timeList [hour,minute]
	*@param serverOpenTime 开服的时间
	*@param durationMinute 活动持续时间
	*@param callback 回调函数
	*@param params 回调函数参数
	*@param timeOffset 时间偏移(单位：毫秒,如果在活动时间之前,则为负数)example:活动开启前10分钟，则 timeOffset=-TextUtil.timeToMilSeconds(0,10,00);
	*@return
	*
	*/
	__proto.registerWeekAlarmClock=function(weekDayList,timeList,serverOpenTime,durationMinute,callback,timeOffset){
		if(callback.once){
			console.error("once必须为false");
			debugger;
		};
		var curDay=this.getCurDay();
		var index=0;
		var len=weekDayList.length;
		while(index < len){
			if(curDay==weekDayList[index]){
				var hour=timeList[0];
				var minue=timeList[1];
				var timeArr=this.getDailyTimeArrByTimeOffset(TextUtil.timeToMilSeconds(hour,minue,0),timeOffset);
				var obj={c:callback,p:callback.args,t:timeArr,o:serverOpenTime,d:durationMinute,tl:timeList,w:weekDayList,to:timeOffset};
				if(this.checkIsStartNow(hour,minue,durationMinute)){
					obj.c.run();
				}
				if(this.isTimeOut(timeArr)){
					this._weekAffairsDone.push(obj);
				}
				else{
					this._weekAffairsTodo.push(obj);
				}
				break ;
			}
			index++;
		}
	}

	/**
	*检测是否刚好在活动时间内 （是，则直接发布通知）
	*@param hour
	*@param minue
	*@param durationMinute
	*/
	__proto.checkIsStartNow=function(hour,minue,durationMinute){
		var curTimeSec=TextUtil.changeServerTimeToSeconds(Mgr.curTime.serverTimer);
		var startTimeSec=hour *3600+minue *60;
		var endTimeSec=startTimeSec+durationMinute;
		return (curTimeSec > startTimeSec && curTimeSec < endTimeSec)
	}

	/**
	*根据现在时间 获取现在星期几
	*@return
	*
	*/
	__proto.getCurDay=function(){
		this.helperDate1.setTime(Mgr.curTime.serverTimer);
		var day=this.helperDate1.getDay();
		if(day==0)day=7;
		return day;
	}

	/**
	*获取指定时间戳的当日时间的数组形式[小时，分钟，秒]
	*@param time 时间戳(时间戳是自 1970 年 1 月 1 日（08:00:00 GMT）至当前时间的总秒数)
	*@return
	*/
	__proto.getDailyTimeArrByTimeStamp=function(time,resultArr){
		var date=this.helperDate1;
		date.setTime(time);
		if(resultArr==null){
			resultArr=[];
		}
		resultArr[0]=date.getHours();
		resultArr[1]=date.getMinutes();
		resultArr[2]=date.getSeconds();
		return resultArr;
	}

	/**
	*通过活动时间和时间偏移获取需要提醒的当日时间的数组形式[小时，分钟，秒],当日时间转毫秒方法：TextUtil.timeToMilSeconds(hours,minutes,seconds);
	*@param activityTime 活动时间(单位：毫秒)example:活动开启时间为15:30:00，则 activityTime=TextUtil.timeToMilSeconds(15,30,00);
	*@param timeOffset 时间偏移(单位：毫秒,如果在活动时间之前,则为负数)example:活动开启前10分钟，则timeOffset=-TextUtil.timeToMilSeconds(0,10,00);
	*@return 需要提醒的当日时间的数组形式[小时，分钟，秒]
	*/
	__proto.getDailyTimeArrByTimeOffset=function(activityTime,timeOffset,result){
		var date=new Date(Mgr.curTime.serverTimer);
		var _hours=date.getHours()*3600;
		var _minutes=date.getMinutes()*60;
		var _seconds=date.getSeconds();
		var _milliseconds=date.getMilliseconds();
		var acttime=(_hours+_minutes+_seconds)*1000;
		var times=Mgr.curTime.serverTimer-acttime+_milliseconds+activityTime;
		var timeArr=this.getDailyTimeArrByTimeStamp(times,result);
		var timeArr1=this.getDailyTimeArrByTimeStamp(times+timeOffset,result);
		if(timeOffset > 0){
			return timeArr.concat(timeArr1);
		}
		else{
			return timeArr1.concat(timeArr);
		}
	}

	/**
	*计时器
	*/
	__proto.onTimer=function(){
		if(this.isOverDay()){
			var obj;
			var i=0;
			var lenD=this.overDayResetAry.length;
			for (i=lenD-1;i >=0;i--){
				obj=this.overDayResetAry[i];
				if(!this.isDailyRemain){
					this.isTimeIn(obj.t)
					obj.c.run();
					this._dailyAffairsTodo.splice(i,1);
					this._dailyAffairsDone.push(obj);
				}
			}
			this.onOverDay();
		};
		var lenT=this._dayAfterServerStartAffairsTodo.length;
		for (i=lenT-1;i >=0;i--){
			obj=this._dayAfterServerStartAffairsTodo[i];
			var curdate=new Date(Mgr.curTime.serverTimer).getDate();
			if(this.checkIsStartNow(obj.ta[0],obj.ta[1],obj.d)){
				obj.c.run();
				this._dayAfterServerStartAffairsTodo.splice(i,1);
			}
		};
		var lenA=this._weekAffairsTodo.length;
		for (i=lenA-1;i >=0;i--){
			obj=this._weekAffairsTodo[i];
			if(this.isTimeIn(obj.t)){
				obj.c.run();
				this._weekAffairsTodo.splice(i,1);
				this._weekAffairsDone.push(obj);
			}
		}
	}

	/**
	*是否已过当日提醒最迟时间
	*/
	__proto.isTimeOut=function(time){
		var curTime=Mgr.curTime.serverTimer;
		var dailyTimeArr=this.getDailyTimeArrByTimeStamp(curTime,this.helpTimeArr);
		var nowSecend=dailyTimeArr[0]*3600+dailyTimeArr[1]*60+dailyTimeArr[2];
		var alarmSecond1=time[3]*3600+time[4]*60+time[5];
		return (nowSecend >=alarmSecond1);
	}

	/**是否到达当日提醒最早时间*/
	__proto.isTimeIn=function(time){
		var curTime=Mgr.curTime.serverTimer;
		var dailyTimeArr=this.getDailyTimeArrByTimeStamp(curTime,this.helpTimeArr);
		var nowSecend=dailyTimeArr[0]*3600+dailyTimeArr[1]*60+dailyTimeArr[2];
		var alarmSecond=time[0]*3600+time[1]*60+time[2];
		return (nowSecend >=alarmSecond);
	}

	/**
	*是否跨天了(此时的日时间点小于上次刷新时的日时间点则为跨天：00:00:00 < 23:59:59)
	*/
	__proto.isOverDay=function(){
		var serverTime=Mgr.curTime.serverTimer;
		this.helperDate1.setTime(serverTime);
		this.helperDate2.setTime(serverTime-this.CLOCK_INTERVAL*3000);
		return (this.helperDate2.getDate()!=this.helperDate1.getDate());
	}

	/**
	*跨天时，将前一天的已完成事务重新转为待办事务
	*/
	__proto.onOverDay=function(){
		this._dailyAffairsTodo=this._dailyAffairsDone.concat();
		this._dailyAffairsDone=[];
		this._weekAffairsTodo=this._weekAffairsDone.concat();
		this._weekAffairsDone=[];
		var obj;
		var weekAffairList=[];
		var $each_obj;
		for($each_obj in this._weekAffairsTodo){
			obj=this._weekAffairsTodo[$each_obj];
			weekAffairList.push(obj);
		}
		this._weekAffairsTodo=[];
		var $each_obj;
		for($each_obj in weekAffairList){
			obj=weekAffairList[$each_obj];
			this.registerWeekAlarmClock(obj.w,obj.tl,obj.o,obj.d,obj.c,obj.to);
		}
	}

	/**
	*检测是否重复注册(每日事务)
	*/
	__proto.isExist=function(callback,params,time){
		var obj;
		var len=this._dailyAffairsTodo.length;
		for (var i=0;i < len;i++){
			obj=this._dailyAffairsTodo[i];
			if(obj.c==callback && this.equalArray(obj.p ,params)&& this.equalArray(obj.t,time)){
				return true;
			}
		}
		len=this._dailyAffairsDone.length;
		for (var k=0;k < len;k++){
			obj=this._dailyAffairsDone[k];
			if(obj.c==callback && this.equalArray(obj.p ,params)&& this.equalArray(obj.t,time)){
				return true;
			}
		}
		return false;
	}

	__proto.equalArray=function(array1,array2){
		if(array1==array2){
			return true;
		}
		if(array1==null){
			return false;
		}
		if(array2==null){
			return false;
		}
		if(array1.length !=array2.length){
			return false;
		};
		var len=array1.length;
		var isEqual=true;
		for (var i=0;i < len;i++){
			if(array1[i]!=array2[i]){
				isEqual=false;
				break ;
			}
		}
		return isEqual;
	}

	/**
	*注册开服第几天某个时间提醒(非周期性)
	*@param callback 回调函数
	*@param params 回调函数参数
	*@param serverStartTime 开服时间(时间戳,单位：毫秒)
	*@param durationMinute 活动持续时间(单位：分钟)
	*@param dayCount 开服第几天(如1号开服,1号23:59:59后为开服第2天)
	*@param activityTime 活动时间(单位：毫秒)example:活动开启时间为15:30:00，则 activityTime=TextUtil.timeToMilSeconds(15,30,00);
	*@param timeOffset 时间偏移(单位：毫秒,如果在活动时间之前,则为负数)example:活动开启前10分钟，则 timeOffset=-TextUtil.timeToMilSeconds(0,10,00);
	*/
	__proto.registerDayAfterServerStartAlarmClock=function(callback,serverStartTime,durationMinute,dayCount,activityTime,timeOffset){
		if(callback.once==true){
			console.error("注册回调必须改成false");
			debugger;
		};
		var regTime=serverStartTime+(dayCount-1)*this.oneDayMileSeconds;
		var regTimeDate=new Date(regTime);
		var regDate=regTimeDate.getDate();
		var timeArr=this.getDailyTimeArrByTimeOffset(activityTime,timeOffset);
		var obj={c:callback,p:callback.args,s:serverStartTime,d:durationMinute,r:regDate,a:activityTime,t:timeOffset,ta:timeArr};
		if(this.isExistDayAfterServerStart(serverStartTime,regDate,activityTime,timeOffset)){
			console.log("请不要重复注册！ -- > registerDayAfterServerStartAlarmClock");
			return;
		}
		this._dayAfterServerStartAffairsTodo.push(obj);
		console.log("注册开服第几天某个时间提醒注册成功：",serverStartTime,dayCount,activityTime,timeOffset,timeArr);
	}

	/**
	*检测是否重复注册(开服第几天待办事务)
	*/
	__proto.isExistDayAfterServerStart=function(serverStartTime,regDate,activityTime,timeOffset){
		var obj;
		var $each_obj;
		for($each_obj in this._dayAfterServerStartAffairsTodo){
			obj=this._dayAfterServerStartAffairsTodo[$each_obj];
			if(obj.s==serverStartTime && obj.r==regDate && obj.a==activityTime && obj.t==timeOffset){
				return true;
			}
		}
		return false;
	}

	ServerClock.getInstance=function(){
		if(null==ServerClock.instance)ServerClock.instance=new ServerClock();
		return ServerClock.instance;
	}

	ServerClock.instance=null;
	return ServerClock;
})()


