	TextUtil.formatNumber=function(value){
		var temp=String(value).split(".");
		var tempStr="";
		if (temp.length > 1){
			tempStr=temp[1];
		};
		var data="";
		var numList=String(temp[0]).split("");
		var len=numList.length;
		if (len <=3)
			return value.toString();
		var mark=3;
		temp=[];
		var index=0;
		while (index < len){
			if ((index % mark)==0 && index > 0){
				temp.push(",");
			}
			temp.push(numList.pop())
			index++;
		}
		temp.reverse();
		index=0;
		len=temp.length;
		while (index < len){
			data+=temp[index];
			index++;
		}
		if (tempStr !=""){
			data+="."+tempStr;
		}
		else{
			data+=tempStr;
		}
		return data;
	}

