	TextUtil.toSBC=function(str,alsoSpace){
		(alsoSpace===void 0)&& (alsoSpace=true);
		var a=str.split('');
		var i=a.length;
		while (--i >-1){
			var c=str.charCodeAt(i);
			if (32==c && alsoSpace)
				a[i]=String.fromCharCode(12288);
			else if (c >=33 && c <=126)
			a[i]=String.fromCharCode(c+65248);
		}
		return a.join('');
	}

	TextUtil.toDBC=function(str,alsoSpace){
		(alsoSpace===void 0)&& (alsoSpace=true);
		var a=str.split('');
		var i=a.length;
		while (--i >-1){
			var c=str.charCodeAt(i);
			if (12288==c && alsoSpace)
				a[i]=String.fromCharCode(32);
			else if (c >=65281 && c <=65374)
			a[i]=String.fromCharCode(c-65248);
		}
		return a.join('');
	}

