	TextUtil.replaceEx=function(context,targetIndex,sourceStr,targetStr){
		var index=0;
		var len=0;
		var dataList=context.split(sourceStr);
		if (dataList.length==0){
			return context;
		};
		index=0;
		len=dataList.length-1;
		while (index < len){
			dataList[index]+=sourceStr;
			index++;
		};
		if (targetIndex >=dataList.length){
			return context;
		};
		dataList[targetIndex]=(dataList [targetIndex]).replace(sourceStr,targetStr);
		var newContext="";
		index=0;
		len=dataList.length;
		while (index < dataList.length){
			newContext+=dataList[index];
			index++;
		};
		return newContext;
	}

