var PaiMaiDetailVo=(function(){
	function PaiMaiDetailVo(){
		/**拍卖的唯一id数据类型：int64*/
		this.auctionId=NaN;
		/**拍卖的道具id 和 当前买家名称 itemId;roleName数据类型：string*/
		this.itemId=null;
		/**拍卖的道具数量数据类型：int32*/
		this.itemNum=0;
		/**拍卖的金钱类型数据类型：int32*/
		this.moneyType=0;
		/**拍卖的最终价格数据类型：int64*/
		this.salePrice=NaN;
		/**拍卖的利润值数据类型：int64*/
		this.rewardPrice=NaN;
		/**玩家的分钱数据数据类型：RolePriceMsg*/
		this.roleDatas=null;
		this.roleDataVos=null;
		this.roleName=null;
	}

	__class(PaiMaiDetailVo,'com.xq.vo.PaiMaiDetailVo');
	var __proto=PaiMaiDetailVo.prototype;
	__proto.updateData=function(msg){
		if(!msg)return;
		this.auctionId=msg.auctionId;
		this.itemNum=msg.itemNum;
		this.moneyType=msg.moneyType;
		this.salePrice=msg.salePrice;
		this.rewardPrice=msg.rewardPrice;
		this.roleDatas=msg.roleDatas;
		this.roleDatas.sort(this.compare);
		this.roleDataVos=[];
		var len=this.roleDatas.length;
		for(var i=0;i<len;i++){
			var vo=new RoleDatasVo();
			vo.updataData(this.roleDatas[i],i+1);
			this.roleDataVos.push(vo);
		}
		if(msg.itemId){
			var tempArr=msg.itemId.split(";");
			this.itemId=tempArr[0];
			this.roleName=tempArr[1];
		}
	}

	__proto.compare=function(a,b){
		return b.harmRate-a.harmRate;
	}

	return PaiMaiDetailVo;
})()


