//class com.xq.vo.PropAttrVo
var PropAttrVo=(function(){
	function PropAttrVo(){
		this._attrId=0;
		this.attrName=null;
		this.attrVal=NaN;
		this.color=null;
		/**下一级增加属性值*/
		this.nextLvAddVal=NaN;
		/**用于自定义展示的属性名称*/
		this.ifShow=false;
		this.showName=null;
		this.showVal=NaN;
		this.ifShowPer=false;
	}

	__class(PropAttrVo,'com.xq.vo.PropAttrVo');
	var __proto=PropAttrVo.prototype;
	/**传入数据 [name,value]*/
	__proto.setData=function(arr){
		this.attrName=arr[0];
		this.attrVal=arr[1];
	}

	__getset(0,__proto,'cnName',function(){
		if(!this.attrName)return "";
		var cof=Model.prop.getAttrCofByName(this.attrName);
		if(!cof)return "";
		return cof.mingzi;
	});

	/**属性Id*/
	__getset(0,__proto,'attrId',function(){
		if(!this.attrName)return-1;
		return Model.prop.getAttrIdByName(this.attrName);
	});

	/**属性战力 前端自己算的 会有一些偏差，用于小模块算战力，大模块还是用后端的数据*/
	__getset(0,__proto,'attrFV',function(){
		if(!this.attrName)return 0;
		var cof=Model.prop.getAttrCofByName(this.attrName);
		if(!cof)return 0;
		var attrFactor=cof.pingfen;
		return parseInt(Math.round(this.attrVal *attrFactor).toString());
	});

	__getset(0,__proto,'ifPer',function(){
		if(!this.attrName)return false;
		var cof=Model.prop.getAttrCofByName(this.attrName);
		if(!cof)return false;
		return cof.isPer==1;
	});

	return PropAttrVo;
})()


