/**
*@author:huanghong
*@date:2021-4-15
*@desc:元神infoVo
*/
//class com.xq.vo.YuanShenInfoVo
var YuanShenInfoVo=(function(){
	function YuanShenInfoVo(){
		/**类型数据类型：int8*/
		this.type=0;
		/**当前修炼经验数据类型：int32*/
		this.xlexp=0;
		/**当前修炼重数数据类型：int8*/
		this.xlChong=0;
		/**当前修炼阶数数据类型：int16*/
		this.xlJie=0;
		/**当前激活的灌顶id数据类型：int8*/
		this.gdId=0;
		/**当前淬炼等级数据类型：int16*/
		this.clLv=0;
		/**元神装备信息数据类型：YuanShenEquipMsg*/
		this.infos=null;
		/**附魔信息数据类型：YuanShenEquipFuMoMsg*/
		this.fumos=null;
		/**元神技能信息数据类型：YuanShenSkillMsg*/
		this.skills=null;
		/**元神技能共鸣数据类型：int16*/
		this.skillGms=null;
		/**装备字典*/
		this._equipDic=null;
		/**附魔字典*/
		this._fumoDic=null;
		/**技能字典*/
		this._skillDic=null;
		/**技能共鸣字典*/
		this._gmDic=null;
		this._equipDic=new Dictionary();
		this._fumoDic=new Dictionary();
		this._skillDic=new Dictionary();
		this._gmDic=new Dictionary();
	}

	__class(YuanShenInfoVo,'com.xq.vo.YuanShenInfoVo');
	var __proto=YuanShenInfoVo.prototype;
	__proto.setData=function(msg){
		this.type=msg.type;
		this.xlexp=msg.xlexp;
		this.xlChong=msg.xlChong;
		this.xlJie=msg.xlJie;
		this.gdId=msg.gdId;
		this.clLv=msg.clLv;
		this.infos=msg.infos;
		this.fumos=msg.fumos;
		this.skills=msg.skills;
		this.skillGms=msg.skillGMInfos;
		var len=this.infos.length;
		for(var i=0;i<len;i++){
			var equipInfo=this.infos[i];
			this._equipDic.set(equipInfo.slotNum,equipInfo);
		}
		len=this.fumos.length;
		for(i=0;i<len;i++){
			var fumoInfo=this.fumos[i];
			this._fumoDic.set(fumoInfo.slotNum,fumoInfo);
		}
		this.updateFMGuidEle();
		len=this.skills.length;
		for(i=0;i<len;i++){
			var skillInfo=this.skills[i];
			this._skillDic.set(skillInfo.id,skillInfo.level);
		}
		len=this.skillGms.length;
		for(i=0;i<len;i++){
			var gmInfo=this.skillGms[i];
			this._gmDic.set(gmInfo.gmtype,gmInfo.gmLv);
		}
	}

	//============修炼===============
	__proto.updateFMGuidEle=function(){
		var slots=YuanShenMgr.Slots;
		var len=slots.length;
		var arr=Model.yuanShen.fmGridDc.array;
		var gridLen=arr.length;
		var ele;
		for(var i=0;i<gridLen;i++){
			ele=arr[i];
			for(var j=0;j<len;j++){
				var slot=slots[j];
				var key=this.type+"_"+slot;
				var fumoInfo=this._fumoDic.get(slot);
				var fumoIds=fumoInfo?fumoInfo.fumoId:[];
				var id=fumoIds[i];
				if(id>=0){
					ele.setValue(key,id);
				}
				else{
					ele.setValue(key,-1);
				}
			}
		}
	}

	__proto.updateXLData=function(msg){
		this.xlexp=msg.xlexp;
		this.xlChong=msg.xlChong;
		this.xlJie=msg.xlJie;
	}

	__proto.updateGDData=function(msg){
		this.gdId=msg.gdId;
	}

	__proto.updateCLData=function(msg){
		this.clLv=msg.clLv;
	}

	//===========装备==============
	__proto.updateDress=function(msg){
		var info=msg.info;
		this._equipDic.set(info.slotNum,info);
	}

	__proto.updateOpenGrid=function(msg){
		var info=msg.fumos;
		this._fumoDic.set(info.slotNum,info);
		this.updateFMGuidEle();
	}

	__proto.updateFumo=function(msg){
		var slot=this.getSlotNumByGuid(msg.guid);
		var fumoInfo=this._fumoDic.get(slot);
		if(fumoInfo){
			fumoInfo.fumoId[msg.index-1]=msg.fumoId;
		}
		this.updateFMGuidEle();
	}

	/**通过装备唯一Id 获取 该装备所处的栏位*/
	__proto.getSlotNumByGuid=function(guid){
		var equipArr=this._equipDic.values;
		var len=equipArr.length;
		var index=-1;
		for(var i=0;i<len;i++){
			var info=equipArr[i];
			if(info.guid==guid){
				return info.slotNum;
			}
		}
		return 0;
	}

	/**根据栏位获取元神装备信息*/
	__proto.getEquipInfoBySlot=function(slot){
		return this._equipDic.get(slot);
	}

	/**根据栏位获取元神装备星级 未佩戴-1 装备星级从0开始*/
	__proto.getEquipStarBySlot=function(slot){
		var equip=this.getEquipInfoBySlot(slot);
		if(!equip)return-1;
		var id=equip.templateId;
		var cof=Mgr.item.getEquip(id);
		if(!cof)return 0;
		return cof.star;
	}

	/**根据当前栏位获取前一个有装备的栏位*/
	__proto.getLastEquip=function(slot){
		var targetSlot=slot;
		while(targetSlot>0){
			targetSlot--;
			var equip=this.getEquipInfoBySlot(targetSlot);
			if(equip){
				return targetSlot;
			}
		}
		return 0;
	}

	/**根据当前栏位获取后一个有装备的栏位*/
	__proto.getNextEquip=function(slot){
		var targetSlot=slot;
		while(targetSlot<6){
			targetSlot++;
			var equip=this.getEquipInfoBySlot(targetSlot);
			if(equip){
				return targetSlot;
			}
		}
		return 0;
	}

	/**通过栏位获取附魔info*/
	__proto.getFumoInfo=function(slot){
		return this._fumoDic.get(slot);
	}

	//===========技能============
	__proto.updateUpgradeSkill=function(msg){
		var skillInfo=msg.skill;
		this._skillDic.set(skillInfo.id,skillInfo.level);
	}

	__proto.updateSkillGm=function(msg){
		var gmInfo=msg.skillGMInfo;
		this._gmDic.set(gmInfo.gmtype,gmInfo.gmLv);
	}

	__proto.getSkillLv=function(skillId){
		var lv=this._skillDic.get(skillId);
		lv=lv?lv:0;
		return lv;
	}

	__proto.getGmLv=function(gmType){
		var lv=this._gmDic.get(gmType);
		lv=lv?lv:0;
		return lv;
	}

	return YuanShenInfoVo;
})()


