//class com.xq.vo.ZhouKaInfoVo
var ZhouKaInfoVo=(function(){
	function ZhouKaInfoVo(){
		/**今日已击杀boss数量数据类型：int16*/
		this.kill=0;
		/**今日已经领取礼包数量数据类型：int16*/
		this.getRewardTimes=0;
		/**可领取礼包总数量数据类型：int16*/
		this.totalRewardTimes=0;
		/**下级可领取礼包总数量数据类型：int16*/
		this.nextTotalRewardTimes=0;
		/**击杀一个boss可以领取的礼包数量数据类型：int8*/
		this.killReward=0;
		/**周卡等级数据类型：int8*/
		this.level=0;
		/**周卡经验数据类型：int8*/
		this.exp=0;
		/**总周卡经验数据类型：int8*/
		this.totalExp=0;
		/**每次增加经验值数据类型：int8*/
		this.addExp=0;
		/**奖励数据类型：ItemParamVoRewardMsg*/
		this.reward=null;
		this._showReward=null;
	}

	__class(ZhouKaInfoVo,'com.xq.vo.ZhouKaInfoVo');
	var __proto=ZhouKaInfoVo.prototype;
	/**数据刷新*/
	__proto.updateData=function(msg){
		this.kill=msg.kill;
		this.getRewardTimes=msg.getRewardTimes;
		this.totalRewardTimes=msg.totalRewardTimes;
		this.nextTotalRewardTimes=msg.nextTotalRewardTimes;
		this.killReward=msg.killReward;
		this.level=msg.level;
		this.exp=msg.exp;
		this.totalExp=msg.totalExp;
		this.addExp=msg.addExp;
		this.reward=msg.reward;
		this._showReward=TextUtil.rewardMsgToItemsId(this.reward);
	}

	__proto.updateTimes=function(msg){
		this.getRewardTimes=msg.getRewardTimes;
	}

	__proto.updateKillBossNum=function(msg){
		this.kill=msg.kill;
	}

	/**剩余可领取奖励次数*/
	__getset(0,__proto,'remainReward',function(){
		return this.kill*this.killReward-this.getRewardTimes;
	});

	/**是否全部领取完毕*/
	__getset(0,__proto,'ifOver',function(){
		return this.totalRewardTimes!=0&&this.getRewardTimes>=this.totalRewardTimes;
	});

	__getset(0,__proto,'showReward',function(){
		return this._showReward;
	});

	return ZhouKaInfoVo;
})()


