/**
*@author xiangjia
*@date 2019-11-17
*/
//class com.xq.core.pathFinding.GridExt extends PathFinding.core.Grid
var GridExt=(function(_super){
	function GridExt(width_or_matrix,height,matrix){
		GridExt.__super.call(this,width_or_matrix,height,matrix);
	}

	__class(GridExt,'com.xq.core.pathFinding.GridExt',_super);
	var __proto=GridExt.prototype;
	/**
	*新增
	*算上对角
	*根据距离格子来返回所有的附近Node
	**/
	__proto.getNearNodesByDis=function(cur_node,dis){
		var nodes=this.nodes;
		var w=this.width;
		var h=this.height;
		var x=cur_node.x;
		var nodeArr=[];
		var y=cur_node.y;
		var ydown=y+dis;
		var yup=y-dis;
		var xleft=x-dis;
		var xright=x+dis;
		for(var i=-dis;i <=dis;i++){
			var tempX=x+i;
			var tempY=y+i;
			if(tempX >=0 && tempX < w){
				if(ydown>=0 && ydown < h){
					nodeArr.push(nodes[ydown][tempX]);
				}
				if(yup>=0 && yup < h){
					nodeArr.push(nodes[yup][tempX]);
				}
			}
			if(i!=-dis && i!=dis){
				if(tempY>=0 && tempY < h){
					if(xleft>=0 && xleft < w){
						nodeArr.push(nodes[tempY][xleft]);
					}
					if(xright>=0 && xright < w){
						nodeArr.push(nodes[tempY][xright]);
					}
				}
			}
		}
		return nodeArr;
	}

	return GridExt;
})(Grid)


