var FourteenAction=(function(_super){
	function FourteenAction(){
		FourteenAction.__super.call(this);
	}

	__class(FourteenAction,'com.xq.modules.active.fourteenLuxury.FourteenAction',_super);
	var __proto=FourteenAction.prototype;
	/**
	*子类重写定义一个协议数组
	*
	**/
	__proto.registerMsg=function(){
		this._methodDic[88103000]=this.onFourteen;
		this._methodDic[88103001]=this.onFourteen_one;
	}

	__proto.sendFourteen=function(){
		this._net.sendMsg(88103000);
	}

	__proto.onFourteen=function(byte){
		var vo=new Get14DayInfoSC();
		vo.decode(byte);
		if(vo.errCode==1){
			Mgr.fourtenMgr.receiveGet14Day(vo);
			Mgr.fourtenMgr.nextRewardTime=vo.nextRewardTime;
			EventCenter.instance.event("UPDATE_DATA");
		}
	}

	__proto.sendFourteen_one=function(day){
		var get14Day=new Get14DayRewardCS();
		get14Day.day=day;
		this._net.sendMsg(88103001,get14Day);
	}

	__proto.onFourteen_one=function(byte){
		var vo=new Get14DayRewardSC();
		vo.decode(byte);
		if(vo.errCode==1){
			EventCenter.instance.event("FOURTEEN_REWARD");
			this.showReward(vo.day);
			this.sendFourteen();
			}else{
			Mgr.prompt.optionPrompt(CodeMgr.ins.getStringByCode(vo.errCode));
		}
	}

	__proto.showReward=function(day){
		var fourteenVO=Mgr.fourtenMgr.cfgData_vo[day-1];
		if(fourteenVO){
			var rewardObj={};
			var obj=fourteenVO.configData;
			var propC=obj.propC.split(";");
			rewardObj["scale"]=parseFloat(obj.effectsuofang);
			var resPath;
			if(propC.length > 1){
				var sex=0;
				if(NetMgr.ins().roleVO.job=="A"){
					sex=0;
					}else{
					sex=1;
				}
				resPath=PathDefine.OUT_RES+"ani/"+propC[sex]+".amt";
				}else{
				resPath=PathDefine.OUT_RES+"ani/"+propC[0]+".amt";
			}
			rewardObj["resPath"]=resPath;
			if(obj.xy){
				var XY=obj.xy.split(":");
				rewardObj["x"]=parseInt(XY[0]);
				rewardObj["y"]=parseInt(XY[1]);
			};
			var rewardShow=UIMgrR.openIView(com.xq.view.modules.fourteenluxurygifts.IRewardShow,2);
			rewardShow.dataSource=rewardObj;
		}
	}

	FourteenAction.USE_FOURTEEN=88103000;
	FourteenAction.USE_FOURTEENP_one=88103001;
	return FourteenAction;
})(BaseMsgAction)


