	__proto.sendGetLiBaoInfo=function(type){
		var lbInfo=new GetLiBaoInfoCS();
		lbInfo.type=type;
		this._net.sendMsg(80200800,lbInfo);
	}

	__proto.onGetLiBaoInfo=function(byte){
		var vo=new GetLiBaoInfoSC();
		vo.decode(byte);
		if(vo.type==1){
			Mgr.kflbMgr.liBaoInfo(vo);
			}else if(vo.type==2){
			Mgr.kfxgMgr.liBaoInfo(vo);
			}else if(vo.type==3){
			Mgr.feiLongZaiTianMgr.getFeiLongZaiTianInfo(vo);
			}else if(vo.type==4){
			Mgr.qlbMgr.getLiBaoInfo(vo);
			}else if(vo.type==5){
			Mgr.qlbMgr.getYuanShiLiBaoInfo(vo);
			}else if(vo.type==6){
			Mgr.svipMiaoShaMgr.checkVipMiaoShaRed(vo);
		}
		else if(vo.type==9 || vo.type==7 || vo.type==8 || vo.type==11){
			Mgr.taoZhuangZhiGouMgr.setTaoZhuangZhigouInfo(vo);
		}
		else if(vo.type==10){
			Mgr.marriageMgr.updateSLHZ(vo);
		}
		else if(vo.type==12){
			Mgr.mergeSvrLiBao.updateInfo(vo);
		}
		else if(vo.type==13){
			var ary=vo.list;
			var l=ary.length;
			for (var i=0;i < ary.length;i++){
				var tt=ary[i]
				Mgr.xinWu.updateLibao(tt.id,tt);
			}
		}
	}

