	__proto.sendBuyLiBao=function(type,id){
		var bugLb=new BuyLiBaoCS();
		bugLb.type=type;
		bugLb.id=id;
		this._net.sendMsg(80200801,bugLb);
	}

	__proto.onBuyLiBao=function(byte){
		var vo=new BuyLiBaoSC();
		vo.decode(byte);
		if(vo.type==1){
			Mgr.kflbMgr.buyLiBao(vo);
			}else if(vo.type==2){
			Mgr.kfxgMgr.buyLiBao(vo);
			}else if(vo.type==3){
			Mgr.feiLongZaiTianMgr.gouMaiFeiLongZaiTian(vo);
			}else if(vo.type==4){
			Mgr.qlbMgr.getBuyQiLinBi(vo);
			}else if(vo.type==5){
			Mgr.qlbMgr.getYuanShiBuyQiLinBi(vo);
		}
		else if(vo.type==9 || vo.type==7 || vo.type==8 || vo.type==11){
			Mgr.taoZhuangZhiGouMgr.buyZhiGou(vo.type,vo.msg);
		}
		else if(vo.type==10){
			Mgr.marriageMgr.updateSinlegSLHZ(vo);
		}
		else if(vo.type==12){
			Mgr.mergeSvrLiBao.updateBuy(vo);
		}
		else if(vo.type==13){
			Mgr.xinWu.updateLibao(vo.msg.id,vo.msg);
		}
	}

