	__proto.getRandomXY=function(arr){
		var x=parseInt(arr[0]);
		var y=parseInt(arr[1]);
		var angle=Math.PI *2 *Math.random();
		var tx=Math.floor(x+Math.sin(angle)*200);
		var ty=Math.floor(y+Math.cos(angle)*200);
		return [tx,ty];
	}

