	/**拉取个人数据返回*/
	__proto.onGeRenBossHistory=function(data){
		var vo=new GerenBossHistorySC();
		vo.decode(data);
		var historyArr=vo.finished.split(";");
		var todayArr=vo.today.split(";");
		var grArr=this.gerenMgr.cfgArr;
		this.parserArr(grArr,todayArr,historyArr);
		var tqArr=this.gerenMgr.tequanBoss;
		this.parserArr(tqArr,todayArr,historyArr);
		EventCenter.instance.event("UPDATE_GERENBOSS");
		Mgr.geren.checkRed();
		Mgr.geren.checkTeQuanRed();
	}

	__proto.parserArr=function(cfgArr,todayArr,historyArr){
		var dic=this.gerenMgr.setTZBoss();
		var cur=NetMgr.ins().roleVO.level;
		var len=historyArr.length;
		var tLen=todayArr.length;
		var grLen=cfgArr.length;
		for(var i=0;i<grLen;i++){
			var o=cfgArr[i];
			if(o.type==5)
				o.order=parseInt(o.level);
			else
			o.order=parseInt(o.type);
			o.isKilled=false;
			if(o.level>cur){
				o.isLock=true;
			}
			else{
				o.isLock=false;
			}
			for(var j=0;j<tLen;j++){
				if(o.number==parseInt(todayArr[j])){
					o.isKilled=true;
					if(o.type==5)
						o.order=parseInt(o.level)+600;
					else
					o.order=parseInt(o.type)+600;
					break ;
				}
			}
			for(var k=0;k<len;k++){
				o.kSD=false;
				if(o.number==parseInt(historyArr[k])){
					o.kSD=true;
					break ;
				}
			}
		}
		cfgArr.sort(this.compare);
	}

	/**用于个人boss的排序*/
	__proto.compare=function(vo1,vo2){
		if(vo1 && vo2)
			return vo1.order-vo2.order;
		return 0;
	}

