var CommonAction=(function(_super){
	function CommonAction(){
		this.customDataDic={};
		this.v=new CommonErrSC();
		CommonAction.__super.call(this);
	}

	__class(CommonAction,'com.xq.modules.CommonAction',_super);
	var __proto=CommonAction.prototype;
	__proto.registerMsg=function(){
		this._methodDic[10086]=this.onError;
		this._methodDic[8819002]=this.onGetCustomData;
		this._methodDic[10085]=this.onServerUpdate;
		this._methodDic[10087]=this.onServerUpdate;
	}

	/**后端代码更新，前端刷新游戏*/
	__proto.onServerUpdate=function(b){
		AlertUtil.show("亲爱的玩家您好，游戏进行了一次不停服数据更新，是否现在重启游戏？","更新提示",Handler.create(this,this.onAlertHan));
	}

	__proto.onAlertHan=function(state){
		if(state=="OK"){
			ReconnectAction.getInstance().restart();
		}
	}

	__proto.onError=function(b){
		this.v.decode(b);
		var errId=this.v.err;
		if(errId==1002){
			UIMgrR.openIView(com.xq.view.modules.vip.IYuanBaoBuZuView,2);
			EventCenter.instance.event("YUANBAO_BUZU");
		}
		else if(errId==261124){
			AlertUtil.ShowAlert("装备背包空间不足，是否一键熔炼",Handler.create(this,this.toRongLian),null);
			}else if(errId==261125){
			AlertUtil.ShowAlert("道具背包空间不足，是否前往处理",Handler.create(this,this.toDaoJuBag),null);
			}else if(errId==261126){
			AlertUtil.ShowAlert("法宝背包空间不足，是否前往处理",Handler.create(this,this.toFaBao),null);
		}
		else if(errId==261127){
			AlertUtil.ShowAlert("宝石背包空间不足，是否前往合成",Handler.create(this,this.toHeCheng),null);
			}else if(errId==261128){
			AlertUtil.ShowAlert("图鉴背包空间不足，是否前往处理",Handler.create(this,this.toTuJian),null);
			}else if(errId==261129){
			AlertUtil.ShowAlert("天命背包空间不足，是否前往处理",Handler.create(this,this.toFenJie),null);
		}
		else if(errId !=5100 && errId !=5300){
			Mgr.prompt.optionPrompt(CodeMgr.ins.getStringByCode(errId));
		}
		console.log("错误码："+this.v.err+"内容："+CodeMgr.ins.getStringByCode(errId));
	}

	/**自动熔炼*/
	__proto.toRongLian=function(){
		Mgr.bag.autoSmeltEquip();
	}

	/**跳转道具背包*/
	__proto.toDaoJuBag=function(){
		UIMgrR.openViewByFunID("bag",null,2);
	}

	/**跳转法宝*/
	__proto.toFaBao=function(){
		UIMgrR.openViewByFunID("roleFaBao",null,2);
	}

	/**跳宝石合成*/
	__proto.toHeCheng=function(){
		UIMgrR.openViewByFunID("hecheng",null,2);
	}

	/**跳图鉴*/
	__proto.toTuJian=function(){
		UIMgrR.openViewByFunID("tujian",null,2);
	}

	/**跳天命分解*/
	__proto.toFenJie=function(){
		UIMgrR.openIView(com.xq.view.modules.tianming.ITianMingBreakView,2);
	}

	__proto.onGetCustomData=function(b){
		var msg=new GetCustomDataSC();
		msg.decode(b);
		var item;
		for(var $each_item in msg.datas){
			item=msg.datas[$each_item];
			this.customDataDic[item.key]=item.value;
		}
		Mgr.chat.setJingYanDic(this.customDataDic[1]);
		Mgr.setting.updateBgmV(parseFloat(this.customDataDic[2]));
		Mgr.setting.updateSoundV(parseFloat(this.customDataDic[3]));
		Mgr.setting.updateSubPlayerName(parseInt(this.customDataDic[5]));
		Mgr.wuLinHuanJingM.updateAutoUstItems(this.customDataDic[4]);
		Mgr.guanZMgr.startCheckInstallShortcut();
	}

	__proto.getCustomStr=function(key){
		return this.customDataDic[key];
	}

	__proto.initCustomData=function(keys){
		var getC=new GetCustomDataCS();
		getC.keys=keys;
		this._net.sendMsg(8819002,getC);
	}

	__proto.setCustomData=function(key,value){
		this.customDataDic[key]=value;
		Mgr.chat.setJingYanDic(value);
		var msg=new SetCustomDataCS();
		msg.key=key;
		msg.value=value;
		this._net.sendMsg(8819003,msg);
	}

	/**请求玩家showInfo*/
	__proto.sendGetRoleShowInfo=function(roleIdArr){
		var msg=new GetRoleShowInfoCS();
		msg.roleIds=roleIdArr;
		this._net.sendMsg(10087,msg);
	}

	/**收到请求玩家showInfo*/
	__proto.onGetRoleShowInfo=function(d){
		var msg=new GetRoleShowInfoSC();
		msg.decode(d);
	}

	CommonAction.COMMON_ERROR=10086;
	CommonAction.GET_CUSTOM_DATA=8819002;
	CommonAction.SET_CUTOM_DATA=8819003;
	CommonAction.Msg_10085=10085;
	CommonAction.Msg_10087=10087;
	CommonAction.CUSTOM_DATA_BLACLIST=1;
	CommonAction.CUSTOM_DATA_BGM=2;
	CommonAction.CUSTOM_DATA_SOUNDEFFECT=3;
	CommonAction.CUSTOM_DATA_YUANSHENHUANJINGAUTO=4;
	CommonAction.CUSTOM_DATA_SUBPLAYERNAME=5;
	CommonAction.CUSTOM_DATA_SHORTCUT=6;
	return CommonAction;
})(BaseMsgAction)


