	/**挑战boss返回*/
	__proto.onReceiveChallengSC=function(d){
		var msg=new JinDiBossChallengeSC();
		msg.decode(d);
		if(msg.errCode==1){
			var id=msg.id;
			Mgr.jindi.curBossNumber=id;
			var type=Mgr.jindi.getTypeByID(id);
			this.mjrq=false;
			EventCenter.instance.off("BOSS_OWER_CHANGE",this,this.setOwner);
			switch(type){
				case 4:
				case 3:
				case 1:
				case 10:
				case 16:
				case 17:
				case 18:
				case 19:
				case 20:
				case 21:
				case 22:
					EventCenter.instance.on("BOSS_OWER_CHANGE",this,this.setOwner,[17]);
					EventCenter.instance.once("APPLY_ENTER_SCENE",this,this.enterCopy,[msg.id,17]);
					EventCenter.instance.once("MAP_LOAD_OK",this,this.sendEnterFuben,[msg.id,17]);
					break ;
				case 2:
					EventCenter.instance.once("APPLY_ENTER_SCENE",this,this.enterCopy,[msg.id,6]);
					EventCenter.instance.once("MAP_LOAD_OK",this,this.sendEnterFuben,[msg.id,6]);
					break ;
				case 8:
					EventCenter.instance.on("BOSS_OWER_CHANGE",this,this.setOwner,[,16]);
					EventCenter.instance.once("APPLY_ENTER_SCENE",this,this.enterCopy,[msg.id,16]);
					EventCenter.instance.once("MAP_LOAD_OK",this,this.sendEnterFuben,[msg.id,16]);
					break ;
				case 9:
					EventCenter.instance.on("BOSS_OWER_CHANGE",this,this.setOwner,[16]);
					EventCenter.instance.once("APPLY_ENTER_SCENE",this,this.enterCopy,[msg.id,16]);
					EventCenter.instance.once("MAP_LOAD_OK",this,this.sendEnterFuben,[msg.id,16]);
					break
				case 11:
					EventCenter.instance.on("BOSS_OWER_CHANGE",this,this.setOwner,[18]);
					EventCenter.instance.once("APPLY_ENTER_SCENE",this,this.enterCopy,[msg.id,18]);
					EventCenter.instance.once("MAP_LOAD_OK",this,this.sendEnterFuben,[msg.id,18]);
					break ;
				case 12:
					this.mjrq=true;
					EventCenter.instance.on("BOSS_OWER_CHANGE",this,this.setOwner,[19]);
					EventCenter.instance.once("APPLY_ENTER_SCENE",this,this.enterCopy,[msg.id,19]);
					EventCenter.instance.once("MAP_LOAD_OK",this,this.sendEnterFuben,[msg.id,19]);
					break ;
				case 13:
					EventCenter.instance.on("BOSS_OWER_CHANGE",this,this.setOwner,[20]);
					EventCenter.instance.once("APPLY_ENTER_SCENE",this,this.enterCopy,[msg.id,20]);
					EventCenter.instance.once("MAP_LOAD_OK",this,this.sendEnterFuben,[msg.id,20]);
					break ;
				}
			EventCenter.instance.event("BossHall_Close");
		}
		else{
			if(!this.isAuto){
				Mgr.prompt.optionPrompt(CodeMgr.ins.getStringByCode(msg.errCode));
			}
		}
		this.isAuto=false;
	}

