//class com.xq.modules.danyao.DanYaoAction extends com.xq.core.net.BaseMsgAction
var DanYaoAction=(function(_super){
	function DanYaoAction(){
		/**丹药数据*/
		this.danYaoInfo=[];
		/**丹药数据*/
		this.danYaoDic={};
		/**总战力*/
		this.power=0;
		/**丹药配置表*/
		this.danyaoCfg=null;
		/**丹药配置表字典*/
		this.danyaoCfgDic=null;
		/**根据类型 保存此种丹 已使用数量*/
		this.danYaoUseDic=null;
		/**根据类型 保存此种丹 已使用数量*/
		this.danYaoMaxDic=null;
		this.red=null;
		this.fuhunMgr=null;
		this.arr=[];
		DanYaoAction.__super.call(this);
		this.danYaoUseDic=new Dictionary();
		this.danYaoMaxDic=new Dictionary();
		this.red=Mgr.red;
		this.fuhunMgr=Mgr.fuhun;
		this.danyaoCfgDic={};
		this.danyaoCfg=CfgManager.getTableCfg("DanYaoBiao");
		var danyaoCfgArr=this.danyaoCfg.objectDataArray;
		var len=danyaoCfgArr.length;
		for (var i=0;i < len;i++){
			this.danyaoCfgDic[danyaoCfgArr[i].id]=danyaoCfgArr[i];
		}
		EventCenter.instance.onQue("ITEM_CHANGE",this,this.checkDanYaoTab);
		EventCenter.instance.on("new_function_open",this,this.newOpenFun);
	}

	__class(DanYaoAction,'com.xq.modules.danyao.DanYaoAction',_super);
	var __proto=DanYaoAction.prototype;
	// init();
	__proto.newOpenFun=function(funId){
		if(funId=="roleDanyao"){
			this.checkDanYaoTab();
		}
	}

	/**
	*注册协议号
	*/
	__proto.registerMsg=function(){
		this._methodDic[881008000]=this.onReceiveDanYaoInfo;
		this._methodDic[881008001]=this.onUseDanYao;
		this._methodDic[881008002]=this.onQianNengDanInfo;
		this._methodDic[881008003]=this.onQianNengUpLv;
	}

	__proto.init=function(){
		var heroAry=Mgr.subPlayer.getHeroHeadList();
		var len2=heroAry.length;
		for (var j=0;j < len2;j++){
			var subVo=heroAry[j];
			if(!subVo)
				break
			this.sendDaoYaoInfoCS(subVo.roleId);
		}
		Mgr.danyaoPro.sendGetQianNeng(1);
		Mgr.danyaoPro.sendGetQianNeng(2);
		Mgr.danyaoPro.sendGetQianNeng(3);
		Mgr.danyaoPro.sendGetQianNeng(4);
		Mgr.danyaoPro.sendGetQianNeng(5);
		Mgr.danyaoPro.sendGetQianNeng(7);
		Mgr.danyaoPro.sendGetQianNeng(6);
		Mgr.danyaoPro.sendGetQianNeng(8);
		Mgr.danyaoPro.sendGetQianNeng(9);
		Mgr.danyaoPro.sendGetQianNeng(10);
		Mgr.danyaoPro.sendGetQianNeng(11);
		Mgr.danyaoPro.sendGetQianNeng(12);
		Mgr.danyaoPro.sendGetQianNeng(16);
		Mgr.danyaoPro.sendGetQianNeng(14);
		Mgr.danyaoPro.sendGetQianNeng(15);
		Mgr.danyaoPro.sendGetQianNeng(13);
	}

	__proto.onReceiveDanYaoInfo=function(data){
		var infoSC=new DanYaoInfoSC();
		infoSC.decode(data);
		this.danYaoDic[infoSC.roleId]=infoSC.infos;
		this.danYaoInfo=infoSC.infos;
		this.assemble(this.danYaoInfo);
		this.power=infoSC.fightValue;
		this.checkDanYaoTab();
		EventCenter.instance.event("update_danyao");
	}

	/**请求丹药信息*/
	__proto.sendDaoYaoInfoCS=function(id){
		(id===void 0)&& (id=-1);
		var msg=new DanYaoInfoCS();
		if(id==-1)
			msg.roleId=Mgr.subPlayer.curGuid;
		else
		msg.roleId=id;
		this._net.sendMsg(881008000,msg);
	}

	__proto.assemble=function(danYaoInfo){
		this.arr.length=0;
		var cfgArr=this.danyaoCfg.objectDataArray;
		for (var i=0;i < cfgArr.length;i++){
			var obj=cfgArr[i];
			var vo=new DanYaoVO();
			vo.templateId=obj.id;
			vo.name=obj.name;
			vo.limit=parseInt(obj.limit);
			for (var j=0;j < danYaoInfo.length;j++){
				var danYaoMsg=danYaoInfo[j];
				if (danYaoMsg.id==vo.templateId && danYaoMsg.todayNum >=vo.limit){
					vo.haveMax=true;
				}
			}
			this.arr.push(vo);
		}
	}

	/**
	*更加ID获取种类丹药信息
	*/
	__proto.getMsgInfoById=function(id){
		var tempInfo;
		var temp=this.danYaoDic[Mgr.subPlayer.curGuid];
		if(temp){
			for (var i=0;i < temp.length;i++){
				var obj=temp[i];
				if(obj.id==id){
					tempInfo=obj;
					break ;
				}
			}
		}
		return tempInfo;
	}

	/**
	*根据ID获取丹药的每日最大使用数量
	*/
	__proto.getDanYaoLimitById=function(id){
		var obj=this.danyaoCfg.getItemByField("id" ,id);
		return obj.limit;
	}

	/**
	*根据类型获取丹药配置表数据
	*/
	__proto.getDanYaoByType=function(type){
		var obj=this.danyaoCfg.getItemByField("type",type+"");
		return obj;
	}

	/**
	*更加ID获取丹药当前使用数量
	*/
	__proto.getDanYaoUseNumById=function(id){
		var obj=this.getMsgInfoById(id);
		if(obj)
			return obj.todayNum;
		return 0
	}

	/**
	*更加ID获取丹药的剩余使用次数
	*/
	__proto.getCountById=function(id){
		var count=0;
		if(this.danyaoCfg){
			var tempInfo=this.danyaoCfg.getItemByField("id" ,id);
			var info=this.getMsgInfoById(id);
			if(tempInfo){
				if(info){
					if(info.todayNum >=tempInfo.limit)
						count=-1;
					else
					count=tempInfo.limit-info.todayNum;
				}
				else
				count=tempInfo.limit;
			}
		}
		return count;
	}

	/**
	*获取类型丹药的总属性加成
	*/
	__proto.caculatePower=function(type){
		var addAtr=0;
		if(this.danyaoCfg){
			var tempInfo=this.danyaoCfg.getItemsByField("type" ,type);
			var v;
			for(var $each_v in tempInfo){
				v=tempInfo[$each_v];
				var msgInfo=this.getMsgInfoById(v.id);
				if(!msgInfo || msgInfo.totalNum <=0)
					continue ;
				addAtr=addAtr+parseInt(String(v.attribute).split(":")[1])*msgInfo.totalNum;
			}
		}
		return addAtr;
	}

	/**
	*获取当前丹药总战斗力加成
	*/
	__proto.getTotalLv=function(){
		var fv=0;
		for (var i=0;i < 3;i++){
			fv+=this.caculatePower(i+1);
		}
		return fv;
	}

	/**
	*检测丹药页签是否有红点
	*/
	__proto.checkDanYaoTab=function(){
		if(!Mgr.guide.isOpen("roleDanyao"))return;
		for (var i=1;i <=8;i++){
			this.red.hideRedPoint("roleDanyao",RedTypeEnum.RoleDanYaoRed+"_"+i,RedTypeEnum.RoleDanYaoRed);
		}
		this.danYaoUseDic.clear();
		this.danYaoMaxDic.clear();
		var serverArr=this.danYaoDic[NetMgr.ins().roleVO.guid];
		if(!serverArr)
			return;
		var len=serverArr.length;
		for (var i=0;i< len;i++){
			var cfgObj=this.danyaoCfgDic[serverArr[i].id];
			if(!cfgObj)
				continue ;
			if(this.danYaoUseDic.get(cfgObj.type)){
				this.danYaoUseDic.set(cfgObj.type,this.danYaoUseDic.get(cfgObj.type)+serverArr[i].todayNum);
			}
			else{
				this.danYaoUseDic.set(cfgObj.type,serverArr[i].todayNum);
			}
			if(this.danYaoMaxDic.get(cfgObj.type)){
				this.danYaoMaxDic.set(cfgObj.type,this.danYaoMaxDic.get(cfgObj.type)+parseInt(cfgObj.limit));
			}
			else{
				this.danYaoMaxDic.set(cfgObj.type,parseInt(cfgObj.limit));
			}
			if(serverArr[i].todayNum < parseInt(cfgObj.limit)&& Mgr.item.checkMatIsEnou(serverArr[i].id+":"+1)){
				this.red.showRedPoint("roleDanyao",RedTypeEnum.RoleDanYaoRed+"_"+cfgObj.type,RedTypeEnum.RoleDanYaoRed);
			}
		}
	}

	/**
	*刷新丹药红点
	*/
	__proto.refreshDanyaoRed=function(){
		var bagGoodArr=Mgr.bag.bagGoodsArr;
		var len=this.arr.length;
		for (var i=0;i < len;i++){
			var danYaoVO=this.arr[i];
			for (var j=0;j < bagGoodArr.length;j++){
				var goodVO=bagGoodArr[j];
				if (goodVO && danYaoVO.haveMax==false && goodVO.templateId==danYaoVO.templateId){
					return;
				}
			}
		}
	}

	__proto.sendUseDanYao=function(id,count){
		var msg=new UseDanYaoInfoCS();
		msg.itemGuid=id;
		msg.count=count;
		msg.roleId=Mgr.subPlayer.curGuid;
		this._net.sendMsg(881008001,msg);
	}

	__proto.onUseDanYao=function(b){
		var msg=new UseDanYaoInfoSC();
		msg.decode(b);
		if(msg.errCode==1){
			Mgr.danyaoPro.sendDaoYaoInfoCS();
		}
	}

	/**拉去潜能丹信息*/
	__proto.sendGetQianNeng=function(type){
		if(!type)return;
		var msg=new QianNengDanInfoCS();
		msg.type=type;
		this._net.sendMsg(881008002,msg);
	}

	/**收到后端返回的潜能丹信息*/
	__proto.onQianNengDanInfo=function(b){
		var msg=new QianNengDanInfoSC();
		msg.decode(b);
		this.fuhunMgr.setFuHunMsg(msg);
		this.fuhunMgr.refreshRed();
	}

	/**升级潜能丹信息*/
	__proto.sendQianNengUpLv=function(type,danYaoTip,typeId,isUseAll){
		(isUseAll===void 0)&& (isUseAll=false);
		var msg=new UseQianNengDanCS();
		msg.type=type;
		msg.danYaoType=danYaoTip;
		msg.isOneKey=isUseAll;
		this._net.sendMsg(881008003,msg);
	}

	/**收到后端返回的潜能丹信息*/
	__proto.onQianNengUpLv=function(b){
		var msg=new UseQianNengDanSC();
		msg.decode(b);
		if(msg.errorCode==1){
			var data=msg.msg;
			var fuhunType=data.type;
			var vo=this.fuhunMgr.getFuHunVo(fuhunType);
			vo.setServerMsg(data);
			EventCenter.instance.event("UpdateFuHun");
			}else{
			if(msg.errorCode!=0){
				Mgr.prompt.optionPrompt(msg.errorCode);
			}
		}
	}

	DanYaoAction.DANYAOINFOCS=881008000;
	DanYaoAction.DANYAOINFOSC=881008000;
	DanYaoAction.USE_DANYAO=881008001;
	DanYaoAction.GET_QIAN_NENG_INFO=881008002;
	DanYaoAction.USE_QIAN_NENG_INFO=881008003;
	DanYaoAction.UPDATE_DANYAO="update_danyao";
	DanYaoAction.COUNT=3;
	return DanYaoAction;
})(BaseMsgAction)


