//class com.xq.modules.douyinGame.DouYinGameAction extends com.xq.core.net.BaseMsgAction
var DouYinGameAction=(function(_super){
	function DouYinGameAction(){
		this.dyGMgr=null;
		DouYinGameAction.__super.call(this);
		Cmd.regCmd("进入BOSS",Handler.create(this,this.enter,[1],false));
		Cmd.regCmd("进入PK",Handler.create(this,this.enter,[2],false));
		Cmd.regCmd("退出",Handler.create(this,this.exit,null,false));
		Cmd.regCmd("召唤BOSS",Handler.create(this,this.sendCreateMonster,[1],false));
		this.dyGMgr=Mgr.douyinGameM;
		if(Configs.dyzbjId){
			this.enter();
		}
		EventCenter.instance.on("OfflineAndReconnection",this,this.reconnectEnter);
	}

	__class(DouYinGameAction,'com.xq.modules.douyinGame.DouYinGameAction',_super);
	var __proto=DouYinGameAction.prototype;
	/**注册协议号*/
	__proto.registerMsg=function(){
		this._methodDic[80206802]=this.onDouYinGameFubenInfo;
		this._methodDic[80206803]=this.onDouYinGameCreateMonster;
		this._methodDic[80206804]=this.onDouYinGameCreatePlayer;
		this._methodDic[80206805]=this.onDouYiGamePlayerUpgrad;
		this._methodDic[80206806]=this.onDouYinGameBossEnd;
		this._methodDic[80206807]=this.onDouYinGameHeJiValue;
		this._methodDic[80206808]=this.onDDouYinGameHeJiUse;
	}

	__proto.onDDouYinGameHeJiUse=function(b){
		var p=new DouYinGameHeJiUseSC();
		p.decode(b);
		EventCenter.instance.event("HejiUse",[p.type]);
		Mgr.douyinGameM.useHeJi(p.type);
	}

	__proto.onDouYinGameHeJiValue=function(b){
		var p=new DouYinGameHeJiAddValueSC();
		p.decode(b);
		EventCenter.instance.event("HeJiChangePro",[p.type,p.value,p.maxValue]);
	}

	__proto.reconnectEnter=function(){
		Laya.timer.once(3000,this,this.enter);
	}

	__proto.enter=function(type){
		(type===void 0)&& (type=1);
		var zhibojianId=Configs.dyzbjId;
		if(!zhibojianId){
			return;
		}
		Game.getInstance().player.isPermitMove=true;
		Mgr.juqing.end();
		var p=new DouYinGameEnterCS();
		p.type=type;
		p.id=zhibojianId;
		this.dyGMgr.type=type;
		Laya.timer.once(3000,this.dyGMgr,this.dyGMgr.changeView,[true]);
		console.log("发送进入抖音单机本",type);
		NetMgr.ins().sendMsg(80206800,p)
	}

	__proto.exit=function(){
		console.log("发送退出抖音单机本");
		this.dyGMgr.type=0;
		this.dyGMgr.changeView(false);
		NetMgr.ins().sendMsg(80206801);
	}

	__proto.onDouYiGamePlayerUpgrad=function(b){
		var p=new DouYiGamePlayerUpgradSC();
		p.decode(b);
		this.dyGMgr.upgradeLvPlayer(p.id,p.level);
	}

	__proto.sendCreatePlayer=function(name){
		var p=new DouYinGameCreatePlayerCS();
		p.name=name;
		console.log("召唤玩家"+name);
		NetMgr.ins().sendMsg(80206804,p);
	}

	__proto.onDouYinGameCreatePlayer=function(b){
		var p=new DouYinGameCreatePlayerSC();
		p.decode(b);
		this.dyGMgr.registerPlayer(p.playerInfo);
	}

	__proto.sendCreateMonster=function(mtype){
		(mtype===void 0)&& (mtype=0);
		var p=new DouYinGameCreateMonsterCS();
		p.mType=mtype;
		this.dyGMgr.mType=mtype;
		console.log("召唤Boss"+mtype);
		NetMgr.ins().sendMsg(80206803,p);
	}

	__proto.onDouYinGameCreateMonster=function(b){
		var p=new DouYinGameCreateMonsterSC();
		p.decode(b);
		this.dyGMgr.enterTime=p.time;
		this.dyGMgr.endTime=p.endTime;
		this.dyGMgr.curBossId=p.mId;
		this.dyGMgr.curBossCallname=p.callName;
		EventCenter.instance.event("BossEnterTime",[p]);
		console.log(p.callName+"成功召唤Boss"+p.mType,p.mId,p.time);
	}

	__proto.onDouYinGameFubenInfo=function(b){
		var p=new DouYinGameFubenInfoSC();
		p.decode(b);
		this.dyGMgr.rankArr=p.infos;
		this.dyGMgr.wave=p.wave;
		EventCenter.instance.event("FubenInfoRefrsh",[p]);
	}

	__proto.onDouYinGameBossEnd=function(b){
		var p=new DouYinGameBossEndSC();
		p.decode(b);
		this.dyGMgr.wave=p.wave;
		var v=UIMgrR.getIView(com.xq.view.modules.douyinGame.IDouYinGameResultView);
		v.setData(p.suc);
		v.x=(Laya.stage.width-v.width)>>1;
		v.y=(Laya.stage.height-v.height)>>1;
		Game.getInstance().addChild(v);
		EventCenter.instance.event("BossEndResult");
		console.log("Boss挑战结束",p.suc,p.wave);
		this.dyGMgr.hideBossBlood();
	}

	DouYinGameAction.DouYinGameEnter=80206800;
	DouYinGameAction.DouYinGameExit=80206801;
	DouYinGameAction.DouYinGameFubenInfo=80206802;
	DouYinGameAction.DouYinGameCreateMonster=80206803;
	DouYinGameAction.DouYinGameCreatePlayer=80206804;
	DouYinGameAction.DouYinGamePlayerUpgrad=80206805;
	DouYinGameAction.DouYinGameBossEnd=80206806;
	DouYinGameAction.DouYinGameHeJiValue=80206807;
	DouYinGameAction.DouYinGameHeJiUse=80206808;
	return DouYinGameAction;
})(BaseMsgAction)


