	/**发送拉取装备列表*/
	__proto.sendGetRoleEquipMsg=function(guid){
		var msg=new EquipListCS();
		msg.roleId=NetMgr.ins().roleVO.guid;
		if(!guid)return;
		this._net.sendMsg(8831000,msg);
	}

	/**拉取装备列表*/
	__proto.receiveE=function(data){
		var equipListSC=new EquipListSC();
		equipListSC.decode(data);
		var items=equipListSC.items;
		var len=items.length;
		var equipArr=[];
		var zuoQiArr=[];
		for (var i=0;i < len;i++){
			var itemMsg=items[i]
			if (itemMsg.slotNum <=-1 && itemMsg.slotNum >=-19){
				equipArr.push(itemMsg);
			}
			else if (itemMsg.slotNum <=-101 && itemMsg.slotNum >=-404){
				zuoQiArr.push(itemMsg);
			}
		}
		Mgr.equip.updatePaylineEquip(zuoQiArr);
		Mgr.equip.updateEquipList(equipListSC);
		Mgr.equip.totalLv(equipArr);
		Mgr.shenZhuMgr.getShenZhuDic();
		EventCenter.instance.event("equip_info");
	}

