	/**
	*收到激活装备奖励
	*/
	__proto.rCR=function(data){
		var e=new EquipSuitRewardSC();
		e.decode(data);
		if (e.errCode==1){
			var suitMsg=Mgr.suit.getSuitSerValue(e.id);
			suitMsg.suitEquipState=e.suitEquipState;
			Mgr.suit.setSuitSerValue(suitMsg);
			Mgr.suit.checkSuitTabRedPoint();
			if((e.equipNum==0 || e.equipNum==8)){
				var curCfg=Mgr.suit.getSuitMsgById(e.id);
				Mgr.prompt.optionPrompt("恭喜收集"+8+"件成功，获得属性奖励");
				EventCenter.instance.event("EQUIP_COLLECT");
			}
			else{
				EventCenter.instance.event("GUIDE_SUIT_UPDAE");
				Mgr.prompt.optionPrompt("恭喜收集"+e.equipNum+"件成功，获得属性奖励");
			}
			Mgr.suit.setMaxShowSuitTab(e.bigId);
		}
		else{
			if(e.errCode==5102){
				Mgr.prompt.optionPrompt("已全部激活");
			}
			else{
				Mgr.prompt.optionPrompt(CodeMgr.ins.getStringByCode(e.errCode));
			}
		}
	}

