	__proto.rW=function(data){
		var e=new EquipXiLianSC();
		e.decode(data);
		Mgr.equip.changeCurModel(Mgr.subPlayer.curGuid);
		if (e.errcode==1){
			var p=e.equipXiLianMsg;
			var type=e.xiLianType;
			var lockIdArr=e.lockXiLianId;
			var freeTimes=e.freeNum;
			Mgr.equipWashMgr.curWashPart=e.equipXiLianMsg.dressPart;
			Mgr.equipWashMgr.equipWashSC=e;
			Mgr.equipWashMgr.wash(p,type,lockIdArr,freeTimes);
			var lenl=e.equipXiLianMsg.xiLianAttributeMsgList.length;
			for (var i=0;i <lenl;i++){
				var mag=e.equipXiLianMsg.xiLianAttributeMsgList[i];
				if(mag.xiLianId==0)
					debugger
			}
			if(!Mgr.equipWashMgr.isOpenWashPanel){
				var equopwash=UIMgrR.openIView(com.xq.view.modules.equip.wash.IEquipWashPanel,2);
			}
			equopwash.dataSource=p;
		}
		else{
			if(e.errcode){
				UIMgrR.openIView(com.xq.view.modules.vip.IYuanBaoBuZuView,2);
			}
			else{
				Mgr.prompt.optionPrompt(CodeMgr.ins.getStringByCode(e.errcode));
			}
		}
	}

