	/**
	*共鸣激活类型，20强化八件、24宝石、 126强化十件 等级为0时为拉取信息
	*/
	__proto.sendGongMing=function(type,level,openType){
		(openType===void 0)&& (openType=0);
		var msg=new GongMingJiaChengCSC();
		msg.type=type;
		msg.level=level;
		if(level==0 && openType==0)
			this.isOnce=1;
		else if(level==0 && openType==2)
		this.isOnce=2;
		else if(level > 0)
		this.isOnce=3;
		msg.roleId=Mgr.subPlayer.curGuid;
		this._net.sendMsg(8831019,msg);
	}

	/**收到共鸣激活或拉去共鸣信息*/
	__proto.receiveGongMing=function(b){
		var msg=new GongMingJiaChengCSC();
		msg.decode(b);
		Mgr.equip.changeCurModel(Mgr.subPlayer.curGuid);
		if(msg.type){
			Mgr.equip.curModel.gongMingDic[msg.type]=msg;
			if(this.isOnce==3 && msg)
				EventCenter.instance.event("updata_equip_resonance",[msg]);
			else if(this.isOnce==1)
			EventCenter.instance.event("GONGMING_INFO",[msg.type]);
			EventCenter.instance.event("updata_forge_fight");
			if(msg.type==20 || msg.type==126){
				Mgr.strenAndStar.checkGongMingRed(msg);
			}
			else{
				Mgr.gemMgr.checkGongMingRed(msg);
			}
		}
	}

