	__proto.onGetInfo=function(b){
		var vo=new GetTeamFubenInfoSC();
		vo.decode(b);
		NetMgr.ins().roleVO.meili=vo.charm;
		this.mgr.fengshenRank=vo.ranks;
		this.mgr.rank=vo.myRank;
		this.mgr.refreshFengShenLuRed(vo.maxId);
		this.mgr.maxId=vo.maxId;
		this.mgr.isSaoDang=vo.saoDangState;
		if(this.mgr.cfgMaxId > vo.maxId){
			this.mgr.curId=vo.maxId+1;
			}else{
			this.mgr.curId=vo.maxId;
		}
		this.mgr.historyMaxId=vo.historyMaxId;
		if(this.mgr.teamArr.length==0){
			this.mgr.curChallangeId=this.mgr.curId;
			if(this.mgr.cfgDic[vo.maxId+1]){
				var vo1=new CreateTeamCSC();
				vo1.id=vo.maxId+1;
				this.mgr.isCreater=true;
			}
			else{
				this.mgr.isCreater=false;
			}
		}
		else{
			console.log("已有队伍，直接刷新");
			EventCenter.instance.event("FSL_UPDATE_TEAM");
		}
		EventCenter.instance.event("FSL_UPDATE_GUANKA",[vo]);
	}

