//class com.xq.modules.guildParty.GuildPartyAction extends com.xq.core.net.BaseMsgAction
var GuildPartyAction=(function(_super){
	function GuildPartyAction(){
		this.coolectEF=null;
		/**---------------------------------------CS------------------------------------------*/
		this._isInParty=false;
		/**活动结束后一次蓄力的特效*/
		this.baseAni3d1=null;
		/**蓄力之后喷发奖励特效*/
		this.baseAni3d2=null;
		GuildPartyAction.__super.call(this);
	}

	__class(GuildPartyAction,'com.xq.modules.guildParty.GuildPartyAction',_super);
	var __proto=GuildPartyAction.prototype;
	__proto.registerMsg=function(){
		this._msgList=[881005208,881005200,881005211,881005203,881005202
		,881005201,881000223,881005205,881005212]
	}

	__proto.onMesgage=function(data){
		switch(data.msgId){
			case 881005208:
				this.onReceiveEnterScene(data.data);
				break ;
			case 881005200:
				this.onReceiveAnswerData(data.data);
				break ;
			case 881005211:
				this.onReceiveEXP(data.data);
				break ;
			case 881005203:
				this.onReceiveAnswertopic(data.data);
				break ;
			case 881005202:
				this.onReceiveAnswerResponse(data.data);
				break
			case 881005201:
				this.onReceiveRankiList(data.data);
				break ;
			case 881000223:
				this.onReceiveAnswerEnd(data.data);
				break ;
			case 881005205:
				this.onReceiveAnswerPutReward(data.data);
				break ;
			case 881005223:
				this.onReceivePartyEnd(data.data);
				break ;
			case 881005212:
				this.onReceiveExit(data.data);
				break ;
			}
	}

	/**进入场景返回*/
	__proto.onReceiveEnterScene=function(byte){
		var msg=new EnterFactionPartyStageSC;
		msg.decode(byte);
		if(msg.result==0){
			Mgr.guildParty.activityTimes=msg.remainTime;
			Mgr.guildParty.registerCollectClick(true);
			}else if(msg.result==3){
			Mgr.prompt.optionPrompt("没有帮派");
			}else{
			Mgr.prompt.optionPrompt("不在活动时间内哦");
		}
	}

	/**获取聚会信息*/
	__proto.onReceiveAnswerData=function(byte){
		var msg=new ActivityInfoSC;
		msg.decode(byte);
		if(msg.isOnAnswerTime==0){
			Mgr.guildParty.answerBeginTimes=msg.cdTime;
			var str=CommonUtil.formatDate(msg.cdTime,5);
			Mgr.consoleMgr.info(str);
			}else{
			Mgr.guildParty.answerCdtimes=msg.cdTime;
			UIMgrR.closeAllPanelBylv(1);
			Mgr.guildParty.setAnswerMsg(msg.answerSchedule.rankInfo);
		}
	}

	/**推送获得经验*/
	__proto.onReceiveEXP=function(byte){
		var msg=new PushExpChangeSC;
		msg.decode(byte);
		Mgr.guildParty.ownexp=msg.exp;
		this.coolectEF=CoolingMaskUtil.createCollectEff("聚会经验",4800,350,Laya.stage.height-270,Laya.stage,null);
	}

	/**下发题目题目*/
	__proto.onReceiveAnswertopic=function(byte){
		if(!this._isInParty)
			return;
		var msg=new PushQuestionSC;
		msg.decode(byte);
		UIMgrR.closeAllPanelBylv(1);
		Mgr.guildParty.subjectCount=msg.count;
		Mgr.guildParty.subjectId=msg.id;
	}

	/**返回答案是否正确*/
	__proto.onReceiveAnswerResponse=function(byte){
		var msg=new AnswerTopicSC;
		msg.decode(byte);
	}

	/**宗门答题排行*/
	__proto.onReceiveRankiList=function(byte){
		var msg=new PushZongMenRankSC;
		msg.decode(byte);
		Mgr.guildParty.setAnswerMsg(msg.rankInfo);
	}

	/**答题结束*/
	__proto.onReceiveAnswerEnd=function(byte){
		var msg=new AnswerActivityOverSC;
		msg.decode(byte);
	}

	/**推送奖励*/
	__proto.onReceiveAnswerPutReward=function(byte){
		var msg=new PushFactionPartyBoxSC;
		msg.decode(byte);
		this.playXuliEffect();
	}

	/**宗门聚会结束*/
	__proto.onReceivePartyEnd=function(byte){
		var msg=new FactionPartyTimeOverSC;
		msg.decode(byte);
		Mgr.guildParty.registerCollectClick(false);
	}

	/**退出场景*/
	__proto.onReceiveExit=function(byte){
		var msg=new FactionPartyExitStageSC;
		msg.decode(byte);
		if(this.coolectEF)
			this.coolectEF.dispose();
		console.log("收到宗门退出协议！");
	}

	/**请求进入场景*/
	__proto.onRequestJoinScene=function(){
		this._isInParty=true;
		this._net.sendMsg(881005208);
	}

	/**拉取题目*/
	__proto.onRequestAnswertopic=function(){
		this._net.sendMsg(881005203);
	}

	/**发送答题*/
	__proto.onRequestAnswerKey=function(arr){
		var msg=new AnswerTopicCS;
		msg.count=arr[0];
		msg.answer=arr[1];
		this._net.sendMsg(881005202,msg);
	}

	/**请求退出场景*/
	__proto.onRequestExitScene=function(){
		this._isInParty=false;
		this._net.sendMsg(881005212);
		this.disposeEffect();
		Mgr.guildParty.registerCollectClick(false);
	}

	__proto.playXuliEffect=function(){
		if(this.baseAni3d1){
			this.baseAni3d1.dispose();
			this.baseAni3d1=null;
		}
		this.baseAni3d1=new SceneAni();
		this.baseAni3d1.setRes(PathDefine.EFFECT+"dapenfaqianxuli"+".amt");
		this.baseAni3d1.x=3229;
		this.baseAni3d1.y=1446;
		this.baseAni3d1.loopTimes=1;
		SceneContainer.getInstance().topLayer.addChild(this.baseAni3d1);
		Laya.timer.once(700,this,this.scenePenfa);
	}

	__proto.scenePenfa=function(){
		if(this.baseAni3d2){
			this.baseAni3d2.dispose();
			this.baseAni3d2=null;
		}
		this.baseAni3d2=new SceneAni();
		this.baseAni3d2.setRes(PathDefine.EFFECT+"pencaibao"+".amt");
		this.baseAni3d2.loopTimes=4;
		this.baseAni3d2.x=3280;
		this.baseAni3d2.y=1446;
		SceneContainer.getInstance().topLayer.addChild(this.baseAni3d2);
	}

	/**删除特效*/
	__proto.disposeEffect=function(){
		if(this.baseAni3d1){
			this.baseAni3d1.dispose();
			this.baseAni3d1=null;
		}
		if(this.baseAni3d2){
			this.baseAni3d2.dispose();
			this.baseAni3d2=null;
		}
	}

	GuildPartyAction.GUILDSCENEJOIN=881005208;
	GuildPartyAction.GUILDPARTYDATA=881005200;
	GuildPartyAction.GUILDPARTYEXP=881005211;
	GuildPartyAction.GUILDANSWERTIMUTOPIC=881005203;
	GuildPartyAction.GUILDRANKLIST=881005201;
	GuildPartyAction.GUILDANSWERRETURN=881005202;
	GuildPartyAction.GUILDANSWEREND=881000223;
	GuildPartyAction.GUILDANSWERRAWARD=881005205;
	GuildPartyAction.GUILDPARTYEND=881005223;
	GuildPartyAction.EXITSCENE=881005212;
	return GuildPartyAction;
})(BaseMsgAction)


