//class com.xq.modules.meiribizuo.MeirihuodongAction extends com.xq.core.net.BaseMsgAction
var MeirihuodongAction=(function(_super){
	function MeirihuodongAction(){
		/**每日必做配置数据*/
		this.meiribizuoCfg=null;
		/**每日限时活动*/
		this.mrhdCfg=null;
		/**每日限时活动过滤已经过期的活动*/
		this.meirihuodongData=null;
		/**奖励数据*/
		this.rewardData=null;
		/**拉取每日必做信息*/
		this.LAQUMEIRIBIZUO=881000200;
		/**领取奖励*/
		this.LINGQUJIANGLI=881000205;
		/**同步数据*/
		this.TONGBUSHUJU=881000202;
		/**文散馆升级*/
		this.WENSANGUAN_UP_lEVEL=80201100;
		/**储存每个ID对应的完成次数*/
		this.countDataInfo=null;
		/**活动开启中*/
		this.isOpen=false;
		this.red=null;
		/**多被活动表格*/
		this.duobeiCfg=null;
		this.meiribizuoArr=null;
		this.delayShow=[];
		this.activeId=null;
		this.activityList=null;
		this.weekday=7;
		this.activeTable=null;
		this.activeTableArr=null;
		/**周例标签*/
		this.weeksLables=null;
		/**当前所选中的周几*/
		this.selectToday=0;
		this.today=0;
		MeirihuodongAction.__super.call(this);
		this.meiribizuoCfg=CfgManager.getTableCfg("meiribizuo");
		this.mrhdCfg=CfgManager.getTableCfg("meirihuodong");
		this.rewardData=CfgManager.getTableCfg("meiribizuojiangli");
		Laya.timer.once(1000,this,this.checkActivityStatus);
		ServerClock.getInstance().startClock();
		this.red=Mgr.red;
		this.red.regist("huodong","xianshihuodong");
		this.red.regist("huodong","yaomojindi");
		this.red.regist("huodong","xuezhanmuye");
		this.red.regist("richang","meiribizuo",true,"ACT_CORNER_UPDATE");
	}

	__class(MeirihuodongAction,'com.xq.modules.meiribizuo.MeirihuodongAction',_super);
	var __proto=MeirihuodongAction.prototype;
	/**
	*所需要监听的Socket Code
	*
	**/
	__proto.registerMsg=function(){
		this._methodDic[this.LAQUMEIRIBIZUO]=this.rGetDaily;
		this._methodDic[this.LINGQUJIANGLI]=this.getReward;
		this._methodDic[this.TONGBUSHUJU]=this.upRightNowData;
		this._methodDic[this.WENSANGUAN_UP_lEVEL]=this.onWenSanGuanUpLevel;
	}

	/**
	*发送拉取每日必做信息
	*/
	__proto.sGetDaily=function(){
		this._net.sendMsg(this.LAQUMEIRIBIZUO);
	}

	/**
	*收到拉取每日必做信息
	*/
	__proto.rGetDaily=function(byte){
		var r=new GetDailyInfoSC;
		r.decode(byte);
		this.countDataInfo=r;
		Mgr.meiRiBiMgr.curWenSanCfg=r.levelid;
		Mgr.meiRiBiMgr.curWenSanRewardCfg=r.rewardLevelId;
		this.meiribizuoArr=r.dailyInfoList;
		this.checkHasSteak();
		EventCenter.instance.event("LAQUMEIRIBIZUO_DATA",r);
	}

	/**
	*发送领奖
	*
	*/
	__proto.sendRequestGetReward=function(id){
		var vo=new GetDailyMustDoRewardCS;
		vo.id=id;
		this._net.sendMsg(this.LINGQUJIANGLI,vo);
	}

	/**领取奖励*/
	__proto.getReward=function(byte){
		var vo=new GetDailyMustDoRewardSC;
		vo.decode(byte);
		if(vo.resultCode==1){
			this.countDataInfo.rewardList.push(vo.id);
			this.checkHasSteak()
			EventCenter.instance.event("LAQUMEIRIBIZUO_DATA",vo);
		}
		else{
			Mgr.prompt.optionPrompt(CodeMgr.ins.getStringByCode(vo.resultCode));
		}
	}

	__proto.upRightNowData=function(byte){
		var vo=new UpdateInfo;
		vo.decode(byte);
		if(this.countDataInfo){
			this.countDataInfo.dailyInfoList=vo.updateInfoLists;
			this.checkHasSteak();
			EventCenter.instance.event("LAQUMEIRIBIZUO_DATA",vo);
		}
	}

	/**
	*发送领取文散馆奖励
	*/
	__proto.sendWenSanGuanUpLevel=function(){
		this._net.sendMsg(this.WENSANGUAN_UP_lEVEL);
	}

	__proto.onWenSanGuanUpLevel=function(byte){
		var vo=new UpLevelSC();
		vo.decode(byte);
		Mgr.meiRiBiMgr.curWenSanRewardCfg=vo.rewardLevelId;
		this.sGetDaily();
	}

	/**------------------------------------------------model------------------------------------------------------*/
	__proto.checkHasSteak=function(){
		if(!Mgr.guide.isOpen("meiribizuo"))
			return;
		var curXiuwei=this.countDataInfo.activityValue;
		var rList=this.rewardData.objectDataArray;
		var sRlist=this.countDataInfo.rewardList;
		var leg=rList.length;
		var len=sRlist.length;
		var corNum=0;
		if(Mgr.meiRiBiMgr.getCurWenSanRewardCfg()&& this.countDataInfo.rewardLevelId <=this.countDataInfo.levelid){
			Mgr.red.showRedPoint("meiribizuo","mrbzShengJie","ACT_CORNER_UPDATE");
			}else{
			Mgr.red.hideRedPoint("meiribizuo","mrbzShengJie","ACT_CORNER_UPDATE");
		}
		for(var i=0;i<leg;i++){
			var hasGet=false;
			var obj=rList[i];
			for(var j=0;j<len;j++){
				var str=sRlist[j];
				if(str==obj.id){
					hasGet=true;
				}
			}
			if(curXiuwei >=obj.xiuwei&&!hasGet){
				Mgr.red.showRedPoint("meiribizuo","mrbzRwdGet","ACT_CORNER_UPDATE");
				return;
			}
			else{
				Mgr.red.hideRedPoint("meiribizuo","mrbzRwdGet","ACT_CORNER_UPDATE");
			}
		}
	}

	/**
	*给每日的活动添加闹钟功能再将每日的活动存储起来
	*/
	__proto.checkActivityStatus=function(){
		var openNums=0;
		this.meirihuodongData=[];
		var kaifuday=CommonUtil.openServerDay;
		var serverDate=Mgr.curTime.serverDate;
		var serverDay=serverDate.getDay();
		if(serverDay==0)serverDay=7;
		var isInServerSevenDay=CommonUtil.checkIsInSevenDay();
		var vo;
		for(var $each_vo in this.mrhdCfg.objectDataArray){
			vo=this.mrhdCfg.objectDataArray[$each_vo];
			var hasShow=false;
			var arr=vo.time.split("-");
			vo.startTime=arr[0];
			vo.endTime=arr[1];
			var starts=arr[0].split(":");
			var ends=arr[1].split(":");
			var startTime=TextUtil.timeToMilSeconds(starts[0],starts[1],0);
			var endTime=TextUtil.timeToMilSeconds(ends[0],ends[1],0);
			var offsetTime=-TextUtil.timeToMilSeconds(0,5,0);
			hasShow=this.isTodayActive(vo,serverDay+"",isInServerSevenDay,kaifuday);
			if(hasShow){
				if(vo.specialTime){
					var openServerTimes=0;
					var durationMinute=NaN;
					var timeList;
					var offDayList;
					var activityInfo=CommonUtil.getNextOpenTime(serverDate,vo.specialTime,kaifuday,vo.kaifutime);
					if(activityInfo){
						vo.openType=parseInt(activityInfo[1]);
					}
					else{
						vo.openType=1;
					}
					if(vo.openType !=0){
						if(isInServerSevenDay && vo.kaifutime){
							if(hasShow){
								ServerClock.getInstance().registerDailyAlarmClock(Handler.create(this,this.activityStart,[vo.id],false),startTime,endTime-startTime);
								ServerClock.getInstance().registerDailyAlarmClock(Handler.create(this,this.activityEnd,[vo.id],false),endTime,0);
							};
							var first7DaysStartTime;
							openServerTimes=NetMgr.ins().serverVO.openTime;
							var isUioned=NetMgr.ins().serverVO.combineTime > 0;
							if(isUioned){
							}
							else{
								first7DaysStartTime=this.jointString(vo.kaifutime,vo.startTime);
								offDayList=TextUtil.getServerBeforeDayList(first7DaysStartTime);
								var activeOpenTime=TextUtil.getTimeList(first7DaysStartTime);
								activeOpenTime=activeOpenTime[0];
								var index=0;
								var len=offDayList.length;
								while(index < len){
									ServerClock.getInstance().registerDayAfterServerStartAlarmClock(Handler.create(this,this.activityStart,[vo.id],false),openServerTimes,0,offDayList[index],TextUtil.timeToMilSeconds(activeOpenTime[0],activeOpenTime[1],0),0);
									ServerClock.getInstance().registerDayAfterServerStartAlarmClock(Handler.create(this,this.activityEnd,[vo.id],false),openServerTimes,0,offDayList[index],TextUtil.timeToMilSeconds(ends[0],ends[1],0),0);
									index++;
								}
							}
							}else{
							var joint=vo.specialTime.split("-");
							var str=String(joint[0])+"]";
							var weekDayList=TextUtil.getServerAfterDayList(str);
							durationMinute=TextUtil.timeToMilSeconds(ends[0],ends[1],0);
							timeList=TextUtil.getTimeList(str);
							timeList=timeList[0];
							ServerClock.getInstance().registerWeekAlarmClock(weekDayList,timeList,openServerTimes,durationMinute,Handler.create(this,this.activityStart,[vo.id],false),0);
							ServerClock.getInstance().registerWeekAlarmClock(weekDayList,ends,openServerTimes,durationMinute,Handler.create(this,this.activityEnd,[vo.id],false),0);
						}
					}
				}
				else{
					vo.openType=CommonUtil.compareTimes(serverDate,arr[0],arr[1]);
					if(vo.openType !=0){
						ServerClock.getInstance().registerDailyAlarmClock(Handler.create(this,this.activityStart,[vo.id],false),startTime,endTime-startTime);
						ServerClock.getInstance().registerDailyAlarmClock(Handler.create(this,this.activityEnd,[vo.id],false),endTime,0);
					}
				}
				if(vo.type !=16)
					this.meirihuodongData.push(vo);
				if(vo.openType==2){
					openNums++;
				}
			}
		}
		if(openNums > 0){
			this.isOpen=true;
		}
		else{
			this.isOpen=false;
		}
		this.meirihuodongData.sort(this.listSort);
		this.exeWeekLableList();
		Mgr.consoleMgr.info(Mgr.curTime.getServerDateStr()+"");
		EventCenter.instance.event("MEI");
	}

	__proto.isTodayActive=function(vo,today,is7Day,openDay){
		if(!vo || !vo.week)return false;
		if(vo.week=="0"){
			return true
		}
		else if(vo.kaifutime!=""){
			if(is7Day){
				var arr=vo.kaifutime.split(";");
				if(arr.indexOf(openDay+"")!=-1){
					return true;
				}
			}
			else{
				var arr2=vo.week.split(";");
				if(arr2.indexOf(today)!=-1){
					return true;
				}
			}
		}
		else{
			var arr3=vo.week.split(";");
			if(arr3.indexOf(today)!=-1){
				return true;
			}
		}
		return false;
	}

	/**拼接工具*/
	__proto.jointString=function(str1,str2){
		var joint1="["+str1+"]";
		var joint2="["+str2+"]";
		return joint1+joint2;
	}

	/**
	*活动开始提醒
	*/
	__proto.activityStart=function(activeID){}
	/**
	*获取活动的剩余时间
	*/
	__proto.getRT=function(id){
		if (!id)id=this.activeId;
		var temp=this.mrhdCfg.getItemByField("id",id);
		var arr=temp.time.split("-");
		var starts=arr[0].split(":");
		var ends=arr[1].split(":");
		var date=new Date(Mgr.curTime.serverTimer);
		var _hours=date.getHours();
		var _minutes=date.getMinutes();
		var _seconds=date.getSeconds();
		var starttimes=TextUtil.timeToMilSeconds(_hours,_minutes,_seconds);
		var endtimes=TextUtil.timeToMilSeconds(ends[0],ends[1],0);
		var residues=endtimes-starttimes;
		return residues;
	}

	__proto.checkHasActive=function(){
		if(this.delayShow.length > 0){
			this.activityStart(this.delayShow.shift());
		}
	}

	/**
	*活动结束提醒
	*
	*/
	__proto.activityEnd=function(activeID){}
	// EventCenter.instance.event(GameEvent.MEIRIHUODONG,[activeID,false]);
	__proto.listSort=function(value1,value2){
		if(value1.openType > value2.openType)
			return-1;
		else if(value1.openType < value2.openType)
		return 1;
		else{
			var starts1=value1.startTime.split(":");
			var starts2=value2.startTime.split(":");
			if(starts1[0] > starts2[0])
				return 1;
			else if(starts1[0] < starts2[0])
			return-1;
			else{
				if(starts1[1] > starts2[1])
					return 1;
				else if(starts1[1] < starts2[1])
				return-1;
				else
				return 0;
			}
		}
	}

	__proto.generaWeekTable=function(isIn7Day){
		if(this.activeTable==null){
			this.activeTable=new Dictionary();
			var rowIndex=0;
			var day=0;
			for (var i=0;i < 7;i++){
				var actives=this.weeksLables[i];
				var len=actives.length;
				for (var j=1;j < len;j++){
					var vo=actives[j];
					var timeStart=vo.time.split("-")[0];
					var data=this.activeTable.get(timeStart);
					var k=1;
					if(data==null){
						data={};
						data.isAlpha=rowIndex % 2==0;
						arr=[];
						arr.length=8;
						arr[0]=timeStart;
						data.arr=arr;
						var tt=timeStart.split(":");
						data.hour=parseInt(tt[0])+parseInt(tt[1])/60;
						this.activeTable.set(timeStart ,data);
					};
					var arr=data.arr;
					arr[i+1]=vo.name;
				}
			}
			this.activeTableArr=this.activeTable.values.concat();
			this.activeTableArr.sort(function(a,b){
				return a.hour-b.hour;
			});
		}
	}

	__proto.exeWeekLableList=function(){
		this.weeksLables=[[1],[2],[3],[4],[5],[6],[7]];
		var arr=this.mrhdCfg.objectDataArray;
		var leg=arr.length;
		var kaifuday=CommonUtil.openServerDay;
		var sday=Mgr.curTime.serverDate.getDay();
		var _today=sday==0?7:sday;
		this.today=_today;
		for(var i=0;i < leg;i++){
			var wtemp=arr[i];
			var warr;
			if(wtemp.week=="0"){
				for(var e=0;e<this.weekday;e++){
					if(e==_today-1){
						wtemp.openType=this.checkHuodongStrak(wtemp.id);
					}
					warr=this.weeksLables[e]? this.weeksLables[e] :[];
					warr.push(wtemp);
				}
			}
			else{
				if(wtemp.kaifutime!="" && kaifuday <=7){
					var days=wtemp.kaifutime.split(";");
					days=this.changeKaifuDaytoWeek(days);
					var dl=days.length;
					for (var j=0;j < dl;j++){
						var od=days[j];
						if(od==0){
							od=6;
						}
						else{
							od--;
						}
						if(od==_today){
							wtemp.openType=this.checkHuodongStrak(wtemp.id);
						}
						warr=this.weeksLables[od]? this.weeksLables[od] :[];
						warr.push(wtemp);
					}
				}
				else{
					var daylist=String(wtemp.week).split(";");
					var dleg=daylist.length;
					for(var t=0;t<dleg;t++){
						var pick=daylist[t];
						var day=pick-1;
						if(pick==_today){
							wtemp.openType=this.checkHuodongStrak(wtemp.id);
						}
						warr=this.weeksLables[day]? this.weeksLables[day] :[];
						warr.push(wtemp);
					}
				}
			}
		}
		this.generaWeekTable(kaifuday>7);
	}

	__proto.changeKaifuDaytoWeek=function(days){
		var len=days.length;
		for (var i=0;i < len;i++){
			var date=new Date(NetMgr.ins().serverVO.openTime);
			date.setDate(date.getDate()+parseInt(days[i])-1);
			days[i]=date.getDay();
		}
		return days;
	}

	__proto.checkHuodongStrak=function(id){
		var leg=this.meirihuodongData.length;
		for(var i=0;i<leg;i++){
			var vo=this.meirihuodongData[i];
			if(vo.id==id){
				return vo.openType;
			}
		}
		return 1;
	}

	__proto.getMeiribizuoArr=function(){
		var arr=this.meiribizuoCfg.objectDataArray;
		var arr2=[];
		var lv=NetMgr.ins().roleVO.level;
		for (var i=0;i < arr.length;i++){
			var vo=this.createMeiribizuoVO(arr[i]);
			if(lv >=vo.level && Mgr.guide.isOpen(vo.func_key)){
				arr2.push(vo);
			}
		}
		arr2.sort(this.compare);
		return arr2;
	}

	__proto.compare=function(vo1,vo2){
		if(vo1.isFinish==vo2.isFinish){
			return vo1.id-vo2.id;
		}
		else{
			if(vo1.isFinish){
				return 1;
			}
			else{
				return-1;
			}
		}
	}

	__proto.createMeiribizuoVO=function(obj){
		var vo=new MeiribizuoVO();
		vo.id=parseInt(obj.id);
		vo.type=parseInt(obj.type);
		vo.order=parseInt(obj.order);
		vo.linkType=parseInt(obj.linkType);
		vo.desc=obj.desc;
		vo.level=parseInt(obj.level);
		vo.reward=obj.reward;
		vo.img=obj.img;
		vo.count=parseInt(obj.count);
		vo.value=parseInt(obj.value);
		vo.danci=obj.danci;
		vo.mediator=obj.mediator;
		vo.showShoes=obj.showShoes;
		vo.func_key=obj.func_key;
		vo.tips=obj.tips;
		vo.icon=obj.icon;
		vo.bannar=obj.bannar;
		var len=this.meiribizuoArr?this.meiribizuoArr.length:0;
		for (var i=0;i < len;i++){
			var dailyInfo=this.meiribizuoArr[i];
			var id=dailyInfo.id;
			if (id==vo.id){
				var count=dailyInfo.count;
				if (count >=vo.count){
					vo.isFinish=true;
				}
				break ;
			}
		}
		return vo;
	}

	return MeirihuodongAction;
})(BaseMsgAction)


