/**
*断线重连机制
*@author xiangjia
*@date 2019-12-26
*/
//class com.xq.modules.ReconnectAction extends com.xq.core.net.BaseMsgAction
var ReconnectAction=(function(_super){
	function ReconnectAction(){
		this.delayConnect=3000;
		this.mask=null;
		this.isDinghao=false;
		/**重连次数*/
		this.conectNum=0;
		this.alertDisconnet=null;
		/**是否正在重连*/
		this.isConnecting=false;
		ReconnectAction.__super.call(this);
		this.model=Model.scene;
		this.isConnecting=false;
		NetMgr.ins().on("close" ,this ,this.onClosehander ,null);
		EventCenter.instance.on(GameEvent.RESTART_CONNECT,this,this.reconnect);
	}

	__class(ReconnectAction,'com.xq.modules.ReconnectAction',_super);
	var __proto=ReconnectAction.prototype;
	/**注册协议号*/
	__proto.registerMsg=function(){
		this._methodDic[8810000]=this.onRecconect;
		this._methodDic[8810005]=this.onKickOut;
	}

	__proto.onKickOut=function(bytes){
		this.isDinghao=true;
	}

	__proto.onRecconect=function(bytes){
		var msg=new ReconnecteSC();
		msg.decode(bytes);
		if(msg.result){
			this.model.isReconnect=true;
			Mgr.userLogin.sendRoleLogin(NetMgr.ins().roleVO.guid,Handler.create(this,this.gamecleanUp));
		}
		else{
			this.restart();
			console.log("重连失败!");
		}
	}

	__proto.gamecleanUp=function(){
		var game=Game.getInstance();
		game.lastMapId=-1;
		if(game.player){
			game.player.reset();
			game.player.clearBuff();
		};
		var vo=NetMgr.ins().roleVO;
		game.enterScene(vo.mapId,vo.gx,vo.gy);
		EventCenter.instance.once("ENTER_SCENE",this,this.huifuState);
		EventCenter.instance.event("OfflineAndReconnection");
		NewActiveManager.ins.reqInfo();
	}

	__proto.huifuState=function(){
		Mgr.taskPro.sendGetTaskInfo();
	}

	__proto.onClosehander=function(){
		console.log("侦听到掉线了！！！！！！！！！！！！！！！");
		if(this.isConnecting)
			return;
		this.isConnecting=true;
		if(!this.isDinghao){
			this.reconnect();
		}
		else{
			this.showAlert();
		}
		UIMgrR.closeAllPanelBylv();
		Mgr.teamMgr.clearTeamInfo();
	}

	//清除组队
	__proto.reconnect=function(){
		console.error("发起了一次重连GOGGOGOG");
		if(this.conectNum > 2){
			this.showAlert();
		}
		this.conectNum++;
		NetMgr.ins().reconnect(Handler.create(this,this.onReconnectComplete,null));
	}

	__proto.onReconnectComplete=function(succes){
		if(succes){
			this.isConnecting=false
			console.error("重连成功了！！！！")
			this.conectNum=0;
			var reconnectMsg=new ReconnecteCS();
			var roleVO=NetMgr.ins().roleVO;
			var serverVo=NetMgr.ins().serverVO;
			reconnectMsg.serverId=serverVo.serverId;
			reconnectMsg.userId=serverVo.userId;
			reconnectMsg.roleId=roleVO.guid;
			reconnectMsg.platform=Configs.subPlatformId;
			console.error("发送重登协议：",serverVo.serverId,serverVo.userId,roleVO.guid);
			this._net.sendMsg(8810000,reconnectMsg);
			if(this.alertDisconnet){
				this.alertDisconnet.close();
				this.alertDisconnet=null;
			}
			if(this.mask){
				this.mask.removeSelf();
			}
		}
		else{
			console.error("重连失败了！！！！重连次数= "+this.conectNum)
			Laya.timer.once(3000,this,this.reconnect);
		}
	}

	__proto.showAlert=function(){
		if(this.alertDisconnet==null){
			if(this.mask==null){
				this.mask=new Sprite();
				this.mask.graphics.drawRect(0,0,10,10,"#000000");
				this.mask.mouseEnabled=true;
				this.mask.mouseThrough=false;
				this.mask.alpha=0.2;
				this.mask.zOrder=3000;
			}
			this.mask.hitArea=new Rectangle(0,0,Laya.stage.width,Laya.stage.height);
			this.mask.scaleX=Laya.stage.width/10;
			this.mask.scaleY=Laya.stage.height/10;
			Dialog.manager.addChild(this.mask);
			this.alertDisconnet=UIMgrR.newInstanceByIClass(com.xq.view.modules.common.IDuanXianView);
			this.alertDisconnet.zOrder=3001;
			if(this.isDinghao)
				this.alertDisconnet.getContentLbel().text="该账号已经在别处登录\n\n";
			else
			this.alertDisconnet.getContentLbel().text="服务器连接已断开,正在尝试重连……\n\n";
			this.alertDisconnet.getContentLbel().color="#d4e7f9";
			this.alertDisconnet.getTitle().text="网络中断";
			this.alertDisconnet.getBtnOk().visible=true;
			this.alertDisconnet.getBtnOk().centerX=0;
			this.alertDisconnet.getBtnOk().label="重新登录";
			this.alertDisconnet.height=343;
			this.alertDisconnet.setCloseHandler(Handler.create(this ,this.onAlertDisconnect ,null ,false));
			this.alertDisconnet.setModel(true);
			this.alertDisconnet.popup();
			this.alertDisconnet.x=(Laya.stage.width-this.alertDisconnet.width)*0.5;
			this.alertDisconnet.y=(Laya.stage.height-this.alertDisconnet.height)*0.5;
		}
	}

	__proto.onAlertDisconnect=function(type){
		if(type=="OK"){
			this.restart();
		}
		Laya.timer.clear(this,this.reconnect);
		if(this.alertDisconnet){
			this.alertDisconnet.removeSelf();
			this.alertDisconnet=null;
		}
	}

	// debugger;
	__proto.restart=function(){
		if((typeof(SDKRuntime)!='undefined')){
			if((typeof(SDKRuntime.logout)!='undefined')){
				SDKRuntime.logout();
				return;
			}
		}
		if(Browser.onWeiXin){
			wx.exitMiniProgram({});
			}else if(window.hasOwnProperty('qg')){
			QGMiniAdapter.exitMiniProgram();
		}
		else{
			Browser.window.location.reload();
		}
	}

	ReconnectAction.getInstance=function(){
		return ReconnectAction._instance=ReconnectAction._instance|| new ReconnectAction();
	}

	ReconnectAction._instance=null;
	ReconnectAction.RECONNET_MSG=8810000;
	ReconnectAction.KICKOUT_MSG=8810005;
	return ReconnectAction;
})(BaseMsgAction)


