		this.poolCfg=new Object();
		this.playCfg=CfgManager.getTableCfg("platformGift");
		this.vipStoreCfg=CfgManager.getTableCfg("platformVipStore");
		var arr=this.playCfg.objectDataArray;
		var o=this.playCfg.getItemByField("type",1);
		this.todayN=o.count;
		this.todayR=o.item;
		o=this.playCfg.getItemByField("type",2);
		this.leijiN=o.count;
		this.leijiR=o.item;
		o=this.playCfg.getItemByField("type",3);
		this.shoucangN=o.count;
		this.shoucangR=o.item;
		this.red=Mgr.red;
