__proto.sendGetInvitedRewardInfo=function(){}
// _net.sendMsg(GET_INVITED_REWARD_INFO);
__proto.onGetInvitedRewardInfo=function(b){
	var d=new GetInviteRewardInfoSC();
	d.decode(b);
	var len=this.invitedArr.length;
	var o=JSON.parse(d.rewardInfo);
	for(var i=0;i < len;i++){
		var o1=this.invitedArr[i];
		if(!o[o1.id])
			o1.hasGet=0;
		else
		o1.hasGet=o[o1.id];
	}

}


__proto.sendGetInvitedInfo=function(){
	var d=new GetInviteInfoCS();
	d.platform=Configs.platformId;
	this._net.sendMsg(800024,d);
}


__proto.onGetInvitedInfo=function(b){
	var data=new GetInviteInfoSC();
	data.decode(b);
	var arr=data.info;
	var len=arr.length;
	var len1=this.invitedArr.length;
	this.invitedInfoArr.length=0;
	for(var j=0;j< len1;j++){
		var o1=this.invitedArr[j];
		o1.total=0;
		for(var i=0;i < len;i++){
			var o=JSON.parse(arr[i]);
			if(!o.fight || o.fight < o1.value)
				continue ;
			o1.total++;
			if(j==0){
				o.rank=(i+1);
				this.invitedInfoArr.push(o);
			}
		}
	}

	this.inivtedTotal=data.total;
	this.invitedInfoArr.sort(this.invitedSort);
}


__proto.invitedSort=function(o1,o2){
	var flag=(o1.fight < o2.fight)?1:-1;
	if(flag==1){
		var rank=o1.rank;
		o1.rank=o2.rank;
		o2.rank=rank;
	}

	return flag;
}


__proto.sendGetInviteReward=function(){
	var d=new GetInviteRewardCSC();
	this._net.sendMsg(800025,d);
}


__proto.onGetInvitedReward=function(b){
	this.sendGetInvitedRewardInfo();
}


__proto.synInvitedInfo=function(){
	var d=new SynInviteInfoCS();
	var o={};
	o.guid=NetMgr.ins().roleVO.guid;
	o.vipLv=NetMgr.ins().roleVO.vipLevel;
	o.name=NetMgr.ins().roleVO.name;
	o.fight=NetMgr.ins().roleVO.fightValue;
	o.level=NetMgr.ins().roleVO.level;
	o.server=NetMgr.ins().serverVO.serverName;
	d.info=JSON.stringify(o);
	d.platform=Configs.platformId;
	this._net.sendMsg(800026,d);
}


__proto.openShareView=function(){}
