	__proto.onCreateCollect=function(b){
		var sc=new CreateCollectionInStageSC();
		sc.decode(b);
		var collectArr=sc.elements;
		var len=collectArr.length;
		var container=Game.getInstance().sceneContainer;
		for(var i=0;i <len;i++){
			var cvo=new CollectVO();
			cvo.bindServer(collectArr [i]);
			var c=this.unitManager.createCollect(cvo);
			if(c){
				var roleVo=NetMgr.ins().roleVO;
				var mapId=roleVo.mapId;
				if(mapId==6601){
					this.guildPartyCollect(c);
				}
				container.unitLayer.addChild(c);
			}
		}
	}

