	/**发送角色移动消息*/
	__proto.sendPlayerMove=function(activeUnit,path,isActiveMove,isMust){
		if(Game.getInstance().player.isInSinCopy)
			return
		if(activeUnit.vo && Math.abs(this.lastMoveTime-Mgr.curTime.serverTimer)> 3000 || isMust){
			if(path==null || path.length==0){
				return;
			}
			this.lastMoveTime=Mgr.curTime.serverTimer;
			var pvo=new PlayerMoveCSC();
			pvo.faceto=activeUnit.curDir;
			pvo.moverId=activeUnit.vo.guid;
			pvo.step=0;
			this.parr.length=0;
			pvo.pathPoints=this.parr;
			pvo.isActiveMove=isActiveMove;
			var len=path.length;
			for(var i=0;i < len;i++){
				var pmsg=new PointMsg();
				var arr=SceneContainer.GlobalToGrid(path[i][0],path[i][1]);
				pmsg.x=arr[0];
				pmsg.y=arr[1];
				this.parr.push(pmsg);
			};
			var firstPos=this.parr[this.parr.length-1];
			pvo.x=firstPos.x;
			pvo.y=firstPos.y;
			this._net.sendMsg(8840000,pvo);
		}
	}

	__proto.onRecconetPosSyn=function(byteData){
		var msg=new ReconnectToPositionSC();
		msg.decode(byteData);
		if(this._net.roleVO.mapId !=msg.mapId){
			var ro=new RoleApplyEnterStageSC();
			var m=new MapInfoMsg();
			m.mapId=msg.mapId;
			m.mapX=msg.x;
			m.mapY=msg.y;
			m.mapZ=msg.z;
			ro.mapInfo=m;
			this.changeStageCS(ro);
		}
	}

	/**接受角色移动消息*/
	__proto.onUnitMove=function(b){
		this.pmsc.decode(b);
		var moverId=this.pmsc.moverId;
		if(moverId==this._net.roleVO.guid ||
			Mgr.subPlayer.isMySubPlayer(moverId)){
			return;
		}
		this.umo.faceto=this.pmsc.faceto;
		this.umo.moverId=this.pmsc.moverId;
		this.umo.step=this.pmsc.step;
		var point=SceneContainer.GridToGlobal(this.pmsc.x,this.pmsc.y);
		this.umo.x=point[0];
		this.umo.y=point[1];
		this.uarr.length=0;
		this.umo.pathArr=this.uarr;
		this.umo.isActiveMove=this.pmsc.isActiveMove;
		var len=this.pmsc.pathPoints.length;
		for(var i=0;i < len;i++){
			var p=this.pmsc.pathPoints[i];
			var arr=SceneContainer.GridToGlobal(p.x,p.y);
			this.umo.pathArr.push(arr);
		}
		this.ucacheArr=this.ucacheArr.concat(this.umo.pathArr);
		UnitManager.ins.moveUnitByServer(this.umo);
	}

	/**接受加buff的消息*/
	__proto.onUpdateBuff=function(b){
		var sc=new UpdateBuffSC();
		sc.decode(b);
		var unit=this.unitManager.unitList.get(sc.playerGuid);
		if(!unit)
			return;
		var addbuffs=sc.addBufs;
		var len=addbuffs.length;
		for(var i=0;i < len;i++){
			BufferManager.ins.addBuff(unit,addbuffs[i]);
		};
		var updatebuffs=sc.updateedBufs;
		len=updatebuffs.length;
		for(i=0;i < len;i++){
			BufferManager.ins.updateBuff(updatebuffs[i]);
		};
		var removebuffs=sc.removedBufId;
		len=removebuffs.length;
		for(i=0;i < len;i++){
			BufferManager.ins.removeBuff(removebuffs[i]);
		}
	}

	/**接受属性变化的消息*/
	__proto.onAttributeChange=function(b){
		var vo=new AttributeChangeSC();
		vo.decode(b);
		var roleVo=NetMgr.ins().roleVO;
		if(roleVo.guid==vo.roleId){
			if(this.ifFirst){
				roleVo.bindFightProperty(vo.attrs,!this.ifFirst);
				this.ifFirst=false;
				}else{
				roleVo.bindFightProperty(vo.attrs,!vo.isNot2Show);
			}
		}
		else{
			var subPlayer=Mgr.subPlayer.getSubPlayerById(vo.roleId);
			if(subPlayer){
				(subPlayer.vo).bindFightProperty(vo.attrs,false);
			}
		}
		EventCenter.instance.event("FIGHT_PROPERTY_CHANGE",vo.roleId);
	}

