	/**等级提升*/
	__proto.onLevelUp=function(b){
		var vo=new LevelUpSC();
		vo.decode(b);
		var unit=this.unitManager.roleList.get(vo.roleId);
		if((unit instanceof com.xq.rpg.unit.MainPlayer )){
			BaseSDK.roleLevelUpTime=Math.round(ServerTimeAction.ins().serverTimer/1000);
			var LastLv=NetMgr.ins().roleVO.level;
			var curLv=vo.level;
			if(LastLv!=curLv){
				this.showLvUp(LastLv,curLv);
				NetMgr.ins().roleVO.level=curLv;
				EventCenter.instance.event("LEVEL_UP");
				this.showLvAni(unit);
				var t=Browser.now();
				if(t-this._lstUpT > 1000){
					this._lstUpT=t;
					BaseSDK.ins.levelEvent();
				}
			}
		}
	}

	__proto.showLvUp=function(preLv,targetLv){
		var dengji=UIMgrR.getIView(com.xq.view.modules.common.ILevelUpTip,2);
		var x=(Laya.stage.width-dengji.width)>>1;
		var y=(Laya.stage.height>>1)-200;
		if(!dengji.parent){
			Game.getInstance().fightHintView.addChild(dengji);
		}
		dengji.pos(x,y);
		dengji.levelUp(preLv,targetLv);
	}

	__proto.showLvAni=function(unit){
		var skeleton=this.skeletonDic[unit.guid];
		if(!skeleton || skeleton.destroyed){
			skeleton=new BoneAni();
			this.skeletonDic[unit.guid]=skeleton;
			skeleton.setOnce(true);
			skeleton.load(PathDefine.BONES+"2/2.sk");
			skeleton.pos(0,0);
			skeleton.blendMode="screen";
			unit.addChild(skeleton);
		}
	}

