	/**接受角色释放技能效果消息 */
	__proto.onDisplaySkillMsg=function(b){
		var sc=new SkillDisplayMsgSC();
		sc.decode(b);
		if(sc.errcode !=-1){
			var vo=new UseSkillVO();
			vo.attackerId=sc.attackerId;
			vo.param1=sc.param1;
			vo.param2=sc.param2;
			vo.skillCategory=sc.skillCategory;
			vo.targetGuid=sc.targetGuid;
			vo.targetX=sc.targetX;
			vo.targetY=sc.targetY;
			var key=vo.skillCategory+"_"+vo.attackerId
			if(this.skillcompleteDic[key]){
				var skillcomplete=this.skillcompleteDic[key];
				skillcomplete.runWith(sc.remainCD);
				skillcomplete=null;
				delete this.skillcompleteDic[key];
			}
			else{
				if(this.mplyer && !this.mplyer.isJuQing && sc.attackerId!=this.mplyer.guid){
					this.unitManager.useSkillBySever(vo);
				}
			}
		}
		else{
			CodeLinkUtil.ins().optionPrompt(sc.errcode+"");
		}
	}

	/**接受到伤害消息*/
	__proto.onSkillHarmMsg=function(b){
		var sc=new SkillHarmMsgSC();
		sc.decode(b);
		var vo=new SkillHarmVO();
		vo.attackerId=sc.attackerId;
		vo.harmMsgs=sc.harmMsgs;
		vo.index=sc.index;
		vo.param1=sc.param1;
		vo.param2=sc.param2;
		vo.skillCategory=sc.skillCategory;
		if(this.mplyer && !this.mplyer.isJuQing)
			FrameSmooth.add(Handler.create(this.unitManager,this.unitManager.harm,[vo]));
		var len=sc.harmMsgs.length;
		for (var i=0;i < len;i++){
			var temp=sc.harmMsgs[i];
		}
	}

	/**发送角色释放技能消息*/
	__proto.sendUseSkillMsg=function(vo,skillcomplete){
		this.skillcompleteDic[vo.skillCategory+"_"+vo.attackerId]=skillcomplete;
		var cs=new UseSkillMsgCS();
		cs.attackerId=vo.attackerId;
		cs.index=vo.index;
		cs.param1=vo.param1;
		cs.param2=vo.param2;
		cs.skillCategory=vo.skillCategory;
		cs.targetIds=vo.targetIds;
		cs.targetX=vo.targetX;
		cs.targetY=vo.targetY;
		this._net.sendMsg(8842002,cs);
	}

	/**请求技能伤害*/
	__proto.sendGetSkillHarm=function(vo){
		var cs=new SkillHarmMsgCS();
		cs.attackerId=vo.attackerId;
		cs.param1=vo.param1;
		cs.param2=vo.param2;
		cs.skillCategory=vo.skillCategory;
		cs.targetIds=vo.targetIds;
		cs.targetX=vo.targetX;
		cs.targetY=vo.targetY;
		this._net.sendMsg(8842006,cs);
	}

	/**发送击飞击退的同步消息*/
	__proto.sendRepelMonster=function(x,y,guid){
		this.repelMsg.guid=guid;
		this.repelMsg.x=x;
		this.repelMsg.y=y;
		this._net.sendMsg(8842010,this.repelMsg);
	}

	/**接受到击退击飞消息*/
	__proto.onRepelMonster=function(b){
		var vo=new RepelMonsterCSC();
		vo.decode(b);
	}

	/**位置同步
	*像素坐标
	**/
	__proto.sendSynPosition=function(x,y,must){
		(must===void 0)&& (must=false);
		if(Model.game.mPlayer.isInSinCopy)
			return
		if(!this._model.isMustSysPos && (this._model.isChangeScene || Browser.now()-this.lastTime<1500)&& !must){
			return;
		}
		this.lastTime=Browser.now();
		var posArr=SceneContainer.GlobalToGrid(x,y);
		this.syncMsg.x=posArr[0];
		this.syncMsg.y=posArr[1];
		this._net.sendMsg(8840002,this.syncMsg);
	}

	__proto.onSynRolePos=function(b){
		var sc=new PlayerPosSyncSC();
		sc.decode(b);
		var player=this.unitManager.getPlayerByRoleID(sc.roleId);
		if(player){
			var arr=SceneContainer.GridToGlobal(sc.gx,sc.gy);
			if(arr && arr[0] && arr[1]){
				player.x=arr[0];
				player.y=arr[1];
			}
		}
	}

	/**判断当前地图是否可以上坐骑*/
	__proto.checkIsMountByMap=function(){
		var mapId=NetMgr.ins().roleVO.mapId;
		switch(mapId){
			case 2027:{
					return false;
				}
			case 2032:{
					return false;
				}
			}
		return true;
	}

	SceneSynAction2.ins=function(){
		return SceneSynAction2._ins=SceneSynAction2._ins||new SceneSynAction2();
	}

	SceneSynAction2._ins=null;
	SceneSynAction2.SCENE_GET_SKILL_HARM=8842006;
