//class com.xq.modules.task.TaofaAction extends com.xq.core.net.BaseMsgAction
var TaofaAction=(function(_super){
	function TaofaAction(){
		this.mgr=null;
		this.complete=null;
		this.isOnce=true;
		this.o1=null;
		TaofaAction.__super.call(this);
		this.mgr=Mgr.taofa;
	}

	__class(TaofaAction,'com.xq.modules.task.TaofaAction',_super);
	var __proto=TaofaAction.prototype;
	__proto.registerMsg=function(){
		this._methodDic[8850607]=this.ongetInfo;
		this._methodDic[8850608]=this.onUpdateInfo;
		this._methodDic[8850609]=this.onFinish;
	}

	/**一键完成*/
	__proto.sendYiJian=function(){
		this._net.sendMsg(8850610);
	}

	/**任务完成*/
	__proto.onFinish=function(b){}
	/**拉取讨伐信息*/
	__proto.sendGetInfo=function(com){
		this._net.sendMsg(8850607);
		if(com)
			this.complete=com;
	}

	__proto.ongetInfo=function(b){
		if(this.complete){
			this.complete.run();
			this.complete=null;
		};
		var v=new GetTaofaTaskSC();
		v.decode(b);
		this.mgr.taskId=v.taskId;
		this.mgr.rewardId=v.rewardId;
		this.mgr.itemId=v.itemId;
		this.mgr.progress=v.progress;
		this.mgr.leftTimes=v.leftTimes;
		if(this.mgr.taskId!=0){
			this.mgr.curTask=this.mgr.tfTaskDic[this.mgr.taskId];
			var o=this.mgr.curTask;
			var str="讨伐<font color='#77f440'>"+o.name+"</font>("+v.progress+"/"+o.number+")";
			if(!this.o1)
				this.o1={};
			this.o1.str=str;
			this.o1.map=o.map;
			this.o1.monsterId=o.monsterId;
			EventCenter.instance.event("TASKBAR_COUNT_UPDATE",[18,v.leftTimes,1,this.o1]);
			if(!this.isOnce){
			}
		}
		else{
			this.mgr.curTask=null;
			if(Mgr.guide.isOpen("taofa")){
				if(v.leftTimes==0){
					v.leftTimes=-1;
				}
				EventCenter.instance.event("TASKBAR_COUNT_UPDATE",[18,v.leftTimes]);
			}
		}
		if(this.isOnce)
			this.isOnce=false;
	}

	/**讨伐进度更新*/
	__proto.onUpdateInfo=function(b){
		var v=new TaofaTaskUpdateSC();
		v.decode(b);
		this.mgr.progress=v.progress;
		var o=this.mgr.curTask;
		var str="讨伐<font color='#77f440'>"+o.name+"</font>("+v.progress+"/"+o.number+")";
		if(!this.o1)
			this.o1={};
		this.o1.str=str;
		this.o1.map=o.map;
		this.o1.monsterId=o.monsterId;
		EventCenter.instance.event("TASKBAR_COUNT_UPDATE",[18,this.mgr.leftTimes,1,this.o1]);
	}

	TaofaAction.GET_INFO=8850607;
	TaofaAction.UPDATE_INFO=8850608;
	TaofaAction.FINISH=8850609;
	TaofaAction.YIJIAN=8850610;
	return TaofaAction;
})(BaseMsgAction)


