//class com.xq.modules.transfer.TransferAction extends com.xq.core.net.BaseMsgAction
var TransferAction=(function(_super){
	function TransferAction(){
		/**飞到目的地后的处理类型
		*
		*
		**/
		this.taskType=0;
		TransferAction.__super.call(this);
		EventCenter.instance.on("SEND_TRANSFER_PORT",this,this.sendTransfer);
	}

	__class(TransferAction,'com.xq.modules.transfer.TransferAction',_super);
	var __proto=TransferAction.prototype;
	__proto.registerMsg=function(){
		this._msgList=[8840100,8820003];
	}

	__proto.onMesgage=function(data){
		switch(data.msgId){
			case 8840100:{
					var transferInmapSc=new TransferInMapSC();
					transferInmapSc.decode(data.data);
					debugger
					console.log("广播本地图传送");
					break ;
				}
			case 8820003:{
					this.onShoesTransfer(data.data);
					break ;
				}
			default :{
					break ;
				}
			}
	}

	/**
	*告诉服务器 请求传送
	*@param waypoint :传送点ＩＤ
	**/
	__proto.sendTransfer=function(waypoint){
		var transfer=new TransferByMapPointCS();
		transfer.wayPoint=waypoint;
		this._net.sendMsg(8820001 ,transfer);
	}

	__proto.sendShoesTransfer=function(mapId,x,y,taskType){
		(taskType===void 0)&& (taskType=0);
		var shoseNum=Mgr.bag.getBagMatCount("dj1063");
		if(Game.getInstance().player)
			Game.getInstance().player.stand();
		var mapTemp=SceneContainer.getInstance().mapDataDic.getItemByField("mapid",mapId);
		var limtLV=String(mapTemp.maplv).split("|")[0];
		var heroLV=NetMgr.ins().roleVO.level;
		var transfer=new TransferByFlyShoeCS();
		transfer.mapId=mapId;
		transfer.x=x;
		transfer.y=y;
		transfer.type=0;
		this.taskType=taskType;
		this._net.sendMsg(8820003,transfer);
	}

	// }
	__proto.onShoesTransfer=function(byteData){
		var sc=new TransferByFlyShoeSC();
		sc.decode(byteData);
		if(sc.errCode!=1){
			Mgr.prompt.optionPrompt(CodeMgr.ins.getStringByCode(sc.errCode));
			}else{
			var player=Game.getInstance().player;
			SceneContainer.getInstance().mapCamera.lookAt(null);
			var tx=player.x;
			var ty=player.y-Laya.stage.height/2-player.mainAni.height;
			var arr=SceneContainer.GridToGlobal(sc.x,sc.y);
			Laya.timer.once(800,this,this.tiaoComplete,[arr[0],arr[1]]);
			(player).isChangeScene=true;
			player.tiao(tx,ty,2000);
		}
	}

	__proto.tiaoComplete=function(fx,fy){
		var player=Game.getInstance().player;
		player.tiaoAction.stop();
		var camera=SceneContainer.getInstance().mapCamera;
		camera.lookAtPos(fx,fy);
		SceneContainer.getInstance().updateViewPort(camera.viewPort);
		player.x=fx;
		player.y=fy-Laya.stage.height/2-player.mainAni.height;
		player.updatePos();
		player.tiaoAction.tween.off("complete",this,this.tiaoComplete);
		this.downTiao(player.x,player.y+Laya.stage.height/2+player.mainAni.height);
	}

	//Laya.timer.once(300,this,dsf,[player.x,player.y+600]);
	__proto.downTiao=function(x,y){
		var player=Game.getInstance().player;
		player.tiaoAction.tween.on("complete",this,this.tiaoComplete1);
		player.tiao(x,y,2000,1);
	}

	__proto.tiaoComplete1=function(){
		var player=Game.getInstance().player;
		SceneContainer.getInstance().mapCamera.lookAt(player);
		(player).isChangeScene=false;
		player.tiaoAction.tween.off("complete",this,this.tiaoComplete1);
		Mgr.task.flyCompleteDoTask(this.taskType);
	}

	__proto.flyingshoseCallback=function(unit,mapid,position){}
	return TransferAction;
})(BaseMsgAction)


