	__proto.onJHSDKCharge=function(byte){
		var msg=new SDKChargeSC();
		msg.decode(byte);
		if(Configs.rechargeTest){
			msg.rmbFen=1;
		};
		var roleVo=NetMgr.ins().roleVO;
		var table=CfgManager.getTableCfg("chongzhi");
		if(typeof(SDKRuntime)!='undefined'){
			var order={};
			order["uid_in_game"]=roleVo.guid;
			order["user_name_in_game"]=roleVo.name;
			order["level"]=roleVo.level;
			order["vipLevel"]=roleVo.vipLevel;
			order["power"]=roleVo.fightValue;
			order["balance"]=roleVo.yuanbao;
			order["tongban"]=roleVo.taiYu;
			order["guildName"]=roleVo.guildName;
			order["order_id"]=msg.orderId;
			order["feeid"]=msg.productId;
			order["item_id"]=msg.itemId;
			order["callback_url"]=msg.callbackUrl;
			var item=table.getItemByField("id",msg.productId);
			if(item){
				order["product_name"]=item.name;
				order["remark"]=item.name;
			}
			else{
				order["product_name"]="元宝x"+(msg.rmbFen*0.1);
				order["remark"]=order["product_name"];
			}
			order["product_id"]=""+msg.productId;
			order["server_id"]=""+BaseSDK.serverId;
			order["serverName"]=""+BaseSDK.serverName;
			order["pay_money"]=msg.rmbFen;
			order["product_count"]=1;
			var extra={};
			extra["game_area"]="微端测试区";
			extra["rgrade"]=roleVo.level;
			extra["desc"]="来自VIP充值面板";
			extra["user_id"]=BaseSDK.userId;
			extra["iapObjectId"]=msg.itemId2 ? msg.itemId2 :"com.shjj.6yuan.pay1";
			extra["iapAmount"]=""+(msg.rmbFen/100);
			extra["iapExtraStr"]=msg.orderId;
			extra["sid"]=""+BaseSDK.serverId;
			var time=Mgr.curTime.serverTimer;
			extra["time"]=time;
			var signature="";
			SDKRuntime.h5_pay(order,extra,signature,this.onH5PayFailded);
		}
	}

	__proto.onH5PayFailded=function(result){
		var alert;
		if(result.content){
			alert=AlertUtil.show(result.content.msg);
		}
		else{
			alert=AlertUtil.show(result.msg);
		}
		alert.getBtnCancel().visible=false;
		alert.getBtnOK().x=215;
		console.log("支付失败："+JSON.stringify(result));
	}

	__proto.sendJHSDKCharege=function(yuanBaoNum,productId,productName){
		if(Configs.needShiMingRenZheng){
			var gzMgr=Mgr.guanZMgr;
			if(gzMgr.rzStatu==-1 || gzMgr.rzStatu==3){
				UIMgrR.openIView(com.xq.view.modules.shiMingRenZheng.IShiMingRenZheng);
				return;
			}
			else{
				if(Mgr.guanZMgr.checkMaxMoney(Mgr.chargeMgr.getRmbByID(productId+""))){
					return;
				}
			}
		}
		if(Browser.now()-this.lastSendTim > 1000){
			if(Configs.isForbitIOSPay||Configs.isForbitAndroidPay){
				console.log("屏蔽了ios或安卓平台支付....")
				return;
			}
			this.lastSendTim=Browser.now();
			var msg;
			msg=new SDKChargeCS();
			msg.productId=productId;
			msg.platform=Configs.platform;
			msg.payParam=Configs.payChannelId;
			msg.os=Configs.payOs;
			console.log("支付平台=----"+msg.platform);
			this._net.sendMsg(88010001,msg);
		}
	}

