var AutoPathingAIStatus=(function(_super){
	function AutoPathingAIStatus(){
		this.targetMapID=0;
		this.targetPosX=0;
		this.targetPosY=0;
		this._completeHandler=null;
		this.mainPlayer=null;
		/**
		*地图ID 路径（长途寻路 需要经历的地图IDs）
		**/
		this.mapPath=null;
		this.scene=null;
		AutoPathingAIStatus.__super.call(this);
	}

	__class(AutoPathingAIStatus,'com.xq.rpg.action.ai.action.AutoPathingAIStatus',_super);
	var __proto=AutoPathingAIStatus.prototype;
	__proto.active=function(){
		var mapId=NetMgr.ins().roleVO.mapId;
		if(mapId==this.targetMapID){
			this.mapPath=[mapId];
		}
		else{
			this.mapPath=TransferMgr.ins().findMapIDPath(mapId,this.targetMapID);
		}
		this.scene=Model.game.sceneContainer;
		this.mainPlayer=Model.game.mPlayer;
		this._active=true;
		this.mainPlayer.reqMount(true);
	}

	__proto.exec=function(){
		if(this._active){
			if(this.mainPlayer.isChangeScene){
				return 1;
			};
			var targetX=-1;
			var targetY=-1;
			var mapId=NetMgr.ins().roleVO.mapId;
			if(mapId==this.targetMapID){
				if(Math.abs(this.mainPlayer.x-this.targetPosX)<=128 && Math.abs(this.mainPlayer.y-this.targetPosY)<=128){
					if(this.completeHandler){
						this.mainPlayer.isActiveMove=false;
						this._active=false;
						this.completeHandler.run();
						if(this.completeHandler && this.completeHandler.once){
							this.completeHandler=null;
						}
					}
					AIController.ins().stopAutoPath();
				}
				else{
					if(!this.mainPlayer.isMoving){
						targetX=this.targetPosX;
						targetY=this.targetPosY;
						this.mainPlayer.moveTo(this.targetPosX,this.targetPosY);
					}
				}
			}
			else{
				if(!this.mainPlayer.isMoving){
					var curMapIndex=this.mapPath.indexOf(mapId);
					var nextMapID=this.mapPath[curMapIndex+1];
					var trasferVO=TransferMgr.ins().getTransferVo(mapId ,nextMapID);
					if(trasferVO){
						var arr=SceneContainer.GridToGlobal(trasferVO.x,trasferVO.y);
						targetX=arr[0];
						targetY=arr[1];
						this.mainPlayer.moveTo(targetX,targetY);
					}
				}
			}
			if(targetY !=-1){
				if(!this.mainPlayer.isMount && CommonUtil.getDistance(this.mainPlayer.x ,this.mainPlayer.y,targetX,targetY)> 1000){
					if(CodeLinkUtil.ins().funcIsOpen("jingjiemount")){
						this.mainPlayer.reqMount(true);
					}
				}
			}
		}
		return 1;
	}

	__proto.sleep=function(){
		if(this.mainPlayer){
			this.mainPlayer.stand();
		}
		this._active=false;
		this.completeHandler=null;
		_super.prototype.sleep.call(this);
	}

	__getset(0,__proto,'completeHandler',function(){
		return this._completeHandler;
		},function(value){
		if(this._completeHandler&& this._completeHandler.once){
			this._completeHandler.recover();
		}
		this._completeHandler=value;
	});

	return AutoPathingAIStatus;
})(BaseAIStatus)


