var SkillOPDirectMulAOE=(function(_super){
	function SkillOPDirectMulAOE(vo,unit){
		SkillOPDirectMulAOE.__super.call(this,vo,unit);
	}

	__class(SkillOPDirectMulAOE,'com.xq.rpg.skill.op.SkillOPDirectMulAOE',_super);
	var __proto=SkillOPDirectMulAOE.prototype;
	__proto.start=function(forbitSount){
		(forbitSount===void 0)&& (forbitSount=false);
		_super.prototype.start.call(this,forbitSount);
		this.svo.curObj=this.curObj;
		this.svo.tarArr=this.targetArr;
		this.svo.actKey=this.vo.action;
		this.svo.delayTime=this.vo.skillSpace;
		this.svo.dirId=this.curObj.curDir || 0;
		this.svo.nums=this.vo.skillNum;
		this.svo.radius=this.vo.length;
		this.svo.rang=this.vo.rang;
		this.svo.skillUseRes=this.vo.skillUseRes;
		this.svo.skillBottomRes=this.vo.skillBottomRes;
		this.svo.type=10;
		this.svo.shake=this.vo.shake;
		this.svo.skillCD=this.vo.skillCD;
		SkillBase.show(this.svo);
	}

	__proto.getTarget=function(){
		var dir=this.svo.dirId;
		var angle=CommonUtil.angleToRadian(SkillOPBase.rotArr[dir]);
		var num=this.svo.nums;
		var distance=this.svo.radius;
		var rang=this.svo.rang;
		var sin=Math.sin(angle);
		var cos=Math.cos(angle);
		var flagDic={};
		var sprArr=[];
		for(var i=0;i< num;i++){
			var sp=SkillOPCache.spArr.length?SkillOPCache.spArr.pop():new Sprite();
			var totalDistance=distance+rang *i;
			var offX=totalDistance*cos;
			var offY=totalDistance*sin;
			sp.x=this.curObj.x+offX;
			sp.y=this.curObj.y+offY;;
			sp.graphics.clear();
			sp.graphics.drawCircle(0,0,this.vo.rang,"#00FF00");
			sp.alpha=0.5;
			var hit=new HitArea();
			hit.hit.drawCircle(0,0,this.vo.rang,"#00FF00");
			sp.hitArea=hit;
			SceneContainer.getInstance().bottomLayer.addChild(sp);
			var tempResult=UnitLayerManager.ins.hitTestBySprite(sp);
			var len=tempResult.length;
			for(var j=0;j < len;j++){
				var unit=tempResult [j];
				if(!flagDic[unit.guid]){
					flagDic[unit.guid]=1;
					this.targetArr.push(unit);
				}
			}
			sprArr.push(sp);
		}
		len=sprArr.length;
		for(i=0;i < len;i++){
			if(!SkillManager.ins.isShowSkillfanwei)
				sprArr[i].removeSelf();
			SkillOPCache.spArr.push(sprArr[i]);
		}
		sprArr=null;
		return this.targetArr;
	}

	return SkillOPDirectMulAOE;
})(SkillOPBase)


