//class com.xq.rpg.skill.op.SkillOPDirectSector extends com.xq.rpg.skill.op.SkillOPBase
var SkillOPDirectSector=(function(_super){
	function SkillOPDirectSector(vo,unit){
		this.sprArr=null;
		this.poAry=[];
		SkillOPDirectSector.__super.call(this,vo,unit);
	}

	__class(SkillOPDirectSector,'com.xq.rpg.skill.op.SkillOPDirectSector',_super);
	var __proto=SkillOPDirectSector.prototype;
	/**释放技能*/
	__proto.start=function(forbitSount){
		(forbitSount===void 0)&& (forbitSount=false);
		_super.prototype.start.call(this,forbitSount);
		this.svo.curObj=this.curObj;
		this.svo.tarArr=this.targetArr;
		this.svo.actKey=this.vo.action;
		this.svo.delayTime=this.vo.skillSpace;
		this.svo.dirId=this.curObj.curDir || 0;
		this.svo.nums=this.vo.skillNum;
		this.svo.radius=this.vo.length;
		this.svo.rang=this.vo.rang;
		this.svo.skillUseRes=this.vo.skillUseRes;
		this.svo.skillBottomRes=this.vo.skillBottomRes;
		this.svo.type=9;
		this.svo.dropType=this.vo.dropType;
		this.svo.shake=this.vo.shake;
		this.svo.poAry=this.poAry;
		this.svo.skillCD=this.vo.skillCD;
		SkillBase.show(this.svo);
	}

	/**计算技能范围命中的对象数组*/
	__proto.getTarget=function(){
		_super.prototype.getTarget.call(this);
		var dir=this.svo.dirId;
		var distance=this.svo.radius;
		var angle=CommonUtil.angleToRadian(SkillOPBase.rotArr[dir]);
		var sin=Math.sin(angle);
		var cos=Math.cos(angle);
		this.sprArr=[];
		var data={};
		data.flagDic={};
		data.guidDic={};
		data.angle=angle;
		data.num=this.svo.nums;
		data.rang=this.svo.rang;
		var offX=this.curObj.x+distance*cos;
		var offY=this.curObj.y+distance*sin;
		this.recursionGetTarget(data,true,1,1,offX,offY);
		var len=this.sprArr.length;
		for(var i=0;i < len;i++){
			if(!SkillManager.ins.isShowSkillfanwei)
				this.sprArr[i].removeSelf();
			SkillOPCache.spArr.push(this.sprArr[i]);
		}
		this.sprArr=null;
		return this.targetArr;
	}

	/**递归创建扇形位置特效
	*isLeft 判断是不是左子树
	**/
	__proto.recursionGetTarget=function(data,isLeft,index,ceng,offX,offY){
		var flagDic=data.flagDic;
		if(flagDic[index]){
			return;
		};
		var guidDic=data.guidDic;
		flagDic[index]=1;
		var angle=data.angle;
		var rang=data.rang;
		var num=data.num;
		var sp=SkillOPCache.spArr.length?SkillOPCache.spArr.pop():new Sprite();
		this.sprArr.push(sp);
		sp.x=offX;
		sp.y=offY;
		sp.alpha=0.5;
		sp.graphics.clear();
		sp.graphics.drawCircle(0,0,this.vo.rang,"#00FF00");
		var hit=new HitArea();
		hit.hit.drawCircle(0,0,this.vo.rang,"#00FF00");
		sp.hitArea=hit;
		SceneContainer.getInstance().bottomLayer.addChild(sp);
		var tempResult=UnitLayerManager.ins.hitTestBySprite(sp);
		var len=tempResult.length;
		for(var j=0;j < len;j++){
			var unit=tempResult [j];
			if(!flagDic[unit.guid]){
				flagDic[unit.guid]=1;
				this.targetArr.push(unit);
			}
		}
		if(index !=1){
			var tempAngle=angle;
			if(isLeft){
				tempAngle-=CommonUtil.angleToRadian(30);
				}else{
				tempAngle+=CommonUtil.angleToRadian(30);
			};
			var sin=Math.sin(tempAngle);
			var cos=Math.cos(tempAngle);
			offX+=rang *cos;
			offY+=rang *sin;
		}
		if(ceng<=num){
			this.recursionGetTarget(data,true,index+ceng,ceng+1,offX,offY);
			this.recursionGetTarget(data,false,index+ceng+1,ceng+1,offX,offY);
		}
	}

	return SkillOPDirectSector;
})(SkillOPBase)


