//class com.xq.component.MagicFont extends laya.display.Sprite
var MagicFont=(function(_super){
	function MagicFont(){
		this.contentTxt=null;
		this._timer=null;
		this.txtField=null;
		this.time=0;
		this.count=0;
		this.wordAry=null;
		this.callback=null;
		this.txt=null;
		this.oldN=0;
		this.newN=0;
		this.endT=null;
		this.tcaller=null;
		this.ftcp=null;
		MagicFont.__super.call(this);
		this._timer=Laya.timer;
	}

	__class(MagicFont,'com.xq.component.MagicFont',_super);
	var __proto=MagicFont.prototype;
	__proto.showDaYinJiTxt=function(_txtLabel,str,_time,_callback){
		(_time===void 0)&& (_time=1000);
		if(!_txtLabel)return;
		this.txtField=_txtLabel
		if(!this.txtField)return;
		this.callback=_callback
		this.txtField.text="";
		this.time=_time;
		this.count=-1;
		this.txtField.wordWrap=true;
		this.wordAry=[];
		for (var i=0;i < str.length;i++){
			this.wordAry.push(str.charAt(i));
		}
		this._timer.clear(this,this.showMagic);
		var gap=Math.round(_time/this.wordAry.length);
		if(gap==0)
			debugger
		if(gap > 100)
			gap=100;
		else if(gap < 60)
		gap=60;
		this._timer.loop(gap,this,this.showMagic);
	}

	__proto.showMagic=function(){
		this.count++;
		if(this.txtField){
			var str=this.txtField.text+this.wordAry[this.count];
			this.txtField.text=str;
			if(this.count >=this.wordAry.length-1){
				if(this.callback)
					this.callback.run();
				this._timer.clear(this,this.showMagic);
			}
		}
		else
		this._timer.clear(this,this.showMagic);
	}

	__proto.gc=function(){
		this._timer.clear(this,this.showMagic);
	}

	__proto.starWatch=function(){
		Laya.timer.clear(this.tcaller,this.showTxt);
		Laya.timer.loop(this.time,this,this.showTxt);
		this.showTxt()
	}

	__proto.showTxt=function(){
		this.oldN+=1;
		var gp=this.newN-this.oldN;
		if(gp >=10)
			this.oldN+=10
		if(gp >=100)
			this.oldN+=100;
		if(gp >=1000)
			this.oldN+=1000;
		if(gp >=10000)
			this.oldN+=10000;
		if(this.oldN >=this.newN)
			this.oldN=this.newN;
		if(this.ftcp)
			this.ftcp.value=this.oldN+this.endT;
		else
		this.txt.text=this.oldN+this.endT;
		if(this.oldN >=this.newN)
			Laya.timer.clear(this,this.showTxt);
	}

	__proto.clearWatchTxt=function(){
		Laya.timer.clear(this,this.showTxt);
		if(this.ftcp)
			this.ftcp.value=String(this.newN+this.endT);
		else
		this.txt.text=this.newN+this.endT;
	}

	__getset(1,MagicFont,'ins',function(){
		if(!MagicFont._ins)
			MagicFont._ins=new MagicFont();
		return MagicFont._ins;
	},laya.display.Sprite._$SET_ins);

	MagicFont.showWatchTxt=function(_caller,ftp,txt,_oldN,_newN,_endT,time){
		(_endT===void 0)&& (_endT="");
		(time===void 0)&& (time=50);
		var m=new MagicFont();
		if(ftp)
			m.ftcp=ftp;
		else
		m.txt=txt;
		if(_oldN > _newN)
			_oldN=0;
		m.oldN=_oldN;
		m.newN=_newN;
		m.endT=_endT;
		m.time=time;
		m.tcaller=_caller;
		m.starWatch();
		return m;
	}

	MagicFont._ins=null;
	return MagicFont;
})(Sprite)


