	/**根据平台，判断活动*/
	__proto.checkPlayActive=function(){
		if(!Mgr.userLogin.canPay){
			EventCenter.instance.event("ACTIVE_TOGGLE",["juhuasuan"]);
			EventCenter.instance.event("ACTIVE_TOGGLE",["WXGUANZHUYOULI"]);
			EventCenter.instance.event("ACTIVE_TOGGLE",["kuafuzhanchangyugao"]);
			EventCenter.instance.event("ACTIVE_TOGGLE",["kuafuzhanchang"]);
		}
		if(!BaseSDK.ins.checkGuanZhu()){
			EventCenter.instance.event("ACTIVE_TOGGLE",["WXGUANZHUYOULI"]);
			EventCenter.instance.event("ACTIVE_TOGGLE",["guanzhuyouli"]);
		};
		var obj=BaseSDK.loginSDKUserData;
		if(obj){
			if(obj.game_channel_id==PlatGameChannelIdEnum.CHANNEL_4399){
				EventCenter.instance.event("ACTIVE_TOGGLE",["shoucang"]);
				EventCenter.instance.event("ACTIVE_TOGGLE",["share"]);
			}
			if(obj.game_channel_id==PlatGameChannelIdEnum.CHANNEL_9377){
				EventCenter.instance.event("ACTIVE_TOGGLE",["viptip"]);
				EventCenter.instance.event("ACTIVE_TOGGLE",["shouchonghaoli"]);
				EventCenter.instance.event("ACTIVE_TOGGLE",["juhuasuan"]);
				Mgr.guideActivity.isPermit=true;
			}
			if(obj.game_channel_id !=PlatGameChannelIdEnum.CHANNEL_WANBA){
				EventCenter.instance.event("ACTIVE_TOGGLE",["KJVip"]);
				Configs.isHideYaoQing=true;
			}
			else{
				Configs.isHideYaoQing=false;
				this.isWanBa=true;
				var obj2=BaseSDK.ins.getQZoneOpenData();
				if(obj2)
				{Mgr.vip.sendGetQVipLevelCS(obj2.openid,obj2.openkey);
					var gifgId=BaseSDK.ins.getQZoneJFGift()
					if(gifgId)
						Mgr.vip.sendExchangeGiftCS(gifgId);
				}
			}
		}
		else{
			EventCenter.instance.event("ACTIVE_TOGGLE",["KJVip"]);
		}
		if(WXSDK.isInWX){
			EventCenter.instance.event("ACTIVE_TOGGLE",["KJVip"]);
		}
	}

