//class com.xq.map.display.MapWeatherLayer extends laya.display.Sprite
var MapWeatherLayer=(function(_super){
	function MapWeatherLayer(types){
		this.particle0=null;
		this.particle1=null;
		this.particle2=null;
		this.particle3=null;
		// private var cloud3D0:BaseAni3D;
		this.type=0;
		this.speedScale=0.01;
		this.speedAlpha=0.001;
		this.speedX=5;
		this.speedY=5;
		MapWeatherLayer.__super.call(this);
		this.type=types;
		this.init();
	}

	__class(MapWeatherLayer,'com.xq.map.display.MapWeatherLayer',_super);
	var __proto=MapWeatherLayer.prototype;
	__proto.init=function(){
		switch(this.type){
			case 1:
				this.particle0=new ParticleSystem();
				this.particle0.setRes(PathDefine.PARTICLE+"yun01"+".lz");
				this.particle0.x=Laya.stage.width>>1;
				this.particle0.y=-300;
				SceneContainer.getInstance().underWeatherLayer.addChild(this.particle0);
				this.particle1=new ParticleSystem();
				this.particle1.setRes(PathDefine.PARTICLE+"yun01"+".lz");
				this.particle1.x=Laya.stage.width>>1;
				this.particle1.y=-300;
				SceneContainer.getInstance().topWeatherLayer.addChild(this.particle1);
				break ;
			case 2:
				this.weatherAni();
				Laya.timer.loop(60000,this,this.weatherAni);
				break ;
			case 3:
				this.particle1=new ParticleSystem();
				this.particle1.setRes(PathDefine.PARTICLE+"shuijing"+".lz");
				this.particle1.x=Laya.stage.width>>1;
				this.particle1.y=0;
				SceneContainer.getInstance().underWeatherLayer.addChild(this.particle1);
				this.particle2=new ParticleSystem();
				this.particle2.setRes(PathDefine.PARTICLE+"shuijing"+".lz");
				this.particle2.x=Laya.stage.width>>1;
				this.particle2.y=0;
				SceneContainer.getInstance().topWeatherLayer.addChild(this.particle2);
				break ;
			case 4:
				this.particle0=new ParticleSystem();
				this.particle0.setRes(PathDefine.PARTICLE+"shuibo"+".lz");
				this.particle0.x=1000;
				this.particle0.y=600;
				this.particle1=new ParticleSystem();
				this.particle1.setRes(PathDefine.PARTICLE+"shuiceng"+".lz");
				this.particle1.x=1000;
				this.particle1.y=600;
				SceneContainer.getInstance().underWeatherLayer.addChild(this.particle1);
				SceneContainer.getInstance().underWeatherLayer.addChild(this.particle0);
				break ;
			case 5:
				SceneContainer.getInstance().y=100;
				break ;
			case 6:
				break ;
			}
	}

	__proto.weatherAni=function(){
		switch(this.type){
			case 1:
				this.weatherAni1();
				break ;
			case 2:
				this.weatherAni2();
				break ;
			}
	}

	__proto.weatherAni2=function(){
		LightingUtil.light(2,200);
	}

	/**从上往下飘*/
	__proto.weatherAni1=function(){}
	__proto.dispose=function(){
		Laya.timer.clear(this,this.weatherAni);
		if(this.particle0)
			this.particle0.dispose();
		if(this.particle1)
			this.particle1.dispose();
		if(this.particle2)
			this.particle2.dispose();
		if(this.particle3)
			this.particle3.dispose();
		this.removeSelf();
	}

	return MapWeatherLayer;
})(Sprite)


