//class com.xq.util.WatchUtil
var WatchUtil=(function(){
	function WatchUtil(){
		this.target=null;
		this.end=null;
		this.start=0;
		this.gap=0;
		this.max=0;
		this.curT=0;
	}

	__class(WatchUtil,'com.xq.util.WatchUtil');
	var __proto=WatchUtil.prototype;
	__proto.change=function(){
		this.max-=1;
		this.curT+=1;
		this.target.text=this.curT+this.end;
		if(this.max <=this.start){
			this.stop();
		}
	}

	__proto.startTime=function(){
		this.curT=this.start;
		Laya.timer.loop(this.gap,this,this.change);
	}

	__proto.stop=function(){
		Laya.timer.clear(this,this.change);
	}

	WatchUtil.changeNum=function(target,time,max,end){
		var wat=new WatchUtil();
		wat.target=target;
		wat.start=parseInt(target.text);
		wat.end=end;
		wat.max=max
		wat.gap=Math.floor(time / (max-wat.start));
		wat.startTime();
		return wat;
	}

	return WatchUtil;
})()


