	/**通过ID获取描叙*/
	__proto.getPathAry=function(idAry){
		var ary=[];
		var len=idAry.length;
		for (var i=0;i < len;i++){
			var id=idAry[i];
			if(id=="1"){
				ary.push("精彩活动");
			}
			else{
				var tempObj=this.getDataByID(id);
				if(tempObj){
					ary.push(tempObj.path);
				}
			}
		}
		return ary;
	}

	__proto.getDataByID=function(id){
		return this.uiControlTable.getItemByField("ID",id);
	}

	/**每个子模块一定是有自己的funcid*/
