	/**新的替换老的动画*/
	__proto.repalceAni=function(replacePos){
		var newRender=new this._render();
		newRender.dataSource=this._array[replacePos];
		newRender.zOrder=replacePos;
		var render=this._renderArr[replacePos];
		newRender.y=render.y;
		newRender.x=render.width+10;
		this.addChild(newRender);
		Tween.to(newRender,{x:0},this.ANI_TIME,Ease.backIn);
		Tween.to(render,{x:-render.width-10,alpha:0.4},this.ANI_TIME,Ease.backIn,Handler.create(this,this.onRepalceAniComp,[replacePos,newRender,render]));
	}

	__proto.onRepalceAniComp=function(replacePos,newRender,oldRender){
		this._renderArr[replacePos]=newRender;
		if(oldRender.hasOwnProperty("dispose")){
			oldRender["dispose"]();
		}
		oldRender.removeSelf();
		this.nextAni();
	}

	__proto.createBaseRender=function(){
		var len1=this._renderArr.length;
		var len2=this._array.length;
		if(len1 < len2){
			for(var i=len1;i < len2;i++){
				var render=new this._render();
				render.dataSource=this._array[i];
				render.y=(render.height+this._space)*i
				render.zOrder=i;
				this.addChild(render);
				this._renderArr[i]=render;
			}
		}
	}

