//class view.loading.CreateRoleView extends ui.loading.CreateRoleUI
var CreateRoleView=(function(_super){
	function CreateRoleView(roles){
		/***角色配置表信息*/
		this.shenjiangArray=null;
		/**角色配置表信息数据索引对象*/
		this.shenjiangIndexObj=null;
		/**角色随机名字配置表信息数据索引对象*/
		this.nameRandomIndexObj=null;
		/**当前已有的角色列表*/
		this.roles=null;
		/**当前选中的未创建的角色信息*/
		this.cur_chooseVo=null;
		/**当前选中的已创建的角色信息*/
		this.cur_roleVo=null;
		// private var skeleton_woman_url:String="res2/ani/bones/create_woman.sk";
		this.player=null;
		this.roleMan=null;
		this.roleWoman=null;
		/**15秒后自动创建角色*/
		this.autoCreateRoleTime=30;
		/**是否编辑了名称*/
		this.isEditorName=false;
		this.bgURL=null;
		this.roleURL=null;
		this.bgTexture=null;
		this.bgOrienWidth=NaN;
		this.bgOirenHeight=NaN;
		this.roleOrienWidth=NaN;
		this.roleOirenHeight=NaN;
		this.per=NaN;
		this.privacyView=null;
		/**页面开始时间*/
		this.curTiem=NaN;
		CreateRoleView.__super.call(this);
		this.player=new BigPlayer();
		this.sp_ani.addChild(this.player);
		this.player.scale(1.5,1.5);
		this.roleMan=new RoleVO();
		this.roleMan.weaponQianghuaLevel=1;
		this.roleMan.job="A";
		this.roleWoman=new RoleVO();
		this.roleWoman.weaponQianghuaLevel=1;
		this.roleWoman.job="C";
		this.roles=[];
		this.width=Laya.stage.width;
		this.height=Laya.stage.height;
		this.box.height=Laya.stage.height;
		LogMgr.ins.report(10,{});
		Laya.timer.frameOnce(1,this,this.init,[roles]);
		this.txt_name.on("input",this,this.changeTxt);
	}

	__class(CreateRoleView,'view.loading.CreateRoleView',_super);
	var __proto=CreateRoleView.prototype;
	__proto.changeTxt=function(){
		this.isEditorName=true;
	}

	__proto.init=function(roles){
		var obj=CfgManager.getData("ShenJiangBiao");
		this.shenjiangIndexObj=obj.index;
		this.shenjiangArray=obj.data;
		this.cur_chooseVo=new ShenJiangVO();
		this.cur_chooseVo.bind([this.shenjiangArray[0][this.shenjiangIndexObj.id],
		this.shenjiangArray[0][this.shenjiangIndexObj.race],
		this.shenjiangArray[0][this.shenjiangIndexObj.sex],
		this.shenjiangArray[0][this.shenjiangIndexObj.icon],
		this.shenjiangArray[0][this.shenjiangIndexObj.job],
		this.shenjiangArray[0][this.shenjiangIndexObj.res]]);
		this.btn_start.visible=false;
		if(roles&&roles.length>0){
			this.mouseEnabled=false;
			for(var i=0;i < roles.length;i++){
				var roleVo=new HeroVO();
				roleVo.guid=roles[i].id;
				roleVo.sex=roles[i].gender;
				roleVo.res=this.shenjiangArray[roleVo.sex][this.shenjiangIndexObj.res];
				roleVo.job=roles[i].job;
				roleVo.name=roles[i].name;
				roleVo.level=roles[i].level;
				roleVo.face=roles[i].face;
				roleVo.registTime=roles[i].addTime;
				roleVo.fightValue=roles[i].power;
				this.roles.push(roleVo);
				this.cur_roleVo=roleVo;
				this.onStartGame();
				return
			}
		}
		this.btn_create.on("click",this,this.onBtnCreateRole);
		this.btn_start.on("click",this,this.onStartGame);
		this.ck_man.on("click",this,this.onManChange);
		this.ck_woman.on("click",this,this.onWomanChange);
		this.btn_random.on("click",this,this.randomName);
		this.ck_man.selected=true;
		this.ck_woman.selected=false;
		this.txt_label.alpha=0;
		var job=LocalStorage.getItem(NetMgr.ins().serverVO.userId);
		var random=Math.random();
		Laya.stage.on("resize",this,this.onResize);
		this.bg.centerX=0;
		this.bg.centerY=0;
		this.img_role.centerX=0;
		if(random > 0.5){
			this.onManChange();
			}else{
			this.onWomanChange();
		}
		this.randomName();
		this.checkIsCreate();
		this.txt_autoCreate.text=this.autoCreateRoleTime+"秒后自动创建角色";
		Laya.timer.loop(1000,this,this.autoCreateRole);
		this.curTiem=0
		if(this.btn_create.visible){
			BaseSDK.ins.reportMark("1");
			this.curTiem=Browser.now();
		}
	}

	__proto.autoCreateRole=function(){
		this.autoCreateRoleTime--;
		this.txt_autoCreate.text=this.autoCreateRoleTime+"秒后自动创建角色";
		if(this.autoCreateRoleTime <=0){
			Laya.timer.clear(this,this.autoCreateRole);
			this.onBtnCreateRole();
		}
	}

	/**名字随机*/
	__proto.randomName=function(){
		if(this.destroyed)return;
		var job;
		if(this.ck_man.selected)
			job="A";
		else
		job="C";
		this.txt_name.text=CommonUtil.getRanNameBySex(job);
		this.autoCreateRoleTime=30;
		this.txt_autoCreate.text=this.autoCreateRoleTime+"秒后自动创建角色";
	}

	/**检测当前选中角色是否已经创建*/
	__proto.checkIsCreate=function(){
		this.randomName();
		this.btn_create.visible=true;
		this.btn_start.visible=false;
		this.btn_random.visible=true;
		this.txt_name.visible=true;
		this.txt_label.visible=true;
		for(var i=0;i < this.roles.length;i++){
			if(this.roles[i].sex==this.cur_chooseVo.sex){
				this.cur_roleVo=this.roles[i];
				this.btn_create.visible=false;
				this.btn_start.visible=true;
				this.btn_random.visible=false;
				this.txt_name.visible=false;
				this.txt_label.visible=false;
			}
		}
	}

	__proto.loadJobBg=function(sex){
		if(Browser.onPC){
			this.bgURL=sex?PathDefine.getROLEBGUrl("create_womanBg_pc",false):PathDefine.getROLEBGUrl("create_manBg_pc",false);
		}
		else{
			this.bgURL=sex?PathDefine.getROLEBGUrl("create_womanBg",false):PathDefine.getROLEBGUrl("create_manBg",false);
		}
		this.roleURL=sex?PathDefine.getROLEBGUrl("woman",true):PathDefine.getROLEBGUrl("man",true);
		Laya.loader.load(this.bgURL,Handler.create(this,this.onLoaded));
	}

	__proto.onResize=function(){
		this.onResizeBg();
		this.onResizeRole();
	}

	__proto.onResizeBg=function(){
		var sw=Laya.stage.width;
		var sh=Laya.stage.height;
		if(isNaN(sw)||isNaN(sh))return;
		this.width=sw;
		this.height=sh;
		this.bg.skin=this.bgURL;
		if(isNaN(this.bgOrienWidth)||isNaN(this.bgOirenHeight))return;
		if(Browser.onPC){
			this.per=sh/this.bgOirenHeight;
			this.bg.width=this.bgOrienWidth *this.per;
			this.bg.height=sh;
		}
		else{
			this.bg.width=this.bgOrienWidth;
			this.bg.height=this.bgOirenHeight;
		}
	}

	__proto.onResizeRole=function(){
		if(isNaN(this.roleOrienWidth)||isNaN(this.roleOirenHeight))return;
		if(Browser.onPC){
			if(this.per){
				this.img_role.width=this.roleOrienWidth*this.per;
				this.img_role.height=this.roleOirenHeight*this.per;
				this.img_role.y=155;
			}
		}
		else{
			this.img_role.width=this.roleOrienWidth;
			this.img_role.height=this.roleOirenHeight;
			this.img_role.y=217;
		}
	}

	__proto.onLoaded=function(){
		if(this.destroyed)return;
		var bgTexture=Laya.loader.getRes(this.bgURL);
		if(bgTexture){
			this.bgOrienWidth=bgTexture.width;
			this.bgOirenHeight=bgTexture.height;
			this.onResizeBg();
			Laya.loader.load(this.bgURL,Handler.create(this,this.onRoleLoaded));
		}
	}

	__proto.onRoleLoaded=function(){
		if(this.destroyed)return;
		var bgTexture=Laya.loader.getRes(this.roleURL);
		if(bgTexture){
			this.roleOrienWidth=bgTexture.width;
			this.roleOirenHeight=bgTexture.height;
			this.onResizeRole();
		}
	}

	__proto.tweenImage=function(){
		this.img_role.alpha=0;
		Tween.to(this.img_role,{alpha:1},500);
	}

	/**选择男主*/
	__proto.onManChange=function(){
		this.tweenImage();
		this.loadJobBg(0);
		this.img_role.skin=PathDefine.getROLEBGUrl("man",true);
		if(!this.ck_woman.selected){
			this.ck_man.selected=true;
			return;
		}
		this.ck_woman.selected=false;
		this.cur_chooseVo.bind([this.shenjiangArray[0][this.shenjiangIndexObj.id],
		this.shenjiangArray[0][this.shenjiangIndexObj.race],
		this.shenjiangArray[0][this.shenjiangIndexObj.sex],
		this.shenjiangArray[0][this.shenjiangIndexObj.icon],
		this.shenjiangArray[0][this.shenjiangIndexObj.job],
		this.shenjiangArray[0][this.shenjiangIndexObj.res]]);
		this.checkIsCreate();
	}

	/**选择女主*/
	__proto.onWomanChange=function(){
		this.tweenImage();
		this.loadJobBg(1);
		this.img_role.skin=PathDefine.getROLEBGUrl("woman",true);
		if(!this.ck_man.selected){
			this.ck_woman.selected=true;
			return;
		}
		this.ck_man.selected=false;
		this.ck_woman.selected=true;
		this.cur_chooseVo.bind([this.shenjiangArray[1][this.shenjiangIndexObj.id],
		this.shenjiangArray[1][this.shenjiangIndexObj.race],
		this.shenjiangArray[1][this.shenjiangIndexObj.sex],
		this.shenjiangArray[1][this.shenjiangIndexObj.icon],
		this.shenjiangArray[1][this.shenjiangIndexObj.job],
		this.shenjiangArray[1][this.shenjiangIndexObj.res]]);
		this.checkIsCreate();
	}

	/**等待*/
	__proto.onwaiting=function(flag){
		if(flag)
			LoadingUtil.showLoading();
		else
		LoadingUtil.hideLoading();
		this.btn_create.disabled=flag;
		this.btn_start.disabled=flag;
	}

	__proto.regisTimeOt=function(){
		Laya.timer.once(5000,this,this.onwaiting,[false]);
	}

	__proto.onBtnCreateRole=function(){
		var recentSerData=ServerMgr.ins.getLastServer();
		var curServerData=ServerMgr.ins.gameServerObj;
		var day=Math.ceil((Browser.now()-curServerData.openTime)/1000/60/60/24);
		if(PathDefine.isPublish &&Configs.isServerLimit&&curServerData&&recentSerData&&recentSerData.serverId!=curServerData.serverId&&day>3){
			Alert.show("当前服开服时间较久，请前往新服进行游戏。","提示",Handler.create(this,this.alerHandler));
			return;
		};
		var userName=this.txt_name.text;
		CreateRoleMgr.ins().checkNameIsOK(userName,Handler.create(this,this.onBtnCreateRoleLater,[userName]));
	}

	__proto.alerHandler=function(){
		if(this.destroyed)return;
		NetMgr.ins().closeConnect();
		var newSerObj=ServerMgr.ins.getNewServer();
		if(!newSerObj)return;
		ServerMgr.ins.gameServerObj=newSerObj;
		ServerMgr.ins.roleLoginName=BaseSDK.userId;
		BaseSDK.serverId=newSerObj.serverId;
		BaseSDK.serverName=newSerObj.serverName;
		BaseSDK.setServerID();
		NetMgr.ins().connect(newSerObj.serverPath,Handler.create(this,this.onConnectSuccess,[BaseSDK.userId,BaseSDK.serverId]));
	}

	__proto.onConnectSuccess=function(userId,serverId,isSuccess){
		if(isSuccess){
			Mgr.userLogin.sendLogin(userId,
			serverId,
			Handler.create(this,this.onLoginOK));
			var svo=NetMgr.ins().serverVO;
			svo.userId=userId;
			svo.serverId=serverId;
			svo.serverName=BaseSDK.serverName;
			NetMgr.ins().roleVO.serverId=serverId;
		}
		else{
			Mgr.prompt.optionPrompt("服务器连接失败，请刷新游戏稍后再试");
		}
	}

	__proto.onLoginOK=function(data){
		var roles=data.arr;
		if(roles){
			if(!((roles instanceof Array))){
				roles=[roles];
			}
		};
		var roleArr=roles;
		if(roleArr && roleArr.length > 0){
			this.init(roles);
		}
		else{
			var userName=this.txt_name.text;
			CreateRoleMgr.ins().checkNameIsOK(userName,Handler.create(this,this.onBtnCreateRoleLater,[userName]));
		}
	}

	__proto.onBtnCreateRoleLater=function(userName,isLegal){
		if(isLegal){
			var _net=NetMgr.ins();
			_net.roleVO.res=this.cur_chooseVo.res;
			Mgr.userLogin.sendCreateRole(this.cur_chooseVo,userName,Handler.create(this,this.onCreateOK));
			this.onwaiting(true);
			BaseSDK.ins.reportMark("2",Math.floor((Browser.now()-this.curTiem)/1000));
			if(this.isEditorName){
				BaseSDK.ins.reportMark("3");
			}
		}
	}

	/**已有角色直接进入游戏*/
	__proto.onStartGame=function(){
		NetMgr.ins().roleVO=this.cur_roleVo;
		Mgr.userLogin.sendRoleLogin(this.cur_roleVo.guid,Handler.create(this,this.loginCallback));
		this.onwaiting(true);
	}

	/**创角成功 发送角色登录消息*/
	__proto.onCreateOK=function(data,suc){
		if(suc){
			var roleVo=new HeroVO();
			roleVo.guid=data.id;
			roleVo.sex=data.gender;
			roleVo.res=this.shenjiangArray[roleVo.sex][this.shenjiangIndexObj.res];
			roleVo.job=data.job;
			roleVo.name=data.name;
			roleVo.level=data.level;
			roleVo.face=data.face;
			NetMgr.ins().roleVO=roleVo;
			Mgr.userLogin.sendRoleLogin(data.id,Handler.create(this,this.loginCallback));
		}
		else{
			this.onwaiting(false);
			this.randomName();
			this.autoCreateRoleTime=30;
			this.txt_autoCreate.text=this.autoCreateRoleTime+"秒后自动创建角色";
			Laya.timer.loop(1000,this,this.autoCreateRole);
		}
	}

	__proto.loginCallback=function(){
		Mgr.sceneSyn.sendApplyEnterStage();
		EventCenter.instance.once("APPLY_ENTER_SCENE",this,this.onApplyEnterOK);
	}

	__proto.onApplyEnterOK=function(){
		this.dispose();
		CreateRoleMgr.ins().onApplyEnterOK();
	}

	__proto.dispose=function(){
		Laya.stage.off("resize",this,this.onResize);
		Laya.timer.clear(this,this.autoCreateRole);
		Laya.timer.clear(this,this.onwaiting);
		this.onwaiting(false);
		this.btn_random.off("click",this,this.randomName);
		this.btn_create.off("click",this,this.onBtnCreateRole);
		this.ck_man.off("click",this,this.onManChange);
		this.ck_woman.off("click",this,this.onWomanChange);
		Mgr.sinImgMgr.add(this.bg);
		this.img_role.skin=null;
		if(this.player){
			this.player.dispose();
			this.player=null;
		}
		this.removeSelf();
		this.destroy(true);
	}

	CreateRoleView.isAutoCreate=false;
	return CreateRoleView;
})(CreateRoleUI)


