//class view.loading.HealthTips extends ui.loading.HealthTipsUI
var HealthTips=(function(_super){
	function HealthTips(){
		this.showOver=false;
		this.loaded=false;
		HealthTips.__super.call(this);
		if(isNaN(Laya.stage.width)){
			this.width=750;
			this.height=1334;
		}
		else{
			this.width=Laya.stage.width;
			this.height=Laya.stage.height;
		}
		this.loaded=false;
		this.showOver=false;
		this.loadChooserRes();
		Laya.timer.once(1500,this,this.showTime);
		EventCenter.instance.on(ServerMgr.GET_SERVER_LIST_BACK,this,this.onServer);
		this.txtB.visible=!Configs.hideHealthTip;
	}

	__class(HealthTips,'view.loading.HealthTips',_super);
	var __proto=HealthTips.prototype;
	__proto.onServer=function(){
		this.close();
	}

	__proto.showTime=function(){
		this.showOver=true;
		this.close();
	}

	__proto.loadChooserRes=function(){
		ServerMgr.ins;
		var ary=[
		{url:Configs.startLoadUrl.commonUrl,type:"atlas",size:100,priority:1},
		{url:Configs.startLoadUrl.panel2Url,type:"atlas",size:100,priority:1},
		{url:Configs.startLoadUrl.basePanelUrl,type:"atlas",size:100,priority:1},
		{url:Configs.startLoadUrl.loginImgUrl,type:"image",size:100,priority:1},
		{url:Configs.startLoadUrl.createUrl,type:"atlas",size:100,priority:1},
		{url:Configs.startLoadUrl.loadingUrl,type:"atlas",size:100,priority:1},
		{url:Configs.startLoadUrl.pardicUrl,type:"json",size:200,priority:1}]
		Laya.loader.load(ary,Handler.create(this,this.onServerAlted));
	}

	__proto.onServerAlted=function(){
		this.loaded=true;
		this.close();
	}

	__proto.close=function(){
		if(this.showOver && this.loaded && ServerMgr.ins.serverIsOK){
			this.removeSelf();
			EventCenter.instance.off(ServerMgr.GET_SERVER_LIST_BACK,this,this.onServer);
			var p=new PreloadingView();
			p.visible=false;
			var chooseServer=new ChooseServer();
			Laya.stage.addChild(chooseServer);
			Laya.stage.addChild(p);
			BaseSDK.ins.setLoadingProgress(100);
			if(Configs.showHealthTipLogin){
				this.txt_login&&this.txt_login.off("click",this,this.onReLogin);
			}
		}
		else{
			if(Configs.showHealthTipLogin){
				this.txt_login.visible=true;
				this.txt_login.on("click",this,this.onReLogin);
			}
		}
	}

	__proto.onReLogin=function(){
		BaseSDK.ins.reloginSDK();
	}

	__proto.sdkLoadCallBack=function(){}
	return HealthTips;
})(HealthTipsUI)


