		this.height=sh;
		this.nBg.skin=this.bgURL;
		if(Browser.onPC){
			if(isNaN(this.bgOrienWidth)||isNaN(this.bgOrienWidth))return;
			var per=sh/this.bgOirenHeight;
			this.nBg.width=this.bgOrienWidth *per;
			this.nBg.height=sh;
		}
