var TransitCloudView=(function(_super){
	function TransitCloudView(){
		this.lastSceneId=-1;
		TransitCloudView.__super.call(this);
	}

	__class(TransitCloudView,'view.loading.TransitCloudView',_super);
	var __proto=TransitCloudView.prototype;
	Laya.imps(__proto,{"com.xq.view.loading.ITransitCloudView":true})
	__proto.init=function(bo){
		(bo===void 0)&& (bo=false);
		Game.getInstance().newMainView.showHide(1,false);
		Game.getInstance().newMainView.getTopActive().isShowActive(false);
		if(bo){
			this.bg.alpha=1;
			this.lastSceneId=NetMgr.ins().roleVO.mapId;
			NetMgr.ins().roleVO.mapId=Game.getInstance().lastMapId;
			this.closeAni();
			Laya.stage.on("resize",this,this.onResize);
		}
		else{
			this.bg.alpha=0;
			Laya.timer.once(800,this,this.doCom);
		}
		this.onResize();
	}

	__proto.onResize=function(){
		this.width=Laya.stage.width+10;
		this.height=Laya.stage.height+10;
		this.x=-5;
		this.y=-5;
	}

	__proto.doCom=function(){
		this.openCom();
		this.close();
	}

	__proto.closeAni=function(){
		Laya.timer.once(1000,this,this.closeCom);
		Laya.timer.once(800,this,this.openCom);
	}

	__proto.closeCom=function(){
		Laya.stage.off("resize",this,this.onResize);
		Tween.to(this.bg,{alpha:0},500,null,Handler.create(this,this.close));
	}

	__proto.openCom=function(){
		Game.getInstance().cleanUp();
		this.event("complete");
	}

	__proto.close=function(){
		Tween.clearAll(this.bg);
		Laya.timer.clear(this,this.closeCom);
		Laya.timer.clear(this,this.openCom);
		Laya.timer.clear(this,this.doCom);
		this.removeSelf();
	}

	__proto.readyDestory=function(){
		if(this.lastSceneId !=-1){
			Game.getInstance().lastMapId=this.lastSceneId;
		}
	}

	__proto.firstInit=function(){}
	__proto.loadPreMapRes=function(mapId,posX,posY){}
	return TransitCloudView;
})(TransitCloudUI)


