		Laya.timer.loop(15000,this,this.closeXuanShangTips);
		if(!this.mrxstips){
			this.mrxstips=MeirtsTipsView.getItem();
		}
		this.mrxsBoo=true;
		this.btnDaily.addChild(this.mrxstips);
