			var curLvCfg=Mgr.minggeMgr.getMgLvCof(lv);
			var curAttr=Mgr.minggeMgr.getAttributeStrings(mgCfg.attr,curLvCfg.gudingchengzhang,curLvCfg.baifenbichengzhang,mgCfg.gudingxishu,mgCfg.baifenbixishu);
