//class view.mainUI.subPanel.ControlBoxView extends ui.mainUI.subPanel.ControlBoxUI
var ControlBoxView=(function(_super){
	function ControlBoxView(){
		// private var _isStart:Boolean;
		this._centerX=0;
		this._centerY=0;
		this._radius=59;
		this._player=null;
		this._curDir=0;
		/**路径点距离*/
		this._distance=300;
		/**触摸点与遥感中心点的距离*/
		this._curdistance=NaN;
		/**场景对象*/
		this._scene=null;
		this.curTouchId=-1;
		/**是否移动了*/
		this.hasMove=false;
		/**遥感时间*/
		this.conTime=0;
		/**新的移动*/
		this.isNew=false;
		/**启动坐标*/
		this.starPo=null;
		ControlBoxView.__super.call(this);
		Laya.stage.on("mousedown",this,this.startMove);
		Laya.stage.on("mouseup",this,this.endMove);
		this._centerX=this.btn_move.x;
		this._centerY=this.btn_move.y;
		this.mouseThrough=true;
		this.visible=false;
		this.reset();
		this.mouseEnabled=false;
		this.mouseThrough=true;
	}

	__class(ControlBoxView,'view.mainUI.subPanel.ControlBoxView',_super);
	var __proto=ControlBoxView.prototype;
	Laya.imps(__proto,{"com.xq.view.mainUI.subPanel.IControlBoxView":true})
	/**开始准备摇杆*/
	__proto.startMove=function(e){
		this.hasMove=false;
		this.isNew=true;
		InputMgr.getInstance().onStageMouseDown(e);
		EventCenter.instance.on("ChangeControlBoxState",this,this.updateState);
	}

	__proto.updateState=function(bo){
		this.visible=bo;
	}

	__proto.doMove=function(e){
		if(!this.starPo){
			this.starPo=new Point();
		}
		this.starPo.setTo(Laya.stage.mouseX,Laya.stage.mouseY);
		this.stage.on("mousemove",this,this.move);
	}

	__proto.showBox=function(e){
		var player=Game.getInstance().player;
		if(!player || player.isNotClick)
			return;
		this.pos(Laya.stage.mouseX-this.width/2,Laya.stage.mouseY-this.height/2,true);
		if((e.target instanceof laya.display.Stage )|| (e.target instanceof view.mainUI.subPanel.ControlBoxView )){
			this.visible=true;
			this.conTime=0;
			this.curTouchId=e.touchId;
			if(!this._player)
				this._player=Game.getInstance().player;
			InputMgr.getInstance()._isStart=true;
			AIController.ins().stopAutoPath();
			Laya.timer.loop(200,this,this.toMove);
		}
	}

	/**移动摇杆*/
	__proto.move=function(e){
		if(this.isNew){
			var curPo=new Point(Laya.stage.mouseX,Laya.stage.mouseY);
			if(curPo.distance(this.starPo.x,this.starPo.y)> 20){
				this.showBox(e);
				this.isNew=false;
			}
			else
			return;
		}
		this.hasMove=true;
		if(InputMgr.getInstance()._isStart){
			if(this.curTouchId==e.touchId){
				var tx=(e.stageX-Math.round(this.x));
				var ty=(e.stageY-Math.round(this.y));
				this.updateXY(tx,ty);
				var dy=this.btn_move.y-this._centerY;
				var dx=this.btn_move.x-this._centerX;
				var tempR=180 / Math.PI *Math.atan2(dy,dx);
				this.mc_bg.rotation=tempR;
			}
		}
	}

	/**结束摇杆移动*/
	__proto.endMove=function(e){
		this.stage.off("mousemove",this,this.move);
		Laya.timer.clear(this,this.toMove);
		if((e.target instanceof laya.display.Stage )){
			if(!this.hasMove){
				this.hasMove=false;
				InputMgr.getInstance().showClickEff();
			}
		}
		if(!InputMgr.getInstance()._isStart){
			return;
		}
		if(e.touchId==this.curTouchId){
			this.reset();
			this.btn_move.x=this._centerX;
			this.btn_move.y=this._centerY;
			InputMgr.getInstance()._isStart=false;
			if(this._player)
				this._player.stand();
			if(!this._player)
				return;
			this._player.isTask=false;
			Mgr.sceneSyn.sendPlayerMove(this._player,[[this._player.x,this._player.y]],true,true);
			this.curTouchId=-1;
		}
	}

	__proto.toMove=function(){
		if(this._curdistance==0){
			return;
		}
		this.conTime+=200;
		if(this.conTime > 1000 && !this._player.isMount){
			console.log("=============起乘状态"+this._player.isMount);
			SceneSynAction2.ins().sendHorseUpDownCS(true);
			this.conTime=0;
		};
		var arr=this.getPath();
		if(this._player){
			if(!this._scene)
				this._scene=Game.getInstance().sceneContainer;
			this._player.moveTo(arr[0],arr[1],false,true);
			this._player.isGuaji=false;
		}
	}

	/**根据当前方向返回一个目标点*/
	__proto.getPath=function(){
		if(isNaN(this._curdistance)){
			return [this._player.x,this._player.y];
		};
		var per=this._distance/this._curdistance;
		var perX=this.btn_move.x-this._centerX;
		var perY=this.btn_move.y-this._centerY;
		var xx=Math.round(perX *per+this._player.x);
		var yy=Math.round(perY *per+this._player.y);
		return [xx,yy];
	}

	/**根据鼠标点击的坐标来计算并显示实际的XY坐标*/
	__proto.updateXY=function(tx,ty){
		this._curdistance=CommonUtil.getDistance(tx,ty,this._centerX,this._centerY);
		if(!this._curdistance){
			this._curdistance=0;
			return;
		}
		if(this._curdistance > this._radius){
			var per=this._radius/this._curdistance;
			var x=0;
			var y=0;
			x=(tx-this._centerX)*per+this._centerX;
			y=(ty-this._centerY)*per+this._centerY;
			this.btn_move.x=x;
			this.btn_move.y=y;
			this._curdistance=this._radius
		}
		else{
			this.btn_move.x=tx;
			this.btn_move.y=ty;
		}
	}

	__proto.reset=function(){
		this.x=(Laya.stage.width-this.width)/2-250;
		this.y=Laya.stage.height-700;
	}

	return ControlBoxView;
})(ControlBoxUI)


