	/**初次进入游戏或货币改变时调用*/
	__proto.onUpdateGoldSilver=function(){
		var roleVO=NetMgr.ins().roleVO;
		this.tongbanTxt.text=CommonUtil.numFormat(roleVO.taiYu);
		this.goldTxt.text=CommonUtil.numFormat(roleVO.yuanbao,0,false,2);
		this.coinTxt.text=CommonUtil.numFormat(roleVO.coin);
		var ob=Mgr.friend.getValueBytp(100);
		var tl=roleVO.coin-Mgr.bag.oldYL;
		var t2=roleVO.yuanbao-Mgr.bag.oldYB;
		var t3=roleVO.bindYuanbao-Mgr.bag.oldBY;
		if(ob){
			var flyX=Laya.stage.width*0.5;
			var flyY=Laya.stage.height*0.4;
			if(Mgr.bag.oldYL!=0&&tl >=1&&Mgr.bag.ylFly){
				MoneyFlyEffectUtill.instance.play(1,flyX,flyY,10,0);
			}
			if(Mgr.bag.oldYB !=0 &&t2 >=100){
				MoneyFlyEffectUtill.instance.play(2,flyX,flyY,20);
			}
			if(Mgr.bag.oldBY!=0&&t3 >=1){
				MoneyFlyEffectUtill.instance.play(3,flyX,flyY,12);
			}
		}
		Mgr.bag.oldYL=roleVO.coin;
		Mgr.bag.oldYB=roleVO.yuanbao;
		Mgr.bag.oldBY=roleVO.bindYuanbao;
	}

