			if(!this._resAni){
				this._resAni=new DisplayAni();
				this._resAni.mouseEnabled=false;
				this._resAni.mouseThrough=true;
			};
			var scale=parseFloat(cof.size);
			var path=cof.ani;
			var pathArr=path.split(";");
			if(pathArr.length>1){
				var job=this._roleVo.job;
				path=job=="A"?pathArr[0]:pathArr[1];
			}
			else{
				path=pathArr[0];
			}
			this._resAni.setResWithScale(PathDefine.OUT_RES+"ani/"+path+".amt",scale,scale);
			var offsetArr=cof.xytype.split(":");
			var offsetX=parseInt(offsetArr[0]);
			var offsetY=parseInt(offsetArr[1]);
			this._resAni.pos(offsetX,offsetY);
