			var i=parseInt(cof.value);
			var l=0;
			while(i >=1){
				i=i/10;
				l++;
			}
			this.view_value.setFight=cof.powernum;
			this.txt_num.text=this._arM.progress.toString();
			this.hbox_num.refresh();
			this.hbox_num.centerX=0;
			this._stat=this._arM.getStat(cof.id);
