//class view.modules.baoDaGM.item.BaoDaGMBossItem extends ui.modules.baoDaGM.BaoDaGMBossItemUI
var BaoDaGMBossItem=(function(_super){
	function BaoDaGMBossItem(){
		this.endTime=NaN;
		this.maskPro=null;
		this.bossState=null;
		BaoDaGMBossItem.__super.call(this);
	}

	__class(BaoDaGMBossItem,'view.modules.baoDaGM.item.BaoDaGMBossItem',_super);
	var __proto=BaoDaGMBossItem.prototype;
	__proto.initialize=function(){
		laya.ui.Component.prototype.initialize.call(this);
		this.maskPro=new Sprite();
		this.imgPro.mask=this.maskPro;
		this.maskPro.x=this.imgIco.width *0.5;
		this.maskPro.y=this.imgIco.height *0.5;
		this.on("click",this,this.onSearch);
	}

	__proto.updatePlayerIco=function(touxiangId){
		this.img_bossbg.visible=true;
		this.imgIco.skin="mainui/topPanel/"+touxiangId+".png";
	}

	__proto.updateBossIco=function(touxiangId){this.img_bossbg.visible=false;
		this.imgIco.skin="modules/baodagm/"+touxiangId+".png";
	}

	__proto.updatePro=function(){
		this.imgGet.visible=false;
		var curValue=0;
		var curMaxValue=0;
		var valueMsg=BaoDaGMMgr.ins.getBossValueById(this.bossState.bossId);
		if(valueMsg){
			curValue=valueMsg.curVal;
			curMaxValue=valueMsg.targetVal;
		}
		this.imgGet.visible=curMaxValue==0;
		this.maskPro.graphics.clear();
		if(curMaxValue <=0)
			return;
		var params=curValue / curMaxValue *360+270;
		this.maskPro.graphics.drawPie(0,0,this.imgIco.height *0.5,270,params,0xff0000);
	}

	__proto.ticktick=function(){
		var rtime=this.endTime-Mgr.curTime.serverTimer;
		if(rtime > 0){
			this.labInfo.text=CommonUtil.formatDate(rtime,15,false);
			this.labInfo.color=rtime > 30000 ? "#00d400" :"#FF0000";
		}
		else{
			Laya.timer.clear(this,this.ticktick);
			this.labInfo.color="#00d400";
			this.labInfo.text="";
		}
	}

	__proto.onSearch=function(){
		AIController.ins().clearAutoChangeForbit();
		AIController.ins().changeForbitAutoCombat(false);
		var pointArr=SceneContainer.GridToGlobal(this.bossState.x,this.bossState.y);
		AIController.ins().startAutoPath(NetMgr.ins().roleVO.mapId,pointArr[0],pointArr[1],Handler.create(this,this.moveComplete));
	}

	__proto.moveComplete=function(){
		if(this.bossState.removeBossTime > 0){
			AIController.ins().startAutoCombat(this.bossState.bossId);
			return;
		}
		if(Number(this.bossState.bossId)==NetMgr.ins().roleVO.guid){
			return;
		}
		AIController.ins().changeTarget(UnitManager.ins.getPlayerByRoleID(Number(this.bossState.bossId)));
		EventCenter.instance.event("boss_update_attackPlayer");
	}

	__proto.gc=function(){
		Laya.timer.clear(this,this.ticktick);
	}

	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		Laya.timer.clear(this,this.ticktick);
		if(!value)return;
		this._dataSource=value;
		this.bossState=value;
		if(this.bossState.removeBossTime > 0){
			this.endTime=this.bossState.removeBossTime;
			this.updatePro();
			this.updateBossIco(this.bossState.touxiangId);
			this.ticktick();
			Laya.timer.loop(1000,this,this.ticktick);
			return;
		}
		this.imgGet.visible=false;
		this.labInfo.text=this.bossState.bossName;
		this.labInfo.color="#00d400"
		this.updatePlayerIco(this.bossState.touxiangId);
		this.maskPro.graphics.clear();
	});

	return BaoDaGMBossItem;
})(BaoDaGMBossItemUI)


