		var ary=[this.btnSx,this.btnJh,this.btnL,this.btnR];
		CommonUtil.addEvent(ary,"click",this,this.onClick);
		this.onCardInfo();
		this.fightV.setFight=Mgr.gqMgr.getTotalFight();
		this.comImg.skin=PathDefine.ShenJiangCardImg+this.curCfg.uiRes+".png";;
		var url=PathDefine.JXName+this.curCfg.uiRes+".png";
		this.v_name.setName(url);
