		CommonUtil.clearRes(this.bg1);
		CommonUtil.clearRes(this.bg2);
		CommonUtil.clearRes(this.comImg);
		this.v_name.dispose();
		this.comImg.skin="";
		var ary=[this.btnSx,this.btnJh];
		CommonUtil.clrEvent(ary,"click",this,this.onClick);
		EventCenter.instance.off("unlockcard_gqEvent",this,this.flush);
		EventCenter.instance.off("card_infoEvent",this,this.onCardInfo);
		EventCenter.instance.off(RedTypeEnum.JiangXingRed ,this ,this.checkRed);
		EventCenter.instance.off("JiHuoChengGongJX" ,this ,this.jhcgHandler);
