		if(value <=1){
			value=1;
			this.btnL.visible=false;
		}
		if(value >=autoSelectId){
			value=autoSelectId;
			this.btnR.visible=false;
		}
		this._curCardId=value;
		this.curCfg=this.gqMgr.getCardCfg(value);
		this.updaeFl();
		this.checkRed();
		this.spList.refresh();
