			this.roleVO=new RoleVO();
		var aRank=this.mgr.getRankData(1);
		if(aRank){
			this.roleVO.job=aRank.sex==1?"A":"C";
			}else{
			this.roleVO.job=NetMgr.ins().roleVO.job;
		}
		if(vo.chibangId > 0){
			this.roleVO.wingHuanHuaId=vo.chibangId;
			}else{
			this.roleVO.wingLevel=1;
		}
		this.roleVO.wuQiHuanHuaId=vo.wuqiId;
		this.roleVO.roleHuanHuaId=vo.shizhuangId;
		this.bigPlayer.createPlayer(this.roleVO);
		this.spriteAni.addChild(this.bigPlayer);
