		Mgr.sinImgMgr.add(this.mc_djBg);
		Laya.timer.clear(this,this.jishi);
		var bossCells=this.list.cells;
		for(var idx in bossCells){
			var r=bossCells[idx];
			if(r)
				r.dispose();
		}
		if(this.ani){
			this.ani.dispose();
			this.ani=null;
		}
		Mgr.jindi.openType=1
		Mgr.bossRefreshMgr.removeGoIdDic(999);
