var ZhuanJinTongView=(function(_super){
	function ZhuanJinTongView(){
		this._mgr=null;
		this._action=null;
		/**记录剩余次数*/
		this.times=0;
		/**本次花费玉币 */
		this.cost=0;
		/**本次可获得经验*/
		this.exp=0;
		this.roleVO=null;
		/**月卡免费次数*/
		this.freeTimes=0;
		/**当前vip最大次数*/
		this.maxTimes=0;
		/**当前角色身上玉币*/
		this.role_coin=0;
		this.cacheArr=null;
		ZhuanJinTongView.__super.call(this);
		this._mgr=Mgr.zhuanJinTongM;
		this._action=Mgr.zhuanJinTongA;
		this.SetLabel();
	}

	__class(ZhuanJinTongView,'view.modules.activity.zhuanJinTong.ZhuanJinTongView',_super);
	var __proto=ZhuanJinTongView.prototype;
	__proto.SetLabel=function(){
		this.txt_reward.style.align="center";
		this.txt_reward.style.fontSize=26;
		this.txt_times.style.align="center";
		this.txt_times.style.fontSize=24;
	}

	__proto.open=function(){
		this._action.sendGetInfo();
		this.startListener();
		this.roleVO=NetMgr.ins().roleVO;
		this.svipData();
	}

	__proto.startListener=function(){
		EventCenter.instance.on("UpdateInfo",this,this.updateInfo);
		this.btn_yq.on("click",this,this.onDraw);
		this.text_kaitong.on("click",this,this.svipTiaoZhuan);
	}

	__proto.onDraw=function(){
		if(this.times<=0){
			Mgr.prompt.optionPrompt("今日摇经验次数已经用完，欢迎明天再来摇经验哦！");
			return;
		};
		var imgskin="modules/common/exp.png";
		var pos={};
		pos.x=Laya.stage.width>>1;
		pos.y=Laya.stage.height;
		var startX=(Laya.stage.width-this.width)>>1;
		DropIconTween.start(imgskin,pos,50,700,200,startX,400,70,680);
		this._action.sendStartExPCS();
	}

	//发送摇经验消息给后台
	__proto.svipData=function(){
		if(this.roleVO.vipLevel >=Mgr.vipcfgMgr.maxSvipLv){
			this.hbox_svip.visible=false;
			this.text_kaitong.visible=false;
			return;
		}
		if(this.roleVO.vipLevel==0){
			this.text_kaitong.text="立即开通";
			}else{
			this.text_kaitong.text="立即升级";
		};
		var vipCfg=Mgr.vip.getVipInfoByLv(this.roleVO.vipLevel);
		var len=Mgr.vipcfgMgr.maxSvipLv-this.roleVO.vipLevel;
		var svipLv=this.roleVO.vipLevel+1;
		var qty=0;
		for (var i=1;i <=len;i++){
			var vipInfo=Mgr.vip.getVipInfoByLv(this.roleVO.vipLevel+i);
			if(vipInfo.zhuanjingcount > vipCfg.zhuanjingcount){
				qty=vipInfo.zhuanjingcount-vipCfg.zhuanjingcount;
				svipLv=vipInfo.lv;
				break ;
			}
		}
		this.text_svip.text="SVIP"+svipLv;
		this.text_Qty.text="+"+qty;
		this.hbox_svip.refresh();
	}

	__proto.updateInfo=function(){
		this.times=this._mgr.getInfo().times;
		this.exp=this._mgr.getInfo().exp;
		this.freeTimes=this._mgr.getInfo().freeTimes;
		this.txt_reward.innerHTML=CodeMgr.ins.getStringByCode([261162,this.exp]);
		var color="";
		this.maxTimes=this._mgr.getmaxtimer(this.roleVO.vipLevel);
		this.cost=this._mgr.getCost(this.maxTimes-this.times);
		this.role_coin=this.roleVO.taiYu;
		this.fTimeFree();
		if(this.times==0){
			this.btn_yq.disabled=true;
			color="#ff4141";
			}else{
			this.btn_yq.disabled=false;
			color="#4dff55";
		}
		if(this.cost > this.role_coin){
			this.btn_yq.disabled=true;
			this.txt_cost.color="#ff4141";
			}else{
			this.btn_yq.disabled=false;
			this.txt_cost.color="#4dff55";
		}
		this.txt_times.innerHTML=CodeMgr.ins.getStringByCode([6016,color,this.times,this.maxTimes]);
	}

	__proto.svipTiaoZhuan=function(){
		Mgr.kaiFuHDMgr.getSkip();
	}

	/**第一次免费*/
	__proto.fTimeFree=function(){
		var index=this.maxTimes-this.times;
		this.btn_yq.dispose();
		CornerUtil.removeCorner(this.btn_yq);
		if(this.freeTimes>0){
			this.box_cost.visible=false;
			this.txt_freetime.visible=true;
			this.txt_freetime.text="月卡免费"
			CornerUtil.addCorner(this.btn_yq);
		}
		else if(index==0&&this.freeTimes<=0){
			this.box_cost.visible=false;
			this.txt_freetime.visible=true;
			this.txt_freetime.text="今日免费"
			CornerUtil.addCorner(this.btn_yq);
			this.btn_yq.showAni("anniu_01",-4,-2);
		}
		else{
			this.box_cost.visible=true;
			this.txt_freetime.visible=false;
			this.txt_cost.text=this.cost.toString();
		}
	}

	__proto.dispose=function(){
		this.bg.disposeLater();
		this.btn_yq.dispose();
	}

	return ZhuanJinTongView;
})(ZhuanJinTongUI)


