//class view.modules.comp.ResloveItem extends ui.modules.comp.ResloveItemUI
var ResloveItem=(function(_super){
	function ResloveItem(){
		this.equipVo=null;
		ResloveItem.__super.call(this);
		this.on("click",this,this.onClick);
	}

	__class(ResloveItem,'view.modules.comp.ResloveItem',_super);
	var __proto=ResloveItem.prototype;
	__proto.onClick=function(){
		if(!this.equipVo)return;
		if(Mgr.equipCompMgr.resloveEquipDic.get(this.equipVo.guid)){
			Mgr.equipCompMgr.resloveEquipDic.remove(this.equipVo.guid);
			this.img_choose.visible=false;
			}else{
			if(Mgr.equipCompMgr.resloveEquipDic.keys.length >=8){
				return;
			}
			Mgr.equipCompMgr.resloveEquipDic.set(this.equipVo.guid,this.equipVo);
			this.img_choose.visible=true;
		}
		EventCenter.instance.event("updata_equip_reslove_list");
	}

	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		if(value){
			this.equipVo=value;
			this.equipVo.isShowTip=true;
			this.item_reslove.visible=true;
			this.item_reslove.dataSource=this.equipVo;
			if(Mgr.equipCompMgr.resloveEquipDic.get(this.equipVo.guid)){
				this.img_choose.visible=true;
			}
			else{
				this.img_choose.visible=false;
			}
		}
		else{
			this.equipVo=null;
			this.img_choose.visible=false;
			this.item_reslove.visible=false;
		}
	});

	return ResloveItem;
})(ResloveItemUI)


