//class view.modules.kaixueqingdian.QingDianCostItem extends ui.modules.kaixueqingdian.QingDianCostItemUI
var QingDianCostItem=(function(_super){
	function QingDianCostItem(){
		this.isEnough=false;
		this.cfg=null;
		this.itemVO=null;
		QingDianCostItem.__super.call(this);
		this.img_icon.on("click",this,this.onClick);
	}

	__class(QingDianCostItem,'view.modules.kaixueqingdian.QingDianCostItem',_super);
	var __proto=QingDianCostItem.prototype;
	__proto.onClick=function(){
		if(this.isEnough){
			Mgr.kaiXueQingDianAction.sendUseProp(Mgr.kaiXueQingDianMgr.curActivityType,parseInt(this.cfg.type));
			}else{
			Mgr.kaiXueQingDianMgr.openBuyCostPanel(this.cfg);
		}
	}

	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		if(!value){
			return;
		}
		this.cfg=(value).getCfgData();
		this.txt_add.text="增加："+this.cfg.num+"点";
		if((this.cfg.costitem instanceof Array)){
			var costStr=this.cfg.costitem[0].split(":")[0];
			}else{
			costStr=this.cfg.costitem.split(":")[0];
		};
		var costNum=Mgr.kaiXueQingDianMgr.getConsumeNum(Mgr.kaiXueQingDianMgr.curActivityType);
		this.itemVO=Mgr.item.getItemVO(costStr);
		this.iconItem.dataSource=this.itemVO;
		var bagNum=Mgr.bag.getBagMatCount(costStr);
		this.txt_cost.text=bagNum+"/"+costNum;
		if(bagNum >=costNum){
			CornerUtil.addCorner(this.img_icon);
			this.txt_cost.color="#4dff55";
			this.isEnough=true;
			}else{
			this.txt_cost.color="#ff4141";
			CornerUtil.removeCorner(this.img_icon);
			this.isEnough=false;
		}
		if(Mgr.kaiXueQingDianMgr.curActivityType==106){
			var flag=NewActiveManager.ins.getActiveFlag(106);
			if(flag){
				this.img_icon.skin=PathDefine.getQinDianRes(flag,106+"_"+this.cfg.id);
			}
		}
		else{
			this.img_icon.skin=PathDefine.getQingDianCostSkin(Mgr.kaiXueQingDianMgr.curActivityType+"_"+this.cfg.id);
		}
	});

	return QingDianCostItem;
})(QingDianCostItemUI)


