	__proto.onXiangQian=function(){
		var isTiHuan=false;
		if(!this.curGemArr)
			return;
		var lastGemGuid=NaN;
		var gemUseDic={};
		for (var i=0;i < 5;i++){
			var tipGemDataArr=Mgr.gemMgr.getBagGemArr(this.curGemArr[i].gemType);
			var arr=[];
			for (var j=0;j < tipGemDataArr.length;j++){
				var b=tipGemDataArr[j];
				var g=new GemSortVO;
				g.index=j;
				g.bagItemVo=b;
				arr.push(g);
			}
			if(this.curGemArr[i].state==1 || this.curGemArr[i].state==2){
				if(arr.length > 0){
					var gemBagVo=arr[0].bagItemVo;
					if(gemUseDic[gemBagVo.guid]){
						if(arr.length > 1){
							var bagGemFv=Mgr.item.getGemFV([arr[1].bagItemVo.templateId]);
							var curGemFv=Mgr.item.getGemFV([this.curGemArr[i].templateId]);
							if(bagGemFv > curGemFv){
								isTiHuan=true;
								Mgr.gemProMgr.sendSetupGem(arr[1].bagItemVo.guid,parseInt(this.curGemArr[i].part),parseInt(this.curGemArr[i].slot));
							}
						}
						}else{
						isTiHuan=true;
						Mgr.gemProMgr.sendSetupGem(gemBagVo.guid,parseInt(this.curGemArr[i].part),parseInt(this.curGemArr[i].slot));
						if(gemBagVo.count==1){
							gemUseDic[gemBagVo.guid]=gemBagVo;
						}
					}
				}
			}
		}
		if(!isTiHuan)
			Mgr.prompt.optionPrompt("暂无可镶嵌宝石");
	}

	__proto.onShengJi=function(){
		var isShengJi=false;
		for (var i=0;i < 5;i++){
			var partGemVO=this.curGemArr[i]
			if(partGemVO.state==3){
				var gemCfgMsg=Model.equipGem.getGemCofById(this.curGemArr[i].templateId);
				this.onCompoundGem(this.curGemArr[i],gemCfgMsg);
				isShengJi=true;
			}
		}
		if(!isShengJi)
			Mgr.prompt.optionPrompt("暂无可升级宝石");
	}

