var EquipTabItemGemView=(function(_super){
	function EquipTabItemGemView(){
		this.GEM_SLOT_NUM=5;
		this.isShow=false;
		/**
		*ui数组
		*/
		this.gemSpArr=null;
		/**
		*宝石表
		*/
		this.gemCfg=null;
		EquipTabItemGemView.__super.call(this);
		this.gemCfg=CfgManager.getTableCfg("BaoShi");
		this.img_bg.on("click",this,this.skipXunBao);
		this.gemSpArr=[this.gemItem0,this.gemItem1,this.gemItem2,this.gemItem3,this.gemItem4];
	}

	__class(EquipTabItemGemView,'view.modules.equip.EquipTabItemGemView',_super);
	var __proto=EquipTabItemGemView.prototype;
	__proto.skipXunBao=function(){
		if(Mgr.guide.isOpen("jipingxunbao_xunbao",true)){
			UIMgr.ins.openSecView(XunBaoHallView,2,0,0);
		}
	}

	/**打开面板后和选择单元格后调用的方法*/
	__proto.setGemData=function(gemArr){
		var leng=this.gemSpArr.length;
		for (var i=0;i < leng;i++){
			var partGemVO=gemArr[i];
			if (partGemVO==null){
				CornerUtil.removeCorner(this.gemSpArr[i]);
				console.log("当前宝石孔"+(i+1)+"无数据");
				continue ;
			}
			this.gemSpArr[i].mc_nameBg.visible=false;
			this.gemSpArr[i].txt_gemType.visible=false;
			this.gemSpArr[i].dataSource=partGemVO;
		}
	}

	// }
	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		if(!value){
			this.visible=false;
			return;
		}
		this.visible=true;
		this._dataSource=value;
		this.txt_state.visible=false;
		this.txt_gem.visible=false;
		if (value !=null && value.cfgItem){
			var evo=value;
			var partPos=evo.partPos;
			var gemArr=value.gemArr;
			if(!gemArr){
				return
			}
			this.setGemData(gemArr);
			evo.isShowTip=true;
			this.iconEquipView.dataSource=evo;
			this.txt_name.text=evo.cfgItem.name;
			var state;
			var btnState=0;
			var gemLv=0;
			for (var j=0;j < this.GEM_SLOT_NUM;j++){
				if(!gemArr[j])continue ;
				if(!gemArr[j].state){
					gemArr[j]=Mgr.gemMgr.createGemVO(gemArr[j],Mgr.equip.curModel);
				};
				var partGemVO1=gemArr[j];
				if(partGemVO1.state==1 || partGemVO1.state==2){
					btnState=1;
					state="可镶嵌";
				}
				if(partGemVO1.state==3){
					if(btnState !=1)
						state="可升级";
				}
				if(partGemVO1.templateId){
					gemLv+=parseInt(Model.equipGem.getGemCofById(partGemVO1.templateId).level);
				}
			}
			if(gemLv){
				this.txt_gem.text="+"+gemLv;
				this.txt_gem.visible=true;
			};
			var redVo=Mgr.red.getValue("dzbaoshi");
			if(redVo.getCornerState(Mgr.subPlayer.curGuid+"_"+value.partPos+"dzbaoshi")){
				CornerUtil.addCorner(this);
				this.txt_state.visible=true;
				if(!state)state="可镶嵌";
			}
			else{
				CornerUtil.removeCorner(this);
				this.txt_state.visible=false;
			}
			}else{
			this.partImg.skin=PathDefine.getPartSlotUrl(value.partPos);
			this.iconEquipView.visible=false;
			CornerUtil.removeCorner(this);
			if(value.partPos==7 || value.partPos==8){
				this.img_bg.visible=true;
				this.img_bg.skin=PathDefine.PART_SLOT_URL+"part_"+value.partPos+".png";
				this.iconEquipView.visible=true;
				var obj={};
				obj.part=value.partPos;
				this.iconEquipView.dataSource=obj;
				this.img_bg.visible=false;
			}
		}
		if(this.isShow){
			CornerUtil.removeCorner(this);
			this.txt_state.visible=false;
		}
	});

	return EquipTabItemGemView;
})(EquipTabItemGemUI)


