		EventCenter.instance.on("UpdateParamValueOpraEvent",this,this.showXFNum);
		EventCenter.instance.on("LeiJiXFCBRed",this,this.updateRed);
		EventCenter.instance.on("LeiJiXFKFRed",this,this.updateRed);
		EventCenter.instance.on("LeiJiXiaoFeiWeekRed",this,this.updateRed);
