		EventCenter.instance.off("GetTargetRewardOpraEvent",this,this.flush);
		EventCenter.instance.off("UpDataTargetInfoOpraEvent",this,this.flush);
		EventCenter.instance.off("UpdateParamValueOpraEvent",this,this.showXFNum);
		EventCenter.instance.off("LeiJiXFCBRed",this,this.updateRed);
		EventCenter.instance.off("LeiJiXFKFRed",this,this.updateRed);
