var FourteenItem1View=(function(_super){
	function FourteenItem1View(){
		FourteenItem1View.__super.call(this);
	}

	__class(FourteenItem1View,'view.modules.fourteenluxurygifts.FourteenItem1View',_super);
	var __proto=FourteenItem1View.prototype;
	__proto.getDay=function(day){
		var str="";
		var txt_len=Mgr.fourtenMgr.day_txt.length-1;
		if(day > txt_len){
			var a=day-txt_len;
			var b=Mgr.fourtenMgr.day_txt[txt_len];
			str=b+Mgr.fourtenMgr.day_txt[a];
			}else{
			str=Mgr.fourtenMgr.day_txt[day];
		}
		return "第"+str+"天";
	}

	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		if(!value)
			return;
		this._dataSource=value;
		var obj=value.configData;
		this.labe_name.changeText(obj.propA);
		this.labe_day.changeText(this.getDay(obj.number));
		var djArr=obj.propB.split(";");
		var sex=0;
		if(djArr[1] && NetMgr.ins().roleVO.job=="A"){
			sex=1;
		};
		var vo=Mgr.item.getItemVO(djArr[sex]);
		this.dj_icon.dataSource=vo;
		this.labe_name.changeText(vo.goodName);
		this.mc_ylq.visible=false;
		var arr=Mgr.fourtenMgr.rewardListory;
		var len=arr.length;
		CornerUtil.removeCorner(this);
		if(len > 0){
			var rewLis;
			for (var i=0;i < len;i++){
				rewLis=arr[i];
				if(rewLis.id==obj.number){
					break ;
				}
			}
			if(rewLis && rewLis.id==parseInt(obj.number)&& Mgr.chaoZhiTeDianMgr.isBuyYk && rewLis.tequanIsGet){
				this.mc_ylq.visible=true;
				}else if(Mgr.fourtenMgr.day >=obj.number){
				CornerUtil.addCorner(this);
			}
			}else{
			var arrId=Mgr.fourtenMgr.rewardListoryId;
			if(arrId.indexOf(parseInt(obj.number))!=-1){
				this.mc_ylq.visible=true;
				}else if(arrId.indexOf(parseInt(obj.number))==-1 && Mgr.fourtenMgr.day >=obj.number){
				CornerUtil.addCorner(this);
			}
		}
	});

	return FourteenItem1View;
})(FourteenItem1UI)


