	__proto.dispose=function(){
		Mgr.mdActMgr.exit(207,0,Browser.now(),Mgr.copy.openType);
		Mgr.sinImgMgr.add(this.bg);
		Laya.loader.clearRes("modules/guanka/renderBg.png");
		EventCenter.instance.off(view.modules.guanka.CMGuanKa.CMGQ_SCROLL,this,this.onSaoDanBack);
		EventCenter.instance.off("DuoBeiTuBiao",this,this.refreshStart);
		EventCenter.instance.off("GK_TIAOZHAN",this,this.updateListData);
		if(this.ani){
			this.ani.dispose();
			this.ani=null;
		}
		if(this.ani_item){
			this.ani_item.dispose();
			this.ani_item=null;
		}
	}

	__proto.update=function(){}
	// list_chapter.array=mgr.cfgZJ;
	__proto.onListSelect=function(index){
		this.curIndex=index;
		if(this.curIndex==-1)
			return;
	}

