//class view.modules.guildBoss.GuildBossView extends ui.modules.guildBoss.GuildBossUI
var GuildBossView=(function(_super){
	function GuildBossView(){
		/**挑战奖励*/
		this.display=null;
		this.curCfg=null;
		this.thisMgr=null;
		this.curSelect=0;
		this.resModel=null;
		GuildBossView.__super.call(this);
	}

	__class(GuildBossView,'view.modules.guildBoss.GuildBossView',_super);
	var __proto=GuildBossView.prototype;
	__proto.initialize=function(){
		laya.ui.Component.prototype.initialize.call(this);
		this.thisMgr=Mgr.guildBoss;
		this.lblNun.style.align="center";
		this.paiMingJingLi.on("click",this,this.onJingLi);
		this.btn_start.on("click",this,this.onClickStart);
		EventCenter.instance.on("ENTER_GUILD_BOSS_STAGESC",this,this.close);
		EventCenter.instance.on("gd_boo_rewad",this,this.onFlush);
		this.setupHelpPanel();
	}

	__proto.setupHelpPanel=function(){
		laya.ui.Component.prototype.initialize.call(this);
		this.contentLbel.style.leading=10;
		this.contentLbel.style.fontSize=24;
		this.contentLbel.style.font="SimHei"
		this.panel.vScrollBarSkin=null;
		this.panel.vScrollBar.elasticBackTime=200;
		this.panel.vScrollBar.elasticDistance=200;
	}

	__proto.close=function(){
		UIMgr.ins.closeView(GuildMainHall,true);
	}

	__proto.onClickStart=function(){
		if(this.curCfg){
			Mgr.guildBossPro.sendYaoQing();
			Mgr.copyPro.sendEnterGuildBossCS(this.curCfg.mainId);
			Mgr.guildBossPro.sendGuWuInfo();
			this.thisMgr.curBossId=this.curCfg.mainId;
			UIMgr.ins.closeView(GuildMainHall,true);
		}
	}

	__proto.onJingLi=function(){
		var guildBossJiangLiView=UIMgr.ins.openView(GuildBossJiangLiView,2);
	}

	__proto.onListSelect=function(){
		var monsterId=this.curCfg.monsterId.split(":")[1];
		if(!monsterId){
			return;
		}
		this.txtName.text=Model.monster.getMonsterNameById(monsterId);
		if(!this.resModel){
			this.resModel=new UIAni();
			this.addChild(this.resModel);
			this.resModel.pos(377,514);
		};
		var pak=Model.monster.getUrlById(monsterId);
		var url=PathDefine.getBossUIAni(pak);
		this.resModel.setRes(url,1);
	}

	__proto.open=function(){
		if(Mgr.guild.guildLevel > 0){
			this.onFlush();
			EventCenter.instance.on("UPDATE_GUILD_BOSS_PANEL",this,this.onFlush);
			Mgr.guildBossPro.sendGetGuildBossInFoCS();
			this.changeTime();
			if(this.thisMgr.activeTime > Mgr.curTime.serverTimer){
				Laya.timer.loop(1000,this,this.changeTime);
			}
			this.contentLbel.innerHTML=CodeMgr.ins.getStringByCode(230062);
			this.panel.refresh();
		}
	}

	// contentLbel.height=contentLbel.contextHeight;
	__proto.changeTime=function(){
		var time=this.thisMgr.activeTime-Mgr.curTime.serverTimer;
		var tipStr="";
		if(time <=0){
			tipStr="<font color='#4dff55'>活动开启中</font>";
			this.btn_start.disabled=false;
			}else{
			this.btn_start.disabled=true;
			tipStr="<font color='#ff4141'>活动开启倒计时："+CommonUtil.formatDate(time,27,false)+"</font>";
		}
		this.lblNun.innerHTML=tipStr;
	}

	__proto.dispose=function(){
		EventCenter.instance.off("UPDATE_GUILD_BOSS_PANEL",this,this.onFlush);
		if(this.resModel){
			this.resModel.dispose();
			this.resModel=null;
		}
		Laya.timer.clear(this,this.changeTime);
		Mgr.sinImgMgr.add(this.bg);
	}

	__proto.onFlush=function(){
		if(this.thisMgr.servGuildBossInfo){
			var selectIndex=this.thisMgr.servGuildBossInfo.mainId > this.thisMgr.bossList.length ? 0 :(this.thisMgr.servGuildBossInfo.mainId-1);
			if(this.thisMgr.servGuildBossInfo.mainId > this.thisMgr.bossList.length){
				this.curCfg=this.thisMgr.getBossCfgByID(this.thisMgr.bossList.length);
				CornerUtil.removeCorner(this.btn_start);
				this.btn_start.label="已通关";
				this.btn_start.disabled=true;
				}else{
				this.curCfg=this.thisMgr.getBossCfgByID(this.thisMgr.servGuildBossInfo.mainId);
				this.btn_start.label="挑战";
			}
		}
		else{
			selectIndex=0;
			this.curCfg=this.thisMgr.bossList[selectIndex];
			CornerUtil.removeCorner(this.btn_start);
		}
		this.updateReward();
		this.onListSelect();
		if(this.thisMgr.checkBossRed()){
			CornerUtil.addCorner(this.paiMingJingLi);
			}else{
			CornerUtil.removeCorner(this.paiMingJingLi);
		}
	}

	// }
	__proto.updateReward=function(){
		if(!this.display){
			this.display=new ItemDisplayList();
			this.display.y=945;
			this.addChild(this.display);
		}
		this.display.showItems(this.curCfg.reward,5,95,50,1);
		this.display.showHorCenter(this.width);
	}

	return GuildBossView;
})(GuildBossUI)


