//class view.modules.guildBoss.GuWuIconView extends ui.modules.guildBoss.GuWuIconUI
var GuWuIconView=(function(_super){
	function GuWuIconView(){
		this.guildBossAct=null;
		this.guildBoss=null;
		this.harmVal=NaN;
		this.ani=null;
		this.shagnhaiReward=null;
		GuWuIconView.__super.call(this);
		this.name="GuWuIconView";
		GuideTargetMgr.ins.changeGuideView(this);
	}

	__class(GuWuIconView,'view.modules.guildBoss.GuWuIconView',_super);
	var __proto=GuWuIconView.prototype;
	Laya.imps(__proto,{"com.xq.view.modules.guildBoss.IGuWuIconView":true})
	__proto.initialize=function(){
		laya.ui.Component.prototype.initialize.call(this);
		this.btn_guwu1.on("click",this,this.onGuWu1);
		this.btn_guwu2.on("click",this,this.onGuWu2);
		this.btn_guwu3.on("click",this,this.onGuWu3);
		this.dj_zhangshi.on("click",this,this.onShanHaiJL);
		this.guildBossAct=Mgr.guildBossPro;
		this.guildBoss=Mgr.guildBoss;
	}

	__proto.open=function(){}
	/**领取伤害奖励*/
	__proto.onShanHaiJL=function(){
		if(this.guildBoss.harmId !=0){
			this.guildBossAct.sendGetRewardBoss(this.guildBoss.harmId);
			}else{
			Mgr.prompt.optionPrompt("奖励已领完");
		}
	}

	__proto.shanHaiTxt=function(){
		var obj=this.guildBoss.getBossRankCfgId(this.guildBoss.harmId);
		this.txt_shanhai.color="#d4e7f9";
		this.txt_ywc.visible=false;
		this.txt_shanhai.visible=false
		if(obj)this.shagnhaiReward=obj.reward;
		if(obj){
			this.harmVal=obj.harmvalue;
			this.txt_shanhai.visible=true;
			this.djReward(false);
			this.shanHaiJiangLI();
			this.txt_shanhai.text=CommonUtil.numFormat(this.harmVal)+"伤害";
			}else{
			var object=this.guildBoss.getBossRankLast();
			this.shagnhaiReward=object.reward;
			this.djReward(false);
			this.txt_ywc.visible=true;
			this.ani.visible=false;
		}
	}

	__proto.shanHaiJiangLI=function(){
		if(this.guildBoss.harmVal >=this.harmVal && this.guildBoss.harmId !=0){
			this.txt_shanhai.visible=true;
			this.txt_shanhai.color="#4dff55";
			this.txt_shanhai.text=CommonUtil.numFormat(this.harmVal)+"伤害";
			this.djReward(true);
		}
	}

	__proto.djReward=function(boo){
		if(this.shagnhaiReward){
			var djArr=this.shagnhaiReward.split(":");
			var vo=Mgr.item.getItemVO(djArr[0]);
			if(djArr[1])vo.count=djArr[1];
			if(boo){
				vo.isShowTip=true;
				this.ani.visible=true;
				}else{
				vo.isShowTip=false;
				this.ani.visible=false;
			}
			this.dj_zhangshi.dataSource=vo;
		}
	}

	__proto.onGuWu1=function(){
		UIMgr.ins.openView(GuildBossLxGuWuView,2);
	}

	__proto.onGuWu2=function(){
		UIMgr.ins.openView(GuildBossQyGuWuView,2);
	}

	__proto.onGuWu3=function(){
		UIMgr.ins.openView(GuildBossGuWuView,2);
	}

	__proto.fname=function(){
		EventCenter.instance.on("guwugaibian",this,this.fname);
		EventCenter.instance.on("shanghairank",this,this.shanHaiTxt);
		EventCenter.instance.on("shanghaijiangli",this,this.shanHaiJiangLI);
		if(this.ani==null){
			this.ani=new UIAni();
			this.ani.pos(this.dj_zhangshi.x,this.dj_zhangshi.y);
			this.addChild(this.ani);
		}
		this.ani.setRes(PathDefine.EFFECT_UI+"lingqu"+".amt");
		if(this.guildBoss.peopleNum==1){
			this.txt_guwu1.color="#ff4141";
			this.txt_guwu1.text="未激活";
			}else{
			this.txt_guwu1.color="#4dff55";
			this.txt_guwu1.text="已激活";
		}
		this.txt_guwu2.text="攻击+"+this.guildBoss.quanyuanGWJiaCheng+"%";
		this.txt_guwu3.text="攻击+"+this.guildBoss.gerenJiaCheng+"%";
	}

	__proto.dispose=function(){
		if(this.ani){
			this.ani.dispose();
			this.ani=null;
		}
		EventCenter.instance.off("guwugaibian",this,this.fname);
		EventCenter.instance.off("shanghairank",this,this.shanHaiTxt);
		EventCenter.instance.off("shanghaijiangli",this,this.shanHaiJiangLI);
	}

	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		if(!value)return;
		this._dataSource=value;
		this.guildBossAct.sendGuildBossHarmInfoSC();
		this.fname();
	});

	return GuWuIconView;
})(GuWuIconUI)


