var GuanKaRank=(function(_super){
	function GuanKaRank(){
		this.topDisplay=null;
		this.ani=null;
		this.jinRiDaJiangAni=null;
		this.targetAni=null;
		this.voCfg=null;
		this.qmMgr=null;
		GuanKaRank.__super.call(this);
		CommonUtil.listSetScroll(this.rank_list,false);
		this.btn.on("click",this,this.onSkip);
		this.btn_explain.on("click",this,this.openHelp);
		this.btn_rank.on("click",this,this.rankXiangQing);
		this.topDisplay=new ItemDisplayList();
		this.qmMgr=Mgr.quanMinTzMgr;
	}

	__class(GuanKaRank,'view.modules.hancock.GuanKaRank',_super);
	var __proto=GuanKaRank.prototype;
	__proto.onClickDaBiao=function(){
		var jinRiDaJiangInfo=Mgr.hancock.getJinRiDaJiangInfo();
		Mgr.opeAct.sendGetActivityReward(185,parseInt(jinRiDaJiangInfo.id));
	}

	__proto.rankXiangQing=function(){
		if(this.voCfg){
			var rankXiangQing=UIMgr.ins.openView(GuanKaRankTips,2);
			var obj={};
			this.qmMgr.getRankName(parseInt(this.voCfg.type));
			obj["activitId"]=186;
			obj["rankList"]=this.qmMgr.getRankCfg();
			obj["rankName"]=this.qmMgr.strTitleName;
			obj["strName"]=this.qmMgr.strName;
			obj["myRank"]=this.qmMgr.rankInfoSc.rank;
			obj["myStar"]=this.qmMgr.rankInfoSc.todayScore;
			rankXiangQing.dataSource=obj;
		}
	}

	__proto.openHelp=function(){
		HelpView.show(CodeMgr.ins.getStringByCode(261051));
	}

	__proto.onSkip=function(){
		if(this.voCfg)UIMgr.ins.navigateToViewByID(this.voCfg.mediator);
	}

	__proto.open=function(){
		EventCenter.instance.on("tiaozhangrank_info",this,this.init);
		Mgr.rankingPro.c_getRank(186);
		CommonUtil.reloadImg(this.bg2);
	}

	__proto.init=function(){
		var rankCfg=this.qmMgr.getRankCfg();
		this.refreshTime();
		Laya.timer.loop(1000,this,this.refreshTime);
		if(!this.qmMgr.nextRank)
			this.lab0.visible=false;
		this.lab0.text="明日预告排行:"+this.qmMgr.nextRank;
		if(!this.ani){
			this.ani=new UIAni();
			this.sp_topAni.addChild(this.ani);
		};
		var objCfg=rankCfg[0];
		if(objCfg){
			this.voCfg=objCfg.cfgData;
			EventCenter.instance.event(GameEvent.UPDATE_FRAME_TITLE,this.voCfg.title);
			var resArr=this.voCfg.res.split(";");
			var overmainPos=this.voCfg.overmainPos.split(":");
			if(resArr.length > 1){
				if(NetMgr.ins().roleVO.job=="A"){
					this.ani.setRes(PathDefine.EFFECT_UI+resArr[0]+".amt");
					}else{
					this.ani.setRes(PathDefine.EFFECT_UI+resArr[1]+".amt");
				}
				}else{
				this.ani.setRes(PathDefine.EFFECT_UI+this.voCfg.res+".amt");
			}
			this.ani.pos(parseInt(overmainPos[0]),parseInt(overmainPos[1]));
			this.ani.scale(this.voCfg.oversize,this.voCfg.oversize);
			this.v_addfight.setFight=this.voCfg.powershow;
			var bannerArr=this.voCfg.nameRes.split(";");
			if(bannerArr.length > 1){
				if(NetMgr.ins().roleVO.sex==0){
					this.banner.skin=PathDefine.FeiShengBang+"quanmintiaozhan/banner"+bannerArr[0]+".png";
					}else{
					this.banner.skin=PathDefine.QuanMinChongBang+"quanmintiaozhan/banner"+bannerArr[1]+".png";
				}
				}else{
				this.banner.skin=PathDefine.QuanMinChongBang+"quanmintiaozhan/banner"+bannerArr[0]+".png";
			}
		}
		this.updataLastInfo(this.qmMgr.rankInfoSc);
		this.rank_list.array=rankCfg;
	}

	/**我自己的排名*/
	__proto.updataLastInfo=function(lastInfo){
		this.txt_myStar.text=""+lastInfo.todayScore;
		if(lastInfo.rank > 0){
			this.txt_myRank.text=""+lastInfo.rank;
			}else{
			this.txt_myRank.text="未上榜";
		}
	}

	/**刷新倒计时*/
	__proto.refreshTime=function(){
		var syTime=this.qmMgr.rankEndTime-Mgr.curTime.serverTimer;
		if(syTime>=0){
			this.timeLab.text=CommonUtil.formatDate(syTime,4,false)
			}else{
			this.timeLab.text="已结束";
		}
	}

	__proto.dispose=function(){
		EventCenter.instance.off("tiaozhangrank_info",this,this.init);
		Laya.loader.clearRes(this.banner.skin);
		Mgr.sinImgMgr.add(this.bg2);
		Mgr.sinImgMgr.add(this.bg3);
		if(this.ani){
			this.ani.dispose();
			this.ani=null;
		}
		if(this.targetAni){
			this.targetAni.dispose();
			this.targetAni=null;
		}
		this.btn.dispose();
		Laya.timer.clear(this,this.refreshTime);
	}

	return GuanKaRank;
})(GuanKaRankUI)


