				this.html.innerHTML="<font color='#f7f5b2'>你的"+jinJieRi.targetdes+"还差</font><font color='#ffd951'>"+(parseInt(frontPlayer["limit"])-this.mgr.ownStar)+"</font><font color='#f7f5b2'>追上</font><font color='#ffd951'>第"+frontPlayer.rank+"名</font>";
