//class view.modules.jintaibaijiang.ShaChangDianBingItem extends ui.modules.jintaibaijiang.ShaChangDianBingItemUI
var ShaChangDianBingItem=(function(_super){
	function ShaChangDianBingItem(){
		this.roleId=NaN;
		this.player=null;
		ShaChangDianBingItem.__super.call(this);
	}

	__class(ShaChangDianBingItem,'view.modules.jintaibaijiang.ShaChangDianBingItem',_super);
	var __proto=ShaChangDianBingItem.prototype;
	__proto.checkChallenge=function(){
		Mgr.inoutMap.check(Handler.create(this,this.clickChallenge));
	}

	__proto.clickChallenge=function(){
		if(Mgr.jintai.getChallegeCount()> 0){
			if(this.roleId==NetMgr.ins().roleVO.guid){
				Mgr.prompt.optionPrompt("无法挑战自己");
				}else{
				Mgr.jintaiPro.sendSINPVP_CS_FIGHTPVP(this.roleId);
			}
			}else{
			Mgr.prompt.optionPrompt("挑战次数不足");
		}
	}

	__proto.gc=function(){
		this.off("click",this,this.checkChallenge);
		if(this.player){
			this.player.dispose();
			this.player=null;
		}
	}

	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		if(!value)return;
		var arenaFighter=value;
		this.txt_name.text=arenaFighter.name;
		this.fightV.setFight=arenaFighter.battleValue;
		this.txt_rank.text="第"+arenaFighter.rank+"名";
		this.roleId=arenaFighter.roleId;
		var curRole=new RoleVO();
		curRole.roleHuanHuaId=arenaFighter.huanhuaRole;
		curRole.job=arenaFighter.gender==0 ? "A":"C";
		curRole.name=arenaFighter.name;
		curRole.guid=arenaFighter.roleId;
		if(arenaFighter.weapon){
			curRole.wuQiHuanHuaId=arenaFighter.weapon;
		}
		curRole.wingHuanHuaId=arenaFighter.wing;
		if(!this.player){
			this.player=new BigPlayer();
			this.sp_player.addChild(this.player);
		}
		this.player.createPlayer(curRole);
		this.player.scale(0.6,0.6);
		if(this.roleId==NetMgr.ins().roleVO.guid){
			this.btn_tz.disabled=true;
			this.txt_name.color="#4dff55";
			}else{
			this.btn_tz.disabled=false;
			this.txt_name.color="#ffffff";
		}
		this.on("click",this,this.checkChallenge);
	});

	return ShaChangDianBingItem;
})(ShaChangDianBingItemUI)


