var JinDiBossPaiMaiInfoView=(function(_super){
	function JinDiBossPaiMaiInfoView(){
		this.guid=null;
		this.title=["80%奖励","60%奖励","40%奖励","20%奖励","击杀奖励"];
		/**ItemDisplayList*/
		this.rewardList=null;
		this.oldIndex=-2;
		JinDiBossPaiMaiInfoView.__super.call(this);
	}

	__class(JinDiBossPaiMaiInfoView,'view.modules.kuaquBoss.dungeon.JinDiBossPaiMaiInfoView',_super);
	var __proto=JinDiBossPaiMaiInfoView.prototype;
	__proto.initialize=function(){
		laya.ui.Component.prototype.initialize.call(this);
		this.rewardList=new ItemDisplayList();
		this.rewardList.pos(10,44);
		this.boxInfo.addChild(this.rewardList);
		this.boxInfo.visible=false;
		this.imgArrow.visible=false;
	}

	__proto.startListener=function(){
		EventCenter.instance.on("KuaQuBossAwardSelect",this,this.selectHead);
		EventCenter.instance.on("dead",this,this.gc);
	}

	__proto.stopListener=function(){
		EventCenter.instance.off("KuaQuBossAwardSelect",this,this.selectHead);
		EventCenter.instance.off("dead",this,this.gc);
	}

	__proto.open=function(){
		this.startListener();
	}

	__proto.selectHead=function(){
		var index=this.listPro.selectedIndex;
		if(this.oldIndex==index){
			this.gc();
			return;
		}
		this.oldIndex=index;
		if(index !=-1 && this.listPro.array){
			var cfgObj=this.listPro.selectedItem;
			if(!cfgObj)
				return;
			this.updateAward(cfgObj);
			this.imgArrow.x=index *72;
			this.boxInfo.x=this.imgArrow.x+(72-this.boxInfo.width)/ 2;
			this.imgArrow.visible=true;
			this.boxInfo.visible=true;
		}
	}

	__proto.updateAward=function(cfgObj){
		this.labTitle.text=cfgObj.title;
		this.rewardList.showItems(cfgObj.award.split(";"),5,84,84,0.82,true,true);
		var list=this.rewardList.getItems();
		var len=list.length;
		for (var j=0;j < len;j++){
			var iconFactory=list[j];
			if (iconFactory && PaiMaiMgr.ins.isPaiMaiGood(iconFactory.dataSource.templateId)){
				iconFactory.setTab(PathDefine.getBossJinDiQua("_jb"));
			}
		}
		this.imgBg.width=(len < 5 ? 440-84 :440);
		this.imgBg.height=this.rewardList.y+(len <=5 ? 84 :(len % 5 *84))+10;
		this.imgLine.width=this.imgBg.width-4;
		this.boxInfo.width=this.imgBg.width;
	}

	__proto.clearList=function(){
		var arr=this.listPro.cells;
		var len=arr.length;
		for(var i=0;i<len;i++){
			arr[i]&&arr[i].gc();
		}
	}

	__proto.gc=function(){
		this.oldIndex=-2;
		this.listPro.selectedIndex=-1;
		this.boxInfo.visible=false;
		this.imgArrow.visible=false;
	}

	__proto.dispose=function(){
		this.stopListener();
		this.clearList();
		this.gc();
	}

	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		if(!value)return;
		this._dataSource=value;
		this.guid=value;
		var cfg=KuaQuBossMgr.ins.getBossCfgById(this.guid);
		if(!cfg)return;
		var awardlist=[ cfg.eightyshow,cfg.sixtyshow,cfg.fortyshow,cfg.twentyshow,cfg.jishashow1];
		var list=[];
		var len=awardlist.length;
		for(var i=0;i < len;i++){
			var obj=new Object();
			obj.title=this.title[i];
			obj.award=awardlist[i];
			obj.index=i;
			list.push(obj);
		}
		this.listPro.array=list;
	});

	return JinDiBossPaiMaiInfoView;
})(JinDiBossPaiMaiInfoViewUI)


