var HancockRankItem=(function(_super){
	function HancockRankItem(){
		HancockRankItem.__super.call(this);
		this.v_rank.type=1;
		this.img_pro.visible=true;
	}

	__class(HancockRankItem,'view.modules.hancock.HancockRankItem',_super);
	var __proto=HancockRankItem.prototype;
	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		if(!value)return;
		this.img_pro.width=0;
		var rank=0;
		if(Mgr.hancock.rankState==2){
			rank=value;
			this.txt_layer.text="无";
			this.txt_name.text="无";
		}
		else if(Mgr.hancock.rankState==0){
			rank=value.rank;
			if(value.roleName){
				this.txt_layer.text=CommonUtil.numFormat((value.rankValue),1);
				var w=(value.rankValue/Mgr.hancock.previousMaxValue)*684;
				w=isNaN(w)?0:w;
				this.img_pro.width=w;
				if(!value.rankValue){
					this.txt_layer.text="战力更新中";
				}
				this.txt_name.text=value.roleName;
				this.txt_layer.color="#d4e7f9";
				this.txt_name.color="#d4e7f9";
			}
			else{
				this.txt_name.text="虚位以待";
				this.txt_layer.text="无";
				this.txt_layer.color="#818181";
				this.txt_name.color="#818181";
			}
		}
		else{
			rank=value.rank;
			if(value.roleName){
				this.txt_layer.text=CommonUtil.numFormat((value.levelOrZhanli),1);
				w=(value.levelOrZhanli/Mgr.hancock.maxValue)*684;
				w=isNaN(w)?0:w;
				this.img_pro.width=w;
				if(!value.levelOrZhanli){
					this.txt_layer.text="战力更新中";
				}
				this.txt_name.text=value.roleName;
				this.txt_layer.color="#d4e7f9";
				this.txt_name.color="#d4e7f9";
			}
			else{
				this.txt_layer.text=CommonUtil.numFormat((parseInt(value["limit"])),1)+"上榜";
				if(!parseInt(value["limit"])){
					this.txt_layer.text="战力更新中";
				}
				this.txt_name.text="虚位以待";
				this.txt_layer.color="#818181";
				this.txt_name.color="#818181";
			}
		}
		this.v_rank.rank=rank;
	});

	return HancockRankItem;
})(CommonRankItemUI)


