		this.txt_optime.color=stat==3?"#ff4141":"#4dff55";
		this.imgName.skin=PathDefine.MeiRiHuoDong+this._cof.res+".png";
		this.img_double.visible=this._cof.type==2;
		var rewards=this._cof.jiangli.split(";");
