var ZhuZhanRank=(function(_super){
	function ZhuZhanRank(){
		/**人物模型*/
		this.bigPlayer=null;
		this.rankType=106;
		ZhuZhanRank.__super.call(this);
		this.btn_mobai.on("click",this,this.onClickMoBai);
		this.btn_mobai.label="膜拜";
		CommonUtil.listSetScroll(this.list,false);
	}

	__class(ZhuZhanRank,'view.modules.ranKing.ZhuZhanRank',_super);
	var __proto=ZhuZhanRank.prototype;
	__proto.open=function(){
		EventCenter.instance.on("RANKINGLIST_ONE",this,this.refreshListData);
		Mgr.rankingPro.sendGetRankInfoCS(106);
		EventCenter.instance.on("RankRed",this,this.refreshPanelRed);
		Mgr.rankingPro.sendGetMoBaiInfo();
	}

	__proto.onClickMoBai=function(){
		if(Mgr.rankingPro.moBaiDic && Mgr.rankingPro.moBaiDic.get(this.rankType).mobaiState){
			Mgr.prompt.optionPrompt("今日可膜拜次数已用完");
			}else{
			Mgr.rankingPro.sendMoBai(this.rankType);
		}
	}

	__proto.refreshListData=function(vo){
		var arr=[];
		var len=vo.rankInfoLists.length;
		for (var i=0;i < 9;i++){
			var isRank=false;
			for (var j=0;j < len;j++){
				var rank=vo.rankInfoLists[j];
				if(rank.rank==i+2){
					arr.push(rank);
					isRank=true;
					break ;
				}
			}
			if(!isRank){
				arr.push(i+2);
			}
		}
		this.list.array=arr;
		if(vo.rankInfoLists[0] && vo.rankInfoLists[0].rank==1){
			var rankVo=vo.rankInfoLists[0].rankVo;
			this.zhuZhanView.dataSource=vo.rankInfoLists[0];
			}else{
			this.zhuZhanView.dataSource=1;
		};
		var myRank=vo.selfInfo;
		if(myRank.rank==0){
			this.txt_rank.text="未上榜";
			}else{
			this.txt_rank.text=myRank.rank+"";
		}
		if(myRank.rankVo){
			this.txt_foght.text=myRank.rankVo.powerValue+"";
			}else{
			this.txt_foght.text="0";
		};
		var curCfg=Mgr.rankingPro.rankConfig.getItemByField("type",vo.rankType+"");
		this.txt_gold.text=curCfg.mobai.split(":")[1];
	}

	__proto.refreshPanelRed=function(){
		Mgr.rankingPro.sendGetRankInfoCS(106);
		if(Mgr.rankingPro.moBaiDic){
			this.btn_mobai.disabled=Mgr.rankingPro.moBaiDic.get(106).mobaiState;
		}
		if(this.btn_mobai.disabled){
			CornerUtil.removeCorner(this.btn_mobai);
			}else{
			CornerUtil.addCorner(this.btn_mobai);
		}
	}

	__proto.dispose=function(){
		Mgr.sinImgMgr.add(this.bg);
		this.zhuZhanView.dispose();
		EventCenter.instance.off("RankRed",this,this.refreshPanelRed);
		EventCenter.instance.off("RANKINGLIST_ONE",this,this.refreshListData);
	}

	return ZhuZhanRank;
})(ZhuZhanRankUI)


