		if (this.bigPlayer){
			this.bigPlayer.dispose();
			this.bigPlayer=null;
		}
		if(this.player){
			this.player.dispose();
			this.player=null;
		}
		this.naviTab.selectedIndex=-1;
		this.naviTab.offEvent(RedTypeEnum.RoleOneMenuRed);
		EventCenter.instance.off("ROLE_EQUIP_LIST_UPDATED",this,this.onEquipDataUpdate);
		EventCenter.instance.off("ROLE_EQUIP_EXCHANGE_UPDATED" ,this,this.onEquipDataUpdate);
		EventCenter.instance.off("FIGHT_PROPERTY_CHANGE",this,this.onDisplay);
