	__proto.updateLimitCount=function(_ele){
		this.btnBuy.dispose();
		this.btnBuy.labelColors="#2c4857";
		CornerUtil.removeCorner(this.btnBuy);
		if(!_ele)return;
		var cfg=_ele.getCfgData();
		var limitType=cfg.countLimitType?parseInt(cfg.countLimitType):0;
		var max=cfg.maxCount?parseInt(cfg.maxCount):0;
		var desc=this._buyCount+"/"+max;
		switch(limitType){
			case 0:
				this.xiangou.text="";
				break ;
			case 1:
				this.xiangou.text="每日限购："+desc;
				break ;
			case 2:
				this.xiangou.text="每周限购："+desc;
				break ;
			case 3:
				this.xiangou.text="永久限购："+desc;
				break ;
			}
		if(limitType>0 && this._buyCount>=max){
			this.btnBuy.gray=true;
			this.btnBuy.disabled=true;
			if(cfg.money==0){
				this.btnBuy.label="已领取"
			}
			else{
				this.btnBuy.label="已购";
			}
		}
		else{
			this.btnBuy.gray=false;
			this.btnBuy.disabled=false;
			if(cfg.money==0){
				CornerUtil.addCorner(this.btnBuy);
				this.btnBuy.label="免费领取";
				this.btnBuy.labelColors="#794e2e"
				this.btnBuy.showAni("anniu_01",-4,-2);
			}
			else{
				this.btnBuy.label="购买";
			}
		}
	}

