	__proto.onClosed=function(){
		var arr=this.list_tab.cells;
		var len=arr.length;
		for(var i=0;i< len;i++){
			var render=arr[i];
			render && render.dispose();
		}
		Laya.loader.clearRes("modules/vip/cz_1.png");
		Laya.loader.clearRes("modules/vip/cz_shouchong.png");
		Laya.loader.clearRes("modules/vip/cz_yuanbao.png");
	}

