//class view.modules.vip.VipStore extends ui.modules.vip.VipStoreUI
var VipStore=(function(_super){
	function VipStore(){
		VipStore.__super.call(this);
		this.setupList();
	}

	__class(VipStore,'view.modules.vip.VipStore',_super);
	var __proto=VipStore.prototype;
	__proto.setupList=function(){
		this.list_vip.itemRender=VipStoreRender;
		CommonUtil.listSetScroll(this.list_vip,false);
		this.list_vip.array=null;
	}

	__proto.open=function(){
		EventCenter.instance.on("updata_vip_shop",this,this.updataShopList);
		EventCenter.instance.on("DUMMY_ITEM_INFO_UDDATE",this,this.updateMoney);
		Mgr.vip.sendVipShopInfo();
		this.updateMoney();
	}

	__proto.updataShopList=function(vipShopInfo){
		if(this.list_vip.array&&this.list_vip.array.length!=0){
			this.list_vip.refresh();
		}
		else{
			this.list_vip.array=vipShopInfo.sort(this.compare);
			this.list_vip.tweenTo(this.setSelect(this.list_vip.array));
		}
	}

	__proto.setSelect=function(arr){
		var index=0;
		if(Mgr.store.showEffTemplateId){
			var len=arr.length;
			for (var i=0;i < arr.length;i++){
				if(arr[i].rewards[0]==Mgr.store.showEffTemplateId){
					index=i;
					break
				}
			}
		}
		return index;
	}

	__proto.dispose=function(){
		EventCenter.instance.off("updata_vip_shop",this,this.updataShopList);
		var ary=this.list_vip.cells;
		var len=ary.length
		for (var i=0;i < len;i++){
			var it=ary [i];
			if(it)
				it.dispose();
		}
		this.list_vip.array=null;
	}

	__proto.updateMoney=function(){
		this.img_coin.skin=PathDefine.getMoneyIcon(2);
		this.txt_have.text=Mgr.moneyMgr.moneyName[2]+":"+Mgr.moneyMgr.getMoneyByType(2);
		this.hbox.refresh();
		this.hbox.x=750-this.hbox.width-40;
	}

	__proto.compare=function(vo1,vo2){
		if(vo1.getReward > vo2.getReward){
			return 1;
		}
		else if(vo1.getReward < vo2.getReward){
			return-1;
		}
		return 0;
	}

	return VipStore;
})(VipStoreUI)


