//class view.modules.waiXianActive.WaiXianItem extends ui.modules.waixianActive.WaiXianItemUI
var WaiXianItem=(function(_super){
	function WaiXianItem(){
		WaiXianItem.__super.call(this);
	}

	__class(WaiXianItem,'view.modules.waiXianActive.WaiXianItem',_super);
	var __proto=WaiXianItem.prototype;
	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		if(!value)return;
		var rewardObj=value;
		var arr=rewardObj.reward.split(";");
		if(arr.length > 1){
			if(NetMgr.ins().roleVO.sex==0){
				var rewardStr=arr[0].split(":")[0];
				}else{
				rewardStr=arr[1].split(":")[0];
			}
		}
		else{
			rewardStr=rewardObj.reward.split(":")[0];
		};
		var huanhuaCfg=Mgr.szMgr.getHuanHuaCfg(rewardStr);
		if(huanhuaCfg){
			this.img_head.skin=PathDefine.huanHua+"a"+huanhuaCfg.huanhuaid+".png";
		}
		if(Mgr.waiXianActiveMgr.curType==154){
			var txt=CommonUtil.getNum(parseInt(rewardObj.taskId));
			this.font_day.text="第"+txt+"天";
			}else{
			if(huanhuaCfg){
				this.img_head.skin=PathDefine.getWaiXianActive("kaiFuHaoLi/head_"+rewardObj.taskId);
				this.img_head.pos(26,10);
				this.font_day.text=huanhuaCfg.name;
			}
		}
		this.img_yiLingQu.visible=false;
		CornerUtil.removeCorner(this);
		var state=Mgr.waiXianActiveMgr.getCurDayRewardState(Mgr.waiXianActiveMgr.curType,parseInt(rewardObj.taskId));
		if(state==1){
			CornerUtil.addCorner(this);
			}else if(state==2){
			this.img_yiLingQu.visible=true;
		}
	});

	return WaiXianItem;
})(WaiXianItemUI)


