//class view.modules.waiXianActive.WaiXianTaskItem extends ui.modules.waixianActive.WaiXianTaskItemUI
var WaiXianTaskItem=(function(_super){
	function WaiXianTaskItem(){
		WaiXianTaskItem.__super.call(this);
	}

	__class(WaiXianTaskItem,'view.modules.waiXianActive.WaiXianTaskItem',_super);
	var __proto=WaiXianTaskItem.prototype;
	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		if(!value)return;
		var cfg=value.getCfgData();
		this.txt_des.text=cfg.des;
		var pro=Mgr.waiXianActiveMgr.getSerTaskInfoById(parseInt(cfg.taskId),parseInt(cfg.id));
		var tp=pro > 1000000? CommonUtil.numFormat(pro):pro.toString();
		var tp2=parseInt(cfg.target)> 1000000? CommonUtil.numFormat(parseInt(cfg.target)):cfg.target;
		this.txt_pro.text="("+tp+"/"+tp2+")";
		if(pro >=parseInt(cfg.target)){
			this.txt_pro.color="#4dff55";
			}else{
			this.txt_pro.color="#ff2424";
		}
	});

	return WaiXianTaskItem;
})(WaiXianTaskItemUI)


