		this.dispImg();
		this.ar_img=[];
		this.arr_dj=[];
		this.arr_dj=this.mgr.getDjItenArr(this.mgr.version);
		var len=this.arr_dj.length;
		for (var i=0;i < len;i++){
			var itemArr=[];
			var djItemArr=this.arr_dj[i].item.split(";");
			itemArr=djItemArr[0].split(":");
			if(djItemArr.length > 1){
				if(NetMgr.ins().roleVO.job=="C"){
					itemArr=djItemArr[1].split(":");
				}
			};
			var vo=Mgr.item.getItemVO(itemArr[0],0,itemArr[1]);
			this["dj_"+(i+1)].dataSource=vo;
			if(this.mgr.rewardList[i].isGain){
				this.yinLingQu(this["dj_"+(i+1)]);
			}
		};
		var djItem=this.mgr.jdItemConst.split(":");
		var needItemVO=Mgr.item.getItemVO(djItem[0]);
		this.dj_xiaohao.dataSource=needItemVO;
		var djCount=Mgr.bag.getBagMatCount(djItem[0]);
		var xiaoHaoDJ=djItem[1];
		var _color="#ff4141";
		this.isItem=false;
		CornerUtil.removeCorner(this.btn_xunbao);
		if(djCount >=xiaoHaoDJ && !this.mgr.shiFouChouWan()){
			this.isItem=true;
			_color="#4dff55";
			CornerUtil.addCorner(this.btn_xunbao);
		}
		this.txt_djSl.color=_color;
		this.txt_djSl.text=djCount+"/"+xiaoHaoDJ;
