var YuanShenProBall=(function(_super){
	function YuanShenProBall(){
		this._barAni=null;
		this._type=0;
		/**当前进度0-1*/
		this._curPro=0;
		this._timer=null;
		this._tweenArr=[];
		this._targetY=0;
		this._duration=0;
		this._ballHight=132;
		this._v=5;
		this._ifTweening=false;
		YuanShenProBall.__super.call(this);
	}

	__class(YuanShenProBall,'view.modules.yuanshen.YuanShenProBall',_super);
	var __proto=YuanShenProBall.prototype;
	__proto.initialize=function(){
		laya.ui.Component.prototype.initialize.call(this);
	}

	__proto.setData=function(curType,curV,maxV){
		this.type=curType;
		var pro=curV/maxV;
		this.value=pro;
		this.proText=curV+"/"+maxV;
	}

	__proto.tweenTo=function(){
		if(this._ifTweening)return;
		if(this._tweenArr&&this._tweenArr.length>0){
			this._targetY=-(this._tweenArr[0]*this._ballHight);
			Laya.timer.loop(20,this,this.onTween);
			this._ifTweening=true;
		}
	}

	__proto.onTween=function(){
		this._barAni.y-=this._v;
		this._barAni.y=Math.max(this._barAni.y,-this._ballHight);
		if(this._barAni.y<=this._targetY){
			this.changeTarget();
			if(this._targetY==0){
				this._barAni.y=0;
				this.changeTarget();
			}
		}
	}

	__proto.changeTarget=function(){
		this._tweenArr.shift();
		if(this._tweenArr.length<=0){
			Laya.timer.clear(this,this.onTween);
			this._ifTweening=false;
			this._barAni.y=this._targetY;
			return;
		}
		this._targetY=-(this._tweenArr[0]*this._ballHight);
	}

	__proto.dispose=function(){
		this._type=0;
		this._curPro=0;
		this._tweenArr.length=0;
		this._ifTweening=false;
		Laya.timer.clear(this,this.onTween);
		if(this._barAni){
			this._barAni.recover();
			this._barAni.y=0;
		}
	}

	__getset(0,__proto,'value',null,function(pro){
		if(pro>1)pro=1;
		if(pro<0)pro=0;
		if(this._curPro>pro){
			this._tweenArr.push(1);
			this._tweenArr.push(0);
			this._tweenArr.push(pro);
		}
		else{
			this._tweenArr.push(pro);
		}
		this._curPro=pro;
		this.tweenTo();
	});

	__getset(0,__proto,'proText',null,function(txt){
		this.txt_pro.text=txt;
	});

	__getset(0,__proto,'type',null,function(type){
		this._type=type;
		if(!this._barAni){
			this._barAni=new UIAni();
			this._barAni.scale(1,1.4);
		}
		this.sp_mask.addChild(this._barAni);
		var url=PathDefine.getWaterByType(type);
		this._barAni.setRes(url);
	});

	return YuanShenProBall;
})(YuanShenProBallUI)


