		this.txt_stat.color=this._info.online?"#4dff55":"#cccccc";
		this.hbox_name.refresh();
		this.txt_value.text="战力:"+CommonUtil.numFormat3(this._info.fight);
		this.txt_gx.text="历史最大贡献:"+CommonUtil.numFormat3(this._info.val);
		this.img_dz.visible=Mgr.zhanduiM.checkMemberLeader(this._info.id);
