	__proto.onUpgrade=function(){
		if(!this._curInfo)return;
		var needId=this._curInfo.cost;
		var have=Mgr.bag.getBagMatCount(needId);
		if(have<=0){
			Mgr.prompt.optionPrompt("道具不足");
			return;
		};
		var nextNeed=this._curInfo.num-this._curInfo.pro;
		var xiaNeed=this._curInfo.xiayizhi;
		var haveXy=Mgr.moneyMgr.getMoneyByType(19);
		if(xiaNeed!=0){
			var xiayiCount=haveXy/xiaNeed;
			if(haveXy<xiaNeed){
				Mgr.prompt.optionPrompt("侠义值不足");
				return;
			}
			else if(xiayiCount>=nextNeed){
				var count=have>nextNeed?nextNeed:have;
			}
			else{
				count=Math.min(xiayiCount,have);
			}
		}
		else{
			count=have>nextNeed?nextNeed:have;
		}
		Mgr.zhanduiA.c_upgradeYuPei(count);
	}

	__proto.updataFight=function(){
		var fig=0;
		fig=Mgr.power.getPowerByType(155);
		if(!fig)fig=0;
		this.fightV.setFight=fig;
	}

	__proto.updateRed=function(){
		if(this.yupeiRedVo.getCornerState("jinJieRed")){
			CornerUtil.addCorner(this.btn_SJ);
			this.btn_SJ.showAni("anniu_01",-4,-2);
		}
		else{
			CornerUtil.removeCorner(this.btn_SJ);
			this.btn_SJ.dispose();
		}
	}

