		var cost;
		for (var i=0;i < 10;i++){
			var temp=this.datas[i];
			if(temp.level > 0){
				cost=temp["cost"]
				if(temp["state"]==2){
					b=true
					Mgr.zhanZhuangAct.reqUpgrade(this.suitID,temp.part);
				}
			}
		}
		if(!b){
			this.onClickMaterialName(cost);
		}
