			var mgr=Mgr.zhongQiuMgr;
			var roleVo=NetMgr.ins().roleVO;
			this.itemVo=value;
			this.lblGoods.text=this.itemVo.name;
			this.curPriceBox.y=201;
			this.txt_yjiaybao.text=this.itemVo.purchase+"";
			this.txt_xjiaybao.text=this.itemVo.value+"";
			this.moneyIcon.skin=PathDefine.getMoneyIcon(value.moneytype);
			this.moneyIcon2.skin=this.moneyIcon.skin;
