var ExpGetPath=(function(_super){
	function ExpGetPath(){
		this.propCell=null;
		this.itemVo=null;
		this.maxNum=0;
		this.useNum=0;
		this.bagNum=0;
		ExpGetPath.__super.call(this);
	}

	__class(ExpGetPath,'view.modules.singleCopy.ExpGetPath',_super);
	var __proto=ExpGetPath.prototype;
	__proto.initialize=function(){
		laya.ui.Dialog.prototype.initialize.call(this);
		this.btnQd.on("click",this,this.onQueDing);
		this.btn_add.on("click",this,this.onAdd);
		this.btn_reduce.on("click",this,this.onReduce);
		this.pathList.renderHandler=Handler.create(this,this.listRender,null,false);
	}

	__proto.onAdd=function(){
		if(this.useNum < this.bagNum){
			this.useNum++;
			this.txt_useNum.text=this.useNum+"";
		}
	}

	__proto.onReduce=function(){
		if(this.useNum > 1){
			this.useNum--;
			this.txt_useNum.text=this.useNum+"";
		}
	}

	__proto.onOpened=function(){
		laya.ui.Dialog.prototype.onOpened.call(this);
		this.bgV.setTxtName("提示");
		var pathStr=this.itemVo.cfgItem.getpath;
		var pathArr=pathStr.split(";");
		this.pathList.array=pathArr;
		var len=pathArr.length;
		if(len <=1){
			var tw=86 *pathArr.length;
		}
		else{
			tw=126 *(len-1)+86;
		}
		if(tw >=412)
			this.pathList.x=29
		else
		this.pathList.x=(this.width-tw)/2;
		if(!this.propCell){
			this.propCell=new BagItemFactoryView();
			this.propCell.pos((this.width-this.propCell.width)/2,104);
			this.addChild(this.propCell);
		}
		this.propCell.dataSource=this.itemVo;
		EventCenter.instance.onQue("ITEM_CHANGE" ,this ,this.showNum);
		this.showNum();
	}

	__proto.onClosed=function(type){
		laya.ui.Dialog.prototype.onClosed.call(this);
		EventCenter.instance.offQue("ITEM_CHANGE" ,this ,this.showNum);
	}

	__proto.showNum=function(){
		this.bagNum=Mgr.bag.getBagMatCount(this.itemVo.cfgItem.id);
		this.numTxt.text=this.bagNum+"";
		this.useNum=1;
		this.txt_useNum.text=this.useNum+"";
		if(this.bagNum > 0){
			this.numTxt.color="#4dff55";
			this.btnQd.disabled=false;
		}
		else{
			this.btnQd.disabled=true;
			this.numTxt.color="#ff4141";
		}
	}

	__proto.listRender=function(cell,index){
		if(cell.dataSource){
			var pathId=parseInt(cell.dataSource);
			var msgObj=UIMgr.ins.getNavigateItem(cell.dataSource);
			if(msgObj){
				var btn_go=cell.getChildByName("imIcon");
				if(msgObj.func){
					btn_go.skin=PathDefine.activeIcon(msgObj.pathicon);
				}
				cell.on("click",this,this.clickGo,[pathId]);
			}
		}
	}

	__proto.clickGo=function(pathId){
		UIMgr.ins.navigateToViewByID(pathId,null,2);
		this.close();
	}

	/**确定*/
	__proto.onQueDing=function(){
		Mgr.jingyanPro.sendAddChallengeCount(this.useNum,false);
	}

	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		if(!value){
			return
		}
		this.itemVo=value.dataVo;
		this.maxNum=value.maxNum;
	});

	return ExpGetPath;
})(ExpGetPathUI)


