	__proto.initialize=function(){
		laya.ui.Dialog.prototype.initialize.call(this);
		this.bgView.setOffPos(182,10);
		this.bgView.setTxtName("经验丹使用");
		this.djIcon=[this.dj_0,this.dj_1,this.dj_2,this.dj_3,this.dj_4,this.dj_5];
		this.djId=[];
		for (var i=0;i < 6;i++){
			this.djId.push("dj10"+(i+37));
			this.djIcon[i].on("click",this,this.onEvenDJ,[this.djIcon[i]]);
		}
	}

	__proto.onEvenDJ=function(obj){
		if(!obj.gray){
			Mgr.bag.useItem(obj._dataSource.guid,1);
		}
	}

