var JingYanTip1View=(function(_super){
	function JingYanTip1View(){
		this.cell=null;
		this.callback=null;
		// private var tequanCfg:TableConfig;
		this._vo=null;
		/**是否足够标志位*/
		this._ifEnough=false;
		JingYanTip1View.__super.call(this);
	}

	__class(JingYanTip1View,'view.modules.singleCopy.jingyanCopy.JingYanTip1View',_super);
	var __proto=JingYanTip1View.prototype;
	__proto.initialize=function(){
		this.btnCancel.on("click",this,this.close);
		this.btnOk.on("click",this,this.onClickOK);
	}

	// tequanCfg=CfgManager.getTableCfg("vipbiao");
	__proto.onOpened=function(){
		EventCenter.instance.onQue("ITEM_CHANGE" ,this ,this.updateCount);
		EventCenter.instance.on("CURRENCY_CHANGE",this,this.updateCount);
		this.bgV.setTxtName("提示")
	}

	__proto.onClickOK=function(){
		if(this._ifEnough){
			if(this.callback){
				this.callback.run();
			}
		}
		else{
			Mgr.prompt.optionPrompt(this._vo.name+"数量不足");
		}
	}

	/**刷新次数*/
	__proto.updateCount=function(){
		var moneyType=Mgr.moneyMgr.getMoneyTypeById(this._vo.templateID);
		if(moneyType){
			var maxNum=Mgr.moneyMgr.getMoneyByType(moneyType);
		}
		else{
			maxNum=Mgr.bag.getBagMatCount(this._vo.templateID);
		}
		this.lbl_num.text=maxNum+"/"+this._vo.curNum;
		if(maxNum >=this._vo.curNum)
			this.lbl_num.color="#24971e";
		else
		this.lbl_num.color="#cb1a1a";
		this._ifEnough=maxNum >=this._vo.curNum;
	}

	__proto.onClose=function(){
		this.close();
	}

	__proto.onClosed=function(type){
		EventCenter.instance.offQue("ITEM_CHANGE" ,this ,this.updateCount);
		EventCenter.instance.off("CURRENCY_CHANGE",this,this.updateCount);
		this.callback=null;
		this._vo=null;
	}

	/**obj
	*.txtContent==文本内容
	*.curNum 数量
	*。templateID ID
	*.callback 回调函数
	*/
	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		if(!value)return;
		this._vo=value;
		this._dataSource=value;
		this.lbl_dec.text=value.txtContent;
		this.callback=value.callback;
		if(!this.cell){
			this.cell=new BagItemFactoryView();
			this.cell.scale(0.9,0.9);
			this.spr_pro.addChild(this.cell);
		};
		var objVO=Mgr.item.getItemVO(value.templateID);
		objVO.whichPanel=10;
		this.cell.dataSource=objVO;
		this.updateCount();
	});

	return JingYanTip1View;
})(JingYanTip1UI)


