			cvo.chatType=1;
			cvo.message="可以开始跟我聊天啦~";
			this.toGuid=vo.guid;
			this.toName=vo.name;
			var infoRender=this.chatMgr.renderCacheArr.length>0?this.chatMgr.renderCacheArr.pop():new NewChatItem();
